        Assert.DoesNotContain("apps/local-node-host/Health/AuthorizationAdminRoutes.cs", discovered);
        Assert.DoesNotContain("apps/local-node-host/Health/Catalogue.cs", discovered);
        Assert.DoesNotContain("apps/local-node-host/Health/HostedAuthorizationAdminApiEndpoint.cs", discovered);
        Assert.DoesNotContain("apps/local-node-host/Program.cs", discovered);
    }

    private static string[] ProductionConsumers()
    {
        var root = RepositoryRoot();
        return new[] { "apps", "packages" }
            .SelectMany(area => Directory.EnumerateFiles(Path.Combine(root, area), "*.cs", SearchOption.AllDirectories))
            .Select(path => (path, relative: Path.GetRelativePath(root, path).Replace('\\', '/')))
            .Where(file => !file.relative.Contains("/tests/", StringComparison.Ordinal)
                && !file.relative.Contains("/obj/", StringComparison.Ordinal)
                && !file.relative.Contains("/bin/", StringComparison.Ordinal)
                && !file.relative.StartsWith("packages/foundation-rule-engine/", StringComparison.Ordinal))
            .Where(file => File.ReadLines(file.path).Any(line =>
                !line.TrimStart().StartsWith("//", StringComparison.Ordinal) && line.Contains(Copy, StringComparison.Ordinal)))
            .Select(file => file.relative)
            .Order(StringComparer.Ordinal)
            .ToArray();
    }

    private static string RepositoryRoot([CallerFilePath] string thisFile = "")
    {
        var hostRoot = Path.GetDirectoryName(Path.GetDirectoryName(Path.GetDirectoryName(thisFile)!)!)!;
        var repositoryRoot = Path.GetDirectoryName(Path.GetDirectoryName(hostRoot)!)!;
        Assert.True(Directory.Exists(Path.Combine(repositoryRoot, "packages")), $"repository root not found from {thisFile}");
        return repositoryRoot;
    }
}

using System.Xml.Linq;

namespace Harborline.Api.LocalNodeHost.Tests.ArchTests;

/// <summary>
/// Enforces the Harborline API's project-reference tier boundaries directly from the
/// repository's <c>*.csproj</c> graph.
/// </summary>
/// <remarks>
/// <para>
/// The package tiers form an inward dependency model: kernel must not depend on
/// foundation or blocks, and foundation must not depend on blocks. The contracts
/// lane is purer still and may reference only projects beneath
/// <c>packages/contracts/</c>.
/// </para>
/// <para>
/// Package projects must never reach outward into applications. These assertions
/// inspect declared <c>ProjectReference</c> edges rather than loaded assemblies, so
/// unloaded packages and test projects remain inside the architecture fence.
/// </para>
/// </remarks>
public sealed class ApiTierDependencyArchTests
{
    // Harborline.Api.Kernel self-describes in its csproj as a "Kernel contract facade ...
    // type-forwarded wrappers over Harborline.Api.Foundation primitives". During the
    // migration era the entire kernel tier therefore deliberately sits on Foundation.
    // Each edge is pinned until the facade inversion lands, at which point
    // this list must shrink to empty. One edge per line keeps debt-removal diffs visible.
    private static readonly HashSet<(string Source, string Target)> KernelFoundationFacadeExemptions =
    [
        ("packages/kernel-audit/Harborline.Kernel.Audit.csproj", "packages/foundation/Harborline.Foundation.csproj"),
        // Ticket 199: authorized audit copies the carried gate decision; the reverse edge was verified absent.
        ("packages/kernel-audit/Harborline.Kernel.Audit.csproj", "packages/foundation-authorization/Harborline.Foundation.Authorization.csproj"),
        // Ticket 199: AuditRecord carries typed Actor/Target/Act identity primitives from the admitted decision.
        ("packages/kernel-audit/Harborline.Kernel.Audit.csproj", "packages/foundation-identity-atlas/Harborline.Foundation.IdentityAtlas.csproj"),
        ("packages/kernel-buckets/Harborline.Kernel.Buckets.csproj", "packages/foundation/Harborline.Foundation.csproj"),
        ("packages/kernel-crdt/Harborline.Kernel.Crdt.csproj", "packages/foundation/Harborline.Foundation.csproj"),
        ("packages/kernel-event-bus/Harborline.Kernel.EventBus.csproj", "packages/foundation/Harborline.Foundation.csproj"),
        ("packages/kernel-lease/Harborline.Kernel.Lease.csproj", "packages/foundation/Harborline.Foundation.csproj"),
        ("packages/kernel-ledger/Harborline.Kernel.Ledger.csproj", "packages/foundation/Harborline.Foundation.csproj"),
        ("packages/kernel-runtime/Harborline.Kernel.Runtime.csproj", "packages/foundation/Harborline.Foundation.csproj"),
        ("packages/kernel-runtime/Harborline.Kernel.Runtime.csproj", "packages/foundation-localfirst/Harborline.Foundation.LocalFirst.csproj"),
        ("packages/kernel-schema-registry/Harborline.Kernel.SchemaRegistry.csproj", "packages/foundation/Harborline.Foundation.csproj"),
        ("packages/kernel-security/Harborline.Kernel.Security.csproj", "packages/foundation/Harborline.Foundation.csproj"),
        ("packages/kernel-security/Harborline.Kernel.Security.csproj", "packages/foundation-localfirst/Harborline.Foundation.LocalFirst.csproj"),
        ("packages/kernel-signatures/Harborline.Kernel.Signatures.csproj", "packages/foundation/Harborline.Foundation.csproj"),
        // Ticket 199: constructing AuditRecord requires its carried-authority public signature at compile time.
        ("packages/kernel-signatures/Harborline.Kernel.Signatures.csproj", "packages/foundation-authorization/Harborline.Foundation.Authorization.csproj"),
        // Ticket 199: constructing AuditRecord requires its typed Actor/Target/Act public signature at compile time.
        ("packages/kernel-signatures/Harborline.Kernel.Signatures.csproj", "packages/foundation-identity-atlas/Harborline.Foundation.IdentityAtlas.csproj"),
        ("packages/kernel-signatures/Harborline.Kernel.Signatures.csproj", "packages/foundation-taxonomy/Harborline.Foundation.Taxonomy.csproj"),
        ("packages/kernel-sync/Harborline.Kernel.Sync.csproj", "packages/foundation/Harborline.Foundation.csproj"),
        ("packages/kernel/Harborline.Kernel.csproj", "packages/foundation/Harborline.Foundation.csproj"),
    ];

    /// <summary>Ticket 257: the exemption rows, for the shared vacuous-row property.</summary>
    internal static string[] KernelFoundationFacadeExemptionRows() =>
        KernelFoundationFacadeExemptions.Select(row => $"{row.Source} -> {row.Target}").ToArray();

    /// <summary>Ticket 257: the restricted kernel edges the csproj-graph discovery actually finds.</summary>
    internal static string[] DiscoveredRestrictedKernelEdges() =>
        ReadProjectReferenceGraph()
            .Where(edge => edge.SourceTier == "kernel" &&
                           (edge.TargetTier == "foundation" || edge.TargetTier == "blocks"))
            .Select(edge => $"{edge.Source} -> {edge.Target}")
            .Distinct(StringComparer.Ordinal)
            .Order(StringComparer.Ordinal)
            .ToArray();

    /// <summary>
    /// R1 prevents kernel projects from acquiring new foundation or blocks dependencies
    /// and makes every retired migration-era facade exemption fail visibly.
    /// </summary>
    [Fact(DisplayName = "R1: kernel references no foundation or blocks projects")]
    public void R1_KernelReferencesNoFoundationOrBlocksProjects()
    {
        var edges = ReadProjectReferenceGraph();
        var actualRestrictedEdges = edges
            .Where(edge => edge.SourceTier == "kernel" &&
                           (edge.TargetTier == "foundation" || edge.TargetTier == "blocks"))
            .ToArray();

        var staleExemptions = KernelFoundationFacadeExemptions
            .Where(exemption => !actualRestrictedEdges.Any(edge =>
                edge.Source == exemption.Source && edge.Target == exemption.Target))
            .OrderBy(exemption => exemption.Source, StringComparer.Ordinal)
            .ThenBy(exemption => exemption.Target, StringComparer.Ordinal)
            .ToArray();

        if (staleExemptions.Length > 0)
        {
            throw new InvalidOperationException(
                $"R1 stale exemption detected ({staleExemptions.Length} entries); remove debt entries that no longer exist:\n" +
                string.Join("\n", staleExemptions.Select(exemption =>
                    $"{exemption.Source} -> {exemption.Target} (kernel -> foundation)")));
        }

        AssertNoViolations(
            "R1: kernel references no foundation or blocks projects",
            actualRestrictedEdges.Where(edge =>
                !KernelFoundationFacadeExemptions.Contains((edge.Source, edge.Target))));
    }

    /// <summary>
    /// R2 prevents foundation projects from reaching outward into the blocks tier.
    /// </summary>
    [Fact(DisplayName = "R2: foundation references no blocks projects")]
    public void R2_FoundationReferencesNoBlocksProjects()
    {
        AssertNoViolations(
            "R2: foundation references no blocks projects",
            ReadProjectReferenceGraph().Where(edge =>
                edge.SourceTier == "foundation" && edge.TargetTier == "blocks"));
    }

    /// <summary>
    /// R3 prevents every project beneath <c>packages/</c> from depending on an
    /// application project beneath <c>apps/</c>.
    /// </summary>
    [Fact(DisplayName = "R3: packages reference no apps projects")]
    public void R3_PackagesReferenceNoAppsProjects()
    {
        AssertNoViolations(
            "R3: packages reference no apps projects",
            ReadProjectReferenceGraph().Where(edge =>
                edge.Source.StartsWith("packages/", StringComparison.Ordinal) && edge.TargetTier == "apps"));
    }

    /// <summary>
    /// R4 keeps the contracts lane pure by allowing its projects to reference only
    /// other projects beneath <c>packages/contracts/</c>.
    /// </summary>
    [Fact(DisplayName = "R4: contracts reference only contracts projects")]
    public void R4_ContractsReferenceOnlyContractsProjects()
    {
        AssertNoViolations(
            "R4: contracts reference only contracts projects",
            ReadProjectReferenceGraph().Where(edge =>
                edge.SourceTier == "contracts" && edge.TargetTier != "contracts"));
    }

    /// <summary>
    /// Reads all package and application project files, excluding generated and
    /// vendored directory segments, and resolves every declared project reference to
    /// a repository-relative edge.
    /// </summary>
    private static IReadOnlyList<ProjectReferenceEdge> ReadProjectReferenceGraph()
    {
        var repositoryRoot = LocateRepositoryRoot();
        var scanRoots = new[]
        {
            Path.Combine(repositoryRoot, "packages"),
            Path.Combine(repositoryRoot, "apps"),
        };

        return scanRoots
            .SelectMany(root => Directory.EnumerateFiles(root, "*.csproj", SearchOption.AllDirectories))
            .Where(path => !HasExcludedDirectorySegment(repositoryRoot, path))
            .SelectMany(projectPath =>
            {
                var source = ToRepositoryRelativePath(repositoryRoot, projectPath);
                return XDocument.Load(projectPath)
                    .Descendants("ProjectReference")
                    .Select(reference => ((string?)reference.Attribute("Include"))?.Replace('\\', '/'))
                    .Where(include => !string.IsNullOrWhiteSpace(include))
                    .Select(include => Path.GetFullPath(include!, Path.GetDirectoryName(projectPath)!))
                    .Select(targetPath => new ProjectReferenceEdge(
                        source,
                        ToRepositoryRelativePath(repositoryRoot, targetPath),
                        ClassifyTier(source),
                        ClassifyTier(ToRepositoryRelativePath(repositoryRoot, targetPath))));
            })
            .OrderBy(edge => edge.Source, StringComparer.Ordinal)
            .ThenBy(edge => edge.Target, StringComparer.Ordinal)
            .ToArray();
    }

    /// <summary>
    /// Reports whether a project path passes through a <c>bin</c>, <c>obj</c>, or
    /// <c>node_modules</c> directory segment.
    /// </summary>
    private static bool HasExcludedDirectorySegment(string repositoryRoot, string path)
    {
        var segments = Path.GetRelativePath(repositoryRoot, path)
            .Replace('\\', '/')
            .Split('/', StringSplitOptions.RemoveEmptyEntries);
        return segments.Any(segment =>
            segment is "bin" or "obj" or "node_modules");
    }

    /// <summary>
    /// Converts an absolute path into the normalized, forward-slash repository path
    /// used for classification, exemptions, and failure diagnostics.
    /// </summary>
    private static string ToRepositoryRelativePath(string repositoryRoot, string path) =>
        Path.GetRelativePath(repositoryRoot, Path.GetFullPath(path)).Replace('\\', '/');

    /// <summary>
    /// Classifies a normalized repository-relative project path according to the
    /// manifest's apps, contracts, kernel, foundation, blocks, and other tiers.
    /// </summary>
    private static string ClassifyTier(string path)
    {
        if (path.StartsWith("apps/", StringComparison.Ordinal)) return "apps";
        if (path.StartsWith("packages/contracts/", StringComparison.Ordinal)) return "contracts";

        var segments = path.Split('/', StringSplitOptions.RemoveEmptyEntries);
        if (segments.Length < 2 || segments[0] != "packages") return "other";

        var package = segments[1];
        if (package == "kernel" || package.StartsWith("kernel-", StringComparison.Ordinal)) return "kernel";
        if (package == "foundation" || package.StartsWith("foundation-", StringComparison.Ordinal)) return "foundation";
        if (package.StartsWith("blocks-", StringComparison.Ordinal)) return "blocks";
        return "other";
    }

    /// <summary>
    /// Throws one detailed architecture failure containing every violating source and
    /// target edge, including both classified tiers.
    /// </summary>
    private static void AssertNoViolations(string ruleName, IEnumerable<ProjectReferenceEdge> candidates)
    {
        var violations = candidates
            .OrderBy(edge => edge.Source, StringComparer.Ordinal)
            .ThenBy(edge => edge.Target, StringComparer.Ordinal)
            .Select(FormatEdge)
            .ToArray();

        if (violations.Length > 0)
        {
            throw new InvalidOperationException(
                $"{ruleName} failed ({violations.Length} violating edges):\n" +
                string.Join("\n", violations));
        }
    }

    /// <summary>
    /// Formats an edge with the stable path and tier detail required for actionable
    /// architecture-test failures.
    /// </summary>
    private static string FormatEdge(ProjectReferenceEdge edge) =>
        $"{edge.Source} -> {edge.Target} ({edge.SourceTier} -> {edge.TargetTier})";

    /// <summary>
    /// Locates the repository root by walking upward from the test output until both
    /// the <c>packages</c> and <c>apps</c> directories are present.
    /// </summary>
    private static string LocateRepositoryRoot()
    {
        var directory = new DirectoryInfo(AppContext.BaseDirectory);
        while (directory is not null)
        {
            if (Directory.Exists(Path.Combine(directory.FullName, "packages")) &&
                Directory.Exists(Path.Combine(directory.FullName, "apps")))
            {
                return directory.FullName;
            }

            directory = directory.Parent;
        }

        throw new InvalidOperationException(
            "Could not locate the repository root containing both packages and apps from the test output.");
    }

    /// <summary>
    /// Represents one normalized <c>ProjectReference</c> edge and the tier assigned to
    /// each endpoint.
    /// </summary>
    private sealed record ProjectReferenceEdge(
        string Source,
        string Target,
        string SourceTier,
        string TargetTier);
}

using System.Reflection;

using Harborline.Api.Foundation.Authorization.SeparationOfDuty;
using Harborline.Api.LocalNodeHost.Tests.Audit;

namespace Harborline.Api.LocalNodeHost.Tests.ArchTests;

/// <summary>
/// Ticket 272 slice 1 — the approval facts belong to the separation-of-duty engine, and to nothing else.
/// <para>
/// ADR 0067 clause 2 puts one decider behind the approval facts an audit entry records. The failure mode it
/// exists to prevent is a writer computing a fact for itself — reading an ambient threshold, inventing a
/// policy version, deciding a separation-of-duty outcome inline — because a fact derived at the writer is a
/// second decision, and the audit entry then misstates the authority the act was made under.
/// </para>
/// <para>
/// The inventory is discovered by SYMBOL: an IL walk over every shipped <c>Harborline*.dll</c> for
/// <c>newobj</c> of an approval-fact type, anchored to file:line through the portable PDB. Aliases, helper
/// locals and target-typed <c>new</c> do not hide a construction site from it. Every discovered site must be
/// the engine, the decision it returns, or an explicitly allowed row below.
/// </para>
/// </summary>
public sealed class ApprovalFactConstructionFenceTests
{
    /// <summary>The approval-fact types no writer may construct. Both spellings: the engine's and audit's.</summary>
    private static readonly string[] FactTypes =
    [
        "Harborline.Api.Foundation.Authorization.SeparationOfDuty.ApprovalPolicyFact",
        "Harborline.Api.Foundation.Authorization.SeparationOfDuty.ApprovalLimitSourceFact",
        "Harborline.Api.Foundation.Authorization.SeparationOfDuty.SeparationOfDutyFact",
        "Harborline.Api.Foundation.Authorization.SeparationOfDuty.SeparationOfDutyDecision",
        "Harborline.Api.Kernel.Audit.AuthorityPolicySnapshot",
        "Harborline.Api.Kernel.Audit.AuthorityLimitSourceSnapshot",
        "Harborline.Api.Kernel.Audit.SeparationOfDutySnapshot",
    ];

    private const string EngineSymbol =
        "packages/foundation-authorization/SeparationOfDuty/SeparationOfDutyEngine.cs"
        + "|Harborline.Api.Foundation.Authorization.SeparationOfDuty.SeparationOfDutyEngine.Decide"
        + "(Harborline.Api.Foundation.Authorization.SeparationOfDuty.SeparationOfDutyRequest)"
        + ": Harborline.Api.Foundation.Authorization.SeparationOfDuty.SeparationOfDutyDecision|";

    private const string SnapshotCopySymbol =
        "packages/kernel-audit/AuthoritySnapshot.cs"
        + "|Harborline.Api.Kernel.Audit.AuthoritySnapshot.Copy(): Harborline.Api.Kernel.Audit.AuthoritySnapshot|";

    private const string SeamSymbol =
        "packages/kernel-audit/AuthorityCapturingAuditTrail.cs"
        + "|Harborline.Api.Kernel.Audit.AuthorizedAuditRecord.CopyCore("
        + "Harborline.Api.Kernel.Audit.AuditRecord,"
        + "Harborline.Api.Foundation.Authorization.AuthorizationDecision,"
        + "Harborline.Api.Foundation.Authorization.SeparationOfDuty.SeparationOfDutyDecision,System.Boolean"
        + "): Harborline.Api.Kernel.Audit.AuditRecord|";

    private const string InvoiceThresholdSymbol =
        "apps/local-node-host/Data/Workflow/NodeWorkflowDefinitions.cs"
        + "|Harborline.Api.LocalNodeHost.Data.Workflow.NodeWorkflowDefinitions..cctor(): System.Void|";

    /// <summary>
    /// The exact set of non-engine sites that construct an approval fact today. Each row is
    /// <c>file|symbol|constructed type</c> as the scan reports it, with the reason it is not an offender.
    /// A row here that the scan no longer finds fails <see cref="AllowListVacuityArchTests"/>.
    /// </summary>
    private static readonly Dictionary<string, string> Allowed = new(StringComparer.Ordinal)
    {
        [EngineSymbol + "Harborline.Api.Foundation.Authorization.SeparationOfDuty.SeparationOfDutyFact"] =
            "the engine itself — the one place the separation-of-duty fact is decided",
        [EngineSymbol + "Harborline.Api.Foundation.Authorization.SeparationOfDuty.SeparationOfDutyDecision"] =
            "the engine returning its own decision object",
        [SnapshotCopySymbol + "Harborline.Api.Kernel.Audit.AuthorityPolicySnapshot"] =
            "AuthoritySnapshot.Copy severs the persisted snapshot from the decision's own instances; it "
            + "copies the policy fact field-for-field and derives nothing (ADR 0068 clause 1)",
        [SnapshotCopySymbol + "Harborline.Api.Kernel.Audit.AuthorityLimitSourceSnapshot"] =
            "AuthoritySnapshot.Copy, field-for-field copy of the limit source; derives nothing",
        [SnapshotCopySymbol + "Harborline.Api.Kernel.Audit.SeparationOfDutySnapshot"] =
            "AuthoritySnapshot.Copy, field-for-field copy of the SoD verdict; derives nothing",
        [SeamSymbol + "Harborline.Api.Kernel.Audit.AuthorityPolicySnapshot"] =
            "ticket 272 slice 2: the one seam that maps a separation-of-duty decision onto the stored "
            + "snapshot; every field is read off the decision, nothing is derived",
        [SeamSymbol + "Harborline.Api.Kernel.Audit.AuthorityLimitSourceSnapshot"] =
            "the same seam, limit source; the kind is a default-arm-free switch over the decided kind",
        [InvoiceThresholdSymbol
            + "Harborline.Api.Foundation.Authorization.SeparationOfDuty.ApprovalPolicyFact"] =
            "ticket 272 slice 3: the ONE place the invoice-approval family's ApprovalThreshold is built, "
            + "from the single V1ApprovalThreshold constant. A threshold is an INPUT to the engine, not a "
            + "decided fact — the writers read this object and never a threshold at a point of use",
        [InvoiceThresholdSymbol
            + "Harborline.Api.Foundation.Authorization.SeparationOfDuty.ApprovalLimitSourceFact"] =
            "the same threshold, naming the pinned decision table it comes from; nothing is derived per act",
        [SeamSymbol + "Harborline.Api.Kernel.Audit.SeparationOfDutySnapshot"] =
            "the same seam, SoD verdict and refusal reason; both are default-arm-free switches over the "
            + "decided members, so a refusal cannot be stored as a pass",
    };

    /// <summary>Allow-list rows, for the vacuity registry.</summary>
    internal static string[] AllowedRows() => [.. Allowed.Keys.Order(StringComparer.Ordinal)];

    /// <summary>The scan with the allow-list bypassed, for the vacuity registry.</summary>
    internal static string[] DiscoveredApprovalFactConstructionSites() => Discover();

    // Cached: the IL walk reads every shipped assembly, and the vacuity registry re-runs each registered
    // discovery thirteen times across four threads. The build output does not change mid-run.
    private static readonly Lazy<string[]> Sites = new(
        () => AuditAppendSymbolInventory
            .Discover(Classify)
            .Select(site => $"{site.File}|{site.Symbol}|{site.Kind}")
            .Distinct(StringComparer.Ordinal)
            .Order(StringComparer.Ordinal)
            .ToArray(),
        LazyThreadSafetyMode.ExecutionAndPublication);

    private static string[] Discover() => Sites.Value;

    /// <summary>
    /// A construction of an approval fact, by either route the language offers. <c>newobj</c> is the plain
    /// <c>new</c>; <c>&lt;Clone&gt;$</c> is what a <c>with</c> expression emits at the writer, because the
    /// record's copy constructor lives in the record's own compiler-generated clone and not in the caller.
    /// Without the second arm a writer holding a decision fabricates a fact in one token —
    /// <c>decision.SeparationOfDuty with { Outcome = Pass }</c> — and the fence sees nothing.
    /// </summary>
    internal static string? Classify(MethodBase method)
    {
        if (method is not ConstructorInfo && method.Name is not "<Clone>$") return null;
        var declaring = method.DeclaringType?.FullName;
        return declaring is not null && FactTypes.Contains(declaring, StringComparer.Ordinal)
            ? declaring
            : null;
    }

    [Fact(DisplayName = "The fence sees a fact fabricated with a `with` expression, not only with `new`")]
    public void A_with_expression_clone_is_classified_as_a_construction()
    {
        // The reviewer's plant, at the classifier: a `with` on a fact record emits `callvirt <Clone>$`
        // at the writer, and the IL walk already yields call/callvirt. If Classify ignores it, a
        // one-token fabrication is invisible to every assertion above.
        var clone = typeof(SeparationOfDutyFact).GetMethod(
            "<Clone>$", BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance);

        Assert.NotNull(clone);
        Assert.Equal(
            "Harborline.Api.Foundation.Authorization.SeparationOfDuty.SeparationOfDutyFact", Classify(clone));
    }

    [Fact]
    public void No_writer_constructs_an_approval_fact_outside_the_engine()
    {
        var offenders = Discover().Where(site => !Allowed.ContainsKey(site)).ToArray();

        Assert.True(
            offenders.Length == 0,
            "An approval fact was constructed outside the ADR 0067 clause 2 separation-of-duty engine. "
            + "A writer must carry the engine's decision, not derive a fact from an ambient threshold. "
            + "Offending sites:\n  " + string.Join("\n  ", offenders));
    }

    [Fact]
    public void The_scan_finds_the_engine_itself()
    {
        // Guards the fence against silent vacuity: if the IL walk stopped resolving constructor tokens, or
        // stopped seeing newobj, every assertion above would pass over an empty set.
        var discovered = Discover();

        Assert.Contains(
            discovered,
            site => site.Contains("SeparationOfDutyEngine.Decide", StringComparison.Ordinal)
                && site.EndsWith("SeparationOfDutyFact", StringComparison.Ordinal));
    }

    [Fact]
    public void A_planted_offender_is_rejected()
    {
        // The mutation the fence exists for, run in-test: a writer-shaped construction site that is not on
        // the allow-list must be reported. Planted rather than committed, so the mutation runs every build.
        const string planted =
            "apps/local-node-host/Health/InvoiceRoutes.cs|Harborline.Api.LocalNodeHost.Health.InvoiceRoutes"
            + ".Map(): System.Void|Harborline.Api.Foundation.Authorization.SeparationOfDuty.ApprovalPolicyFact";

        var offenders = Discover().Append(planted).Where(site => !Allowed.ContainsKey(site)).ToArray();

        Assert.Equal([planted], offenders);
    }
}

using Harborline.Api.Blocks.Assets.Registry.Services;
using Harborline.Api.LocalNodeHost.Health;

namespace Harborline.Api.LocalNodeHost.Tests.ArchTests;

/// <summary>
/// Ticket 358 slice 1 — the gated asset-registry entity READS, discovered by symbol. The inventory is the
/// set of route handlers in <see cref="AssetRegistryRoutes"/> that resolve a
/// <see cref="RequestAuthorization.RefusalAsync"/> decision before reading
/// <see cref="IRegistryEntityRepository"/>: the entity list and the entity detail. Removing either
/// decision drops that handler out of the discovered set, and reading the repository before deciding puts
/// the read ahead of the guard — both turn this fence red.
/// </summary>
public sealed class AssetRegistryAuthorizedReadFenceTests
{
    [Fact]
    public void Entity_read_route_inventory_is_exact_and_every_read_reaches_the_gate_first()
    {
        // Class: authorized read. Reason: ADR 0060 — the typed-entity rows are projected only after the
        // records:read decision the route resolves for the record it addresses.
        var reads = RawMutationPortSymbolInventoryTests.DiscoverCalls(
            [typeof(AssetRegistryRoutes).Assembly],
            target => target.DeclaringType == typeof(IRegistryEntityRepository)
                && target.Name is nameof(IRegistryEntityRepository.GetByIdAsync)
                    or nameof(IRegistryEntityRepository.ListByTenantAsync)
                    or nameof(IRegistryEntityRepository.ListByTypeAsync),
            type => IsNestedWithin(type, typeof(AssetRegistryRoutes)));
        var guards = RawMutationPortSymbolInventoryTests.DiscoverCalls(
            [typeof(AssetRegistryRoutes).Assembly],
            target => target.DeclaringType == typeof(RequestAuthorization)
                && target.Name == nameof(RequestAuthorization.RefusalAsync),
            type => IsNestedWithin(type, typeof(AssetRegistryRoutes)));

        Assert.NotEmpty(reads);
        Assert.All(guards, guard => Assert.Equal("apps/local-node-host/Health/AssetRegistryRoutes.cs", guard.Path));

        // The gated handlers: exactly the two entity read routes, named by what each one reads.
        var gated = reads
            .Where(read => guards.Any(guard => guard.Symbol == read.Symbol))
            .GroupBy(read => read.Symbol, StringComparer.Ordinal)
            .Select(handler => handler
                .Select(read => TargetName(read.Target)).Distinct(StringComparer.Ordinal)
                .Order(StringComparer.Ordinal).ToArray())
            .OrderBy(names => string.Join(",", names), StringComparer.Ordinal)
            .ToArray();
        Assert.Equal(2, gated.Length);
        Assert.Equal([nameof(IRegistryEntityRepository.GetByIdAsync)], gated[0]);
        Assert.Equal(
            [
                nameof(IRegistryEntityRepository.ListByTenantAsync),
                nameof(IRegistryEntityRepository.ListByTypeAsync),
            ],
            gated[1]);

        // In every gated handler the decision is resolved BEFORE the repository is touched.
        foreach (var read in reads.Where(read => guards.Any(guard => guard.Symbol == read.Symbol)))
        {
            var first = guards.Where(guard => guard.Symbol == read.Symbol).Min(guard => guard.Line);
            Assert.True(first < read.Line, $"{read.Symbol}: read at line {read.Line} precedes its guard at {first}.");
        }
    }

    private static string TargetName(string target) =>
        target.Split('(', 2)[0].Split('.')[^1];

    private static bool IsNestedWithin(Type candidate, Type owner)
    {
        for (var type = candidate; type is not null; type = type.DeclaringType)
            if (type == owner) return true;
        return false;
    }
}

