/// <summary>
/// Council condition C2 (ADR 0114): every shared EF entity module must compile and
/// produce a correct, non-diverged model on BOTH the Npgsql (Bridge) and the SQLite
/// (local-node-host) providers.
/// </summary>
/// <remarks>
/// <para>
/// The test builds the EF model twice — once against a Npgsql provider and once
/// against a SQLite provider — using the same set of <see cref="IHarborlineEntityModule"/>
/// instances. It then asserts:
/// <list type="number">
///   <item>Both models contain the same set of entity types (no type lost in the
///     post-config sweep).</item>
///   <item>Both models contain the same set of column names per entity type (no
///     column renamed or dropped in the sweep).</item>
///   <item>jsonb columns in the Npgsql model are rewritten to TEXT on SQLite;
///     bytea columns are rewritten to BLOB on SQLite.</item>
///   <item>No remaining PG-quoted filter predicates (double-quoted identifiers)
///     survive on the SQLite model.</item>
/// </list>
/// </para>
/// <para>
/// This test does NOT run migrations or touch a real database. It is a pure
/// model-compilation and metadata-inspection test.
/// </para>
/// </remarks>
public sealed class BothProviderModelDriftTests
{
    // ── Shared module set ──────────────────────────────────────────────────

    private static IReadOnlyList<IHarborlineEntityModule> AllModules() =>
    [
        new FinancialLedgerEntityModule(),
        new Harborline.Api.Blocks.FinancialPeriods.Data.FinancialPeriodsEntityModule(),
        new ArEntityModule(),
        new ApEntityModule(),
        new PaymentsEntityModule(),
        new BankingEntityModule(),
        new PeopleEntityModule(),
        new DocsEntityModule(),
    ];

    // ── Model builders ─────────────────────────────────────────────────────

    /// <summary>
    /// Builds the EF model using the SQLite provider (the local-node-host path).
    /// </summary>
    private static IModel BuildSqliteModel()
    {
        var modules = AllModules();
        var options = new DbContextOptionsBuilder<LocalNodeDbContext>()
            .UseSqlite("Data Source=:memory:")
            .Options;
        using var ctx = new LocalNodeDbContext(options, modules);
        return ctx.Model;
    }

    /// <summary>
    /// Builds the EF model using the Npgsql provider (the Bridge path).
    /// This mirrors what <c>DesignTimeDbContextFactory</c> in signal-bridge does.
    /// </summary>
    private static IModel BuildNpgsqlModel()
    {
        var modules = AllModules();
        // Use a fake connection string — Npgsql reads it only to determine the
        // server version; model compilation doesn't open a real connection.
        var options = new DbContextOptionsBuilder<NpgsqlProbeContext>()
            .UseNpgsql("Host=localhost;Database=probe;Username=probe;Password=probe")
            .Options;
        using var ctx = new NpgsqlProbeContext(options, modules);
        return ctx.Model;
    }

    // ── Tests ──────────────────────────────────────────────────────────────

    [Fact(DisplayName = "C2: shared modules compile on both SQLite and Npgsql providers")]
    public void SharedModules_CompileOnBothProviders()
    {
        // This test simply asserts that both model builds succeed (no exception).
        var sqliteModel = BuildSqliteModel();
        var npgsqlModel = BuildNpgsqlModel();

        Assert.NotNull(sqliteModel);
        Assert.NotNull(npgsqlModel);
    }

    [Fact(DisplayName = "C2: both-provider models contain the same entity types")]
    public void BothModels_ContainSameEntityTypes()
    {
        var sqliteModel = BuildSqliteModel();
        var npgsqlModel = BuildNpgsqlModel();

        // Compare by CLR type FullName — stable across providers.
        var sqliteTypes = sqliteModel.GetEntityTypes()
            .Select(e => e.ClrType.FullName!)
            .Order()
            .ToList();

        var npgsqlTypes = npgsqlModel.GetEntityTypes()
            .Select(e => e.ClrType.FullName!)
            .Order()
            .ToList();

        Assert.Equal(npgsqlTypes, sqliteTypes);
    }

    [Fact(DisplayName = "C2: both-provider models contain the same columns per entity type")]
    public void BothModels_ContainSameColumnsPerEntityType()
    {
        var sqliteModel = BuildSqliteModel();
        var npgsqlModel = BuildNpgsqlModel();

        var drifts = new List<string>();

        foreach (var npgsqlEntity in npgsqlModel.GetEntityTypes())
        {
            var sqliteEntity = sqliteModel.FindEntityType(npgsqlEntity.ClrType);
            if (sqliteEntity is null)
            {
                drifts.Add($"{npgsqlEntity.ClrType.Name}: entity missing from SQLite model");
                continue;
            }

            // Use property CLR name (stable across providers) to detect added/missing properties.
            var npgsqlCols = npgsqlEntity.GetProperties()
                .Select(p => p.Name)
                .Order()
                .ToList();

            var sqliteCols = sqliteEntity.GetProperties()
                .Select(p => p.Name)
                .Order()
                .ToList();

            if (!npgsqlCols.SequenceEqual(sqliteCols))
            {
                drifts.Add(
                    $"{npgsqlEntity.ClrType.Name}: property set differs.\n" +
                    $"  Npgsql:  {string.Join(", ", npgsqlCols)}\n" +
                    $"  SQLite:  {string.Join(", ", sqliteCols)}");
            }
        }

        if (drifts.Count > 0)
        {
            throw new InvalidOperationException(
                $"C2 column-drift detected ({drifts.Count} entities):\n\n" +
                string.Join("\n\n", drifts));
        }
    }

    [Fact(DisplayName = "C2: SQLite post-config sweep rewrites jsonb → TEXT")]
    public void SqliteModel_JsonbColumnsAreText()
    {
        var sqliteModel = BuildSqliteModel();
        var npgsqlModel = BuildNpgsqlModel();

        var violations = new List<string>();

        // Every jsonb column in the Npgsql model must be TEXT in the SQLite model.
        foreach (var npgsqlEntity in npgsqlModel.GetEntityTypes())
        {
            var sqliteEntity = sqliteModel.FindEntityType(npgsqlEntity.ClrType);
            if (sqliteEntity is null) continue;

            foreach (var npgsqlProp in npgsqlEntity.GetProperties())
            {
                if (!"jsonb".Equals(npgsqlProp.GetColumnType(), StringComparison.OrdinalIgnoreCase))
                    continue;

                var sqliteProp = sqliteEntity.FindProperty(npgsqlProp.Name);
                var sqliteColType = sqliteProp?.GetColumnType();

                if (!"TEXT".Equals(sqliteColType, StringComparison.OrdinalIgnoreCase))
                {
                    violations.Add(
                        $"{npgsqlEntity.ClrType.Name}.{npgsqlProp.Name}: " +
                        $"Npgsql=jsonb → SQLite={sqliteColType ?? "(null)"} (expected TEXT)");
                }
            }
        }

        if (violations.Count > 0)
        {
            throw new InvalidOperationException(
                $"C2 jsonb→TEXT sweep failed ({violations.Count} columns):\n" +
                string.Join("\n", violations));
        }
    }

    /// <summary>
    /// C2 bytea→BLOB sweep — <b>FORWARD-COVERAGE ONLY (currently a vacuous set).</b>
    /// </summary>
    /// <remarks>
    /// As of the ADR 0114/0115 cohort-1a.2 module set there are ZERO
    /// <c>HasColumnType("bytea")</c> columns owned by any shared entity module
    /// (the migration emits 358 TEXT, 0 BLOB; the only binary-ish column,
    /// <c>raw_provider_blob</c>, is a <c>string</c>→TEXT, and the fleet's one real
    /// bytea — <c>TenantRegistration.TeamPublicKey</c> — is configured inline in
    /// the Bridge control-plane DbContext, not contributed by a shared module, so
    /// it never reaches the local node). This assertion therefore iterates an
    /// EMPTY set today: it guards the sweep's bytea branch against a FUTURE
    /// module-owned bytea column, but proves nothing about the current model.
    /// Per the .NET-architect SPOT-CHECK (verdict 2026-06-13, condition 1) it is
    /// annotated as forward-coverage; the corrected tally is "358 TEXT, 0 BLOB".
    /// The explicit zero-column observation below makes the vacuity visible rather
    /// than silently green.
    /// </remarks>
    [Fact(DisplayName = "C2: SQLite post-config sweep rewrites bytea → BLOB (forward-coverage; 0 bytea columns today)")]
    public void SqliteModel_ByteaColumnsAreBlob()
    {
        var sqliteModel = BuildSqliteModel();
        var npgsqlModel = BuildNpgsqlModel();

        var violations = new List<string>();
        var byteaColumnsObserved = 0;

        // Every bytea column in the Npgsql model must be BLOB in the SQLite model.
        foreach (var npgsqlEntity in npgsqlModel.GetEntityTypes())
        {
            var sqliteEntity = sqliteModel.FindEntityType(npgsqlEntity.ClrType);
            if (sqliteEntity is null) continue;

            foreach (var npgsqlProp in npgsqlEntity.GetProperties())
            {
                if (!"bytea".Equals(npgsqlProp.GetColumnType(), StringComparison.OrdinalIgnoreCase))
                    continue;

                byteaColumnsObserved++;

                var sqliteProp = sqliteEntity.FindProperty(npgsqlProp.Name);
                var sqliteColType = sqliteProp?.GetColumnType();

                if (!"BLOB".Equals(sqliteColType, StringComparison.OrdinalIgnoreCase))
                {
                    violations.Add(
                        $"{npgsqlEntity.ClrType.Name}.{npgsqlProp.Name}: " +
                        $"Npgsql=bytea → SQLite={sqliteColType ?? "(null)"} (expected BLOB)");
                }
            }
        }

        if (violations.Count > 0)
        {
            throw new InvalidOperationException(
                $"C2 bytea→BLOB sweep failed ({violations.Count} columns):\n" +
                string.Join("\n", violations));
        }

        // Forward-coverage marker: the current module set owns NO bytea columns,
        // so this assertion is vacuous by design. If a future module introduces a
        // module-owned bytea column, this observed-count assertion will need to be
        // raised (and the assertion above starts doing real work). Documented as
        // a non-blocking C2 wording correction (verdict 2026-06-13, condition 1).
        Assert.Equal(0, byteaColumnsObserved);
    }

    [Fact(DisplayName = "C2: SQLite model has no PG-quoted filter predicates")]
    public void SqliteModel_HasNoPgQuotedIndexFilters()
    {
        var sqliteModel = BuildSqliteModel();

        var violations = new List<string>();

        foreach (var entityType in sqliteModel.GetEntityTypes())
        {
            foreach (var index in entityType.GetIndexes())
            {
                var filter = index.GetFilter();
                if (filter is not null && filter.Contains('"'))
                {
                    violations.Add(
                        $"{entityType.ClrType.Name} index {index.GetDatabaseName()}: " +
                        $"PG-quoted filter not stripped: {filter}");
                }
            }
        }

        if (violations.Count > 0)
        {
            throw new InvalidOperationException(
                $"C2 PG-quoted index filter found on SQLite model ({violations.Count}):\n" +
                string.Join("\n", violations));
        }
    }

    [Fact(DisplayName = "C2: payment reversal uniqueness filter is provider-consistent")]
    public void PaymentReversalUniqueIndex_FilterMatchesProvider()
    {
        const string indexName = "ux_payment_applications_tenant_reverses";
        const string npgsqlFilter = "\"ReversesApplicationId\" IS NOT NULL";

        var sqliteIndex = BuildSqliteModel()
            .FindEntityType(typeof(PaymentApplication))!
            .GetIndexes()
            .Single(index => index.GetDatabaseName() == indexName);
        var npgsqlIndex = BuildNpgsqlModel()
            .FindEntityType(typeof(PaymentApplication))!
            .GetIndexes()
            .Single(index => index.GetDatabaseName() == indexName);

        Assert.Null(sqliteIndex.GetFilter());
        Assert.Equal(npgsqlFilter, npgsqlIndex.GetFilter());
    }

    // ── Npgsql probe context ───────────────────────────────────────────────

    /// <summary>
    /// Minimal DbContext for Npgsql model-build. Does NOT reference SQLite.
    /// Accepts the same <see cref="IHarborlineEntityModule"/> set as
    /// <see cref="LocalNodeDbContext"/> but skips the SQLite post-config sweep.
    /// </summary>
    private sealed class NpgsqlProbeContext : DbContext
    {
        private readonly IEnumerable<IHarborlineEntityModule> _modules;

        public NpgsqlProbeContext(
            DbContextOptions<NpgsqlProbeContext> options,
            IEnumerable<IHarborlineEntityModule> modules) : base(options)
        {
            _modules = modules;
        }

        protected override void OnModelCreating(ModelBuilder modelBuilder)
        {
            base.OnModelCreating(modelBuilder);

            // Apply every module — same as SignalBridgeDbContext, no sweep.
            foreach (var module in _modules)
            {
                module.Configure(modelBuilder);
            }
        }
    }
}

using System;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;

using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging.Abstractions;

using Harborline.Api.Foundation.Crypto;
using Harborline.Api.Kernel.Crdt;
using Harborline.Api.Kernel.Crdt.Backends;
using Harborline.Api.LocalNodeHost.Data.Comms;

using Xunit;

namespace Harborline.Api.LocalNodeHost.Tests.ArchTests;

/// <summary>
/// C1 conversation-scope fence — the "make the wrong wiring impossible" guard (design §4: a conversation
/// whose id is the team channel MUST be plaintext + all-team; a <c>dm:</c>/<c>grp:</c>/<c>chan:</c>
/// conversation MUST — once those increments land — be SEALED + bounded-recipient). C1 ships ONLY the team
/// channel, so the LIVE assertions here pin the C1 facts (the team channel = the well-known plaintext,
/// all-team conversation) and the doctype vocabulary the DM increments attach to. The
/// <see cref="C4_C5_extension_point"/> documents — and structurally reserves — the assertions C4 (content
/// seal) + C5 (participant-scoped routing) will GROW this fence into.
/// </summary>
/// <remarks>
/// <para>
/// <b>What C1 can prove (and these assert):</b>
/// <list type="bullet">
///   <item>the team channel id is the bare well-known constant <c>"team"</c> (no prefix) — so the pre-C1
///     default route + the EF back-fill default are preserved exactly;</item>
///   <item>the team channel classifies as TEAM and NOT as a direct message — so the (later) DM seal/routing
///     policy never applies to the team channel, and the team policy never applies to a DM;</item>
///   <item>a team-channel message is PLAINTEXT end-to-end — the body stored in the read model + carried in
///     the CRDT state IS the literal author text (no seal), the C1 visibility fact;</item>
///   <item>the reserved DM/group/channel prefixes are distinct from each other and from the team id — so the
///     id-prefix policy classification is unambiguous.</item>
/// </list>
/// </para>
/// <para>
/// <b>The C4/C5 extension point (NOT yet enforced — documented seam).</b> When DM content encryption (C4)
/// lands, this fence GROWS an assertion that a <c>dm:</c> conversation's stored body is CIPHERTEXT (never the
/// plaintext author text) + has a non-empty bounded recipient set; when participant-scoped routing (C5)
/// lands, it grows an assertion that a <c>dm:</c> stream's recipient set is exactly the two participants and
/// the team channel's is "all team". Those assertions cannot be written in C1 (no seal field, no recipient
/// set exists yet) — the seam is named so the later increments extend THIS file rather than re-deriving the
/// invariant. See the design doc §4.2 + §6.
/// </para>
/// </remarks>
public sealed class CommsConversationScopeArchTests
{
    private static readonly IOperationVerifier Verifier = new Ed25519Verifier();

    // ── C1 FACT: the team channel is the bare well-known constant "team" (no prefix). ───────────────────────

    [Fact(DisplayName = "C1 fence: the team channel id is the bare well-known constant \"team\" (no prefix)")]
    public void TeamChannel_Is_TheWellKnownBareConstant()
    {
        Assert.Equal("team", CommsConversation.TeamConversationId);
        // The team channel uses NO kind prefix — it is the pre-C1 default route, preserved exactly.
        Assert.False(CommsConversation.TeamConversationId.StartsWith(CommsConversation.DirectMessagePrefix, StringComparison.Ordinal));
        Assert.False(CommsConversation.TeamConversationId.StartsWith(CommsConversation.GroupPrefix, StringComparison.Ordinal));
        Assert.False(CommsConversation.TeamConversationId.StartsWith(CommsConversation.ChannelPrefix, StringComparison.Ordinal));
    }

    // ── C1 FACT: the team channel classifies as TEAM and NOT as a direct message. ───────────────────────────

    [Fact(DisplayName = "C1 fence: the team channel is TEAM and NOT a direct message (the DM policy never applies to it)")]
    public void TeamChannel_ClassifiesAsTeam_NotDm()
    {
        Assert.True(CommsConversation.IsTeam(CommsConversation.TeamConversationId));
        Assert.False(CommsConversation.IsDirectMessage(CommsConversation.TeamConversationId));

        // A dm:-prefixed id classifies as a DM and NOT as the team channel — the inverse, so the team policy
        // (plaintext + all-team) never applies to a DM. (C1 has no LIVE dm: conversation; this proves the
        // classifier the C4/C5 fence will key its seal/routing assertions off.)
        const string dmId = "dm:abc123example";
        Assert.True(CommsConversation.IsDirectMessage(dmId));
        Assert.False(CommsConversation.IsTeam(dmId));
    }

    // ── C1 FACT: a team-channel message is PLAINTEXT end-to-end (the C1 visibility fact). ────────────────────

    [Fact(DisplayName = "C1 fence: a team-channel message is PLAINTEXT — the stored + synced body IS the literal author text")]
    public async Task TeamChannel_Message_Is_Plaintext_EndToEnd()
    {
        var dir = System.IO.Path.Combine(System.IO.Path.GetTempPath(), $"harborline-comms-arch-{Guid.NewGuid():N}");
        System.IO.Directory.CreateDirectory(dir);
        var services = new ServiceCollection();
        services.AddLogging();
        services.AddDbContextFactory<NodeLocalCommsDbContext>(o =>
            o.UseSqlite($"Data Source={System.IO.Path.Combine(dir, "comms.db")}"));
        services.AddSingleton<ICrdtEngine, YDotNetCrdtEngine>();
        await using var sp = services.BuildServiceProvider();
        var factory = sp.GetRequiredService<IDbContextFactory<NodeLocalCommsDbContext>>();
        await using (var ctx = await factory.CreateDbContextAsync())
            await ctx.Database.EnsureCreatedAsync();

        await using var team = new CommsCrdtProjection(
            sp.GetRequiredService<ICrdtEngine>(), factory, Verifier, NullLogger<CommsCrdtProjection>.Instance);
        // The team-channel projection owns the well-known "team" conversation.
        Assert.Equal(CommsConversation.TeamConversationId, team.ConversationId);

        var kp = KeyPair.Generate();
        var signer = new Ed25519Signer(kp);
        const string plaintext = "team standup at 10 — PLAINTEXT, not sealed";
        var message = await CommsMessageFactory.CreateSignedAsync(
            signer, authorPartyId: "alice", tenantId: "team-arch", body: plaintext,
            authoredAt: DateTimeOffset.UtcNow, conversationId: CommsConversation.TeamConversationId);

        // The signable + CRDT state carry the conversation + the LITERAL body (no seal in C1).
        Assert.Equal(CommsConversation.TeamConversationId, message.ConversationId);
        Assert.Equal(plaintext, message.Body);

        // The durable read row stores the LITERAL plaintext body (not ciphertext) for the team channel.
        await team.PersistLocalAsync(message, CancellationToken.None);
        await using (var ctx = await factory.CreateDbContextAsync())
        {
            var row = await ctx.Set<NodeMessage>().AsNoTracking().SingleAsync();
            Assert.Equal(CommsConversation.TeamConversationId, row.ConversationId);
            Assert.Equal(plaintext, row.Body); // PLAINTEXT at rest in the read model (C1 visibility fact)
        }

        // And the body re-verifies (the conversation id is inside the signed payload — replay-into-another-
        // thread defence; a team message signed for "team" verifies as "team").
        Assert.True(CommsMessageFactory.VerifyAuthorship(message, Verifier));

        try { System.IO.Directory.Delete(dir, recursive: true); } catch { /* best-effort */ }
    }

    // ── C1 FACT: the reserved kind prefixes are distinct (unambiguous id-prefix policy classification). ──────

    [Fact(DisplayName = "C1 fence: the reserved DM/group/channel prefixes are distinct (unambiguous classification)")]
    public void Reserved_Kind_Prefixes_Are_Distinct()
    {
        var prefixes = new[]
        {
            CommsConversation.DirectMessagePrefix,
            CommsConversation.GroupPrefix,
            CommsConversation.ChannelPrefix,
        };
        Assert.Equal(prefixes.Length, prefixes.Distinct().Count()); // all distinct
        foreach (var p in prefixes)
        {
            Assert.False(string.IsNullOrWhiteSpace(p));
            Assert.NotEqual(CommsConversation.TeamConversationId, p);
        }
    }

    // ── C2 FENCE: the conversation DESCRIPTOR invariant (design §4.2). ──────────────────────────────────────
    //
    // C2 adds the descriptor ({conversationId, kind, participantPartyIds, visibilityScope}), so the fence now
    // asserts the C2 facts the descriptor encodes: a dm: conversation MUST be kind=DirectMessage + Participants
    // visibility + EXACTLY 2 participant party ids; the team channel MUST stay kind=Team + AllTeam + the
    // "all team" sentinel (empty participant set). These are the structural "make the wrong wiring impossible"
    // guards the DM increments build on. (The dm:-MUST-be-SEALED + participant-ONLY-routing assertions remain
    // the C4/C5 extension point below — C2 is plaintext-but-gated.)

    [Fact(DisplayName = "C2 fence: a dm: conversation descriptor is DirectMessage + Participants + EXACTLY 2 parties")]
    public void Dm_Descriptor_Is_DirectMessage_Participants_TwoParties()
    {
        var dm = CommsConversationDescriptor.DirectMessage("team-arch", "alice", "bob");
        Assert.Equal(CommsConversationKind.DirectMessage, dm.Kind);
        Assert.Equal(CommsVisibilityScope.Participants, dm.VisibilityScope);
        Assert.Equal(2, dm.ParticipantPartyIds.Count);
        Assert.True(CommsConversation.IsDirectMessage(dm.ConversationId));
        dm.Validate(); // the invariant holds (throws if malformed)

        // The DM policy NEVER applies to the team channel, and the team policy never to a DM (inverse classification).
        var team = CommsConversationDescriptor.Team();
        Assert.Equal(CommsConversationKind.Team, team.Kind);
        Assert.Equal(CommsVisibilityScope.AllTeam, team.VisibilityScope);
        Assert.Empty(team.ParticipantPartyIds); // the "all team" sentinel — the roster is resolved live.
        team.Validate();
    }

    [Fact(DisplayName = "C2 fence: a malformed dm: descriptor (wrong participant count / scope) is REJECTED by Validate")]
    public void Malformed_Dm_Descriptor_Is_Rejected()
    {
        // A dm: descriptor with ≠2 participants violates the 1:1 invariant.
        var oneParty = new CommsConversationDescriptor(
            "dm:x", CommsConversationKind.DirectMessage, new[] { "alice" }, CommsVisibilityScope.Participants);
        Assert.Throws<InvalidOperationException>(() => oneParty.Validate());

        // A dm: descriptor with AllTeam visibility violates the participant-scoped invariant (a DM must be
        // Participants — the structural seed the C5 routing fence depends on).
        var allTeamDm = new CommsConversationDescriptor(
            "dm:x", CommsConversationKind.DirectMessage, new[] { "alice", "bob" }, CommsVisibilityScope.AllTeam);
        Assert.Throws<InvalidOperationException>(() => allTeamDm.Validate());

        // A team descriptor with a non-empty participant set violates the all-team sentinel invariant.
        var teamWithParticipants = new CommsConversationDescriptor(
            CommsConversation.TeamConversationId, CommsConversationKind.Team, new[] { "alice" }, CommsVisibilityScope.AllTeam);
        Assert.Throws<InvalidOperationException>(() => teamWithParticipants.Validate());
    }

    // ── C4 FENCE (NOW LIVE): a dm: conversation's stored body MUST be CIPHERTEXT; the team stays plaintext. ───
    //
    // C4 grows the documented C4/C5 extension point into a LIVE structural assertion (the "make the wrong wiring
    // impossible" guard): a sealed DM body carries the DmContentSeal envelope prefix (ciphertext), NEVER the
    // literal author text; the team channel body is the literal plaintext (asserted above). This is the body-half
    // of the design §4.2 invariant — the CONSTRUCTION fence. The confidentiality GUARANTEE (a forged party id
    // cannot derive the key) is NOT proven by C4 — it lands with the C5 roster-bound resolver; the B1 fence below
    // asserts production is fail-closed (NoDmConversationKeyProvider) in the meantime. (The C5 routing half — a
    // dm: stream's recipient set is EXACTLY the two participants + the inbound fail-closed guard — remains the C5
    // extension point at the bottom.)

    [Fact(DisplayName = "C4 fence: a dm: body is SEALED CIPHERTEXT (the seal envelope) — never the literal plaintext")]
    public async Task Dm_Body_Is_Sealed_Ciphertext_Never_Plaintext()
    {
        // The C4 derived-ECDH key for the alice↔bob conversation (the seed-derived stand-in resolver, acting as
        // alice). Both participants compute the same key; a non-participant cannot.
        var teamId = "team-arch";
        var dmId = DmConversationId.Derive(teamId, "alice", "bob");
        var aliceSeed = new byte[32];
        for (var i = 0; i < aliceSeed.Length; i++) aliceSeed[i] = (byte)(i + 7);
        var keyProvider = new DerivedDmConversationKeyProvider(
            new SeedDerivedParticipantDmKeyResolver(aliceSeed, "alice"));
        var key = keyProvider.TryDeriveConversationKey(dmId, "alice", "bob");
        Assert.NotNull(key);

        var kp = KeyPair.Generate();
        var signer = new Ed25519Signer(kp);
        const string plaintext = "for bob's eyes only — MUST be sealed, not plaintext";
        var sealedMessage = await CommsMessageFactory.CreateSignedSealedAsync(
            signer, authorPartyId: "alice", tenantId: teamId, plaintextBody: plaintext,
            authoredAt: DateTimeOffset.UtcNow, conversationId: dmId, conversationKey: key!);

        // The STORED/WIRE body is the SEAL envelope (ciphertext), NEVER the literal plaintext — the C4 fact.
        Assert.True(DmContentSeal.IsSealed(sealedMessage.Body));
        Assert.NotEqual(plaintext, sealedMessage.Body);
        Assert.DoesNotContain(plaintext, sealedMessage.Body, StringComparison.Ordinal);
        Assert.StartsWith(DmContentSeal.EnvelopePrefix, sealedMessage.Body, StringComparison.Ordinal);
        // The conversation id classifies as a DM (so the seal policy applies) — the team policy never does.
        Assert.True(CommsConversation.IsDirectMessage(sealedMessage.ConversationId));

        // A participant unseals it back to the plaintext; the signed payload covered the plaintext (DR-3).
        Assert.True(DmContentSeal.TryUnseal(
            sealedMessage.Body, key!, dmId, teamId, "alice", sealedMessage.MessageId, out var recovered));
        Assert.Equal(plaintext, recovered);
        Assert.True(CommsMessageFactory.VerifySealedAuthorship(sealedMessage, recovered, new Ed25519Verifier()));
        System.Security.Cryptography.CryptographicOperations.ZeroMemory(key!);
    }

    [Fact(DisplayName = "C4 construction: the self-guard returns null for a NON-PARTICIPANT who reports a non-participant id (NOT the leak guarantee)")]
    public void NonParticipant_SelfGuard_Returns_Null_For_Honest_NonParticipant()
    {
        // NOTE (sec-eng deep-review of PR #1325): this asserts the CONSTRUCTION's self-guard, NOT a confidentiality
        // GUARANTEE. With the test-double resolver, a non-participant who LIES about their party id (claims
        // "alice") CAN derive the key — the guard is an identity check, not a cryptographic barrier. The real
        // no-leak guarantee (a forged party id yields a useless key) is delivered by the C5 roster-bound resolver
        // and its real leak test. Here we only confirm the provider returns null when honestly told "not a
        // participant" (the routing/fail-closed behaviour the merge gate relies on).
        var teamId = "team-arch";
        var dmId = DmConversationId.Derive(teamId, "alice", "bob");
        var carolSeed = new byte[32];
        for (var i = 0; i < carolSeed.Length; i++) carolSeed[i] = (byte)(i + 13);
        // Carol's node, HONESTLY reporting "carol", is not a participant → the self-guard returns null.
        var carolProvider = new DerivedDmConversationKeyProvider(
            new SeedDerivedParticipantDmKeyResolver(carolSeed, "carol"));
        Assert.Null(carolProvider.TryDeriveConversationKey(dmId, "alice", "bob"));
    }

    // ── B1 / C5 STRUCTURAL FENCE (sec-eng deep-review of PR #1325, completed in C5): the DM key resolver must ──
    //    NEVER be PARTY-ID-DERIVABLE. C4 made AddNodeComms FAIL-CLOSED (NoDm) until a real roster-bound resolver
    //    existed; C5 supplies it (RosterDmKeyResolver — node-secret, derived from the install root, NOT the party
    //    id) and wires it via AddRosterBoundDmKeyProvider in the FULL host. The two posture fences below pin BOTH
    //    invariants: (1) AddNodeComms ALONE stays fail-closed (a minimal graph can derive NO DM key — so a future
    //    host that forgets to wire the real provider degrades to fail-closed, never to party-id-derivable); (2) the
    //    real wiring (AddNodeComms + AddRosterBoundDmKeyProvider) registers the roster-bound resolver; (3) the only
    //    IParticipantDmKeyResolver in the SHIPPED assembly is the node-secret RosterDmKeyResolver — a party-id-
    //    derivable resolver (the C4 stand-in) lives ONLY in this test assembly and can NEVER be the prod resolver.

    [Fact(DisplayName = "B1 fence: AddNodeComms ALONE (no root secret / roster) stays FAIL-CLOSED — NoDmConversationKeyProvider")]
    public async Task AddNodeComms_Alone_Is_FailClosed_NoDmKeyProvider()
    {
        // AddNodeComms by itself — a minimal graph with no install root secret + no active team + no roster — MUST
        // remain fail-closed: it registers the null-object NoDm provider so a host that does NOT wire the real
        // roster-bound provider can derive NO DM key (degrade-to-fail-closed, never to party-id-derivable).
        var dir = System.IO.Path.Combine(System.IO.Path.GetTempPath(), $"harborline-comms-b1fence-{Guid.NewGuid():N}");
        System.IO.Directory.CreateDirectory(dir);
        var services = new ServiceCollection();
        services.AddLogging();
        services.AddDbContextFactory<NodeLocalCommsDbContext>(o =>
            o.UseSqlite($"Data Source={System.IO.Path.Combine(dir, "comms.db")}"));
        services.AddNodeComms(); // ← AddNodeComms alone (no AddRosterBoundDmKeyProvider).

        await using var sp = services.BuildServiceProvider();
        var provider = sp.GetRequiredService<IDmConversationKeyProvider>();

        Assert.IsType<NoDmConversationKeyProvider>(provider);
        var teamId = "team-arch";
        var dmId = DmConversationId.Derive(teamId, "alice", "bob");
        Assert.Null(provider.TryDeriveConversationKey(dmId, "alice", "bob"));
        Assert.Null(provider.TryDeriveConversationKey(dmId, "bob", "alice"));

        try { System.IO.Directory.Delete(dir, recursive: true); } catch { /* best-effort */ }
    }

    [Fact(DisplayName = "C5 fence: the FULL prod wiring (AddNodeComms + AddRosterBoundDmKeyProvider) registers the ROSTER-BOUND resolver (NOT NoDm, NOT party-id-derivable)")]
    public async Task FullProdWiring_RegistersRosterBound_NotNoDm_NotPartyIdDerivable()
    {
        // The shipped host (Program.cs) is AddNodeComms() THEN AddRosterBoundDmKeyProvider(rootSeed, teamId, party).
        // After the override the DM key provider DI sees MUST be the real derived-ECDH provider over the roster-bound
        // resolver — NOT the NoDm null-object (so DMs CAN be sealed for a participant) and NOT a party-id-derivable
        // resolver (so a non-participant who forges a party id derives a DIFFERENT, useless key).
        var dir = System.IO.Path.Combine(System.IO.Path.GetTempPath(), $"harborline-comms-c5fence-{Guid.NewGuid():N}");
        System.IO.Directory.CreateDirectory(dir);
        var services = new ServiceCollection();
        services.AddLogging();
        services.AddDbContextFactory<NodeLocalCommsDbContext>(o =>
            o.UseSqlite($"Data Source={System.IO.Path.Combine(dir, "comms.db")}"));

        // A live roster is required (the resolver resolves a peer DM key from it). Seed a genesis roster + the
        // founder's own DM key, exactly as Program.cs does.
        var teamId = Guid.NewGuid();
        var teamIdStr = teamId.ToString("D");
        var founderKp = KeyPair.Generate();
        var founderSigner = new Ed25519Signer(founderKp);
        var roster = new Harborline.Api.LocalNodeHost.Enrollment.NodeTeamRoster(
            Harborline.Api.Foundation.IdentityAtlas.MemberRoster.StableGenesis(
                teamId, "alice", founderSigner, new Ed25519Verifier()));
        var rootSeed = new byte[32];
        for (var i = 0; i < rootSeed.Length; i++) rootSeed[i] = (byte)(i + 41);
        var aliceDmPub = Harborline.Api.LocalNodeHost.Enrollment.NodeDmKeyDerivation.DeriveDmPublicKey(rootSeed, teamIdStr);
        roster.SetOwnDmPublicKey("alice", aliceDmPub);
        services.AddSingleton(roster);

        services.AddNodeComms();
        services.AddRosterBoundDmKeyProvider(rootSeed, teamIdStr, "alice"); // ← the FULL prod override.

        await using var sp = services.BuildServiceProvider();
        var provider = sp.GetRequiredService<IDmConversationKeyProvider>();

        Assert.IsType<DerivedDmConversationKeyProvider>(provider);
        Assert.IsNotType<NoDmConversationKeyProvider>(provider);

        // Alice (the active member) + Bob: with Bob's DM key in the roster, alice can derive K_dm; without it (Bob
        // not yet enrolled), it is null (fail-closed) — proving the resolver reads the ROSTER, not a constant.
        var dmId = DmConversationId.Derive(teamIdStr, "alice", "bob");
        Assert.Null(provider.TryDeriveConversationKey(dmId, "alice", "bob")); // bob has no roster DM key yet.

        // Add Bob's roster DM key (a distinct root) → now alice derives a key. (This confirms the resolver depends
        // on the ROSTER-published public key, not a party id: with Bob's key present alice's seed-private × bob's
        // roster-public yields K_dm.) Inject via the DM-map seam directly — the resolver reads DmPublicKeyOf.
        var bobSeed = new byte[32];
        for (var i = 0; i < bobSeed.Length; i++) bobSeed[i] = (byte)(i + 97);
        var bobDmPub = Harborline.Api.LocalNodeHost.Enrollment.NodeDmKeyDerivation.DeriveDmPublicKey(bobSeed, teamIdStr);
        roster.SetOwnDmPublicKey("bob", bobDmPub); // (SetOwnDmPublicKey writes the party→DM-pubkey map entry.)
        var key = provider.TryDeriveConversationKey(dmId, "alice", "bob");
        Assert.NotNull(key);
        System.Security.Cryptography.CryptographicOperations.ZeroMemory(key!);

        try { System.IO.Directory.Delete(dir, recursive: true); } catch { /* best-effort */ }
    }

    [Fact(DisplayName = "C5 fence: the SHIPPED assembly's ONLY IParticipantDmKeyResolver is the node-secret RosterDmKeyResolver (NOT a party-id-derivable one)")]
    public void ProductionAssembly_DmKeyResolver_Is_NodeSecret_RosterBound_Only()
    {
        // C5 ships a resolver in the production assembly (RosterDmKeyResolver) — so the C4-era "assembly declares
        // ZERO resolvers" fence is replaced by: the assembly's resolver(s) are EXACTLY {RosterDmKeyResolver}, and a
        // party-id-derivable resolver (the C4 stand-in SeedDerivedParticipantDmKeyResolver) is NOT in the shipped
        // assembly. The roster-bound resolver derives the active member's DM private key from the NODE ROOT SECRET
        // (not the party id), so a forged party id yields a different, useless key — the real no-leak guarantee.
        var productionAssembly = typeof(NodeCommsComposition).Assembly;
        Assert.Equal("Harborline.Api.LocalNodeHost", productionAssembly.GetName().Name);

        var resolverImpls = productionAssembly.GetTypes()
            .Where(t => t is { IsClass: true, IsAbstract: false }
                        && typeof(IParticipantDmKeyResolver).IsAssignableFrom(t))
            .Select(t => t.Name)
            .OrderBy(n => n, StringComparer.Ordinal)
            .ToArray();

        // The ONLY shipped resolver is the node-secret roster-bound one.
        Assert.Equal(new[] { nameof(RosterDmKeyResolver) }, resolverImpls);

        // And the party-id-derivable stand-in is NOT in the shipped assembly (it lives ONLY in this test assembly).
        Assert.DoesNotContain(nameof(SeedDerivedParticipantDmKeyResolver), resolverImpls);
        var testDouble = typeof(SeedDerivedParticipantDmKeyResolver);
        Assert.Equal("Harborline.Api.LocalNodeHost.Tests", testDouble.Assembly.GetName().Name);
    }

    // ── C5 ARCH-FENCE (DM key-substitution fix; sec-eng deep-review BLOCKER of PR #1326): the roster accepts a ──
    //    DM key ONLY from a SIGNATURE-VALIDATED admission authenticated to that party. A DM key not authenticated to
    //    its owner (a substituted/unsigned record) is DROPPED. This is the structural "the wrong wiring is
    //    impossible" guard for the DM key-distribution channel — the DM public key is now bound INTO the signed
    //    admission envelope (AdmissionRecord.AdmittedDmPublicKey), so a roster writer cannot substitute a peer's DM
    //    key without re-signing (which it cannot). MemberRoster.DmPublicKeyOf surfaces ONLY the signed key.

    [Fact(DisplayName = "C5 arch-fence: the roster honors a DM key ONLY from the SIGNED admission — a substituted/unsigned DM key is DROPPED")]
    public void Roster_Honors_Dm_Key_Only_From_Signed_Admission()
    {
        var teamId = Guid.NewGuid();
        var founderKp = KeyPair.Generate();
        var founderSigner = new Ed25519Signer(founderKp);
        var aliceKp = KeyPair.Generate();

        // A distinct, well-formed 32-byte X25519 DM key per party (a valid curve point).
        static string Dm(byte seed)
        {
            var bytes = new byte[Harborline.Api.Foundation.Crypto.PrincipalId.LengthInBytes];
            for (var i = 0; i < bytes.Length; i++) bytes[i] = (byte)(seed + i);
            return Harborline.Api.Foundation.Crypto.PrincipalId.FromBytes(bytes).ToBase64Url();
        }
        var aliceAuthenticDm = Dm(0x20);
        var attackerDm = Dm(0xA0);

        // The founder admits Alice with her DM key SIGNED into the admission.
        var roster = Harborline.Api.Foundation.IdentityAtlas.MemberRoster
            .Genesis(teamId, "founder", founderSigner, Verifier, DateTimeOffset.UtcNow, Guid.NewGuid(),
                founderDmPublicKey: Dm(0x01))
            .Admit("founder", founderSigner, "alice",
                aliceKp.PrincipalId,
                Harborline.Api.Foundation.IdentityAtlas.Permissions.PermissionCompositions.Member,
                Verifier, DateTimeOffset.UtcNow, Guid.NewGuid(),
                newDmPublicKey: aliceAuthenticDm);

        // FENCE 1 — the roster surfaces ONLY the SIGNED DM key for Alice (the authority is the signed admission).
        var signedAliceDm = roster.DmPublicKeyOf("alice");
        Assert.NotNull(signedAliceDm);
        Assert.Equal(aliceAuthenticDm,
            Harborline.Api.Foundation.Crypto.PrincipalId.FromBytes(signedAliceDm!).ToBase64Url());

        // FENCE 2 — a record whose CARRIED DM key is SUBSTITUTED (away from the signed value) is DROPPED on rebuild,
        // so the substituted key NEVER reaches a live member. Take Alice's real synced record, rewrite the signed DM
        // field to the attacker's key WITHOUT re-signing (the attacker lacks the founder's key) → the signature no
        // longer validates → the record is dropped → Alice is NOT a live member of the rebuilt roster from that
        // record alone.
        var aliceRec = roster.EnumerateAdmissions().Single(r => r.PartyId == "alice");
        var substituted = aliceRec with
        {
            Admission = aliceRec.Admission with { DmPublicKey = attackerDm },
            DmPublicKey = Harborline.Api.Foundation.Crypto.PrincipalId.FromBase64Url(attackerDm).AsSpan().ToArray(),
        };
        var genesisRec = roster.EnumerateAdmissions().Single(r => r.Admission.IsGenesis);
        var rebuiltFromSubstitutedOnly = Harborline.Api.Foundation.IdentityAtlas.MemberRoster.FromSyncedRecords(
            new[] { genesisRec, substituted },
            System.Array.Empty<Harborline.Api.Foundation.IdentityAtlas.MemberRevocationRecord>(),
            Verifier);
        Assert.False(rebuiltFromSubstitutedOnly.Contains("alice")); // the substituted-DM-key record is DROPPED.
        Assert.Null(rebuiltFromSubstitutedOnly.DmPublicKeyOf("alice"));

        // FENCE 3 — with BOTH Alice's authentic record AND the substituted record present, the authentic key wins
        // (the substituted record is dropped; Alice is live via her real record carrying the signed key).
        var rebuiltWithBoth = Harborline.Api.Foundation.IdentityAtlas.MemberRoster.FromSyncedRecords(
            new[] { genesisRec, aliceRec, substituted },
            System.Array.Empty<Harborline.Api.Foundation.IdentityAtlas.MemberRevocationRecord>(),
            Verifier);
        Assert.True(rebuiltWithBoth.Contains("alice"));
        Assert.Equal(aliceAuthenticDm,
            Harborline.Api.Foundation.Crypto.PrincipalId.FromBytes(rebuiltWithBoth.DmPublicKeyOf("alice")!).ToBase64Url());

        // FENCE 4 (C5 round-2) — a same-party DM-key override by an AUTHORIZED ADMITTER is structurally rejected.
        // FENCE 2's substituted record fails the SIGNATURE check; this is the harder case the re-review surfaced —
        // an admin (legitimately holding members:admit) signs a FRESH, fully-VALID admission of an existing
        // participant carrying a different DM key. The signature/authority/no-escalation gates all PASS, so only
        // FIRST-WRITE-WINS keeps the binding immutable: the earliest genesis-rooted admission for a party fixes its
        // DM key, and a later same-party admission — even one signed by an authorized admitter — CANNOT overwrite it.
        // This is the structural "admit-authority ≠ key-binding-authority" guard.
        var adminKp = KeyPair.Generate();
        var adminSigner = new Ed25519Signer(adminKp);
        var rosterWithAdmin = roster.Admit(
            "founder", founderSigner, "admin", adminKp.PrincipalId,
            Harborline.Api.Foundation.IdentityAtlas.Permissions.PermissionCompositions.Admin,
            Verifier, DateTimeOffset.UnixEpoch.AddSeconds(1000), System.Guid.NewGuid(), newDmPublicKey: Dm(0x70));
        // The admin re-admits Alice (LATER issuance, fresh nonce) with the attacker's DM key — a genuine signature.
        var adminReAdmitAlice = Harborline.Api.Foundation.IdentityAtlas.RosterSigning.SignAdmission(
            signer: adminSigner, teamId: teamId, admittedPartyId: "alice",
            admittedPublicKey: aliceKp.PrincipalId, admittedByPartyId: "admin",
            isGenesis: false, issuedAt: DateTimeOffset.UnixEpoch.AddSeconds(2000), nonce: System.Guid.NewGuid(),
            admittedDmPublicKey: attackerDm);
        var adminOverrideRec = new Harborline.Api.Foundation.IdentityAtlas.MemberAdmissionRecord(
            teamId.ToString("D"), "alice", aliceKp.PrincipalId,
            adminReAdmitAlice, TransportPublicKey: null,
            DmPublicKey: Harborline.Api.Foundation.Crypto.PrincipalId.FromBase64Url(attackerDm).AsSpan().ToArray());
        var fence4Records = rosterWithAdmin.EnumerateAdmissions().Append(adminOverrideRec).ToArray();
        var rebuiltFence4 = Harborline.Api.Foundation.IdentityAtlas.MemberRoster.FromSyncedRecords(
            fence4Records,
            System.Array.Empty<Harborline.Api.Foundation.IdentityAtlas.MemberRevocationRecord>(),
            Verifier);
        Assert.True(rebuiltFence4.Contains("alice"));
        Assert.Equal(aliceAuthenticDm,
            Harborline.Api.Foundation.Crypto.PrincipalId.FromBytes(rebuiltFence4.DmPublicKeyOf("alice")!).ToBase64Url());
    }

    // ── C5 EXTENSION POINT (documented + reserved; NOT yet enforced — C5 adds participant-scoped routing). ────

    /// <summary>
    /// The seam C5 (participant-scoped sync routing) grows this fence into. C4 sealed the body (above); C5 adds
    /// the sync-plane half: a <c>dm:</c> stream's outbound recipient set is EXACTLY the two participants, and the
    /// inbound fail-closed guard drops a <c>dm:</c> frame the local member is not a participant of (defence in
    /// depth — even with C4's seal making a leaked frame unreadable, C5 stops the frame reaching a non-participant
    /// at all). The descriptor's <see cref="CommsConversationDescriptor.ParticipantPartyIds"/> +
    /// <see cref="CommsConversationDescriptor.IsParticipant"/> are the seam C5's routing/inbound-guard fence keys
    /// off. (See design §3.2 + §6.)
    /// </summary>
    [Fact(DisplayName = "C4 fence: C5 extension point is documented + reserved (participant-scoped routing lands here)")]
    public void C5_extension_point()
    {
        var dm = CommsConversationDescriptor.DirectMessage("team-arch", "alice", "bob");
        Assert.True(dm.IsParticipant("alice"));
        Assert.True(dm.IsParticipant("bob"));
        Assert.False(dm.IsParticipant("carol")); // the leak adversary C5's routing fence will keep the frame from.
        Assert.True(CommsConversation.IsDirectMessage(dm.ConversationId));
        Assert.False(CommsConversation.IsDirectMessage(CommsConversation.TeamConversationId));
    }
}

using System.Reflection;
using System.Runtime.CompilerServices;
using System.Text;
using System.Text.RegularExpressions;

using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using Xunit.Abstractions;

using Harborline.Api.Foundation.Assets;
using Harborline.Api.Foundation.Assets.Common;
using Harborline.Api.Foundation.Assets.Entities;
using Harborline.Api.Foundation.Forms.DependencyInjection;
using Harborline.Api.Foundation.Forms.Engine.DependencyInjection;

namespace Harborline.Api.LocalNodeHost.Tests.ArchTests;

/// <summary>Ticket 368: host-reachable composition extensions resolve only with reviewed seams.</summary>
public sealed class CompositionExtensionIsolationArchTests
{
    private const string DiscoveryPattern = "^(?:AddEntityStore.*|AddHarborline(?:.*Engine|EngineRoom)|AddNode.*Composition)$";
    private const string ProductionAssemblyPrefix = "Harborline.";
    private static readonly Regex DiscoveryRegex = new(DiscoveryPattern, RegexOptions.CultureInvariant);
    private sealed record Extension(MethodInfo Method);
    private sealed record CompositionSource(string Text, int FileCount);
    internal sealed record CrossExtensionCollaborator(string Extension, string Type, string Reason);

    // This is the one mechanism the fence applies. A row is live only when withholding it breaks its extension.
    internal static readonly CrossExtensionCollaborator[] KnownCrossExtensionCollaborators =
    [
        new("AddEntityStoreFormDefinitionStore", "IEntityStore", "entity-backed definition storage"),
        new("AddEntityStoreFormDefinitionStore", "IEntityMutationStore", "entity-backed definition mutation"),
        new("AddEntityStoreFormDefinitionStore", "AuthorizationGate/IRoleGateAdmission", "definition lifecycle admission"),
        new("AddEntityStoreWorkflowDefinitionStore", "IEntityStore", "entity-backed workflow storage"),
        new("AddEntityStoreWorkflowDefinitionStore", "IEntityMutationStore", "entity-backed workflow mutation"),
        new("AddEntityStoreWorkflowDefinitionStore", "AuthorizationGate/IRoleGateAdmission", "workflow lifecycle admission"),
        new("AddHarborlineFormEngine", "IEntityMutationStore", "authorized form writer mutation store"),
        new("AddHarborlineFormEngine", "AuthorizationGate/IRoleGateAdmission", "form-engine authorization"),
        new("AddHarborlineFormEngine", "ITenantKeyProvider/IFieldEncryptor", "field encryption substrate"),
        new("AddHarborlineFormEngine", "NodeFormsComposition", "shared forms composition supplies schema, audit, signer, and definition-store substrates"),
    ];

    private readonly ITestOutputHelper output;
    public CompositionExtensionIsolationArchTests(ITestOutputHelper output) => this.output = output;

    [Fact(DisplayName = "Ticket 368: every Program-reachable entity-store or engine extension resolves its own registered graph")]
    public void ProgramReachableExtensions_ResolveEveryRegisteredService()
    {
        var assemblies = ProductionAssemblies();
        var source = HostCompositionSource();
        var extensions = DiscoverExtensions(assemblies, source);
        output.WriteLine($"Discovery regex: {DiscoveryPattern}");
        output.WriteLine($"Production assembly prefix: {ProductionAssemblyPrefix}");
        output.WriteLine($"Discovered production assemblies ({assemblies.Length}): {string.Join(", ", assemblies.Select(assembly => assembly.GetName().Name))}");
        output.WriteLine($"Composition source files (expected/found >= 1/{source.FileCount})");
        output.WriteLine($"Discovered inventory ({extensions.Length}): {string.Join(", ", extensions.Select(e => e.Method.Name))}");
        Assert.NotEmpty(extensions);
        foreach (var extension in extensions) Resolve(extension, except: null);
    }

    [Fact(DisplayName = "Ticket 368: a discovered extension is named when no host composition source invokes it")]
    public void CrdtEngine_IsReachedByHostComposition()
    {
        var assemblies = ProductionAssemblies();
        var source = HostCompositionSource();
        var extension = Assert.Single(ExtensionCandidates(assemblies), candidate => candidate.Method.Name == "AddHarborlineCrdtEngine");
        Assert.True(IsInvoked(source.Text, extension.Method.Name),
            $"Discovered extension is unreached by host composition source: {extension.Method.DeclaringType!.FullName}.{extension.Method.Name}");
    }

    [Fact(DisplayName = "Ticket 368: every allow-list row burns down when its collaborator is no longer needed")]
    public void AllowListRows_AreRequiredByTheirExtension()
    {
        var expected = KnownCrossExtensionCollaboratorRows();
        var found = RequiredCollaboratorRows();
        var stale = expected.Except(found, StringComparer.Ordinal).ToArray();
        var missing = found.Except(expected, StringComparer.Ordinal).ToArray();
        Assert.True(stale.Length == 0 && missing.Length == 0,
            "Allow-list and live required collaborators differ. Stale rows mask nothing; missing rows are unreviewed:\n"
            + $"stale: {string.Join(", ", stale)}\nmissing: {string.Join(", ", missing)}");
    }

    [Fact(DisplayName = "Ticket 368 mutation: removing a needed allow-list row names its extension and collaborator")]
    public void UnapprovedCollaborator_IsNamed()
    {
        var row = Assert.Single(KnownCrossExtensionCollaborators, item => item.Extension == "AddHarborlineFormEngine" && item.Type == "NodeFormsComposition");
        var error = Assert.ThrowsAny<Exception>(() => Resolve(FindExtension(row.Extension), row));
        Assert.Contains(row.Extension, error.Message, StringComparison.Ordinal);
        Assert.Contains("IFormDefinitionStore", error.Message, StringComparison.Ordinal);
    }

    internal static string[] KnownCrossExtensionCollaboratorRows() =>
        [.. KnownCrossExtensionCollaborators.Select(Row).Order(StringComparer.Ordinal)];
    internal static string[] DiscoveredKnownCrossExtensionCollaborators() => RequiredCollaboratorRows();

    private static string[] RequiredCollaboratorRows() =>
        [.. KnownCrossExtensionCollaborators.Where(row => !CanResolve(FindExtension(row.Extension), row)).Select(Row).Order(StringComparer.Ordinal)];
    private static string Row(CrossExtensionCollaborator row) => $"{row.Extension}:{row.Type}";
    private static bool CanResolve(Extension extension, CrossExtensionCollaborator except)
    {
        try { Resolve(extension, except); return true; } catch { return false; }
    }

    private static void Resolve(Extension extension, CrossExtensionCollaborator? except)
    {
        var services = Bootstrap();
        var first = services.Count;
        Invoke(extension.Method, services);
        var registered = services.Skip(first).ToArray();
        foreach (var row in KnownCrossExtensionCollaborators.Where(row => row.Extension == extension.Method.Name && row != except)) Apply(row, services);
        using var provider = services.BuildServiceProvider(new ServiceProviderOptions { ValidateOnBuild = true, ValidateScopes = true });
        using var scope = provider.CreateScope();
        foreach (var descriptor in registered.Where(d => !d.ServiceType.IsGenericTypeDefinition))
        {
            try
            {
                var resolver = descriptor.Lifetime == ServiceLifetime.Scoped ? scope.ServiceProvider : provider;
                _ = descriptor.IsKeyedService ? resolver.GetRequiredKeyedService(descriptor.ServiceType, descriptor.ServiceKey) : resolver.GetRequiredService(descriptor.ServiceType);
            }
            catch (Exception error)
            {
                throw new Xunit.Sdk.XunitException($"{extension.Method.Name} cannot resolve registered {descriptor.ServiceType.FullName}: {error.Message}");
            }
        }
    }

    private static ServiceCollection Bootstrap()
    {
        var services = new ServiceCollection();
        services.AddSingleton<IConfiguration>(new ConfigurationBuilder().AddInMemoryCollection([new KeyValuePair<string, string?>("LocalNode:DataDirectory", Path.GetTempPath())]).Build());
        services.AddLogging();
        services.AddTestKernelClock(); // shared composition-test minimum: configuration, logging, TimeProvider only.
        return services;
    }

    private static Extension[] DiscoverExtensions() => DiscoverExtensions(ProductionAssemblies(), HostCompositionSource());

    private static Extension[] DiscoverExtensions(Assembly[] assemblies, CompositionSource source) =>
        ExtensionCandidates(assemblies)
            .Where(extension => IsInvoked(source.Text, extension.Method.Name))
            .ToArray();

    private static Extension[] ExtensionCandidates(IEnumerable<Assembly> assemblies) =>
        assemblies.SelectMany(Types).SelectMany(type => type.GetMethods(BindingFlags.Public | BindingFlags.Static))
            .Where(method => method.IsDefined(typeof(ExtensionAttribute), false) && DiscoveryRegex.IsMatch(method.Name)
                && method.GetParameters() is [{ ParameterType: var type }, ..] && type == typeof(IServiceCollection))
            .Where(HasSupportedCompositionSignature)
            .Select(method => new Extension(method)).OrderBy(extension => extension.Method.Name, StringComparer.Ordinal).ToArray();

    private static bool HasSupportedCompositionSignature(MethodInfo method) => method.GetParameters().Skip(1).All(parameter =>
        parameter.HasDefaultValue || parameter.ParameterType == typeof(Func<IServiceProvider, IEntityMutationStore>));

    private static bool IsInvoked(string source, string methodName) =>
        Regex.IsMatch(source, $@"\.{Regex.Escape(methodName)}\s*\(");

    private static IEnumerable<Type> Types(Assembly assembly)
    {
        try { return assembly.GetTypes(); }
        catch (ReflectionTypeLoadException error) { return error.Types.OfType<Type>(); }
    }

    private static Assembly[] ProductionAssemblies()
    {
        var assemblies = new Dictionary<string, Assembly>(StringComparer.Ordinal);
        var pending = new Queue<Assembly>([typeof(Program).Assembly]);
        while (pending.TryDequeue(out var assembly))
        {
            var name = assembly.GetName().Name!;
            if (!name.StartsWith(ProductionAssemblyPrefix, StringComparison.Ordinal)
                || name.EndsWith(".Tests", StringComparison.OrdinalIgnoreCase)
                || !assemblies.TryAdd(assembly.FullName!, assembly))
            {
                continue;
            }

            foreach (var reference in assembly.GetReferencedAssemblies())
            {
                var referenceName = reference.Name!;
                if (referenceName.StartsWith(ProductionAssemblyPrefix, StringComparison.Ordinal)
                    && !referenceName.EndsWith(".Tests", StringComparison.OrdinalIgnoreCase))
                {
                    pending.Enqueue(Assembly.Load(reference));
                }
            }
        }

        return assemblies.Values.OrderBy(assembly => assembly.GetName().Name, StringComparer.Ordinal).ToArray();
    }

    private static CompositionSource HostCompositionSource([CallerFilePath] string file = "")
    {
        var hostRoot = Path.GetDirectoryName(Path.GetDirectoryName(Path.GetDirectoryName(file)!)!)!;
        var files = Directory.EnumerateFiles(hostRoot, "*.cs", SearchOption.AllDirectories)
            .Where(path => !path.Split(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar)
                .Any(segment => segment.Equals("tests", StringComparison.OrdinalIgnoreCase)
                    || segment.Equals("obj", StringComparison.OrdinalIgnoreCase)))
            .Order(StringComparer.Ordinal)
            .ToArray();
        Assert.NotEmpty(files);
        return new CompositionSource(string.Join(Environment.NewLine, files.Select(path => StripCommentsAndStrings(File.ReadAllText(path)))), files.Length);
    }

    private static string StripCommentsAndStrings(string source)
    {
        var stripped = new StringBuilder(source.Length);
        for (var index = 0; index < source.Length; index++)
        {
            if (source[index] == '/' && index + 1 < source.Length && source[index + 1] == '/')
            {
                index = StripToLineEnd(source, stripped, index + 2) - 1;
                continue;
            }

            if (source[index] == '/' && index + 1 < source.Length && source[index + 1] == '*')
            {
                index = StripBlockComment(source, stripped, index + 2) - 1;
                continue;
            }

            if (source[index] == '\"' || source[index] == '\'')
            {
                index = StripLiteral(source, stripped, index) - 1;
                continue;
            }

            stripped.Append(source[index]);
        }

        return stripped.ToString();
    }

    private static int StripToLineEnd(string source, StringBuilder stripped, int index)
    {
        for (; index < source.Length && source[index] != '\r' && source[index] != '\n'; index++) stripped.Append(' ');
        return index;
    }

    private static int StripBlockComment(string source, StringBuilder stripped, int index)
    {
        stripped.Append("  ");
        for (; index < source.Length; index++)
        {
            if (source[index] == '*' && index + 1 < source.Length && source[index + 1] == '/')
            {
                stripped.Append("  ");
                return index + 2;
            }

            stripped.Append(source[index] is '\r' or '\n' ? source[index] : ' ');
        }

        return index;
    }

    private static int StripLiteral(string source, StringBuilder stripped, int index)
    {
        var quote = source[index];
        var quoteCount = 1;
        while (index + quoteCount < source.Length && source[index + quoteCount] == quote) quoteCount++;
        var verbatim = quote == '\"' && index > 0 && source[index - 1] == '@';
        for (var count = 0; count < quoteCount; count++) stripped.Append(' ');
        index += quoteCount;

        for (; index < source.Length; index++)
        {
            if (source[index] is '\r' or '\n')
            {
                stripped.Append(source[index]);
                continue;
            }

            if (source[index] == quote)
            {
                var closingCount = 1;
                while (index + closingCount < source.Length && source[index + closingCount] == quote) closingCount++;
                if (closingCount >= quoteCount)
                {
                    for (var count = 0; count < quoteCount; count++) stripped.Append(' ');
                    return index + quoteCount;
                }

                if (verbatim && quoteCount == 1)
                {
                    stripped.Append("  ");
                    index++;
                    continue;
                }
            }

            if (!verbatim && quoteCount == 1 && source[index] == '\\' && index + 1 < source.Length)
            {
                stripped.Append("  ");
                index++;
                continue;
            }

            stripped.Append(' ');
        }

        return index;
    }

    private static Extension FindExtension(string name) => Assert.Single(DiscoverExtensions(), extension => extension.Method.Name == name);
    private static void Invoke(MethodInfo method, IServiceCollection services)
    {
        var arguments = method.GetParameters().Select(parameter => parameter.Position switch
        {
            0 => (object)services,
            _ when parameter.ParameterType == typeof(Func<IServiceProvider, IEntityMutationStore>) => (Func<IServiceProvider, IEntityMutationStore>)EntityMutations,
            _ when parameter.HasDefaultValue => parameter.DefaultValue,
            _ => throw new Xunit.Sdk.XunitException($"{method.Name} has an unsupported composition argument {parameter.ParameterType.FullName}"),
        }).ToArray();
        _ = method.Invoke(null, arguments);
    }

    private static void AddEntityStoreReader(IServiceCollection services) =>
        services.AddSingleton<IEntityStore>(_ => new InMemoryEntityStoreReader(new InMemoryEntityStore(new InMemoryAssetStorage(), TimeProvider.System)));
    private static void AddEntityMutationStore(IServiceCollection services) =>
        services.AddSingleton<IEntityMutationStore>(_ => new InMemoryEntityStore(new InMemoryAssetStorage(), TimeProvider.System));
    private static void AddFieldEncryption(IServiceCollection services)
    {
        services.AddSingleton<Harborline.Api.Foundation.Recovery.TenantKey.ITenantKeyProvider,
            Harborline.Api.Foundation.Recovery.TenantKey.InMemoryTenantKeyProvider>();
        services.AddSingleton<Harborline.Api.Foundation.Recovery.Crypto.IFieldEncryptor,
            Harborline.Api.Foundation.Recovery.Crypto.TenantKeyProviderFieldEncryptor>();
    }
    private static void AddAuthorization(IServiceCollection services) => services.AddTestAuthorizationGate();
    private static void AddNodeForms(IServiceCollection services) => services.AddTestNodeForms();
    private static void Apply(CrossExtensionCollaborator row, IServiceCollection services)
    {
        switch (row.Type)
        {
            case "IEntityStore": AddEntityStoreReader(services); break;
            case "IEntityMutationStore": AddEntityMutationStore(services); break;
            case "AuthorizationGate/IRoleGateAdmission": AddAuthorization(services); break;
            case "ITenantKeyProvider/IFieldEncryptor": AddFieldEncryption(services); break;
            case "NodeFormsComposition": AddNodeForms(services); break;
            default: throw new Xunit.Sdk.XunitException($"Unknown allow-list collaborator {row.Extension}:{row.Type}");
        }
    }
    private static IEntityMutationStore EntityMutations(IServiceProvider provider) => provider.GetRequiredService<IEntityMutationStore>();
}

using System.Runtime.CompilerServices;
using System.Text.RegularExpressions;

using Xunit;

namespace Harborline.Api.LocalNodeHost.Tests.ArchTests;

/// <summary>
/// T-664: the field runtime chooses a value-domain field's editor (DES-0030 decision 3), so no host
/// code may map an authored <c>ControlHint</c> string to a control type again. Every production read
/// of the hint is listed here with the reason it is not a dispatch; a new read is red until someone
/// adds a row, and a row whose line is gone is red too, so the list cannot go stale.
/// </summary>
public sealed class ControlHintDispatchFenceTests
{
    /// <summary>(repo-relative path, trimmed code line, occurrences). Each is a pass-through or an admission check.</summary>
    private static readonly (string Path, string Line, int Count)[] AllowedReads =
    [
        // Wire overlay to stored model, and stored model back to the authoring wire.
        ("apps/local-node-host/Health/FormDefinitionRoutes.cs", "ControlHint: kv.Value.ControlHint,", 1),
        ("apps/local-node-host/Health/FormDefinitionRoutes.cs", "f.ControlHint,", 1),
        // Admission: a hint on a value-domain field is refused (T-724 ruling 37); only its presence is read.
        ("apps/local-node-host/Health/FormDefinitionRoutes.cs", "if (string.IsNullOrWhiteSpace(field.ControlHint)", 1),
        // Render wire: a value-domain field's hint is then replaced by the runtime's editor (FieldEditorChoice).
        ("apps/local-node-host/Health/FormsRoutes.cs", "f.ControlHint,", 1),
        ("packages/foundation-forms-engine/FormEngine.cs", "ControlHint: fieldOverlay?.ControlHint,", 2),
        // Render plan (T-752): a write, not a read; the runtime's editor overwrites a value-domain field's hint.
        ("apps/local-node-host/Health/RenderPlanCatalogue.cs", "presentation[\"controlHint\"] = domain.Editor.ToString();", 1),
    ];

    private static readonly Regex HintRead = new(
        @"\.ControlHint\b|\[\s*""controlHint""\s*\]|Property\(\s*""controlHint""",
        RegexOptions.Compiled);

    [Fact(DisplayName = "T-664: no host code dispatches on an authored ControlHint")]
    public void Every_production_read_of_the_control_hint_is_an_allowed_pass_through()
    {
        var root = RepositoryRoot();
        var reads = Directory.EnumerateFiles(root, "*.cs", SearchOption.AllDirectories)
            .Select(file => (File: file, Relative: Path.GetRelativePath(root, file).Replace('\\', '/')))
            .Where(file => !file.Relative.Split('/').Any(segment => ExcludedSegments.Contains(segment, StringComparer.OrdinalIgnoreCase)))
            .SelectMany(file => CodeOnly(File.ReadAllText(file.File))
                .Split('\n')
                .Select(line => line.Trim())
                .Where(line => HintRead.IsMatch(line))
                .Select(line => (Path: file.Relative, Line: line)))
            .GroupBy(read => read)
            .ToDictionary(group => group.Key, group => group.Count());

        var expected = AllowedReads.ToDictionary(row => (row.Path, row.Line), row => row.Count);
        var unexpected = reads.Where(read => !expected.TryGetValue(read.Key, out var count) || count != read.Value)
            .Select(read => $"{read.Key.Path}: `{read.Key.Line}` x{read.Value}");
        var stale = expected.Where(row => !reads.ContainsKey(row.Key))
            .Select(row => $"{row.Key.Path}: `{row.Key.Line}`");

        Assert.True(!unexpected.Any() && !stale.Any(),
            "ControlHint reads must be pass-throughs or the admission check. Unexpected: ["
            + string.Join(" | ", unexpected) + "]; stale allow rows: [" + string.Join(" | ", stale) + "]");
    }

    private static readonly string[] ExcludedSegments =
        ["tests", "obj", "bin", "node_modules", ".git", ".claude", ".codex", "artifacts", ".feed"];

    private static string CodeOnly(string source)
    {
        var withoutBlockComments = Regex.Replace(source, @"/\*.*?\*/", string.Empty, RegexOptions.Singleline);
        return Regex.Replace(withoutBlockComments, @"//.*?$", string.Empty, RegexOptions.Multiline);
    }

    private static string RepositoryRoot([CallerFilePath] string thisFile = "")
    {
        var hostRoot = Path.GetDirectoryName(Path.GetDirectoryName(Path.GetDirectoryName(thisFile)!)!)!;
        var repositoryRoot = Path.GetDirectoryName(Path.GetDirectoryName(hostRoot)!)!;
        Assert.True(File.Exists(Path.Combine(repositoryRoot, "Harborline.Api.slnx")),
            $"Could not locate the repository root from '{thisFile}'.");
        return repositoryRoot;
    }
}

using System.Reflection;
using System.Security.Cryptography;

using Microsoft.Data.Sqlite;
using Microsoft.Extensions.DependencyInjection;

using Harborline.Api.Foundation.Crypto;
using Harborline.Api.Kernel.Security.Crypto;
using Harborline.Api.Kernel.Security.KeyDistribution;
using Harborline.Api.Kernel.Security.Keys;
using Harborline.Api.LocalNodeHost.Data;
using Harborline.Api.LocalNodeHost.Data.KeyDistribution;
using Harborline.Api.LocalNodeHost.Enrollment;
using Harborline.Api.LocalNodeHost.Tests.TestDoubles;

using Xunit;

// MD-1 uses the FOUNDATION canonical-JSON Ed25519 signer/verifier (the IOperationSigner path); disambiguate from the
// kernel-security Crypto Ed25519Signer/Verifier of the same name.
using Ed25519Signer = Harborline.Api.Foundation.Crypto.Ed25519Signer;
using Ed25519Verifier = Harborline.Api.Foundation.Crypto.Ed25519Verifier;
using MemberRoster = Harborline.Api.Foundation.IdentityAtlas.MemberRoster;

namespace Harborline.Api.LocalNodeHost.Tests.ArchTests;

/// <summary>
/// <b>DekPairingResolverArchFence</b> — the MD-1 / <b>G-1</b> no-mock-crypto fence (joint ADR 0113+0117 amendment,
/// 2026-06-24; composes the #1325 / bug-1312 B1 pattern). The LOAD-BEARING guard on tenant-DEK distribution: the
/// wrap recipient key MUST be roster-bound, the production resolver MUST be the roster-bound provider (fail-closed
/// null-object for any unadmitted recipient), the SHIPPED assembly MUST declare ZERO identity-derivable DEK
/// resolvers, and the LEAK test MUST run against the REAL roster-bound resolver (a green leak test against a
/// stand-in is a FALSE POSITIVE).
/// </summary>
/// <remarks>
/// This file is the DEK-pairing analogue of <c>CommsConversationScopeArchTests</c>'s B1/C5 DM-key fence — same
/// structure: (1) the fail-closed default posture; (2) the production override registers the roster-bound resolver;
/// (3) the assembly-reflection fence (no identity-derivable resolver ships); (4) the real leak test + the real
/// end-to-end admitted-decrypt against the roster-bound resolver; (5) the G-2 compartmentalization vector.
/// </remarks>
public sealed class DekPairingResolverArchFence
{
    private static readonly IX25519KeyAgreement Kem = new X25519KeyAgreement();
    private static readonly IOperationVerifier Verifier = new Ed25519Verifier();

    // ── Helpers: a verified roster with a real admitted party whose DM key is signed in, + the node's DM keypair ──

    /// <summary>
    /// Build a verified two-party roster (founder "owner" admits "sally"), with each party's DM public key derived
    /// from its OWN node root seed + signed into its admission (the C5 forge-proof binding). Returns the host-level
    /// <see cref="NodeTeamRoster"/> the resolver consumes, the admin signer, sally's node root seed (so the test can
    /// derive sally's DM PRIVATE key for unwrap), and the team id string.
    /// </summary>
    private static (NodeTeamRoster roster, Ed25519Signer adminSigner, byte[] sallyRootSeed, string teamId)
        BuildRosterWithAdmittedParty()
    {
        var teamId = Guid.NewGuid();
        var teamIdStr = teamId.ToString("D");

        var ownerKp = KeyPair.Generate();
        var ownerSigner = new Ed25519Signer(ownerKp);
        var ownerRootSeed = RandomSeed(11);
        var ownerDmPub = NodeDmKeyDerivation.DeriveDmPublicKey(ownerRootSeed, teamIdStr);

        var sallyKp = KeyPair.Generate();
        var sallyRootSeed = RandomSeed(97);
        var sallyDmPub = NodeDmKeyDerivation.DeriveDmPublicKey(sallyRootSeed, teamIdStr);

        // Genesis(owner) then Admit(sally) — both DM keys signed into the chain (forge-proof).
        var member = MemberRoster
            .Genesis(teamId, "owner", ownerSigner, Verifier, DateTimeOffset.UnixEpoch, Guid.NewGuid(),
                founderDmPublicKey: PrincipalId.FromBytes(ownerDmPub).ToBase64Url())
            .Admit("owner", ownerSigner, "sally", sallyKp.PrincipalId,
                Harborline.Api.Foundation.IdentityAtlas.Permissions.PermissionCompositions.Member,
                Verifier, DateTimeOffset.UnixEpoch.AddSeconds(1), Guid.NewGuid(),
                newDmPublicKey: PrincipalId.FromBytes(sallyDmPub).ToBase64Url());

        // Host-level roster: seed the live DM-key map exactly as production harvests it from the validated chain.
        var roster = new NodeTeamRoster(member);
        roster.SetOwnDmPublicKey("owner", ownerDmPub);
        roster.SetOwnDmPublicKey("sally", sallyDmPub);

        return (roster, ownerSigner, sallyRootSeed, teamIdStr);
    }

    private static byte[] RandomSeed(byte salt)
    {
        var s = new byte[32];
        for (var i = 0; i < s.Length; i++) s[i] = (byte)(i + salt);
        return s;
    }

    private static byte[] FreshDek()
    {
        var dek = new byte[TenantDekWrapper.TenantDekLength];
        RandomNumberGenerator.Fill(dek);
        return dek;
    }

    // ── FENCE 1 — fail-closed DEFAULT posture ──────────────────────────────────────────────────────────────────

    [Fact(DisplayName = "G-1 fence: AddNodeTenantDekPairing ALONE (no roster) registers the FAIL-CLOSED NoTenantDekPairingResolver")]
    public void AddNodeTenantDekPairing_Alone_Is_FailClosed()
    {
        var services = new ServiceCollection();
        services.AddSingleton<IX25519KeyAgreement, X25519KeyAgreement>();
        services.AddNodeTenantDekPairing();

        using var sp = services.BuildServiceProvider();
        var resolver = sp.GetRequiredService<ITenantDekPairingResolver>();

        Assert.IsType<NoTenantDekPairingResolver>(resolver);
        // No recipient is resolvable → no DEK can be wrapped to anyone (fail-closed, never plaintext).
        Assert.Null(resolver.ResolveRecipientWrapKey("sally"));
        Assert.Null(resolver.ResolveRecipientWrapKey("owner"));
    }

    // ── FENCE 2 — the production override registers the ROSTER-BOUND resolver ──────────────────────────────────

    [Fact(DisplayName = "G-1 fence: the FULL wiring (+ AddRosterBoundTenantDekPairingResolver) registers the ROSTER-BOUND resolver")]
    public void FullWiring_Registers_RosterBound_Resolver()
    {
        var (roster, _, _, _) = BuildRosterWithAdmittedParty();

        var services = new ServiceCollection();
        services.AddSingleton<IX25519KeyAgreement, X25519KeyAgreement>();
        services.AddSingleton(roster);
        services.AddNodeTenantDekPairing();
        services.AddRosterBoundTenantDekPairingResolver(); // the production override.

        using var sp = services.BuildServiceProvider();
        var resolver = sp.GetRequiredService<ITenantDekPairingResolver>();

        Assert.IsType<RosterBoundTenantDekPairingResolver>(resolver);
        Assert.IsNotType<NoTenantDekPairingResolver>(resolver);

        // An ADMITTED party resolves to its ROSTER-BOUND DM key; an UNADMITTED party resolves null (fail-closed).
        var sallyKey = resolver.ResolveRecipientWrapKey("sally");
        Assert.NotNull(sallyKey);
        Assert.Equal(roster.DmPublicKeyOf("sally"), sallyKey); // it IS the roster's signed key, nothing derived.
        Assert.Null(resolver.ResolveRecipientWrapKey("mallory")); // never admitted → no wrap key.
    }

    // ── FENCE 3 — the SHIPPED assembly declares ZERO identity-derivable DEK resolvers ──────────────────────────

    [Fact(DisplayName = "G-1 fence: the SHIPPED assembly's ONLY ITenantDekPairingResolver impls are the roster-bound + fail-closed (NO identity-derivable one)")]
    public void ProductionAssembly_DekPairingResolver_Is_RosterBound_Or_FailClosed_Only()
    {
        var productionAssembly = typeof(RosterBoundTenantDekPairingResolver).Assembly;
        Assert.Equal("Harborline.Api.LocalNodeHost", productionAssembly.GetName().Name);

        var resolverImpls = productionAssembly.GetTypes()
            .Where(t => t is { IsClass: true, IsAbstract: false }
                        && typeof(ITenantDekPairingResolver).IsAssignableFrom(t))
            .Select(t => t.Name)
            .OrderBy(n => n, StringComparer.Ordinal)
            .ToArray();

        // The ONLY shipped resolvers are the roster-bound one and the fail-closed null-object. There is NO third
        // (identity-derivable) resolver in production — the only identity-derivable one lives in the TEST assembly.
        Assert.Equal(
            new[] { nameof(NoTenantDekPairingResolver), nameof(RosterBoundTenantDekPairingResolver) },
            resolverImpls);
        Assert.DoesNotContain(nameof(IdentityDerivableTenantDekPairingResolver), resolverImpls);

        // And the identity-derivable stand-in really is test-assembly-only (structurally unreferenceable from prod).
        var testDouble = typeof(IdentityDerivableTenantDekPairingResolver);
        Assert.Equal("Harborline.Api.LocalNodeHost.Tests", testDouble.Assembly.GetName().Name);
    }

    // ── FENCE 4a — the REAL LEAK TEST (against the REAL roster-bound resolver, NOT a stand-in) ─────────────────

    [Fact(DisplayName = "G-1 leak test (REAL resolver): an UNADMITTED / rogue party resolves NO wrap key — no DEK can be minted for it")]
    public void Leak_Test_Unadmitted_Party_Gets_No_Dek_From_Real_Resolver()
    {
        // This is the REAL no-leak guarantee, run against the REAL RosterBoundTenantDekPairingResolver — NOT a
        // construction stand-in. A rogue party that simply CLAIMS an id it was never admitted under resolves null,
        // so the pairing route can mint NO DEK wrap for it. (The bug-1312 lesson: a green leak test against a
        // party-id-derivable stand-in would be a FALSE POSITIVE; this runs against the production resolver.)
        var (roster, adminSigner, _, teamId) = BuildRosterWithAdmittedParty();
        ITenantDekPairingResolver resolver = new RosterBoundTenantDekPairingResolver(roster);
        var wrapper = new TenantDekWrapper(Kem);
        var dek = FreshDek();

        // A rogue party "mallory" — never admitted. The resolver gives no wrap key.
        Assert.Null(resolver.ResolveRecipientWrapKey("mallory"));

        // So the pairing flow cannot wrap a DEK to mallory: a host that resolves null MUST fail closed (it has no
        // recipient key to pass the wrapper). Demonstrate the flow does exactly that.
        var malloryWrapKey = resolver.ResolveRecipientWrapKey("mallory");
        Assert.Null(malloryWrapKey); // ← the fail-closed gate; the host never reaches Wrap() with a null key.

        // Contrast: an ADMITTED party DOES resolve, so the flow proceeds for a legitimate recipient (FENCE 4b proves
        // the full decrypt). This asserts the resolver is the boundary — admission, not identity-claim, gates it.
        var sallyWrapKey = resolver.ResolveRecipientWrapKey("sally");
        Assert.NotNull(sallyWrapKey);
        var ctx = TenantDekPairingContext.For("tenant-A", "sally", homeEpoch: 0);
        var wrap = wrapper.Wrap(dek, sallyWrapKey!, ctx, "owner", adminSigner);
        Assert.NotNull(wrap); // a legitimate wrap is producible only for an admitted recipient.
        _ = teamId;
    }

    [Fact(DisplayName = "G-1 leak test (REAL resolver): a rogue party that FORGES an admitted party's id still cannot unwrap (it lacks the node-secret private key)")]
    public void Leak_Test_Forged_Id_Cannot_Unwrap_Because_Private_Key_Is_Node_Secret()
    {
        // The deeper no-leak guarantee: even if a wrap for "sally" is observed on the wire, a rogue party that CLAIMS
        // to be sally cannot unwrap it — sally's DM PRIVATE key is HKDF(sally-node-root, teamId), node-secret, NOT
        // derivable from the party id (the structural difference from the #1325 stand-in). The rogue holds a
        // DIFFERENT private key, so OpenBox fails closed.
        var (roster, adminSigner, sallyRootSeed, teamId) = BuildRosterWithAdmittedParty();
        ITenantDekPairingResolver resolver = new RosterBoundTenantDekPairingResolver(roster);
        var wrapper = new TenantDekWrapper(Kem);
        var dek = FreshDek();

        var ctx = TenantDekPairingContext.For("tenant-A", "sally", homeEpoch: 0);
        var sallyWrapKey = resolver.ResolveRecipientWrapKey("sally")!;
        var wrap = wrapper.Wrap(dek, sallyWrapKey, ctx, "owner", adminSigner);

        // The genuine sally unwraps (her node-secret private key matches her roster-bound public key).
        var sallyPrivate = NodeDmKeyDerivation.DeriveDmPrivateKey(sallyRootSeed, teamId);
        var genuine = wrapper.VerifyAndUnwrap(wrap, adminSigner.IssuerId, ctx, sallyPrivate, Verifier);
        Assert.Equal(dek, genuine);

        // A rogue "claims to be sally" but holds its OWN node-root-derived private key → OpenBox fails closed.
        var rogueRootSeed = RandomSeed(200);
        var roguePrivate = NodeDmKeyDerivation.DeriveDmPrivateKey(rogueRootSeed, teamId);
        var leaked = wrapper.VerifyAndUnwrap(wrap, adminSigner.IssuerId, ctx, roguePrivate, Verifier);
        Assert.Null(leaked); // the forged-identity unwrap yields NO DEK — the real no-leak guarantee.
    }

    // ── FENCE 4b — END-TO-END: an admitted party unwraps the DEK + DECRYPTS the tenant's real data ─────────────

    [Fact(DisplayName = "MD-1 E2E: an ADMITTED party unwraps the tenant DEK + DECRYPTS the tenant's SQLCipher data; an UNADMITTED party cannot")]
    public void E2E_Admitted_Party_Decrypts_Tenant_Data_Unadmitted_Cannot()
    {
        var (roster, adminSigner, sallyRootSeed, teamId) = BuildRosterWithAdmittedParty();
        ITenantDekPairingResolver resolver = new RosterBoundTenantDekPairingResolver(roster);
        var wrapper = new TenantDekWrapper(Kem);

        // The tenant's REAL data-encryption key: HKDF(owner-root, relationalStoreKeyId) — the SQLCipher DEK keying
        // the financial store. Create a SQLCipher store under it and write a row of the tenant's data.
        var ownerRootSeed = RandomSeed(11); // (matches the owner seed BuildRosterWithAdmittedParty used)
        var tenantDek = new SqlCipherKeyDerivation().DeriveSqlCipherKey(
            ownerRootSeed, LocalNodeSqlCipherRegistration.RelationalStoreKeyId);

        var dir = Path.Combine(Path.GetTempPath(), "harborline-md1-e2e-" + Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(dir);
        var dbPath = Path.Combine(dir, "tenant-data.db");
        try
        {
            const string secret = "tenant-A confidential ledger row #4001";
            CreateSqlCipherStoreWithRow(dbPath, tenantDek, secret);

            // ── The ADMITTED party (sally) ── resolves her roster-bound recipient key, the owner wraps the tenant DEK
            // to her, she verify+unwraps with her node-secret private key, opens the store, reads the tenant's data.
            var sallyWrapKey = resolver.ResolveRecipientWrapKey("sally");
            Assert.NotNull(sallyWrapKey);
            var ctx = TenantDekPairingContext.For("tenant-A", "sally", homeEpoch: 0);
            var wrap = wrapper.Wrap(tenantDek, sallyWrapKey!, ctx, "owner", adminSigner);

            var sallyPrivate = NodeDmKeyDerivation.DeriveDmPrivateKey(sallyRootSeed, teamId);
            var recoveredDek = wrapper.VerifyAndUnwrap(wrap, adminSigner.IssuerId, ctx, sallyPrivate, Verifier);
            Assert.NotNull(recoveredDek);
            Assert.Equal(tenantDek, recoveredDek);

            var read = ReadRowUnderKey(dbPath, recoveredDek!);
            Assert.Equal(secret, read); // the admitted party DECRYPTS the tenant's real data end-to-end.

            // ── The UNADMITTED party (mallory) ── resolves NO wrap key → the pairing flow fails closed: no DEK is
            // ever minted for her, so she has nothing to open the store with.
            Assert.Null(resolver.ResolveRecipientWrapKey("mallory"));

            // And even the recovered store-DEK only opens THIS tenant's store: a sanity check that a wrong key fails.
            var wrongDek = FreshDek();
            Assert.Throws<SqliteException>(() => ReadRowUnderKey(dbPath, wrongDek));
        }
        finally
        {
            SqliteConnection.ClearAllPools();
            try { Directory.Delete(dir, recursive: true); } catch { /* best-effort */ }
        }
    }

    // ── FENCE 5 — G-2 COMPARTMENTALIZATION: a Harborline wrap yields no flight-deck-decryptable material ──────────

    [Fact(DisplayName = "MD-1 G-2: a tenant-A (harborline) DEK wrap cannot decrypt tenant-B (flight-deck) data — per-app DEK lineages stay independent")]
    public void G2_Compartmentalization_LegacyWrap_Cannot_Decrypt_FlightDeck()
    {
        var (roster, adminSigner, sallyRootSeed, teamId) = BuildRosterWithAdmittedParty();
        ITenantDekPairingResolver resolver = new RosterBoundTenantDekPairingResolver(roster);
        var wrapper = new TenantDekWrapper(Kem);

        // Two INDEPENDENT per-app root seeds → two INDEPENDENT tenant DEKs for the same logical org (0117 D2).
        var harborlineRoot = RandomSeed(11);
        var flightDeckRoot = RandomSeed(211);
        var keyDeriv = new SqlCipherKeyDerivation();
        var harborlineDek = keyDeriv.DeriveSqlCipherKey(harborlineRoot, LocalNodeSqlCipherRegistration.RelationalStoreKeyId);
        var flightDeckDek = keyDeriv.DeriveSqlCipherKey(flightDeckRoot, LocalNodeSqlCipherRegistration.RelationalStoreKeyId);
        Assert.NotEqual(harborlineDek, flightDeckDek); // independent lineages.

        // Wrap ONLY the Harborline DEK to sally; she unwraps it.
        var ctx = TenantDekPairingContext.For("harborline-tenant-A", "sally", homeEpoch: 0);
        var wrap = wrapper.Wrap(harborlineDek, resolver.ResolveRecipientWrapKey("sally")!, ctx, "owner", adminSigner);
        var sallyPrivate = NodeDmKeyDerivation.DeriveDmPrivateKey(sallyRootSeed, teamId);
        var recovered = wrapper.VerifyAndUnwrap(wrap, adminSigner.IssuerId, ctx, sallyPrivate, Verifier);

        Assert.NotNull(recovered);
        Assert.Equal(harborlineDek, recovered);        // it carries the Harborline DEK …
        Assert.NotEqual(flightDeckDek, recovered);   // … and is NOT the flight-deck DEK — no cross-app material.

        // Concretely: a flight-deck store keyed with flightDeckDek does NOT open under the unwrapped Harborline DEK.
        var dir = Path.Combine(Path.GetTempPath(), "harborline-md1-g2-" + Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(dir);
        var fdPath = Path.Combine(dir, "flight-deck.db");
        try
        {
            CreateSqlCipherStoreWithRow(fdPath, flightDeckDek, "flight-deck tenant-B data");
            Assert.Throws<SqliteException>(() => ReadRowUnderKey(fdPath, recovered!)); // Harborline key cannot open it.
        }
        finally
        {
            SqliteConnection.ClearAllPools();
            try { Directory.Delete(dir, recursive: true); } catch { /* best-effort */ }
        }
    }

    // ── SQLCipher helpers (the proven raw-key-hex PRAGMA pattern from SqlCipherStoreDekTests) ──────────────────

    // SC-1 (LocalNodeSqlCipherRegistration): the cipher provider MUST be bound explicitly, else a bare
    // Batteries init can pin the NON-cipher e_sqlite3 provider and PRAGMA key becomes a SILENT NO-OP (plaintext).
    // These tests open SQLCipher stores directly (no host registration runs), so pin the cipher provider once here.
    private static int s_cipherProviderBound;

    private static void EnsureCipherProvider()
    {
        if (Interlocked.Exchange(ref s_cipherProviderBound, 1) == 0)
        {
            SQLitePCL.raw.SetProvider(new SQLitePCL.SQLite3Provider_e_sqlcipher());
        }
    }

    private static void CreateSqlCipherStoreWithRow(string dbPath, byte[] key, string value)
    {
        EnsureCipherProvider();
        using (var conn = new SqliteConnection($"Data Source={dbPath};Pooling=False"))
        {
            conn.Open();
            ApplyKey(conn, key);
            using var create = conn.CreateCommand();
            create.CommandText = "CREATE TABLE t(v TEXT); INSERT INTO t(v) VALUES ($v);";
            create.Parameters.AddWithValue("$v", value);
            create.ExecuteNonQuery();
        }
        SqliteConnection.ClearAllPools();
    }

    private static string ReadRowUnderKey(string dbPath, byte[] key)
    {
        EnsureCipherProvider();
        // Clear pools so a wrong-key open cannot reuse a pooled handle that was opened under a different key — the
        // same hygiene SqlCipherStoreDekTests uses; otherwise the wrong-key probe can spuriously succeed.
        SqliteConnection.ClearAllPools();
        using var conn = new SqliteConnection($"Data Source={dbPath};Pooling=False");
        conn.Open();
        ApplyKey(conn, key);
        // Force SQLCipher to decrypt the header by reading sqlite_schema FIRST — a wrong/absent key surfaces here as
        // SQLITE_NOTADB ("file is not a database"), exactly as the SC-1 interceptor probe does. Without this, the
        // first row read may not reliably trip the key check.
        using (var probe = conn.CreateCommand())
        {
            probe.CommandText = "SELECT count(*) FROM sqlite_schema;";
            probe.ExecuteScalar();
        }
        using var read = conn.CreateCommand();
        read.CommandText = "SELECT v FROM t LIMIT 1;";
        return (string)read.ExecuteScalar()!;
    }

    private static void ApplyKey(SqliteConnection conn, byte[] key)
    {
        var hex = Convert.ToHexString(key);
        using var keyCmd = conn.CreateCommand();
        keyCmd.CommandText = $"PRAGMA key = \"x'{hex}'\";";
        keyCmd.ExecuteNonQuery();
    }
}

using Harborline.Api.LocalNodeHost.Tests.Audit;

namespace Harborline.Api.LocalNodeHost.Tests.ArchTests;

public sealed class DeterministicSourcePathsArchTests
{
    [Fact]
    public void Metadata_paths_resolve_to_the_same_source_and_exact_repository_relative_identity()
    {
        var root = AuditAppendSymbolInventory.RepositoryRoot();
        Assert.True(File.Exists(Path.Combine(root, "Harborline.Api.slnx")));
        foreach (var relative in new[]
                 {
                     "apps/local-node-host/Program.cs",
                     "packages/kernel-audit/AuthoritySnapshot.cs",
                 })
        {
            var absolute = Path.GetFullPath(Path.Combine(root, relative));
            var expectedSource = File.ReadAllText(absolute);
            foreach (var path in new[] { relative, absolute, "/_/" + relative })
            foreach (var separator in new[] { '/', '\\' })
            {
                var input = path.Replace('/', separator).Replace('\\', separator);
                Assert.Equal(relative, AuditAppendSymbolInventory.NormalizeFile(input));
                Assert.Equal(absolute, AuditAppendSymbolInventory.ResolveSourcePath(input));
                Assert.Equal(expectedSource, File.ReadAllText(AuditAppendSymbolInventory.ResolveSourcePath(input)));
            }

            for (var depth = 1; depth <= root.Split(Path.DirectorySeparatorChar).Length + 2; depth++)
            foreach (var marker in new[] { "_/", "/_/" })
            foreach (var separator in new[] { '/', '\\' })
            {
                var input = (string.Concat(Enumerable.Repeat("../", depth)) + marker + relative)
                    .Replace('/', separator);
                Assert.Equal(relative, AuditAppendSymbolInventory.NormalizeFile(input));
                Assert.Equal(absolute, AuditAppendSymbolInventory.ResolveSourcePath(input));
            }
        }

        // A marker inside an ordinary path, or a climb with no marker, retains its identity.
        foreach (var ordinary in new[] { "apps/_/example.cs", "../outside.cs", "_ordinary/example.cs" })
            Assert.Equal(Path.GetFullPath(Path.Combine(root, ordinary)),
                AuditAppendSymbolInventory.ResolveSourcePath(ordinary));
        var outside = Path.Combine(Path.GetTempPath(), "source-outside-checkout.cs");
        Assert.Equal(Path.GetFullPath(outside), AuditAppendSymbolInventory.ResolveSourcePath(outside));
    }
}

using System.Runtime.CompilerServices;
using System.Text.RegularExpressions;

namespace Harborline.Api.LocalNodeHost.Tests.ArchTests;

/// <summary>
/// DES-0029 kernel-core-ck-6: every production durable write site in the host is classified against the
/// transaction-boundary obligation (record and audit atomic, rollback, replay, batch refusal). A new
/// <c>SaveChanges</c>/<c>ExecuteUpdate</c>/<c>ExecuteDelete</c>/<c>ExecuteSql</c>/<c>ExecuteNonQuery</c> site,
/// or a changed count in a classified file, fails until its row in
/// <c>durable-write-classification.tsv</c> is written or updated.
/// </summary>
public sealed class DurableWriteClassificationArchTests
{
    private static readonly Regex WriteCall = new(
        @"\b(?:SaveChanges|ExecuteUpdate|ExecuteDelete|ExecuteSqlRaw|ExecuteSqlInterpolated|ExecuteSql|ExecuteNonQuery)(?:Async)?\s*[(<]",
        RegexOptions.Compiled);

    [Fact]
    public void EveryProductionDurableWriteSiteIsClassifiedWithItsExactCount()
    {
        // The class vocabulary, not an allow-list: every row must use one of these.
        string[] classes = ["atomic-audit", "record-is-audit", "outbox-audit", "post-commit-audit", "unaudited", "n/a"];
        var root = RepositoryRoot();
        var rows = ReadClassification(root);
        Assert.All(rows, row =>
        {
            Assert.True(classes.Contains(row.Value.Class), $"{row.Key}: unknown class '{row.Value.Class}'");
            Assert.False(string.IsNullOrWhiteSpace(row.Value.Evidence), $"{row.Key}: evidence is required");
        });

        var expected = rows.Select(row => $"{row.Key}\t{row.Value.Count}").Order(StringComparer.Ordinal).ToArray();
        var actual = Scan(root).Select(item => $"{item.Path}\t{item.Count}").ToArray();
        Assert.True(
            expected.SequenceEqual(actual, StringComparer.Ordinal),
            "Classify every durable write site in durable-write-classification.tsv. Missing or stale rows:" +
            Environment.NewLine + string.Join(Environment.NewLine, actual.Except(expected).Select(row => "+ " + row)
                .Concat(expected.Except(actual).Select(row => "- " + row))));
    }

    [Fact]
    public void ScanReportsAPlantedUnclassifiedWrite()
    {
        var root = Path.Combine(Path.GetTempPath(), "ck6-write-scan-" + Guid.NewGuid().ToString("N"));
        var planted = Path.Combine(root, "apps", "local-node-host", "Data", "Planted");
        Directory.CreateDirectory(planted);
        try
        {
            File.WriteAllText(Path.Combine(planted, "Offender.cs"),
                "sealed class Offender { async Task Go(DbContext c) { await c.SaveChangesAsync(); " +
                "await c.Set<Row>().ExecuteDeleteAsync(); /* c.SaveChanges(); */ } }");

            Assert.Equal([("apps/local-node-host/Data/Planted/Offender.cs", 2)], Scan(root));
        }
        finally
        {
            Directory.Delete(root, recursive: true);
        }
    }

    private static Dictionary<string, (int Count, string Class, string Evidence)> ReadClassification(string root)
    {
        var path = Path.Combine(root, "apps", "local-node-host", "tests", "ArchTests", "durable-write-classification.tsv");
        var result = new Dictionary<string, (int, string, string)>(StringComparer.Ordinal);
        foreach (var line in File.ReadLines(path))
        {
            if (string.IsNullOrWhiteSpace(line) || line.StartsWith('#')) continue;
            var columns = line.Split('\t', 4);
            Assert.Equal(4, columns.Length);
            Assert.True(int.TryParse(columns[1], out var count) && count > 0, $"Bad count: {line}");
            Assert.True(result.TryAdd(columns[0], (count, columns[2], columns[3])), $"Duplicate row: {columns[0]}");
        }
        return result;
    }

    private static (string Path, int Count)[] Scan(string root)
    {
        var host = Path.Combine(root, "apps", "local-node-host");
        if (!Directory.Exists(host)) return [];
        return Directory.EnumerateFiles(host, "*.cs", SearchOption.AllDirectories)
            .Select(file => (File: file, Relative: Path.GetRelativePath(root, file).Replace('\\', '/')))
            .Where(item => !item.Relative.Split('/').Any(segment =>
                segment is "tests" or "bin" or "obj" or ".git" or ".claude" or "Migrations"))
            .Where(item => !item.Relative.EndsWith(".Designer.cs", StringComparison.Ordinal)
                && !item.Relative.EndsWith(".g.cs", StringComparison.Ordinal))
            .Select(item => (item.Relative, Count: WriteCall.Matches(StripComments(File.ReadAllText(item.File))).Count))
            .Where(item => item.Count > 0)
            .OrderBy(item => item.Relative, StringComparer.Ordinal)
            .ToArray();
    }

    private static string StripComments(string source) => Regex.Replace(
        source,
        @"//.*?$|/\*.*?\*/",
        string.Empty,
        RegexOptions.Multiline | RegexOptions.Singleline);

    private static string RepositoryRoot([CallerFilePath] string file = "")
    {
        var directory = new DirectoryInfo(Path.GetDirectoryName(file)!);
        while (directory is not null)
        {
            if (Directory.Exists(Path.Combine(directory.FullName, "apps"))
                && Directory.Exists(Path.Combine(directory.FullName, "packages")))
                return directory.FullName;
            directory = directory.Parent;
        }
        throw new DirectoryNotFoundException();
    }
}

