/// <summary>
/// ADR 0135 invoice-approval threshold — the #1357 deep-review's <b>Finding 1 (threshold single-source)</b>
/// fast-follow as an ARCH-TEST.
/// </summary>
/// <remarks>
/// <para>
/// The issue-route gate (<see cref="NodeInvoiceApprovalCutover.ShouldRouteToEngine"/> → route to the engine
/// iff <c>Total &gt; V1ApprovalThreshold</c>, strictly above) and the pinned decision table's "over" row
/// (<c>RequireApproval</c> iff <c>amount &gt;= over-row floor</c>) encode the SAME boundary in two places.
/// They already DERIVE from the single <see cref="NodeWorkflowDefinitions.V1ApprovalThreshold"/> constant
/// (the route reads it directly; the over-row floor is <c>V1ApprovalThreshold + 0.01m</c>) — so this is the
/// arch-test that PINS that agreement, so a future edit to either side cannot silently open the gap interval
/// between "the route routes to the engine" and "the table requires approval".
/// </para>
/// <para>
/// <b>The invariant (the gap interval must stay empty):</b> for every representable money amount, the route's
/// route-to-engine decision MUST equal the pinned table's require-approval decision. If they ever disagree at
/// any boundary cent, an over-threshold invoice could be sent to the engine yet auto-approve in the table
/// (split-brain) — or the reverse. The boundary cents are the only place they can diverge, so the test pins
/// every cent across the boundary plus the endpoints.
/// </para>
/// <para>
/// <b>Proof the fence bites:</b> bump the over-row floor in <see cref="NodeWorkflowDefinitions"/> away from
/// <c>V1ApprovalThreshold + 0.01m</c> (e.g. to <c>+ 1.00m</c>), or change the route gate to <c>&gt;=</c>, and
/// <see cref="RouteGate_And_PinnedTable_AgreeAtEveryBoundaryCent"/> fails immediately — the empty gap interval
/// has opened.
/// </para>
/// </remarks>
public sealed class InvoiceApprovalThresholdSingleSourceArchTests
{
    private static readonly string PinnedVersion = NodeWorkflowDefinitions.InvoiceApprovalV1Version;
    private static readonly decimal Threshold = NodeWorkflowDefinitions.V1ApprovalThreshold;

    /// <summary>
    /// The route gate and the pinned decision table agree at every cent across the boundary (and at the
    /// endpoints): "route to engine" ⇔ "require approval", for all of them. This is the single-source
    /// guarantee — the gap interval between the two encodings is provably empty.
    /// </summary>
    [Fact(DisplayName = "Finding 1: the issue-route gate (>$5k) and the pinned over-row (require-approval) AGREE at every boundary cent — the gap interval is empty")]
    public void RouteGate_And_PinnedTable_AgreeAtEveryBoundaryCent()
    {
        var table = NodeWorkflowDefinitions.InvoiceApprovalThresholdTable();

        // Walk every cent in a window straddling the boundary: well below → well above. This covers the only
        // amounts where the two encodings could diverge (the boundary cents), plus normal-magnitude amounts.
        for (var cents = (long)((Threshold - 5m) * 100m); cents <= (long)((Threshold + 5m) * 100m); cents++)
        {
            var amount = cents / 100m;

            var routeToEngine = NodeInvoiceApprovalCutover.ShouldRouteToEngine(InvoiceWithTotal(amount));
            var requiresApproval =
                table.EvaluatePinned(PinnedVersion, amount).Decision == ApprovalDecision.RequireApproval;

            Assert.True(
                routeToEngine == requiresApproval,
                $"Threshold split-brain at amount {amount.ToString(CultureInfo.InvariantCulture)}: " +
                $"route routes-to-engine={routeToEngine} but pinned table requires-approval={requiresApproval}. " +
                "The issue-route gate and the decision-table over-row boundary have diverged (the gap interval " +
                "between them is no longer empty). Keep both derived from NodeWorkflowDefinitions.V1ApprovalThreshold.");
        }
    }

    /// <summary>
    /// The endpoints pin the strictly-above semantics directly: $5000.00 exactly is DIRECT (auto-approve);
    /// the very next cent ($5000.01) is the first amount that requires approval.
    /// </summary>
    [Fact(DisplayName = "Finding 1: $5000.00 exactly is direct (auto-approve) on BOTH the route and the table; $5000.01 is the first require-approval amount on BOTH")]
    public void StrictlyAboveSemantics_AreSharedByBothEncodings()
    {
        var table = NodeWorkflowDefinitions.InvoiceApprovalThresholdTable();

        // Exactly at the threshold → DIRECT on both.
        Assert.False(NodeInvoiceApprovalCutover.ShouldRouteToEngine(InvoiceWithTotal(Threshold)));
        Assert.Equal(ApprovalDecision.AutoApprove, table.EvaluatePinned(PinnedVersion, Threshold).Decision);

        // The very next representable cent → REQUIRE APPROVAL on both.
        var firstOver = Threshold + 0.01m;
        Assert.True(NodeInvoiceApprovalCutover.ShouldRouteToEngine(InvoiceWithTotal(firstOver)));
        Assert.Equal(ApprovalDecision.RequireApproval, table.EvaluatePinned(PinnedVersion, firstOver).Decision);
    }

    // ── Helper: a minimal Draft invoice whose Total is the amount under test ──────
    // Mirrors InvoiceRoutes' own Invoice.Create / InvoiceLine.Create construction. A single line at
    // qty 1 × unitPrice `total` (no tax) → Invoice.Total == total — the only field ShouldRouteToEngine reads.
    private static Invoice InvoiceWithTotal(decimal total)
    {
        var invoiceId = new InvoiceId(Guid.NewGuid().ToString("N"));
        var line = InvoiceLine.Create(
            invoiceId:       invoiceId,
            lineNumber:      1,
            description:     "Consulting",
            quantity:        1m,
            unitPrice:       total,
            incomeAccountId: new GLAccountId("4000"));
        return Invoice.Create(
            tenantId:      new TenantId("arch-test"),
            chartId:       new ChartOfAccountsId("CH-1"),
            invoiceNumber: "INV-2026-03-01-AA-0001",
            customerId:    new PartyId("customer-1"),
            issueDate:     new DateOnly(2026, 3, 1),
            dueDate:       new DateOnly(2026, 3, 31),
            lines:         new[] { line },
            arAccountId:   new GLAccountId("1100"),
            id:            invoiceId,
            createdAtUtc:  new Instant(System.TimeProvider.System.GetUtcNow()));
    }
}

using System.Runtime.CompilerServices;
using System.Text.RegularExpressions;

namespace Harborline.Api.LocalNodeHost.Tests.ArchTests;

/// <summary>
/// DES-0029 kernel-core-ck-6: a journal row reaches the node database only through the Platform
/// <c>KernelTransactionBoundary</c> port, whose <c>CommitAsync</c> is the one journal commit point. Workflow
/// effects join that port through the enclosing workflow boundary and never stage a journal row themselves.
/// </summary>
public sealed class JournalKernelBoundaryArchTests
{
    private const string Port = "apps/local-node-host/Data/Financial/NodeJournalKernelTransactionPort.cs";
    private const string Store = "apps/local-node-host/Data/Financial/NodeEfJournalStore.cs";

    private static readonly Regex JournalStage = new(
        @"Set<JournalEntry>\(\)\s*\.\s*(?:Add|AddRange|Update|UpdateRange|Attach|Remove|RemoveRange)(?:Async)?\s*\(",
        RegexOptions.Compiled);

    private static readonly Regex CommitCall = new(
        @"\.\s*(?<call>(?:SaveChanges|BeginTransaction|UseTransaction|Commit|ExecuteUpdate|ExecuteDelete|ExecuteSql\w*|ExecuteNonQuery)(?:Async)?)\s*\(",
        RegexOptions.Compiled);

    [Fact]
    public void JournalRowsAreStagedOnlyByTheKernelPort()
    {
        Assert.Equal(
            [Port],
            ScanJournalStages(RepositoryRoot()));
    }

    [Fact]
    public void TheJournalStoreCommitsOnlyThroughTheKernelBoundaryPort()
    {
        var root = RepositoryRoot();
        var store = Source(root, Store);
        Assert.Contains("KernelTransactionBoundary.ExecutePreparedAsync(", store);
        Assert.Contains("new NodeJournalKernelTransactionPort(", store);
        Assert.Empty(CommitCall.Matches(store));

        // The port opens the single BEGIN IMMEDIATE fence in BeginAsync and saves and commits only in CommitAsync.
        var port = Source(root, Port);
        Assert.Contains("HomeEpochFenceTransaction.BeginAsync(", port);
        var commit = port[port.IndexOf("CommitAsync(CancellationToken", StringComparison.Ordinal)..];
        commit = commit[..commit.IndexOf("RollbackAsync(", StringComparison.Ordinal)];
        Assert.Equal(["SaveChangesAsync", "CommitAsync"], CommitCall.Matches(commit).Select(match => match.Groups["call"].Value).ToArray());
        Assert.Equal(2, CommitCall.Matches(port).Count);
    }

    [Fact]
    public void TheScanFindsAPlantedJournalWriteOutsideThePort()
    {
        var root = Path.Combine(Path.GetTempPath(), "ck6-journal-scan-" + Guid.NewGuid().ToString("N"));
        var planted = Path.Combine(root, "apps", "local-node-host", "Data", "Planted");
        Directory.CreateDirectory(planted);
        try
        {
            File.WriteAllText(Path.Combine(planted, "Writer.cs"),
                "sealed class Writer { void Go(DbContext c, JournalEntry e) { c.Set<JournalEntry>()\n.Add(e); /* c.Set<JournalEntry>().Add(e); */ } }");
            Assert.Equal(["apps/local-node-host/Data/Planted/Writer.cs"], ScanJournalStages(root));
        }
        finally
        {
            Directory.Delete(root, recursive: true);
        }
    }

    private static string[] ScanJournalStages(string root)
    {
        var host = Path.Combine(root, "apps", "local-node-host");
        return Directory.EnumerateFiles(host, "*.cs", SearchOption.AllDirectories)
            .Select(file => (File: file, Relative: Path.GetRelativePath(root, file).Replace('\\', '/')))
            .Where(item => !item.Relative.Split('/').Any(segment => segment is "tests" or "bin" or "obj" or "Migrations"))
            .Where(item => JournalStage.IsMatch(StripComments(File.ReadAllText(item.File))))
            .Select(item => item.Relative)
            .Order(StringComparer.Ordinal)
            .ToArray();
    }

    private static string Source(string root, string relative) =>
        StripComments(File.ReadAllText(Path.Combine(root, relative)));

    private static string StripComments(string source) => Regex.Replace(
        source,
        @"//.*?$|/\*.*?\*/",
        string.Empty,
        RegexOptions.Multiline | RegexOptions.Singleline);

    private static string RepositoryRoot([CallerFilePath] string file = "")
    {
        var directory = new DirectoryInfo(Path.GetDirectoryName(file)!);
        while (directory is not null)
        {
            if (Directory.Exists(Path.Combine(directory.FullName, "apps"))
                && Directory.Exists(Path.Combine(directory.FullName, "packages")))
                return directory.FullName;
            directory = directory.Parent;
        }
        throw new DirectoryNotFoundException();
    }
}

using System.Reflection;
using Harborline.Api.LocalNodeHost.Data;
using Xunit;

namespace Harborline.Api.LocalNodeHost.Tests.ArchTests;

/// <summary>
/// Council condition C3 (ADR 0114): no LINQ query in the fleet may project
/// <em>into</em> <c>lines_json</c> or <c>applications_json</c> columns by name.
/// </summary>
/// <remarks>
/// <para>
/// Projecting into a JSON column by string literal bypasses EF's value-converter
/// pipeline and produces provider-specific raw SQL. On SQLite the JSON functions
/// differ from Postgres's <c>jsonb</c> operators, so a query that works on Postgres
/// silently fails (or produces wrong results) on SQLite.
/// </para>
/// <para>
/// The constraint is: LINQ must never reference these column names as string
/// literals in <c>FromSqlRaw</c> / <c>ExecuteSqlRaw</c> / <c>HasFilter</c> calls
/// within the local-node-host assembly or any of its block-package dependencies.
/// Value-converter paths (the normal EF serialization flow) are exempted because
/// they produce portable parameterised queries.
/// </para>
/// <para>
/// If a new JSON column is added and its name must appear in raw SQL:
/// <list type="number">
///   <item>Add it to the <see cref="KnownAllowedRawJsonColumnRefs"/> set with a
///   justification comment explaining why the raw reference is safe.</item>
///   <item>Ensure the raw SQL is guarded by <c>Database.IsNpgsql()</c> so it
///   never runs on SQLite.</item>
/// </list>
/// </para>
/// </remarks>
public sealed class JsonProjectionConstraintTests
{
    /// <summary>
    /// Column names that ARE allowed in raw SQL strings because they are explicitly
    /// guarded by <c>Database.IsNpgsql()</c> at the call site.  Each entry here
    /// must have a corresponding inline comment in the guarded block explaining why
    /// the allowance is safe.
    /// </summary>
    private static readonly HashSet<string> KnownAllowedRawJsonColumnRefs =
    [
        // Add entries here ONLY when a raw SQL reference is genuinely necessary
        // and is strictly guarded by Database.IsNpgsql(). Format:
        //   "lines_json",  // guarded in FooEntityModule.Configure at line NN
    ];

    /// <summary>
    /// JSON column names that MUST NOT appear in raw SQL strings without a guard.
    /// Extend this list whenever a new JSON column is added to the local-node model.
    /// </summary>
    private static readonly string[] ProtectedJsonColumns =
    [
        "lines_json",
        "applications_json",
        "line_templates_json",
        "generated_invoices_json",
        "revision_vector_json",
    ];

    [Fact(DisplayName = "Ticket 257: the raw-JSON allowance list is empty, so no row of it can be vacuous")]
    public void KnownAllowedRawJsonColumnRefs_IsEmpty() =>
        Assert.True(KnownAllowedRawJsonColumnRefs.Count == 0,
            "KnownAllowedRawJsonColumnRefs skips a column name for the whole C3 scan, so a stale row "
            + "silently pre-authorises a future unguarded reference. Adding the first real row means "
            + "registering it in AllowListVacuityArchTests against a skip-list-bypassed discovery and "
            + "deleting this pin:\n  " + string.Join("\n  ", KnownAllowedRawJsonColumnRefs));

    [Fact(DisplayName = "C3: No unguarded LINQ projections into JSON columns in LocalNodeHost assembly")]
    public void NoUnguardedJsonColumnProjections_InLocalNodeHostAssembly()
    {
        var assembly = typeof(LocalNodeDbContext).Assembly;
        AssertNoRawJsonProjections(assembly);
    }

    [Fact(DisplayName = "C3: No unguarded LINQ projections into JSON columns in test assembly")]
    public void NoUnguardedJsonColumnProjections_InTestAssembly()
    {
        var assembly = typeof(JsonProjectionConstraintTests).Assembly;
        AssertNoRawJsonProjections(assembly);
    }

    // -----------------------------------------------------------------------
    // Implementation
    // -----------------------------------------------------------------------

    private static void AssertNoRawJsonProjections(Assembly assembly)
    {
        // Scan every embedded string resource in the IL for raw JSON column refs.
        // This is a heuristic — it catches FromSqlRaw / ExecuteSqlRaw / HasFilter
        // string literals baked into the assembly. It does NOT catch dynamic strings
        // constructed at runtime, but those are a separate code-review concern.
        var violations = new List<string>();

        foreach (var type in assembly.GetTypes())
        {
            // C3 targets APPLICATION LINQ code (FromSqlRaw / ExecuteSqlRaw / HasFilter
            // literals). Two classes of type legitimately embed JSON column NAMES as
            // string literals without being LINQ-into-JSON projections, and must be
            // excluded or the heuristic produces false positives:
            //
            //   1. EF migration types — `<Timestamp>_<Name>` + the model snapshot
            //      DECLARE columns by name (e.g. HasColumnName("lines_json")). That is
            //      schema metadata, not a query projecting into the column.
            //   2. Compiler-generated types — anonymous types (`<>f__AnonymousType…`)
            //      synthesize a ToString() that embeds their property names (the
            //      validation API's `Results.Ok(new { … })` objects), and other
            //      `[CompilerGenerated]` closures. These are not author-written SQL.
            //
            // Excluding them keeps C3 enforcing the real invariant (no raw JSON
            // projection in hand-written query code) without flagging migrations or
            // synthesized ToString members.
            if (IsExcludedFromC3Scan(type)) continue;

            foreach (var method in type.GetMethods(
                BindingFlags.Public | BindingFlags.NonPublic |
                BindingFlags.Static | BindingFlags.Instance |
                BindingFlags.DeclaredOnly))
            {
                var body = method.GetMethodBody();
                if (body is null) continue;

                // Read the IL bytes and extract string tokens. EF string literals
                // for column names appear as ldstr instructions (opcode 0x72) whose
                // operand is an RVA into the #US heap — but reflection doesn't give
                // us the US heap directly. Instead we use the module's ResolveString
                // on each metadata token found after 0x72 in the raw IL.
                var il = body.GetILAsByteArray();
                if (il is null) continue;

                for (int i = 0; i < il.Length - 4; i++)
                {
                    // 0x72 = ldstr, followed by 4-byte metadata token
                    if (il[i] != 0x72) continue;

                    var token = il[i + 1] | (il[i + 2] << 8) | (il[i + 3] << 16) | (il[i + 4] << 24);
                    string? str;
                    try
                    {
                        str = assembly.GetManifestResourceStream(token.ToString()) is null
                            ? method.Module.ResolveString(token)
                            : null;
                    }
                    catch
                    {
                        continue;
                    }

                    if (str is null) continue;

                    foreach (var col in ProtectedJsonColumns)
                    {
                        if (!str.Contains(col, StringComparison.OrdinalIgnoreCase)) continue;
                        if (KnownAllowedRawJsonColumnRefs.Contains(col)) continue;

                        violations.Add(
                            $"  {type.FullName}.{method.Name} contains raw reference to '{col}' in string literal: \"{Truncate(str, 120)}\"");
                    }
                }
            }
        }

        if (violations.Count > 0)
        {
            throw new InvalidOperationException(
                $"C3 violation — {violations.Count} unguarded raw JSON column reference(s) found in " +
                $"{assembly.GetName().Name}. Guard each with Database.IsNpgsql() or add to KnownAllowedRawJsonColumnRefs " +
                $"with a justification comment.\n\n" +
                string.Join("\n", violations));
        }
    }

    /// <summary>
    /// True when <paramref name="type"/> is one C3 must not scan: an EF migration
    /// type (column-name declarations are schema metadata) or a compiler-generated
    /// type (anonymous-type ToString / closures embed property names but are not
    /// author-written SQL).
    /// </summary>
    private static bool IsExcludedFromC3Scan(Type type)
    {
        // EF migration / model-snapshot types live under the *.Data.Migrations
        // namespace and declare columns by name. Not LINQ projections.
        if (type.Namespace is { } ns && ns.Contains(".Migrations", StringComparison.Ordinal))
        {
            return true;
        }

        // Compiler-generated types: anonymous types (`<>f__AnonymousType…`),
        // closures, iterator/async state machines. Their synthesized members embed
        // property names but contain no hand-written raw SQL.
        if (Attribute.IsDefined(type, typeof(System.Runtime.CompilerServices.CompilerGeneratedAttribute)))
        {
            return true;
        }

        // Belt-and-suspenders for anonymous types whose CompilerGenerated marker is
        // on a nesting boundary the reflection above may not surface.
        if (type.Name.StartsWith("<>", StringComparison.Ordinal))
        {
            return true;
        }

        return false;
    }

    private static string Truncate(string s, int max) =>
        s.Length <= max ? s : s[..max] + "…";
}

