    [Fact]
    public void ClosureKeysDropTheEnclosingMethodOrdinalAndKeepEveryReviewedDistinction()
    {
        // The enclosing-method ordinal renumbers when an unrelated member is added to the declaring
        // type — 151 s2 added one primary-constructor parameter to NodeHierarchyCompositeCoordinator
        // and every closure there moved 9 -> 10 — so keying the reviewed inventory on it makes the
        // fence stale for a reason no reviewer chose, on any host that compiles the tree.
        Assert.Equal(
            "N+<>c__DisplayClass_0.<Reparent>b__0(): System.Void",
            MethodSignatureSymbol.StableClosureNames("N+<>c__DisplayClass10_0.<Reparent>b__0(): System.Void"));
        Assert.Equal(
            MethodSignatureSymbol.StableClosureNames("N+<>c__DisplayClass9_0.<Reparent>b__0(): System.Void"),
            MethodSignatureSymbol.StableClosureNames("N+<>c__DisplayClass10_0.<Reparent>b__0(): System.Void"));

        // Scope ordinal, lambda ordinal and the owning method name all survive.
        Assert.NotEqual(
            MethodSignatureSymbol.StableClosureNames("N+<>c__DisplayClass9_0.<M>b__0(): System.Void"),
            MethodSignatureSymbol.StableClosureNames("N+<>c__DisplayClass9_1.<M>b__0(): System.Void"));
        Assert.NotEqual(
            MethodSignatureSymbol.StableClosureNames("N+<>c.<M>b__9_0(): System.Void"),
            MethodSignatureSymbol.StableClosureNames("N+<>c.<M>b__9_1(): System.Void"));
        Assert.NotEqual(
            MethodSignatureSymbol.StableClosureNames("N+<>c.<A>b__9_0(): System.Void"),
            MethodSignatureSymbol.StableClosureNames("N+<>c.<B>b__9_0(): System.Void"));
    }

    [Fact]
    public void SignatureKeysDistinguishCallerOverloadsGenericTargetsAndSiblingLambdas()
    {
        var found = DiscoverSignatureCases();
        var overloads = found.Where(site => site.Symbol.Contains(".OverloadedCaller(", StringComparison.Ordinal)).ToArray();
        Assert.Equal(2, overloads.Length);
        Assert.NotEqual(overloads[0].Symbol, overloads[1].Symbol);
        Assert.Equal(overloads[0].Target, overloads[1].Target);

        var genericTargets = found.Where(site => site.Symbol.Contains(".GenericTargets(", StringComparison.Ordinal)).ToArray();
        Assert.Equal(2, genericTargets.Length);
        Assert.NotEqual(genericTargets[0].Target, genericTargets[1].Target);

        var lambdas = found.Where(site => site.Symbol.Contains("<TwoLambdas>", StringComparison.Ordinal)).ToArray();
        Assert.Equal(2, lambdas.Length);
        Assert.Equal(2, lambdas.Select(site => site.Symbol).Distinct(StringComparer.Ordinal).Count());
        Assert.Equal(lambdas[0].Target, lambdas[1].Target);
    }

    [Fact]
    public void SignatureKeysDistinguishMethodsThatDifferOnlyByReturnType()
    {
        var assembly = AssemblyBuilder.DefineDynamicAssembly(
            new AssemblyName($"ReturnTypeSignatureProbe_{Guid.NewGuid():N}"),
            AssemblyBuilderAccess.Run);
        var typeBuilder = assembly.DefineDynamicModule("Probe").DefineType(
            "Probe.Target", TypeAttributes.Public | TypeAttributes.Abstract | TypeAttributes.Sealed);
        EmitRead(typeBuilder, typeof(int), static il => il.Emit(OpCodes.Ldc_I4_0));
        EmitRead(typeBuilder, typeof(string), static il => il.Emit(OpCodes.Ldnull));

        var keys = typeBuilder.CreateType()!
            .GetMethods(BindingFlags.Public | BindingFlags.Static | BindingFlags.DeclaredOnly)
            .Select(MethodSignatureSymbol.Format)
            .Order(StringComparer.Ordinal)
            .ToArray();

        Assert.Equal(["Probe.Target.Read(): System.Int32", "Probe.Target.Read(): System.String"], keys);

        static void EmitRead(TypeBuilder type, Type returnType, Action<ILGenerator> emitValue)
        {
            var method = type.DefineMethod(
                "Read", MethodAttributes.Public | MethodAttributes.Static, returnType, Type.EmptyTypes);
            var il = method.GetILGenerator();
            emitValue(il);
            il.Emit(OpCodes.Ret);
        }
    }

    [Fact]
    public void AsyncStateMachineMapsToItsExactOwnerSignature()
    {
        var site = Assert.Single(DiscoverSignatureCases(), site =>
            site.Symbol.Contains(".AsyncOwner(", StringComparison.Ordinal));
        var owner = typeof(SignatureCases).GetMethod(
            "AsyncOwner", BindingFlags.Static | BindingFlags.NonPublic)!;

        Assert.Equal(MethodSignatureSymbol.Format(owner), site.Symbol);
        Assert.DoesNotContain("MoveNext", site.Symbol, StringComparison.Ordinal);
    }

    [Fact]
    public void ReviewedTargetOverloadMatchesTheExactInventory()
    {
        var actual = Assert.Single(DiscoverSignatureCases(), site =>
            site.Symbol.Contains(".OverloadSubstitution(", StringComparison.Ordinal));
        var reviewed = typeof(SignatureTarget).GetMethod(
            nameof(SignatureTarget.Overloaded), BindingFlags.Static | BindingFlags.NonPublic,
            binder: null, types: [typeof(int)], modifiers: null)!;

        AssertExactInventory(
            [Key(actual with { Target = MethodSignatureSymbol.Format(reviewed) })], [actual]);
    }

    private static void AssertExactInventory(IEnumerable<string> expected, IEnumerable<CallSite> discovered)
    {
        var expectedRows = expected.Order(StringComparer.Ordinal).ToArray();
        var actualRows = discovered.Select(Key).Order(StringComparer.Ordinal).ToArray();
        Assert.True(expectedRows.SequenceEqual(actualRows, StringComparer.Ordinal),
            "Raw mutation call-site inventory mismatch:\n" + string.Join("\n", discovered.Select(Describe)));
    }

    private static string Key(CallSite site) => $"{site.Path}|{site.Symbol}|{site.Target}|{site.Ordinal}";
    private static string Describe(CallSite site) => $"{Key(site)} @ {site.Path}:{site.Line}";

    private static Assembly[] ProductionAssemblies() =>
    [
        typeof(IEntityMutationStore).Assembly,
        typeof(IBankAccountMutationRepository).Assembly,
        typeof(PackInstaller).Assembly,
        typeof(Harborline.Api.Foundation.Forms.AuthorizedFormDefinitionLifecycle).Assembly,
        typeof(Harborline.Api.Blocks.Workflow.Durable.AuthorizedWorkflowDefinitionLifecycle).Assembly,
        typeof(Harborline.Api.Foundation.Forms.Engine.FormEngine).Assembly,
        typeof(NodeEntityWriter).Assembly,
    ];

    private static CallSite[] DiscoverSignatureCases() => DiscoverCalls(
        [typeof(SignatureCases).Assembly],
        target => target.DeclaringType == typeof(SignatureTarget),
        type => IsNestedWithin(type, typeof(SignatureCases)));

    private static bool IsNestedWithin(Type candidate, Type owner)
    {
        for (var type = candidate; type is not null; type = type.DeclaringType)
            if (type == owner) return true;
        return false;
    }

    private static readonly HashSet<Type> Ports =
    [
        typeof(IEntityMutationStore),
        typeof(IBankAccountMutationRepository),
        typeof(IPackInstallMutationStore),
        typeof(IPackProjectionAdmissionStore),
        typeof(IHierarchyMutationStore),
        typeof(IHierarchyCompositeUnitOfWork),
    ];

    /// <summary>The raw mutation seams this inventory fences; ck-10's executor fence reuses them as sinks.</summary>
    internal static bool IsRawMutationSink(MethodBase target) =>
        IsRawMutationTarget(target, Ports) || IsRawGrantRevocationTarget(target);

    private static CallSite[] Discover(IEnumerable<Assembly> assemblies, Func<Type, bool>? typeFilter = null) =>
        DiscoverCalls(assemblies, IsRawMutationSink, typeFilter);

    private static bool IsRawGrantRevocationTarget(MethodBase target) =>
        target.Name == nameof(IGrantStore.RevokeAsync)
        && target.DeclaringType is { } declaring
        && (declaring == typeof(IGrantStore) || typeof(IGrantStore).IsAssignableFrom(declaring));

    internal static CallSite[] DiscoverCalls(
        IEnumerable<Assembly> assemblies,
        Func<MethodBase, bool> targetPredicate,
        Func<Type, bool>? typeFilter = null)
    {
        ArgumentNullException.ThrowIfNull(assemblies);
        ArgumentNullException.ThrowIfNull(targetPredicate);
        var found = new List<CallSite>();
        var ordinals = new Dictionary<(string Caller, string Target), int>();
        foreach (var assembly in assemblies.Distinct())
        {
            foreach (var type in assembly.GetTypes().Where(type => typeFilter?.Invoke(type) ?? true))
            foreach (var caller in DeclaredMethods(type))
            {
                var callerSymbol = MethodSignatureSymbol.ForCaller(caller);
                foreach (var call in CalledMethods(caller))
                {
                    if (!targetPredicate(call.Target))
                        continue;
                    var target = MethodSignatureSymbol.Format(call.Target);
                    var ordinalKey = (callerSymbol, target);
                    ordinals.TryGetValue(ordinalKey, out var ordinal);
                    ordinals[ordinalKey] = ordinal + 1;
                    var source = SourceLocation(caller, call.Offset);
                    found.Add(new CallSite(source.Path, callerSymbol, source.Line, target, ordinal));
                }
            }
        }
        return found.OrderBy(Key, StringComparer.Ordinal).ToArray();
    }

    private static bool IsRawMutationTarget(MethodBase target, IReadOnlySet<Type> ports)
    {
        if (target is not MethodInfo method || method.DeclaringType is not { } declaring)
            return false;
        if (ports.Contains(declaring))
            return true;
        foreach (var port in ports.Where(port => port.IsAssignableFrom(declaring)))
        {
            var map = declaring.GetInterfaceMap(port);
            for (var index = 0; index < map.TargetMethods.Length; index++)
                if (map.TargetMethods[index] == method && map.InterfaceMethods[index].DeclaringType == port)
                    return true;

            // Ticket 366 slice 1: a store may implement a port member EXPLICITLY and keep a same-signature
            // member of its own for the assemblies the port's internal seam is visible to. That member is
            // not in the interface map, so match it by signature too — otherwise a direct concrete-type
            // raw write would leave the fence's inventory (the planted offender proves it does not).
            if (port.GetMethods(BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)
                .Any(declared => declared.Name == method.Name && SameParameters(declared, method)))
                return true;
        }
        return false;
    }

    private static bool SameParameters(MethodInfo left, MethodInfo right)
    {
        var a = left.GetParameters();
        var b = right.GetParameters();
        return a.Length == b.Length
            && a.Zip(b).All(pair => pair.First.ParameterType == pair.Second.ParameterType);
    }

    private static IEnumerable<MethodBase> DeclaredMethods(Type type) =>
        type.GetMethods(BindingFlags.Instance | BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic)
            .Cast<MethodBase>()
            .Concat(type.GetConstructors(BindingFlags.Instance | BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic));

    private static (string Path, int Line) SourceLocation(MethodBase method, int ilOffset)
    {
        var pdbPath = Path.ChangeExtension(method.Module.Assembly.Location, ".pdb");
        using var stream = File.OpenRead(pdbPath);
        using var provider = MetadataReaderProvider.FromPortablePdbStream(stream);
        var reader = provider.GetMetadataReader();
        var handle = (MethodDefinitionHandle)MetadataTokens.Handle(method.MetadataToken);
        var debug = reader.GetMethodDebugInformation(handle);
        SequencePoint? selected = null;
        foreach (var point in debug.GetSequencePoints())
        {
            if (!point.IsHidden && point.Offset <= ilOffset)
                selected = point;
        }
        Assert.True(selected.HasValue, $"No portable-PDB source point for {method} at IL_{ilOffset:x4}.");
        var pointValue = selected!.Value;
        var documentHandle = pointValue.Document.IsNil ? debug.Document : pointValue.Document;
        var relative = Audit.AuditAppendSymbolInventory.NormalizeFile(
            reader.GetString(reader.GetDocument(documentHandle).Name));
        return (relative, pointValue.StartLine);
    }

    internal static IEnumerable<(MethodBase Target, int Offset)> CalledMethods(MethodBase method)
    {
        var il = method.GetMethodBody()?.GetILAsByteArray();
        if (il is null)
            yield break;
        var position = 0;
        while (position < il.Length)
        {
            var instructionOffset = position;
            OpCode opCode;
            var first = il[position++];
            if (first == 0xfe)
                opCode = MultiByteOpCodes[il[position++]];
            else
                opCode = SingleByteOpCodes[first];
            if (opCode.OperandType == OperandType.InlineMethod)
            {
                var token = BitConverter.ToInt32(il, position);
                MethodBase? target = null;
                try
                {
                    target = method.Module.ResolveMethod(token, method.DeclaringType?.GetGenericArguments(),
                        method is MethodInfo info ? info.GetGenericArguments() : null);
                }
                catch (ArgumentException) { }
                if (target is not null)
                    yield return (target, instructionOffset);
            }
            position += OperandSize(opCode.OperandType, il, position);
        }
    }

    private static int OperandSize(OperandType operandType, byte[] il, int position) => operandType switch
    {
        OperandType.InlineNone => 0,
        OperandType.ShortInlineBrTarget or OperandType.ShortInlineI or OperandType.ShortInlineVar => 1,
        OperandType.InlineVar => 2,
        OperandType.InlineI or OperandType.InlineBrTarget or OperandType.InlineField or
            OperandType.InlineMethod or OperandType.InlineSig or OperandType.InlineString or
            OperandType.InlineTok or OperandType.InlineType or OperandType.ShortInlineR => 4,
        OperandType.InlineI8 or OperandType.InlineR => 8,
        OperandType.InlineSwitch => 4 + (BitConverter.ToInt32(il, position) * 4),
        _ => throw new InvalidOperationException($"Unsupported IL operand {operandType}.")
    };

    private static readonly OpCode[] SingleByteOpCodes = BuildOpCodes(multiByte: false);
    private static readonly OpCode[] MultiByteOpCodes = BuildOpCodes(multiByte: true);

    private static OpCode[] BuildOpCodes(bool multiByte)
    {
        var result = new OpCode[256];
        foreach (var field in typeof(OpCodes).GetFields(BindingFlags.Public | BindingFlags.Static))
        {
            var opCode = (OpCode)field.GetValue(null)!;
            if ((opCode.Size == 2) == multiByte)
                result[opCode.Value & 0xff] = opCode;
        }
        return result;
    }

    private sealed class ConcretePlantedOffender(
        InMemoryEntityStore entities,
        InMemoryHierarchyService hierarchy,
        NodeEfBankAccountRepository bankAccounts,
        DurablePackInstallStore packs,
        IGrantStore grants)
    {
        public Task<EntityId> Entity(
            SchemaId schema, System.Text.Json.JsonDocument body, CreateOptions options, CancellationToken cancellationToken) =>
            entities.CreateAsync(schema, body, options, cancellationToken);

        public Task<EntityEdge> Hierarchy(
            EntityId child,
            EntityId parent,
            DateTimeOffset at,
            CancellationToken cancellationToken) =>
            hierarchy.AddEdgeAsync(child, parent, EdgeKind.ChildOf, at, null, cancellationToken);

        public Task Bank(BankAccount account, CancellationToken cancellationToken) =>
            bankAccounts.AddAsync(account, cancellationToken);

        public void Pack(PackInstallTransaction transaction) => packs.Commit(transaction);

        public Task<AccessGrant?> Grant(
            TenantId tenant,
            GrantId grant,
            GrantRevocation revocation,
            CancellationToken cancellationToken) =>
            grants.RevokeAsync(tenant, grant, revocation, cancellationToken);

        public void TwoCallsToSameTarget(EntityId entity)
        {
            _ = entities.DeleteAsync(entity, new DeleteOptions(new ActorId("actor")), default);
            _ = entities.DeleteAsync(entity, new DeleteOptions(new ActorId("actor")), default);
        }
    }

    private static class SignatureCases
    {
        private static void OverloadedCaller(int value) => SignatureTarget.SameTarget();
        private static void OverloadedCaller(string value) => SignatureTarget.SameTarget();

        private static void GenericTargets()
        {
            SignatureTarget.Generic<int>();
            SignatureTarget.Generic<string>();
        }

        private static void TwoLambdas()
        {
            Action first = () => SignatureTarget.SameTarget();
            Action second = () => SignatureTarget.SameTarget();
            first();
            second();
        }

        private static async Task AsyncOwner()
        {
            await Task.Yield();
            SignatureTarget.SameTarget();
        }

        private static void OverloadSubstitution() => SignatureTarget.Overloaded(1);
    }

    private static class SignatureTarget
    {
        internal static void SameTarget() { }
        internal static void Generic<T>() { }
        internal static void Overloaded(int value) { }
        internal static void Overloaded(string value) { }
    }
}

using System.Reflection;

using Harborline.Api.Foundation.Assets.Entities;
using Harborline.Api.LocalNodeHost.Data.Entities;

namespace Harborline.Api.LocalNodeHost.Tests.ArchTests;

/// <summary>
/// Ticket 151 slice 2 (judge), narrowed by ticket 366 slice 1 — the bypass fence's discovery and its
/// allow-list, now covering only what the type system cannot.
/// <para>
/// RW-9 on the RECORD seam is held by <see cref="ValidatedRecordBody"/>: that seam takes a token only its
/// own mint can produce, so a record write that skips the gate or the validator does not compile and needs
/// no row here. What remains is the store's RAW (internal) seam, reachable only by the assemblies that own
/// a NON-record write shape. Row 6 of <c>RecordWriteValidationJudgeTests</c> is therefore: every raw-seam
/// call site is one of the named envelope writers below, and the exception list is empty. It lives in this
/// namespace so <see cref="AllowListVacuityArchTests"/>'s by-type coverage scan sees it.
/// </para>
/// </summary>
internal static class RecordWriteValidatedWriterFence
{
    /// <summary>
    /// The writers permitted to reach the entity store's RAW create/update seam (path prefixes of the call
    /// site). Every row is a <b>non-record envelope writer</b> — an RW-8 shape. The body is a definition
    /// envelope or a form instance, not a record, so the RECORD validator deliberately does not run on
    /// them; each keeps its own admission, named per row. A record writer can no longer be added to this
    /// block even by mistake: ticket 366 slice 1 made the raw seam internal to exactly these assemblies,
    /// and the record writers (NodeEntityWriter, NodeHierarchyCompositeCoordinator) now reach the token
    /// seam instead — their two rows were deleted with that change because the type makes those call sites
    /// impossible.
    /// </summary>
    internal static readonly string[] ValidatedWriters =
    [
        // Body is a serialized DEFINITION envelope on a lifecycle status transition; admitted by the
        // definition lifecycle's own allowed-from transition guard, which a record schema cannot express.
        "packages/foundation/Definitions/EntityStoreDefinitionLifecycle.cs",
        // Body is a serialized WORKFLOW DEFINITION envelope (EntityStoreWorkflowDefinitionStore
        // .SerializeEnvelope) under its own conflict + authorization admission; not a record body.
        "packages/blocks-workflow/src/durable/AuthorizedWorkflowDefinitionLifecycle.cs",
        // Body is a serialized FORM DEFINITION envelope, admitted by the forms definition path (frozen
        // definition + lineage checks, FormDefinitionValidationException); form INSTANCES are validated
        // against their own form schema by that path, never by the record validator.
        "packages/foundation-forms/AuthorizedFormDefinitionLifecycle.cs",
    ];

    /// <summary>Rule 12: the per-call-site exception list, held empty. A row here needs a named reason.</summary>
    internal static readonly string[] ExceptionRows = [];

    /// <summary>Every production call site of <see cref="IEntityMutationStore"/> create/update.</summary>
    internal static string[] DiscoveredRecordWriteCallers() =>
        RawMutationPortSymbolInventoryTests.DiscoverCalls(
            [
                typeof(IEntityMutationStore).Assembly,
                typeof(NodeEntityWriter).Assembly,
                typeof(Harborline.Api.Foundation.Forms.AuthorizedFormDefinitionLifecycle).Assembly,
                typeof(Harborline.Api.Blocks.Workflow.Durable.AuthorizedWorkflowDefinitionLifecycle).Assembly,
            ],
            IsRecordWrite)
        .Select(site => $"{site.Path}|{site.Symbol}")
        .Distinct(StringComparer.Ordinal)
        .Order(StringComparer.Ordinal)
        .ToArray();

    /// <summary>
    /// The store's RAW seam only (ticket 366 slice 1): a create/update whose body is a
    /// <see cref="System.Text.Json.JsonDocument"/>. The token overloads are excluded because
    /// <see cref="ValidatedRecordBody"/> already proves what a row here would assert.
    /// </summary>
    private static bool IsRecordWrite(MethodBase target)
    {
        if (target is not MethodInfo method || method.DeclaringType is not { } declaring) return false;
        if (method.Name is not (nameof(IEntityMutationStore.CreateAsync)
            or nameof(IEntityMutationStore.UpdateAsync)
)) return false;
        if (!method.GetParameters().Any(p => p.ParameterType == typeof(System.Text.Json.JsonDocument)))
            return false;
        return declaring == typeof(IEntityMutationStore)
            || typeof(IEntityMutationStore).IsAssignableFrom(declaring);
    }
}

using System.Reflection;
using Harborline.Api.LocalNodeHost.BackupRestore;
using Harborline.Api.LocalNodeHost.Tests.Audit;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;

namespace Harborline.Api.LocalNodeHost.Tests.ArchTests;

/// <summary>Ticket 292: one grant redemption owner and no retired opaque-string restore contract.</summary>
public sealed class RehostGrantBoundaryArchTests
{
    [Fact]
    public void OnlyNodeRehostServiceRedeemsGrants()
    {
        // Discover compiled calls (including concrete calls, aliases and async state machines).
        // Exact equality makes both a second caller and deletion of the real caller fail.
        var site = Assert.Single(AuditAppendSymbolInventory.Discover(ClassifyRedemption));
        Assert.Equal("apps/local-node-host/BackupRestore/NodeRehostService.cs", site.File);
        Assert.Equal(MethodSignatureSymbol.Format(
            typeof(NodeRehostService).GetMethod(nameof(NodeRehostService.RestoreAsync))!), site.Symbol);
        Assert.Equal(128, site.Line); // Manual restore: redemption precedes every recovery/write port.
    }

    private static string? ClassifyRedemption(MethodBase method) =>
        method.Name == nameof(IRosterRehostGrantProvider.RedeemAsync)
        && method.DeclaringType is { } owner
        && typeof(IRosterRehostGrantProvider).IsAssignableFrom(owner)
            ? "rehost-redemption" : null;

    [Fact]
    public void RetiredOpaqueGrantContractCannotReturn()
    {
        var root = AuditAppendSymbolInventory.RepositoryRoot();
        var offenders = ProductionSources(root).SelectMany(file =>
            CSharpSyntaxTree.ParseText(File.ReadAllText(file)).GetRoot().DescendantTokens()
                .Where(token => token.ValueText is "RosterSignedGrant" or "rosterSignedGrant"
                    or "ReplicaRestoreCoordinator" or "IReplicaRehostSource")
                .Select(token => $"{Path.GetRelativePath(root, file).Replace('\\', '/')}:{token.GetLocation().GetLineSpan().StartLinePosition.Line + 1}: {token.ValueText}"))
            .ToArray();
        Assert.True(offenders.Length == 0,
            "Retired restore symbols accept an unverified string grant:\n" + string.Join("\n", offenders));

        // Also reject renamed plain-string grant inputs on re-host types. Resolve the parameter
        // type so System.String and using aliases cannot evade this boundary.
        var envelopeInputs = 0;
        foreach (var file in ProductionSources(root))
        {
            var tree = CSharpSyntaxTree.ParseText(File.ReadAllText(file));
            var inputs = tree.GetRoot().DescendantNodes().OfType<ParameterSyntax>()
                .Where(parameter => parameter.Identifier.ValueText.Contains("grant", StringComparison.OrdinalIgnoreCase)
                    && parameter.Ancestors().OfType<TypeDeclarationSyntax>().Any(type =>
                        type.Identifier.ValueText.Contains("rehost", StringComparison.OrdinalIgnoreCase)))
                .ToArray();
            if (inputs.Length == 0) continue;
            var model = CSharpCompilation.Create("RehostStringInputs", [tree],
                [MetadataReference.CreateFromFile(typeof(object).Assembly.Location)])
                .GetSemanticModel(tree);
            foreach (var input in inputs)
            {
                if (input.Type is null || model.GetTypeInfo(input.Type).Type?.SpecialType != SpecialType.System_String)
                    continue;
                // This one transport envelope stores bytes; it neither admits nor redeems a grant.
                Assert.Equal("apps/local-node-host/BackupRestore/NodeRehostService.cs",
                    Path.GetRelativePath(root, file).Replace('\\', '/'));
                Assert.Equal(nameof(RosterSignedRehostGrant),
                    input.Ancestors().OfType<TypeDeclarationSyntax>().First().Identifier.ValueText);
                Assert.Equal(nameof(RosterSignedRehostGrant.SerializedGrant), input.Identifier.ValueText);
                envelopeInputs++;
            }
        }
        Assert.Equal(1, envelopeInputs);
    }

    private static IEnumerable<string> ProductionSources(string directory)
    {
        foreach (var file in Directory.EnumerateFiles(directory, "*.cs")) yield return file;
        foreach (var child in Directory.EnumerateDirectories(directory))
        {
            // Prune before descending so nested worktrees, dependencies and build output are never read.
            if (Path.GetFileName(child) is "tests" or "test" or "bin" or "obj"
                or "node_modules" or "artifacts" || Path.GetFileName(child).StartsWith('.')) continue;
            foreach (var file in ProductionSources(child)) yield return file;
        }
    }
}

using System.Runtime.CompilerServices;
using System.Text.RegularExpressions;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;

namespace Harborline.Api.LocalNodeHost.Tests.ArchTests;

/// <summary>
/// ADR-0163 AM-16 G1 and AM-17 residual fences. The admission-less PEP state is safe only while
/// stale/own roster rows are the sole rows that can disappear, and while subject erasure remains
/// outside the roster store.
/// </summary>
public sealed class RosterAuthorizationBoundaryArchTests
{
    private static readonly Regex RosterRecordMutation = new(
        @"\.\s*(?<method>RemoveRange|Remove|ExecuteDelete(?:Async)?|ExecuteSql(?:Raw|Interpolated)?(?:Async)?|FromSql(?:Raw|Interpolated)?(?:Async)?)\s*\(",
        RegexOptions.Compiled);

    private static readonly Regex RawSqlCall = new(
        @"\.\s*(?:ExecuteSql(?:Raw|Interpolated)?|FromSql(?:Raw|Interpolated)?)(?:Async)?\s*\(",
        RegexOptions.Compiled);

    [Theory]
    [InlineData(true)]
    [InlineData(false)]
    public void GenesisReadExemptionIgnoresSourceFormatting(bool moveLine)
    {
        var root = NodeHostProjectRoot();
        var file = Path.Combine(root, "Data", "Roster", "VerifiedTenantRosterReader.cs");
        var source = File.ReadAllText(file);
        var formatted = moveLine ? "\n" + source : source.Replace("            $", "\t$");
        Assert.False(HasRosterRawSql(RosterFenceSource(file, root, formatted)));
    }

    [Fact(DisplayName = "AM-16/G1: NodeRosterRecord deletion has one owner and two scoped predicates")]
    public void NodeRosterRecord_Deletion_Is_Only_Scoped_In_RosterProjection()
    {
        var root = NodeHostProjectRoot();
        var projectionPath = Path.Combine(root, "Data", "Roster", "RosterCrdtProjection.cs");
        var mutations = EnumerateProductionSource(root)
            .SelectMany(file => RosterRecordMutations(file, root))
            .ToArray();
        var rawSql = EnumerateProductionSource(root)
            .Where(file => HasRosterRawSql(RosterFenceSource(file, root)))
            .Select(file => Path.GetRelativePath(root, file))
            .ToArray();

        Assert.Empty(rawSql);
        Assert.Equal(2, mutations.Length);
        Assert.All(mutations, mutation => Assert.Equal(
            Path.GetRelativePath(root, projectionPath), mutation.RelativePath));
        Assert.All(mutations, mutation => Assert.True(
            HasTeamScope(mutation.Source, mutation.Index),
            $"Roster mutation '{mutation.Method}' at index {mutation.Index} is not scoped to a non-active team."));

        var projection = File.ReadAllText(projectionPath);
        var projectionCode = CodeOnly(projection);
        Assert.Contains(".Where(r => r.TeamId == ownTeamIdString)", projectionCode);
        Assert.Contains(".Where(row => staleRecordIds.Contains(row.Id))", projectionCode);

        // The stale-genesis predicate is record-id based, so its source set must prove the row's
        // team differs from the current/active team before it can reach RemoveRange.
        Assert.Contains("recordTeamId == currentTeamId", projectionCode);
    }

    [Fact(DisplayName = "AM-16/G1: an unscoped NodeRosterRecord delete is rejected by the fence")]
    public void Unscoped_Delete_Is_Not_Accepted_By_The_Fence()
    {
        const string plantedUnscopedDelete =
            "var rows = await ctx.Set<NodeRosterRecord>().ToListAsync(); ctx.Set<NodeRosterRecord>().RemoveRange(rows);";
        const string plantedScopedDelete =
            "var rows = await ctx.Set<NodeRosterRecord>().Where(r => r.TeamId == ownTeamId).ToListAsync(); " +
            "ctx.Set<NodeRosterRecord>().RemoveRange(rows);";

        const string plantedExecuteDelete =
            "var rows = ctx.Set<NodeRosterRecord>(); rows.ExecuteDeleteAsync();";
        const string plantedExecuteDeleteSync =
            "var rows = ctx.Set<NodeRosterRecord>(); rows.ExecuteDelete();";
        const string plantedBareRemove =
            "NodeRosterRecord row = GetRow(); ctx.Remove(row);";
        const string plantedRosterSql =
            "ctx.Database.ExecuteSqlRaw(\"DELETE FROM roster_records WHERE team_id = 'x'\");";

        Assert.True(RosterRecordMutationsIn(plantedUnscopedDelete).Count == 1);
        Assert.False(HasTeamScope(plantedUnscopedDelete, RosterRecordMutationsIn(plantedUnscopedDelete)[0].Index));
        Assert.True(RosterRecordMutationsIn(plantedScopedDelete).Count == 1);
        Assert.True(HasTeamScope(plantedScopedDelete, RosterRecordMutationsIn(plantedScopedDelete)[0].Index));
        Assert.True(RosterRecordMutationsIn(plantedExecuteDelete).Count == 1);
        Assert.False(HasTeamScope(plantedExecuteDelete, RosterRecordMutationsIn(plantedExecuteDelete)[0].Index));
        Assert.True(RosterRecordMutationsIn(plantedExecuteDeleteSync).Count == 1);
        Assert.False(HasTeamScope(plantedExecuteDeleteSync, RosterRecordMutationsIn(plantedExecuteDeleteSync)[0].Index));
        Assert.True(RosterRecordMutationsIn(plantedBareRemove).Count == 1);
        Assert.False(HasTeamScope(plantedBareRemove, RosterRecordMutationsIn(plantedBareRemove)[0].Index));
        Assert.True(HasRosterRawSql(plantedRosterSql));
    }

    [Fact(DisplayName = "AM-17/WW-1: subject erasure never reaches the roster context")]
    public void SubjectErasure_Flow_Never_Touches_Roster_Context()
    {
        var root = NodeHostProjectRoot();
        // Composition roots are intentionally excluded: their DI registrations name the interface but do
        // not implement erasure. The implementation classes below are the surfaces that can reach a store.
        var erasureFlowFiles = EnumerateProductionSource(root)
            .Where(file =>
            {
                var code = CodeOnly(File.ReadAllText(file));
                return Regex.IsMatch(
                    code,
                    @"\bclass\s+\w+(?:\s*<[^>]+>)?\s*:\s*[^\r\n{]*(?:ISubjectErasurePropagator|ISubjectErasureService)\b");
            })
            .ToArray();

        Assert.NotEmpty(erasureFlowFiles);
        Assert.All(erasureFlowFiles, file =>
            Assert.DoesNotContain(
                "NodeLocalRosterDbContext",
                CodeOnly(File.ReadAllText(file)),
                StringComparison.Ordinal));
    }

    [Fact(DisplayName = "AM-17/WW-1: roster columns carry no subject-key encryption")]
    public void Roster_Columns_Have_No_SubjectKey_Encryption()
    {
        var root = NodeHostProjectRoot();
        var rosterRoot = Path.Combine(root, "Data", "Roster");
        var forbiddenMarkers = new[]
        {
            "SubjectKey",
            "SubjectScoped",
            "ISubjectFieldEncryptor",
            "IFieldEncryptor",
            "EncryptedField",
        };

        var rosterSources = Directory.EnumerateFiles(rosterRoot, "*.cs", SearchOption.AllDirectories)
            .Where(file => !file.Contains($"{Path.DirectorySeparatorChar}Migrations{Path.DirectorySeparatorChar}",
                StringComparison.OrdinalIgnoreCase))
            .ToArray();
        Assert.NotEmpty(rosterSources);
        foreach (var file in rosterSources)
        {
            var code = CodeOnly(File.ReadAllText(file));
            foreach (var marker in forbiddenMarkers)
            {
                Assert.DoesNotContain(marker, code, StringComparison.Ordinal);
            }
        }
    }

    [Fact(DisplayName = "AM-17 residual: supersession receives only a non-active own team id")]
    public void Supersession_Requires_OwnTeam_Different_From_JoinedTeam()
    {
        var root = NodeHostProjectRoot();
        var enrollment = CodeOnly(File.ReadAllText(
            Path.Combine(root, "Enrollment", "NodeWireEnrollmentClient.cs")));
        var guard = enrollment.IndexOf("ownTeamIdBeforeAdopt != plan.TeamId", StringComparison.Ordinal);
        var call = enrollment.IndexOf("SupersedeOwnTeamRecordsAsync(ownTeamIdBeforeAdopt", StringComparison.Ordinal);
        var adopt = enrollment.IndexOf("_roster.AdoptEnrollment(", StringComparison.Ordinal);

        Assert.True(guard >= 0, "The join path must reject an own-team id equal to the joined/active team.");
        Assert.True(call > guard, "Supersession must be dominated by the own-team != joined-team guard.");
        Assert.True(adopt > call, "The in-memory active-team switch must happen after supersession.");
    }

    private sealed record RosterMutation(string Source, int Index, string Method, string RelativePath);

    private static IReadOnlyList<RosterMutation> RosterRecordMutations(string file, string root)
    {
        var source = RosterFenceSource(file, root);
        if (!source.Contains("NodeRosterRecord", StringComparison.Ordinal)
            && !source.Contains("RosterRecords", StringComparison.Ordinal))
        {
            return [];
        }

        return RosterRecordMutationsIn(source)
            .Select(mutation => mutation with { Source = source, RelativePath = Path.GetRelativePath(root, file) })
            .ToArray();
    }

    private static IReadOnlyList<RosterMutation> RosterRecordMutationsIn(string source) =>
        RosterRecordMutation.Matches(source)
            .Select(match => new RosterMutation(source, match.Index, match.Groups["method"].Value, string.Empty))
            .ToArray();

    private static bool HasRosterRawSql(string source) =>
        RawSqlCall.IsMatch(source)
            && source.Contains("roster_records", StringComparison.OrdinalIgnoreCase);

    private static string RosterFenceSource(string file, string root, string? sourceOverride = null)
    {
        var source = sourceOverride ?? File.ReadAllText(file);
        if (Path.GetRelativePath(root, file).Replace('\\', '/') != "Data/Roster/VerifiedTenantRosterReader.cs")
            return CodeOnly(source);

        // Classified read, ticket 296: this exact file/symbol reads the existing append order.
        // Discover the call through Roslyn and require the complete parameterized SELECT, not a SQL prefix.
        // Any changed SQL, extra call, moved owner or deletion still fails the same production fence.
        var tree = CSharpSyntaxTree.ParseText(source);
        var read = Assert.Single(tree.GetRoot().DescendantNodes().OfType<InvocationExpressionSyntax>(),
            call => call.Expression.ToString() == "db.RosterRecords.FromSql");
        Assert.Equal("ReadGenesisAsync", read.Ancestors().OfType<MethodDeclarationSyntax>().First().Identifier.ValueText);
        Assert.Equal("db.RosterRecords.FromSql($\"SELECT * FROM roster_records WHERE team_id = {team} AND kind = 0 AND is_genesis = 1 ORDER BY rowid\")",
            string.Concat(read.DescendantTokens().Select(token => token.Text)));
        return CodeOnly(source.Remove(read.SpanStart, read.Span.Length));
    }

    private static bool HasTeamScope(string source, int mutationIndex)
    {
        var statementStart = Math.Max(
            Math.Max(source.LastIndexOf(';', mutationIndex), source.LastIndexOf('{', mutationIndex)),
            source.LastIndexOf('}', mutationIndex)) + 1;
        var statement = source[statementStart..mutationIndex];

        // A direct Remove(entity) has no predicate and is never accepted. Query-terminal deletes must
        // carry their team restriction in the same statement as the typed NodeRosterRecord expression.
        if (!statement.Contains("Set<NodeRosterRecord>()", StringComparison.Ordinal)
            && !statement.Contains("RosterRecords", StringComparison.Ordinal))
        {
            return false;
        }

        return IsRosterQuery(statement)
            && (HasTeamPredicate(statement) || HasTeamPredicate(PreviousStatement(source, statementStart)));
    }

    private static bool IsRosterQuery(string statement) =>
        statement.Contains("Set<NodeRosterRecord>()", StringComparison.Ordinal)
            || statement.Contains("RosterRecords", StringComparison.Ordinal);

    private static bool HasTeamPredicate(string statement) =>
        statement.Contains(".Where(", StringComparison.Ordinal)
            && (statement.Contains("TeamId ==", StringComparison.Ordinal)
                || statement.Contains("staleRecordIds.Contains", StringComparison.Ordinal));

    private static string PreviousStatement(string source, int beforeIndex)
    {
        var previousEnd = source.LastIndexOf(';', Math.Max(0, beforeIndex - 1));
        var previousStart = Math.Max(
            Math.Max(source.LastIndexOf(';', Math.Max(0, previousEnd - 1)),
                source.LastIndexOf('{', Math.Max(0, previousEnd - 1))),
            source.LastIndexOf('}', Math.Max(0, previousEnd - 1))) + 1;
        return previousEnd < 0 ? string.Empty : source[previousStart..previousEnd];
    }

    private static string CodeOnly(string source) => string.Join(
        Environment.NewLine,
        Regex.Replace(source, @"/\*.*?\*/", string.Empty, RegexOptions.Singleline)
            .Split(["\r\n", "\n"], StringSplitOptions.None)
            .Select(line =>
            {
                var comment = line.IndexOf("//", StringComparison.Ordinal);
                return comment < 0 ? line : line[..comment];
            }));

    private static string NodeHostProjectRoot([CallerFilePath] string thisFile = "")
    {
        var archTestsDir = Path.GetDirectoryName(thisFile)!;
        var testsDir = Path.GetDirectoryName(archTestsDir)!;
        var hostRoot = Path.GetDirectoryName(testsDir)!;
        Assert.True(
            File.Exists(Path.Combine(hostRoot, "Program.cs"))
                && File.Exists(Path.Combine(hostRoot, "LocalNodeOptions.cs")),
            $"Could not locate the node-host project root from '{thisFile}'.");
        return hostRoot;
    }

    private static IEnumerable<string> EnumerateProductionSource(string hostRoot) =>
        Directory.EnumerateFiles(hostRoot, "*.cs", SearchOption.AllDirectories)
            .Where(file =>
            {
                var relative = Path.GetRelativePath(hostRoot, file);
                var segments = relative.Split(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
                return !segments.Any(segment =>
                    segment.Equals("tests", StringComparison.OrdinalIgnoreCase)
                    || segment.Equals("bin", StringComparison.OrdinalIgnoreCase)
                    || segment.Equals("obj", StringComparison.OrdinalIgnoreCase)
                    || segment.Equals(".worktrees", StringComparison.OrdinalIgnoreCase));
            });
}

using System.Reflection;

using Harborline.Api.Foundation.IdentityAtlas;
using Harborline.Api.LocalNodeHost.Tests.Audit;

namespace Harborline.Api.LocalNodeHost.Tests.ArchTests;

/// <summary>
/// Ticket 293 slice 5 — NO production code reads a permission SET off the roster.
/// <para>
/// The M1 milestone exit test is that a search finds no production read of a roster member's permission
/// set. The reason is not tidiness: since slice 3b2 the roster wire record carries no permission set, so a
/// REPLICATED member has none. A production reader of <c>MemberRoster.PermissionsOf</c> therefore answers
/// the empty set for exactly the members it is asked about — silently, and in the fail-OPEN direction for
/// an audit row (it records "granted nothing") and the fail-CLOSED direction for a display (it blanks the
/// app). Slice 4 moved the answer to <c>AuthorizationGate</c> over the local grant store; the roster's
/// remaining contribution is membership and ejection, which are booleans and are welcome.
/// </para>
/// <para>
/// The fence discovers its inventory BY SYMBOL — the same IL walk over every shipped
/// <c>Harborline*.dll</c> that the audit-append and separation-of-duty fences use — so an alias, a local,
/// an extension-looking call or a reformat does not make a reader disappear. The allow-list has ZERO rows
/// and is registered in <see cref="AllowListVacuityArchTests"/>: there is no justified production reader,
/// and a row added to excuse one must name a call site the scan really finds.
/// </para>
/// </summary>
public sealed class RosterPermissionSetReadFenceTests
{
    private const string PermissionsOfMethod =
        "Harborline.Api.Foundation.IdentityAtlas.MemberRoster.PermissionsOf";
    private const string HasPermissionMethod =
        "Harborline.Api.Foundation.IdentityAtlas.MemberRoster.HasPermission";

    /// <summary>
    /// Production readers of a roster member's permission set, as <c>file|symbol|callee</c>. EMPTY, and
    /// intended to stay empty: what a party may do is the gate's answer over the grant store, and the
    /// roster answers only whether the party is a live member. A row here would be a decision taken
    /// outside the gate on data a replicated member does not carry.
    /// </summary>
    private static readonly Dictionary<string, string> ForbiddenRosterSetReaders = new(StringComparer.Ordinal);

    /// <summary>Allow-list rows, for the vacuity registry.</summary>
    internal static string[] ForbiddenRosterSetReaderRows() =>
        [.. ForbiddenRosterSetReaders.Keys.Order(StringComparer.Ordinal)];

    /// <summary>The scan with the allow-list bypassed, for the vacuity registry.</summary>
    internal static string[] DiscoveredRosterSetReads() => Sites.Value;

    // Cached: the vacuity registry re-runs each registered discovery many times across several threads.
    private static readonly Lazy<string[]> Sites = new(
        () => Discover(Classify),
        LazyThreadSafetyMode.ExecutionAndPublication);

    private static readonly Lazy<string[]> MembershipSites = new(
        () => Discover(method =>
            method.DeclaringType == typeof(MemberRoster) && method.Name == nameof(MemberRoster.Contains)
                ? "Harborline.Api.Foundation.IdentityAtlas.MemberRoster.Contains"
                : null),
        LazyThreadSafetyMode.ExecutionAndPublication);

    private static string[] Discover(Func<MethodBase, string?> classify) =>
        [.. AuditAppendSymbolInventory.Discover(classify)
            .Select(site => $"{site.File}|{site.Symbol}|{site.Kind}")
            .Distinct(StringComparer.Ordinal)
            .Order(StringComparer.Ordinal)];

    /// <summary>A read of the SIGNED set on a roster member. A membership or ejection predicate is not one.</summary>
    internal static string? Classify(MethodBase method) =>
        method.DeclaringType != typeof(MemberRoster)
            ? null
            : method.Name switch
            {
                "PermissionsOf" => PermissionsOfMethod,
                "HasPermission" => HasPermissionMethod,
                _ => null,
            };

    [Fact(DisplayName = "293 s5: no production code reads a permission set off the roster")]
    public void No_production_call_site_reads_a_roster_permission_set()
    {
        var offenders = Sites.Value.Where(site => !ForbiddenRosterSetReaders.ContainsKey(site)).ToArray();

        Assert.True(
            offenders.Length == 0,
            "Production code reads a roster member's permission SET. A replicated member carries none "
            + "(ticket 293 slice 3b2), so this answers the empty set for the members it is asked about. Ask "
            + "AuthorizationGate over the grant store instead, and take membership/ejection from "
            + "EffectiveMemberPermissions.Read. Offending sites:\n  " + string.Join("\n  ", offenders));
        Assert.Empty(ForbiddenRosterSetReaders);
    }

    [Fact(DisplayName = "293 s5: the roster set readers are not reachable from production at all")]
    public void The_roster_set_readers_are_internal_to_the_atlas()
    {
        // Belt to the fence's braces: the compiler keeps a production assembly from calling these at all.
        // Only the host test assembly sees them (InternalsVisibleTo), which is why this test can name them.
        foreach (var name in new[] { "PermissionsOf", "HasPermission" })
        {
            var method = typeof(MemberRoster).GetMethod(
                name, BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
            Assert.NotNull(method);
            Assert.False(method!.IsPublic, $"MemberRoster.{name} is public again; production can read the set.");
            Assert.True(method.IsAssembly, $"MemberRoster.{name} must be internal to the atlas assembly.");
        }
    }

    [Fact(DisplayName = "293 s5: the set-read scan is not vacuous — the same walk finds the membership predicate")]
    public void The_scan_resolves_roster_call_sites()
    {
        // Anti-vacuity. An empty offender list is only evidence if the walk can find a roster call at all;
        // if call-token resolution broke, the fence above would pass over nothing forever. MemberRoster
        // .Contains is the predicate production is SUPPOSED to use, so it must be found, and in numbers.
        Assert.NotEmpty(MembershipSites.Value);
        Assert.Contains(
            MembershipSites.Value,
            site => site.Contains("EffectiveMemberPermissions", StringComparison.Ordinal));
    }

    [Fact(DisplayName = "293 s5: a planted production set read is rejected")]
    public void A_planted_set_read_is_rejected()
    {
        // The mutation the fence exists for, run in-test rather than committed, so it runs every build.
        const string planted =
            "apps/local-node-host/Health/WebSession/SelectedSessionIdentityRoutes.cs"
            + "|Harborline.Api.LocalNodeHost.Health.WebSession.SelectedSessionIdentityRoutes.PermissionsAsync()"
            + ": System.Threading.Tasks.Task`1[Microsoft.AspNetCore.Http.IResult]"
            + "|" + PermissionsOfMethod;

        var offenders = Sites.Value.Append(planted)
            .Where(site => !ForbiddenRosterSetReaders.ContainsKey(site)).ToArray();

        Assert.Equal([planted], offenders);
    }
}

using System.Text.RegularExpressions;

namespace Harborline.Api.LocalNodeHost.Tests.ArchTests;

/// <summary>
/// Keeps route-fence evidence inseparable from the filter that enforces the matching policy.
/// </summary>
public sealed class RouteFenceMetadataArchTests
{
    private static readonly HashSet<string> FenceHelperPaths = new(StringComparer.Ordinal)
    {
        Path.Combine("Health", "AdmissionWebPlaneRouteFence.cs"),
        Path.Combine("Health", "DeviceReachableProductDataRouteFence.cs"),
        Path.Combine("Health", "PreAuthOperationalRouteFence.cs"),
        Path.Combine("Health", "SelectedSessionProductRouteFence.cs"),
        Path.Combine("Health", "WebPlaneUnavailableRouteFence.cs"),
    };

    /// <summary>The fence-helper skip rows, for the ticket-257 vacuity property.</summary>
    internal static string[] FenceHelperPathRows() => [.. FenceHelperPaths.Order(StringComparer.Ordinal)];

    /// <summary>
    /// The same scan with the skip list BYPASSED: every host file that really performs a marker
    /// operation. A skip row that names nothing here is dead width pre-authorising a future file.
    /// </summary>
    internal static string[] DiscoveredMarkerOperationFiles() =>
        [.. ScanForMarkerOperationsOutsideFenceHelpers(skipFenceHelpers: false).Order(StringComparer.Ordinal)];

    private static readonly string MarkerDefinitionPath =
        Path.Combine("Health", "RouteFenceMetadata.cs");

    private static readonly Regex MarkerConstruction = new(
        @"new\s+RouteFenceMetadata\s*\(",
        RegexOptions.Compiled);

    private static readonly Regex MarkerStamp = new(
        @"(?:\.WithMetadata\s*(?:<\s*RouteFenceMetadata\b|\([^;]*\bRouteFenceMetadata\b)|" +
        @"\.Metadata\s*\.\s*Add\s*\([^;]*\bRouteFenceMetadata\b)",
        RegexOptions.Compiled | RegexOptions.Singleline);

    private static readonly Regex MarkerAlias = new(
        @"\busing\s+\w+\s*=\s*(?:global::)?(?:[\w.]+\.)?RouteFenceMetadata\s*;",
        RegexOptions.Compiled);

    private static readonly Regex MarkerPartialDeclaration = new(
        @"\bpartial\s+(?:class|record(?:\s+class)?)\s+RouteFenceMetadata\b",
        RegexOptions.Compiled);

    // Raw FilterFactories is fenced because ordering and removal on that list are the only
    // remaining ways to separate a stamped marker from the filter that enforces it. Ordinary
    // AddEndpointFilter usage remains unrestricted and composes inside the fence.
    private static readonly Regex RawFilterFactoriesReference = new(
        @"\bFilterFactories\b",
        RegexOptions.Compiled);

    [Fact(DisplayName = "Route-fence marker operations stay inside structural fence helpers")]
    public void MarkerOperations_ExistOnlyInFenceHelpers()
    {
        var offenders = ScanForMarkerOperationsOutsideFenceHelpers();

        Assert.True(
            offenders.Count == 0,
            "RouteFenceMetadata operations and raw FilterFactories references can only exist inside " +
            "the structural fence helper files. Move this endpoint into the matching Map*Group() " +
            "helper instead:\n  " + string.Join("\n  ", offenders));
    }

    [Fact(DisplayName = "Route-fence marker scanner still reports an offender")]
    public void MarkerOperations_Scanner_Still_Reports_An_Offender()
    {
        var root = Path.Combine(
            Path.GetTempPath(),
            "ticket-066-route-fence-arch-" + Guid.NewGuid().ToString("N"));
        var health = Path.Combine(root, "Health");
        Directory.CreateDirectory(health);
        try
        {
            File.WriteAllText(
                Path.Combine(health, "Offender.cs"),
                "var marker = new RouteFenceMetadata(RouteFenceKind.SelectedSessionProduct);");

            Assert.Equal(
                [Path.Combine("Health", "Offender.cs")],
                ScanForMarkerOperationsOutsideFenceHelpers(root));
        }
        finally
        {
            Directory.Delete(root, recursive: true);
        }
    }

    private static List<string> ScanForMarkerOperationsOutsideFenceHelpers(
        string? sourceRoot = null,
        bool skipFenceHelpers = true)
    {
        var hostRoot = sourceRoot ?? LocateHostSourceRoot();
        var excludedSegments = new[]
        {
            $"{Path.DirectorySeparatorChar}bin{Path.DirectorySeparatorChar}",
            $"{Path.DirectorySeparatorChar}obj{Path.DirectorySeparatorChar}",
            $"{Path.DirectorySeparatorChar}tests{Path.DirectorySeparatorChar}",
        };
        var offenders = new List<string>();

        foreach (var file in Directory.EnumerateFiles(hostRoot, "*.cs", SearchOption.AllDirectories))
        {
            var relativePath = Path.GetRelativePath(hostRoot, file);
            if (skipFenceHelpers && FenceHelperPaths.Contains(relativePath)) continue;
            if (excludedSegments.Any(segment => file.Contains(segment, StringComparison.Ordinal))) continue;

            var source = File.ReadAllText(file);
            var forbiddenPartial = relativePath != MarkerDefinitionPath &&
                MarkerPartialDeclaration.IsMatch(source);
            if (MarkerConstruction.IsMatch(source) ||
                MarkerStamp.IsMatch(source) ||
                MarkerAlias.IsMatch(source) ||
                forbiddenPartial ||
                RawFilterFactoriesReference.IsMatch(source))
            {
                offenders.Add(relativePath);
            }
        }

        return offenders;
    }

    private static string LocateHostSourceRoot()
    {
        var directory = new DirectoryInfo(AppContext.BaseDirectory);
        while (directory is not null)
        {
            var direct = Path.Combine(directory.FullName, "Harborline.LocalNodeHost.csproj");
            if (File.Exists(direct)) return directory.FullName;

            var nested = Path.Combine(
                directory.FullName,
                "apps",
                "local-node-host",
                "Harborline.LocalNodeHost.csproj");
            if (File.Exists(nested)) return Path.GetDirectoryName(nested)!;

            directory = directory.Parent;
        }

        throw new InvalidOperationException(
            "Could not locate the local-node-host source root from " + AppContext.BaseDirectory);
    }
}

namespace Harborline.Api.LocalNodeHost.Tests.ArchTests;

internal static class ScratchTree
{
    public static void Delete(string root)
    {
        if (!Directory.Exists(root)) return;

        foreach (var file in Directory.EnumerateFiles(root, "*", SearchOption.AllDirectories))
            File.SetAttributes(file, File.GetAttributes(file) & ~FileAttributes.ReadOnly);

        foreach (var directory in Directory.EnumerateDirectories(root, "*", SearchOption.AllDirectories)
                     .OrderByDescending(path => path.Length))
            File.SetAttributes(directory, File.GetAttributes(directory) & ~FileAttributes.ReadOnly);

        File.SetAttributes(root, File.GetAttributes(root) & ~FileAttributes.ReadOnly);
        Directory.Delete(root, recursive: true);
    }
}

