using Harborline.Api.Foundation.Assets.Common;
using Harborline.Api.Foundation.Authorization;
using Harborline.Api.Foundation.Authorization.SeparationOfDuty;
using Harborline.Api.Foundation.Crypto;
using Harborline.Api.Foundation.IdentityAtlas.Permissions;
using Harborline.Api.Kernel.Audit;

namespace Harborline.Api.LocalNodeHost.Tests.Audit;

/// <summary>
/// Ticket 272 slice 2 — the decision maps to the stored snapshot at its one seam,
/// <c>Harborline.Api.Kernel.Audit.AuthorizedAuditRecord.CopyFromDecision</c>.
/// <para>
/// The failure this pins is a refusal recorded as an approval. Before this slice the kernel-audit
/// <c>SeparationOfDutyResult</c> had only <c>Pass</c> and <c>Override</c>, so an unoverridden conflict — a
/// refused act — had no faithful spelling at all, and the refusal reason the engine decided had nowhere to
/// go. Every assertion below is on the record the seam returns, so it runs through
/// <c>AuthoritySnapshot.Copy</c> as the persisted value does.
/// </para>
/// </summary>
public sealed class ApprovalFactSnapshotMappingTests
{
    private static readonly TenantId Tenant = new("tenant-272-approval");
    private static readonly DateTimeOffset At = new(2026, 9, 6, 12, 0, 0, TimeSpan.Zero);
    private static readonly ApprovalPolicyFact Policy = new("policy-272", "v3");
    private static readonly ApprovalLimitSourceFact LimitSource =
        new(ApprovalLimitSourceKind.SigningLimitAgreement, "sla-9", "v2");

    [Fact(DisplayName = "A refused conflict is stored as Conflict with the reason it was refused for")]
    public async Task Refused_conflict_maps_to_Conflict_with_its_refusal_reason()
    {
        // The principal is among its own approvers and nothing overrides it: refused, outcome Conflict.
        var (record, decision, principal) = await AuthorizedAsync();
        var approval = Decide(principal, [new ApproverOnRecord(principal)]);
        Assert.False(approval.Approved);

        var stored = AuthorizedAuditRecord.CopyFromDecision(record, decision, approval);

        var sod = stored.AuthoritySnapshot!.SeparationOfDuty!;
        Assert.Equal(SeparationOfDutyResult.Conflict, sod.Result);
        Assert.Equal(AuthorityApprovalRefusalReason.SelfApproval, sod.RefusalReason);
        Assert.Null(sod.OverrideReason);
        Assert.Null(sod.OverrideApprover);
        // The other four approval facts are recorded on a refusal exactly as on an approval.
        Assert.Equal(new AuthorityPolicySnapshot("policy-272", "v3"), stored.AuthoritySnapshot.Policy);
        Assert.Equal(4200m, stored.AuthoritySnapshot.AppliedLimit);
        Assert.Equal(
            new AuthorityLimitSourceSnapshot(AuthorityLimitSourceKind.SigningLimitAgreement, "sla-9", "v2"),
            stored.AuthoritySnapshot.LimitSource);
        Assert.Equal(SeparationOfDutyEngine.OpenPostingPeriod, stored.AuthoritySnapshot.PostingPeriodState);
    }

    [Fact(DisplayName = "An overridden conflict is stored as Override with its reason and its overrider")]
    public async Task Override_maps_to_Override_with_reason_and_approver()
    {
        var (record, decision, principal) = await AuthorizedAsync();
        var approval = Decide(principal,
        [
            new ApproverOnRecord(principal),
            new ApproverOnRecord(
                new ActorId("party:controller"),
                "single-approver night close",
                ResolvedApprover: new ActorId("party:controller")),
        ]);
        Assert.True(approval.Approved);

        var stored = AuthorizedAuditRecord.CopyFromDecision(record, decision, approval);

        var sod = stored.AuthoritySnapshot!.SeparationOfDuty!;
        Assert.Equal(SeparationOfDutyResult.Override, sod.Result);
        Assert.Equal("single-approver night close", sod.OverrideReason);
        Assert.Equal("party:controller", sod.OverrideApprover);
        Assert.Equal(AuthorityApprovalRefusalReason.None, sod.RefusalReason);
    }

    [Fact(DisplayName = "A clean approval is stored as Pass with no refusal reason")]
    public async Task Pass_maps_to_Pass()
    {
        var (record, decision, _) = await AuthorizedAsync();
        var approval = Decide(
            new ActorId("party:preparer"), [new ApproverOnRecord(new ActorId("party:controller"))]);
        Assert.True(approval.Approved);

        var stored = AuthorizedAuditRecord.CopyFromDecision(record, decision, approval);

        var sod = stored.AuthoritySnapshot!.SeparationOfDuty!;
        Assert.Equal(SeparationOfDutyResult.Pass, sod.Result);
        Assert.Equal(AuthorityApprovalRefusalReason.None, sod.RefusalReason);
        Assert.Null(sod.OverrideReason);
        Assert.Null(sod.OverrideApprover);
    }

    [Fact(DisplayName = "A writer that carries no separation-of-duty decision records none of the five facts")]
    public async Task No_approval_decision_leaves_the_five_facts_null()
    {
        // Today's writers (slices 3 to 5 convert them) pass no approval decision. The seam must not invent
        // one: a fact absent from the decision is absent from the entry, never defaulted to a Pass.
        var (record, decision, _) = await AuthorizedAsync();

        var stored = AuthorizedAuditRecord.CopyFromDecision(record, decision);

        Assert.Null(stored.AuthoritySnapshot!.SeparationOfDuty);
        Assert.Null(stored.AuthoritySnapshot.Policy);
        Assert.Null(stored.AuthoritySnapshot.AppliedLimit);
        Assert.Null(stored.AuthoritySnapshot.LimitSource);
        Assert.Null(stored.AuthoritySnapshot.PostingPeriodState);
    }

    [Fact(DisplayName = "Every decided outcome and refusal reason has a stored spelling of the same name and value")]
    public void Every_member_of_both_decision_enums_has_a_faithful_stored_member()
    {
        // The compile-time half of this is the seam's default-arm-free switch expressions: a new member on
        // either decision enum fails the build (CS8509). This is the other half — that the audit enum the
        // switch maps INTO carries the same member under the same name and the same number, so a stored
        // entry read back years later means what the engine decided.
        AssertMirrored<SeparationOfDutyOutcome, SeparationOfDutyResult>();
        AssertMirrored<ApprovalRefusalReason, AuthorityApprovalRefusalReason>();
        AssertMirrored<ApprovalLimitSourceKind, AuthorityLimitSourceKind>();
    }

    private static void AssertMirrored<TDecided, TStored>()
        where TDecided : struct, Enum
        where TStored : struct, Enum
    {
        // Both directions (272 slice 2 review, MINOR-1): iterating only the decided enum leaves a stored
        // member with no decided counterpart invisible, and an unreachable stored spelling is a reader
        // hazard — it looks like a value the engine can produce.
        Assert.Equal(Enum.GetValues<TDecided>().Length, Enum.GetValues<TStored>().Length);

        foreach (var decided in Enum.GetValues<TDecided>())
        {
            var name = decided.ToString();
            Assert.True(
                Enum.TryParse<TStored>(name, ignoreCase: false, out var stored),
                $"{typeof(TStored).FullName} has no member named '{name}'; a decision the engine can make "
                + "would have no faithful stored spelling.");
            Assert.Equal(
                Convert.ToInt32(decided, System.Globalization.CultureInfo.InvariantCulture),
                Convert.ToInt32(stored, System.Globalization.CultureInfo.InvariantCulture));
        }
    }

    /// <summary>An engine decision over the given principal and approvers; every input is explicit.</summary>
    private static SeparationOfDutyDecision Decide(ActorId principal, ApproverOnRecord[] approvers) =>
        new SeparationOfDutyEngine().Decide(new SeparationOfDutyRequest(
            new PermissionAtom(
                AuthorizationOperation.Parse("records:write"), ScopeExpression.Parse("/records/audit-record")),
            principal,
            Tenant,
            approvers,
            new ApprovalThreshold(Policy, 4200m, RequiredApprovers: 1, LimitSource),
            SeparationOfDutyEngine.OpenPostingPeriod,
            At));

    /// <summary>The record and carried authorization decision the seam's own guards require.</summary>
    private static async Task<(AuditRecord Record, AuthorizationDecision Decision, ActorId Principal)>
        AuthorizedAsync()
    {
        using var keys = KeyPair.Generate();
        var signer = new Ed25519Signer(keys);
        var (decision, _) = await AuthoritySnapshotTests.DecisionAsync(signer, Tenant, At, ("grant-272", 1));
        var record = await AuthoritySnapshotTests.RecordAsync(signer, Tenant, At);
        return (record, decision, new ActorId(signer.IssuerId.ToBase64Url()));
    }
}

using System.Reflection;
using System.Reflection.Emit;
using System.Reflection.Metadata;
using System.Reflection.Metadata.Ecma335;
using System.Runtime.Loader;

using Harborline.Api.LocalNodeHost.Tests.ArchTests;

namespace Harborline.Api.LocalNodeHost.Tests.Audit;

internal enum AuditAppendKind
{
    Ordinary,
    Authorized,
    Refused,
    PackOrdinary,
    PackAuthorized,
}

/// <summary>One discovered call or construction site, anchored to a source line by the portable PDB.</summary>
internal sealed record SymbolCallSite(
    string Kind,
    string File,
    string Symbol,
    int Line,
    string CalledMethod,
    int Ordinal,
    string SourceMethod);

internal sealed record AuditAppendCallSite(
    AuditAppendKind Kind,
    string File,
    string Symbol,
    int Line,
    string CalledMethod,
    int Ordinal,
    string SourceMethod);

/// <summary>
/// Discovers the emitted calls to the two audit contracts. This deliberately inspects IL rather
/// than source tokens: aliases, unusual formatting, helper locals, and extension-looking syntax do
/// not make an appending writer disappear from the inventory. Portable-PDB sequence points anchor
/// every emitted call back to a source line for human-readable failure diagnostics.
/// </summary>
internal static class AuditAppendSymbolInventory
{
    private static readonly OpCode[] OneByte = new OpCode[0x100];
    private static readonly OpCode[] TwoByte = new OpCode[0x100];

    static AuditAppendSymbolInventory()
    {
        foreach (var field in typeof(OpCodes).GetFields(BindingFlags.Public | BindingFlags.Static))
        {
            if (field.GetValue(null) is not OpCode opcode) continue;
            var value = unchecked((ushort)opcode.Value);
            if (value < 0x100) OneByte[value] = opcode;
            else if ((value & 0xff00) == 0xfe00) TwoByte[value & 0xff] = opcode;
        }
    }

    internal static IReadOnlyList<AuditAppendCallSite> Discover() =>
        Discover(method => Classify(method)?.ToString())
            .Select(site => new AuditAppendCallSite(
                Enum.Parse<AuditAppendKind>(site.Kind),
                site.File,
                site.Symbol,
                site.Line,
                site.CalledMethod,
                site.Ordinal,
                site.SourceMethod))
            .ToArray();

    /// <summary>
    /// The same IL walk over the shipped assemblies, driven by a caller-supplied classifier so a second
    /// fence (ticket 272's approval-fact construction fence) discovers its own inventory without a second
    /// disassembler. <paramref name="classify"/> returns a kind for a called or constructed method, or null.
    /// </summary>
    internal static IReadOnlyList<SymbolCallSite> Discover(Func<MethodBase, string?> classify)
    {
        var output = new List<SymbolCallSite>();
        var ordinals = new Dictionary<(string Caller, string Target), int>();
        var baseDirectory = AppContext.BaseDirectory;
        var loaded = AppDomain.CurrentDomain.GetAssemblies()
            .Where(assembly => !assembly.IsDynamic)
            .GroupBy(assembly => assembly.GetName().Name!, StringComparer.OrdinalIgnoreCase)
            .ToDictionary(group => group.Key, group => group.First(), StringComparer.OrdinalIgnoreCase);

        foreach (var assemblyPath in Directory.EnumerateFiles(baseDirectory, "Harborline*.dll")
                     .Where(path => !Path.GetFileName(path).Contains("Tests", StringComparison.OrdinalIgnoreCase)
                         && !Path.GetFileName(path).Contains("Analyzers", StringComparison.OrdinalIgnoreCase)
                         && !Path.GetFileName(path).Contains("Tooling", StringComparison.OrdinalIgnoreCase))
                     .Order(StringComparer.Ordinal))
        {
            Assembly assembly;
            var simpleName = Path.GetFileNameWithoutExtension(assemblyPath);
            try
            {
                assembly = loaded.TryGetValue(simpleName, out var existing)
                    ? existing
                    : AssemblyLoadContext.Default.LoadFromAssemblyPath(assemblyPath);
            }
            catch (Exception)
            {
                continue;
            }

            var pdbPath = Path.ChangeExtension(assemblyPath, ".pdb");
            if (!File.Exists(pdbPath)) continue;
            using var pdbStream = File.OpenRead(pdbPath);
            using var provider = MetadataReaderProvider.FromPortablePdbStream(pdbStream);
            var pdb = provider.GetMetadataReader();

            foreach (var method in Methods(assembly))
            {
                MethodBody? body;
                try { body = method.GetMethodBody(); }
                catch (Exception) { continue; }
                if (body?.GetILAsByteArray() is not { } il) continue;

                var sourceMethod = MethodSignatureSymbol.SourceMethod(method);
                var sourceSymbol = MethodSignatureSymbol.Format(sourceMethod);
                foreach (var call in Calls(method, il))
                {
                    if (classify(call.Callee) is not { } kind) continue;
                    var calledMethod = MethodSignatureSymbol.Format(call.Callee);
                    var ordinalKey = (sourceSymbol, calledMethod);
                    ordinals.TryGetValue(ordinalKey, out var ordinal);
                    ordinals[ordinalKey] = ordinal + 1;
                    var location = Location(pdb, method, call.Offset);
                    if (location is null) continue;
                    output.Add(new SymbolCallSite(
                        kind,
                        NormalizeFile(location.Value.File),
                        sourceSymbol,
                        location.Value.Line,
                        calledMethod,
                        ordinal,
                        sourceMethod.Name));
                }
            }
        }

        return output
            .OrderBy(site => site.File, StringComparer.Ordinal)
            .ThenBy(site => site.Symbol, StringComparer.Ordinal)
            .ThenBy(site => site.CalledMethod, StringComparer.Ordinal)
            .ThenBy(site => site.Ordinal)
            .ToArray();
    }

    private static IEnumerable<MethodBase> Methods(Assembly assembly)
    {
        Type[] types;
        try { types = assembly.GetTypes(); }
        catch (ReflectionTypeLoadException exception) { types = exception.Types.OfType<Type>().ToArray(); }
        foreach (var type in types)
        {
            foreach (var method in type.GetMethods(BindingFlags.Public | BindingFlags.NonPublic
                         | BindingFlags.Static | BindingFlags.Instance | BindingFlags.DeclaredOnly))
                yield return method;
            foreach (var constructor in type.GetConstructors(BindingFlags.Public | BindingFlags.NonPublic
                         | BindingFlags.Static | BindingFlags.Instance | BindingFlags.DeclaredOnly))
                yield return constructor;
        }
    }

    private static IEnumerable<(int Offset, MethodBase Callee)> Calls(MethodBase caller, byte[] il)
    {
        for (var position = 0; position < il.Length;)
        {
            var offset = position;
            var first = il[position++];
            var opcode = first == 0xfe ? TwoByte[il[position++]] : OneByte[first];
            if (opcode.Size == 0) yield break;

            if (opcode.OperandType == OperandType.InlineMethod)
            {
                var token = BitConverter.ToInt32(il, position);
                MethodBase? callee = null;
                try
                {
                    callee = caller.Module.ResolveMethod(
                        token,
                        caller.DeclaringType?.GetGenericArguments(),
                        caller is MethodInfo info ? info.GetGenericArguments() : null);
                }
                catch (Exception) { }
                if (callee is not null
                    && (opcode == OpCodes.Call || opcode == OpCodes.Callvirt || opcode == OpCodes.Newobj))
                    yield return (offset, callee);
            }

            position += OperandSize(opcode.OperandType, il, position);
        }
    }

    private static int OperandSize(OperandType type, byte[] il, int position) => type switch
    {
        OperandType.InlineNone => 0,
        OperandType.ShortInlineBrTarget or OperandType.ShortInlineI or OperandType.ShortInlineVar => 1,
        OperandType.InlineVar => 2,
        OperandType.InlineI or OperandType.InlineBrTarget or OperandType.InlineField
            or OperandType.InlineMethod or OperandType.InlineSig or OperandType.InlineString
            or OperandType.InlineTok or OperandType.InlineType or OperandType.ShortInlineR => 4,
        OperandType.InlineI8 or OperandType.InlineR => 8,
        OperandType.InlineSwitch => 4 + (BitConverter.ToInt32(il, position) * 4),
        _ => throw new InvalidOperationException($"Unsupported IL operand type {type}."),
    };

    private static AuditAppendKind? Classify(MethodBase method)
    {
        var contract = method.DeclaringType?.FullName;
        return (contract, method.Name) switch
        {
            ("Harborline.Api.Kernel.Audit.IRefusedAuditTrail", "AppendRefusedAsync") => AuditAppendKind.Refused,
            ("Harborline.Api.Kernel.Audit.IAuditTrail", "AppendAsync") => AuditAppendKind.Ordinary,
            ("Harborline.Api.Kernel.Audit.IAuthorizedAuditTrail", "AppendAuthorizedAsync") => AuditAppendKind.Authorized,
            ("Harborline.Api.Foundation.Packs.Install.Audit.IPackInstallAudit", "Append") => AuditAppendKind.PackOrdinary,
            ("Harborline.Api.Foundation.Packs.Install.Audit.IPackInstallAudit", "AppendAuthorized") => AuditAppendKind.PackAuthorized,
            _ => null,
        };
    }

    private static (string File, int Line)? Location(MetadataReader pdb, MethodBase method, int ilOffset)
    {
        if ((method.MetadataToken & 0xff000000) != 0x06000000) return null;
        var handle = MetadataTokens.MethodDefinitionHandle(method.MetadataToken & 0x00ffffff);
        MethodDebugInformation debug;
        try { debug = pdb.GetMethodDebugInformation(handle); }
        catch (BadImageFormatException) { return null; }

        SequencePoint? chosen = null;
        foreach (var point in debug.GetSequencePoints())
        {
            if (point.IsHidden || point.Offset > ilOffset) continue;
            chosen = point;
        }
        if (chosen is null) return null;
        var document = pdb.GetDocument(chosen.Value.Document);
        return (pdb.GetString(document.Name), chosen.Value.StartLine);
    }

    internal static string NormalizeFile(string path) =>
        Path.GetRelativePath(RepositoryRoot(), ResolveSourcePath(path)).Replace('\\', '/');

    /// <summary>Resolve metadata paths before either opening source or comparing allow-list rows.</summary>
    internal static string ResolveSourcePath(string path)
    {
        var normalized = path.Replace('\\', '/');
        var remainder = normalized;
        while (remainder.StartsWith("../", StringComparison.Ordinal))
            remainder = remainder[3..];

        // CI maps the checkout to /_/. Older callers may already have made that path
        // relative to the checkout, leaving a climb followed by _/ instead.
        if (remainder.StartsWith("/_/", StringComparison.Ordinal))
            normalized = remainder[3..];
        else if (remainder != normalized && remainder.StartsWith("_/", StringComparison.Ordinal))
            normalized = remainder[2..];

        return Path.GetFullPath(Path.Combine(RepositoryRoot(), normalized));
    }

    internal static string RepositoryRoot()
    {
        var directory = new DirectoryInfo(AppContext.BaseDirectory);
        while (directory is not null)
        {
            if (File.Exists(Path.Combine(directory.FullName, "Harborline.Api.slnx")))
                return directory.FullName;
            directory = directory.Parent;
        }
        throw new DirectoryNotFoundException("Could not locate Harborline.Api.slnx above the test output.");
    }
}

