            AuthoritySnapshot = Snapshot([new AuthorityGrantSnapshot("caller-forged", 99)]),
        };

        await trail.AppendAsync(record);

        Assert.Null(Assert.Single(await QueryAsync(trail, Tenant)).AuthoritySnapshot);
    }

