        Assert.Empty(identity.ReceivedCalls());
        Assert.Empty(sessions.ReceivedCalls());
        Assert.Empty(grants.ReceivedCalls());
        Assert.Empty(party.ReceivedCalls());
        Assert.Empty(roster.ReceivedCalls());
    }

