    public async Task AuthorizationSeed_ForeignGrantStoreIsRejectedByStableFenceFailure()
    {
        var at = new DateTimeOffset(2026, 9, 2, 12, 0, 0, TimeSpan.Zero);
        var tenant = new TenantId("race-tenant");
