                    CredentialCeremonyId = "ticket-216",
                    CredentialVersion = 1,
                    Status = InstallationAccountStatus.Active,
                    SecurityVersion = 1,
                    OwnerVersion = 1,
                    CreatedAtUtc = FrozenAt.AddMinutes(-1),
