        Assert.Equal(
            "contacts",
            AuthorizationGate.RecordKindFor(AuthorizationOperation.Parse(Permission.ContactsWrite)));
        Assert.Equal(
            "record",
            AuthorizationGate.RecordKindFor(AuthorizationOperation.Parse(TeamRolePermissions.RecordsWrite)));
        Assert.Equal(
