            CancellationToken ct = default) =>
            ValueTask.FromResult<IReadOnlyList<CanonicalReplicaDocument>>(
            [
                new CanonicalReplicaDocument(
                    "contacts",
                    "abc"u8.ToArray(),
                    "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad"),
            ]);
