    {
        var accessorTypes = typeof(LocalNodeOptions).Assembly
            .GetExportedTypes()
            .Where(type => type.Name.EndsWith("Accessor", StringComparison.Ordinal))
            .Select(type => type.FullName)
            .Order(StringComparer.Ordinal)
