    [Fact]
    public async Task Effective_read_resolves_the_active_packs_before_any_activation()
    {
        var effective = await EffectiveAsync();
        Assert.Matches("^[0-9a-f]{64}$", effective.GetProperty("digest").GetString());
        Assert.Equal(_tenant.Value, effective.GetProperty("references").GetProperty("tenantKey").GetString());
        Assert.Equal(["acme.core", "acme.ext"], effective.GetProperty("references").GetProperty("activePackageKeys").EnumerateArray().Select(k => k.GetString()));
    }

    [Fact]
    public async Task Prepare_then_activate_commits_ownership_and_pointer_together_and_publishes_evidence()
    {
        var baseline = await DigestAsync();
        var prepared = await PrepareAsync(baseline, "form.shared", "acme.ext");
        Assert.Equal("preparing", prepared.GetProperty("status").GetString());
        var candidate = prepared.GetProperty("candidateDigest").GetString()!;
        Assert.NotEqual(baseline, candidate);
        Assert.Equal("Preparing", prepared.GetProperty("detail").GetProperty("status").GetString());

        using var activate = await ActivateAsync(baseline, candidate, "intent-1");
        var body = await activate.Content.ReadFromJsonAsync<JsonElement>();
        Assert.Equal(HttpStatusCode.OK, activate.StatusCode);
        Assert.Equal("effective", body.GetProperty("status").GetString());
        Assert.Equal(candidate, body.GetProperty("effectiveDigest").GetString());
        Assert.Equal("Effective", body.GetProperty("detail").GetProperty("status").GetString());

        Assert.Equal(candidate, await DigestAsync());
        Assert.Equal("acme.ext", _store.GetKeyOwnership(_tenant)["form.shared"]);
        var outbox = Assert.Single(Outbox());
        Assert.Equal("intent-1", outbox.IntentId);
        Assert.Equal(baseline, outbox.PriorDigest);
        Assert.Equal(candidate, outbox.NewDigest);
        Assert.Equal(Frozen, outbox.PublishedAt);
        Assert.Equal(Frozen, outbox.CommittedAt);
        // DES-0029 ck-6: delivered to the kernel trail by the post-write drain, with the authority the decision captured.
        var published = Assert.Single(await EvidenceAsync());
        Assert.Equal(ConfigurationEvidenceOutbox.AuditIdFor(_tenant.Value, "intent-1"), published.AuditId);
        Assert.Equal(Frozen, published.OccurredAt);
        Assert.NotNull(published.AuthoritySnapshot);
        Assert.Equal(candidate, published.Payload.Payload.Body["version"]?.ToString());
        Assert.StartsWith("configuration.activated:intent-1:", published.Payload.Payload.Body["detail"]?.ToString(), StringComparison.Ordinal);
        Assert.Equal("Activated", published.Payload.Payload.Body["action"]?.ToString());
        Assert.Equal("configuration-generation", published.Payload.Payload.Body["packKey"]?.ToString());
        // The install-wide act the decision admitted, so the captured authority names the act the entry records.
        Assert.Equal(Harborline.Api.Foundation.IdentityAtlas.Permissions.PermissionAtom.Parse(
            $"{Harborline.Api.Foundation.IdentityAtlas.Permissions.Permission.PackagesOperate}@/"), published.Act);
        Assert.Equal(("", "", "/"), (published.Target!.Value.RecordKind, published.Target.Value.RecordId, published.Target.Value.Scope.ToString()));
    }

    [Fact(DisplayName = "ck-6 activation outbox: evidence whose publication crashed is delivered by the running host's drain daemon, without the offline verb")]
    public async Task Crashed_publication_is_delivered_by_the_drain_daemon()
    {
        var candidate = await ActivateCrashingPublicationAsync("intent-daemon", "acme.ext");
        Assert.Empty(await EvidenceAsync());

        using var daemon = new ConfigurationEvidenceDrainDaemon(_evidence, TimeProvider.System, NullLogger<ConfigurationEvidenceDrainDaemon>.Instance);
        await daemon.StartAsync(CancellationToken.None);
        var deadline = DateTime.UtcNow.AddSeconds(30);
        // Each poll opens a keyed connection to the rollback-journal test store and holds its shared lock, so a 20 ms
        // poll starved the daemon's mark commit under a loaded runner (the entry was on the trail, the mark never landed).
        while (Outbox().Single().PublishedAt is null && DateTime.UtcNow < deadline) await Task.Delay(250);
        await daemon.StopAsync(CancellationToken.None);

        Assert.NotNull(Outbox().Single().PublishedAt);
        var delivered = Assert.Single(await EvidenceAsync());
        Assert.Equal(ConfigurationEvidenceOutbox.AuditIdFor(_tenant.Value, "intent-daemon"), delivered.AuditId);
        Assert.Equal(candidate, delivered.Payload.Payload.Body["version"]?.ToString());
    }

