        new(
            new JournalEntryId("JE-ENLISTMENT"),
            new TenantId("tenant-1"),
            new DateOnly(2026, 8, 18),
            "coordination test",
            [
                new JournalEntryLine(new GLAccountId("1000"), 10m, 0m),
                new JournalEntryLine(new GLAccountId("4000"), 0m, 10m),
