        var legacyCiphertext = new EncryptedField(
            Convert.FromHexString("1087FE1CA05F4223EEC8A43715134C85B77A65DCA8C7424D5F71575F039D7765"),
            Convert.FromHexString("000102030405060708090A0B"),
