                .Where(type => type != typeof(AccessGrantAuthorizationSeed))
                .SelectMany(DeclaredMethods)
                .OfType<MethodInfo>()
                .Where(method => method.IsPublic || method.IsAssembly),
            method => method.ReturnType == platformDecision);
