/// <summary>
/// ADR 0115 gap C4 — route-level tests for the node-local chart-of-accounts
/// seed endpoint.
/// </summary>
/// <remarks>
/// <para>
/// Hosts the SAME route handlers <see cref="HostedChartOfAccountsApiEndpoint"/>
/// and <see cref="HostedEntityApiEndpoint"/> register on a real in-process
/// Kestrel listener, backed by a temp SQLite store (plain, unencrypted — SC-1
/// covered separately). Drives them via a real <see cref="HttpClient"/>.
/// </para>
/// <para>
/// The entity endpoint is co-registered so tests can create an entity (offline
/// POST /api/local-node/entities) before seeding the CoA — exactly as the
/// onboarding wizard does.
/// </para>
/// </remarks>
public sealed class ChartOfAccountsRouteTests : IAsyncLifetime
{
    private WebApplication _app = null!;
    private HttpClient _client = null!;
    private string _dir = null!;

    public async Task InitializeAsync()
    {
        var builder = WebApplication.CreateBuilder();
        // Ticket 294 slice 3b: the desktop actor (no compile-time operator id).
        Harborline.Api.LocalNodeHost.Tests.Authorization.TestDesktopOperator.AddTestDesktopOperator(builder.Services);
        builder.WebHost.UseUrls("http://127.0.0.1:0");
        builder.Logging.ClearProviders();

        _dir = Path.Combine(Path.GetTempPath(), "harborline-coa-routes-" + Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(_dir);
        // Pooling=False: keep this fixture's SQLite handles out of the process-global pool so a sibling test
        // class's ClearAllPools() cannot dispose a handle mid-Open() (the ObjectDisposedException race,
        // bug-20260702-8012e553). See ChartOfAccountsManagementRouteTests for the full note.
        var connectionString = $"Data Source={Path.Combine(_dir, "coa-test.db")};Pooling=False";

        builder.Services.AddSingleton<IHarborlineEntityModule, FinancialLedgerEntityModule>();
        // Ticket 151: the entity POST is now permission-gated; grant-all keeps these route tests on their pre-gate behaviour.
        builder.Services.AddSingleton<Harborline.Api.Foundation.Authorization.IAuthorizationContext>(Harborline.Api.LocalNodeHost.Tests.Packs.TestAuthorizationContext.AllowAll());
        builder.Services.AddTestKernelClock();
        builder.Services.AddSingleton(Harborline.Api.LocalNodeHost.Tests.Authorization.TestRouteGate.AllowAll());
        builder.Services.AddSingleton<IHarborlineEntityModule, Harborline.Api.Blocks.FinancialPeriods.Data.FinancialPeriodsEntityModule>();
        builder.Services.AddDbContextFactory<LocalNodeDbContext>(opt =>
            opt.UseSqlite(connectionString));

        _app = builder.Build();

        var factory = _app.Services.GetRequiredService<IDbContextFactory<LocalNodeDbContext>>();
        await using (var ctx = await factory.CreateDbContextAsync())
        {
            await ctx.Database.EnsureCreatedAsync();
        }

        // Register both the entity route (to create a pre-existing entity)
        // and the CoA seed route (the subject under test).
        _app.Use(async (http, next) =>
        {
            http.Features.Set(DesktopPlaneRequestFeature.Instance);
            await next(http);
        });
        var deviceReachable = _app.MapDeviceReachableProductDataGroup();
        EntityRoutes.Map(deviceReachable, factory, NodeTestActiveTeam.Accessor,
            new Data.Entities.NodeEntityWriter(factory, Harborline.Api.Foundation.Assets.Entities.NullEntityValidator.Instance, Authorization.TestAuthorization.AllowGate()),
            TimeProvider.System);
        ChartOfAccountsRoutes.Map(
            deviceReachable,
            factory,
            NodeTestActiveTeam.Accessor,
            TimeProvider.System);

        await _app.StartAsync();

        var addresses = _app.Services.GetRequiredService<IServer>()
            .Features.Get<IServerAddressesFeature>();
        _client = new HttpClient { BaseAddress = new Uri(addresses!.Addresses.First()) };
    }

    public async Task DisposeAsync()
    {
        _client?.Dispose();
        await _app.StopAsync();
        await _app.DisposeAsync();
        // No ClearAllPools(): Pooling=False already closes/releases the handles on app dispose, and a
        // process-global pool clear is a cross-test race hazard (bug-20260702-8012e553).
        try { if (Directory.Exists(_dir)) Directory.Delete(_dir, recursive: true); }
        catch { /* best-effort temp cleanup */ }
    }

    private const string EntityRoute = "/api/local-node/entities";
    private const string SeedRoute = "/api/local-node/chart-of-accounts/seed-from-template";

    /// <summary>
    /// Creates an entity via the entity route and returns its id string.
    /// </summary>
    private async Task<string> CreateEntityAsync(string legalName = "Test Entity LLC")
    {
        var resp = await _client.PostAsJsonAsync(EntityRoute, new { legalName });
        resp.EnsureSuccessStatusCode();
        var doc = await resp.Content.ReadFromJsonAsync<JsonElement>();
        return doc.GetProperty("id").GetString()!;
    }

    [Fact(DisplayName = "CoA seed: rental-real-estate template seeds expected account count")]
    public async Task Seed_RentalRealEstate_SeedsExpectedAccounts()
    {
        var entityId = await CreateEntityAsync();
        var resp = await _client.PostAsJsonAsync(SeedRoute, new
        {
            entityId,
            templateId = "rental-real-estate",
        });

        Assert.Equal(HttpStatusCode.Created, resp.StatusCode);
        var doc = await resp.Content.ReadFromJsonAsync<JsonElement>();

        Assert.False(string.IsNullOrWhiteSpace(doc.GetProperty("chartId").GetString()));
        Assert.Equal(entityId, doc.GetProperty("entityId").GetString());
        Assert.Equal(
            DefaultChartTemplates.RentalRealEstate.Accounts.Count,
            doc.GetProperty("accountsSeeded").GetInt32());
    }

    [Fact(DisplayName = "CoA seed: pm-pack template seeds accounts and reports template name")]
    public async Task Seed_PmPack_SeedsAccounts()
    {
        var entityId = await CreateEntityAsync("ScorpMgmt LLC");
        var resp = await _client.PostAsJsonAsync(SeedRoute, new
        {
            entityId,
            templateId = "pm-pack",
        });

        Assert.Equal(HttpStatusCode.Created, resp.StatusCode);
        var doc = await resp.Content.ReadFromJsonAsync<JsonElement>();
        Assert.Equal(
            DefaultChartTemplates.ScorpManagementCo.Accounts.Count,
            doc.GetProperty("accountsSeeded").GetInt32());
        Assert.False(string.IsNullOrWhiteSpace(doc.GetProperty("templateName").GetString()));
    }

    [Fact(DisplayName = "CoA seed: skip template seeds 0 accounts")]
    public async Task Seed_Skip_SeedsZeroAccounts()
    {
        var entityId = await CreateEntityAsync("Manual Corp");
        var resp = await _client.PostAsJsonAsync(SeedRoute, new
        {
            entityId,
            templateId = "skip",
        });

        Assert.Equal(HttpStatusCode.Created, resp.StatusCode);
        var doc = await resp.Content.ReadFromJsonAsync<JsonElement>();
        Assert.Equal(0, doc.GetProperty("accountsSeeded").GetInt32());
    }

    [Theory(DisplayName = "CoA seed: a client-supplied chart id is refused 400 with no write, and omission mints a server id (T-974)")]
    [InlineData("id")]
    [InlineData("chartId")]
    public async Task Seed_refuses_a_client_supplied_record_id(string key)
    {
        var entityId = await CreateEntityAsync("Client Chart LLC");

        var refused = await _client.PostAsJsonAsync(SeedRoute, new Dictionary<string, object?>
        {
            ["entityId"] = entityId,
            ["templateId"] = "rental-real-estate",
            [key] = "client-constructed-id",
        });

        Assert.Equal(HttpStatusCode.BadRequest, refused.StatusCode);
        Assert.Equal("request.record-id-not-accepted",
            (await refused.Content.ReadFromJsonAsync<JsonElement>()).GetProperty("code").GetString());
        var factory = _app.Services.GetRequiredService<IDbContextFactory<LocalNodeDbContext>>();
        await using (var ctx = await factory.CreateDbContextAsync())
            Assert.Empty(await ctx.Set<ChartOfAccounts>().ToListAsync());

        var created = await _client.PostAsJsonAsync(SeedRoute, new { entityId, templateId = "rental-real-estate" });
        Assert.Equal(HttpStatusCode.Created, created.StatusCode);
        var minted = (await created.Content.ReadFromJsonAsync<JsonElement>()).GetProperty("chartId").GetString();
        Assert.False(string.IsNullOrWhiteSpace(minted));
        Assert.NotEqual("client-constructed-id", minted);
    }

    [Fact(DisplayName = "CoA seed: chart is linked to the correct entity")]
    public async Task Seed_ChartLinkedToEntity()
    {
        var entityId = await CreateEntityAsync("Linked Entity LLC");
        var resp = await _client.PostAsJsonAsync(SeedRoute, new
        {
            entityId,
            templateId = "rental-real-estate",
        });

        Assert.Equal(HttpStatusCode.Created, resp.StatusCode);
        var doc = await resp.Content.ReadFromJsonAsync<JsonElement>();
        Assert.Equal(entityId, doc.GetProperty("entityId").GetString());
    }

    [Fact(DisplayName = "CoA seed: default templateId is rental-real-estate when omitted")]
    public async Task Seed_DefaultTemplate_IsRentalRealEstate()
    {
        var entityId = await CreateEntityAsync("Default Template LLC");
        // POST body with no templateId — should default to rental-real-estate
        var resp = await _client.PostAsJsonAsync(SeedRoute, new { entityId });

        Assert.Equal(HttpStatusCode.Created, resp.StatusCode);
        var doc = await resp.Content.ReadFromJsonAsync<JsonElement>();
        Assert.Equal(
            DefaultChartTemplates.RentalRealEstate.Accounts.Count,
            doc.GetProperty("accountsSeeded").GetInt32());
    }

    [Fact(DisplayName = "CoA seed: custom chartName appears in response template name")]
    public async Task Seed_CustomChartName_Accepted()
    {
        var entityId = await CreateEntityAsync("Custom Name LLC");
        var resp = await _client.PostAsJsonAsync(SeedRoute, new
        {
            entityId,
            templateId = "rental-real-estate",
            chartName = "My Custom Chart 2026",
        });

        Assert.Equal(HttpStatusCode.Created, resp.StatusCode);
        // Response carries templateName from the resolved template, not chartName —
        // that's by design (chartName is a stored DB field, not echoed in the response).
        Assert.Equal(HttpStatusCode.Created, resp.StatusCode);
    }

    [Fact(DisplayName = "CoA seed: unknown entity returns 400")]
    public async Task Seed_UnknownEntity_Returns400()
    {
        var resp = await _client.PostAsJsonAsync(SeedRoute, new
        {
            entityId = Guid.NewGuid().ToString(),
            templateId = "rental-real-estate",
        });
        Assert.Equal(HttpStatusCode.BadRequest, resp.StatusCode);
    }

    [Fact(DisplayName = "CoA seed: unknown templateId returns 400")]
    public async Task Seed_UnknownTemplateId_Returns400()
    {
        var entityId = await CreateEntityAsync("Template Error LLC");
        var resp = await _client.PostAsJsonAsync(SeedRoute, new
        {
            entityId,
            templateId = "nonexistent-template",
        });
        Assert.Equal(HttpStatusCode.BadRequest, resp.StatusCode);
    }

    [Fact(DisplayName = "CoA seed: missing entityId returns 400")]
    public async Task Seed_MissingEntityId_Returns400()
    {
        var resp = await _client.PostAsJsonAsync(SeedRoute, new
        {
            templateId = "rental-real-estate",
        });
        Assert.Equal(HttpStatusCode.BadRequest, resp.StatusCode);
    }

    [Fact(DisplayName = "CoA seed: second seed on same entity creates a second chart (append semantics)")]
    public async Task Seed_SecondSeed_AppendsChart()
    {
        var entityId = await CreateEntityAsync("Double-Seed LLC");

        var resp1 = await _client.PostAsJsonAsync(SeedRoute, new { entityId, templateId = "rental-real-estate" });
        var resp2 = await _client.PostAsJsonAsync(SeedRoute, new { entityId, templateId = "skip" });

        Assert.Equal(HttpStatusCode.Created, resp1.StatusCode);
        Assert.Equal(HttpStatusCode.Created, resp2.StatusCode);

        var doc1 = await resp1.Content.ReadFromJsonAsync<JsonElement>();
        var doc2 = await resp2.Content.ReadFromJsonAsync<JsonElement>();

        // The two charts should have distinct IDs.
        Assert.NotEqual(
            doc1.GetProperty("chartId").GetString(),
            doc2.GetProperty("chartId").GetString());
    }
}

using System.Net;
using System.Net.Http.Json;
using System.Text.Json;

using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Hosting.Server;
using Microsoft.AspNetCore.Hosting.Server.Features;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Logging.Abstractions;

using Harborline.Api.Foundation.Crypto;
using Harborline.Api.Foundation.IdentityAtlas;
using Harborline.Api.Kernel.Crdt;
using Harborline.Api.Kernel.Crdt.Backends;
using Harborline.Api.Kernel.Runtime.Teams;
using Harborline.Api.Kernel.Sync.Application;
using Harborline.Api.Kernel.Sync.DependencyInjection;
using Harborline.Api.LocalNodeHost.Data.Comms;
using Harborline.Api.LocalNodeHost.Enrollment;
using Harborline.Api.LocalNodeHost.Health;

namespace Harborline.Api.LocalNodeHost.Tests.Entities;

/// <summary>
/// GAP #2 — the comms author party id is the ACTIVE ENROLLED MEMBER (the trust-roster party bound to the
/// signing principal key), NOT the install-constant <c>"local"</c> that every node would otherwise stamp.
/// These tests prove the SHIPPING wiring (the 6-arg <see cref="CommsRoutes.Map"/> overload + the
/// <see cref="HostedCommsApiEndpoint"/> consistency assertion):
/// <list type="bullet">
///   <item>a message's <c>authorPartyId</c> is the active enrolled member's party id (NOT "local");</item>
///   <item>two distinct-root nodes stamp DISTINCT party ids (the two-user-test residual fixed);</item>
///   <item>the author-party-id↔signing-key consistency holds — the production forge-proof gate passes the
///     operator's OWN messages (and rejects a mismatch, not regressing #1277-B1);</item>
///   <item>the genesis (single-user) node stamps its own per-node-distinct party id + its messages verify;</item>
///   <item>the host consistency assertion FAILS-CLOSED when the author party is not the roster party bound to
///     the signing key (a composition error must not ship messages the node's own gate would drop).</item>
/// </list>
/// </summary>
public sealed class CommsAuthorPartyIdTests : IAsyncLifetime
{
    private static readonly IOperationVerifier Verifier = new Ed25519Verifier();
    private static readonly System.Guid TeamId = System.Guid.Parse("7e57dddd-0000-0000-0000-0000000000a2");

    private readonly List<IAsyncDisposable> _asyncDisposables = new();
    private readonly List<WebApplication> _apps = new();
    private readonly List<HttpClient> _clients = new();
    private readonly List<NodePrincipalSigner> _signers = new();
    private readonly List<string> _dirs = new();

    public Task InitializeAsync() => Task.CompletedTask;

    public async Task DisposeAsync()
    {
        foreach (var c in _clients) c.Dispose();
        foreach (var s in _signers) s.Dispose();
        foreach (var d in _asyncDisposables) await d.DisposeAsync();
        foreach (var a in _apps) { await a.StopAsync(); await a.DisposeAsync(); }
        foreach (var dir in _dirs)
        {
            try { if (Directory.Exists(dir)) Directory.Delete(dir, recursive: true); } catch { /* best-effort */ }
        }
    }

    // ── A node whose comms routes are mapped via the SHIPPING (6-arg) overload, the author resolved from a ──
    //    seeded genesis roster exactly as HostedCommsApiEndpoint.ResolveAndAssertActiveMember does. ─────────
    private sealed record Node(HttpClient Client, string AuthorPartyId, NodePrincipalSigner Signer);

    private async Task<Node> NewShippingNodeAsync(byte[] rootSeed)
    {
        var signer = new NodePrincipalSigner(rootSeed);
        _signers.Add(signer);

        // Seed the genesis (self) roster with a PER-NODE-DISTINCT party id derived from the node principal key
        // — the same shape Program.cs seeds (os:<user>#<key8>). Distinct roots ⇒ distinct key8 ⇒ distinct ids.
        var key8 = System.Convert.ToHexString(signer.Signer.IssuerId.AsSpan()[..4]).ToLowerInvariant();
        var partyId = $"os:tester#{key8}";
        var roster = new NodeTeamRoster(MemberRoster.Genesis(
            TeamId, partyId, signer.Signer, Verifier, System.DateTimeOffset.UtcNow, System.Guid.NewGuid()));

        // The consistency invariant HostedCommsApiEndpoint asserts before mapping: the author party is bound,
        // in this roster, to the signing key. Mirror it here so this helper builds the SHIPPING author source.
        var bound = roster.Current.PublicKeyOf(partyId);
        Assert.NotNull(bound);
        Assert.True(bound!.Value.Equals(signer.Signer.IssuerId));

        var dir = Path.Combine(Path.GetTempPath(), "harborline-comms-gap2-" + System.Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(dir);
        _dirs.Add(dir);

        var builder = WebApplication.CreateBuilder();
        // Ticket 294 slice 3b: the desktop actor (no compile-time operator id).
        Harborline.Api.LocalNodeHost.Tests.Authorization.TestDesktopOperator.AddTestDesktopOperator(builder.Services);
        builder.WebHost.UseUrls("http://127.0.0.1:0");
        builder.Logging.ClearProviders();
        builder.Services.AddDbContextFactory<NodeLocalCommsDbContext>(opt =>
            opt.UseSqlite($"Data Source={Path.Combine(dir, "comms.db")};Pooling=False"));
        builder.Services.AddSingleton<ICrdtEngine, YDotNetCrdtEngine>();
        var app = builder.Build();
        _apps.Add(app);

        var factory = app.Services.GetRequiredService<IDbContextFactory<NodeLocalCommsDbContext>>();
        await using (var ctx = await factory.CreateDbContextAsync())
            await ctx.Database.EnsureCreatedAsync();

        // The production forge-proof projection — rosterBinding wired from THIS seeded roster (as AddNodeComms).
        var crdt = new CommsCrdtProjection(
            app.Services.GetRequiredService<ICrdtEngine>(), factory, new Ed25519Verifier(),
            NullLogger<CommsCrdtProjection>.Instance, rosterBinding: roster.ForgeProofBinding);
        _asyncDisposables.Add(crdt);

        // SHIPPING (6-arg) overload: author = the resolved active enrolled member's party id.
        CommsRoutes.Map(app, crdt, signer.Signer, NodeTestActiveTeam.Accessor,
            new NodeCallerSessionToken(null), partyId, TimeProvider.System);

        await app.StartAsync();
        var addresses = app.Services.GetRequiredService<IServer>().Features.Get<IServerAddressesFeature>();
        var client = new HttpClient { BaseAddress = new System.Uri(addresses!.Addresses.First()) };
        _clients.Add(client);
        return new Node(client, partyId, signer);
    }

    private static byte[] Seed(byte fill)
    {
        var s = new byte[32];
        for (var i = 0; i < s.Length; i++) s[i] = (byte)(fill + i);
        return s;
    }

    private const string Route = "/api/local-node/comms";

    private static async Task<string> PostAndReadAuthorAsync(HttpClient client, string body)
    {
        var resp = await client.PostAsJsonAsync(Route, new { body });
        Assert.Equal(HttpStatusCode.Created, resp.StatusCode);
        var created = await resp.Content.ReadFromJsonAsync<JsonElement>();
        return created.GetProperty("authorPartyId").GetString()!;
    }

    // ── TEST 1: the SHIPPING path stamps the active enrolled member's id, NOT the constant "local". ─────────

    [Fact(DisplayName = "gap #2: a message's authorPartyId is the active enrolled member's id (NOT \"local\")")]
    public async Task Post_Stamps_ActiveEnrolledMember_PartyId_NotLocal()
    {
        var node = await NewShippingNodeAsync(Seed(0x10));

        var author = await PostAndReadAuthorAsync(node.Client, "hello");
        Assert.Equal(node.AuthorPartyId, author);
        Assert.NotEqual("local", author);
        Assert.StartsWith("os:tester#", author); // the per-node-distinct os:<user>#<key8> shape

        // GET returns the same attribution.
        var doc = await node.Client.GetFromJsonAsync<JsonElement>(Route);
        Assert.Equal(node.AuthorPartyId, doc.GetProperty("messages")[0].GetProperty("authorPartyId").GetString());
    }

    // ── TEST 2: two distinct-root nodes stamp DISTINCT party ids (the two-user-test residual fixed). ────────

    [Fact(DisplayName = "gap #2: two distinct-root nodes stamp DISTINCT author party ids")]
    public async Task TwoDistinctRootNodes_StampDistinctPartyIds()
    {
        var nodeA = await NewShippingNodeAsync(Seed(0x20));
        var nodeB = await NewShippingNodeAsync(Seed(0x40)); // a DIFFERENT root → a different principal key

        var authorA = await PostAndReadAuthorAsync(nodeA.Client, "from A");
        var authorB = await PostAndReadAuthorAsync(nodeB.Client, "from B");

        // The whole point of gap #2: not both "local" — they are DISTINCT.
        Assert.NotEqual(authorA, authorB);
        Assert.NotEqual("local", authorA);
        Assert.NotEqual("local", authorB);
        // And distinct because the signing keys are distinct (the key8 suffix differs).
        Assert.NotEqual(nodeA.Signer.NodePublicKey, nodeB.Signer.NodePublicKey);
    }

    // ── TEST 3: author↔signing-key consistency — the operator's OWN messages pass the forge-proof gate. ─────

    [Fact(DisplayName = "gap #2: the stamped author is roster-bound to the signing key → forge-proof gate passes own messages")]
    public async Task StampedAuthor_IsBoundToSigningKey_ForgeProofGatePassesOwnMessages()
    {
        var node = await NewShippingNodeAsync(Seed(0x30));

        // The route stamped (authorPartyId, authorIssuerId). The consistency the forge-proof gate requires is:
        // authorPartyId is the roster party BOUND to authorIssuerId — so the operator's own message is not dropped.
        var resp = await node.Client.PostAsJsonAsync(Route, new { body = "my own message" });
        Assert.Equal(HttpStatusCode.Created, resp.StatusCode);
        var created = await resp.Content.ReadFromJsonAsync<JsonElement>();
        var stampedAuthor = created.GetProperty("authorPartyId").GetString()!;
        var stampedIssuer = created.GetProperty("authorIssuerId").GetString()!;

        // The route signed with the node's principal key.
        Assert.Equal(node.Signer.NodePublicKey, stampedIssuer);

        // The roster the production gate consumes binds the stamped author to the node's signing key.
        var roster = new NodeTeamRoster(MemberRoster.Genesis(
            TeamId, node.AuthorPartyId, node.Signer.Signer, Verifier, System.DateTimeOffset.UtcNow, System.Guid.NewGuid()));

        // FORGE-PROOF (passes own messages): the stamped author IS the roster party bound to the stamped key.
        var boundKey = roster.ForgeProofBinding(stampedAuthor);
        Assert.NotNull(boundKey);
        Assert.Equal(stampedIssuer, boundKey!.Value.ToBase64Url());

        // And the inverse holds (don't regress #1277-B1): a claim for a party NOT in the roster has NO binding
        // → fail-closed (dropped). A forger who signs with their own key but stamps another party fails too.
        Assert.Null(roster.ForgeProofBinding("os:someone-else#deadbeef"));
    }

    // ── TEST 4: the host consistency assertion FAILS-CLOSED on an author/key mismatch (no shipping a self-drop). ──

    [Fact(DisplayName = "gap #2: HostedCommsApiEndpoint fails-closed when the author is not roster-bound to the signing key")]
    public async Task HostedEndpoint_FailsClosed_OnAuthorKeyMismatch()
    {
        // The seeded roster binds a DIFFERENT key than the comms signer — the exact composition error the
        // assertion guards (the operator's own messages would otherwise be dropped by the production merge gate).
        var commsSigner = new NodePrincipalSigner(Seed(0x50));
        _signers.Add(commsSigner);
        var otherSigner = new NodePrincipalSigner(Seed(0x60)); // binds a DIFFERENT key into the roster
        _signers.Add(otherSigner);

        var dir = Path.Combine(Path.GetTempPath(), "harborline-comms-gap2-mismatch-" + System.Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(dir);
        _dirs.Add(dir);

        // A minimal CommsConversationRegistry over its own SQLite store (the assertion throws BEFORE any
        // conversation projection is touched, but the endpoint ctor requires a non-null registry).
        var services = new ServiceCollection();
        services.AddTestKernelClock();
        services.AddLogging();
        services.AddDbContextFactory<NodeLocalCommsDbContext>(opt =>
            opt.UseSqlite($"Data Source={Path.Combine(dir, "comms.db")};Pooling=False"));
        services.AddSingleton<ICrdtEngine, YDotNetCrdtEngine>();
        services.AddSingleton<IActiveTeamAccessor>(NodeTestActiveTeam.Accessor);
        services.AddSingleton(new NodeCallerSessionToken(null));
        services.AddHarborlineDeltaRouter();
        var sp = services.BuildServiceProvider();
        var factory = sp.GetRequiredService<IDbContextFactory<NodeLocalCommsDbContext>>();
        await using (var ctx = await factory.CreateDbContextAsync())
            await ctx.Database.EnsureCreatedAsync();

        // Roster binds "os:mismatch" to OTHER's key; the endpoint signs with commsSigner — they differ.
        var roster = new NodeTeamRoster(MemberRoster.Genesis(
            TeamId, "os:mismatch", otherSigner.Signer, Verifier, System.DateTimeOffset.UtcNow, System.Guid.NewGuid()));
        var registry = new CommsConversationRegistry(
            sp.GetRequiredService<ICrdtEngine>(), factory, new Ed25519Verifier(),
            sp.GetRequiredService<IDeltaRouter>(), sp.GetRequiredService<ILoggerFactory>(),
            rosterBinding: roster.ForgeProofBinding);
        _asyncDisposables.Add(registry);

        // SharedHostedWebApp constructed directly (mirrors SharedHostedWebAppCallerAuthTests). It is never
        // started — the consistency assertion throws before StartAsync touches it.
        var sharedApp = new SharedHostedWebApp(
            sp,
            Microsoft.Extensions.Options.Options.Create(new LocalNodeOptions { HealthPort = 0 }),
            new Harborline.Api.LocalNodeHost.Capabilities.LocalNodeExecutableEndpointRegistry(),
            sp.GetRequiredService<Microsoft.Extensions.Logging.ILogger<SharedHostedWebApp>>(),
            sp.GetRequiredService<TimeProvider>());

        var endpoint = new HostedCommsApiEndpoint(
            sharedApp, registry, commsSigner, NodeTestActiveTeam.Accessor, new NodeCallerSessionToken(null), roster,
            new CommsDmFeatureFlag(enabled: false), sp.GetRequiredService<TimeProvider>(),
            NullLogger<HostedCommsApiEndpoint>.Instance);

        // FAIL-CLOSED: the roster binds the author to OTHER's key, not the comms signer's → StartAsync throws.
        var ex = await Assert.ThrowsAsync<System.InvalidOperationException>(
            () => endpoint.StartAsync(CancellationToken.None));
        Assert.Contains("author binding is inconsistent", ex.Message);

        await sharedApp.DisposeAsync();
    }
}

using System;

using Harborline.Api.LocalNodeHost.Data.Comms;

using Xunit;

namespace Harborline.Api.LocalNodeHost.Tests.Entities;

/// <summary>
/// C2 — the conversation DESCRIPTOR (<see cref="CommsConversationDescriptor"/>): the unifying
/// <c>{ conversationId, kind, participantPartyIds, visibilityScope }</c> value the access + (later C5) sync
/// layers key off. Proves the team-channel descriptor (Team + AllTeam + all-team sentinel), the DM descriptor
/// (DirectMessage + Participants + exactly-2), and the <see cref="CommsConversationDescriptor.Validate"/>
/// invariant the arch-test fence asserts.
/// </summary>
public sealed class CommsConversationDescriptorTests
{
    private const string Team = "team-office";

    // ── TEAM descriptor: Team + AllTeam + the "all team" sentinel (empty participant set). ──────────────────

    [Fact(DisplayName = "C2: the team descriptor is Team + AllTeam + the all-team sentinel (empty participant set)")]
    public void Team_Descriptor_Is_AllTeam_With_Empty_Participants()
    {
        var d = CommsConversationDescriptor.Team();
        Assert.Equal(CommsConversation.TeamConversationId, d.ConversationId);
        Assert.Equal(CommsConversationKind.Team, d.Kind);
        Assert.Equal(CommsVisibilityScope.AllTeam, d.VisibilityScope);
        Assert.Empty(d.ParticipantPartyIds); // the roster is resolved LIVE — empty = "all team".
        d.Validate(); // well-formed
        // Any member is a participant of the team channel (AllTeam).
        Assert.True(d.IsParticipant("anyone"));
    }

    // ── DM descriptor: DirectMessage + Participants + EXACTLY the two parties (order-independent). ───────────

    [Fact(DisplayName = "C2: the DM descriptor carries kind=DirectMessage, Participants scope, and the two parties")]
    public void Dm_Descriptor_Carries_Kind_Participants_And_The_Two_Parties()
    {
        var d = CommsConversationDescriptor.DirectMessage(Team, "alice", "bob");
        Assert.Equal(CommsConversationKind.DirectMessage, d.Kind);
        Assert.Equal(CommsVisibilityScope.Participants, d.VisibilityScope);
        Assert.Equal(2, d.ParticipantPartyIds.Count);
        Assert.Contains("alice", d.ParticipantPartyIds);
        Assert.Contains("bob", d.ParticipantPartyIds);
        // The id matches the deterministic derivation.
        Assert.Equal(DmConversationId.Derive(Team, "alice", "bob"), d.ConversationId);
        d.Validate(); // well-formed
    }

    [Fact(DisplayName = "C2: the DM descriptor is order-independent (alice,bob == bob,alice)")]
    public void Dm_Descriptor_Is_Order_Independent()
    {
        var ab = CommsConversationDescriptor.DirectMessage(Team, "alice", "bob");
        var ba = CommsConversationDescriptor.DirectMessage(Team, "bob", "alice");
        Assert.Equal(ab.ConversationId, ba.ConversationId);
        Assert.Equal(ab.ParticipantPartyIds, ba.ParticipantPartyIds); // sorted → identical order
    }

    [Fact(DisplayName = "C2: IsParticipant is the v1 ACL — only the two DM parties; a third party is NOT a participant")]
    public void Dm_IsParticipant_Is_The_V1_Acl()
    {
        var d = CommsConversationDescriptor.DirectMessage(Team, "alice", "bob");
        Assert.True(d.IsParticipant("alice"));
        Assert.True(d.IsParticipant("bob"));
        Assert.False(d.IsParticipant("carol")); // the leak adversary — a team member who is NOT a DM participant.
    }

    // ── DescriptorFor: id → descriptor resolution (team always; DM with the pair). ───────────────────────────

    [Fact(DisplayName = "C2: DescriptorFor resolves the team id to the all-team descriptor")]
    public void DescriptorFor_Team_Resolves_AllTeam()
    {
        var d = CommsConversation.DescriptorFor(CommsConversation.TeamConversationId);
        Assert.Equal(CommsConversationKind.Team, d.Kind);
        Assert.Equal(CommsVisibilityScope.AllTeam, d.VisibilityScope);
    }

    [Fact(DisplayName = "C2: DescriptorFor resolves a dm: id to the participant-scoped descriptor when given the pair")]
    public void DescriptorFor_Dm_Resolves_When_Pair_Matches()
    {
        var id = DmConversationId.Derive(Team, "alice", "bob");
        var d = CommsConversation.DescriptorFor(id, Team, "alice", "bob");
        Assert.Equal(CommsConversationKind.DirectMessage, d.Kind);
        Assert.Equal(id, d.ConversationId);
    }

    [Fact(DisplayName = "C2: DescriptorFor REJECTS a dm: id when the supplied pair derives to a different id")]
    public void DescriptorFor_Dm_Rejects_Mismatched_Pair()
    {
        var id = DmConversationId.Derive(Team, "alice", "bob");
        // Supplying carol instead of bob derives a DIFFERENT id → mismatch → reject (the identity binds the pair).
        Assert.Throws<InvalidOperationException>(() => CommsConversation.DescriptorFor(id, Team, "alice", "carol"));
    }

    // ── Validate: the C2 invariant — malformed descriptors are rejected. ────────────────────────────────────

    [Fact(DisplayName = "C2: Validate rejects a DM descriptor with the wrong participant count")]
    public void Validate_Rejects_Wrong_Participant_Count()
    {
        var malformed = new CommsConversationDescriptor(
            "dm:abc", CommsConversationKind.DirectMessage, new[] { "alice" }, CommsVisibilityScope.Participants);
        Assert.Throws<InvalidOperationException>(() => malformed.Validate());
    }

    [Fact(DisplayName = "C2: Validate rejects a DM descriptor whose id lacks the dm: prefix")]
    public void Validate_Rejects_Dm_Without_Prefix()
    {
        var malformed = new CommsConversationDescriptor(
            "not-a-dm", CommsConversationKind.DirectMessage, new[] { "alice", "bob" }, CommsVisibilityScope.Participants);
        Assert.Throws<InvalidOperationException>(() => malformed.Validate());
    }

    [Fact(DisplayName = "C2: Validate rejects a DM descriptor with AllTeam visibility (a DM must be Participants)")]
    public void Validate_Rejects_Dm_With_AllTeam_Visibility()
    {
        var malformed = new CommsConversationDescriptor(
            "dm:abc", CommsConversationKind.DirectMessage, new[] { "alice", "bob" }, CommsVisibilityScope.AllTeam);
        Assert.Throws<InvalidOperationException>(() => malformed.Validate());
    }

    [Fact(DisplayName = "C2: Validate rejects a Team descriptor that carries a non-empty participant set")]
    public void Validate_Rejects_Team_With_Participants()
    {
        var malformed = new CommsConversationDescriptor(
            CommsConversation.TeamConversationId, CommsConversationKind.Team,
            new[] { "alice" }, CommsVisibilityScope.AllTeam);
        Assert.Throws<InvalidOperationException>(() => malformed.Validate());
    }
}

using System.Net;
using System.Net.Http.Json;
using System.Text.Json;

using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Hosting.Server;
using Microsoft.AspNetCore.Hosting.Server.Features;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Logging.Abstractions;

using Harborline.Api.Foundation.Crypto;
using Harborline.Api.Kernel.Crdt;
using Harborline.Api.Kernel.Crdt.Backends;
using Harborline.Api.Kernel.Sync.Application;
using Harborline.Api.Kernel.Sync.DependencyInjection;
using Harborline.Api.LocalNodeHost.Data.Comms;
using Harborline.Api.LocalNodeHost.Health;

namespace Harborline.Api.LocalNodeHost.Tests.Entities;

/// <summary>
/// C1 — CONVERSATION SCOPE: the comms doctype now carries a conversation dimension. These tests prove the C1
/// success criteria over the real in-process Kestrel listener + the real conversation registry:
/// <list type="bullet">
///   <item>the TEAM conversation (<c>"team"</c>) round-trips identically over BOTH the bare
///     <c>/api/local-node/comms</c> route (back-compat) AND the conversation-addressed
///     <c>/api/local-node/comms/team</c> route;</item>
///   <item>a NON-TEAM conversation id round-trips (append + read) and is SCOPED — its messages do NOT bleed
///     into the team channel and vice-versa;</item>
///   <item>each conversation is its OWN CRDT document on the delta router (one document per conversation);</item>
///   <item>the migration is additive — an existing pre-C1 row (no conversation_id) back-fills to <c>"team"</c>
///     and reads back on the team channel.</item>
/// </list>
/// Mirrors <see cref="CommsRouteTests"/> but exercises the registry-backed conversation addressing.
/// </summary>
public sealed class CommsConversationScopeTests : IAsyncLifetime
{
    private WebApplication _app = null!;
    private HttpClient _client = null!;
    private string _dir = null!;
    private CommsConversationRegistry _registry = null!;
    private NodePrincipalSigner _signer = null!;
    private IDbContextFactory<NodeLocalCommsDbContext> _factory = null!;

    public async Task InitializeAsync()
    {
        var builder = WebApplication.CreateBuilder();
        // Ticket 294 slice 3b: the desktop actor (no compile-time operator id).
        Harborline.Api.LocalNodeHost.Tests.Authorization.TestDesktopOperator.AddTestDesktopOperator(builder.Services);
        builder.WebHost.UseUrls("http://127.0.0.1:0");
        builder.Logging.ClearProviders();

        _dir = Path.Combine(Path.GetTempPath(), "harborline-comms-convscope-" + Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(_dir);
        var connectionString = $"Data Source={Path.Combine(_dir, "comms.db")};Pooling=False";

        builder.Services.AddDbContextFactory<NodeLocalCommsDbContext>(opt => opt.UseSqlite(connectionString));
        builder.Services.AddSingleton<ICrdtEngine, YDotNetCrdtEngine>();
        builder.Services.AddHarborlineDeltaRouter();

        _app = builder.Build();

        _factory = _app.Services.GetRequiredService<IDbContextFactory<NodeLocalCommsDbContext>>();
        // EnsureCreated builds the CURRENT model (incl. the conversation_id column) — the conversation-scoped
        // read path depends on it.
        await using (var ctx = await _factory.CreateDbContextAsync())
            await ctx.Database.EnsureCreatedAsync();

        _registry = new CommsConversationRegistry(
            _app.Services.GetRequiredService<ICrdtEngine>(), _factory, new Ed25519Verifier(),
            _app.Services.GetRequiredService<IDeltaRouter>(),
            _app.Services.GetRequiredService<ILoggerFactory>());

        var seed = new byte[32];
        for (var i = 0; i < seed.Length; i++) seed[i] = (byte)(i + 1);
        _signer = new NodePrincipalSigner(seed);

        // Map the SHIPPING registry-backed routes (bare + conversation-addressed).
        CommsRoutes.Map(_app, _registry, _signer.Signer, NodeTestActiveTeam.Accessor,
            new NodeCallerSessionToken(null), "alice", TimeProvider.System);

        await _app.StartAsync();

        var addresses = _app.Services.GetRequiredService<IServer>().Features.Get<IServerAddressesFeature>();
        _client = new HttpClient { BaseAddress = new Uri(addresses!.Addresses.First()) };
    }

    public async Task DisposeAsync()
    {
        _client?.Dispose();
        _signer?.Dispose();
        await _registry.DisposeAsync();
        await _app.StopAsync();
        await _app.DisposeAsync();
        try { if (Directory.Exists(_dir)) Directory.Delete(_dir, recursive: true); }
        catch { /* best-effort temp cleanup */ }
    }

    private const string BareRoute = "/api/local-node/comms";
    private const string TeamRoute = "/api/local-node/comms/team";

    private static string[] Bodies(JsonElement doc) =>
        doc.GetProperty("messages").EnumerateArray().Select(m => m.GetProperty("body").GetString()!).ToArray();

    // ── (a) the team conversation round-trips identically via BOTH the bare + conversation-addressed route ───

    [Fact(DisplayName = "C1: the team conversation round-trips identically via the bare route AND /comms/team")]
    public async Task TeamConversation_RoundTrips_Via_BareAnd_ConversationRoute()
    {
        // Append via the BARE route (back-compat — defaults to "team").
        Assert.Equal(HttpStatusCode.Created, (await _client.PostAsJsonAsync(BareRoute, new { body = "bare-1" })).StatusCode);
        // Append via the CONVERSATION-ADDRESSED team route.
        Assert.Equal(HttpStatusCode.Created, (await _client.PostAsJsonAsync(TeamRoute, new { body = "team-2" })).StatusCode);

        // Both routes read the SAME team log (the bare route == /comms/team).
        var viaBare = await _client.GetFromJsonAsync<JsonElement>(BareRoute);
        var viaTeam = await _client.GetFromJsonAsync<JsonElement>(TeamRoute);
        Assert.Equal(new[] { "bare-1", "team-2" }, Bodies(viaBare));
        Assert.Equal(new[] { "bare-1", "team-2" }, Bodies(viaTeam));

        // The wire carries the conversation id, stamped "team" on both.
        foreach (var m in viaBare.GetProperty("messages").EnumerateArray())
            Assert.Equal("team", m.GetProperty("conversationId").GetString());
    }

    // ── (b) a non-team conversation round-trips AND is isolated from the team channel ────────────────────────

    [Fact(DisplayName = "C1: a non-team conversation round-trips (append + read scoped) and is ISOLATED from the team channel")]
    public async Task NonTeamConversation_RoundTrips_AndIsIsolated()
    {
        const string convId = "dm:roundtrip-example";
        var convRoute = $"/api/local-node/comms/{convId}";

        // Append to the team channel + the non-team conversation.
        Assert.Equal(HttpStatusCode.Created, (await _client.PostAsJsonAsync(TeamRoute, new { body = "team only" })).StatusCode);
        Assert.Equal(HttpStatusCode.Created, (await _client.PostAsJsonAsync(convRoute, new { body = "conv only" })).StatusCode);

        // The non-team conversation reads back ONLY its own message (scoped append + read).
        var conv = await _client.GetFromJsonAsync<JsonElement>(convRoute);
        Assert.Equal(new[] { "conv only" }, Bodies(conv));
        Assert.Equal(convId, conv.GetProperty("messages")[0].GetProperty("conversationId").GetString());

        // The team channel reads back ONLY its own message — no bleed from the non-team conversation.
        var team = await _client.GetFromJsonAsync<JsonElement>(TeamRoute);
        Assert.Equal(new[] { "team only" }, Bodies(team));

        // The registry created a distinct projection per conversation (one document per conversation).
        Assert.Contains("team", _registry.ActiveConversationIds);
        Assert.Contains(convId, _registry.ActiveConversationIds);
        // Distinct CRDT documents → distinct router streams.
        var router = _app.Services.GetRequiredService<IDeltaRouter>();
        Assert.Contains("team", router.RegisteredDocumentIds);
        Assert.Contains(convId, router.RegisteredDocumentIds);
    }

    // ── (b') the durable rows are conversation-scoped in the ONE shared table ────────────────────────────────

    [Fact(DisplayName = "C1: messages from two conversations share the ONE messages table, scoped by conversation_id")]
    public async Task TwoConversations_ShareTable_ScopedByColumn()
    {
        await _client.PostAsJsonAsync(TeamRoute, new { body = "t" });
        await _client.PostAsJsonAsync("/api/local-node/comms/dm:scoped", new { body = "d" });

        await using var ctx = await _factory.CreateDbContextAsync();
        var rows = await ctx.Set<NodeMessage>().AsNoTracking().OrderBy(m => m.Body).ToListAsync();
        Assert.Equal(2, rows.Count); // one table, two rows
        Assert.Equal("d", rows[0].Body);
        Assert.Equal("dm:scoped", rows[0].ConversationId);
        Assert.Equal("t", rows[1].Body);
        Assert.Equal("team", rows[1].ConversationId);
    }

    // ── (c) the migration is additive — a pre-C1 row (no conversation_id) back-fills to "team" ──────────────

    [Fact(DisplayName = "C1: an existing pre-C1 row (inserted with the column default) back-fills to \"team\" and reads on the team channel")]
    public async Task PreC1Row_BackFills_To_Team_And_ReadsOnTeamChannel()
    {
        // Simulate a pre-C1 durable row: insert via raw SQL WITHOUT the conversation_id column, so SQLite
        // applies the column DEFAULT ('team') the additive migration set — exactly the back-fill an upgraded
        // node sees for its existing team log.
        await using (var ctx = await _factory.CreateDbContextAsync())
        {
            await ctx.Database.ExecuteSqlRawAsync(
                "INSERT INTO messages (id, tenant_id, author_party_id, author_issuer_id, body, nonce, signature, authored_at) " +
                "VALUES ('preC1-id', {0}, 'alice', 'issuer', 'pre-C1 team message', 'nonce', 'sig', {1})",
                NodeTestActiveTeam.TestTeamId.Value.ToString(),
                DateTimeOffset.UtcNow.ToUnixTimeMilliseconds());

            // The row took the column default.
            var backfilled = await ctx.Set<NodeMessage>().AsNoTracking().SingleAsync(m => m.Id == "preC1-id");
            Assert.Equal("team", backfilled.ConversationId);
        }

        // And it reads back on the TEAM channel (the bare route) — the pre-C1 team log is preserved.
        var team = await _client.GetFromJsonAsync<JsonElement>(BareRoute);
        Assert.Contains("pre-C1 team message", Bodies(team));
    }

    // ── unknown conversation behaviour: the registry creates lazily, so any id is a valid (empty) thread ─────

    [Fact(DisplayName = "C1: GET on a never-used conversation returns an empty log (the registry creates it lazily)")]
    public async Task UnusedConversation_Returns_EmptyLog()
    {
        var doc = await _client.GetFromJsonAsync<JsonElement>("/api/local-node/comms/dm:never-used");
        Assert.Empty(Bodies(doc));
    }
}

using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Logging.Abstractions;

using Harborline.Api.Foundation.Crypto;
using Harborline.Api.Kernel.Crdt;
using Harborline.Api.Kernel.Crdt.Backends;
using Harborline.Api.LocalNodeHost.Data.Comms;

namespace Harborline.Api.LocalNodeHost.Tests.Entities;

/// <summary>
/// Acceptance coverage for the comms append-log doctype — the FIRST messaging doctype on the live node-host
/// path. Proves the core property: two replicas, two DISTINCT authors, each appending messages, converge to
/// the SAME ordered log, with every message attributed to its author. This is the list (append-log) analogue
/// of <c>ContactCrdtConvergenceTests</c> — the contacts doctype proves map convergence; this proves
/// append-only ORDERED-list convergence.
/// </summary>
/// <remarks>
/// <para>
/// <b>Two in-proc replicas, NO networking.</b> Convergence is proven with two in-process
/// <see cref="CommsCrdtProjection"/> replicas (each over its own CRDT engine + its own SQLite store)
/// exchanging deltas directly — simulating the gossip daemon's produce/consume round.
/// </para>
/// <para>
/// <b>Real YDotNet backend.</b> The convergence assertions exercise the production
/// <see cref="YDotNetCrdtEngine"/> (Yjs/yrs) — the stub's replay cannot honestly test concurrent-append
/// list convergence, so these tests pin the real backend.
/// </para>
/// <para>
/// <b>Two distinct authors.</b> Each author is a distinct Ed25519 keypair + a distinct member PartyId. The
/// messages they append carry their own signed identity, so a peer can tell — and verify — which author
/// wrote each message on the converged log.
/// </para>
/// </remarks>
public sealed class CommsCrdtConvergenceTests : IAsyncLifetime
{
    private readonly List<Replica> _replicas = new();

    public Task InitializeAsync() => Task.CompletedTask;

    public async Task DisposeAsync()
    {
        foreach (var r in _replicas) await r.DisposeAsync();
    }

    private const string Tenant = "team-7e57";

    // ── Two distinct authors: distinct keypair + distinct member id ──────────────────────────────────────
    private sealed class Author
    {
        public required string PartyId { get; init; }
        public required IOperationSigner Signer { get; init; }
        public required KeyPair KeyPair { get; init; }

        public static Author New(string partyId)
        {
            var kp = KeyPair.Generate();
            return new Author { PartyId = partyId, Signer = new Ed25519Signer(kp), KeyPair = kp };
        }
    }

    private static readonly Author Alice = Author.New("alice");
    private static readonly Author Bob = Author.New("bob");
    private static readonly IOperationVerifier Verifier = new Ed25519Verifier();

    // ── A small in-proc replica: own CRDT engine, own SQLite store, own projection ──────────────────────
    private sealed class Replica : IAsyncDisposable
    {
        public required string Name { get; init; }
        public required string Dir { get; init; }
        public required ServiceProvider Sp { get; init; }
        public required IDbContextFactory<NodeLocalCommsDbContext> Factory { get; init; }
        public required CommsCrdtProjection Projection { get; init; }

        public async ValueTask DisposeAsync()
        {
            await Projection.DisposeAsync();
            await Sp.DisposeAsync();
            try { if (Directory.Exists(Dir)) Directory.Delete(Dir, recursive: true); }
            catch { /* best-effort temp cleanup */ }
        }
    }

    private Task<Replica> NewReplicaAsync(string name) => NewReplicaAsync(name, rosterBinding: null);

    private async Task<Replica> NewReplicaAsync(
        string name, Func<string, PrincipalId?>? rosterBinding, ILogger<CommsCrdtProjection>? logger = null)
    {
        var dir = Path.Combine(Path.GetTempPath(), $"harborline-comms-crdt-{name}-{Guid.NewGuid():N}");
        Directory.CreateDirectory(dir);
        var connectionString = $"Data Source={Path.Combine(dir, "comms.db")};Pooling=False";

        var services = new ServiceCollection();
        services.AddLogging();
        services.AddDbContextFactory<NodeLocalCommsDbContext>(opt => opt.UseSqlite(connectionString));
        services.AddSingleton<ICrdtEngine, YDotNetCrdtEngine>();

        var sp = services.BuildServiceProvider();
        var factory = sp.GetRequiredService<IDbContextFactory<NodeLocalCommsDbContext>>();
        await using (var ctx = await factory.CreateDbContextAsync())
            await ctx.Database.EnsureCreatedAsync();

        // rosterBinding null = pre-enrollment merge gate (B1a integrity); non-null = forge-proof merge gate (B1b).
        var projection = new CommsCrdtProjection(
            sp.GetRequiredService<ICrdtEngine>(),
            factory,
            Verifier,
            logger ?? NullLogger<CommsCrdtProjection>.Instance,
            rosterBinding);

        var replica = new Replica { Name = name, Dir = dir, Sp = sp, Factory = factory, Projection = projection };
        _replicas.Add(replica);
        return replica;
    }

    /// <summary>Append a signed message by <paramref name="author"/> the way <c>CommsRoutes</c> does
    /// (EF-first via PersistLocalAsync, then push onto the CRDT list).</summary>
    private static async Task<MessageCrdtState> AppendAsync(
        Replica r, Author author, string body, DateTimeOffset authoredAt)
    {
        var message = await CommsMessageFactory.CreateSignedAsync(
            author.Signer, author.PartyId, Tenant, body, authoredAt);
        await r.Projection.PersistLocalAsync(message, CancellationToken.None);
        r.Projection.AppendLocal(message);
        return message;
    }

    /// <summary>Read the durable EF log (the GET path's source) in authored order.</summary>
    private static Task<IReadOnlyList<MessageCrdtState>> ReadLogAsync(Replica r) =>
        r.Projection.ReadLogAsync(Tenant, CancellationToken.None);

    /// <summary>One direction of a sync round on the LIVE trigger: encode src's outbound delta against
    /// dst's clock, apply it to dst, then await the reconciles the projection's Changed→reconcile handler
    /// spawned (the production path — no explicit ReconcileAsync).</summary>
    private static async Task SyncAsync(Replica src, Replica dst)
    {
        var delta = await src.Projection.EncodeOutboundDeltaAsync(
            CommsCrdtProjection.DocumentId, dst.Projection.VectorClock, CancellationToken.None);
        Assert.NotNull(delta);
        await dst.Projection.ApplyInboundDeltaAsync(
            CommsCrdtProjection.DocumentId, 1, delta!.Value, CancellationToken.None);
        await dst.Projection.DrainPendingReconcilesAsync();
    }

    /// <summary>The full bidirectional anti-entropy round: each encodes against the OTHER's pre-exchange
    /// clock, both apply, both reconcile — the order-independent convergence both replicas reach.</summary>
    private static async Task ExchangeAsync(Replica a, Replica b)
    {
        var aClock = a.Projection.VectorClock;
        var bClock = b.Projection.VectorClock;
        var aDelta = await a.Projection.EncodeOutboundDeltaAsync(CommsCrdtProjection.DocumentId, bClock, CancellationToken.None);
        var bDelta = await b.Projection.EncodeOutboundDeltaAsync(CommsCrdtProjection.DocumentId, aClock, CancellationToken.None);
        await b.Projection.ApplyInboundDeltaAsync(CommsCrdtProjection.DocumentId, 1, aDelta!.Value, CancellationToken.None);
        await a.Projection.ApplyInboundDeltaAsync(CommsCrdtProjection.DocumentId, 1, bDelta!.Value, CancellationToken.None);
        await a.Projection.DrainPendingReconcilesAsync();
        await b.Projection.DrainPendingReconcilesAsync();
    }

    private static IReadOnlyList<(string Author, string Body)> OrderedAuthorBodies(IReadOnlyList<MessageCrdtState> log) =>
        log.Select(m => (m.AuthorPartyId, m.Body)).ToList();

    // ── Test 1: one author appends on A → message reaches B's readable log, attributed ──────────────────

    [Fact(DisplayName = "comms: append on A → delta → appears in B's readable log, attributed to its author")]
    public async Task Append_On_A_Appears_On_B_Attributed()
    {
        var a = await NewReplicaAsync("A");
        var b = await NewReplicaAsync("B");

        var t0 = DateTimeOffset.UtcNow;
        var msg = await AppendAsync(a, Alice, "hello team", t0);

        await SyncAsync(a, b);

        var bLog = await ReadLogAsync(b);
        Assert.Single(bLog);
        Assert.Equal("hello team", bLog[0].Body);
        // Attributed to its author (Alice's member id + Alice's signing key), and the signature verifies.
        Assert.Equal("alice", bLog[0].AuthorPartyId);
        Assert.Equal(msg.AuthorIssuerId, bLog[0].AuthorIssuerId);
        Assert.True(CommsMessageFactory.VerifyAuthorship(bLog[0], Verifier));
    }

    // ── Test 2: TWO DISTINCT AUTHORS converge in append-order, each attributed (the core proof) ─────────

    [Fact(DisplayName = "comms: two distinct authors converge to the SAME ordered log, each attributed (CORE)")]
    public async Task Two_Distinct_Authors_Converge_In_Append_Order_Attributed()
    {
        var a = await NewReplicaAsync("A");
        var b = await NewReplicaAsync("B");

        // Alice appends on A; Bob appends on B — concurrently, neither seen by the other yet.
        var t0 = DateTimeOffset.UtcNow;
        var aliceMsg = await AppendAsync(a, Alice, "Alice: standup at 10?", t0);
        var bobMsg   = await AppendAsync(b, Bob,   "Bob: works for me",     t0.AddSeconds(1));

        // Each replica sees only its own message so far.
        Assert.Single(await ReadLogAsync(a));
        Assert.Single(await ReadLogAsync(b));

        // Full bidirectional round.
        await ExchangeAsync(a, b);

        var aLog = await ReadLogAsync(a);
        var bLog = await ReadLogAsync(b);

        // CONVERGENCE: both replicas hold BOTH messages (the union — no append lost).
        Assert.Equal(2, aLog.Count);
        Assert.Equal(2, bLog.Count);

        // The CRDT list converged to the SAME deterministic total order on both replicas.
        var aOrder = a.Projection.Snapshot().Select(m => m.MessageId).ToList();
        var bOrder = b.Projection.Snapshot().Select(m => m.MessageId).ToList();
        Assert.Equal(aOrder, bOrder); // same order on both — CRDT-list convergence

        // ATTRIBUTION: the two distinct authors are distinguishable on the converged log. Each message
        // carries its own author's member id + signing key, and each signature verifies against that key.
        var byId = aLog.ToDictionary(m => m.MessageId);
        Assert.Equal("alice", byId[aliceMsg.MessageId].AuthorPartyId);
        Assert.Equal("bob",   byId[bobMsg.MessageId].AuthorPartyId);
        Assert.NotEqual(byId[aliceMsg.MessageId].AuthorIssuerId, byId[bobMsg.MessageId].AuthorIssuerId);
        Assert.All(aLog, m => Assert.True(CommsMessageFactory.VerifyAuthorship(m, Verifier)));
        Assert.All(bLog, m => Assert.True(CommsMessageFactory.VerifyAuthorship(m, Verifier)));
    }

    // ── Test 3: concurrent interleaved appends from both authors converge deterministically ─────────────

    [Fact(DisplayName = "comms: interleaved concurrent appends from both authors converge deterministically")]
    public async Task Interleaved_Concurrent_Appends_Converge_Deterministically()
    {
        var a = await NewReplicaAsync("A");
        var b = await NewReplicaAsync("B");

        var t0 = DateTimeOffset.UtcNow;
        // A burst of concurrent appends on BOTH replicas before any exchange — the interleave the CRDT must
        // resolve to one deterministic order.
        await AppendAsync(a, Alice, "A1", t0);
        await AppendAsync(b, Bob,   "B1", t0.AddMilliseconds(5));
        await AppendAsync(a, Alice, "A2", t0.AddMilliseconds(10));
        await AppendAsync(b, Bob,   "B2", t0.AddMilliseconds(15));
        await AppendAsync(a, Alice, "A3", t0.AddMilliseconds(20));

        await ExchangeAsync(a, b);

        var aSnap = a.Projection.Snapshot();
        var bSnap = b.Projection.Snapshot();

        // Both replicas hold all 5 messages and AGREE on the order (deterministic convergence).
        Assert.Equal(5, aSnap.Count);
        Assert.Equal(5, bSnap.Count);
        Assert.Equal(aSnap.Select(m => m.MessageId), bSnap.Select(m => m.MessageId));

        // The EF read models also converge to the same set (authored order in the read model).
        var aBodies = (await ReadLogAsync(a)).Select(m => m.Body).ToHashSet();
        var bBodies = (await ReadLogAsync(b)).Select(m => m.Body).ToHashSet();
        Assert.Equal(new[] { "A1", "A2", "A3", "B1", "B2" }.ToHashSet(), aBodies);
        Assert.Equal(aBodies, bBodies);
    }

    // ── Test 4: append-only — applying the same inbound delta twice is idempotent (no duplicate row) ────

    [Fact(DisplayName = "comms: applying the same inbound delta twice is idempotent (no duplicate message)")]
    public async Task Delta_Apply_Is_Idempotent()
    {
        var a = await NewReplicaAsync("A");
        var b = await NewReplicaAsync("B");

        var msg = await AppendAsync(a, Alice, "once", DateTimeOffset.UtcNow);
        var delta = await a.Projection.EncodeOutboundDeltaAsync(
            CommsCrdtProjection.DocumentId, b.Projection.VectorClock, CancellationToken.None);

        await b.Projection.ApplyInboundDeltaAsync(CommsCrdtProjection.DocumentId, 1, delta!.Value, CancellationToken.None);
        await b.Projection.ApplyInboundDeltaAsync(CommsCrdtProjection.DocumentId, 2, delta!.Value, CancellationToken.None);
        await b.Projection.DrainPendingReconcilesAsync();

        Assert.Equal(1, b.Projection.Count);
        var bLog = await ReadLogAsync(b);
        Assert.Single(bLog);
        Assert.Equal(msg.MessageId, bLog[0].MessageId);
    }

    // ── Test 5: signature proves message INTEGRITY (a mutated signed message fails) ──────────────────────
    // NOTE: this proves INTEGRITY only — that you cannot MUTATE an already-signed message. It does NOT prove
    // the AuthorPartyId↔AuthorIssuerId binding on its own (the integrity-only check); the party↔key binding is
    // proven forge-proof by the roster-aware overload, covered by Forged_Foreign_Party_Is_Rejected_By_Roster_Binding
    // (B1b CLOSED) below.

    [Fact(DisplayName = "comms: mutating an already-signed message fails verification (INTEGRITY only)")]
    public async Task Mutated_Signed_Message_Fails_Verification()
    {
        var a = await NewReplicaAsync("A");
        var msg = await AppendAsync(a, Alice, "authentic body", DateTimeOffset.UtcNow);

        Assert.True(CommsMessageFactory.VerifyAuthorship(msg, Verifier));

        // Tamper the body (record with-expression) — the signature no longer covers it.
        var tampered = msg with { Body = "forged body" };
        Assert.False(CommsMessageFactory.VerifyAuthorship(tampered, Verifier));

        // Re-attributing an ALREADY-SIGNED message to a DIFFERENT partyId without re-signing also fails
        // (partyId is inside the signed payload). NOTE: this is NOT the same as forging — see the
        // foreign-party FRESH-sign test below, which DOES pass (the known enrollment gap).
        var misattributed = msg with { AuthorPartyId = "bob" };
        Assert.False(CommsMessageFactory.VerifyAuthorship(misattributed, Verifier));
    }

    // ── Test 5b: VERIFY-IS-ENFORCED-ON-MERGE — an invalid-signature message is DROPPED (#1277 B1a) ───────
    // This is the honest replacement for the false "misattribution fails verification" claim. It proves the
    // gate that actually matters: a garbage/unsigned peer message is NOT stored, NOT returned by the read
    // path. Fails PRE-FIX (before this PR, reconcile did zero verification → the message landed in EF).

    [Fact(DisplayName = "comms: an INVALID-signature peer message is DROPPED on merge — not stored, not in GET (B1a)")]
    public async Task Invalid_Signature_Peer_Message_Is_Dropped_On_Merge()
    {
        var src = await NewReplicaAsync("src");
        var dst = await NewReplicaAsync("dst");

        // A legitimately-signed message (valid sig for its stamped key) — the legit path: this MUST merge.
        var good = await AppendAsync(src, Alice, "legit message", DateTimeOffset.UtcNow);

        // A garbage-signed message: a real Alice-signed message whose BODY was then mutated, so its signature
        // no longer validates. Push it straight onto src's CRDT list (the source of outbound deltas) WITHOUT a
        // local EF write — exactly what a malicious/garbage peer delta looks like on the wire.
        var authentic = await CommsMessageFactory.CreateSignedAsync(
            Alice.Signer, Alice.PartyId, Tenant, "authentic", DateTimeOffset.UtcNow);
        var garbage = authentic with { Body = "tampered-after-signing", MessageId = Guid.NewGuid().ToString("D") };
        Assert.False(CommsMessageFactory.VerifyAuthorship(garbage, Verifier)); // sanity: it does NOT verify
        src.Projection.AppendLocal(garbage); // place it on src's list so it ships in the delta

        // Sync src → dst over the LIVE merge→reconcile trigger (the production path).
        await SyncAsync(src, dst);

        // The CRDT list converged (merge-everything) — dst's list holds BOTH (convergence is by design)...
        Assert.Equal(2, dst.Projection.Count);

        // ...but the durable read store + GET path are GATED: only the valid message landed; the garbage one
        // was DROPPED on merge (verify-on-merge enforcement). PRE-FIX this asserted 2 — the garbage row was
        // stored.
        var dstLog = await ReadLogAsync(dst);
        Assert.Single(dstLog);
        Assert.Equal(good.MessageId, dstLog[0].MessageId);
        Assert.Equal("legit message", dstLog[0].Body);
        Assert.DoesNotContain(dstLog, m => m.MessageId == garbage.MessageId);
    }

    [Fact(DisplayName = "T-909 ck-9: a peer message whose authored instant does not parse is dropped once, logged for its instant, and the rest of the delta lands")]
    [Trait("Holds", "kernel-core-ck-9")]
    public async Task Peer_message_with_an_unparseable_instant_is_dropped_once_and_the_rest_lands()
    {
        var logger = new RecordingLogger();
        var src = await NewReplicaAsync("src");
        var dst = await NewReplicaAsync("dst", rosterBinding: null, logger);

        // Pushed straight onto src's CRDT list (no local EF write), ahead of a legitimate message.
        var signed = await CommsMessageFactory.CreateSignedAsync(
            Alice.Signer, Alice.PartyId, Tenant, "undated", DateTimeOffset.UtcNow);
        var undated = signed with { MessageId = Guid.NewGuid().ToString("D"), AuthoredAtIso = "not-an-instant" };
        src.Projection.AppendLocal(undated);
        var good = await AppendAsync(src, Alice, "legit message", DateTimeOffset.UtcNow);

        await SyncAsync(src, dst);

        var dstLog = await ReadLogAsync(dst);
        Assert.Equal(good.MessageId, Assert.Single(dstLog).MessageId);
        var dropped = Assert.Single(logger.Warnings, warning => warning.Contains(undated.MessageId, StringComparison.Ordinal));
        Assert.Contains("authored instant does not parse", dropped, StringComparison.Ordinal);
    }

    // ── Test 5c: FORGE-PROOF ATTRIBUTION — the foreign-party forgery is now REJECTED (#1277 B1b CLOSED) ───
    // THE PAYOFF OF THE ROSTER (enrollment Phase A). An attacker signs a FRESH message with their OWN key while
    // stamping a VICTIM's partyId. PRE-enrollment this PASSED (the signature is valid for the attacker's stamped
    // key, and nothing bound key→party). Now the roster binds alice→Alice's key + bob→Bob's key, and the
    // forge-proof overload checks the message's stamped key AGAINST that binding for the claimed party — so
    // Bob's key signing under "alice" FAILS (Bob's key ≠ Alice's roster-bound key). This flips the old
    // "still passes" gap test into the enforcement regression test that proves the forgery is rejected.

    [Fact(DisplayName = "comms: a foreign-party FORGED message is REJECTED by forge-proof attribution (B1b CLOSED)")]
    public async Task Forged_Foreign_Party_Is_Rejected_By_Roster_Binding()
    {
        // The verified roster's party→pubkey binding (what MemberRoster.PublicKeyOf returns): alice→Alice's key,
        // bob→Bob's key. A party not in this map has no binding → fail-closed.
        PrincipalId? RosterBinding(string partyId) => partyId switch
        {
            "alice" => Alice.KeyPair.PrincipalId,
            "bob" => Bob.KeyPair.PrincipalId,
            _ => null,
        };

        // Attacker = Bob's keypair (his own valid signing key), but he stamps Alice's partyId.
        var forged = await CommsMessageFactory.CreateSignedAsync(
            Bob.Signer, authorPartyId: Alice.PartyId, tenantId: Tenant, body: "I am Alice (forged)",
            authoredAt: DateTimeOffset.UtcNow);

        // Sanity: the forgery is integrity-valid (Bob's key DID validly sign it) — so the OLD integrity-only
        // check still passes. That is exactly why integrity alone was theater (#1277 B1b).
        Assert.True(CommsMessageFactory.VerifyAuthorship(forged, Verifier));

        // THE PROOF: the forge-proof overload REJECTS it — the stamped issuer (Bob's key) is NOT the roster's
        // bound key for the claimed party (alice → Alice's key). #1277 B1 CLOSED.
        Assert.False(CommsMessageFactory.VerifyAuthorship(forged, Verifier, RosterBinding));

        // And a LEGITIMATE message — Alice signing as alice with her own (roster-bound) key — still PASSES the
        // forge-proof check (the gate doesn't break honest attribution).
        var legit = await CommsMessageFactory.CreateSignedAsync(
            Alice.Signer, authorPartyId: Alice.PartyId, tenantId: Tenant, body: "I really am Alice",
            authoredAt: DateTimeOffset.UtcNow);
        Assert.True(CommsMessageFactory.VerifyAuthorship(legit, Verifier, RosterBinding));

        // An UN-ENROLLED author (no roster binding) is also rejected fail-closed — you cannot attribute a
        // message to a party who is not a verified member.
        var unenrolled = await CommsMessageFactory.CreateSignedAsync(
            Bob.Signer, authorPartyId: "stranger", tenantId: Tenant, body: "hi", authoredAt: DateTimeOffset.UtcNow);
        Assert.False(CommsMessageFactory.VerifyAuthorship(unenrolled, Verifier, RosterBinding));
    }

    // ── Test 5d: FORGE-PROOF ON THE LIVE MERGE PATH — the forgery is DROPPED end-to-end (B1b CLOSED) ──────
    // The unit check above proves the gate logic; this proves it ENFORCED on the production merge→reconcile
    // path when a roster binding is wired into the projection. A forged peer message (Bob's key claiming
    // Alice's partyId) ships over the wire, the CRDT converges (merge-everything by design), but the
    // forge-proof verify-on-merge gate DROPS it — it never lands in the EF read store / GET. A legitimate
    // Alice message in the same round IS stored.

    [Fact(DisplayName = "comms: a forged-party peer message is DROPPED on the live merge path (forge-proof, B1b)")]
    public async Task Forged_Peer_Message_Is_Dropped_On_Merge_With_Roster()
    {
        PrincipalId? RosterBinding(string partyId) => partyId switch
        {
            "alice" => Alice.KeyPair.PrincipalId,
            "bob" => Bob.KeyPair.PrincipalId,
            _ => null,
        };

        var src = await NewReplicaAsync("src");                      // attacker's source (no gate needed to emit)
        var dst = await NewReplicaAsync("dst", RosterBinding);       // victim's node — forge-proof merge gate

        // A legitimate Alice message (alice signed with Alice's roster-bound key) — MUST survive the gate.
        var good = await AppendAsync(src, Alice, "legit from alice", DateTimeOffset.UtcNow);

        // The forgery: Bob's key signs a FRESH message stamping Alice's partyId. Push straight onto src's CRDT
        // list (the source of outbound deltas) — exactly what a malicious peer delta looks like.
        var forged = await CommsMessageFactory.CreateSignedAsync(
            Bob.Signer, authorPartyId: Alice.PartyId, tenantId: Tenant, body: "I am Alice (forged)",
            authoredAt: DateTimeOffset.UtcNow);
        Assert.True(CommsMessageFactory.VerifyAuthorship(forged, Verifier));                  // integrity-valid...
        Assert.False(CommsMessageFactory.VerifyAuthorship(forged, Verifier, RosterBinding));  // ...but a forgery
        src.Projection.AppendLocal(forged);

        await SyncAsync(src, dst);

        // The CRDT list converged (both items present — merge-everything)...
        Assert.Equal(2, dst.Projection.Count);

        // ...but the durable read store + GET are GATED by forge-proof attribution: only Alice's legitimate
        // message landed; the forgery was DROPPED on merge. #1277 B1 CLOSED on the live path.
        var dstLog = await ReadLogAsync(dst);
        Assert.Single(dstLog);
        Assert.Equal(good.MessageId, dstLog[0].MessageId);
        Assert.DoesNotContain(dstLog, m => m.MessageId == forged.MessageId);
    }

    // ── Test 6: cold-start hydration re-seeds the CRDT list from the durable store ──────────────────────

    [Fact(DisplayName = "comms: cold-start hydration re-seeds the CRDT list from the recoverable store")]
    public async Task Hydration_Reseeds_From_Durable_Store()
    {
        var a = await NewReplicaAsync("A");

        // Append two messages (EF + CRDT), then build a FRESH projection over the SAME EF store and hydrate.
        var t0 = DateTimeOffset.UtcNow;
        await AppendAsync(a, Alice, "persisted 1", t0);
        await AppendAsync(a, Bob,   "persisted 2", t0.AddSeconds(1));

        await using var fresh = new CommsCrdtProjection(
            new YDotNetCrdtEngine(), a.Factory, Verifier, NullLogger<CommsCrdtProjection>.Instance);
        Assert.Equal(0, fresh.Count); // empty before hydration

        var hydrated = await fresh.HydrateFromStoreAsync(CancellationToken.None);
        Assert.Equal(2, hydrated);
        Assert.Equal(2, fresh.Count); // the durable rows re-seeded the CRDT list

        // And the hydrated list still verifies authorship (the signed identity round-tripped through EF).
        Assert.All(fresh.Snapshot(), m => Assert.True(CommsMessageFactory.VerifyAuthorship(m, Verifier)));
    }

    private sealed class RecordingLogger : ILogger<CommsCrdtProjection>
    {
        public System.Collections.Concurrent.ConcurrentQueue<string> Warnings { get; } = new();
        public IDisposable? BeginScope<TState>(TState state) where TState : notnull => null;
        public bool IsEnabled(LogLevel logLevel) => true;
        public void Log<TState>(LogLevel level, EventId id, TState state, Exception? exception,
            Func<TState, Exception?, string> formatter)
        {
            if (level >= LogLevel.Warning) Warnings.Enqueue(formatter(state, exception));
        }
    }
}

using System;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using System.IO;

using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging.Abstractions;

using Harborline.Api.Foundation.Crypto;
using Harborline.Api.Kernel.Crdt;
using Harborline.Api.Kernel.Crdt.Backends;
using Harborline.Api.LocalNodeHost.Data.Comms;

using Xunit;

namespace Harborline.Api.LocalNodeHost.Tests.Entities;

/// <summary>
/// C4 — the A↔B DM seal CONSTRUCTION + convergence proof (the Tier-1 backend analogue of the canonical E2E A↔B
/// DM scenario), exercised with a clearly-labeled TEST-DOUBLE key resolver. Two in-process replicas (Alice +
/// Bob), each with its OWN CRDT engine + SQLite store + a per-conversation projection, converge a 1:1 SEALED DM
/// addressed by the deterministic <c>dm:</c> id — scoped, so the DM does NOT bleed into the team channel. Plus a
/// THIRD replica (Carol) acting AS an HONEST non-participant: the sealed delta reaches her node (no C5 routing
/// yet) but her test-double resolver's self-guard derives no key, so she holds only ciphertext.
/// </summary>
/// <remarks>
/// <para>
/// <b>SCOPE — this proves the CONSTRUCTION, not the production confidentiality GUARANTEE</b> (sec-eng deep-review
/// of PR #1325). These tests use <see cref="SeedDerivedParticipantDmKeyResolver"/>, a TEST-ONLY double that derives
/// keys from a party id — so they demonstrate seal/unseal/AAD/tamper/isolation round-trips and the
/// honest-non-participant routing guard, NOT that a non-participant who FORGES a participant id is locked out (the
/// double does not provide that — a liar can derive the key). The real no-leak guarantee is delivered by the C5
/// roster-bound resolver (node-secret, root-seed-bound, non-party-id-derivable keys); production today registers the
/// fail-closed <see cref="NoDmConversationKeyProvider"/> and keeps DMs unexposed until C5.
/// </para>
/// </remarks>
public sealed class CommsDmConvergenceTests : IAsyncLifetime
{
    private readonly System.Collections.Generic.List<Replica> _replicas = new();

    public Task InitializeAsync() => Task.CompletedTask;

    public async Task DisposeAsync()
    {
        foreach (var r in _replicas) await r.DisposeAsync();
    }

    private const string Tenant = "team-7e57";

    // ── Two DM participants + a third (non-participant) team member, each a distinct keypair + member id. ────
    private sealed class Member
    {
        public required string PartyId { get; init; }
        public required IOperationSigner Signer { get; init; }
        public static Member New(string partyId) => new() { PartyId = partyId, Signer = new Ed25519Signer(KeyPair.Generate()) };
    }

    private static readonly Member Alice = Member.New("alice");
    private static readonly Member Bob = Member.New("bob");
    private static readonly Member Carol = Member.New("carol"); // a TEAM member, NOT a DM participant — the leak adversary.
    private static readonly IOperationVerifier Verifier = new Ed25519Verifier();

    // ── C4 — per-member root seeds (deterministic per member, signature-compatible with the C5 resolver). ────
    // NOTE: with the TEST-DOUBLE resolver this seed is NOT actually mixed into the key (the double derives the
    // keypair from the party id alone, which is exactly why it is insecure and test-only). It is passed for
    // signature-compatibility with the C5 roster-bound resolver, where the private key WILL be root-seed-bound.
    private static byte[] SeedFor(string partyId)
    {
        var seed = new byte[32];
        var src = System.Text.Encoding.UTF8.GetBytes("sunfish-dm-test-seed:" + partyId);
        System.Security.Cryptography.SHA256.HashData(src).AsSpan(0, 32).CopyTo(seed);
        return seed;
    }

    /// <summary>A DM key provider for a replica acting AS <paramref name="activeMember"/> (C4 seed-derived resolver).</summary>
    private static IDmConversationKeyProvider DmKeyProviderFor(Member activeMember) =>
        new DerivedDmConversationKeyProvider(
            new SeedDerivedParticipantDmKeyResolver(SeedFor(activeMember.PartyId), activeMember.PartyId));

    /// <summary>The deterministic DM id for the alice↔bob pair (both ends derive this identically — no coordination).</summary>
    private static readonly string AliceBobDmId = DmConversationId.Derive(Tenant, Alice.PartyId, Bob.PartyId);

    // ── A replica that owns BOTH a team-channel projection AND the alice↔bob DM projection. ─────────────────
    private sealed class Replica : IAsyncDisposable
    {
        public required string Name { get; init; }
        public required string Dir { get; init; }
        public required ServiceProvider Sp { get; init; }
        public required IDbContextFactory<NodeLocalCommsDbContext> Factory { get; init; }
        public required CommsCrdtProjection Team { get; init; }
        public required CommsCrdtProjection Dm { get; init; }

        public async ValueTask DisposeAsync()
        {
            await Team.DisposeAsync();
            await Dm.DisposeAsync();
            await Sp.DisposeAsync();
            try { if (Directory.Exists(Dir)) Directory.Delete(Dir, recursive: true); } catch { }
        }
    }

    /// <summary>
    /// A replica acting AS <paramref name="activeMember"/>. Its DM projection is KEYED for that member over the
    /// alice↔bob conversation — so a PARTICIPANT (alice/bob) can seal/unseal, and a NON-PARTICIPANT (carol)
    /// derives no key and holds only ciphertext (the leak property). The team projection is always plaintext.
    /// </summary>
    private async Task<Replica> NewReplicaAsync(string name, Member activeMember)
    {
        var dir = Path.Combine(Path.GetTempPath(), $"harborline-comms-dm-{name}-{Guid.NewGuid():N}");
        Directory.CreateDirectory(dir);
        var services = new ServiceCollection();
        services.AddLogging();
        services.AddDbContextFactory<NodeLocalCommsDbContext>(opt => opt.UseSqlite($"Data Source={Path.Combine(dir, "comms.db")};Pooling=False"));
        services.AddSingleton<ICrdtEngine, YDotNetCrdtEngine>();

        var sp = services.BuildServiceProvider();
        var factory = sp.GetRequiredService<IDbContextFactory<NodeLocalCommsDbContext>>();
        await using (var ctx = await factory.CreateDbContextAsync()) await ctx.Database.EnsureCreatedAsync();

        var engine = sp.GetRequiredService<ICrdtEngine>();
        var team = new CommsCrdtProjection(engine, factory, Verifier, NullLogger<CommsCrdtProjection>.Instance,
            conversationId: CommsConversation.TeamConversationId);
        // C4 — the DM projection is KEYED for this replica's active member over the alice↔bob participant pair.
        var dm = new CommsCrdtProjection(engine, factory, Verifier, NullLogger<CommsCrdtProjection>.Instance,
            rosterBinding: null,
            conversationId: AliceBobDmId,
            dmKeyProvider: DmKeyProviderFor(activeMember),
            dmParticipantA: Alice.PartyId,
            dmParticipantB: Bob.PartyId);

        var replica = new Replica { Name = name, Dir = dir, Sp = sp, Factory = factory, Team = team, Dm = dm };
        _replicas.Add(replica);
        return replica;
    }

    /// <summary>Append a PLAINTEXT (team-channel) message.</summary>
    private static async Task<MessageCrdtState> AppendAsync(
        CommsCrdtProjection conv, Member author, string body, DateTimeOffset at)
    {
        var message = await CommsMessageFactory.CreateSignedAsync(
            author.Signer, author.PartyId, Tenant, body, at, conversationId: conv.ConversationId);
        await conv.PersistLocalAsync(message, CancellationToken.None);
        conv.AppendLocal(message);
        return message;
    }

    /// <summary>
    /// Append a SEALED DM message (C4) on a participant's keyed DM projection — signs the plaintext, seals the
    /// body to the per-conversation key. <paramref name="author"/> must be a participant (alice/bob) so the
    /// projection can derive the key.
    /// </summary>
    private static async Task<MessageCrdtState> AppendSealedDmAsync(
        CommsCrdtProjection dm, Member author, string body, DateTimeOffset at)
    {
        Assert.True(dm.CanSealConversation, "the DM projection must be able to seal (the author is a participant)");
        var message = await dm.CreateSignedSealedLocalAsync(
            author.Signer, author.PartyId, Tenant, body, at, CancellationToken.None);
        await dm.PersistLocalAsync(message, CancellationToken.None);
        dm.AppendLocal(message);
        return message;
    }

    /// <summary>One direction of a sync round between two projections OF THE SAME conversation.</summary>
    private static async Task SyncAsync(CommsCrdtProjection src, CommsCrdtProjection dst)
    {
        var delta = await src.EncodeOutboundDeltaAsync(src.ConversationId, dst.VectorClock, CancellationToken.None);
        Assert.NotNull(delta);
        await dst.ApplyInboundDeltaAsync(src.ConversationId, 1, delta!.Value, CancellationToken.None);
        await dst.DrainPendingReconcilesAsync();
    }

    private static Task<System.Collections.Generic.IReadOnlyList<MessageCrdtState>> ReadAsync(CommsCrdtProjection c) =>
        c.ReadLogAsync(Tenant, CancellationToken.None);

    // ── THE CORE C2 PROOF: a DM round-trips A↔B on the deterministic dm: id, scoped from the team channel. ──

    [Fact(DisplayName = "C4: a SEALED DM round-trips A↔B (both directions), unseals for participants, attributed")]
    public async Task Dm_RoundTrips_A_To_B_BothWays_Attributed()
    {
        var a = await NewReplicaAsync("A", Alice);
        var b = await NewReplicaAsync("B", Bob);

        // Both ends derived the SAME dm: id with no coordination (the projection's conversation id).
        Assert.Equal(AliceBobDmId, a.Dm.ConversationId);
        Assert.Equal(AliceBobDmId, b.Dm.ConversationId);

        // A → B: Alice sends a SEALED DM; the CIPHERTEXT converges to B's DM thread; B (a participant) UNSEALS it,
        // attributed to Alice. The at-rest body on B is CIPHERTEXT (sealed); the unsealed read returns plaintext.
        var t0 = DateTimeOffset.UtcNow;
        await AppendSealedDmAsync(a.Dm, Alice, "Bob, just you and me", t0);
        await SyncAsync(a.Dm, b.Dm);

        var bDmAtRest = await ReadAsync(b.Dm);
        Assert.Single(bDmAtRest);
        Assert.True(DmContentSeal.IsSealed(bDmAtRest[0].Body)); // CIPHERTEXT at rest (the seal).
        Assert.NotEqual("Bob, just you and me", bDmAtRest[0].Body);

        var bDm = await b.Dm.ReadUnsealedLogAsync(Tenant, CancellationToken.None); // participant unseal
        Assert.Single(bDm);
        Assert.Equal("Bob, just you and me", bDm[0].Body); // plaintext for the participant
        Assert.Equal(Alice.PartyId, bDm[0].AuthorPartyId);
        Assert.Equal(AliceBobDmId, bDm[0].ConversationId);
        // Authorship verifies over the UNSEALED plaintext (sign-then-encrypt, DR-3).
        Assert.True(CommsMessageFactory.VerifySealedAuthorship(bDmAtRest[0], bDm[0].Body, Verifier));

        // B → A: Bob replies (sealed); it converges to A's DM thread; A (a participant) unseals it, attributed to Bob.
        await AppendSealedDmAsync(b.Dm, Bob, "Got it, Alice", t0.AddSeconds(1));
        await SyncAsync(b.Dm, a.Dm);

        var aDm = await a.Dm.ReadUnsealedLogAsync(Tenant, CancellationToken.None);
        Assert.Equal(2, aDm.Count);
        Assert.Contains(aDm, m => m.Body == "Got it, Alice" && m.AuthorPartyId == Bob.PartyId);
    }

    [Fact(DisplayName = "C4: a sealed DM is SCOPED — its ciphertext does NOT bleed into the team channel")]
    public async Task Dm_Is_Scoped_From_Team_Channel()
    {
        var a = await NewReplicaAsync("A", Alice);
        var b = await NewReplicaAsync("B", Bob);

        var t0 = DateTimeOffset.UtcNow;
        await AppendAsync(a.Team, Alice, "team announcement", t0);
        await AppendSealedDmAsync(a.Dm, Alice, "private to bob", t0.AddSeconds(1));

        // Sync the DM stream A→B; the team stream is NOT synced in this round.
        await SyncAsync(a.Dm, b.Dm);

        // B's DM thread has ONLY the DM message (unsealed = the plaintext); B's team thread is empty.
        var bDm = await b.Dm.ReadUnsealedLogAsync(Tenant, CancellationToken.None);
        var bTeam = await ReadAsync(b.Team);
        Assert.Equal(new[] { "private to bob" }, bDm.Select(m => m.Body).ToArray());
        Assert.Empty(bTeam);

        // And A's own threads are scoped: the team message is NOT in A's DM thread.
        var aDm = await a.Dm.ReadUnsealedLogAsync(Tenant, CancellationToken.None);
        Assert.DoesNotContain(aDm, m => m.Body == "team announcement");
    }

    [Fact(DisplayName = "C4: a message stamped with a DIFFERENT dm: id is DROPPED by the conversation-scope guard")]
    public async Task Cross_Dm_Message_Is_Dropped_By_Scope_Guard()
    {
        var a = await NewReplicaAsync("A", Alice);
        var b = await NewReplicaAsync("B", Bob);

        // A appends a legit alice↔bob sealed DM, plus a message stamped for a DIFFERENT dm: id (alice↔carol)
        // pushed straight onto the alice↔bob DM stream — exactly what a mis-routed/buggy frame looks like.
        var legit = await AppendSealedDmAsync(a.Dm, Alice, "for bob", DateTimeOffset.UtcNow);
        var aliceCarolId = DmConversationId.Derive(Tenant, Alice.PartyId, Carol.PartyId);
        var misrouted = await CommsMessageFactory.CreateSignedAsync(
            Alice.Signer, Alice.PartyId, Tenant, "for carol (mis-stamped onto bob's stream)",
            DateTimeOffset.UtcNow, conversationId: aliceCarolId);
        a.Dm.AppendLocal(misrouted); // push onto the alice↔bob stream WITHOUT an EF write (the CRDT list sent to the peer)

        await SyncAsync(a.Dm, b.Dm);

        // The CRDT list converged (merge-everything)...
        Assert.Equal(2, b.Dm.Count);
        // ...but the EF read store dropped the cross-conversation message (the C1 conversation-scope guard) — B's
        // alice↔bob DM thread holds ONLY the legit message.
        var bDm = await ReadAsync(b.Dm);
        Assert.Single(bDm);
        Assert.Equal(legit.MessageId, bDm[0].MessageId);
        Assert.DoesNotContain(bDm, m => m.MessageId == misrouted.MessageId);
