/// <see cref="CommsCrdtProjection"/> (real <see cref="YDotNetCrdtEngine"/> backend), and the node's
/// canonical signer. Mirrors <c>ContactDeleteRouteTests</c>.
/// </summary>
public sealed class CommsRouteTests : IAsyncLifetime
{
    // Ticket 294 slice 3b: the single-projection overload names its author; nothing falls back to "local".
    private const string SingleProjectionAuthor = "comms-author-under-test";

    private WebApplication _app = null!;
    private HttpClient _client = null!;
    private string _dir = null!;
    private CommsCrdtProjection _crdt = null!;
    private NodePrincipalSigner _signer = null!;
    private IDbContextFactory<NodeLocalCommsDbContext> _factory = null!;

    public async Task InitializeAsync()
    {
        var builder = WebApplication.CreateBuilder();
        // Ticket 294 slice 3b: the desktop actor (no compile-time operator id).
        Harborline.Api.LocalNodeHost.Tests.Authorization.TestDesktopOperator.AddTestDesktopOperator(builder.Services);
        builder.WebHost.UseUrls("http://127.0.0.1:0");
        builder.Logging.ClearProviders();

        _dir = Path.Combine(Path.GetTempPath(), "harborline-comms-routes-" + Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(_dir);
        var connectionString = $"Data Source={Path.Combine(_dir, "comms.db")};Pooling=False";

        builder.Services.AddDbContextFactory<NodeLocalCommsDbContext>(opt => opt.UseSqlite(connectionString));
        builder.Services.AddSingleton<ICrdtEngine, YDotNetCrdtEngine>();

        _app = builder.Build();

        _factory = _app.Services.GetRequiredService<IDbContextFactory<NodeLocalCommsDbContext>>();
        await using (var ctx = await _factory.CreateDbContextAsync())
            await ctx.Database.EnsureCreatedAsync();

        _crdt = new CommsCrdtProjection(
            _app.Services.GetRequiredService<ICrdtEngine>(), _factory, new Ed25519Verifier(),
            NullLogger<CommsCrdtProjection>.Instance);

        // The node's canonical signer over a fixed 32-byte test seed (the active member's signing identity).
        var seed = new byte[32];
        for (var i = 0; i < seed.Length; i++) seed[i] = (byte)(i + 1);
        _signer = new NodePrincipalSigner(seed);

        // Map the SAME production routes (mirrors HostedCommsApiEndpoint wiring — no [FromServices]).
        CommsRoutes.Map(_app, _crdt, _signer.Signer, NodeTestActiveTeam.Accessor, new NodeCallerSessionToken(null),
            SingleProjectionAuthor, TimeProvider.System);

        await _app.StartAsync();

        var addresses = _app.Services.GetRequiredService<IServer>()
            .Features.Get<IServerAddressesFeature>();
        _client = new HttpClient { BaseAddress = new Uri(addresses!.Addresses.First()) };
    }

    public async Task DisposeAsync()
    {
        _client?.Dispose();
        _signer?.Dispose();
        await _crdt.DisposeAsync();
        await _app.StopAsync();
        await _app.DisposeAsync();
        try { if (Directory.Exists(_dir)) Directory.Delete(_dir, recursive: true); }
        catch { /* best-effort temp cleanup */ }
    }

    private const string Route = "/api/local-node/comms";

    // ── POST appends, GET returns the ordered log ────────────────────────────────────────────────────────

    [Fact(DisplayName = "Comms route: POST appends a signed message; GET returns it attributed + in order")]
    public async Task Post_Appends_Get_Returns_Ordered_Attributed()
    {
        var r1 = await _client.PostAsJsonAsync(Route, new { body = "first message" });
        Assert.Equal(HttpStatusCode.Created, r1.StatusCode);
        var r2 = await _client.PostAsJsonAsync(Route, new { body = "second message" });
        Assert.Equal(HttpStatusCode.Created, r2.StatusCode);

        var doc = await _client.GetFromJsonAsync<JsonElement>(Route);
        var messages = doc.GetProperty("messages");
        Assert.Equal(2, messages.GetArrayLength());

        // Ordered (authored order) + attributed: each carries the active member's id + a verifiable signature.
        Assert.Equal("first message", messages[0].GetProperty("body").GetString());
        Assert.Equal("second message", messages[1].GetProperty("body").GetString());
        var nodeIssuer = _signer.NodePublicKey;
        foreach (var m in messages.EnumerateArray())
        {
            // This test maps the routes via the 4-arg overload (no roster wired — the dev/single-host path),
            // which stamps the FallbackAuthorPartyId ("local"). The SHIPPING path stamps the active enrolled
            // member's per-node-distinct id — proven by Post_Stamps_ActiveEnrolledMember_PartyId below.
            Assert.Equal(SingleProjectionAuthor, m.GetProperty("authorPartyId").GetString());
            Assert.Equal(nodeIssuer, m.GetProperty("authorIssuerId").GetString());
            Assert.False(string.IsNullOrWhiteSpace(m.GetProperty("signature").GetString()));
        }
    }

    [Theory(DisplayName = "Comms route: a client-supplied message id is refused 400 with no append, and omission mints a server id (T-974)")]
    [InlineData("id")]
    [InlineData("messageId")]
    public async Task Post_refuses_a_client_supplied_record_id(string key)
    {
        var refused = await _client.PostAsJsonAsync(
            Route, new Dictionary<string, object?> { ["body"] = "client id", [key] = "client-constructed-id" });

        Assert.Equal(HttpStatusCode.BadRequest, refused.StatusCode);
        Assert.Equal("request.record-id-not-accepted",
            (await refused.Content.ReadFromJsonAsync<JsonElement>()).GetProperty("code").GetString());
        Assert.Equal(0, (await _client.GetFromJsonAsync<JsonElement>(Route)).GetProperty("messages").GetArrayLength());

        var created = await _client.PostAsJsonAsync(Route, new { body = "server id" });
        Assert.Equal(HttpStatusCode.Created, created.StatusCode);
        var minted = (await created.Content.ReadFromJsonAsync<JsonElement>()).GetProperty("messageId").GetString();
        Assert.False(string.IsNullOrWhiteSpace(minted));
        Assert.NotEqual("client-constructed-id", minted);
    }

    [Fact(DisplayName = "Comms route: POST with an empty body → 400 body_required")]
    public async Task Post_EmptyBody_Returns400()
    {
        var resp = await _client.PostAsJsonAsync(Route, new { body = "   " });
        Assert.Equal(HttpStatusCode.BadRequest, resp.StatusCode);
    }

    [Fact(DisplayName = "Comms route: the appended message lands in the durable EF store + the CRDT list")]
    public async Task Post_Persists_To_Durable_Store_And_Crdt()
    {
        var resp = await _client.PostAsJsonAsync(Route, new { body = "durable + synced" });
        Assert.Equal(HttpStatusCode.Created, resp.StatusCode);

        // Durable EF row exists (the recoverable store — the CRDT's only durable sink, SC4-C2).
        await using (var ctx = await _factory.CreateDbContextAsync())
        {
            var rows = await ctx.Set<NodeMessage>().AsNoTracking().ToListAsync();
            Assert.Single(rows);
            Assert.Equal("durable + synced", rows[0].Body);
        }

        // And the CRDT list holds it (so it would ship as a sync delta).
        Assert.Equal(1, _crdt.Count);
    }

    // ── The product-route append converges to a peer (mirrors the harness) ──────────────────────────────

    [Fact(DisplayName = "Comms route: a message appended via the product route converges to a peer replica")]
    public async Task RouteAppend_Converges_To_Peer()
    {
        var peerDir = Path.Combine(Path.GetTempPath(), "harborline-comms-peer-" + Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(peerDir);
        var services = new ServiceCollection();
        services.AddLogging();
        services.AddDbContextFactory<NodeLocalCommsDbContext>(opt =>
            opt.UseSqlite($"Data Source={Path.Combine(peerDir, "comms.db")};Pooling=False"));
        services.AddSingleton<ICrdtEngine, YDotNetCrdtEngine>();
        await using var peerSp = services.BuildServiceProvider();
        var peerFactory = peerSp.GetRequiredService<IDbContextFactory<NodeLocalCommsDbContext>>();
        await using (var ctx = await peerFactory.CreateDbContextAsync())
            await ctx.Database.EnsureCreatedAsync();
        await using var peer = new CommsCrdtProjection(
            peerSp.GetRequiredService<ICrdtEngine>(), peerFactory, new Ed25519Verifier(),
            NullLogger<CommsCrdtProjection>.Instance);

        // Append via the product route, sync to the peer over the live Changed→reconcile trigger.
        Assert.Equal(HttpStatusCode.Created,
            (await _client.PostAsJsonAsync(Route, new { body = "reaches the peer" })).StatusCode);

        var delta = await _crdt.EncodeOutboundDeltaAsync(
            CommsCrdtProjection.DocumentId, peer.VectorClock, CancellationToken.None);
        await peer.ApplyInboundDeltaAsync(CommsCrdtProjection.DocumentId, 1, delta!.Value, CancellationToken.None);
        await peer.DrainPendingReconcilesAsync();

        var peerLog = await peer.ReadLogAsync(
            NodeTestActiveTeam.TestTeamId.Value.ToString(), CancellationToken.None);
        Assert.Single(peerLog);
        Assert.Equal("reaches the peer", peerLog[0].Body);
        Assert.True(CommsMessageFactory.VerifyAuthorship(peerLog[0], new Ed25519Verifier()));

        try { Directory.Delete(peerDir, recursive: true); } catch { /* best-effort */ }
    }
}

using System.Text.Json;

using Harborline.Api.Foundation.Assets.Common;
using Harborline.Api.Foundation.Assets.Entities;
using Harborline.Api.Foundation.Blobs;
using Harborline.Api.Kernel.Schema;

using NSubstitute;

using Xunit;

namespace Harborline.Api.LocalNodeHost.Tests.Entities;

/// <summary>
/// Ticket 367 — a catalog activation or lookup fault cannot leave a record write
/// with a stale or missing schema that it treats as valid.
/// </summary>
public sealed class CompiledSchemaCatalogFaultTests
{
    private static readonly SchemaId Name = new("records.catalog-fault");
    private static readonly Schema Registered = new(
        new SchemaId("schema:missing-artefact"),
        "{\"type\":\"object\"}",
        [],
        [],
        [],
        Cid.Parse("bafkreihdwdcefgh4dqkjv67uzcmw7ojee6xedzdetojuzjevtenxquvyku"));

    [Fact(DisplayName = "367: an activation registry fault clears its binding and the next write refuses by name — holds RW-3 RW-5 RW-H7")]
    public async Task Activate_RegistryThrows_ClearsBindingAndNextWriteRefusesByName()
    {
        var registry = Registry();
        var registrations = 0;
        registry.RegisterAsync(Arg.Any<string>(), ct: Arg.Any<CancellationToken>())
            .Returns(_ => ++registrations == 1
                ? new ValueTask<Schema>(Registered)
                : throw new InvalidOperationException("registry unavailable"));
        var catalog = new CompiledSchemaCatalog(registry);
        var validator = new CompiledSchemaEntityValidator(registry, catalog);

        await catalog.ActivateAsync(Name, Registered.JsonSchemaText);
        Assert.True(catalog.TryGet(Name, out _));
        await Assert.ThrowsAsync<InvalidOperationException>(() =>
            catalog.ActivateAsync(Name, "{\"type\":\"object\"}").AsTask());

        Assert.False(catalog.TryGet(Name, out _));
        await AssertSchemaUnknownAsync(validator);
    }

    [Fact(DisplayName = "367: an activation registry cancellation propagates and clears its binding — holds RW-5 RW-H7")]
    public async Task Activate_RegistryCancels_PropagatesCancellation()
    {
        var registry = Registry();
        var registrations = 0;
        registry.RegisterAsync(Arg.Any<string>(), ct: Arg.Any<CancellationToken>())
            .Returns(_ => ++registrations == 1
                ? new ValueTask<Schema>(Registered)
                : throw new OperationCanceledException());
        var catalog = new CompiledSchemaCatalog(registry);

        await catalog.ActivateAsync(Name, Registered.JsonSchemaText);
        Assert.True(catalog.TryGet(Name, out _));
        await Assert.ThrowsAnyAsync<OperationCanceledException>(() =>
            catalog.ActivateAsync(Name, "{\"type\":\"object\"}").AsTask());

        Assert.False(catalog.TryGet(Name, out _));
    }

    [Fact(DisplayName = "367: a null registry activation result or empty schema text leaves a named refusal — holds RW-3 RW-5 RW-H7")]
    public async Task Activate_NullResultOrEmptyText_NextWriteRefusesByName()
    {
        var nullRegistry = Registry();
        var nullRegistrations = 0;
        nullRegistry.RegisterAsync(Arg.Any<string>(), ct: Arg.Any<CancellationToken>())
            .Returns(_ => ++nullRegistrations == 1
                ? new ValueTask<Schema>(Registered)
                : new ValueTask<Schema>((Schema)null!));
        var nullCatalog = new CompiledSchemaCatalog(nullRegistry);
        var nullValidator = new CompiledSchemaEntityValidator(nullRegistry, nullCatalog);

        await nullCatalog.ActivateAsync(Name, Registered.JsonSchemaText);
        Assert.True(nullCatalog.TryGet(Name, out _));
        Assert.Null(await nullCatalog.ActivateAsync(Name, "{\"type\":\"object\"}"));
        Assert.False(nullCatalog.TryGet(Name, out _));
        await AssertSchemaUnknownAsync(nullValidator);

        var emptyRegistry = Registry();
        var emptyRegistrations = 0;
        emptyRegistry.RegisterAsync(string.Empty, ct: Arg.Any<CancellationToken>())
            .Returns<ValueTask<Schema>>(_ => throw new InvalidSchemaException("schema text is empty"));
        emptyRegistry.RegisterAsync(Arg.Is<string>(text => text != string.Empty), ct: Arg.Any<CancellationToken>())
            .Returns(_ => ++emptyRegistrations == 1
                ? new ValueTask<Schema>(Registered)
                : throw new InvalidOperationException("unexpected registration"));
        var emptyCatalog = new CompiledSchemaCatalog(emptyRegistry);
        var emptyValidator = new CompiledSchemaEntityValidator(emptyRegistry, emptyCatalog);

        await emptyCatalog.ActivateAsync(Name, Registered.JsonSchemaText);
        Assert.True(emptyCatalog.TryGet(Name, out _));
        await Assert.ThrowsAsync<InvalidSchemaException>(() => emptyCatalog.ActivateAsync(Name, string.Empty).AsTask());
        Assert.False(emptyCatalog.TryGet(Name, out _));
        await AssertSchemaUnknownAsync(emptyValidator);
    }

    [Fact(DisplayName = "367: a catalog binding whose compiled artefact is missing refuses by name — holds RW-3 RW-5 RW-H7")]
    public async Task Validate_MissingCompiledArtefact_RefusesByName()
    {
        var registry = Registry();
        registry.RegisterAsync(Arg.Any<string>(), ct: Arg.Any<CancellationToken>())
            .Returns(new ValueTask<Schema>(Registered));
        registry.ValidateAsync(Registered.Id, Arg.Any<ReadOnlyMemory<byte>>(), ct: Arg.Any<CancellationToken>())
            .Returns<ValueTask<SchemaValidationResult>>(_ => throw new SchemaNotFoundException("compiled artefact missing"));
        var catalog = new CompiledSchemaCatalog(registry);
        var validator = new CompiledSchemaEntityValidator(registry, catalog);

        await catalog.ActivateAsync(Name, Registered.JsonSchemaText);
        Assert.True(catalog.TryGet(Name, out var activated));
        Assert.Equal(Registered.Id, activated.CompiledSchemaId);

        await AssertSchemaUnknownAsync(validator);
    }

    private static ISchemaRegistry Registry()
    {
        var registry = Substitute.For<ISchemaRegistry>();
        registry.GetAsync(Arg.Any<SchemaId>(), ct: Arg.Any<CancellationToken>())
            .Returns(new ValueTask<Schema?>((Schema?)null));
        return registry;
    }

    private static async Task AssertSchemaUnknownAsync(CompiledSchemaEntityValidator validator)
    {
        using var body = JsonDocument.Parse("{\"valid\":true}");
        var refusal = await Assert.ThrowsAsync<EntityValidationException>(() => validator.ValidateAsync(Name, body));
        Assert.Equal(CompiledSchemaEntityValidator.SchemaUnknown, refusal.ReasonCode);
    }
}

