    private sealed class StubPdfWriter : IPdfExportWriter
    {
        public ValueTask<byte[]> WriteAsync(RenderedDocument document, CancellationToken ct = default)
            => ValueTask.FromResult("%PDF-1.7 stub"u8.ToArray());
    }
