    public async Task FutureMultihopDescendant_ClipsAFiniteInheritedEndBeforeTheNextLeg()
    {
        var h = await Harness.CreateAsync();
        var displaced = await h.Hierarchy.AddEdgeAsync(KidA, OldA, EdgeKind.ChildOf, At.AddDays(-1));
        await h.Hierarchy.InvalidateEdgeAsync(displaced.Id, At.AddDays(3));
        var first = await h.Hierarchy.AddEdgeAsync(KidB, KidA, EdgeKind.ChildOf, At.AddDays(1));
        await h.Hierarchy.InvalidateEdgeAsync(first.Id, At.AddDays(2));
        await h.Hierarchy.AddEdgeAsync(OldB, KidB, EdgeKind.ChildOf, At.AddDays(2));

        // Oracle: the candidate [day0,day3) must be clipped to [day1,day2) on the first leg.
        // The next leg starts exactly at day2, so the half-open intersection is empty.
        await h.Coordinator.ReparentAsync(KidA, OldA, OldB, "finite-path-end", Actor, Tenant, At);

        var replacement = Assert.Single(await h.ParentEdges(KidA, At));
        Assert.Equal((OldB, At, (DateTimeOffset?)At.AddDays(3)),
            (replacement.To, replacement.Validity.ValidFrom, replacement.Validity.ValidTo));
        Assert.Empty(await h.ParentEdges(KidA, At.AddDays(3)));
        var firstAfter = Assert.Single(await h.ParentEdges(KidB, At.AddDays(1)));
        Assert.Equal((KidA, At.AddDays(1), (DateTimeOffset?)At.AddDays(2)),
            (firstAfter.To, firstAfter.Validity.ValidFrom, firstAfter.Validity.ValidTo));
        Assert.Empty(await h.ParentEdges(KidB, At.AddDays(2)));
        var secondAfter = Assert.Single(await h.ParentEdges(OldB, At.AddDays(2)));
        Assert.Equal((KidB, At.AddDays(2), (DateTimeOffset?)null),
            (secondAfter.To, secondAfter.Validity.ValidFrom, secondAfter.Validity.ValidTo));
        Assert.Equal("finite-path-end", Assert.Single(await h.AuditRows()).Justification);
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public async Task Split_ReassignsRequestedFutureChild_PreservesScheduledInterval(bool finite)
    {
        var h = await Harness.CreateAsync(Original);
        var scheduled = await h.Hierarchy.AddEdgeAsync(KidA, Original, EdgeKind.ChildOf, At.AddDays(1));
        if (finite) await h.Hierarchy.InvalidateEdgeAsync(scheduled.Id, At.AddDays(2));
        await h.Hierarchy.AddEdgeAsync(KidB, Original, EdgeKind.ChildOf, At.AddDays(3));
        h.Hierarchy.Invalidated.Clear();

        var result = await h.Coordinator.SplitAsync(Original, [Target("east")],
            new Dictionary<EntityId, EntityId> { [KidA] = East }, "scheduled-split", Actor, Tenant, At);

        // Oracle: move only the requested child, beginning at day1 and retaining its day2/open end.
        Assert.Empty(await h.ParentEdges(KidA, At));
        var moved = Assert.Single(await h.ParentEdges(KidA, At.AddDays(1)));
        Assert.Equal((East, At.AddDays(1), finite ? (DateTimeOffset?)At.AddDays(2) : null),
            (moved.To, moved.Validity.ValidFrom, moved.Validity.ValidTo));
        if (finite) Assert.Empty(await h.ParentEdges(KidA, At.AddDays(2)));
        else Assert.Equal(East, Assert.Single(await h.ParentEdges(KidA, At.AddDays(2))).To);
        Assert.Contains((scheduled.Id, At.AddDays(1)), h.Hierarchy.Invalidated);
        Assert.Equal(finite ? 2 : 1, h.Hierarchy.Invalidated.Count);
        Assert.Equal(Original, Assert.Single(await h.ParentEdges(KidB, At.AddDays(3))).To);
        Assert.Equal([KidA], result.ReassignedChildren);
        Assert.Equal([East], result.NewEntities);
        Assert.Null(await h.Entities.GetAsync(Original));
        Assert.NotNull(await h.Entities.GetAsync(East));
        var row = Assert.Single(await h.AuditRows());
        Assert.Equal((Original, Op.Split, Actor, Tenant, At, "scheduled-split"),
            (row.EntityId, row.Op, row.Actor, row.Tenant, row.At, row.Justification));
        Assert.Equal([KidA.ToString()], Strings(row.Payload.RootElement, "reassigned"));
        Assert.Equal([East.ToString()], Strings(row.Payload.RootElement, "newIds"));
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public async Task Split_ChangedFutureChildSnapshot_RefusesBeforeMinting(bool addEdge)
    {
        var h = await Harness.CreateAsync(Original);
        var scheduled = await h.Hierarchy.AddEdgeAsync(KidA, Original, EdgeKind.ChildOf, At.AddDays(1));
        await h.Hierarchy.InvalidateEdgeAsync(scheduled.Id, At.AddDays(4));
        h.Hierarchy.BeforeAtomic = async () =>
        {
            if (addEdge) await h.Hierarchy.AddEdgeAsync(KidA, Original, EdgeKind.ChildOf, At.AddDays(2));
            else await h.Hierarchy.InvalidateEdgeAsync(scheduled.Id, At.AddDays(2));
            h.Hierarchy.Added.Clear();
        };

        await Assert.ThrowsAsync<InvalidOperationException>(() => h.Coordinator.SplitAsync(
            Original, [Target("east")], new Dictionary<EntityId, EntityId> { [KidA] = East },
            "stale-scheduled-split", Actor, Tenant, At));

        // Oracle: the intervening future write survives; stale split creates/deletes/audits nothing.
        await h.AssertNothingWrittenAsync([Original], East);
        var winner = Assert.Single(await h.ParentEdges(KidA, At.AddDays(1)));
        Assert.Equal((Original, At.AddDays(1), addEdge ? At.AddDays(4) : At.AddDays(2)),
            (winner.To, winner.Validity.ValidFrom, winner.Validity.ValidTo!.Value));
        Assert.Equal(addEdge ? 2 : 0, (await h.ParentEdges(KidA, At.AddDays(2))).Count);
    }

    private static CreateOptions Options(string localPart, TenantId tenant) =>
        new("entity", "test", localPart, Actor, tenant, At, ExplicitLocalPart: localPart);

    private static SplitTarget Target(string localPart, TenantId? tenant = null) => new(
        Schema, JsonDocument.Parse($$"""{"name":"{{localPart}}"}"""), Options(localPart, tenant ?? Tenant));

    private static AuditAppend Append(EntityId entity) =>
        new(entity, null, Op.Reparent, Actor, Tenant, At, JsonDocument.Parse("""{"op":"reparent"}"""), "move");

    private static string[] Strings(JsonElement payload, string property) =>
        [.. payload.GetProperty(property).EnumerateArray().Select(item => item.GetString()!)];

    private static async Task<List<AuditRecord>> Rows(InMemoryAuditLog log)
    {
        var rows = new List<AuditRecord>();
        await foreach (var row in log.QueryAsync(new AuditQuery())) rows.Add(row);
        return rows;
    }

    private sealed class Harness : IWritePipelineObserver
    {
        private InMemoryAssetStorage storage = null!;

        public InMemoryEntityStore Entities { get; private init; } = null!;
        public RecordingHierarchy Hierarchy { get; private init; } = null!;
        public InMemoryAuditLog Audit { get; private init; } = null!;
        public NodeHierarchyCompositeCoordinator Coordinator { get; private set; } = null!;
        public List<WritePipelineStage> Stages { get; } = [];

        public void OnStage(WritePipelineStage stage) => Stages.Add(stage);

        /// <summary>Real stores sharing one asset storage, with each named entity created a day before the act.</summary>
        public static async Task<Harness> CreateAsync(params EntityId[] existing)
        {
            var storage = new InMemoryAssetStorage();
            var entities = new InMemoryEntityStore(storage, new FixedTimeProvider(At));
            foreach (var id in existing)
            {
                using var body = JsonDocument.Parse($$"""{"name":"{{id.LocalPart}}"}""");
                await entities.CreateAsync(Schema, body, Options(id.LocalPart, Tenant) with { ValidFrom = At.AddDays(-1) });
            }
            var harness = new Harness
            {
                storage = storage,
                Entities = entities,
                Hierarchy = new RecordingHierarchy(new InMemoryHierarchyService(storage)),
                Audit = new InMemoryAuditLog(storage),
            };
            harness.Coordinator = harness.CoordinatorOver(entities);
            return harness;
        }

        public NodeHierarchyCompositeCoordinator CoordinatorOver(IEntityMutationStore entities, DateTimeOffset? admittedAt = null) => new(
            entities, Hierarchy, new HierarchyAuthorizedAuditWriter(Audit),
            TestAuthorization.Gate(true), new FixedTimeProvider(admittedAt ?? At), NullEntityValidator.Instance, this);

        public Task<MergeResult> MergeAsync(NodeHierarchyCompositeCoordinator coordinator, CreateOptions options) =>
            coordinator.MergeAsync(
                [OldA, OldB], Schema, JsonDocument.Parse("""{"name":"merged"}"""), options, "merge", Actor, Tenant, At);

        public async Task<List<EntityEdge>> ParentEdges(EntityId child, DateTimeOffset asOf)
        {
            var edges = new List<EntityEdge>();
            await foreach (var edge in Hierarchy.GetParentsAsync(child, asOf)) edges.Add(edge);
            return edges;
        }

        public Task<List<AuditRecord>> AuditRows() => Rows(Audit);

        /// <summary>The originals survive, no replacement exists, no edge was added at the act and no audit row exists.</summary>
        public async Task AssertNothingWrittenAsync(EntityId[] originals, params EntityId[] replacements)
        {
            foreach (var id in originals) Assert.NotNull(await Entities.GetAsync(id));
            foreach (var id in replacements) Assert.Null(await Entities.GetAsync(id));
            Assert.DoesNotContain(Hierarchy.Added, edge => edge.Validity.ValidFrom == At);
            Assert.Empty(await AuditRows());
        }
    }

    /// <summary>The real hierarchy store, also keeping each edge it returned from an add.</summary>
    private sealed class RecordingHierarchy(InMemoryHierarchyService inner) : IHierarchyCompositeUnitOfWork
    {
        public List<EntityEdge> Added { get; } = [];
        public List<(long EdgeId, DateTimeOffset ValidTo)> Invalidated { get; } = [];
        public Func<Task>? BeforeAtomic { get; set; }

        public async Task<T> ExecuteAtomicAsync<T>(Func<CancellationToken, Task<T>> action, CancellationToken ct = default)
        {
            var beforeAtomic = BeforeAtomic;
            BeforeAtomic = null;
            if (beforeAtomic is not null) await beforeAtomic();
            return await inner.ExecuteAtomicAsync(action, ct);
        }

        public async Task<EntityEdge> AddEdgeAsync(
            EntityId from, EntityId to, EdgeKind kind, DateTimeOffset validFrom,
            JsonDocument? metadata = null, CancellationToken ct = default)
        {
            var edge = await inner.AddEdgeAsync(from, to, kind, validFrom, metadata, ct);
            Added.Add(edge);
            return edge;
        }

        public async Task InvalidateEdgeAsync(long edgeId, DateTimeOffset validTo, CancellationToken ct = default)
        {
            await inner.InvalidateEdgeAsync(edgeId, validTo, ct);
            Invalidated.Add((edgeId, validTo));
        }

        public IAsyncEnumerable<EntityEdge> GetChildrenAsync(EntityId parent, DateTimeOffset? asOf = null, CancellationToken ct = default) =>
            inner.GetChildrenAsync(parent, asOf, ct);

        public IAsyncEnumerable<EntityEdge> GetChildrenNotEndedAsync(EntityId parent, DateTimeOffset asOf, CancellationToken ct = default) =>
            inner.GetChildrenNotEndedAsync(parent, asOf, ct);

        public IAsyncEnumerable<EntityEdge> GetParentsAsync(EntityId child, DateTimeOffset? asOf = null, CancellationToken ct = default) =>
            inner.GetParentsAsync(child, asOf, ct);

        public IAsyncEnumerable<ClosureEntry> GetAncestorsAsync(EntityId descendant, DateTimeOffset? asOf = null, CancellationToken ct = default) =>
            inner.GetAncestorsAsync(descendant, asOf, ct);

        public IAsyncEnumerable<ClosureEntry> GetDescendantsAsync(EntityId ancestor, DateTimeOffset? asOf = null, CancellationToken ct = default) =>
            inner.GetDescendantsAsync(ancestor, asOf, ct);

        public Task<TemporalSnapshot> GetSubtreeAsync(EntityId root, DateTimeOffset? asOf = null, CancellationToken ct = default) =>
            inner.GetSubtreeAsync(root, asOf, ct);
    }

    private sealed class FixedTimeProvider(DateTimeOffset now) : TimeProvider
    {
        public override DateTimeOffset GetUtcNow() => now;
    }
}

using System.Text.Json;

using Harborline.Api.Foundation.Assets.Audit;
using Harborline.Api.Foundation.Assets.Common;
using Harborline.Api.Foundation.Assets.Entities;
using Harborline.Api.Foundation.Assets.Hierarchy;
using Harborline.Api.Foundation.Authorization;
using Harborline.Api.Kernel.Runtime;
using Harborline.Api.LocalNodeHost.Data.Entities;
using Harborline.Api.LocalNodeHost.Tests.Authorization;

using Xunit;

namespace Harborline.Api.LocalNodeHost.Tests.Entities;

/// <summary>
/// ck-10 S3 (DES-0029, ADR 0038): a hierarchy merge runs the six stages through <see cref="WritePipeline.RunAsync"/>
/// inside its atomic unit. A displaced child the caller may not write is refused at validate, before the replacement
/// is minted or any original is removed.
/// </summary>
public sealed class HierarchyMergePipelineTests
{
    private static readonly DateTimeOffset At = new(2026, 10, 1, 12, 0, 0, TimeSpan.Zero);
    private static readonly TenantId Tenant = new("merge-pipeline");
    private static readonly ActorId Actor = new("merge-operator");
    private static readonly SchemaId Schema = new("merge.pipeline");
    private static readonly EntityId OldA = new("entity", "test", "old-a");
    private static readonly EntityId OldB = new("entity", "test", "old-b");
    private static readonly EntityId Kid = new("entity", "test", "kid");
    private static readonly EntityId Merged = new("entity", "test", "merged");

    // ADR 0038's order, written out here rather than read from WritePipeline.Order.
    private static readonly WritePipelineStage[] SixStages =
    [
        WritePipelineStage.Authorize, WritePipelineStage.Bind, WritePipelineStage.Mutate,
        WritePipelineStage.Validate, WritePipelineStage.Commit, WritePipelineStage.React,
    ];

    [Fact(DisplayName = "ck-10 S3: a merge runs the six stages, mints the replacement and moves the displaced child onto it")]
    public async Task Merge_RunsTheSixStages()
    {
        var h = await Harness.CreateAsync(TestAuthorization.Gate(true));

        var result = await h.MergeAsync();

        Assert.Equal(SixStages, h.Stages);
        Assert.Equal(Merged, result.NewEntity);
        Assert.Null(await h.Entities.GetAsync(OldA));
        Assert.Null(await h.Entities.GetAsync(OldB));
        Assert.Equal([Merged], await h.ParentsOf(Kid));
    }

    [Fact(DisplayName = "ck-10 S3: a displaced child the caller may not write is refused at validate; nothing is minted or removed, and an allowed retry merges")]
    public async Task Merge_AnUnwritableDisplacedChild_IsRefusedAtValidate_AndAnAllowedRetryMerges()
    {
        var h = await Harness.CreateAsync(TestRouteGate.ScopedTo("merged", "old-a", "old-b"));

        await Assert.ThrowsAsync<AuthorizationDeniedException>(() => h.MergeAsync());

        Assert.Equal(WritePipelineStage.Validate, h.Stages[^1]);
        Assert.Null(await h.Entities.GetAsync(Merged));
        Assert.NotNull(await h.Entities.GetAsync(OldA));
        Assert.Equal([OldA], await h.ParentsOf(Kid));

        var retry = h.WithGate(TestAuthorization.Gate(true));
        await retry.MergeAsync();
        Assert.Equal(SixStages, retry.Stages);
        Assert.Equal([Merged], await retry.ParentsOf(Kid));
    }

    [Fact(DisplayName = "ck-10 S3: a caller refused a named original stops the merge at authorize")]
    public async Task Merge_RefusedNamedOriginal_StopsAtAuthorize()
    {
        var h = await Harness.CreateAsync(TestRouteGate.ScopedTo("merged", "old-a", "kid"));

        await Assert.ThrowsAsync<AuthorizationDeniedException>(() => h.MergeAsync());

        Assert.Equal([WritePipelineStage.Authorize], h.Stages);
        Assert.NotNull(await h.Entities.GetAsync(OldB));
    }

    private sealed class Harness : IWritePipelineObserver
    {
        private InMemoryAssetStorage storage = null!;
        private InMemoryHierarchyService hierarchy = null!;

        public InMemoryEntityStore Entities { get; private set; } = null!;
        public NodeHierarchyCompositeCoordinator Coordinator { get; private set; } = null!;
        public List<WritePipelineStage> Stages { get; } = [];

        public void OnStage(WritePipelineStage stage) => Stages.Add(stage);

        /// <summary>Two originals, with one child under the first, a day before the act.</summary>
        public static async Task<Harness> CreateAsync(AuthorizationGate gate)
        {
            var storage = new InMemoryAssetStorage();
            var entities = new InMemoryEntityStore(storage, new FixedTimeProvider(At));
            var hierarchy = new InMemoryHierarchyService(storage);
            foreach (var original in new[] { OldA, OldB, Kid })
            {
                using var body = JsonDocument.Parse($$"""{"name":"{{original.LocalPart}}"}""");
                await entities.CreateAsync(Schema, body, Options(original.LocalPart, At.AddDays(-1)));
            }
            await hierarchy.AddEdgeAsync(Kid, OldA, EdgeKind.ChildOf, At.AddDays(-1));
            var harness = new Harness { storage = storage, hierarchy = hierarchy, Entities = entities };
            harness.Coordinator = harness.Build(gate);
            return harness;
        }

        public Harness WithGate(AuthorizationGate gate)
        {
            var harness = new Harness { storage = storage, hierarchy = hierarchy, Entities = Entities };
            harness.Coordinator = harness.Build(gate);
            return harness;
        }

        public Task<MergeResult> MergeAsync() => Coordinator.MergeAsync(
            [OldA, OldB], Schema, JsonDocument.Parse("""{"name":"merged"}"""), Options("merged", At),
            "merge", Actor, Tenant, At);

        public async Task<List<EntityId>> ParentsOf(EntityId child)
        {
            var parents = new List<EntityId>();
            await foreach (var edge in hierarchy.GetParentsAsync(child, At))
                if (edge.Kind == EdgeKind.ChildOf)
                    parents.Add(edge.To);
            return parents;
        }

        private NodeHierarchyCompositeCoordinator Build(AuthorizationGate gate) => new(
            Entities, hierarchy, new HierarchyAuthorizedAuditWriter(new InMemoryAuditLog(storage)),
            gate, new FixedTimeProvider(At), NullEntityValidator.Instance, this);
    }

    private static CreateOptions Options(string localPart, DateTimeOffset validFrom) =>
        new("entity", "test", localPart, Actor, Tenant, validFrom, ExplicitLocalPart: localPart);

    private sealed class FixedTimeProvider(DateTimeOffset now) : TimeProvider
    {
        public override DateTimeOffset GetUtcNow() => now;
    }
}

using Harborline.Api.Foundation.Assets.Audit;
using Harborline.Api.Foundation.Assets.Common;
using Harborline.Api.Foundation.Assets.Entities;
using Harborline.Api.Foundation.Assets.Hierarchy;
using Harborline.Api.Foundation.Authorization;
using Harborline.Api.Kernel.Runtime;
using Harborline.Api.LocalNodeHost.Data.Entities;
using Harborline.Api.LocalNodeHost.Tests.Authorization;

using Xunit;

namespace Harborline.Api.LocalNodeHost.Tests.Entities;

/// <summary>
/// ck-10 S3 (DES-0029, ADR 0038): a hierarchy reparent runs the six stages through
/// <see cref="WritePipeline.RunAsync"/> inside one atomic unit. Validate refuses a new parent that is the child
/// or one of its descendants, so the closure table never gains a cycle; every refusal leaves the edges as they were.
/// </summary>
public sealed class HierarchyReparentPipelineTests
{
    private static readonly DateTimeOffset At = new(2026, 10, 1, 12, 0, 0, TimeSpan.Zero);
    private static readonly TenantId Tenant = new("hierarchy-pipeline");
    private static readonly ActorId Actor = new("hierarchy-operator");
    private static readonly EntityId Root = new("entity", "test", "root");
    private static readonly EntityId Site = new("entity", "test", "site");
    private static readonly EntityId Building = new("entity", "test", "building");
    private static readonly EntityId Room = new("entity", "test", "room");

    // ADR 0038's order, written out here rather than read from WritePipeline.Order.
    private static readonly WritePipelineStage[] SixStages =
    [
        WritePipelineStage.Authorize, WritePipelineStage.Bind, WritePipelineStage.Mutate,
        WritePipelineStage.Validate, WritePipelineStage.Commit, WritePipelineStage.React,
    ];

    [Fact(DisplayName = "ck-10 S3: a reparent runs the six stages and moves the child to its new parent")]
    public async Task Reparent_RunsTheSixStages()
    {
        var h = await Harness.CreateAsync();

        await h.Coordinator.ReparentAsync(Room, Building, Site, "move", Actor, Tenant, At);

        Assert.Equal(SixStages, h.Stages);
        Assert.Equal([Site], await h.ParentsOf(Room));
    }

    [Fact(DisplayName = "ck-10 S3: a refused caller stops at authorize and the edges are unchanged")]
    public async Task Reparent_RefusedCaller_StopsAtAuthorize()
    {
        var h = await Harness.CreateAsync(allow: false);

        await Assert.ThrowsAsync<AuthorizationDeniedException>(() =>
            h.Coordinator.ReparentAsync(Room, Building, Site, "move", Actor, Tenant, At));

        Assert.Equal([WritePipelineStage.Authorize], h.Stages);
        Assert.Equal([Building], await h.ParentsOf(Room));
    }

    [Fact(DisplayName = "ck-10 S3: an entity reparented under itself is refused at validate, with or without a closure row of its own")]
    public async Task Reparent_UnderItself_IsRefusedAtValidate()
    {
        var h = await Harness.CreateAsync();
        var loose = new EntityId("entity", "test", "loose");

        await Assert.ThrowsAsync<ArgumentException>(() =>
            h.Coordinator.ReparentAsync(Building, Site, Building, "loop", Actor, Tenant, At));
        Assert.Equal(WritePipelineStage.Validate, h.Stages[^1]);
        Assert.Equal([Site], await h.ParentsOf(Building));

        h.Stages.Clear();
        await Assert.ThrowsAsync<ArgumentException>(() =>
            h.Coordinator.ReparentAsync(loose, Root, loose, "loop", Actor, Tenant, At));
        Assert.Equal(WritePipelineStage.Validate, h.Stages[^1]);
        Assert.Empty(await h.ParentsOf(loose));
    }

    [Fact(DisplayName = "ck-10 S3: a reparent under the entity's own descendant is refused at validate; a valid retry then moves it")]
    public async Task Reparent_UnderOwnDescendant_IsRefusedAtValidate_AndAValidRetrySucceeds()
    {
        var h = await Harness.CreateAsync();

        await Assert.ThrowsAsync<ArgumentException>(() =>
            h.Coordinator.ReparentAsync(Site, Root, Room, "cycle", Actor, Tenant, At));
        Assert.Equal(WritePipelineStage.Validate, h.Stages[^1]);
        Assert.Equal([Root], await h.ParentsOf(Site));

        h.Stages.Clear();
        await h.Coordinator.ReparentAsync(Room, Building, Root, "flatten", Actor, Tenant, At);
        Assert.Equal(SixStages, h.Stages);
        Assert.Equal([Root], await h.ParentsOf(Room));
    }

    [Fact(DisplayName = "ck-10 S3: of two opposing reparents that both pass validate, the second to commit is refused inside its atomic unit")]
    public async Task OpposingReparents_TheSecondToCommitIsRefusedInsideItsUnit()
    {
        var h = await Harness.CreateAsync();
        var depot = new EntityId("entity", "test", "depot");
        await h.Hierarchy.AddEdgeAsync(depot, Root, EdgeKind.ChildOf, At.AddDays(-1));
        using var held = new ManualResetEventSlim(false);
        using var release = new ManualResetEventSlim(false);
        var gate = new CommitGate(held, release);

        // Reparent one validates "site under depot", then is held just before it commits.
        var first = Task.Run(() => h.CoordinatorObservedBy(gate).ReparentAsync(Site, Root, depot, "first", Actor, Tenant, At));
        Assert.True(held.Wait(TimeSpan.FromSeconds(30)), "the first reparent never reached commit");

        // Reparent two moves depot under site and commits while the first is held.
        await h.Coordinator.ReparentAsync(depot, Root, Site, "second", Actor, Tenant, At);
        Assert.Equal([Site], await h.ParentsOf(depot));

        release.Set();
        await Assert.ThrowsAsync<ArgumentException>(() => first);
        Assert.Equal(WritePipelineStage.Commit, gate.Stages[^1]);
        Assert.Equal([Root], await h.ParentsOf(Site));
    }

    /// <summary>Records stages and holds the write on entering commit until the test releases it.</summary>
    private sealed class CommitGate(ManualResetEventSlim held, ManualResetEventSlim release) : IWritePipelineObserver
    {
        public List<WritePipelineStage> Stages { get; } = [];

        public void OnStage(WritePipelineStage stage)
        {
            Stages.Add(stage);
            if (stage != WritePipelineStage.Commit) return;
            held.Set();
            release.Wait(TimeSpan.FromSeconds(30));
        }
    }

    private sealed class Harness : IWritePipelineObserver
    {
        private InMemoryAssetStorage storage = null!;
        private bool allow;

        private Harness(InMemoryHierarchyService hierarchy, NodeHierarchyCompositeCoordinator coordinator)
        {
            Hierarchy = hierarchy;
            Coordinator = coordinator;
        }

        public NodeHierarchyCompositeCoordinator CoordinatorObservedBy(IWritePipelineObserver observer) => new(
            new InMemoryEntityStore(storage, new FixedTimeProvider(At)), Hierarchy,
            new HierarchyAuthorizedAuditWriter(new InMemoryAuditLog(storage)),
            TestAuthorization.Gate(allow), new FixedTimeProvider(At), NullEntityValidator.Instance, observer);

        public InMemoryHierarchyService Hierarchy { get; }
        public NodeHierarchyCompositeCoordinator Coordinator { get; private set; }
        public List<WritePipelineStage> Stages { get; } = [];

        public void OnStage(WritePipelineStage stage) => Stages.Add(stage);

        /// <summary>Root, then Site under Root, Building under Site and Room under Building, a day before the act.</summary>
        public static async Task<Harness> CreateAsync(bool allow = true)
        {
            var storage = new InMemoryAssetStorage();
            var hierarchy = new InMemoryHierarchyService(storage);
            await hierarchy.AddEdgeAsync(Site, Root, EdgeKind.ChildOf, At.AddDays(-1));
            await hierarchy.AddEdgeAsync(Building, Site, EdgeKind.ChildOf, At.AddDays(-1));
            await hierarchy.AddEdgeAsync(Room, Building, EdgeKind.ChildOf, At.AddDays(-1));
            var harness = new Harness(hierarchy, null!) { storage = storage, allow = allow };
            harness.Coordinator = new NodeHierarchyCompositeCoordinator(
                new InMemoryEntityStore(storage, new FixedTimeProvider(At)), hierarchy,
                new HierarchyAuthorizedAuditWriter(new InMemoryAuditLog(storage)),
                TestAuthorization.Gate(allow), new FixedTimeProvider(At),
                NullEntityValidator.Instance, harness);
            return harness;
        }

        public async Task<List<EntityId>> ParentsOf(EntityId child)
        {
            var parents = new List<EntityId>();
            await foreach (var edge in Hierarchy.GetParentsAsync(child, At))
                if (edge.Kind == EdgeKind.ChildOf)
                    parents.Add(edge.To);
            return parents;
        }
    }

    private sealed class FixedTimeProvider(DateTimeOffset now) : TimeProvider
    {
        public override DateTimeOffset GetUtcNow() => now;
    }
}

using System.Text.Json;

using Harborline.Api.Foundation.Assets.Audit;
using Harborline.Api.Foundation.Assets.Common;
using Harborline.Api.Foundation.Assets.Entities;
using Harborline.Api.Foundation.Assets.Hierarchy;
using Harborline.Api.Foundation.Authorization;
using Harborline.Api.Kernel.Runtime;
using Harborline.Api.LocalNodeHost.Data.Entities;
using Harborline.Api.LocalNodeHost.Tests.Authorization;

using Xunit;

namespace Harborline.Api.LocalNodeHost.Tests.Entities;

/// <summary>
/// ck-10 S3 (DES-0029, ADR 0038): a hierarchy split runs the six stages through <see cref="WritePipeline.RunAsync"/>.
/// Every replacement is admitted at validate before commit opens the atomic unit, so one refused replacement
/// stops the split before anything is written.
/// </summary>
public sealed class HierarchySplitPipelineTests
{
    private static readonly DateTimeOffset At = new(2026, 10, 1, 12, 0, 0, TimeSpan.Zero);
    private static readonly TenantId Tenant = new("split-pipeline");
    private static readonly ActorId Actor = new("split-operator");
    private static readonly SchemaId Accepted = new("split.accepted");
    private static readonly SchemaId Refused = new("split.refused");

    // ADR 0038's order, written out here rather than read from WritePipeline.Order.
    private static readonly WritePipelineStage[] SixStages =
    [
        WritePipelineStage.Authorize, WritePipelineStage.Bind, WritePipelineStage.Mutate,
        WritePipelineStage.Validate, WritePipelineStage.Commit, WritePipelineStage.React,
    ];

    [Fact(DisplayName = "ck-10 S3: a split runs the six stages, mints both replacements and removes the original")]
    public async Task Split_RunsTheSixStages()
    {
        var h = await Harness.CreateAsync();

        var result = await h.Coordinator.SplitAsync(
            h.Original, [Target("east", Accepted), Target("west", Accepted)], new Dictionary<EntityId, EntityId>(),
            "split", Actor, Tenant, At);

        Assert.Equal(SixStages, h.Stages);
        Assert.Null(await h.Entities.GetAsync(h.Original));
        Assert.Equal(["east", "west"], result.NewEntities.Select(id => id.LocalPart));
        foreach (var id in result.NewEntities) Assert.NotNull(await h.Entities.GetAsync(id));
    }

    [Fact(DisplayName = "ck-10 S3: a refused second replacement stops the split at validate before the first is written; a valid retry then splits")]
    public async Task Split_ARefusedReplacement_StopsAtValidate_BeforeAnyWrite_AndAValidRetrySucceeds()
    {
        var h = await Harness.CreateAsync();

        await Assert.ThrowsAsync<EntityValidationException>(() => h.Coordinator.SplitAsync(
            h.Original, [Target("east", Accepted), Target("west", Refused)], new Dictionary<EntityId, EntityId>(),
            "split", Actor, Tenant, At));
        Assert.Equal(WritePipelineStage.Validate, h.Stages[^1]);
        Assert.NotNull(await h.Entities.GetAsync(h.Original));
        Assert.Null(await h.Entities.GetAsync(new EntityId("entity", "test", "east")));

        h.Stages.Clear();
        await h.Coordinator.SplitAsync(
            h.Original, [Target("east", Accepted), Target("west", Accepted)], new Dictionary<EntityId, EntityId>(),
            "retry", Actor, Tenant, At);
        Assert.Equal(SixStages, h.Stages);
        Assert.Null(await h.Entities.GetAsync(h.Original));
    }

    [Fact(DisplayName = "ck-10 S3: a refused caller stops the split at authorize and the original survives")]
    public async Task Split_RefusedCaller_StopsAtAuthorize()
    {
        var h = await Harness.CreateAsync(allow: false);

        await Assert.ThrowsAsync<AuthorizationDeniedException>(() => h.Coordinator.SplitAsync(
            h.Original, [Target("east", Accepted)], new Dictionary<EntityId, EntityId>(), "split", Actor, Tenant, At));

        Assert.Equal([WritePipelineStage.Authorize], h.Stages);
        Assert.NotNull(await h.Entities.GetAsync(h.Original));
    }

    private static SplitTarget Target(string localPart, SchemaId schema) => new(
        schema, JsonDocument.Parse($$"""{"name":"{{localPart}}"}"""),
        new CreateOptions("entity", "test", localPart, Actor, Tenant, At, ExplicitLocalPart: localPart));

    private sealed class Harness : IWritePipelineObserver
    {
        public InMemoryEntityStore Entities { get; private init; } = null!;
        public NodeHierarchyCompositeCoordinator Coordinator { get; private set; } = null!;
        public EntityId Original { get; private init; }
        public List<WritePipelineStage> Stages { get; } = [];

        public void OnStage(WritePipelineStage stage) => Stages.Add(stage);

        public static async Task<Harness> CreateAsync(bool allow = true)
        {
            var storage = new InMemoryAssetStorage();
            var entities = new InMemoryEntityStore(storage, new FixedTimeProvider(At));
            using var body = JsonDocument.Parse("""{"name":"original"}""");
            var original = await entities.CreateAsync(Accepted, body,
                new CreateOptions("entity", "test", "original", Actor, Tenant, At.AddDays(-1), ExplicitLocalPart: "original"));
            var harness = new Harness { Entities = entities, Original = original };
            harness.Coordinator = new NodeHierarchyCompositeCoordinator(
                entities, new InMemoryHierarchyService(storage),
                new HierarchyAuthorizedAuditWriter(new InMemoryAuditLog(storage)),
                TestAuthorization.Gate(allow), new FixedTimeProvider(At), new SchemaRefusingValidator(), harness);
            return harness;
        }
    }

    private sealed class SchemaRefusingValidator : IEntityValidator
    {
        public Task ValidateAsync(SchemaId schema, JsonDocument body, CancellationToken ct = default) =>
            schema == Refused
                ? throw new EntityValidationException("refused", "split.pipeline.refused", ["/name"])
                : Task.CompletedTask;
    }

    private sealed class FixedTimeProvider(DateTimeOffset now) : TimeProvider
    {
        public override DateTimeOffset GetUtcNow() => now;
    }
}

using System;
