                $"Data Source={Path.Combine(_directory, "roster.db")};Pooling=False",
                sqlite => sqlite.MigrationsHistoryTable(NodeLocalRosterDbContext.MigrationsHistoryTableName)));
            services.AddSingleton(new NodeTeamRoster(roster));
            services.AddSingleton<IOperationSigner>(Founder);
            services.AddSingleton(_trail);
            services.AddAuthorizationRefusalAudit();
            services.AddSingleton(sp => new NodeAdministratorAuthority(
                sp.GetRequiredService<IDbContextFactory<NodeLocalRosterDbContext>>(),
                TimeProvider.System, TestAuthorization.AllowGate()));
            services.AddSingleton(TimeProvider.System);
            services.AddNodeRoster();
            return services.BuildServiceProvider();
        }
        public static async Task<Fixture> CreateAsync(PermissionSet? peer = null, IAuditTrail? trail = null)
        {
            var f = new Fixture { _trail = trail ?? new InMemoryAuditTrail() };
            Directory.CreateDirectory(f._directory);
            f.Valid = MemberRoster.Genesis(Tenant, "founder", f.Founder, Verifier, At, Guid.NewGuid())
                .Admit("founder", f.Founder, "peer", KeyPair.Generate().PrincipalId,
                    peer ?? Floor, Verifier, At.AddMinutes(1), Guid.NewGuid(),
                    newDmPublicKey: PrincipalId.FromBytes(f.PeerTransport).ToBase64Url(),
                    newXWingPublicKey: Convert.ToBase64String(new byte[1216]).TrimEnd('='));
            f.Provider = f.NewProvider(f.Valid);
            var factory = f.Provider.GetRequiredService<IDbContextFactory<NodeLocalRosterDbContext>>();
            await using (var db = await factory.CreateDbContextAsync()) await db.Database.MigrateAsync();
            f.Live = f.Provider.GetRequiredService<NodeTeamRoster>();
            f.Projection = f.Provider.GetRequiredService<RosterCrdtProjection>();
            foreach (var a in f.Valid.EnumerateAdmissions())
                await f.PublishAsync(RosterRecordCrdtState.FromAdmission(a with { TransportPublicKey = a.Admission.IsGenesis ? null : f.PeerTransport }));
            Assert.True(f.Live.Current.Contains("peer"));
            Assert.Equal("peer", f.Live.PartyIdForTransportKey(f.PeerTransport));
            Assert.NotNull(f.Live.DmPublicKeyOf("peer"));
            Assert.NotNull(f.Live.XWingPublicKeyOf("peer"));
            return f;
        }
        public MemberRevocationRecord Removal(string party) => new(Tenant.ToString("D"), party,
            RosterSigning.SignRevocation(Founder, Tenant, party, "founder", At.AddHours(1), Guid.NewGuid()));
        public async Task PublishAsync(RosterRecordCrdtState record)
        {
            if (record.AdmittedByPublicKey == Attacker.IssuerId.ToBase64Url())
            {
                await MergeAsync([record]);
                return;
            }
            await Projection.PublishLocalAsync(record, default);
            await Projection.DrainPendingReconcilesAsync();
        }
        public async Task MergeAsync(IEnumerable<RosterRecordCrdtState> records, bool drain = true)
        {
            var materialized = records.ToArray();
            var factory = Provider.GetRequiredService<IDbContextFactory<NodeLocalRosterDbContext>>();
            var attested = materialized.Select(record =>
            {
                var signer = record.AdmittedByPublicKey == Attacker.IssuerId.ToBase64Url() ? Attacker : Founder;
                return record.AttestReceipt(signer, ReferenceEquals(signer, Founder) ? "founder" : record.AdmittedByPartyId,
                    NodeRosterRecord.IssuedAtOr(record, At));
            }).ToArray();
            await using (var db = await factory.CreateDbContextAsync())
            {
                // T-909 ck-9: a record whose instant does not parse cannot become a durable row (it would have
                // to be re-dated), so it reaches the projection through the CRDT log alone.
                var ids = await db.RosterRecords.Select(row => row.Id).ToListAsync();
                db.RosterRecords.AddRange(attested.Where(record => !ids.Contains(record.RecordId)
                        && NodeRosterRecord.TryParseIssuedAt(record, out _))
                    .Select(NodeRosterRecord.FromCrdtState));
                await db.SaveChangesAsync();
            }
            await using var raw = new Harborline.Api.Kernel.Crdt.CrdtProjection<RosterCrdtSchema>(
                new YDotNetCrdtEngine(), new RosterCrdtSchema(_ => Task.CompletedTask));
            raw.Mutate(schema => schema.PushMany(attested));
            await Projection.ApplyInboundDeltaAsync(RosterCrdtProjection.DocumentId, 1,
                raw.EncodeDelta(ReadOnlyMemory<byte>.Empty), default);
            if (drain) await Projection.DrainPendingReconcilesAsync();
        }
        public async Task PoisonAsync(bool drain = true)
        {
            // The candidate lies about its age; durable append precedence must still choose the real root.
            var poison = MemberRoster.Genesis(Tenant, "poison", Attacker, Verifier, At.AddDays(-1), Guid.NewGuid())
                .Admit("poison", Attacker, "intruder", KeyPair.Generate().PrincipalId,
                    PermissionCompositions.Owner, Verifier, At, Guid.NewGuid())
                .Admit("poison", Attacker, "peer", KeyPair.Generate().PrincipalId,
                    Floor, Verifier, At, Guid.NewGuid());
            var records = poison.EnumerateAdmissions().Select(a =>
                RosterRecordCrdtState.FromAdmission(a with { TransportPublicKey = PoisonTransport })).ToArray();
            if (!drain)
            {
                foreach (var record in records) await Projection.PublishLocalAsync(record, default);
                return;
            }
            await MergeAsync(records);
        }
        public async Task<List<AuditRecord>> RowsAsync(Guid? tenant = null)
        {
            var rows = new List<AuditRecord>();
            await foreach (var row in _trail.QueryAsync(new AuditQuery(new TenantId((tenant ?? Tenant).ToString("D"))))) rows.Add(row);
            return rows;
        }
        public async ValueTask DisposeAsync()
        {
            await Projection.DisposeAsync();
            await Provider.DisposeAsync();
            Directory.Delete(_directory, recursive: true);
        }
    }
}

using System.Text;
using Harborline.Api.Foundation.Crypto;
using Harborline.Api.Foundation.IdentityAtlas;
using Harborline.Api.Foundation.IdentityAtlas.Permissions;
using Harborline.Api.LocalNodeHost.Data.Roster;

namespace Harborline.Api.LocalNodeHost.Tests.Entities;

public sealed class RosterPermissionSignatureTests
{
    private static readonly Guid Tenant = Guid.Parse("29100000-0000-0000-0000-000000000001");
    private static readonly DateTimeOffset Now = DateTimeOffset.UnixEpoch.AddDays(1);
    private static readonly IOperationVerifier Verifier = new Ed25519Verifier();

    private static (MemberRoster Roster, MemberAdmissionRecord Root, MemberAdmissionRecord Member) Fixture()
    {
        var founder = new Ed25519Signer(KeyPair.Generate());
        var roster = MemberRoster.Genesis(Tenant, "founder", founder, Verifier, Now, Guid.NewGuid())
            .Admit("founder", founder, "member", KeyPair.Generate().PrincipalId,
                PermissionCompositions.Member, Verifier, Now, Guid.NewGuid());
        return (roster, roster.EnumerateAdmissions().Single(a => a.Admission.IsGenesis),
            roster.EnumerateAdmissions().Single(a => !a.Admission.IsGenesis));
    }

    [Fact]
    public void SignedProvenanceSubstitutionIsRefusedAcrossWireAndDurableRoundTrips()
    {
        var (_, root, member) = Fixture();
        var wire = RosterRecordCrdtState.FromAdmission(member) with
        {
            MintingSessionEvidence = "tampered-session",
        };
        var row = NodeRosterRecord.FromCrdtState(RosterRecordCrdtState.FromAdmission(member));
        row.MintingSessionEvidence = "tampered-session";

        foreach (var forged in new[] { wire.ToAdmissionOrNull()!,
                     NodeRosterRecord.ToCrdtState(row).ToAdmissionOrNull()! })
        {
            Assert.Equal(member.Admission.Signature, forged.Admission.Signature);
            Assert.False(RosterSigning.VerifyAdmission(Tenant, forged.PartyId, forged.PublicKey,
                forged.Admission, Verifier));
            Assert.False(Rebuild(root, forged).Contains("member"));
        }
    }

    [Fact]
    public void PermissionFreeAdmissionRoundTripsAndLocalGrantDoesNotRewriteMembershipEvidence()
    {
        var (roster, root, member) = Fixture();
        var hydrated = NodeRosterRecord.ToCrdtState(NodeRosterRecord.FromCrdtState(
            RosterRecordCrdtState.FromAdmission(member))).ToAdmissionOrNull()!;
        Assert.True(RosterSigning.VerifyAdmission(Tenant, "member", member.PublicKey,
            hydrated.Admission, Verifier));
        Assert.True(Rebuild(root, hydrated).Contains("member"));

        var narrowed = roster.Grant("founder", "member", PermissionSet.Empty);
        var revoked = narrowed.Revoke("founder", "member");
        foreach (var state in new[] { narrowed, revoked })
        {
            var exported = state.EnumerateAdmissions().Single(a => a.PartyId == "member");
            Assert.Equal(member.Admission, exported.Admission);
            Assert.Equal(member.PublicKey, exported.PublicKey);
        }
    }

    [Fact]
    public async Task CanonicalBytesMarkVersionWithoutPermissionSetAndRejectOldShapeSignature()
    {
        var signer = new CapturingSigner(new Ed25519Signer(KeyPair.Generate()));
        var nonce = Guid.NewGuid();
        var admission = RosterSigning.SignAdmission(signer, Tenant, "member", signer.IssuerId,
            "founder", false, Now, nonce);
        Assert.Contains("\"FormatVersion\":4", signer.CanonicalBytes);
        Assert.DoesNotContain("AdmittedPermissions", signer.CanonicalBytes, StringComparison.Ordinal);
        Assert.True(RosterSigning.VerifyAdmission(Tenant, "member", signer.IssuerId, admission, Verifier));
        var record = Assert.IsType<AdmissionRecord>(signer.Payload);
        var same = RosterSigning.SignAdmission(signer, Tenant, "member", signer.IssuerId,
            "founder", false, Now, nonce);
        Assert.Equal(admission.Signature, same.Signature);

        var old = await signer.SignAsync(new
        {
            record.TeamId, record.AdmittedPartyId, record.AdmittedPublicKey, record.AdmittedByPartyId,
            record.AdmittedByPublicKey, record.IsGenesis, record.AdmittedDmPublicKey,
            record.AdmittedXWingPublicKey, record.AdmittedViaTokenId, record.AdmittedUnderSessionEvidence,
            AdmittedPermissions = new[] { "records:read" }, FormatVersion = 3,
        }, Now, nonce);
        Assert.False(RosterSigning.VerifyAdmission(Tenant, "member", signer.IssuerId,
            admission with { Signature = old.Signature.ToBase64Url() }, Verifier));
    }

    private static MemberRoster Rebuild(params MemberAdmissionRecord[] admissions) =>
        MemberRoster.FromSyncedRecords(admissions, [], Verifier);

    private sealed class CapturingSigner(IOperationSigner inner) : IOperationSigner
    {
        public PrincipalId IssuerId => inner.IssuerId;
        public object? Payload { get; private set; }
        public string CanonicalBytes { get; private set; } = "";
        public ValueTask<SignedOperation<T>> SignAsync<T>(T payload, DateTimeOffset issuedAt, Guid nonce,
            CancellationToken ct = default)
        {
            Payload = payload;
            CanonicalBytes = Encoding.UTF8.GetString(CanonicalJson.SerializeSignable(payload, IssuerId, issuedAt, nonce));
            return inner.SignAsync(payload, issuedAt, nonce, ct);
        }
    }
}

