        try
        {
            await using (var db = new NodeLocalRosterDbContext(options))
            {
                await db.Database.EnsureCreatedAsync();
                db.RosterRecords.AddRange(rows);
                await db.SaveChangesAsync();
            }

            var orderTime = NodeRosterRecord.OrderTimes(rows);
