public sealed class RosterSignedFloorTests
{
    private static readonly Guid Tenant = Guid.Parse("29120000-0000-0000-0000-000000000001");
    private static readonly DateTimeOffset At = DateTimeOffset.UnixEpoch.AddDays(1);
    private static readonly IOperationVerifier Verifier = new Ed25519Verifier();
    private static PermissionSet Floor => PermissionSet.Of(Permission.GrantPermissions,
        Permission.OrgTransferOwnership, Permission.MembersAdmit);

    private static (MemberRoster Roster, Ed25519Signer Founder) Fixture(PermissionSet successor)
    {
        var founder = new Ed25519Signer(KeyPair.Generate());
        return (MemberRoster.Genesis(Tenant, "founder", founder, Verifier, At, Guid.NewGuid())
            .Admit("founder", founder, "successor", KeyPair.Generate().PrincipalId,
                successor, Verifier, At, Guid.NewGuid()), founder);
    }

    private static MemberRevocationRecord Removal(Ed25519Signer founder, string target = "founder") =>
        new(Tenant.ToString("D"), target, RosterSigning.SignRevocation(founder, Tenant, target,
            "founder", At.AddMinutes(1), Guid.NewGuid()));

    [Theory]
    [InlineData(Permission.GrantPermissions)]
    [InlineData(Permission.OrgTransferOwnership)]
    [InlineData(Permission.MembersAdmit)]
    public void ProjectedGrantCanAuthorizeFounderRemovalOnceLiveFloorExists(string missing)
    {
        var (roster, _) = Fixture(Floor.Without(missing));
        var projected = roster.Grant("founder", "successor", Floor);
        var removed = projected.Revoke("founder", "founder");
        Assert.False(removed.Contains("founder"));
        Assert.True(removed.Contains("successor"));
        Assert.True(removed.HasRootGrantHolder());
    }

    [Fact]
    public void NarrowedSignedSuccessorCannotAuthorizeFounderRemoval()
    {
        var (roster, _) = Fixture(Floor);
        var projected = roster.Grant("founder", "successor", PermissionSet.Empty);
        var refusal = Assert.Throws<RosterGuardException>(() => projected.Revoke("founder", "founder"));
        Assert.Equal(MemberRoster.NoBrickingFloorCode, refusal.Code);
        Assert.True(projected.Contains("founder"));
        Assert.True(projected.HasRootGrantHolder());
        Assert.True(projected.ValidatesToGenesis(Verifier));
    }

    [Theory]
    [InlineData(Permission.GrantPermissions)]
    [InlineData(Permission.OrgTransferOwnership)]
    [InlineData(Permission.MembersAdmit)]
    public void GrantCannotNarrowLastLiveFloorHolder(string missing)
    {
        var (roster, _) = Fixture(Floor);
        var projected = roster.Grant("founder", "successor", PermissionSet.Empty);
        var before = projected.Members.ToArray();
        var refusal = Assert.Throws<RosterGuardException>(() =>
            projected.Grant("founder", "founder", projected.PermissionsOf("founder")!.Without(missing)));
        Assert.Equal(MemberRoster.NoBrickingFloorCode, refusal.Code);
        Assert.Equal(before, projected.Members);
        Assert.True(projected.HasRootGrantHolder());
    }

    [Fact]
    public async Task RefusalAuditReportsEachRecordOnceAndClearsOnce()
    {
        await using var fixture = await AuditFixture.CreateAsync();
        await fixture.Projection.ReconcileAsync(CancellationToken.None);
        Assert.Single(await fixture.RowsAsync());
        await Task.WhenAll(Enumerable.Range(0, 3).Select(_ =>
            fixture.Projection.ReconcileAsync(CancellationToken.None)));
        Assert.Single(await fixture.RowsAsync());

        await fixture.Projection.PublishLocalAsync(
            RosterRecordCrdtState.FromRevocation(Removal(fixture.Founder)), CancellationToken.None);
        await fixture.Projection.DrainPendingReconcilesAsync();
        var rows = await fixture.RowsAsync();
        Assert.Equal(2, rows.Count);
        Assert.All(rows, row => Assert.Equal("AuthorizationRefused", row.EventType.Value));
        Assert.Equal(2, rows.Select(row => JsonSerializer.Serialize(row.Payload.Payload.Body)).Distinct().Count());

        var admitted = fixture.Roster.Admit("founder", fixture.Founder, "third", fixture.Roster.PublicKeyOf("founder")!.Value,
            Floor, Verifier, At.AddMinutes(2), Guid.NewGuid());
        await fixture.Projection.PublishLocalAsync(RosterRecordCrdtState.FromAdmission(
            admitted.EnumerateAdmissions().Single(a => a.PartyId == "third")), CancellationToken.None);
        await fixture.Projection.DrainPendingReconcilesAsync();
        Assert.Empty(fixture.Live.Current.RefusedRevocations);
        Assert.False(fixture.Live.Current.Contains("founder"));
        rows = await fixture.RowsAsync();
        Assert.Equal(4, rows.Count);
        Assert.Equal(2, rows.Count(row => row.EventType.Value == "AuthorizationRefusalCleared"));
        Assert.All(rows, row => Assert.True(Verifier.Verify(row.Payload)));
        await fixture.Projection.ReconcileAsync(CancellationToken.None);
        Assert.Equal(4, (await fixture.RowsAsync()).Count);
    }

    [Fact]
    public async Task DuplicateRefusalRecordsFromAnotherReplicaProduceOneAudit()
    {
        await using var fixture = await AuditFixture.CreateAsync();
        await fixture.MergeDuplicateRefusalAsync();
        Assert.Equal(2, fixture.Live.Current.RefusedRevocations.Count);
        Assert.Single(await fixture.RowsAsync());
        await fixture.Projection.ReconcileAsync(CancellationToken.None);
        Assert.Single(await fixture.RowsAsync());
    }

    [Fact]
    public async Task RefusalClearIsAuditedOnlyAfterTheRebuildIsAdopted()
    {
        await using var fixture = await AuditFixture.CreateAsync();
        await fixture.Projection.ReconcileAsync(CancellationToken.None);
        var before = Assert.Single(await fixture.RowsAsync());
        var foreign = fixture.Roster.Admit("founder", fixture.Founder, "foreign", KeyPair.Generate().PrincipalId,
            Floor, Verifier, At.AddMinutes(2), Guid.NewGuid());
        await fixture.Projection.PublishLocalAsync(RosterRecordCrdtState.FromAdmission(
            foreign.EnumerateAdmissions().Single(a => a.PartyId == "foreign")), CancellationToken.None);
        await fixture.Projection.DrainPendingReconcilesAsync();
        Assert.True(fixture.Live.Current.Contains("founder"));
        Assert.Equal(before, Assert.Single(await fixture.RowsAsync()));

        // Bind this node's key to a successor so the cleared rebuild passes the own-membership guard.
        var own = fixture.Roster.Admit("founder", fixture.Founder, "own", fixture.Founder.IssuerId,
            Floor, Verifier, At.AddMinutes(3), Guid.NewGuid());
        await fixture.Projection.PublishLocalAsync(RosterRecordCrdtState.FromAdmission(
            own.EnumerateAdmissions().Single(a => a.PartyId == "own")), CancellationToken.None);
        await fixture.Projection.DrainPendingReconcilesAsync();
        Assert.False(fixture.Live.Current.Contains("founder"));
        var cleared = Assert.Single(await fixture.RowsAsync(), row => row.EventType.Value == "AuthorizationRefusalCleared");
        Assert.Equal(JsonSerializer.Serialize(before.Payload.Payload.Body), JsonSerializer.Serialize(cleared.Payload.Payload.Body));
        await fixture.Projection.ReconcileAsync(CancellationToken.None);
        Assert.Equal(2, (await fixture.RowsAsync()).Count);
    }

    [Fact]
    public async Task RefusalAuditIsAwaitedWithoutBlockingTheReconcileCaller()
    {
        var trail = new DelayedAuditTrail();
        await using var fixture = await AuditFixture.CreateAsync(trail);
        var returned = new TaskCompletionSource<Task>(TaskCreationOptions.RunContinuationsAsynchronously);
        var caller = Task.Run(() =>
        {
            var reconcile = fixture.Projection.ReconcileAsync(CancellationToken.None);
            returned.SetResult(reconcile);
            return reconcile;
        });
        try
        {
            await trail.Started.Task.WaitAsync(TimeSpan.FromSeconds(5));
            var reconcile = await returned.Task.WaitAsync(TimeSpan.FromSeconds(5));
            Assert.False(reconcile.IsCompleted);
            Assert.Empty(await fixture.RowsAsync());
        }
        finally
        {
            trail.Release.TrySetResult();
            await caller.WaitAsync(TimeSpan.FromSeconds(5));
        }
        Assert.Single(await fixture.RowsAsync());
    }

    private sealed class DelayedAuditTrail : IAuditTrail
    {
        private readonly InMemoryAuditTrail _inner = new();
        public TaskCompletionSource Started { get; } = new(TaskCreationOptions.RunContinuationsAsynchronously);
        public TaskCompletionSource Release { get; } = new(TaskCreationOptions.RunContinuationsAsynchronously);
        public async ValueTask AppendAsync(AuditRecord record, CancellationToken ct = default)
        {
            Started.TrySetResult();
            await Release.Task.WaitAsync(ct);
            await _inner.AppendAsync(record, ct);
        }
        public IAsyncEnumerable<AuditRecord> QueryAsync(AuditQuery query, CancellationToken ct = default) =>
            _inner.QueryAsync(query, ct);
    }

    private sealed class AuditFixture : IAsyncDisposable
    {
        private readonly SqliteConnection _connection;
        private readonly ServiceProvider _provider;
        private readonly IAuditTrail _trail;
        public MemberRoster Roster { get; }
        public Ed25519Signer Founder { get; }
        public NodeTeamRoster Live { get; }
        public RosterCrdtProjection Projection { get; }

        private AuditFixture(SqliteConnection connection, ServiceProvider provider, IAuditTrail trail,
            MemberRoster roster, Ed25519Signer founder, NodeTeamRoster live, RosterCrdtProjection projection)
        {
            (_connection, _provider, _trail, Roster, Founder, Live, Projection) =
                (connection, provider, trail, roster, founder, live, projection);
        }

        public static async Task<AuditFixture> CreateAsync(IAuditTrail? trail = null)
        {
            var (roster, founder) = Fixture(Floor);
            trail ??= new InMemoryAuditTrail();
            var connection = new SqliteConnection("Data Source=:memory:");
            await connection.OpenAsync();
            var services = new ServiceCollection();
            services.AddDbContextFactory<NodeLocalRosterDbContext>(o => o.UseSqlite(connection));
            var provider = services.BuildServiceProvider();
            var factory = provider.GetRequiredService<IDbContextFactory<NodeLocalRosterDbContext>>();
            await using (var db = await factory.CreateDbContextAsync()) await db.Database.EnsureCreatedAsync();
            var genesis = roster.EnumerateAdmissions().Single(a => a.Admission.IsGenesis);
            // Start with only genesis: two distinct refused records can target the same last holder.
            var live = new NodeTeamRoster(roster);
            AuthorizationRefusalAudit? audit = null;
            var projection = new RosterCrdtProjection(TimeProvider.System, new YDotNetCrdtEngine(), factory, Verifier,
                founder, NullLogger<RosterCrdtProjection>.Instance, nodeRoster: live, refusalAudit: () => audit,
                // The successor admitted later ("third") holds the floor as a GRANT - that is what clears the
                // refusal now that no permission set rides the wire.
                rosterAuthority: () => new TestRosterAuthority(("third", Floor), ("own", Floor)));
            await projection.PublishLocalAsync(RosterRecordCrdtState.FromAdmission(genesis), CancellationToken.None);
            await projection.PublishLocalAsync(RosterRecordCrdtState.FromRevocation(Removal(founder)), CancellationToken.None);
            await projection.DrainPendingReconcilesAsync();
            audit = new AuthorizationRefusalAudit(trail, founder, NullLogger<AuthorizationRefusalAudit>.Instance);
            return new AuditFixture(connection, provider, trail, roster, founder, live, projection);
        }

        public async Task MergeDuplicateRefusalAsync()
        {
            var factory = _provider.GetRequiredService<IDbContextFactory<NodeLocalRosterDbContext>>();
            await using var sender = new RosterCrdtProjection(TimeProvider.System, new YDotNetCrdtEngine(), factory, Verifier,
                Founder, NullLogger<RosterCrdtProjection>.Instance);
            await sender.PublishLocalAsync(Projection.Snapshot().Single(r => r.Kind == RosterRecordKind.Revocation),
                CancellationToken.None);
            await sender.DrainPendingReconcilesAsync();
            var delta = await sender.EncodeOutboundDeltaAsync(RosterCrdtProjection.DocumentId,
                ReadOnlyMemory<byte>.Empty, CancellationToken.None);
            Assert.NotNull(delta);
            await Projection.ApplyInboundDeltaAsync(RosterCrdtProjection.DocumentId, 1, delta.Value, CancellationToken.None);
            await Projection.DrainPendingReconcilesAsync();
        }

        public async Task<List<AuditRecord>> RowsAsync()
        {
            var rows = new List<AuditRecord>();
            await foreach (var row in _trail.QueryAsync(new AuditQuery(new TenantId(Tenant.ToString("D"))))) rows.Add(row);
            return rows;
        }

        public async ValueTask DisposeAsync()
        {
            await Projection.DisposeAsync();
            await _provider.DisposeAsync();
            await _connection.DisposeAsync();
        }
    }

    [Fact]
    public void OrdinaryRemovalConvergesAndDoesNotLeaveAStaleRefusal()
    {
        var (roster, founder) = Fixture(Floor);
        var admissions = roster.EnumerateAdmissions().ToArray();
        var removal = Removal(founder);
        var pending = MemberRoster.FromSyncedRecords(admissions.Where(a => a.Admission.IsGenesis),
            [removal], Verifier);
        Assert.Single(pending.RefusedRevocations);
        foreach (var ordered in new[] { admissions, admissions.Reverse().ToArray() })
        {
            // The successor's floor is a GRANT now - nothing on the wire says it - so the replay reads it from
            // the grant store, and only then does the no-bricking floor let the founder go.
            var complete = MemberRoster.FromSyncedRecords(ordered, [removal, removal], Verifier,
                authority: new TestRosterAuthority(("successor", Floor)));
            Assert.False(complete.Contains("founder"));
            Assert.True(complete.Contains("successor"));
            Assert.Empty(complete.RefusedRevocations);
            Assert.Null(complete.PermissionsOf("successor"));
            Assert.True(complete.ValidatesToGenesis(Verifier));
        }
    }

    [Fact]
    public void NothingCarriedOnTheWireSuppliesTheFloorOrTheRevokerAuthority()
    {
        var (roster, founder) = Fixture(Floor);
        var admissions = roster.EnumerateAdmissions().ToArray();
        var removal = Removal(founder);
        // No grant for the successor: the replay must refuse the removal that would leave no root-grant
        // holder, exactly as the local path refuses it, and must not silently drop the founder.
        var refused = MemberRoster.FromSyncedRecords(admissions, [removal], Verifier);
        Assert.True(refused.Contains("founder"));
        Assert.Equal(MemberRoster.NoBrickingFloorCode, Assert.Single(refused.RefusedRevocations).Code);

        // A revocation signed by a member who holds no members:revoke grant is DROPPED, not refused.
        var successorSigner = new Ed25519Signer(KeyPair.Generate());
        var founderSigner = new Ed25519Signer(KeyPair.Generate());
        var team = MemberRoster.Genesis(Tenant, "founder", founderSigner, Verifier, At, Guid.NewGuid())
            .Admit("founder", founderSigner, "successor", successorSigner.IssuerId, Floor, Verifier, At, Guid.NewGuid());
        var successorSigned = new MemberRevocationRecord(Tenant.ToString("D"), "founder",
            RosterSigning.SignRevocation(successorSigner, Tenant, "founder", "successor",
                At.AddMinutes(2), Guid.NewGuid()));
        var dropped = MemberRoster.FromSyncedRecords(team.EnumerateAdmissions(), [successorSigned], Verifier);
        Assert.True(dropped.Contains("founder"));
        Assert.Empty(dropped.RefusedRevocations);
    }

    [Fact]
    public async Task InboundRebuildCarriesTheFloorReportIntoTheExistingRefusalAudit()
    {
        var (roster, founder) = Fixture(Floor.Without(Permission.MembersAdmit));
        var trail = new InMemoryAuditTrail();
        var services = new ServiceCollection();
        services.AddLogging();
        await using var connection = new SqliteConnection("Data Source=:memory:");
        await connection.OpenAsync();
        services.AddDbContextFactory<NodeLocalRosterDbContext>(o => o.UseSqlite(connection));
        services.AddSingleton(new NodeTeamRoster(roster));
        services.AddSingleton<IOperationSigner>(founder);
        services.AddSingleton<IAuditTrail>(trail);
        services.AddAuthorizationRefusalAudit();
        services.AddSingleton(TimeProvider.System);
        // The grant store holds exactly what the founder granted the successor - short of the root floor - so
        // the replay refuses the founder's removal and the refusal reaches the audit.
        services.AddSingleton<IRosterAuthority>(
            new TestRosterAuthority(("successor", Floor.Without(Permission.MembersAdmit))));
        services.AddNodeRoster();
        await using var provider = services.BuildServiceProvider();
        var projection = provider.GetRequiredService<RosterCrdtProjection>();
        var records = roster.EnumerateAdmissions().Select(a => RosterRecordCrdtState.FromAdmission(a))
            .Append(RosterRecordCrdtState.FromRevocation(Removal(founder))).ToArray();
        var factory = provider.GetRequiredService<IDbContextFactory<NodeLocalRosterDbContext>>();
        await using (var db = await factory.CreateDbContextAsync()) await db.Database.EnsureCreatedAsync();
        await using var sender = new RosterCrdtProjection(TimeProvider.System, new YDotNetCrdtEngine(), factory, Verifier,
            founder, NullLogger<RosterCrdtProjection>.Instance);
        foreach (var record in records) await sender.PublishLocalAsync(record, CancellationToken.None);
        await sender.DrainPendingReconcilesAsync();
        var delta = await sender.EncodeOutboundDeltaAsync(RosterCrdtProjection.DocumentId,
            ReadOnlyMemory<byte>.Empty, CancellationToken.None);
        Assert.NotNull(delta);
        await projection.ApplyInboundDeltaAsync(RosterCrdtProjection.DocumentId, 1, delta.Value, CancellationToken.None);
        await projection.DrainPendingReconcilesAsync();
        var current = provider.GetRequiredService<NodeTeamRoster>().Current;
        Assert.Equal(roster.Members.Select(m => (m.PartyId, m.PublicKey)).OrderBy(m => m.PartyId),
            current.Members.Select(m => (m.PartyId, m.PublicKey)).OrderBy(m => m.PartyId));
        var refusal = Assert.Single(current.RefusedRevocations);
        var rows = new List<AuditRecord>();
        await foreach (var row in trail.QueryAsync(new AuditQuery(new TenantId(Tenant.ToString("D")))))
            rows.Add(row);
        var audit = Assert.Single(rows);
        Assert.Equal(AuthorizationRefusalAudit.AuthorizationRefusedEventType, audit.EventType);
        Assert.True(Verifier.Verify(audit.Payload));
        using var body = JsonDocument.Parse(JsonSerializer.Serialize(audit.Payload.Payload.Body));
        Assert.Equal(refusal.Code, body.RootElement.GetProperty("code").GetString());
        Assert.True(body.RootElement.GetProperty("preDecision").GetBoolean());
        Assert.Equal(JsonSerializer.Serialize(refusal), body.RootElement.GetProperty("diagnostic").GetString());
        Assert.Equal("founder", audit.Actor?.Value);
    }
}

using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging.Abstractions;

using Harborline.Api.Foundation.Crypto;
using Harborline.Api.Foundation.IdentityAtlas;
using Harborline.Api.Kernel.Crdt;
using Harborline.Api.Kernel.Crdt.Backends;
using Harborline.Api.LocalNodeHost.Data.Roster;
using Harborline.Api.LocalNodeHost.Enrollment;
using Harborline.Api.LocalNodeHost.Health;

namespace Harborline.Api.LocalNodeHost.Tests.Entities;

/// <summary>
/// THE app/DEV-SEED COLD-START CRASH (bug-1333). When the Harborline App spawns the node with a
/// <c>HARBORLINE_DEV_SEED_HEX</c> override but points it at a DURABLE store left over from a PRIOR root seed (a changed
/// dev seed, or a <c>HARBORLINE_DEV_DATA_DIR</c> reused across distinct seeds), the node crashed at boot with
/// <c>"Comms author binding is inconsistent: the seeded trust roster does not bind the active member … (gap #2)"</c>.
/// </summary>
/// <remarks>
/// <para>
/// <b>The mechanism.</b> <c>RosterSyncBootstrapHostedService</c> runs cold-start hydration FIRST — it pushes the
/// durable <c>roster_records</c> onto the CRDT list, which fires the reconcile + <c>RebuildLiveRoster</c> BEFORE the
/// live, seed-derived genesis has been published as a synced record. A stale durable genesis (signed by the OLD seed's
/// key) therefore rebuilt cleanly and <c>AdoptSyncedRoster</c> REPLACED <see cref="NodeTeamRoster.Current"/> with it.
/// <see cref="HostedCommsApiEndpoint"/> then resolved <c>Current.GenesisPartyId</c> bound to the OLD key — which no
/// longer equals the comms signer derived from the CURRENT seed — and its forge-proof consistency assertion
/// fails-closed, crashing the host. The STANDALONE node never hit this: its store was seed-consistent.
/// </para>
/// <para>
/// <b>The fix.</b> <see cref="RosterCrdtProjection.RebuildLiveRoster"/> now refuses to adopt a rebuilt roster whose
/// genesis is NOT this node's live seed-derived genesis (same party id AND same bound key) — it keeps the local,
/// seed-correct roster (fail-safe, mirroring the dual-genesis guard). A legitimate team adoption (a joiner taking on an
/// admitter's team) does NOT come through this hydration rebuild — it runs through <c>NodeWireEnrollmentClient</c> /
/// own-team supersession — so this guard only blocks a STALE/FOREIGN durable genesis from silently overwriting the
/// live one.
/// </para>
/// <para>
/// These tests drive the REAL hydration path over a REAL persisted SQLite store + REAL YDotNet engine, then assert the
/// EXACT production fail-closed assertion in <see cref="HostedCommsApiEndpoint"/> by reproducing its consistency check
/// against the resulting live roster (red-pre / green-post), and prove the standalone (seed-consistent) path is
/// unaffected.
/// </para>
/// </remarks>
public sealed class RosterStaleSeedGenesisGuardTests : IAsyncLifetime
{
    private static readonly IOperationVerifier Verifier = new Ed25519Verifier();
    private static readonly Guid TeamId = Guid.Parse("ca12ca12-0000-0000-0000-00000000d133");

    private readonly List<string> _tempDirs = new();
    private readonly List<RosterCrdtProjection> _projections = new();
    private readonly List<ServiceProvider> _providers = new();
    private readonly List<NodePrincipalSigner> _signers = new();

    public Task InitializeAsync() => Task.CompletedTask;

    public async Task DisposeAsync()
    {
        foreach (var p in _projections) await p.DisposeAsync();
        foreach (var sp in _providers) await sp.DisposeAsync();
        foreach (var s in _signers) s.Dispose();
        foreach (var dir in _tempDirs)
        {
            try { if (Directory.Exists(dir)) Directory.Delete(dir, recursive: true); }
            catch { /* best-effort temp cleanup */ }
        }
    }

    /// <summary>A node identity derived from a 32-byte seed (the Harborline App injects this via HARBORLINE_DEV_SEED_HEX →
    /// LocalNode__RootSeedHex). The party id mirrors Program.cs's gap-#2 derivation: os:&lt;user&gt;#&lt;key8&gt;.</summary>
    private sealed record SeedIdentity(string PartyId, NodePrincipalSigner Signer)
    {
        public static SeedIdentity From(byte seedFill, List<NodePrincipalSigner> sink)
        {
            var signer = new NodePrincipalSigner(Seed(seedFill));
            sink.Add(signer);
            // Mirror Program.cs gap-#2: 8-hex prefix of the signing key → per-seed-distinct party id.
            var key8 = Convert.ToHexString(signer.Signer.IssuerId.AsSpan()[..4]).ToLowerInvariant();
            return new SeedIdentity($"os:chris#{key8}", signer);
        }
    }

    private static byte[] Seed(byte fill)
    {
        var s = new byte[32];
        Array.Fill(s, fill);
        return s;
    }

    /// <summary>The genesis self-admission Program.cs seeds at boot for a given seed identity (StableGenesis — the
    /// same deterministic shape, so a restart re-derives byte-identically).</summary>
    private static MemberRoster GenesisFor(SeedIdentity id) =>
        MemberRoster.StableGenesis(TeamId, id.PartyId, id.Signer.Signer, Verifier);

    /// <summary>Build a node's RosterCrdtProjection over a caller-supplied SQLite connection (so a "reboot" can re-open
    /// the SAME durable store). <paramref name="bootGenesis"/> is the in-memory genesis the fresh process seeds.</summary>
    private async Task<(RosterCrdtProjection Projection, NodeTeamRoster Roster)> NewNodeAsync(
        MemberRoster bootGenesis, string connectionString, IOperationSigner attestationSigner)
    {
        var services = new ServiceCollection();
        services.AddLogging();
        services.AddDbContextFactory<NodeLocalRosterDbContext>(opt => opt.UseSqlite(connectionString));
        services.AddSingleton<ICrdtEngine, YDotNetCrdtEngine>();

        var sp = services.BuildServiceProvider();
        _providers.Add(sp);
        var factory = sp.GetRequiredService<IDbContextFactory<NodeLocalRosterDbContext>>();
        await using (var ctx = await factory.CreateDbContextAsync())
            await ctx.Database.EnsureCreatedAsync();

        var roster = new NodeTeamRoster(bootGenesis);
        var projection = new RosterCrdtProjection(TimeProvider.System,
            sp.GetRequiredService<ICrdtEngine>(), factory, Verifier, attestationSigner,
            NullLogger<RosterCrdtProjection>.Instance, roster);
        _projections.Add(projection);
        return (projection, roster);
    }

    private string NewDbConn(string label)
    {
        var dir = Path.Combine(Path.GetTempPath(), $"harborline-staleseed-{label}-{Guid.NewGuid():N}");
        Directory.CreateDirectory(dir);
        _tempDirs.Add(dir);
        return $"Data Source={Path.Combine(dir, "roster.db")};Pooling=False";
    }

    /// <summary>Reproduce the EXACT HostedCommsApiEndpoint.ResolveAndAssertActiveMember consistency check against a
    /// live roster + a comms signer (the production fail-closed assertion). Returns true iff the binding is consistent
    /// (the operator's own messages would pass the forge-proof gate); false reproduces the boot crash.</summary>
    private static bool CommsAuthorBindingIsConsistent(NodeTeamRoster roster, NodePrincipalSigner commsSigner)
    {
        var partyId = roster.Current.GenesisPartyId;
        var boundKey = roster.Current.PublicKeyOf(partyId);
        var signerKey = commsSigner.Signer.IssuerId;
        return boundKey is not null && boundKey.Value.Equals(signerKey);
    }

    /// <summary>Seed a node's own genesis admission onto its synced doctype + durable store — exactly what
    /// RosterSyncBootstrapHostedService does at boot (so a later process hydrates it).</summary>
    private static async Task SeedGenesisDurablyAsync(RosterCrdtProjection projection, NodeTeamRoster roster)
    {
        foreach (var rec in roster.Current.EnumerateAdmissions())
            await projection.PublishLocalAsync(RosterRecordCrdtState.FromAdmission(rec), CancellationToken.None);
    }

    // ── THE CRASH REPRO: a stale-seed durable store + a fresh different-seed boot → pre-fix the live roster is
    //    overwritten by the stale genesis (comms binding inconsistent → boot crash); post-fix it is NOT. ───────────

    [Fact(DisplayName = "bug-1333: an app dev-seed CHANGE over a reused store — hydration must NOT adopt the stale-seed genesis; comms author binding stays consistent (no boot crash)")]
    public async Task DevSeedChange_Over_Reused_Store_KeepsLiveGenesis_CommsBindingConsistent()
    {
        var conn = NewDbConn("seedchange");

        // ── PRIOR RUN: the Harborline App spawned the node with seed-A; it seeded seed-A's genesis durably, then exited. ──
        var seedA = SeedIdentity.From(0xA1, _signers);
        var (projA, rosterA) = await NewNodeAsync(GenesisFor(seedA), conn, seedA.Signer.Signer);
        await SeedGenesisDurablyAsync(projA, rosterA);
        await projA.DisposeAsync();
        _projections.Remove(projA);
        // No global ClearAllPools(): the connection string is Pooling=False, so disposing projA already
        // released the file handle — modeling the process exit needs no process-wide pool clear
        // (bug-20260702-8012e553).

        // ── THIS RUN: the Harborline App re-spawns with a DIFFERENT HARBORLINE_DEV_SEED_HEX (seed-B) but the SAME data dir.
        //    The fresh process seeds seed-B's genesis in memory (Program.cs), then cold-start hydration reloads the
        //    DURABLE seed-A genesis. seed-A.PartyId != seed-B.PartyId and binds seed-A's key. ──
        var seedB = SeedIdentity.From(0xB2, _signers);
        Assert.NotEqual(seedA.PartyId, seedB.PartyId); // distinct identities (gap-#2 per-seed-distinct).
        var (projB, rosterB) = await NewNodeAsync(GenesisFor(seedB), conn, seedB.Signer.Signer);

        // Before hydration: the live roster is the seed-B genesis the boot just seeded — binding is consistent.
        Assert.Equal(seedB.PartyId, rosterB.Current.GenesisPartyId);
        Assert.True(CommsAuthorBindingIsConsistent(rosterB, seedB.Signer));

        // COLD-START HYDRATION — the exact RosterSyncBootstrapHostedService boot step that overwrote the live roster.
        await projB.HydrateFromStoreAsync(CancellationToken.None);
        await projB.DrainPendingReconcilesAsync(); // let the hydration-triggered rebuild settle.

        // THE FIX (green-post): the stale seed-A genesis is NOT adopted — the live roster stays seed-B's genesis, so
        // the comms author binding is still consistent and HostedCommsApiEndpoint would NOT crash at boot.
        // PRE-FIX this FAILS: RebuildLiveRoster adopted the seed-A genesis → Current.GenesisPartyId == seed-A,
        // bound to seed-A's key != seed-B comms signer → the consistency check returns false (the boot crash).
        Assert.Equal(seedB.PartyId, rosterB.Current.GenesisPartyId);
        Assert.True(
            CommsAuthorBindingIsConsistent(rosterB, seedB.Signer),
            "the comms author binding must stay bound to the live seed-derived genesis after cold-start hydration "
            + "of a stale-seed durable store (else HostedCommsApiEndpoint fails-closed at boot — bug-1333).");
    }

    // ── THE BITE (red-pre proof, fix-independent): hydrating ONLY a foreign-seed durable genesis rebuilds a roster
    //    whose genesis party != the live one. The guard refuses it; without the guard AdoptSyncedRoster would set it. ─

    [Fact(DisplayName = "bug-1333 BITE: a durable store whose ONLY genesis is from a different seed rebuilds a foreign genesis — the live seed-derived genesis must survive (guard refuses the stale adopt)")]
    public async Task ForeignSeedOnlyStore_RebuildsForeignGenesis_LiveGenesisSurvives()
    {
        var conn = NewDbConn("foreignonly");

        // A durable store seeded by seed-A only (the prior identity's genesis).
        var seedA = SeedIdentity.From(0xC3, _signers);
        var (projSeed, rosterSeed) = await NewNodeAsync(GenesisFor(seedA), conn, seedA.Signer.Signer);
        await SeedGenesisDurablyAsync(projSeed, rosterSeed);
        await projSeed.DisposeAsync();
        _projections.Remove(projSeed);

        // A fresh boot under seed-B over that store.
        var seedB = SeedIdentity.From(0xD4, _signers);
        var (projB, rosterB) = await NewNodeAsync(GenesisFor(seedB), conn, seedB.Signer.Signer);
        await projB.HydrateFromStoreAsync(CancellationToken.None);
        await projB.DrainPendingReconcilesAsync();

        // Prove the rebuild WOULD have produced a foreign (seed-A) genesis if adopted — the snapshot validates to a
        // single seed-A genesis, distinct from the live seed-B party. The guard is what stops AdoptSyncedRoster.
        var rebuilt = MemberRoster.FromSyncedRecords(
            projB.Snapshot().Where(s => s.Kind == RosterRecordKind.Admission)
                .Select(s => s.ToAdmissionOrNull()).Where(x => x is not null).Select(x => x!),
            Array.Empty<MemberRevocationRecord>(), Verifier);
        Assert.Single(rebuilt.Members);                  // the stale genesis rebuilds cleanly (it is self-consistent)...
        Assert.Equal(seedA.PartyId, rebuilt.GenesisPartyId); // ...as a FOREIGN (seed-A) genesis.

        // THE GUARD: the live roster was NOT overwritten — it remains the seed-B (live) genesis.
        Assert.Equal(seedB.PartyId, rosterB.Current.GenesisPartyId);
        Assert.True(CommsAuthorBindingIsConsistent(rosterB, seedB.Signer));
    }

    // ── NO REGRESSION: the standalone / seed-CONSISTENT path. A store seeded by the SAME seed the node boots under
    //    hydrates + adopts normally (the genesis matches), and the binding is consistent. ────────────────────────────

    [Fact(DisplayName = "bug-1333 NO REGRESSION: a seed-CONSISTENT durable store hydrates + adopts normally (the standalone path) — binding stays consistent")]
    public async Task SeedConsistentStore_HydratesAndAdoptsNormally_BindingConsistent()
    {
        var conn = NewDbConn("consistent");

        var seed = SeedIdentity.From(0xE5, _signers);

        // Prior run seeded this seed's genesis durably.
        var (proj1, roster1) = await NewNodeAsync(GenesisFor(seed), conn, seed.Signer.Signer);
        await SeedGenesisDurablyAsync(proj1, roster1);
        await proj1.DisposeAsync();
        _projections.Remove(proj1);

        // Restart under the SAME seed (the standalone / LocalNode__RootSeedHex-stable path).
        var (proj2, roster2) = await NewNodeAsync(GenesisFor(seed), conn, seed.Signer.Signer);
        await proj2.HydrateFromStoreAsync(CancellationToken.None);
        await proj2.DrainPendingReconcilesAsync();

        // The hydrated genesis == the live genesis (same seed) → adoption proceeds, the member is present, the
        // binding stays consistent. StableGenesis makes the hydrated + re-seeded records byte-identical (#1291 F1),
        // so there is exactly ONE genesis and the rebuild adopts it.
        Assert.Equal(seed.PartyId, roster2.Current.GenesisPartyId);
        Assert.True(roster2.Current.Contains(seed.PartyId));
        Assert.True(roster2.Current.ValidatesToGenesis(Verifier));
        Assert.True(CommsAuthorBindingIsConsistent(roster2, seed.Signer));
    }
}

using System.Text;
using System.Text.Json;

using Harborline.Api.Kernel.Schema;

using Xunit;

namespace Harborline.Api.LocalNodeHost.Tests.Entities;

/// <summary>
/// CodeRabbit 4112934954 (T-737 platform-pin move / F-20 follow-up): the JSON-Schema
/// error-flattening in <see cref="InMemorySchemaRegistry"/> drops a JsonSchema.Net
/// 9.4.0 applicator "summary" error (e.g. <c>properties</c>) only when a MORE SPECIFIC
/// keyword failure exists strictly BELOW it in the schema (its evaluation path, not its
/// instance location). Two keywords declared at the SAME schema location that both fail
/// on the same instance value are independent siblings — neither is a summary of the
/// other — and BOTH must survive even though they share a JSON Pointer.
/// </summary>
public sealed class SchemaValidationErrorFlatteningTests
{
    private static InMemorySchemaRegistry NewRegistry() => new(TimeProvider.System);

    /// <summary>
    /// Root-first: <c>not</c> and <c>minLength</c> are both declared directly on the root
    /// schema (same evaluation path), and both fail against the same string instance. A
    /// pointer-only filter would see them sharing the root JSON Pointer and wrongly treat
    /// <c>minLength</c>'s failure as license to drop <c>not</c> as a redundant summary.
    /// </summary>
    [Fact]
    public async Task Independent_keyword_failures_at_the_same_instance_location_are_both_reported()
    {
        var registry = NewRegistry();
        var schema = await registry.RegisterAsync("""
            {
              "$schema": "https://json-schema.org/draft/2020-12/schema",
              "type": "string",
              "not": { "type": "string" },
              "minLength": 5
            }
            """);

        var result = await registry.ValidateAsync(schema.Id, Encoding.UTF8.GetBytes("\"abc\""));

        Assert.False(result.IsValid);
        var codes = result.Errors.Select(e => e.Code).OrderBy(c => c, StringComparer.Ordinal).ToArray();
        Assert.Equal(new[] { "minLength", "not" }, codes);
    }

    /// <summary>
    /// CodeRabbit 4113220972 (follow-up on 4112934954): a root-level <c>not</c> failure and an
    /// UNRELATED, deeper <c>minLength</c> failure nested under <c>properties</c> both fail on the
    /// same candidate. A fix that compares an applicator's evaluation path (not its own subtree
    /// root) sees "/properties/name" as a descendant of the root "" path and wrongly treats that
    /// as proof <c>not</c> is a redundant summary of it — they are unrelated siblings and BOTH
    /// must survive.
    /// </summary>
    [Fact]
    public async Task An_unrelated_nested_failure_does_not_silence_a_root_level_applicator_failure()
    {
        var registry = NewRegistry();
        var schema = await registry.RegisterAsync("""
            {
              "$schema": "https://json-schema.org/draft/2020-12/schema",
              "type": "object",
              "not": { "type": "object" },
              "properties": { "name": { "type": "string", "minLength": 5 } }
            }
            """);

        var candidate = JsonSerializer.SerializeToUtf8Bytes(new { name = "ab" });
        var result = await registry.ValidateAsync(schema.Id, candidate);

        Assert.False(result.IsValid);
        var codes = result.Errors.Select(e => e.Code).OrderBy(c => c, StringComparer.Ordinal).ToArray();
        Assert.Equal(new[] { "minLength", "not" }, codes);
    }

    /// <summary>
    /// F-20's actual regression shape: a real applicator-summary error (<c>properties</c>,
    /// reported by JsonSchema.Net 9.4.0 on the object node) alongside its genuinely more
    /// specific child failure (<c>minLength</c> on one property). Only the summary drops.
    /// </summary>
    [Fact]
    public async Task An_applicator_summary_is_dropped_in_favor_of_its_more_specific_child_failure()
    {
        var registry = NewRegistry();
        var schema = await registry.RegisterAsync("""
            {
              "$schema": "https://json-schema.org/draft/2020-12/schema",
              "type": "object",
              "properties": { "name": { "type": "string", "minLength": 5 } },
              "additionalProperties": false
            }
            """);

        var candidate = JsonSerializer.SerializeToUtf8Bytes(new { name = "ab" });
        var result = await registry.ValidateAsync(schema.Id, candidate);

        Assert.False(result.IsValid);
        var codes = result.Errors.Select(e => e.Code).ToArray();
        Assert.Equal(new[] { "minLength" }, codes);
    }
}

using Harborline.Api.Foundation.IdentityAtlas;
using Harborline.Api.Foundation.IdentityAtlas.Permissions;

namespace Harborline.Api.LocalNodeHost.Tests.Entities;

/// <summary>
/// Stands in for the local grant store on the replicated path: no permission set rides the wire (293 s3b2), so
/// the rebuild's admitter, revoker and no-escalation gates read a party's authority from here. A party with no
/// row holds nothing, which is what an ungranted party holds in production.
/// </summary>
internal sealed class TestRosterAuthority(params (string Party, PermissionSet Set)[] rows) : IRosterAuthority
{
    /// <summary>Every (party, instant) this authority was asked for, in call order.</summary>
    internal List<(string Party, DateTimeOffset At)> Reads { get; } = [];

    public PermissionSet PermissionsFor(string teamId, string partyId, DateTimeOffset at)
    {
        Reads.Add((partyId, at));
        foreach (var row in rows) if (string.Equals(row.Party, partyId, StringComparison.Ordinal)) return row.Set;
        return PermissionSet.Empty;
    }
}

using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging.Abstractions;
using Microsoft.Extensions.Options;

using Harborline.Api.Foundation.Crypto;
using Harborline.Api.Foundation.IdentityAtlas;
using Harborline.Api.Foundation.IdentityAtlas.Permissions;
using Harborline.Api.Kernel.Crdt;
using Harborline.Api.Kernel.Crdt.Backends;
using Harborline.Api.Kernel.Security.Crypto;
using Harborline.Api.Kernel.Security.Keys;
using Harborline.Api.Kernel.Sync.Gossip;
using Harborline.Api.Kernel.Sync.Handshake;
using Harborline.Api.Kernel.Sync.Identity;
using Harborline.Api.Kernel.Sync.Protocol;
using Harborline.Api.LocalNodeHost.Data.Roster;
using Harborline.Api.LocalNodeHost.Enrollment;

using Ed25519Signer = Harborline.Api.Kernel.Security.Crypto.Ed25519Signer;

namespace Harborline.Api.LocalNodeHost.Tests.Entities;

/// <summary>
/// THE ≥3-NODE MESH PROOF (INFO-2 / the transport-key-in-synced-record follow-on). The flagged gap: the synced
/// roster record carried the member's PRINCIPAL key (forge-proof attribution converges mesh-wide) but NOT its
/// team-scoped TRANSPORT key (the sync-HELLO key <see cref="MemberSetTrustPolicy"/> checks). The transport map was
/// wired ONLY locally — by the admitter (<see cref="NodeTeamRoster.AdmitPeer"/>) and the joiner's one-time
/// <see cref="NodeTeamRoster.AdoptEnrollment"/>; <see cref="NodeTeamRoster.AdoptSyncedRoster"/> could only PRUNE,
/// never ADD. So in a star-admitted team A→{B,C} where B and C are admitted at different times, B never learned
/// C's transport key (and vice-versa) → B↔C could not pass the trust gate → only the A-hub worked
/// (PEER_UNTRUSTED on B↔C).
/// <para>
/// THE FIX: the team-scoped transport PUBLIC key now RIDES the synced admission record
/// (<c>RosterRecordCrdtState.TransportPublicKeyB64Url</c>); <see cref="RosterCrdtProjection.RebuildLiveRoster"/>
/// harvests it for every genesis-validated live member and <see cref="NodeTeamRoster.AdoptSyncedRoster"/> REBUILDS
/// the transport map from the converged roster — so every converged member derives the SAME full transport-trust
/// set from the SAME roster, regardless of admit order. The transport set is ROSTER-DERIVED.
/// </para>
/// </summary>
/// <remarks>
/// <para>
/// <b>Real persisted store + real wire (the recurring "test the REAL host/wire/store" lesson).</b> Three
/// independent <see cref="RosterCrdtProjection"/> replicas, each over its OWN <see cref="YDotNetCrdtEngine"/> +
/// its OWN SQLite-persisted <c>roster.db</c> + its OWN <see cref="NodeTeamRoster"/>. The roster CRDT converges
/// over REAL TCP sockets via <see cref="GossipDaemon"/>s + <see cref="TcpSyncDaemonTransport"/> — the same
/// produce/consume path the production daemon runs, with NO signal-bridge relay (local-first). The trust
/// decisions under test are the real <see cref="MemberSetTrustPolicy"/> over the REAL team-scoped transport
/// subkeys (HKDF(member-root, A.teamId)), computed from the CONVERGED roster — never hand-seeded.
/// </para>
/// <para>
/// <b>NOT hand-provisioned (the lesson of the whole enrollment arc).</b> B and C learn each other's transport key
/// ONLY because the synced roster record carries it and the rebuild harvests it. The
/// <see cref="Mesh_BC_Trust_Converges_Via_Synced_Roster_Not_Hub"/> headline runs the SAME body with the fix
/// neutered (records published WITHOUT the carried key) and asserts B↔C does NOT converge — proving the test
/// exercises the new carried-key path, not a pre-existing one.
/// </para>
/// </remarks>
public sealed class ThreeNodeMeshTransportKeyTests : IAsyncLifetime
{
    private readonly List<IAsyncDisposable> _cleanup = new();
    private readonly List<string> _tempDirs = new();

    public Task InitializeAsync() => Task.CompletedTask;

    public async Task DisposeAsync()
    {
        foreach (var d in _cleanup)
        {
            try { await d.DisposeAsync(); } catch { /* best-effort */ }
        }
        foreach (var dir in _tempDirs)
        {
            try { if (Directory.Exists(dir)) Directory.Delete(dir, recursive: true); }
            catch { /* best-effort temp cleanup */ }
        }
    }

    private static readonly Guid Team = Guid.Parse("7e57aaaa-0000-0000-0000-00000000000a");
    private static readonly string TeamIdString = Team.ToString("D");
    private static readonly IOperationVerifier Verifier = new Ed25519Verifier();
    private static readonly IEd25519Signer TransportSigner = new Ed25519Signer();
    private static readonly ITeamSubkeyDerivation SubkeyDerivation = new TeamSubkeyDerivation(TransportSigner);

    // ───────────────────────────────────────────────────────────────────────────────────────────────────────
    // A team member: a comms/principal identity (the roster binding) + a distinct node ROOT (the source of its
    // team-scoped transport subkey — material no other node holds), like two distinct installs.
    // ───────────────────────────────────────────────────────────────────────────────────────────────────────
    private sealed record Member(string PartyId, KeyPair PrincipalKey, IOperationSigner PrincipalSigner, NodeIdentity Root)
    {
        public static Member New(string partyId)
        {
            var kp = KeyPair.Generate();
            var rootSeed = new byte[32];
            System.Security.Cryptography.RandomNumberGenerator.Fill(rootSeed);
            var (rootPub, rootPriv) = TransportSigner.GenerateFromSeed(rootSeed);
            var nodeId = Convert.ToHexString(rootPub.AsSpan(0, 16)).ToLowerInvariant();
            var root = new NodeIdentity(nodeId, rootPub, rootPriv);
            return new Member(partyId, kp, new Harborline.Api.Foundation.Crypto.Ed25519Signer(kp), root);
        }

        /// <summary>The member's team-scoped TRANSPORT identity for A's team (HKDF(root-private, A.teamId)) — what
        /// it presents in the sync HELLO and what the trust gate must trust.</summary>
        public NodeIdentity TransportIdentity =>
            TeamScopedNodeIdentity.Derive(Root, TeamIdString, SubkeyDerivation);

        /// <summary>The raw 32-byte transport PUBLIC key the joiner supplies over the admission channel — the
        /// datum that now rides the synced roster record.</summary>
        public byte[] TransportPublicKey => TransportIdentity.PublicKey;
    }

    // ── A roster-sync replica: own CRDT engine, own persisted store, own live roster + projection ──────────
    private sealed class Replica : IAsyncDisposable
    {
        public required string Name { get; init; }
        public required string Dir { get; init; }
        public required ServiceProvider Sp { get; init; }
        public required IDbContextFactory<NodeLocalRosterDbContext> Factory { get; init; }
        public required RosterCrdtProjection Projection { get; init; }
        public required NodeTeamRoster NodeRoster { get; init; }

        public async ValueTask DisposeAsync()
        {
            await Projection.DisposeAsync();
            await Sp.DisposeAsync();
            try { if (Directory.Exists(Dir)) Directory.Delete(Dir, recursive: true); } catch { /* best-effort */ }
        }
    }

    private async Task<Replica> NewReplicaAsync(string name, MemberRoster seedRoster, IOperationSigner attestationSigner)
    {
        var dir = Path.Combine(Path.GetTempPath(), $"harborline-3node-{name}-{Guid.NewGuid():N}");
        Directory.CreateDirectory(dir);
        _tempDirs.Add(dir);
        var connectionString = $"Data Source={Path.Combine(dir, "roster.db")};Pooling=False";

        var services = new ServiceCollection();
        services.AddLogging();
        services.AddDbContextFactory<NodeLocalRosterDbContext>(opt => opt.UseSqlite(connectionString));
        services.AddSingleton<ICrdtEngine, YDotNetCrdtEngine>();

        var sp = services.BuildServiceProvider();
        var factory = sp.GetRequiredService<IDbContextFactory<NodeLocalRosterDbContext>>();
        // EnsureCreated builds the schema from the CURRENT model — including the new transport_public_key column
        // (the AdditiveMigration test below covers the column-add against an OLD-schema db explicitly).
        await using (var ctx = await factory.CreateDbContextAsync())
            await ctx.Database.EnsureCreatedAsync();

        var nodeRoster = new NodeTeamRoster(seedRoster);
        var projection = new RosterCrdtProjection(TimeProvider.System,
            sp.GetRequiredService<ICrdtEngine>(), factory, Verifier, attestationSigner,
            NullLogger<RosterCrdtProjection>.Instance, nodeRoster);

        var replica = new Replica
        {
            Name = name, Dir = dir, Sp = sp, Factory = factory, Projection = projection, NodeRoster = nodeRoster,
        };
        _replicas_addCleanup(replica);
        return replica;
    }

    private readonly List<Replica> _replicas = new();
    private void _replicas_addCleanup(Replica r) { _replicas.Add(r); _cleanup.Add(r); }

    private static MemberRoster GenesisFor(Member founder) =>
        MemberRoster.StableGenesis(Team, founder.PartyId, founder.PrincipalSigner, Verifier);

    /// <summary>Seed the founder's genesis self-admission onto the synced doctype, CARRYING the founder's own
    /// team-scoped transport key (what RosterSyncBootstrapHostedService does in production).</summary>
    private static async Task SeedGenesisAsync(Replica r, Member founder) =>
        await r.Projection.PublishLocalAsync(
            RosterRecordCrdtState.FromAdmission(
                r.NodeRoster.Current.EnumerateAdmissions().Single(), founder.TransportPublicKey),
            CancellationToken.None);

    /// <summary>
    /// Admit <paramref name="joiner"/> on the founder replica (the A-side admit), update A's live roster + record
    /// the joiner's transport key locally (AdmitPeer), and publish the admission record CARRYING the joiner's
    /// transport key — exactly what <see cref="WireEnrollmentAdmitter"/> does. <paramref name="carryTransportKey"/>
    /// false = the pre-fix counterfactual (publish WITHOUT the carried key).
    /// </summary>
    private static async Task AdmitAndPublishAsync(
        Replica a, Member founder, Member joiner, bool carryTransportKey = true)
    {
        var withJoiner = a.NodeRoster.Current.Admit(
            founder.PartyId, founder.PrincipalSigner, joiner.PartyId, joiner.PrincipalKey.PrincipalId,
            PermissionCompositions.Member, Verifier, DateTimeOffset.UtcNow, Guid.NewGuid());
        a.NodeRoster.AdmitPeer(withJoiner, joiner.PartyId, joiner.TransportPublicKey);
        var rec = withJoiner.EnumerateAdmissions().Single(x => x.PartyId == joiner.PartyId);
        await a.Projection.PublishLocalAsync(
            RosterRecordCrdtState.FromAdmission(rec, carryTransportKey ? joiner.TransportPublicKey : null),
            CancellationToken.None);
    }

    /// <summary>One direction of a roster sync round over the projections (encode src delta vs dst clock → apply →
    /// drain the reconcile the Changed handler spawns). Mirrors the gossip daemon's produce/consume.</summary>
    private static async Task SyncDirectAsync(Replica src, Replica dst)
    {
        var delta = await src.Projection.EncodeOutboundDeltaAsync(
            RosterCrdtProjection.DocumentId, dst.Projection.VectorClock, CancellationToken.None);
        Assert.NotNull(delta);
        await dst.Projection.ApplyInboundDeltaAsync(
            RosterCrdtProjection.DocumentId, 1, delta!.Value, CancellationToken.None);
        await dst.Projection.DrainPendingReconcilesAsync();
    }

    /// <summary>Converge the roster fully across all three replicas (every pair, both directions, until stable) —
    /// CRDT convergence is order-independent, so a few rounds reach the fixpoint.</summary>
    private static async Task ConvergeAllAsync(params Replica[] replicas)
    {
        for (var round = 0; round < 3; round++)
        {
            foreach (var src in replicas)
                foreach (var dst in replicas)
                    if (!ReferenceEquals(src, dst))
                        await SyncDirectAsync(src, dst);
        }
        // The PRODUCTION periodic anti-entropy round re-reconciles each node's converged list (push-on-change is
        // the primary path; the periodic round is the backstop). Model that backstop here so a converged backfill
        // replace (delete+insert of an already-present record) whose Changed-trigger was coalesced during a busy
        // round is still reconciled — deterministic test convergence matching production's eventual consistency.
        foreach (var r in replicas)
        {
            await r.Projection.ReconcileAsync(CancellationToken.None);
            await r.Projection.DrainPendingReconcilesAsync();
        }
    }

    /// <summary>The trust gate the per-team registrar builds: {own subkey floor} ∪ {the live roster's
    /// transport keys}. Reads the snapshot on each call (convergence applies live).</summary>
    private static MemberSetTrustPolicy TrustPolicyFor(NodeTeamRoster roster, byte[] ownFloorKey) =>
        new(() =>
        {
            var keys = new List<byte[]> { ownFloorKey };
            keys.AddRange(roster.TrustedTransportKeys());
            return keys;
        });

    private static HelloMessage HelloFor(NodeIdentity transportIdentity) => new(
        NodeId: transportIdentity.NodeIdBytes,
        SchemaVersion: "1",
        SupportedVersions: new[] { "1" },
        PublicKey: transportIdentity.PublicKey,
        Timestamp: 0UL,
        Signature: Array.Empty<byte>());

    // ═══════════════════════════════════════════════════════════════════════════════════════════════════════
    // THE HEADLINE: a 3-node mesh — B↔C trust converges via the SYNCED roster, not via the A-hub.
    // ═══════════════════════════════════════════════════════════════════════════════════════════════════════

    [Theory(DisplayName = "≥3-node mesh: A admits B then C; after the roster CRDT converges, B and C MUTUALLY trust each other's transport key (B↔C) derived from the converged roster — NOT via the A-hub (fix carries the key; pre-fix does not)")]
    [InlineData(true)]   // FIX: the synced record carries the transport key → B↔C converge.
    [InlineData(false)]  // PRE-FIX counterfactual: no carried key → B↔C do NOT converge (only the A-hub works).
    public async Task Mesh_BC_Trust_Converges_Via_Synced_Roster_Not_Hub(bool carryTransportKey)
    {
        var founder = Member.New("os:A#founder");
        var bob = Member.New("os:B#bob");
        var carol = Member.New("os:C#carol");

        // Three INDEPENDENT, persisted replicas. A founds; B and C adopt A's team genesis as their trust root (the
        // joiner posture — they do NOT publish a competing genesis, so the team has exactly one genesis).
        var a = await NewReplicaAsync("A", GenesisFor(founder), founder.PrincipalSigner);
        await SeedGenesisAsync(a, founder);
        var aGenesisRoster = a.NodeRoster.Current;
        var b = await NewReplicaAsync("B", aGenesisRoster, founder.PrincipalSigner);
        var c = await NewReplicaAsync("C", aGenesisRoster, founder.PrincipalSigner);

        // A admits B, THEN (later) A admits C — the star-admission shape. Each admission publishes A's record
        // carrying (or, pre-fix, omitting) the admitted peer's transport key.
        await AdmitAndPublishAsync(a, founder, bob, carryTransportKey);
        await AdmitAndPublishAsync(a, founder, carol, carryTransportKey);

        // The roster CRDT converges across all three (over the projections' produce/consume — the daemon path).
        await ConvergeAllAsync(a, b, c);

        // ── Membership + attribution converge mesh-wide in BOTH cases (principal keys always rode the record). ──
        Assert.True(b.NodeRoster.Current.Contains(carol.PartyId), "B's converged roster must contain C (membership).");
        Assert.True(c.NodeRoster.Current.Contains(bob.PartyId), "C's converged roster must contain B (membership).");
        Assert.True(b.NodeRoster.Current.ValidatesToGenesis(Verifier));
        Assert.True(c.NodeRoster.Current.ValidatesToGenesis(Verifier));

        // ── THE TRUST DECISION: does B trust C's wire HELLO (and vice-versa), computed from the CONVERGED roster? ──
        // The own-subkey floor is each node's OWN A-team transport key (what the registrar contributes).
        var policyB = TrustPolicyFor(b.NodeRoster, bob.TransportPublicKey);
        var policyC = TrustPolicyFor(c.NodeRoster, carol.TransportPublicKey);

        var bTrustsC = policyB.IsTrusted(HelloFor(carol.TransportIdentity));
        var cTrustsB = policyC.IsTrusted(HelloFor(bob.TransportIdentity));

        if (carryTransportKey)
        {
            // THE FIX: B↔C MUTUALLY trust each other DIRECTLY — the ≥3-node mesh works without the A-hub.
            Assert.True(bTrustsC,
                "FIX: B must trust C's transport key, HARVESTED from the converged roster record C's admission "
                + "carried — the ≥3-node mesh property. Pre-fix this was PEER_UNTRUSTED (only the A-hub worked).");
            Assert.True(cTrustsB,
                "FIX: C must trust B's transport key (B was admitted BEFORE C, yet C harvests B's key from the "
                + "converged roster — no admit-order dependency).");
            // #1296-F2 reinforcement: the trusted key is the JOINED-team-scoped subkey (HKDF(member-root, A.teamId)).
            Assert.Contains(b.NodeRoster.TrustedTransportKeys(),
                k => k.AsSpan().SequenceEqual(carol.TransportPublicKey));
            Assert.Contains(c.NodeRoster.TrustedTransportKeys(),
                k => k.AsSpan().SequenceEqual(bob.TransportPublicKey));
        }
        else
        {
            // PRE-FIX counterfactual: the record carried NO transport key → the rebuild harvested nothing → B↔C
            // CANNOT trust each other. This is the exact INFO-2 failure (only the A-hub works). Proves the
            // headline above exercises the new carried-key path, not a pre-existing one.
            Assert.False(bTrustsC,
                "PRE-FIX: without the carried transport key, B has no way to learn C's transport key from the "
                + "synced roster → B↔C is PEER_UNTRUSTED (the INFO-2 gap — only the A-hub worked).");
            Assert.False(cTrustsB, "PRE-FIX: symmetric — C cannot trust B either.");
        }

        // ── In BOTH cases the never-brick floor holds: every node trusts itself + the A-hub stays trusted. ──
        Assert.True(policyB.IsTrusted(HelloFor(bob.TransportIdentity)), "B trusts itself (own-subkey floor).");
        Assert.True(policyB.IsTrusted(HelloFor(founder.TransportIdentity)), "B trusts the A-hub (admitter).");
        Assert.True(policyC.IsTrusted(HelloFor(carol.TransportIdentity)), "C trusts itself (own-subkey floor).");
        Assert.True(policyC.IsTrusted(HelloFor(founder.TransportIdentity)), "C trusts the A-hub (admitter).");
    }

    // ═══════════════════════════════════════════════════════════════════════════════════════════════════════
    // THE HEADLINE OVER A REAL WIRE: a real B↔C sync session completes (comms cross B↔C directly, signal-bridge
    // STOPPED), proving the roster-derived trust is honored by the actual handshake, not just the policy snapshot.
    // ═══════════════════════════════════════════════════════════════════════════════════════════════════════

    [Fact(DisplayName = "≥3-node mesh OVER A REAL WIRE: after roster converges, a B↔C roster sync session completes directly over a TCP socket (NOT via A) — the roster-derived transport trust is honored by the real handshake; no signal-bridge")]
    public async Task Mesh_BC_Sync_Session_Completes_Over_Real_Wire_Direct_Not_Via_Hub()
    {
        var founder = Member.New("os:A#founder");
        var bob = Member.New("os:B#bob");
        var carol = Member.New("os:C#carol");

        var a = await NewReplicaAsync("A", GenesisFor(founder), founder.PrincipalSigner);
        await SeedGenesisAsync(a, founder);
        var b = await NewReplicaAsync("B", a.NodeRoster.Current, founder.PrincipalSigner);
        var c = await NewReplicaAsync("C", a.NodeRoster.Current, founder.PrincipalSigner);

        await AdmitAndPublishAsync(a, founder, bob);
        await AdmitAndPublishAsync(a, founder, carol);
        await ConvergeAllAsync(a, b, c);

        // Each node presents its A-team-scoped transport identity on the wire HELLO (the #1296-F2 joined-team scope).
        var bDevice = TeamScopedNodeIdentity.Derive(bob.Root, TeamIdString, SubkeyDerivation);
        var cDevice = TeamScopedNodeIdentity.Derive(carol.Root, TeamIdString, SubkeyDerivation);
        Assert.NotEqual(bDevice.PublicKey, cDevice.PublicKey);

        // C LISTENS; B DIALS C — a DIRECT B↔C session (A is NOT in this path; no signal-bridge relay). The trust
        // gate on each side is the REAL MemberSetTrustPolicy over the converged roster's transport keys.
        var cSigner = new Ed25519Signer();
        var transportCListen = new TcpSyncDaemonTransport("tcp://127.0.0.1:0");
        _cleanup.Add(transportCListen);
        var endpointC = transportCListen.ListenEndpoint!;
        var daemonC = BuildDaemon(transportCListen, cDevice, cSigner, c.Projection,
            TrustPolicyFor(c.NodeRoster, carol.TransportPublicKey));
        _cleanup.Add(daemonC);
        await daemonC.StartListeningAsync(CancellationToken.None);

        var bSigner = new Ed25519Signer();
        var transportBOut = new TcpSyncDaemonTransport();
        _cleanup.Add(transportBOut);
        var daemonB = BuildDaemon(transportBOut, bDevice, bSigner, b.Projection,
            TrustPolicyFor(b.NodeRoster, bob.TransportPublicKey));
        _cleanup.Add(daemonB);
        daemonB.AddPeer(endpointC, cDevice.PublicKey);
        await daemonB.StartAsync(CancellationToken.None);

        // PROOF the B↔C session is TRUSTED + converges: B has a record C does not (yet). The simplest such record
        // is one bob re-publishes — but the roster is already converged. Instead, prove convergence-by-trust: have
        // B admit nobody, but assert the session reaches a converged clock with NO PEER_UNTRUSTED. We do that by
        // making C learn a record only B will push: B publishes a (idempotent) re-seed of carol's record CARRYING
        // its transport key while C's copy is identical, so the session must HANDSHAKE (trust) even if no delta
        // flows. The decisive signal is that the handshake does NOT reject — verified by driving a real new record.
        //
        // Concretely: A admits a fourth member D, publishes to A, syncs A→B ONLY (NOT to C). Now B holds D's
        // admission that C lacks. The DIRECT B↔C session must carry D to C — which only happens if B↔C is TRUSTED.
        var dave = Member.New("os:D#dave");
        await AdmitAndPublishAsync(a, founder, dave);
        await SyncDirectAsync(a, b);                       // B learns D; C does NOT (A→B only).
        Assert.True(b.NodeRoster.Current.Contains(dave.PartyId), "B must hold D's admission (A→B sync).");
        Assert.False(c.NodeRoster.Current.Contains(dave.PartyId), "C must NOT yet hold D (no A→C sync).");

        // Over the LIVE B→C wire session, D's admission must reach C — i.e. the B↔C handshake is TRUSTED + the
        // roster doctype crosses directly. If B↔C were PEER_UNTRUSTED (the pre-fix world) D would never arrive.
        await WaitForRosterMemberAsync(c, dave.PartyId,
            because: "after roster-derived trust converged, the DIRECT B→C session (NOT via A, no signal-bridge) "
                + "must complete its trusted handshake and carry D's admission to C.");

        await daemonB.StopAsync(CancellationToken.None);
        await daemonC.StopListeningAsync(CancellationToken.None);
    }

    // ═══════════════════════════════════════════════════════════════════════════════════════════════════════
    // REFUTE 1: a FORGED transport key for a NON-member is NOT trusted (the by-association trust gate bites).
    // ═══════════════════════════════════════════════════════════════════════════════════════════════════════

    [Fact(DisplayName = "≥3-node refute: a FORGED transport key carried for a NON-member is NOT trusted — the rebuild harvests transport keys ONLY for genesis-validated live members (UNSIGNED-by-association)")]
    public async Task Forged_Transport_Key_For_NonMember_Is_Not_Trusted()
    {
        var founder = Member.New("os:A#founder");
        var bob = Member.New("os:B#bob");
        var mallory = Member.New("os:M#mallory");   // NEVER admitted by A — a stranger.

        var a = await NewReplicaAsync("A", GenesisFor(founder), founder.PrincipalSigner);
        await SeedGenesisAsync(a, founder);
        var b = await NewReplicaAsync("B", a.NodeRoster.Current, founder.PrincipalSigner);

        await AdmitAndPublishAsync(a, founder, bob);
        await ConvergeAllAsync(a, b);

        // An attacker injects a roster record for mallory carrying mallory's REAL transport key but a FORGED
        // admission (signed by mallory's own non-admin principal key, not by A). Build it by hand the way a
        // bogus delta would: a self-signed "admission" mallory tries to pass off.
        var forgedSelfAdmit = MemberRoster.Genesis(
            Team, mallory.PartyId, mallory.PrincipalSigner, Verifier, DateTimeOffset.UtcNow, Guid.NewGuid());
        var forgedRec = forgedSelfAdmit.EnumerateAdmissions().Single();
        // Stamp mallory's real transport key onto the forged record + publish it onto B's doctype (the inject).
        var forgedWire = RosterRecordCrdtState.FromAdmission(forgedRec, mallory.TransportPublicKey);
        await b.Projection.PublishLocalAsync(forgedWire, CancellationToken.None);
        await b.Projection.DrainPendingReconcilesAsync();

        // The injection guard (FromSyncedRecords: ≥2 genesis → reject; mallory's self-admit is a SECOND genesis)
        // drops the whole rebuild → B keeps its prior valid roster → mallory is NOT a member → her transport key
        // is NOT harvested → the trust gate REJECTS her HELLO. The forged transport key bought nothing.
        var policyB = TrustPolicyFor(b.NodeRoster, bob.TransportPublicKey);
        Assert.False(b.NodeRoster.Current.Contains(mallory.PartyId),
            "the forged self-admission is a second genesis — rejected; mallory never becomes a member.");
        Assert.False(policyB.IsTrusted(HelloFor(mallory.TransportIdentity)),
            "a forged transport key for a NON-member is NEVER trusted — the trust anchor (the signed chain) is "
            + "unchanged; the carried key is honored ONLY for a chain-validated member (by-association).");
        Assert.DoesNotContain(b.NodeRoster.TrustedTransportKeys(),
            k => k.AsSpan().SequenceEqual(mallory.TransportPublicKey));
        // B's legitimate trust is intact (bob still trusted; the inject did not brick B).
        Assert.True(policyB.IsTrusted(HelloFor(bob.TransportIdentity)));
        Assert.True(policyB.IsTrusted(HelloFor(founder.TransportIdentity)));
    }

    // ═══════════════════════════════════════════════════════════════════════════════════════════════════════
    // REFUTE 2: a REVOKED member's transport key IS DROPPED post-converge (gap-#3 preserved — rebuild-from-live
    // subsumes the prune). Confirms the new rebuild does not REGRESS the revocation-drop the prior increment fixed.
    // ═══════════════════════════════════════════════════════════════════════════════════════════════════════

    [Fact(DisplayName = "≥3-node refute: a REVOKED member's transport key is DROPPED post-converge — rebuild-from-live subsumes the gap-#3 prune (no regression)")]
    public async Task Revoked_Member_Transport_Key_Is_Dropped_Post_Converge()
    {
        var founder = Member.New("os:A#founder");
        var bob = Member.New("os:B#bob");
        var carol = Member.New("os:C#carol");

        var a = await NewReplicaAsync("A", GenesisFor(founder), founder.PrincipalSigner);
        await SeedGenesisAsync(a, founder);
        var c = await NewReplicaAsync("C", a.NodeRoster.Current, founder.PrincipalSigner);

        // A admits B and C, both carry transport keys; converge → C trusts B (the mesh fix).
        await AdmitAndPublishAsync(a, founder, bob);
        await AdmitAndPublishAsync(a, founder, carol);
        await ConvergeAllAsync(a, c);

        var policyC = TrustPolicyFor(c.NodeRoster, carol.TransportPublicKey);
        Assert.True(policyC.IsTrusted(HelloFor(bob.TransportIdentity)),
            "pre-revocation: C trusts B's transport key (harvested from the converged roster).");

        // A REVOKES B and publishes the signed revocation; it syncs + converges to C.
        var (afterRevoke, signedRevocation) = a.NodeRoster.Current.SignRevoke(
            founder.PartyId, founder.PrincipalSigner, bob.PartyId, Verifier, DateTimeOffset.UtcNow, Guid.NewGuid());
        a.NodeRoster.AdoptSyncedRoster(afterRevoke);
        await a.Projection.PublishLocalAsync(
            RosterRecordCrdtState.FromRevocation(signedRevocation), CancellationToken.None);
        await ConvergeAllAsync(a, c);

        // POST-convergence: B is dropped from C's principal roster (attribution gone) AND — because the rebuild is
        // keyed on the CONVERGED LIVE-MEMBER set — B's transport key is NOT rebuilt (B is no longer a live member).
        // So the gap-#3 revocation-drop is PRESERVED by the new rebuild (rebuild-from-live subsumes the prune).
        Assert.False(c.NodeRoster.Current.Contains(bob.PartyId), "B's attribution binding is dropped on C.");
        Assert.Null(c.NodeRoster.ForgeProofBinding(bob.PartyId));
        Assert.False(policyC.IsTrusted(HelloFor(bob.TransportIdentity)),
            "THE gap-#3 PROPERTY (preserved): a revoked member's transport key is dropped → C REJECTS B's HELLO "
            + "post-converge. The roster-derived rebuild reconstructs only live members, so a revoked member's key "
            + "is never rebuilt.");
        Assert.DoesNotContain(c.NodeRoster.TrustedTransportKeys(),
            k => k.AsSpan().SequenceEqual(bob.TransportPublicKey));
        // C is not bricked: it still trusts itself + the founder.
        Assert.True(policyC.IsTrusted(HelloFor(carol.TransportIdentity)));
        Assert.True(policyC.IsTrusted(HelloFor(founder.TransportIdentity)));
    }

    // ═══════════════════════════════════════════════════════════════════════════════════════════════════════
    // ADDITIVE MIGRATION: an OLD-schema record (no transport field) still works — back-compat 2-node hub.
    // ═══════════════════════════════════════════════════════════════════════════════════════════════════════

    [Fact(DisplayName = "additive migration: an OLD admission record carrying NO transport key still converges + works (the 2-node hub via the legacy AdmitPeer/floor path); a mixed old/new record set rebuilds correctly")]
    public async Task Additive_Migration_Old_Record_Without_Transport_Key_Still_Works()
    {
        var founder = Member.New("os:A#founder");
        var bob = Member.New("os:B#bob");
        var carol = Member.New("os:C#carol");

        var a = await NewReplicaAsync("A", GenesisFor(founder), founder.PrincipalSigner);
        // The genesis carries the founder's own transport key (the production seed path — the upgraded founder).
        await SeedGenesisAsync(a, founder);
        var b = await NewReplicaAsync("B", a.NodeRoster.Current, founder.PrincipalSigner);
        var c = await NewReplicaAsync("C", a.NodeRoster.Current, founder.PrincipalSigner);

        // MIXED record set: B admitted with an OLD record (no carried key), C admitted with a NEW record (carries).
        // This is the realistic rollout shape — an upgraded founder (genesis carries) with a member admitted by a
        // pre-upgrade build (B's record carries nothing) alongside a post-upgrade admission (C's record carries).
        await AdmitAndPublishAsync(a, founder, bob, carryTransportKey: false);   // OLD-style record.
        await AdmitAndPublishAsync(a, founder, carol, carryTransportKey: true);  // NEW-style record.
        await ConvergeAllAsync(a, b, c);

        // Both converge as MEMBERS in all rosters (membership/attribution always rode the principal key — old or new).
        Assert.True(b.NodeRoster.Current.Contains(carol.PartyId));
        Assert.True(c.NodeRoster.Current.Contains(bob.PartyId));
        Assert.True(b.NodeRoster.Current.ValidatesToGenesis(Verifier));
        Assert.True(c.NodeRoster.Current.ValidatesToGenesis(Verifier));

        // The mesh works for the member whose record CARRIED a key (C): B trusts C (harvested from C's new record).
        var policyB = TrustPolicyFor(b.NodeRoster, bob.TransportPublicKey);
        Assert.True(policyB.IsTrusted(HelloFor(carol.TransportIdentity)),
            "the NEW record's carried key still works in a mixed set (additive — new records carry, old ignore).");
        // The OLD record (B's) carried no key → C cannot harvest B's transport key from the roster. This is the
        // documented rollout window: an OLD record contributes nothing to the transport map until it re-emits. It
        // does NOT brick anything — the 2-node hub (A↔B) still works via the live AdmitPeer/floor path, and a
        // re-emit (the founder backfill) carries B's key. Assert the back-compat invariant: no exception, valid
        // roster, C trusts itself + the A-hub (never bricked by the old record).
        var policyC = TrustPolicyFor(c.NodeRoster, carol.TransportPublicKey);
        Assert.True(policyC.IsTrusted(HelloFor(carol.TransportIdentity)), "C trusts itself (floor) — not bricked.");
        Assert.True(policyC.IsTrusted(HelloFor(founder.TransportIdentity)), "C trusts the A-hub — not bricked.");

        // BACKFILL proof: the founder re-emits B's record CARRYING the transport key (replace-in-place); it
        // converges → C now harvests B's key → the mesh completes for B too (the rollout window closes).
        var bRec = a.NodeRoster.Current.EnumerateAdmissions().Single(x => x.PartyId == bob.PartyId);
        await a.Projection.PublishLocalAsync(
            RosterRecordCrdtState.FromAdmission(bRec, bob.TransportPublicKey), CancellationToken.None);
        await ConvergeAllAsync(a, b, c);
        Assert.True(policyC.IsTrusted(HelloFor(bob.TransportIdentity)),
            "after the founder backfills B's record with the transport key (replace-in-place), it converges and C "
            + "harvests B's key → the rollout window closes and the full mesh works.");
    }

    // ── daemon helper (mirrors the socket-E2E template) ──────────────────────────────────────────────────────

    private static GossipDaemon BuildDaemon(
        ISyncDaemonTransport transport,
        NodeIdentity identity,
        IEd25519Signer signer,
        RosterCrdtProjection projection,
        IPeerTrustPolicy trust) =>
        new(
            transport,
            new VectorClock(),
            Options.Create(new GossipDaemonOptions
            {
                RoundIntervalSeconds = 1,
                PeerPickCount = 1,
                ConnectTimeoutSeconds = 5,
                DeadPeerBackoffSeconds = 2,
            }),
            new InMemoryNodeIdentityProvider(identity),
            signer,
            deltaProducer: projection,
            deltaSink: projection,
            trustPolicy: trust, timeProvider: TimeProvider.System);

    private static async Task WaitForRosterMemberAsync(Replica r, string partyId, string because)
    {
        var deadline = DateTime.UtcNow + TimeSpan.FromSeconds(20);
        while (DateTime.UtcNow < deadline)
        {
            if (r.NodeRoster.Current.Contains(partyId)) return;
            await Task.Delay(150);
        }
        Assert.Fail($"{because} Party '{partyId}' never converged into {r.Name}'s roster.");
    }
}

using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging.Abstractions;
using Microsoft.Extensions.Options;

using Harborline.Api.Blocks.People.Foundation.Models;
using Harborline.Api.Foundation.Assets.Common;
using Harborline.Api.Foundation.Crypto;
using Harborline.Api.Foundation.Persistence;
using Harborline.Api.Kernel.Crdt;
using Harborline.Api.Kernel.Crdt.Backends;
using Harborline.Api.Kernel.Security.Crypto;
using Harborline.Api.Kernel.Security.Keys;
using Harborline.Api.Kernel.Sync.Application;
using Harborline.Api.Kernel.Sync.Gossip;
using Harborline.Api.Kernel.Sync.Handshake;
using Harborline.Api.Kernel.Sync.Identity;
using Harborline.Api.Kernel.Sync.Protocol;
using Harborline.Api.LocalNodeHost.Data;
using Harborline.Api.LocalNodeHost.Data.Comms;
using Harborline.Api.LocalNodeHost.Data.People;

// Two Ed25519Signer types are in scope: the daemon's transport signer
// (Harborline.Api.Kernel.Security.Crypto) and the comms message signer
// (Harborline.Api.Foundation.Crypto). Alias BOTH to avoid the ambiguous-reference
// collision (the unqualified name is ambiguous before overload resolution).
using TransportSigner = Harborline.Api.Kernel.Security.Crypto.Ed25519Signer;
using CommsSigner = Harborline.Api.Foundation.Crypto.Ed25519Signer;

namespace Harborline.Api.LocalNodeHost.Tests.Entities;

/// <summary>
/// GAP-1 HEADLINE acceptance — per-document-id gossip wire FAN-OUT: a SECOND doctype crosses the wire.
/// Two <see cref="GossipDaemon"/> instances over REAL loopback TCP, each whose delta plane is the
/// install-level <see cref="DeltaRoutingRegistry"/> with BOTH a contacts projection AND a comms projection
/// registered (the production object graph — the container bridge wires this exact router). A contact CREATE
/// AND a comms message authored on node A BOTH converge to node B — each routed to its own projection.
/// </summary>
/// <remarks>
/// <para>
/// <b>Why this bites pre-fix.</b> Before per-id fan-out, the daemon hard-coded a single <c>"default"</c>
/// outbound stream id (<c>GossipDaemon</c> phase-1 single-stream), which the router resolves to the
/// FIRST-registered doctype (contacts). The comms projection was registered on the router but the daemon
/// never iterated <see cref="DeltaRoutingRegistry.RegisteredDocumentIds"/>, so the comms delta NEVER crossed
/// the wire — only contacts converged. <see cref="Both_Contacts_And_Comms_Cross_The_Wire_Two_Doctypes"/>
/// asserts the comms message reaches B; that assertion FAILS pre-fix (comms never shipped) and PASSES now
/// (the daemon ships one DELTA_STREAM per registered doc-id, each routed by its StreamId). The contacts
/// assertion holds in BOTH worlds, isolating the fan-out as the thing that carries the second doctype.
/// </para>
/// <para>
/// <b>Same hardened channel.</b> Both daemons run the LIVE shared-root trust gate + DoS caps + rate limiter;
/// the fan-out adds per-id streams over that one authenticated/capped channel — no new unauthenticated path.
/// </para>
/// </remarks>
public sealed class TwoDoctypeWireFanoutTests : IAsyncLifetime
{
    private readonly List<IAsyncDisposable> _cleanup = new();
    private readonly List<string> _tempDirs = new();

    public Task InitializeAsync() => Task.CompletedTask;

    public async Task DisposeAsync()
    {
        foreach (var d in _cleanup)
        {
            try { await d.DisposeAsync(); } catch { /* best-effort */ }
        }
        foreach (var dir in _tempDirs)
        {
            try { if (Directory.Exists(dir)) Directory.Delete(dir, recursive: true); }
            catch { /* best-effort temp cleanup */ }
        }
    }

    private static readonly TenantId LocalTenant = new("local");
    private static readonly PartyId Actor = new("operator");
    private const string CommsTenant = "local";
    private static readonly IOperationVerifier Verifier = new Ed25519Verifier();

    [Fact(DisplayName =
        "GAP-1: BOTH a contact AND a comms message authored on A converge to B — two doctypes cross the wire (fan-out)")]
    public async Task Both_Contacts_And_Comms_Cross_The_Wire_Two_Doctypes()
    {
        var signer = new TransportSigner();
        var (_, sharedRoot) = signer.GenerateKeyPair();

        // Two devices, ONE shared root seed → SAME team key (trust anchor), DISTINCT install node ids.
        var deviceA = TeamIdentity(sharedRoot, "team-home", signer, "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa");
        var deviceB = TeamIdentity((byte[])sharedRoot.Clone(), "team-home", signer, "bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb");
        Assert.Equal(deviceA.PublicKey, deviceB.PublicKey);

        var a = await NewReplicaAsync("A");
        var b = await NewReplicaAsync("B");

        // Each replica's delta plane is the install-level router with BOTH doctypes registered, contacts
        // FIRST (so contacts is the default route) and comms SECOND (the additive #1265 registration). This
        // is the production graph the container bridge resolves — NOT a hand-injected single projection.
        Assert.Equal(ContactCrdtProjection.DocumentId, a.Router!.DefaultEntry);
        Assert.Contains(ContactCrdtProjection.DocumentId, a.Router.RegisteredDocumentIds);
        Assert.Contains(CommsCrdtProjection.DocumentId, a.Router.RegisteredDocumentIds);
        Assert.Equal(2, a.Router.RegisteredDocumentIds.Count); // two doctypes — the fan-out cardinality

        // B listens; B's accept loop runs the LIVE shared-root trust gate and feeds inbound deltas to B's
        // router (which routes each by StreamId to the right projection).
        var transportB = new TcpSyncDaemonTransport("tcp://127.0.0.1:0");
        _cleanup.Add(transportB);
        var endpointB = transportB.ListenEndpoint!;
        var daemonB = BuildDaemon(transportB, deviceB, signer, b.Router!, new SharedRootTrustPolicy(deviceB.PublicKey));
        _cleanup.Add(daemonB);
        await daemonB.StartListeningAsync(CancellationToken.None);

        // A initiates; A's daemon ships one DELTA_STREAM per registered doc-id each round.
        var transportA = new TcpSyncDaemonTransport();
        _cleanup.Add(transportA);
        var daemonA = BuildDaemon(transportA, deviceA, signer, a.Router!, new SharedRootTrustPolicy(deviceA.PublicKey));
        _cleanup.Add(daemonA);
        daemonA.AddPeer(endpointB, deviceB.PublicKey);
        await daemonA.StartAsync(CancellationToken.None);

        // ── Author BOTH doctypes on A ────────────────────────────────────────
        // A contact (doctype #1 — the one that already crossed pre-fix).
        var party = await CreateContactAsync(a, "Ada Lovelace");
        // A comms message (doctype #2 — the one the fan-out now carries).
        var message = await AppendCommsAsync(a, "alice", "hello team — first cross-wire message");

        // ── Doctype #1 converges (holds in BOTH pre- and post-fix) ───────────
        await WaitForContactAsync(b, party.Id, expected: "Ada Lovelace",
            because: "a contact CREATEd on A must reach B over the live daemon (doctype #1, the default route).");

        // ── Doctype #2 converges — THE FAN-OUT PROOF (FAILS pre-fix) ─────────
        await WaitForCommsAsync(b, message.MessageId, expectedBody: "hello team — first cross-wire message",
            because: "the comms message must ALSO cross the wire — per-id fan-out ships a SECOND DELTA_STREAM "
                   + "tagged \"comms\" that B routes to its comms projection. Pre-fix only \"default\"=contacts "
                   + "shipped, so this never converged.");

        // B's comms message is attributed to its author and verifies (the signed identity round-tripped over
        // the wire through the comms sink — proof it really traversed the comms route, not contacts).
        var bLog = await b.Comms!.ReadLogAsync(CommsTenant, CancellationToken.None);
        var landed = Assert.Single(bLog, m => m.MessageId == message.MessageId);
        Assert.Equal("alice", landed.AuthorPartyId);
        Assert.True(CommsMessageFactory.VerifyAuthorship(landed, Verifier));

        await daemonA.StopAsync(CancellationToken.None);
        await daemonB.StopListeningAsync(CancellationToken.None);
    }

    [Fact(DisplayName =
        "GAP-1 back-compat: a 'default'-only (non-fan-out) peer still converges contacts — single-stream wire still works")]
    public async Task Default_Only_Peer_Still_Converges_Contacts_Back_Compat()
    {
        var signer = new TransportSigner();
        var (_, sharedRoot) = signer.GenerateKeyPair();
        var deviceA = TeamIdentity(sharedRoot, "team-home", signer, "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa");
        var deviceB = TeamIdentity((byte[])sharedRoot.Clone(), "team-home", signer, "bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb");

        // B is a NON-FAN-OUT peer: its delta plane is a BARE contacts projection (NOT an IDeltaRouter), so it
        // ships/understands exactly one "default" stream — the legacy single-stream wire shape. A is a
        // fan-out peer (router with contacts registered). They must still converge contacts.
        var a = await NewReplicaAsync("A");
        var bLegacy = await NewLegacyReplicaAsync("B");

        var transportB = new TcpSyncDaemonTransport("tcp://127.0.0.1:0");
        _cleanup.Add(transportB);
        var endpointB = transportB.ListenEndpoint!;
        // B's daemon uses the BARE projection as producer+sink (the pre-router, single-stream posture).
        var daemonB = BuildDaemonBare(transportB, deviceB, signer, bLegacy.Contacts, new SharedRootTrustPolicy(deviceB.PublicKey));
        _cleanup.Add(daemonB);
        await daemonB.StartListeningAsync(CancellationToken.None);

        var transportA = new TcpSyncDaemonTransport();
        _cleanup.Add(transportA);
        var daemonA = BuildDaemon(transportA, deviceA, signer, a.Router!, new SharedRootTrustPolicy(deviceA.PublicKey));
        _cleanup.Add(daemonA);
        daemonA.AddPeer(endpointB, deviceB.PublicKey);
        await daemonA.StartAsync(CancellationToken.None);

        var party = await CreateContactAsync(a, "Grace Hopper");

        await WaitForContactAsync(bLegacy, party.Id, expected: "Grace Hopper",
            because: "a fan-out peer must still converge contacts to a single-stream 'default'-only peer (back-compat).");

        await daemonA.StopAsync(CancellationToken.None);
        await daemonB.StopListeningAsync(CancellationToken.None);
    }

    // ───────────────────────────── helpers ─────────────────────────────

    private GossipDaemon BuildDaemon(
        ISyncDaemonTransport transport, NodeIdentity identity, IEd25519Signer signer,
        IDeltaRouter router, IPeerTrustPolicy trust) =>
        new(
            transport,
            new VectorClock(),
            Options.Create(new GossipDaemonOptions
            {
                RoundIntervalSeconds = 1, PeerPickCount = 1, ConnectTimeoutSeconds = 5, DeadPeerBackoffSeconds = 2,
            }),
            new InMemoryNodeIdentityProvider(identity),
            signer,
            // The install-level ROUTER is BOTH outbound producer and inbound sink — the container-bridge graph.
            // The daemon iterates RegisteredDocumentIds for the per-id fan-out.
            deltaProducer: router,
            deltaSink: router,
            trustPolicy: trust, timeProvider: TimeProvider.System);

    private GossipDaemon BuildDaemonBare(
        ISyncDaemonTransport transport, NodeIdentity identity, IEd25519Signer signer,
        ContactCrdtProjection contacts, IPeerTrustPolicy trust) =>
        new(
            transport,
            new VectorClock(),
            Options.Create(new GossipDaemonOptions
            {
                RoundIntervalSeconds = 1, PeerPickCount = 1, ConnectTimeoutSeconds = 5, DeadPeerBackoffSeconds = 2,
            }),
            new InMemoryNodeIdentityProvider(identity),
            signer,
            // A BARE single-document projection (NOT an IDeltaRouter) — the legacy single-stream posture: the
            // daemon ships exactly one "default" frame and applies the inbound "default" frame to this doc.
            deltaProducer: contacts,
            deltaSink: contacts,
            trustPolicy: trust, timeProvider: TimeProvider.System);

    private static NodeIdentity TeamIdentity(byte[] rootSeed, string teamId, IEd25519Signer signer, string installNodeId)
    {
        var (rootPub, _) = signer.GenerateFromSeed(rootSeed);
        var root = new NodeIdentity(installNodeId, rootPub, rootSeed);
        return TeamScopedNodeIdentity.Derive(root, teamId, new TeamSubkeyDerivation(signer));
    }

    /// <summary>A replica whose delta plane is the install-level router with BOTH doctypes registered.</summary>
    private async Task<Replica> NewReplicaAsync(string name)
    {
        var dir = Path.Combine(Path.GetTempPath(), $"harborline-fanout-{name}-{Guid.NewGuid():N}");
        Directory.CreateDirectory(dir);
        _tempDirs.Add(dir);

        // Contacts + comms each over their own SQLite store + their own CRDT engine.
        var services = new ServiceCollection();
        services.AddLogging();
        services.AddSingleton<IHarborlineEntityModule, Harborline.Api.Blocks.People.Foundation.Data.PeopleEntityModule>();
        services.AddDbContextFactory<LocalNodeDbContext>(o => o.UseSqlite($"Data Source={Path.Combine(dir, "contacts.db")};Pooling=False"));
        services.AddDbContextFactory<NodeLocalCommsDbContext>(o => o.UseSqlite($"Data Source={Path.Combine(dir, "comms.db")};Pooling=False"));

        var sp = services.BuildServiceProvider();
        var contactsFactory = sp.GetRequiredService<IDbContextFactory<LocalNodeDbContext>>();
        var commsFactory = sp.GetRequiredService<IDbContextFactory<NodeLocalCommsDbContext>>();
        await using (var ctx = await contactsFactory.CreateDbContextAsync()) await ctx.Database.EnsureCreatedAsync();
        await using (var ctx = await commsFactory.CreateDbContextAsync()) await ctx.Database.EnsureCreatedAsync();

        // DISTINCT CRDT engines per doctype (the production graph — contacts and comms each own a document).
        var contacts = new ContactCrdtProjection(
            new YDotNetCrdtEngine(), contactsFactory, NullLogger<ContactCrdtProjection>.Instance);
        var comms = new CommsCrdtProjection(
            new YDotNetCrdtEngine(), commsFactory, Verifier, NullLogger<CommsCrdtProjection>.Instance);

        // The install-level router: contacts FIRST (default route), comms SECOND (additive #1265 registration).
        var router = new DeltaRoutingRegistry();
        router.Register(ContactCrdtProjection.DocumentId, contacts, contacts);
        router.Register(CommsCrdtProjection.DocumentId, comms, comms);

        var replica = new Replica
        {
            Name = name, Dir = dir, Sp = sp, ContactsFactory = contactsFactory, CommsFactory = commsFactory,
            Contacts = contacts, Comms = comms, Router = router,
        };
        _cleanup.Add(replica);
        return replica;
    }

    /// <summary>A legacy replica whose delta plane is a BARE contacts projection (no router, single-stream).</summary>
    private async Task<Replica> NewLegacyReplicaAsync(string name)
    {
        var dir = Path.Combine(Path.GetTempPath(), $"harborline-fanout-legacy-{name}-{Guid.NewGuid():N}");
        Directory.CreateDirectory(dir);
        _tempDirs.Add(dir);

        var services = new ServiceCollection();
        services.AddLogging();
        services.AddSingleton<IHarborlineEntityModule, Harborline.Api.Blocks.People.Foundation.Data.PeopleEntityModule>();
        services.AddDbContextFactory<LocalNodeDbContext>(o => o.UseSqlite($"Data Source={Path.Combine(dir, "contacts.db")};Pooling=False"));

        var sp = services.BuildServiceProvider();
        var contactsFactory = sp.GetRequiredService<IDbContextFactory<LocalNodeDbContext>>();
        await using (var ctx = await contactsFactory.CreateDbContextAsync()) await ctx.Database.EnsureCreatedAsync();

        var contacts = new ContactCrdtProjection(
            new YDotNetCrdtEngine(), contactsFactory, NullLogger<ContactCrdtProjection>.Instance);

        var replica = new Replica
        {
            Name = name, Dir = dir, Sp = sp, ContactsFactory = contactsFactory, CommsFactory = null,
            Contacts = contacts, Comms = null, Router = null,
        };
        _cleanup.Add(replica);
        return replica;
    }

    private static async Task<Party> CreateContactAsync(Replica r, string displayName)
    {
        var party = Party.Create(LocalTenant, PartyKind.Person, displayName, Actor, new Instant(System.TimeProvider.System.GetUtcNow()));
        await using (var ctx = await r.ContactsFactory.CreateDbContextAsync())
        {
            ctx.Set<Party>().Add(party);
            await ctx.SaveChangesAsync();
        }
        r.Contacts.ProjectUpsert(party);
        return party;
    }

    private async Task<MessageCrdtState> AppendCommsAsync(Replica r, string authorPartyId, string body)
    {
        var signer = new CommsSigner(KeyPair.Generate());
        var message = await CommsMessageFactory.CreateSignedAsync(
            signer, authorPartyId, CommsTenant, body, DateTimeOffset.UtcNow);
        await r.Comms!.PersistLocalAsync(message, CancellationToken.None);
        r.Comms.AppendLocal(message);
        return message;
    }

    private static async Task<string?> ReadContactNameAsync(Replica r, PartyId id)
    {
        await using var ctx = await r.ContactsFactory.CreateDbContextAsync();
        var p = await ctx.Set<Party>().IgnoreQueryFilters().AsNoTracking().FirstOrDefaultAsync(x => x.Id == id);
        return p?.DeletedAt is null ? p?.DisplayName : null;
    }

    private static async Task WaitForContactAsync(Replica r, PartyId id, string expected, string because)
    {
        var deadline = DateTime.UtcNow + TimeSpan.FromSeconds(20);
        string? last = null;
        while (DateTime.UtcNow < deadline)
        {
            last = await ReadContactNameAsync(r, id);
            if (last == expected) return;
            await Task.Delay(150);
        }
        Assert.Fail($"{because} Last observed contact in B's store: '{last ?? "(absent)"}', expected '{expected}'.");
    }

    private static async Task WaitForCommsAsync(Replica r, string messageId, string expectedBody, string because)
    {
        var deadline = DateTime.UtcNow + TimeSpan.FromSeconds(20);
        string? last = null;
        while (DateTime.UtcNow < deadline)
        {
            var log = await r.Comms!.ReadLogAsync(CommsTenant, CancellationToken.None);
            var hit = log.FirstOrDefault(m => m.MessageId == messageId);
            if (hit is not null) { if (hit.Body == expectedBody) return; last = hit.Body; }
            await Task.Delay(150);
        }
        Assert.Fail($"{because} Comms message '{messageId}' in B's log: '{last ?? "(absent)"}', expected '{expectedBody}'.");
    }

    private sealed class Replica : IAsyncDisposable
    {
        public required string Name { get; init; }
        public required string Dir { get; init; }
        public required ServiceProvider Sp { get; init; }
        public required IDbContextFactory<LocalNodeDbContext> ContactsFactory { get; init; }
        public required IDbContextFactory<NodeLocalCommsDbContext>? CommsFactory { get; init; }
        public required ContactCrdtProjection Contacts { get; init; }
        public required CommsCrdtProjection? Comms { get; init; }
        public required DeltaRoutingRegistry? Router { get; init; }

        public async ValueTask DisposeAsync()
        {
            await Contacts.DisposeAsync();
            if (Comms is not null) await Comms.DisposeAsync();
            await Sp.DisposeAsync();
        }
    }
}

using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging.Abstractions;
using Microsoft.Extensions.Options;

using Harborline.Api.Blocks.People.Foundation.Models;
using Harborline.Api.Blocks.People.Foundation.Data;
using Harborline.Api.Foundation.Assets.Common;
using Harborline.Api.Foundation.Crypto;
using Harborline.Api.Foundation.IdentityAtlas;
using Harborline.Api.Foundation.IdentityAtlas.Enrollment;
using Harborline.Api.Foundation.IdentityAtlas.Permissions;
using Harborline.Api.Foundation.Persistence;
using Harborline.Api.Kernel.Crdt;
using Harborline.Api.Kernel.Crdt.Backends;
using Harborline.Api.Kernel.Security.Crypto;
using Harborline.Api.Kernel.Security.Keys;
using Harborline.Api.Kernel.Sync.Gossip;
using Harborline.Api.Kernel.Sync.Handshake;
using Harborline.Api.Kernel.Sync.Identity;
using Harborline.Api.Kernel.Sync.Protocol;
using Harborline.Api.LocalNodeHost.Data;
using Harborline.Api.LocalNodeHost.Data.People;
using Harborline.Api.LocalNodeHost.Data.Roster;
using Harborline.Api.LocalNodeHost.Enrollment;
using Harborline.Api.LocalNodeHost.Health;

// Disambiguate: the transport-layer signer is the kernel-security Ed25519Signer (it owns GenerateKeyPair + is the
// IEd25519Signer the gossip daemon + TeamSubkeyDerivation take). The foundation-crypto Ed25519Signer is the
// IOperationSigner used by NodePrincipalSigner internally (we never construct it directly here).
using Ed25519Signer = Harborline.Api.Kernel.Security.Crypto.Ed25519Signer;

namespace Harborline.Api.LocalNodeHost.Tests.Entities;

/// <summary>
/// THE TEST EVERY PRIOR ONE SHOULD HAVE BEEN (cerebrum [2026-06-21]) — the two-sided WIRE ENROLLMENT trust
/// bootstrap, end-to-end, with TWO INDEPENDENT-GENESIS nodes and ZERO hand-provisioning of trust.
/// </summary>
/// <remarks>
/// <para>
/// <b>What every prior test did wrong (and hid the gap for the entire arc).</b> The "milestone" harness +
/// <see cref="EnrolledPeerConnectSyncTests"/> HAND-PROVISIONED trust: they gave each node the SAME team id, a
/// hand-seeded <c>MemberSetTrustPolicy</c> holding BOTH transport keys, and a shared roster — then proved comms
/// over that PRE-ESTABLISHED trust. They never exercised the BOOTSTRAP (B → a mutually-trusted member of A's team
/// over the wire). The headless production-route cross-machine verify caught it: two fresh nodes get
/// <c>PEER_UNTRUSTED</c> because the shipping admission was ADMITTER-NODE-LOCAL — A admits B into A's roster but
/// the admission never reaches B (roster-sync can't carry it; it needs an already-trusted session — chicken-and-
/// egg).
/// </para>
/// <para>
/// <b>What THIS test does (no hand-provisioning).</b> Two nodes with DISTINCT roots, DISTINCT own-teams, NO
/// hand-seeded trust, NO shared roster, NO pre-set <c>MemberSetTrustPolicy</c>:
/// <list type="number">
///   <item>A founds its team + mints a real invite (token + out-of-band team anchor).</item>
///   <item>B enrolls OVER THE WIRE via <see cref="NodeWireEnrollmentClient"/> — the ONLY trust input is the
///     invite + its anchor. B derives its A-team-scoped transport key, signs + sends the request to A's REAL
///     redeem logic, validates A's response against the anchor, and adopts A's team into B's roster + trust map.</item>
///   <item>After enrollment: BOTH nodes' <see cref="MemberSetTrustPolicy"/> (built from the post-enrollment
///     rosters — NOT hand-seeded) hold BOTH transport keys for A.teamId; the rosters converge (B in A's roster,
///     validates-to-genesis, on BOTH nodes); comms cross BOTH ways attributed to the correct enrolled party ids;
///     and a no-invite / forged peer is REJECTED (<c>PEER_UNTRUSTED</c>).</item>
/// </list>
/// </para>
/// <para>
/// <b>It FAILS on today's code (admitter-local) and PASSES after the build.</b> The
/// <see cref="EnrollmentBypassesBootstrap_ProvesTheGapExists"/> companion test pins the failing pre-build
/// behavior: with ONLY the shipping (A-side) admission and no joiner half, B's trust policy is empty toward A and
/// the handshake is rejected — the exact state the production verify hit.
/// </para>
/// </remarks>
public sealed class TwoSidedWireEnrollmentE2ETests : IAsyncLifetime
{
    private readonly List<IAsyncDisposable> _cleanup = new();
    private readonly List<string> _tempDirs = new();

    public Task InitializeAsync() => Task.CompletedTask;

    public async Task DisposeAsync()
    {
        foreach (var d in _cleanup)
        {
            try { await d.DisposeAsync(); } catch { /* best-effort */ }
        }
        foreach (var dir in _tempDirs)
        {
            try { if (Directory.Exists(dir)) Directory.Delete(dir, recursive: true); }
            catch { /* best-effort temp cleanup */ }
        }
    }

    private static readonly TenantId LocalTenant = new("local");
    private static readonly PartyId Actor = new("operator");
    private static readonly IOperationVerifier Verifier = new Ed25519Verifier();
    private static readonly ITeamSubkeyDerivation SubkeyDerivation = new TeamSubkeyDerivation(new Ed25519Signer());
    private static readonly IXWingSubkeyDerivation XWingSubkeyDerivation =
        new HkdfXWingSubkeyDerivation(new XWingKem());

    // ───────────────────────────────────────────────────────────────────────────────────────────────────────
    // THE headline test — two independent-genesis nodes, enrollment over the wire, mutual trust + sync + reject.
    // ───────────────────────────────────────────────────────────────────────────────────────────────────────

    [Fact(DisplayName = "two-sided wire enrollment: two INDEPENDENT-genesis nodes establish mutual trust over the wire (NO hand-provisioning) → roster converges, comms cross both ways, forged peer rejected")]
    public async Task TwoIndependentNodes_EnrollOverTheWire_MutualTrust_RosterConverges_CommsCrossBothWays_ForgedRejected()
    {
        // ── A: an INDEPENDENT node. Its own root, its own genesis team, its own roster. No knowledge of B. ─────
        var a = NewNode("A", teamSeed: "team-A-office");
        // ── B: an INDEPENDENT node. DISTINCT root, DISTINCT own-team, DISTINCT genesis. No knowledge of A. ─────
        var b = NewNode("B", teamSeed: "team-B-home");

        // Sanity: they are genuinely independent — different team ids, different genesis parties, different roots.
        Assert.NotEqual(a.Roster.Current.TeamId, b.Roster.Current.TeamId);
        Assert.NotEqual(a.Roster.Current.GenesisPartyId, b.Roster.Current.GenesisPartyId);

        // Pre-enrollment: NEITHER node trusts the other for the wire. B's trust set toward A's team is empty
        // (no admitted peers), and A has never heard of B. This is the real two-fresh-nodes starting state.
        Assert.Empty(a.Roster.TrustedTransportKeys());
        Assert.Empty(b.Roster.TrustedTransportKeys());

        // ── A mints a REAL invite (token + the out-of-band team anchor B will pin). ─────────────────────────────
        var anchor = TeamTrustAnchor.FromRoster(a.Roster.Current);
        var invite = a.Coordinator.CreateInvite(anchor);

        // ── B ENROLLS over the wire. The ONLY trust input is the invite token + the anchor (the out-of-band pin).
        // The transport drives A's REAL redeem logic (verify B's signature → admit → build the bootstrap response)
        // — exactly what the /admission/redeem route does, in-process here instead of over HTTP.
        var transport = new InProcessAdmitterTransport(a);
        var outcome = await b.EnrollmentClient.EnrollAsync(invite.TokenId, anchor, transport, CancellationToken.None);

        Assert.True(outcome.Succeeded, $"B must enroll over the wire from the invite alone. Reason: {outcome.FailureReason}");
        Assert.Equal(a.Roster.Current.TeamId, outcome.TeamId);          // B adopted A's team.

        // ── MUTUAL TRUST: both nodes' trust policies now hold BOTH transport keys for A.teamId — built from the
        // post-enrollment rosters, NOT hand-seeded. ──────────────────────────────────────────────────────────
        // A's transport key for A.teamId (the floor) + B's transport key for A.teamId (the key B presented).
        var aTransportKey = a.TransportKeyForTeam(a.Roster.Current.TeamId);
        var bTransportKeyForATeam = b.EnrollmentClient.DeriveTransportPublicKeyForTeam(a.Roster.Current.TeamId.ToString("D"));
        Assert.True(outcome.TransportPublicKey!.AsSpan().SequenceEqual(bTransportKeyForATeam),
            "the key B reports presenting must be its A-team-scoped subkey (the #1296-F2 JOINED-team scope).");

        // A's trust set: own-floor (A's team subkey) ∪ admitted peer B's transport key.
        var aTrustKeys = UnionFloorAndPeers(aTransportKey, a.Roster);
        Assert.Contains(aTrustKeys, k => k.AsSpan().SequenceEqual(aTransportKey));            // A trusts itself.
        Assert.Contains(aTrustKeys, k => k.AsSpan().SequenceEqual(bTransportKeyForATeam));    // A trusts B.

        // B's trust set: own A-team subkey (floor, since B adopted A's team) ∪ A's transport key (from adoption).
        var bTrustKeys = UnionFloorAndPeers(bTransportKeyForATeam, b.Roster);
        Assert.Contains(bTrustKeys, k => k.AsSpan().SequenceEqual(bTransportKeyForATeam));    // B trusts itself.
        Assert.Contains(bTrustKeys, k => k.AsSpan().SequenceEqual(aTransportKey));            // B trusts A.

        // ── ROSTER CONVERGED: B is in A's roster (A admitted it) AND in B's adopted roster, both validate to A's
        // genesis, on BOTH nodes. ────────────────────────────────────────────────────────────────────────────
        Assert.True(a.Roster.Current.Contains(b.PartyId), "A's roster must contain B (A admitted B).");
        Assert.True(a.Roster.Current.ValidatesToGenesis(Verifier));
        Assert.True(b.Roster.Current.Contains(b.PartyId), "B's adopted roster must contain B.");
        Assert.True(b.Roster.Current.Contains(a.PartyId), "B's adopted roster must contain A (the admitter).");
        Assert.True(b.Roster.Current.ValidatesToGenesis(Verifier), "B's adopted roster must validate to A's genesis.");
        Assert.Equal(a.PartyId, b.Roster.Current.GenesisPartyId);      // B's adopted genesis = A's genesis.

        // ── COMMS CROSS BOTH WAYS over the REAL gossip wire, gated by MemberSetTrustPolicy built from the
        // post-enrollment rosters (NOT hand-seeded). Use the two distinct A-team transport identities. ─────────
        var deviceA = a.TeamScopedIdentity(a.Roster.Current.TeamId);                 // A's A-team identity.
        var deviceB = b.TeamScopedIdentity(a.Roster.Current.TeamId);                 // B's A-team identity (adopted).
        Assert.NotEqual(deviceA.PublicKey, deviceB.PublicKey);                       // distinct-root ⇒ distinct keys.

        var signer = new Ed25519Signer();

        // B LISTENS; its accept loop runs the MemberSetTrustPolicy backed by B's POST-ENROLLMENT roster.
        var transportBListen = new TcpSyncDaemonTransport("tcp://127.0.0.1:0");
        _cleanup.Add(transportBListen);
        var endpointB = transportBListen.ListenEndpoint!;
        var daemonB = BuildDaemon(transportBListen, deviceB, signer, b.Projection, TrustPolicyFor(deviceB.PublicKey, b.Roster));
        _cleanup.Add(daemonB);
        await daemonB.StartListeningAsync(CancellationToken.None);

        // A initiates; its trust gate is backed by A's POST-ENROLLMENT roster. AddPeer carries only the address.
        var transportAOut = new TcpSyncDaemonTransport();
        _cleanup.Add(transportAOut);
        var daemonA = BuildDaemon(transportAOut, deviceA, signer, a.Projection, TrustPolicyFor(deviceA.PublicKey, a.Roster));
        _cleanup.Add(daemonA);
        daemonA.AddPeer(endpointB, deviceB.PublicKey);
        await daemonA.StartAsync(CancellationToken.None);

        // A→B: a contact CREATEd on A reaches B's read store (the trusted session passed — NOT PEER_UNTRUSTED).
        var fromA = await CreateContactAsync(a, "Ada Lovelace");
        await WaitForEfAsync(b, fromA.Id, expected: "Ada Lovelace",
            because: "after wire enrollment, A→B comms must cross the trusted session (B trusts A's HELLO via the "
                + "adopted transport key — the bootstrap that never worked before).");

        // B→A: also crosses (mutual). B listens AND can dial A — start A listening too, B dials A.
        var transportAListen = new TcpSyncDaemonTransport("tcp://127.0.0.1:0");
        _cleanup.Add(transportAListen);
        var endpointA = transportAListen.ListenEndpoint!;
        var daemonAListen = BuildDaemon(transportAListen, deviceA, signer, a.Projection, TrustPolicyFor(deviceA.PublicKey, a.Roster));
        _cleanup.Add(daemonAListen);
        await daemonAListen.StartListeningAsync(CancellationToken.None);

        var transportBOut = new TcpSyncDaemonTransport();
        _cleanup.Add(transportBOut);
        var daemonBOut = BuildDaemon(transportBOut, deviceB, signer, b.Projection, TrustPolicyFor(deviceB.PublicKey, b.Roster));
        _cleanup.Add(daemonBOut);
        daemonBOut.AddPeer(endpointA, deviceA.PublicKey);
        await daemonBOut.StartAsync(CancellationToken.None);

        var fromB = await CreateContactAsync(b, "Grace Hopper");
        await WaitForEfAsync(a, fromB.Id, expected: "Grace Hopper",
            because: "after wire enrollment, B→A comms must also cross (mutual trust — both policies hold both keys).");

        await daemonA.StopAsync(CancellationToken.None);
        await daemonBOut.StopAsync(CancellationToken.None);
        await daemonB.StopListeningAsync(CancellationToken.None);
        await daemonAListen.StopListeningAsync(CancellationToken.None);

        // ── A FORGED / NON-INVITE peer is REJECTED. Charlie never enrolled (no invite) → not in any roster →
        // its A-team transport key is in NO trust set → PEER_UNTRUSTED. ───────────────────────────────────────
        var charlie = NewNode("Charlie", teamSeed: "team-A-office"); // even with A's team SEED, no enrollment.
        var deviceCharlie = charlie.TeamScopedIdentity(a.Roster.Current.TeamId);

        var transportBListen2 = new TcpSyncDaemonTransport("tcp://127.0.0.1:0");
        _cleanup.Add(transportBListen2);
        var endpointB2 = transportBListen2.ListenEndpoint!;
        var daemonB2 = BuildDaemon(transportBListen2, deviceB, signer, b.Projection, TrustPolicyFor(deviceB.PublicKey, b.Roster));
        _cleanup.Add(daemonB2);
        var bRejected = new SemaphoreSlim(0, 8);
        daemonB2.FrameReceived += (_, e) => { if (e.FrameType == GossipFrameType.HandshakeFailure) bRejected.Release(); };
        await daemonB2.StartListeningAsync(CancellationToken.None);

        var transportCharlie = new TcpSyncDaemonTransport();
        _cleanup.Add(transportCharlie);
        var daemonCharlie = BuildDaemon(transportCharlie, deviceCharlie, signer, charlie.Projection,
            new MemberSetTrustPolicy(new List<byte[]> { deviceCharlie.PublicKey }));
        _cleanup.Add(daemonCharlie);
        daemonCharlie.AddPeer(endpointB2, deviceB.PublicKey);
        var forged = await CreateContactAsync(charlie, "Exfiltration Attempt");
        await daemonCharlie.StartAsync(CancellationToken.None);

        Assert.True(await bRejected.WaitAsync(TimeSpan.FromSeconds(15)),
            "B must reject the non-invite peer Charlie (PEER_UNTRUSTED) — enrollment, not address, is trust.");

        await Task.Delay(1500);
        await using (var ctx = await b.Factory.CreateDbContextAsync())
        {
            var leaked = await ctx.Set<Party>().IgnoreQueryFilters().AsNoTracking()
                .FirstOrDefaultAsync(p => p.Id == forged.Id);
            Assert.Null(leaked);
        }

        await daemonCharlie.StopAsync(CancellationToken.None);
        await daemonB2.StopListeningAsync(CancellationToken.None);
    }

    // ───────────────────────────────────────────────────────────────────────────────────────────────────────
    // The pre-build PROOF: WITHOUT the joiner half (today's admitter-local admission), B's trust toward A is
    // empty and the handshake is PEER_UNTRUSTED. This is what the production verify hit. With the joiner half
    // (the headline test above) it passes. The two together pin "FAILS pre-build / PASSES post-build."
    // ───────────────────────────────────────────────────────────────────────────────────────────────────────

    [Fact(DisplayName = "PROOF the gap was real: with ONLY the shipping admitter-local admission (no joiner adoption), B does NOT trust A → handshake rejected")]
    public async Task EnrollmentBypassesBootstrap_ProvesTheGapExists()
    {
        var a = NewNode("A", teamSeed: "team-A-office");
        var b = NewNode("B", teamSeed: "team-B-home");

        // Simulate ONLY the shipping (pre-build) behavior: A admits B locally (admitter-node-local), and the
        // admission NEVER reaches B (no joiner adoption — the missing half). B keeps its OWN genesis team + empty
        // trust toward A.
        var anchor = TeamTrustAnchor.FromRoster(a.Roster.Current);
        var invite = a.Coordinator.CreateInvite(anchor);
        var bTransportForA = b.EnrollmentClient.DeriveTransportPublicKeyForTeam(a.Roster.Current.TeamId.ToString("D"));
        var admit = a.Coordinator.AdmitOverInvite(
            a.Roster.Current, invite.TokenId, a.PartyId, a.Signer.Signer, b.PartyId, b.Signer.Signer.IssuerId,
            PermissionCompositions.Member);
        Assert.True(admit.Admitted_);
        a.Roster.AdmitPeer(admit.Roster!, b.PartyId, bTransportForA); // A's local trust map updated (A trusts B).

        // B got NOTHING — its trust set toward A is empty (the admitter-local gap).
        Assert.Empty(b.Roster.TrustedTransportKeys());

        // Stand up the wire: A initiates to B. B's trust gate is its OWN (un-adopted) roster — it does NOT hold
        // A's transport key, so B rejects A's HELLO → PEER_UNTRUSTED. The exact production-verify failure.
        var signer = new Ed25519Signer();
        var deviceA = a.TeamScopedIdentity(a.Roster.Current.TeamId);                 // A's A-team identity.
        var deviceB = b.TeamScopedIdentity(a.Roster.Current.TeamId);                 // B's A-team identity (its HELLO key).

        var transportBListen = new TcpSyncDaemonTransport("tcp://127.0.0.1:0");
        _cleanup.Add(transportBListen);
        var endpointB = transportBListen.ListenEndpoint!;
        // B's trust gate = B's OWN roster (un-adopted) — it has NO peer transport keys, only B's own floor for
        // B's-OWN team, which is NOT even A's team. So it trusts neither A's key nor (here) its own A-team key.
        var bTrust = TrustPolicyFor(deviceB.PublicKey, b.Roster);
        var daemonB = BuildDaemon(transportBListen, deviceB, signer, b.Projection, bTrust);
        _cleanup.Add(daemonB);
        var bRejected = new SemaphoreSlim(0, 8);
        daemonB.FrameReceived += (_, e) => { if (e.FrameType == GossipFrameType.HandshakeFailure) bRejected.Release(); };
        await daemonB.StartListeningAsync(CancellationToken.None);

        var transportA = new TcpSyncDaemonTransport();
        _cleanup.Add(transportA);
        var daemonA = BuildDaemon(transportA, deviceA, signer, a.Projection, TrustPolicyFor(deviceA.PublicKey, a.Roster));
        _cleanup.Add(daemonA);
        daemonA.AddPeer(endpointB, deviceB.PublicKey);
        var party = await CreateContactAsync(a, "Should Not Cross");
        await daemonA.StartAsync(CancellationToken.None);

        Assert.True(await bRejected.WaitAsync(TimeSpan.FromSeconds(15)),
            "Without the joiner adoption (the admitter-local gap), B does NOT trust A's HELLO → PEER_UNTRUSTED. "
            + "This is the production-verify failure the joiner half closes.");

        await Task.Delay(1000);
        await using (var ctx = await b.Factory.CreateDbContextAsync())
        {
            var leaked = await ctx.Set<Party>().IgnoreQueryFilters().AsNoTracking()
                .FirstOrDefaultAsync(p => p.Id == party.Id);
            Assert.Null(leaked); // admitter-local admission → no comms cross → exactly the gap.
        }

        await daemonA.StopAsync(CancellationToken.None);
        await daemonB.StopListeningAsync(CancellationToken.None);
    }

    // ───────────────────────────────────────────────────────────────────────────────────────────────────────
    // #1304 F1 — THE SUPERSESSION-FAULT BITE. The fix is FAIL-CLOSED supersede-before-adopt: if the synced-doctype
    // supersession throws (its durable purge does an EF SaveChangesAsync that can throw DbUpdateException /
    // SqliteException), the JOIN must FAIL LOUD + RETRYABLE with a DISTINCT reason — NOT silently adopt A in memory
    // while leaving B's own genesis on the synced doctype (the persistent dual-genesis converge-never poison the
    // verdict named the BLOCKER). Drive the REAL EnrollAsync over the REAL admitter response with a supersession
    // that throws; assert (a) the enroll FAILS with roster_supersession_failed (not Succeeded, not a silent adopt),
    // and (b) B is left NON-POISONED — UNCHANGED on its OWN genesis team (no partial adopt, no half-state).
    //
    // PRE-FIX (the unhandled call at the old step 5b) the throw would propagate OUT of EnrollAsync after the
    // in-memory AdoptEnrollment had ALREADY run → B half-adopted + the exception escapes as a misleading 409/500 →
    // the exact silent-partial poison. POST-FIX EnrollAsync catches it, adopts nothing, and returns the loud reason.
    // ───────────────────────────────────────────────────────────────────────────────────────────────────────

    [Fact(DisplayName = "#1304 F1 SUPERSESSION-FAULT BITE: a throwing roster supersession makes the JOIN FAIL LOUD + retryable (roster_supersession_failed) and leaves B UNCHANGED on its own team — NOT a silent adopt + dual-genesis poison")]
    public async Task Supersession_Throw_FailsJoinLoud_LeavesBUnpoisoned()
    {
        // A founds its team + mints a real invite; the in-process transport drives A's REAL admit-and-respond.
        var a = NewNode("A", teamSeed: "team-A-office");
        var b = NewNode("B", teamSeed: "team-B-home");
        var anchor = TeamTrustAnchor.FromRoster(a.Roster.Current);
        var invite = a.Coordinator.CreateInvite(anchor);
        var transport = new InProcessAdmitterTransport(a);

        var bOwnTeamBefore = b.Roster.Current.TeamId;
        var bGenesisPartyBefore = b.Roster.Current.GenesisPartyId;
        Assert.NotEqual(a.Roster.Current.TeamId, bOwnTeamBefore); // a genuine cross-team join (supersession runs).

        // B's enrollment client wired with a supersession seam that THROWS (simulates the durable-purge
        // SaveChangesAsync faulting — DbUpdateException). EnrollAsync must NOT adopt; it must fail loud + retryable.
        var faulting = new ThrowingSupersession();
        var bClientFaulting = new NodeWireEnrollmentClient(
            b.RootIdentity, SubkeyDerivation, XWingSubkeyDerivation,
            b.Signer.Signer, b.PartyId, b.Roster, Verifier, faulting, clock: TimeProvider.System);

        var outcome = await bClientFaulting.EnrollAsync(invite.TokenId, anchor, transport, CancellationToken.None);

        // (a) LOUD + RETRYABLE + DISTINCT — not Succeeded, not a silent 200/409/500.
        Assert.False(outcome.Succeeded, "a supersession fault must FAIL the join (no silent adopt).");
        Assert.Equal("roster_supersession_failed", outcome.FailureReason);
        Assert.True(faulting.WasCalled, "the supersession must have been REACHED (the join is a genuine cross-team join).");

        // (b) B is UNCHANGED — still on its OWN genesis team, NOT half-adopted into A. No dual-genesis poison: B's
        //     in-memory roster never swapped, so nothing is inconsistent with the synced doctype.
        Assert.Equal(bOwnTeamBefore, b.Roster.Current.TeamId);
        Assert.Equal(bGenesisPartyBefore, b.Roster.Current.GenesisPartyId);
        Assert.False(b.Roster.Current.Contains(a.PartyId), "B must NOT have adopted A (the fault aborted the join).");
        Assert.Empty(b.Roster.TrustedTransportKeys());

        // RETRY proves recoverable: re-running the join from B's SAME unchanged own-team state with a HEALTHY
        // supersession now succeeds (the fault left no residue on B blocking a retry — atomic-ish: fully joins on
        // retry or cleanly didn't). A fresh admitter A2 (a re-issued invite — a new admit, since the first faulting
        // attempt already admitted B into the original A's roster) stands in for "operator re-runs the join".
        var a2 = NewNode("A2", teamSeed: "team-A2-office");
        var anchor2 = TeamTrustAnchor.FromRoster(a2.Roster.Current);
        var inviteRetry = a2.Coordinator.CreateInvite(anchor2);
        var transport2 = new InProcessAdmitterTransport(a2);
        var healthy = new CountingSupersession();
        var bClientHealthy = new NodeWireEnrollmentClient(
            b.RootIdentity, SubkeyDerivation, XWingSubkeyDerivation,
            b.Signer.Signer, b.PartyId, b.Roster, Verifier, healthy, clock: TimeProvider.System);
        var retry = await bClientHealthy.EnrollAsync(inviteRetry.TokenId, anchor2, transport2, CancellationToken.None);

        Assert.True(retry.Succeeded, $"a re-join after a supersession fault must succeed from B's clean state. Reason: {retry.FailureReason}");
        Assert.Equal(a2.Roster.Current.TeamId, retry.TeamId);
        Assert.True(healthy.WasCalled, "the retry must have run the supersession.");
        Assert.True(b.Roster.Current.Contains(a2.PartyId), "after the successful retry B has adopted A2's team.");
    }

    /// <summary>A supersession seam whose durable purge THROWS — simulates the EF SaveChangesAsync fault
    /// (DbUpdateException / SqliteException) the #1304 F1 fail-closed path must turn into a loud, retryable join
    /// failure rather than a silent partial adopt.</summary>
    private sealed class ThrowingSupersession : IOwnTeamRosterSupersession
    {
        public bool WasCalled { get; private set; }
        public Task<int> SupersedeOwnTeamRecordsAsync(Guid ownTeamId, CancellationToken ct)
        {
            WasCalled = true;
            throw new InvalidOperationException("simulated durable-purge SaveChangesAsync fault (DbUpdateException).");
        }
    }

    /// <summary>A healthy supersession seam (records that it ran) — the retry path's clean replacement.</summary>
    private sealed class CountingSupersession : IOwnTeamRosterSupersession
    {
        public bool WasCalled { get; private set; }
        public Task<int> SupersedeOwnTeamRecordsAsync(Guid ownTeamId, CancellationToken ct)
        {
            WasCalled = true;
            return Task.FromResult(0); // no synced doctype in this fixture — 0 records, but the call SUCCEEDS.
        }
    }

    // ───────────────────────────── node fixture (a self-contained independent node) ─────────────────────────

    /// <summary>An INDEPENDENT node fixture — its own root seed, genesis roster, admission seam, projection,
    /// and joiner enrollment client. No shared state with any other node (the no-hand-provisioning discipline).</summary>
    private sealed class NodeFixture
    {
        public required string Name { get; init; }
        public required byte[] RootSeed { get; init; }
        public required NodeIdentity RootIdentity { get; init; }
        public required NodePrincipalSigner Signer { get; init; }
        public required string PartyId { get; init; }
        public required NodeTeamRoster Roster { get; init; }
        public required AdmissionCoordinator Coordinator { get; init; }
        public required NodeWireEnrollmentClient EnrollmentClient { get; init; }
        public required IDbContextFactory<LocalNodeDbContext> Factory { get; init; }
        public required ContactCrdtProjection Projection { get; init; }

        /// <summary>This node's team-scoped transport PUBLIC key for a given team (HKDF(root, teamId)).</summary>
        public byte[] TransportKeyForTeam(Guid teamId) =>
            TeamScopedNodeIdentity.Derive(RootIdentity, teamId.ToString("D"), SubkeyDerivation).PublicKey;

        /// <summary>This node's team-scoped NodeIdentity for a given team (the wire HELLO identity).</summary>
        public NodeIdentity TeamScopedIdentity(Guid teamId) =>
            TeamScopedNodeIdentity.Derive(RootIdentity, teamId.ToString("D"), SubkeyDerivation);
    }

    private NodeFixture NewNode(string name, string teamSeed)
    {
        // DISTINCT root seed per node (the real independent-node case).
        var ed = new Ed25519Signer();
        var (rootPub, rootPriv) = ed.GenerateKeyPair();
        var nodeId = Convert.ToHexString(rootPub.AsSpan(0, 16)).ToLowerInvariant();
        var rootIdentity = new NodeIdentity(nodeId, rootPub, rootPriv);

        var signer = new NodePrincipalSigner(rootPriv);
        // Per-node-distinct party id (gap #2 shape: os:<name>#<key8>).
        var keyHex8 = Convert.ToHexString(signer.Signer.IssuerId.AsSpan()[..4]).ToLowerInvariant();
        var partyId = $"os:{name}#{keyHex8}";

        // A DISTINCT genesis team per node — deterministic from (teamSeed, nodeId) so each node's own team differs.
        var teamId = new Guid(System.Security.Cryptography.SHA256.HashData(
            System.Text.Encoding.UTF8.GetBytes(teamSeed + ":" + nodeId)).AsSpan(0, 16).ToArray());

        var genesisRoster = MemberRoster.StableGenesis(teamId, partyId, signer.Signer, Verifier);
        var roster = new NodeTeamRoster(genesisRoster);
        var coordinator = new AdmissionCoordinator(Verifier, new InMemoryAdmissionTokenStore(), clock: TimeProvider.System);

        var enrollmentClient = new NodeWireEnrollmentClient(
            rootIdentity, SubkeyDerivation, XWingSubkeyDerivation, signer.Signer, partyId, roster, Verifier, clock: TimeProvider.System);

        var dir = Path.Combine(Path.GetTempPath(), $"harborline-2sided-{name}-{Guid.NewGuid():N}");
        Directory.CreateDirectory(dir);
        _tempDirs.Add(dir);
        var services = new ServiceCollection();
        services.AddLogging();
        services.AddSingleton<IHarborlineEntityModule, PeopleEntityModule>();
        services.AddDbContextFactory<LocalNodeDbContext>(opt =>
            opt.UseSqlite($"Data Source={Path.Combine(dir, "local-node.db")};Pooling=False"));
        services.AddSingleton<ICrdtEngine, YDotNetCrdtEngine>(); // real backend — convergence honest.
        var sp = services.BuildServiceProvider();
        var factory = sp.GetRequiredService<IDbContextFactory<LocalNodeDbContext>>();
        using (var ctx = factory.CreateDbContext()) ctx.Database.EnsureCreated();
        var projection = new ContactCrdtProjection(
            sp.GetRequiredService<ICrdtEngine>(), factory, NullLogger<ContactCrdtProjection>.Instance);
        _cleanup.Add(new ProjectionCleanup(projection, sp));

        return new NodeFixture
        {
            Name = name,
            RootSeed = rootPriv,
            RootIdentity = rootIdentity,
            Signer = signer,
            PartyId = partyId,
            Roster = roster,
            Coordinator = coordinator,
            EnrollmentClient = enrollmentClient,
            Factory = factory,
            Projection = projection,
        };
    }

    /// <summary>
    /// The in-process wire transport that drives A's REAL redeem logic (verify B's signed request → admit over the
    /// invite → build the bootstrap response). This is the EXACT logic <c>AdmissionRoutes.MapRedeemInvite</c> runs,
    /// minus HTTP — so the test exercises the production trust-bootstrap, not a test shortcut.
    /// </summary>
    private sealed class InProcessAdmitterTransport : IEnrollmentTransport
    {
        private readonly NodeFixture _admitter;
        public InProcessAdmitterTransport(NodeFixture admitter) => _admitter = admitter;

        public Task<EnrollmentResponse?> SendAsync(EnrollmentRequest request, CancellationToken ct)
        {
            // (1) A verifies B's signed request (proof-of-possession) — the route's first gate.
            if (!WireEnrollment.VerifyRequest(request, Verifier))
                return Task.FromResult<EnrollmentResponse?>(null);

            // (2) Redeem single-use + admit B (binds B's principal key; no-escalation enforced inside Admit).
            var joiningPrincipal = PrincipalId.FromBase64Url(request.JoiningPrincipalPublicKey);
            var admit = _admitter.Coordinator.AdmitOverInvite(
                _admitter.Roster.Current, request.TokenId, _admitter.PartyId, _admitter.Signer.Signer,
                request.JoiningPartyId, joiningPrincipal, PermissionCompositions.Member);
            if (!admit.Admitted_ || admit.Roster is null)
                return Task.FromResult<EnrollmentResponse?>(null);

            // (3) Wire B's transport key into A's local trust map (gap #3) — A now trusts B's wire HELLO.
            var joiningTransport = PrincipalId.FromBase64Url(request.JoiningTransportPublicKey).AsSpan().ToArray();
            _admitter.Roster.AdmitPeer(admit.Roster, request.JoiningPartyId, joiningTransport);

            // (4) Build the A→B bootstrap response — A's team-scoped transport key (the SAME key A presents on the
            // HELLO) + the per-member transport map (A's own + the just-admitted B).
            var admitterTransportKey = _admitter.TransportKeyForTeam(admit.Roster.TeamId);
            var memberKeys = new Dictionary<string, byte[]>(StringComparer.Ordinal)
            {
                [_admitter.PartyId] = admitterTransportKey,
            };
            foreach (var (party, key) in _admitter.Roster.AdmittedPeerTransportKeys())
                memberKeys[party] = key;

            var response = WireEnrollment.BuildResponse(admit.Roster, admitterTransportKey, memberKeys);
            return Task.FromResult<EnrollmentResponse?>(response);
        }
    }

    // ───────────────────────────── trust-gate + daemon helpers ─────────────────────────

    /// <summary>
    /// Build the EXACT production trust gate (<c>DefaultTeamServiceRegistrar</c> shape): own team subkey (the
    /// never-brick floor) ∪ the live admitted-member transport keys from the node's POST-ENROLLMENT roster. Read
    /// fresh on each handshake (the Func snapshot). This is NOT hand-seeded — it is computed from the roster the
    /// enrollment produced, so the test proves the bootstrap, not a pre-wired set.
    /// </summary>
    private static MemberSetTrustPolicy TrustPolicyFor(byte[] ownTeamSubkey, NodeTeamRoster roster) =>
        new(() =>
        {
            var keys = new List<byte[]> { ownTeamSubkey };
            keys.AddRange(roster.TrustedTransportKeys());
            return keys;
        });

    private static IReadOnlyList<byte[]> UnionFloorAndPeers(byte[] ownTeamSubkey, NodeTeamRoster roster)
    {
        var keys = new List<byte[]> { ownTeamSubkey };
        keys.AddRange(roster.TrustedTransportKeys());
        return keys;
    }

    private GossipDaemon BuildDaemon(
        ISyncDaemonTransport transport,
        NodeIdentity identity,
        IEd25519Signer signer,
        ContactCrdtProjection projection,
        IPeerTrustPolicy trust) =>
        new(
            transport,
            new VectorClock(),
            Options.Create(new GossipDaemonOptions
            {
                RoundIntervalSeconds = 1,
                PeerPickCount = 1,
                ConnectTimeoutSeconds = 5,
                DeadPeerBackoffSeconds = 2,
            }),
            new InMemoryNodeIdentityProvider(identity),
            signer,
            deltaProducer: projection,
            deltaSink: projection,
            trustPolicy: trust, timeProvider: TimeProvider.System);

    private static async Task<Party> CreateContactAsync(NodeFixture r, string displayName)
    {
        var party = Party.Create(LocalTenant, PartyKind.Person, displayName, Actor, new Instant(System.TimeProvider.System.GetUtcNow()));
        await using (var ctx = await r.Factory.CreateDbContextAsync())
        {
            ctx.Set<Party>().Add(party);
            await ctx.SaveChangesAsync();
        }
        r.Projection.ProjectUpsert(party);
        return party;
    }

    private static async Task<string?> ReadDisplayNameAsync(NodeFixture r, PartyId id)
    {
        await using var ctx = await r.Factory.CreateDbContextAsync();
        var p = await ctx.Set<Party>().IgnoreQueryFilters().AsNoTracking()
            .FirstOrDefaultAsync(x => x.Id == id);
        return p?.DeletedAt is null ? p?.DisplayName : null;
    }

    private static async Task WaitForEfAsync(NodeFixture r, PartyId id, string expected, string because)
    {
        var deadline = DateTime.UtcNow + TimeSpan.FromSeconds(20);
        string? last = null;
        while (DateTime.UtcNow < deadline)
        {
            last = await ReadDisplayNameAsync(r, id);
            if (last == expected) return;
            await Task.Delay(150);
        }
        Assert.Fail($"{because} Last observed value: '{last ?? "(absent)"}', expected '{expected}'.");
    }

    private sealed class ProjectionCleanup : IAsyncDisposable
    {
        private readonly ContactCrdtProjection _projection;
        private readonly ServiceProvider _sp;
        public ProjectionCleanup(ContactCrdtProjection projection, ServiceProvider sp)
        {
            _projection = projection;
            _sp = sp;
        }
        public async ValueTask DisposeAsync()
        {
            await _projection.DisposeAsync();
            await _sp.DisposeAsync();
        }
    }
}

using System.Text.Json;

using Harborline.Api.Foundation.Assets;
using Harborline.Api.Foundation.Assets.Common;
using Harborline.Api.Foundation.Assets.Entities;

namespace Harborline.Api.LocalNodeHost.Tests.Entities;

/// <summary>
/// Ticket 366 slice 1 — the behaviour of the record-write token: the mint's ordering guard, and the
/// store's refusal of a token minted against a schema that is not the stored record's (RW-H2, H10).
/// </summary>
public sealed class ValidatedRecordBodyAdmissionTests
{
    private static readonly SchemaId Thing = new("thing");
    private static readonly SchemaId Other = new("other");

    [Fact(DisplayName = "Ticket 366: the mint refuses before validating when the gate did not allow (holds RW-1 RW-2)")]
    public async Task MintRefusesWithoutAnAllowedDecision()
    {
        var validator = new CountingValidator();
        using var body = JsonDocument.Parse("""{"a":1}""");

        var refusal = await Assert.ThrowsAsync<InvalidOperationException>(() =>
            ValidatedRecordBody.AdmitAsync(validator, new Admission(false), Thing, body, Tenant, null));

        Assert.Contains("entity.validation.not_admitted", refusal.Message, StringComparison.Ordinal);
        // The ordering is the point: the validator must not have run for a write the gate refused.
        Assert.Equal(0, validator.Calls);
    }

    [Fact(DisplayName = "Ticket 366: the mint validates, then the token carries that schema (holds RW-2 RW-9)")]
    public async Task MintValidatesAndCarriesTheSchema()
    {
        var validator = new CountingValidator();
        using var body = JsonDocument.Parse("""{"a":1}""");

        var token = await ValidatedRecordBody.AdmitAsync(validator, new Admission(true), Thing, body, Tenant, null);

        Assert.Equal(1, validator.Calls);
        Assert.Equal(Thing, token.Schema);
        Assert.Same(body, token.Body);
    }

    [Fact(DisplayName = "Ticket 366: the store refuses an update token minted against another schema (holds RW-2 RW-9)")]
    public async Task StoreRefusesATokenFromAnotherSchema()
    {
        var validator = new CountingValidator();
        var store = new InMemoryEntityStore(new InMemoryAssetStorage(), TimeProvider.System, validator);
        using var body = JsonDocument.Parse("""{"a":1}""");
        var allowed = new Admission(true);

        var created = await ValidatedRecordBody.AdmitAsync(validator, allowed, Thing, body, Tenant, null);
        var id = await store.CreateAsync(
            created,
            new CreateOptions("record", "test", Guid.NewGuid().ToString("N"),
                new ActorId("actor"), new TenantId("tenant")));

        // A body the validator accepted — against the WRONG schema. This is the shape that broke the
        // competition candidate: a non-record admission must never reach a record's stored schema.
        var mismatched = await ValidatedRecordBody.AdmitAsync(validator, allowed, Other, body, Tenant, null);
        var refusal = await Assert.ThrowsAsync<EntityValidationException>(() =>
            store.UpdateAsync(id, mismatched, new UpdateOptions(new ActorId("actor"))));

        Assert.Equal("entity.validation.schema_mismatch", refusal.ReasonCode);

        // …and the refusal persisted nothing: the record still reads at its first version.
        var stored = await store.GetAsync(id);
        Assert.NotNull(stored);
        Assert.Equal(Thing, stored.Schema);
        Assert.Equal(1, stored.CurrentVersion.Sequence);
    }

    [Fact(DisplayName = "Ticket 366: a token for the record's own schema updates it (holds RW-2)")]
    public async Task StoreAcceptsATokenForTheRecordsOwnSchema()
    {
        var validator = new CountingValidator();
        var store = new InMemoryEntityStore(new InMemoryAssetStorage(), TimeProvider.System, validator);
        using var first = JsonDocument.Parse("""{"a":1}""");
        using var second = JsonDocument.Parse("""{"a":2}""");
        var allowed = new Admission(true);

        var id = await store.CreateAsync(
            await ValidatedRecordBody.AdmitAsync(validator, allowed, Thing, first, Tenant, null),
            new CreateOptions("record", "test", Guid.NewGuid().ToString("N"),
                new ActorId("actor"), new TenantId("tenant")));
        await store.UpdateAsync(
            id,
            await ValidatedRecordBody.AdmitAsync(validator, allowed, Thing, second, Tenant, null),
            new UpdateOptions(new ActorId("actor")));

        var stored = await store.GetAsync(id);
        Assert.NotNull(stored);
        Assert.Equal(2, stored.CurrentVersion.Sequence);
        Assert.Equal(2, stored.Body.RootElement.GetProperty("a").GetInt32());
    }

    private sealed record Admission(bool IsAllowed) : IWriteAdmission
    {
        public DateTimeOffset At { get; } = DateTimeOffset.UnixEpoch;
    }

    private static readonly TenantId Tenant = new("tenant");

    private sealed class CountingValidator : IEntityValidator
    {
        internal int Calls { get; private set; }

        public Task ValidateAsync(SchemaId schema, JsonDocument body, CancellationToken ct = default)
        {
            Calls++;
            return Task.CompletedTask;
        }
    }
}

