/// <summary>
/// ADR 0134 P1b-2 / P2 — route-level tests for the canonical-node-key principal
/// SIGNING route (<see cref="CurrentPrincipalSignatureRoutes"/>). Resolves the
/// P2 "node-key reachability" flag: the canonical .NET node key now HAS a reachable,
/// tested signing surface.
/// </summary>
/// <remarks>
/// <para>
/// Hosts the SAME route handler <see cref="CurrentPrincipalSignatureRoutes.Map"/>
/// registers, on a real in-process Kestrel listener bound to an ephemeral loopback
/// port, with a FIXED-SEED <see cref="NodePrincipalSigner"/> so the issuerId /
/// node-public-key are deterministic, and drives it with a real
/// <see cref="HttpClient"/>. Proves end-to-end: the bounded host-resolved principal,
/// the camelCase signed-principal envelope shape, the node-public-key trust anchor,
/// the canonical-form signature self-verifies, and — critically — that the route is
/// NOT a signing oracle (no request body / query selects WHAT is signed).
/// </para>
/// <para>
/// The cross-LANGUAGE proof (this .NET envelope → the TS <c>verifySignedPrincipal</c>
/// path) is pinned in <c>apps/capability-host/src/membrane/node-route-principal.interop.test.ts</c>
/// from the deterministic vector this suite's <see cref="EmitDeterministicVectorForTsPin"/>
/// fact prints.
/// </para>
/// </remarks>
public sealed class CurrentPrincipalSignatureRouteTests : IAsyncLifetime
{
    private readonly ITestOutputHelper _output;

    private WebApplication _app = null!;
    private HttpClient _client = null!;
    private string _baseUrl = null!;
    private NodePrincipalSigner _nodeSigner = null!;
    private NodeTeamRoster _roster = null!;

    private const string CanonicalPrincipal = "canonical-tenant-principal-294";

    // A fixed 32-byte seed (all 0x07) → a deterministic node identity for assertions.
    private static readonly byte[] FixedSeed = Enumerable.Repeat((byte)0x07, 32).ToArray();

    public CurrentPrincipalSignatureRouteTests(ITestOutputHelper output) => _output = output;

    public async Task InitializeAsync()
    {
        _nodeSigner = new NodePrincipalSigner(FixedSeed);
        _roster = new NodeTeamRoster(MemberRoster.Genesis(
            Guid.Parse("29400000-0000-4000-8000-000000000011"),
            CanonicalPrincipal,
            _nodeSigner.Signer,
            new Ed25519Verifier(),
            DateTimeOffset.UnixEpoch,
            Guid.Parse("29400000-0000-4000-8000-000000000012")));

        var builder = WebApplication.CreateBuilder();
        // Ticket 294 slice 3b: the desktop actor (no compile-time operator id).
        Harborline.Api.LocalNodeHost.Tests.Authorization.TestDesktopOperator.AddTestDesktopOperator(builder.Services);
        builder.WebHost.UseUrls("http://127.0.0.1:0");
        builder.Logging.ClearProviders();

        _app = builder.Build();

        // Map the SAME production route the hosted endpoint maps — one source of truth.
        CurrentPrincipalSignatureRoutes.Map(
            _app,
            _nodeSigner.Signer,
            _nodeSigner.NodePublicKey,
            new NodeCallerSessionToken(null),
            () => HostedCurrentPrincipalSignatureApiEndpoint.ResolveCurrentPrincipal(_roster, _nodeSigner),
            TimeProvider.System);

        await _app.StartAsync();

        var addresses = _app.Services.GetRequiredService<IServer>()
            .Features.Get<IServerAddressesFeature>();
        _baseUrl = addresses!.Addresses.First();
        _client = new HttpClient { BaseAddress = new Uri(_baseUrl) };
    }

    public async Task DisposeAsync()
    {
        _client?.Dispose();
        await _app.StopAsync();
        await _app.DisposeAsync();
        _nodeSigner?.Dispose();
    }

    private const string Route = "/api/local-node/current-principal-signature";

    [Fact(DisplayName = "Route: GET returns the signed-principal envelope (camelCase wire shape)")]
    public async Task Get_ReturnsSignedPrincipalEnvelope()
    {
        var doc = await _client.GetFromJsonAsync<JsonElement>(Route);

        // The camelCase envelope matching TS SignedPrincipalEnvelope + nodePublicKey.
        Assert.True(doc.TryGetProperty("principal", out var principal));
        Assert.True(doc.TryGetProperty("issuerId", out var issuerId));
        Assert.True(doc.TryGetProperty("issuedAt", out var issuedAt));
        Assert.True(doc.TryGetProperty("nonce", out var nonce));
        Assert.True(doc.TryGetProperty("signature", out var signature));
        Assert.True(doc.TryGetProperty("nodePublicKey", out var nodePublicKey));

        // issuedAt is a BARE integer epoch-ms (not an ISO string) — the canonical form.
        Assert.Equal(JsonValueKind.Number, issuedAt.ValueKind);
        Assert.True(issuedAt.GetInt64() > 0);

        // issuerId == nodePublicKey == the fixed-seed node identity (deterministic).
        Assert.Equal(_nodeSigner.NodePublicKey, issuerId.GetString());
        Assert.Equal(_nodeSigner.NodePublicKey, nodePublicKey.GetString());

        // nonce is the lowercase-hyphenated UUID text form.
        Assert.True(Guid.TryParseExact(nonce.GetString(), "D", out _));

        // signature is base64url of the raw 64 bytes.
        var sigBytes = Base64UrlDecode(signature.GetString()!);
        Assert.Equal(64, sigBytes.Length);
    }

    [Fact(DisplayName = "Route: the signed principal is the canonical tenant principal")]
    public async Task Get_SignsHostResolvedPrincipal()
    {
        var doc = await _client.GetFromJsonAsync<JsonElement>(Route);
        var principal = doc.GetProperty("principal");

        // This is the canonical party carried by the real roster edge selected by this node's signing key.
        Assert.Equal(CanonicalPrincipal, principal.GetProperty("id").GetString());
        Assert.Equal("canonical-tenant-principal", principal.GetProperty("kind").GetString());
        // Non-anonymous — the gate never signs an anonymous principal.
        Assert.True(principal.GetProperty("id").GetString()!.Length > "os:".Length);
    }

    [Fact(DisplayName = "294 s2b: HostedCurrentPrincipalSignatureApiEndpoint resolves its signing-key roster edge and names a missing edge")]
    public void HostedCurrentPrincipalSignatureApiEndpoint_ResolvesRosterEdge_OrRefusesWithNamedReason()
    {
        Assert.Equal(
            CanonicalPrincipal,
            HostedCurrentPrincipalSignatureApiEndpoint.ResolveCurrentPrincipal(_roster, _nodeSigner).Value);

        using var foreignSigner = new NodePrincipalSigner(Enumerable.Repeat((byte)0x08, 32).ToArray());
        var noMatchRoster = new NodeTeamRoster(MemberRoster.Genesis(
            Guid.Parse("29400000-0000-4000-8000-000000000013"),
            "other-canonical-principal-294",
            foreignSigner.Signer,
            new Ed25519Verifier(),
            DateTimeOffset.UnixEpoch,
            Guid.Parse("29400000-0000-4000-8000-000000000014")));

        var refusal = Assert.Throws<InvalidOperationException>(() =>
            HostedCurrentPrincipalSignatureApiEndpoint.ResolveCurrentPrincipal(noMatchRoster, _nodeSigner));
        Assert.Equal("current_node_roster_edge_not_found", refusal.Message);
    }

    [Fact(DisplayName = "Route: BOUNDED — a request body cannot select an arbitrary principal (no signing oracle)")]
    public async Task Post_WithArbitraryPrincipal_DoesNotSignIt()
    {
        // Attempt to coax the route into signing an attacker-chosen principal by POSTing
        // a body. The route is GET-only with NO body binding — a POST is 404/405, and a
        // GET ignores any query. Either way the attacker's principal is NEVER signed.
        var attacker = new { id = "os:root", displayName = "ATTACKER", kind = "spoofed" };

        var post = await _client.PostAsJsonAsync(Route, attacker);
        Assert.True(
            post.StatusCode is HttpStatusCode.NotFound or HttpStatusCode.MethodNotAllowed,
            $"Expected 404/405 for a POST body principal, got {(int)post.StatusCode}.");

        // And a GET with an attacker query string still signs ONLY the host principal.
        var doc = await _client.GetFromJsonAsync<JsonElement>($"{Route}?id=os:root&kind=spoofed");
        var signedId = doc.GetProperty("principal").GetProperty("id").GetString();
        Assert.Equal(CanonicalPrincipal, signedId);
        Assert.NotEqual("os:root", signedId);
    }

    [Fact(DisplayName = "Route: the signature verifies over the canonical form against the node public key")]
    public async Task Get_SignatureVerifies_OverCanonicalForm()
    {
        var doc = await _client.GetFromJsonAsync<JsonElement>(Route);

        var principal = new CurrentPrincipalSignatureRoutes.SignedPrincipalPayload(
            Id: doc.GetProperty("principal").GetProperty("id").GetString()!,
            DisplayName: doc.GetProperty("principal").GetProperty("displayName").GetString(),
            Kind: doc.GetProperty("principal").GetProperty("kind").GetString());
        var issuerId = PrincipalId.FromBase64Url(doc.GetProperty("issuerId").GetString()!);
        var issuedAtMs = doc.GetProperty("issuedAt").GetInt64();
        var nonce = Guid.ParseExact(doc.GetProperty("nonce").GetString()!, "D");
        var signature = Signature.FromBase64Url(doc.GetProperty("signature").GetString()!);

        // Rebuild the canonical signable bytes the route signed and verify the signature
        // resolves against the node public key (issuerId). Tamper → fails.
        var signable = CanonicalJson.SerializeSignable(
            principal,
            issuerId,
            DateTimeOffset.FromUnixTimeMilliseconds(issuedAtMs),
            nonce);

        Assert.True(
            KeyPair.VerifyRaw(issuerId.AsSpan(), signable, signature.AsSpan()),
            "The route signature must verify over the canonical signable bytes.");

        // Tampering the principal id breaks verification.
        var tampered = CanonicalJson.SerializeSignable(
            principal with { Id = "os:someone-else" }, issuerId,
            DateTimeOffset.FromUnixTimeMilliseconds(issuedAtMs), nonce);
        Assert.False(KeyPair.VerifyRaw(issuerId.AsSpan(), tampered, signature.AsSpan()));
    }

    [Fact(DisplayName = "Route: distinct calls use distinct nonces (replay defence input)")]
    public async Task Get_DistinctCalls_DistinctNonces()
    {
        var a = await _client.GetFromJsonAsync<JsonElement>(Route);
        var b = await _client.GetFromJsonAsync<JsonElement>(Route);
        Assert.NotEqual(
            a.GetProperty("nonce").GetString(),
            b.GetProperty("nonce").GetString());
    }

    /// <summary>
    /// Emits a DETERMINISTIC signed-principal envelope (fixed seed + fixed principal +
    /// fixed issuedAt + fixed nonce) as JSON to test output. The TS interop test pins
    /// this exact envelope and runs it through the REAL <c>verifySignedPrincipal</c>,
    /// proving the canonical-node-key → TS-verify path end-to-end. Re-run this fact and
    /// re-pin if the canonical form ever changes (it should not — #1254 froze it).
    /// </summary>
    [Fact(DisplayName = "Vector: emit a deterministic .NET-signed envelope for the TS interop pin")]
    public async Task EmitDeterministicVectorForTsPin()
    {
        using var signer = new NodePrincipalSigner(FixedSeed);

        // A FIXED principal (not Environment.UserName) so the vector is host-independent.
        var principal = new CurrentPrincipalSignatureRoutes.SignedPrincipalPayload(
            Id: "os:alice",
            DisplayName: "Alice Example",
            Kind: "local-os-user");
        var issuedAt = DateTimeOffset.FromUnixTimeMilliseconds(1781827200000);
        var nonce = Guid.ParseExact("11111111-2222-3333-4444-555555555555", "D");

        var op = await signer.Signer.SignAsync(principal, issuedAt, nonce);

        var envelope = new
        {
            principal = new
            {
                id = principal.Id,
                displayName = principal.DisplayName,
                kind = principal.Kind,
            },
            issuerId = op.IssuerId.ToBase64Url(),
            issuedAt = op.IssuedAt.ToUnixTimeMilliseconds(),
            nonce = op.Nonce.ToString("D"),
            signature = op.Signature.ToBase64Url(),
            nodePublicKey = signer.NodePublicKey,
        };

        var json = JsonSerializer.Serialize(envelope, new JsonSerializerOptions { WriteIndented = true });
        _output.WriteLine("=== DETERMINISTIC .NET SIGNED-PRINCIPAL ENVELOPE (pin into TS interop test) ===");
        _output.WriteLine(json);

        // Robust capture: also write to a deterministic temp path so the vector can be
        // read back cleanly regardless of console-logger CR mangling (used only to author
        // the TS pin; harmless in CI).
        var capturePath = Environment.GetEnvironmentVariable("CPSR_VECTOR_CAPTURE_PATH");
        if (!string.IsNullOrWhiteSpace(capturePath))
        {
            File.WriteAllText(capturePath, json, Encoding.UTF8);
        }

        // Sanity: it self-verifies over the canonical form here too.
        var signable = CanonicalJson.SerializeSignable(principal, op.IssuerId, issuedAt, nonce);
        Assert.True(KeyPair.VerifyRaw(op.IssuerId.AsSpan(), signable, op.Signature.AsSpan()));

        // The payload canonicalizes with camelCase keys (id/displayName/kind), byte-identical
        // to the TS serializeSignablePrincipal payload — the load-bearing cross-language
        // contract (a PascalCase Id would diverge + break the TS verify). Assert it here so a
        // regression in the payload's [JsonPropertyName] pins is caught WITHOUT re-running TS.
        var canon = Encoding.UTF8.GetString(signable);
        Assert.Contains("\"payload\":{\"displayName\":\"Alice Example\",\"id\":\"os:alice\",\"kind\":\"local-os-user\"}", canon);

        // Assert the deterministic node public key (so a regression in FromSeed is caught).
        Assert.Equal(signer.NodePublicKey, op.IssuerId.ToBase64Url());
    }

    private static byte[] Base64UrlDecode(string value)
    {
        var s = value.Replace('-', '+').Replace('_', '/');
        switch (s.Length % 4)
        {
            case 2: s += "=="; break;
            case 3: s += "="; break;
        }
        return Convert.FromBase64String(s);
    }
}

using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Text.RegularExpressions;

using Xunit;

namespace Harborline.Api.LocalNodeHost.Tests.Health;

/// <summary>
/// Every type registered in the DI container must be constructible BY the container.
///
/// Why this exists: on 2026-07-30 the dogfood host would not start, dying on
/// <c>WebTenantSelectionAuthority</c> with "a suitable constructor could not be located". The
/// constructor was <c>internal</c>. Microsoft's container selects constructors with
/// <c>Type.GetConstructors()</c>, which returns PUBLIC instance constructors only — so an
/// internal constructor on a registered type can never be resolved, whatever its parameters are.
///
/// SEVEN types were affected, the whole ADR 0160 selected-audience identity layer. None of it had
/// ever been DI-constructible, which is the mechanical reason behind earlier repository ticket #3329 ("no member can
/// sign in") and earlier repository ticket #3311 ("the Team &amp; access panel is unreachable in production"): the
/// routes were registered and could never have served a request.
///
/// Why the tests could not catch it: every test constructs these types with <c>new</c>, which
/// honours <c>internal</c> inside the assembly. Nothing anywhere resolved one through a provider.
/// The tests exercised a construction path production never uses.
///
/// SCOPE: every <c>Add(Singleton|Scoped|Transient)&lt;…&gt;</c> and <c>AddHostedService&lt;T&gt;</c>
/// registration written anywhere under <c>apps/local-node-host</c> — Program.cs and the ~30
/// composition extension methods alike. <c>AddHostedService&lt;T&gt;</c> reduces to
/// <c>Singleton&lt;IHostedService, T&gt;</c> and is constructed under the identical rule, so omitting
/// it would have missed hosted actors. Endpoint mappers are constructed explicitly at the
/// composition root and are covered by the composed-host boot tests instead.
///
/// NOT covered: factory-lambda registrations (<c>AddSingleton(sp =&gt; …)</c>), which the container
/// does not construct, and open generics. It needs no dependency stubs: a public constructor is
/// exactly and only what constructor selection requires. It cannot catch a MISSING registration —
/// only the container's own <c>ValidateOnBuild</c> does that, and it is currently Development-only
/// (see the followup card).
/// </summary>
public sealed class DiConstructibilityTests
{
    [Fact]
    public void Every_Di_Registered_Type_Exposes_A_Public_Constructor()
    {
        var appRoot = LocateAppRoot();
        var registered = new HashSet<string>(StringComparer.Ordinal);
        foreach (var file in Directory.EnumerateFiles(appRoot, "*.cs", SearchOption.AllDirectories))
        {
            if (file.Contains($"{Path.DirectorySeparatorChar}tests{Path.DirectorySeparatorChar}", StringComparison.OrdinalIgnoreCase)) continue;
            registered.UnionWith(RegisteredImplementationTypeNames(File.ReadAllText(file)));
        }

        // A DEGRADED parse — not merely an empty one — is the real vacuity risk: the service-type
        // pattern cannot match a generic service type, and the seven types this test was written for
        // sit in one contiguous block. Reformat that block and a count-only floor still passes while
        // the assertion has quietly stopped covering them. Assert the canaries are present by NAME.
        foreach (var canary in new[]
                 {
                     "WebTenantSelectionAuthority", "WebTenantSwitchAuthority", "WebSelectedSessionStore",
                     "WebSelectedSessionIdentityAuthority", "WebSelectedSessionLogoutAuthority",
                     "WebSelectedSessionPrincipalAuthority", "InstallationIdentityCoordinatorService",
                 })
        {
            Assert.True(
                registered.Contains(canary),
                $"the registration parse no longer sees {canary}. The check has narrowed silently — " +
                "fix the parser rather than dropping the canary.");
        }

        var assembly = typeof(Harborline.Api.LocalNodeHost.Capabilities.LocalNodeHostedComponentProfile).Assembly;
        var offenders = new List<string>();

        foreach (var name in registered.OrderBy(x => x, StringComparer.Ordinal))
        {
            var type = assembly.GetTypes().FirstOrDefault(t => t.Name == name && !t.IsInterface && !t.IsAbstract);
            if (type is null) continue;                       // generic/aliased registration, or not ours
            if (type.GetConstructors().Length > 0) continue;   // public instance ctor -> resolvable

            var nonPublic = type.GetConstructors(BindingFlags.NonPublic | BindingFlags.Instance);
            // Defensive: shapes with no declared instance constructor at all. A class with none gets
            // an implicit PUBLIC parameterless one and has already exited above, so this is not the
            // factory-registered case — those are not parsed here in the first place.
            if (nonPublic.Length == 0) continue;

            offenders.Add($"{type.FullName} (has only {string.Join("/", nonPublic.Select(c => c.IsAssembly ? "internal" : c.IsPrivate ? "private" : "protected"))} constructors)");
        }

        Assert.True(
            offenders.Count == 0,
            "These types are registered in the DI container but expose no PUBLIC constructor, so the " +
            "container cannot construct them and the host dies at startup with 'a suitable constructor " +
            "could not be located'. Making the constructor public widens nothing outside the assembly " +
            "when the class itself is internal:\n  " + string.Join("\n  ", offenders));
    }

    /// <summary>Implementation type names from Add/TryAdd registrations in Program.cs.</summary>
    private static HashSet<string> RegisteredImplementationTypeNames(string source)
    {
        var names = new HashSet<string>(StringComparer.Ordinal);

        // AddSingleton<IService, Implementation>()
        foreach (Match m in Regex.Matches(source, @"(?:Try)?Add(?:Singleton|Scoped|Transient)<\s*[A-Za-z0-9_.]+\s*,\s*([A-Za-z0-9_.]+)\s*>"))
        {
            names.Add(Simple(m.Groups[1].Value));
        }

        // AddSingleton<Implementation>() — no factory lambda, no second type argument
        foreach (Match m in Regex.Matches(source, @"(?:Try)?Add(?:Singleton|Scoped|Transient)<\s*([A-Za-z0-9_.]+)\s*>\s*\(\s*\)"))
        {
            names.Add(Simple(m.Groups[1].Value));
        }

        // AddHostedService<T>() — reduces to Singleton<IHostedService, T>, same constructor rule.
        foreach (Match m in Regex.Matches(source, @"AddHostedService<\s*([A-Za-z0-9_.]+)\s*>"))
        {
            names.Add(Simple(m.Groups[1].Value));
        }

        return names;
    }

    private static string Simple(string name) =>
        name.Contains('.') ? name[(name.LastIndexOf('.') + 1)..] : name;

    /// <summary>
    /// Walks up to the app project. Candidates never include a bare "bin": that matches the TEST
    /// project's own bin and short-circuits before reaching the app (a trap this repo has hit).
    /// </summary>
    private static string LocateAppRoot()
    {
        var directory = new DirectoryInfo(AppContext.BaseDirectory);
        while (directory is not null)
        {
            foreach (var candidate in new[] { Path.Combine("apps", "local-node-host"), "local-node-host" })
            {
                var path = Path.Combine(directory.FullName, candidate);
                if (File.Exists(Path.Combine(path, "Program.cs"))) return path;
            }
            if (File.Exists(Path.Combine(directory.FullName, "Program.cs"))) return directory.FullName;
            directory = directory.Parent;
        }

        throw new InvalidOperationException(
            $"local-node-host Program.cs not found walking up from {AppContext.BaseDirectory}. " +
            "Fix the probe rather than deleting the assertion.");
    }
}

