                        var method = evidenceType.GetProperty("HttpMethod")!.GetValue(evidence);
                        var fence = evidenceType.GetProperty("RouteFenceKind")!.GetValue(evidence);
                        return $"{endpoint.RoutePattern}|{method}|{fence ?? "none"}";
