            Environment.SetEnvironmentVariable(
                "LocalNode__SchedulingDogfood__Enabled",
                profile.SchedulingDogfoodEnabled ? "true" : "false");
            Environment.SetEnvironmentVariable(
                "LocalNode__MultiTeam__Enabled",
