    [Fact]
    public async Task GET_teams_returns_the_joined_teams_with_isActive_and_memberCount()
    {
        var response = await _client.GetAsync(TeamRoutes.ListRouteBase);
        Assert.True(response.IsSuccessStatusCode);

        using var doc = JsonDocument.Parse(await response.Content.ReadAsStringAsync());
        var teams = doc.RootElement.EnumerateArray().ToList();
        Assert.Equal(2, teams.Count);

        // Each entry carries the full TeamSummary contract shape.
        foreach (var team in teams)
        {
            Assert.True(team.TryGetProperty("teamId", out _));
            Assert.True(team.TryGetProperty("name", out _));
            Assert.True(team.TryGetProperty("isActive", out _));
            Assert.True(team.TryGetProperty("memberCount", out _));
        }

        var a = Assert.Single(teams, t => t.GetProperty("teamId").GetString() == TeamA.Value.ToString());
        Assert.Equal(TeamADisplay, a.GetProperty("name").GetString());
        Assert.True(a.GetProperty("isActive").GetBoolean());          // A is the active team
        Assert.Equal(2, a.GetProperty("memberCount").GetInt32());     // operator + peer

        var b = Assert.Single(teams, t => t.GetProperty("teamId").GetString() == TeamB.Value.ToString());
        Assert.Equal(TeamBDisplay, b.GetProperty("name").GetString());
        Assert.False(b.GetProperty("isActive").GetBoolean());         // B is NOT active
        Assert.Equal(1, b.GetProperty("memberCount").GetInt32());     // operator only

        // Exactly one team is active.
        Assert.Single(teams, t => t.GetProperty("isActive").GetBoolean());
    }

    [Fact]
    public async Task GET_active_team_returns_204_when_no_team_is_active()
    {
        // A fresh host with NO active team yet (boot) and no joined teams.
        var builder = WebApplication.CreateBuilder();
        // Ticket 294 slice 3b: the desktop actor (no compile-time operator id).
        Harborline.Api.LocalNodeHost.Tests.Authorization.TestDesktopOperator.AddTestDesktopOperator(builder.Services);
        builder.WebHost.UseUrls("http://127.0.0.1:0");
        builder.Logging.ClearProviders();
        await using var app = builder.Build();

        TeamRoutes.Map(app, new FakeTeamContextFactory(), new FakeActiveTeamAccessor(null),
            new InMemoryTeamRegistry());

        await app.StartAsync();
        var addresses = app.Services.GetRequiredService<IServer>()
            .Features.Get<IServerAddressesFeature>();
        using var client = new HttpClient { BaseAddress = new Uri(addresses!.Addresses.First()) };

        var active = await client.GetAsync(TeamRoutes.ActiveRouteBase);
        Assert.Equal(HttpStatusCode.NoContent, active.StatusCode);

        var list = await client.GetAsync(TeamRoutes.ListRouteBase);
        Assert.True(list.IsSuccessStatusCode);
        using var doc = JsonDocument.Parse(await list.Content.ReadAsStringAsync());
        Assert.Empty(doc.RootElement.EnumerateArray());

        await app.StopAsync();
    }

    [Fact]
    public async Task Both_routes_reject_401_when_caller_auth_is_enforced_and_no_bearer_is_presented()
    {
        const string token = "the-per-boot-session-token";

        var builder = WebApplication.CreateBuilder();
        // Ticket 294 slice 3b: the desktop actor (no compile-time operator id).
        Harborline.Api.LocalNodeHost.Tests.Authorization.TestDesktopOperator.AddTestDesktopOperator(builder.Services);
        builder.WebHost.UseUrls("http://127.0.0.1:0");
        builder.Logging.ClearProviders();
        await using var app = builder.Build();

        var team = MakeTeam(TeamA, TeamADisplay);
        // The per-route check is mapped with an ENFORCING token (defence-in-depth;
        // the authoritative gate is the SharedHostedWebApp listener middleware).
        TeamRoutes.Map(app, new FakeTeamContextFactory(team), new FakeActiveTeamAccessor(team),
            new InMemoryTeamRegistry(), new NodeCallerSessionToken(token));

        await app.StartAsync();
        var addresses = app.Services.GetRequiredService<IServer>()
            .Features.Get<IServerAddressesFeature>();
        using var client = new HttpClient { BaseAddress = new Uri(addresses!.Addresses.First()) };

        // No bearer → fail-closed 401 on BOTH routes.
        var listNoAuth = await client.GetAsync(TeamRoutes.ListRouteBase);
        Assert.Equal(HttpStatusCode.Unauthorized, listNoAuth.StatusCode);

        var activeNoAuth = await client.GetAsync(TeamRoutes.ActiveRouteBase);
        Assert.Equal(HttpStatusCode.Unauthorized, activeNoAuth.StatusCode);

        // Wrong bearer → still 401.
        client.DefaultRequestHeaders.Authorization = new AuthenticationHeaderValue("Bearer", "wrong");
        var listWrong = await client.GetAsync(TeamRoutes.ListRouteBase);
        Assert.Equal(HttpStatusCode.Unauthorized, listWrong.StatusCode);

        // Correct bearer → 200.
        client.DefaultRequestHeaders.Authorization = new AuthenticationHeaderValue("Bearer", token);
        var listOk = await client.GetAsync(TeamRoutes.ListRouteBase);
        Assert.Equal(HttpStatusCode.OK, listOk.StatusCode);

        var activeOk = await client.GetAsync(TeamRoutes.ActiveRouteBase);
        Assert.Equal(HttpStatusCode.OK, activeOk.StatusCode);

        await app.StopAsync();
    }

    private static TeamContext MakeTeam(TeamId id, string displayName)
    {
        var services = new ServiceCollection().BuildServiceProvider();
        return new TeamContext(id, displayName, services, TimeProvider.System);
    }

    private static ValueTask Seed(
        IMutableTeamRegistry memberships, ActorId actor, TeamId team, string displayName)
    {
        var membership = new TeamMembership(
            TeamId: team.Value,
            DisplayName: displayName,
            RoleDisplayName: "Member",
            SubkeyFingerprint: KeyFingerprint.FromPublicKey(team.Value.ToByteArray()),
            Role: TeamRole.Member,
            Permissions: PermissionCompositions.ForRole(TeamRole.Member));
        return memberships.AddMembershipAsync(actor, membership);
    }

    private sealed class FakeActiveTeamAccessor : IActiveTeamAccessor
    {
        public FakeActiveTeamAccessor(TeamContext? active) => Active = active;
        public TeamContext? Active { get; }
        public Task SetActiveAsync(TeamId teamId, CancellationToken ct) => Task.CompletedTask;
        public event EventHandler<ActiveTeamChangedEventArgs>? ActiveChanged;
        private void _keep() => ActiveChanged?.Invoke(this, new ActiveTeamChangedEventArgs(null, null));
    }

    private sealed class FakeTeamContextFactory : ITeamContextFactory
    {
        private readonly IReadOnlyCollection<TeamContext> _teams;
        public FakeTeamContextFactory(params TeamContext[] teams) => _teams = teams;
        public IReadOnlyCollection<TeamContext> Active => _teams;
        public Task<TeamContext> GetOrCreateAsync(TeamId teamId, string displayName, CancellationToken ct)
            => Task.FromResult(_teams.First(t => t.TeamId.Equals(teamId)));
        public Task RemoveAsync(TeamId teamId, CancellationToken ct) => Task.CompletedTask;
    }
}

using System.Net;

using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Routing;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;

using Harborline.Api.Kernel.Runtime.Teams;
using Harborline.Api.LocalNodeHost.Health;
using Harborline.Api.LocalNodeHost.Tests.Entities;

using Xunit;

namespace Harborline.Api.LocalNodeHost.Tests.Health;

/// <summary>
/// A hard load of a CLIENT-SIDE route must reach the SPA shell, and the fallback must never answer for
/// the server's own paths (card earlier repository ticket #3489).
/// </summary>
/// <remarks>
/// <para>
/// <c>UseDefaultFiles</c> resolves only the bare origin, so before the fallback a PATH-form client route
/// such as <c>/team</c> 404'd. The Harborline App uses <c>createHashRouter</c>, so its own URLs carry the route in
/// the fragment and a reload sends <c>GET /</c> — those always worked. The path form is reached by a
/// hand-typed or externally-authored link, and by cmd- or middle-clicking the app's own breadcrumbs, which
/// are real anchors whose left-click handler an open-in-new-tab bypasses. Latent until the front door
/// landed (#3329).
/// </para>
/// <para>
/// The fallback sits BEFORE the caller-auth gate, alongside the static middleware, so its path predicate
/// is the only thing between the API surface and an HTML body. A fallback that caught everything would
/// turn an unauthenticated API call into a 200 with HTML — worse than the 404 it replaced. Each test
/// below pins one guard, and each asserts on the BODY as well as the status: a 404 whose body is the
/// shell would satisfy a status-only assertion while being exactly the bug.
/// </para>
/// <para>
/// Caller-auth is ENFORCED here and a real API route is mapped. Without both, "an unknown /api path gets a
/// real status" only proves that routing 404s — not that the gate still answers, which is the claim.
/// </para>
/// </remarks>
public sealed class WebClientShellFallbackTests : IAsyncLifetime
{
    private const string ShellMarker = "<!-- harborline-web-client-shell -->";
    private const string CallerToken = "shell-fallback-caller-token-0001";
    private const string MappedApiRoute = "/api/local-node/shell-fallback-probe";

    private string _bundleRoot = string.Empty;
    private SharedHostedWebApp? _app;
    private ServiceProvider? _provider;
    private HttpClient? _client;

    public async Task InitializeAsync()
    {
        _bundleRoot = Path.Combine(Path.GetTempPath(), $"harborline-shell-fallback-{Guid.NewGuid():N}");
        Directory.CreateDirectory(_bundleRoot);
        Directory.CreateDirectory(Path.Combine(_bundleRoot, "assets"));
        await File.WriteAllTextAsync(
            Path.Combine(_bundleRoot, "index.html"),
            $"<!doctype html><html><body>{ShellMarker}</body></html>");
        await File.WriteAllTextAsync(
            Path.Combine(_bundleRoot, "assets", "main-a1b2c3.js"), "export const real = true;");

        var services = new ServiceCollection();
        services.AddTestKernelClock();
        services.AddLogging(b => b.ClearProviders());
        services.AddSingleton<IActiveTeamAccessor>(NodeTestActiveTeam.Accessor);
        // ENFORCED, and with a real API route mapped below. With a null token the gate waves everyone
        // through and no route exists, so "an unknown /api path gets a real status" would only be proving
        // that routing 404s — not that the caller-auth gate still answers, which is the actual claim.
        services.AddSingleton(new NodeCallerSessionToken(CallerToken));
        services.Configure<NodeWebClientOptions>(o =>
        {
            o.Enabled = true;
            o.BundleRoot = _bundleRoot;
        });
        _provider = services.BuildServiceProvider();

        _app = new SharedHostedWebApp(
            _provider,
            Options.Create(new LocalNodeOptions { HealthPort = 0 }),
            new Harborline.Api.LocalNodeHost.Capabilities.LocalNodeExecutableEndpointRegistry(),
            _provider.GetRequiredService<ILogger<SharedHostedWebApp>>(),
            _provider.GetRequiredService<TimeProvider>());

        _app.MapApiRoutes(a => a.MapGet(MappedApiRoute, () => Results.Ok(new { ok = true })));

        await _app.StartAsync(CancellationToken.None);
        _client = new HttpClient { BaseAddress = new Uri(_app.SelectedUrl!) };
    }

    public async Task DisposeAsync()
    {
        _client?.Dispose();
        if (_app is not null) { await _app.StopAsync(CancellationToken.None); await _app.DisposeAsync(); }
        if (_provider is not null) await _provider.DisposeAsync();
        try { if (Directory.Exists(_bundleRoot)) Directory.Delete(_bundleRoot, recursive: true); }
        catch { /* best-effort */ }
    }

    [Theory]
    [InlineData("/team")]           // the path form of a real client route
    [InlineData("/admin/access")]   // nested — the fallback is not depth-limited
    [InlineData("/apish")]          // a client route whose name merely STARTS with a reserved prefix
    public async Task A_hard_load_of_a_client_route_serves_the_shell(string path)
    {
        var response = await _client!.GetAsync(path);

        Assert.Equal(HttpStatusCode.OK, response.StatusCode);
        Assert.Contains(ShellMarker, await response.Content.ReadAsStringAsync(), StringComparison.Ordinal);
    }

    [Fact]
    public async Task The_bare_origin_still_serves_the_shell()
    {
        // UseDefaultFiles already handled this one; pinned so the fallback cannot regress it.
        var response = await _client!.GetAsync("/");

        Assert.Equal(HttpStatusCode.OK, response.StatusCode);
        Assert.Contains(ShellMarker, await response.Content.ReadAsStringAsync(), StringComparison.Ordinal);
    }

    [Theory]
    [InlineData("/api/local-node/does-not-exist")]
    [InlineData("/api/session/does-not-exist")]
    [InlineData("/health/does-not-exist")]
    [InlineData("/ws/does-not-exist")]
    public async Task An_unknown_server_path_gets_a_real_status_and_never_the_shell(string path)
    {
        // THE guard the card names. A fallback that answered here would turn an unauthenticated API call
        // into a 200 with an HTML body — worse than the 404 it replaced.
        var response = await _client!.GetAsync(path);

        Assert.NotEqual(HttpStatusCode.OK, response.StatusCode);
        Assert.DoesNotContain(
            ShellMarker, await response.Content.ReadAsStringAsync(), StringComparison.Ordinal);
    }

    [Fact]
    public async Task A_mapped_api_route_still_answers_401_without_a_token()
    {
        // THE property the fallback must not break, and the one the first revision of this suite could not
        // see: caller-auth is ENFORCED here and this route really exists, so a 401 is the gate answering —
        // not routing failing to match. A fallback that swallowed it would return 200 with HTML.
        var response = await _client!.GetAsync(MappedApiRoute);

        Assert.Equal(HttpStatusCode.Unauthorized, response.StatusCode);
        Assert.DoesNotContain(
            ShellMarker, await response.Content.ReadAsStringAsync(), StringComparison.Ordinal);
    }

    [Fact]
    public async Task A_mapped_api_route_still_serves_a_caller_holding_the_token()
    {
        // The control on the control: if the gate rejected everything, the test above would pass for the
        // wrong reason.
        var request = new HttpRequestMessage(HttpMethod.Get, MappedApiRoute);
        request.Headers.Add(NodeCallerSessionToken.HeaderName, "Bearer " + CallerToken);

        var response = await _client!.SendAsync(request);

        Assert.Equal(HttpStatusCode.OK, response.StatusCode);
    }

    [Theory]
    // Kestrel does not decode %2F, does not collapse //, and passes ; and \\ through, so a prefix-only
    // test let each of these reach the shell — turning a logged 401 into a silent 200. None ever selected
    // an endpoint, so nothing was reachable that should not have been; the STATUS is what regressed.
    //
    // Sent over a raw socket rather than HttpClient: HttpClient rewrites some of these before they leave
    // (it reads a leading // as protocol-relative and tries to connect to a host called "api"), so a
    // client-level test would be asserting on a request the server never sees.
    [InlineData("/api%2flocal-node%2fshell-fallback-probe")]
    [InlineData("//api/local-node/shell-fallback-probe")]
    [InlineData("/api;/local-node/shell-fallback-probe")]
    [InlineData("/api\\local-node\\shell-fallback-probe")]
    [InlineData("/%2e%2e/api/local-node/shell-fallback-probe")]
    public async Task An_encoded_path_never_gets_the_shell(string target)
    {
        var raw = await SendRawAsync(target);

        Assert.DoesNotContain(ShellMarker, raw, StringComparison.Ordinal);
        Assert.DoesNotContain(" 200 ", raw[..Math.Min(raw.Length, 16)], StringComparison.Ordinal);
    }

    /// <summary>Writes a request line verbatim, so the server sees exactly the target under test.</summary>
    private async Task<string> SendRawAsync(string target)
    {
        var uri = new Uri(_app!.SelectedUrl!);
        using var tcp = new System.Net.Sockets.TcpClient();
        await tcp.ConnectAsync(uri.Host, uri.Port);
        await using var stream = tcp.GetStream();

        var request = $"GET {target} HTTP/1.1\r\nHost: {uri.Host}:{uri.Port}\r\nConnection: close\r\n\r\n";
        var bytes = System.Text.Encoding.ASCII.GetBytes(request);
        await stream.WriteAsync(bytes);

        using var reader = new StreamReader(stream, System.Text.Encoding.UTF8);
        return await reader.ReadToEndAsync();
    }

    [Fact]
    public async Task A_missing_asset_declines_and_never_answers_html()
    {
        // The property is that the fallback DECLINES, never that a particular status comes back: with
        // caller-auth enforced the gate answers 401 before routing reaches its 404. Either is correct.
        // Answering HTML would produce a MIME-type failure in the browser instead of a missing-asset
        // error, hiding the real fault behind a confusing one.
        var response = await _client!.GetAsync("/assets/main-does-not-exist.js");

        Assert.NotEqual(HttpStatusCode.OK, response.StatusCode);
        Assert.DoesNotContain(
            ShellMarker, await response.Content.ReadAsStringAsync(), StringComparison.Ordinal);
    }

    [Fact]
    public async Task A_real_asset_is_still_served_as_itself()
    {
        // The control: if the fallback ran ahead of the static handler, every asset would come back as
        // the shell and the app would never boot.
        var response = await _client!.GetAsync("/assets/main-a1b2c3.js");

        Assert.Equal(HttpStatusCode.OK, response.StatusCode);
        Assert.Contains("export const real", await response.Content.ReadAsStringAsync(), StringComparison.Ordinal);
    }

    [Fact]
    public async Task A_post_to_an_unknown_path_never_gets_the_shell()
    {
        // Same harm as swallowing /api, reached by a different door: a write that silently succeeds with
        // a 200 and an HTML body.
        var response = await _client!.PostAsync("/team", new StringContent(string.Empty));

        Assert.NotEqual(HttpStatusCode.OK, response.StatusCode);
        Assert.DoesNotContain(
            ShellMarker, await response.Content.ReadAsStringAsync(), StringComparison.Ordinal);
    }
}

using Microsoft.Extensions.Logging.Abstractions;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;

using Harborline.Api.LocalNodeHost.Health.WebSession;

using Xunit;

namespace Harborline.Api.LocalNodeHost.Tests.Health;

/// <summary>
/// Unit proof of the S11 web-client login rate limiter: sliding window, lockout engage, exponential
/// backoff, release on expiry, reset on success, per-key independence, memory bound (fail-closed),
/// and concurrency safety.
/// </summary>
public sealed class WebLoginRateLimiterTests
{
    private const string User = "founder";
    private const string Source = "192.0.2.10";

    private sealed class MutableTimeProvider(DateTimeOffset start) : TimeProvider
    {
        private DateTimeOffset _now = start;
        public bool ThrowOnRead { get; set; }
        public override DateTimeOffset GetUtcNow() => ThrowOnRead
            ? throw new InvalidOperationException("clock unavailable")
            : _now;
        public void Advance(TimeSpan by) => _now += by;
    }

    private sealed class ThrowingLogger : ILogger<WebLoginRateLimiter>
    {
        public IDisposable? BeginScope<TState>(TState state) where TState : notnull => null;

        public bool IsEnabled(LogLevel logLevel) => true;

        public void Log<TState>(
            LogLevel logLevel,
            EventId eventId,
            TState state,
            Exception? exception,
            Func<TState, Exception?, string> formatter) =>
            throw new InvalidOperationException("logging provider failed");
    }

    private static (WebLoginRateLimiter Limiter, MutableTimeProvider Clock) Build(
        NodeWebLoginLockoutOptions? lockout = null,
        ILogger<WebLoginRateLimiter>? logger = null)
    {
        var clock = new MutableTimeProvider(
            new DateTimeOffset(2026, 8, 6, 12, 0, 0, TimeSpan.Zero));
        var options = Options.Create(new NodeWebClientOptions
        {
            Lockout = lockout ?? new NodeWebLoginLockoutOptions(),
        });
        return (new WebLoginRateLimiter(
            options,
            clock,
            logger ?? NullLogger<WebLoginRateLimiter>.Instance), clock);
    }

    private static void Fail(WebLoginRateLimiter limiter, int times, string user = User, string source = Source)
    {
        for (var i = 0; i < times; i++)
        {
            Assert.True(limiter.CheckAttempt(user, source).IsAllowed);
            limiter.RecordFailure(user, source);
        }
    }

    [Fact(DisplayName = "Below the threshold, attempts stay admitted")]
    public void BelowThreshold_Admitted()
    {
        var (limiter, _) = Build();
        Fail(limiter, 4);
        Assert.True(limiter.CheckAttempt(User, Source).IsAllowed);
    }

    [Fact(DisplayName = "The Nth failure in the window engages the lockout — even the CORRECT password is refused")]
    public void Threshold_EngagesLockout()
    {
        var (limiter, _) = Build();
        Fail(limiter, 5);
        var decision = limiter.CheckAttempt(User, Source);
        Assert.False(decision.IsAllowed);
        Assert.NotNull(decision.RetryAfter);
        Assert.True(decision.RetryAfter > TimeSpan.Zero);
    }

    [Fact(DisplayName = "The window SLIDES — failures older than the window do not count")]
    public void Window_Slides()
    {
        var (limiter, clock) = Build();
        Fail(limiter, 4);
        clock.Advance(TimeSpan.FromMinutes(16)); // all four age out of the 15-minute window
        Fail(limiter, 4);
        Assert.True(limiter.CheckAttempt(User, Source).IsAllowed);
    }

    [Fact(DisplayName = "The lockout releases after its duration and attempts are admitted again")]
    public void Lockout_Releases_AfterDuration()
    {
        var (limiter, clock) = Build();
        Fail(limiter, 5);
        Assert.False(limiter.CheckAttempt(User, Source).IsAllowed);
        clock.Advance(TimeSpan.FromMinutes(1) + TimeSpan.FromSeconds(1));
        Assert.True(limiter.CheckAttempt(User, Source).IsAllowed);
    }

    [Fact(DisplayName = "Consecutive lockouts back off exponentially, capped at the maximum")]
    public void ConsecutiveLockouts_BackOffExponentially()
    {
        var (limiter, clock) = Build(new NodeWebLoginLockoutOptions
        {
            MaxFailures = 2,
            Window = TimeSpan.FromMinutes(15),
            BaseLockoutDuration = TimeSpan.FromMinutes(1),
            MaxLockoutDuration = TimeSpan.FromMinutes(3),
        });

        Fail(limiter, 2); // lockout #1 — 1 min
        var first = limiter.CheckAttempt(User, Source);
        Assert.False(first.IsAllowed);
        Assert.True(first.RetryAfter <= TimeSpan.FromMinutes(1));

        clock.Advance(TimeSpan.FromMinutes(1) + TimeSpan.FromSeconds(1));
        Fail(limiter, 2); // lockout #2 — 2 min
        var second = limiter.CheckAttempt(User, Source);
        Assert.False(second.IsAllowed);
        Assert.True(second.RetryAfter > TimeSpan.FromMinutes(1));
        Assert.True(second.RetryAfter <= TimeSpan.FromMinutes(2));

        clock.Advance(TimeSpan.FromMinutes(2) + TimeSpan.FromSeconds(1));
        Fail(limiter, 2); // lockout #3 — capped at 3 min (not 4)
        var third = limiter.CheckAttempt(User, Source);
        Assert.False(third.IsAllowed);
        Assert.True(third.RetryAfter <= TimeSpan.FromMinutes(3));
        Assert.True(third.RetryAfter > TimeSpan.FromMinutes(2));
    }

    [Fact(DisplayName = "A successful login RESETS the pair — counters and backoff forgotten")]
    public void Success_Resets()
    {
        var (limiter, clock) = Build();
        Fail(limiter, 4);
        limiter.RecordSuccess(User, Source);
        Fail(limiter, 4); // a fresh window — 4 more failures do not engage
        Assert.True(limiter.CheckAttempt(User, Source).IsAllowed);

        // And the backoff escalation is forgotten too: engage once, release, succeed, re-engage —
        // the new lockout is the BASE duration again, not the doubled one.
        limiter.RecordFailure(User, Source); // 5th → lockout #1
        clock.Advance(TimeSpan.FromMinutes(1) + TimeSpan.FromSeconds(1));
        Assert.True(limiter.CheckAttempt(User, Source).IsAllowed);
        limiter.RecordSuccess(User, Source);
        Fail(limiter, 5);
        var relocked = limiter.CheckAttempt(User, Source);
        Assert.False(relocked.IsAllowed);
        Assert.True(relocked.RetryAfter <= TimeSpan.FromMinutes(1));
    }

    [Fact(DisplayName = "Keys are per (username, source): a different user or source is unaffected")]
    public void Keys_AreIndependent()
    {
        var (limiter, _) = Build();
        Fail(limiter, 5);
        Assert.False(limiter.CheckAttempt(User, Source).IsAllowed);
        Assert.True(limiter.CheckAttempt("someone-else", Source).IsAllowed);
        Assert.True(limiter.CheckAttempt(User, "198.51.100.7").IsAllowed);
        Assert.True(limiter.CheckAttempt(null, Source).IsAllowed);
    }

    [Fact(DisplayName = "One account cannot obtain a second budget through case or whitespace variants")]
    public void KeyVariants_ShareOneBudget()
    {
        var (limiter, _) = Build();
        Fail(limiter, 5);
        Assert.False(limiter.CheckAttempt(User, Source).IsAllowed);
        Assert.False(limiter.CheckAttempt("FOUNDER", Source).IsAllowed);
        Assert.False(limiter.CheckAttempt(" founder ", Source).IsAllowed);
    }

    [Fact(DisplayName = "Distinct long usernames do not collide through key hashing")]
    public void LongUsernames_DoNotCollide()
    {
        var (limiter, _) = Build();
        var sharedPrefix = new string('u', 256);
        var first = sharedPrefix + "-alice";
        var second = sharedPrefix + "-bob";

        Fail(limiter, 5, user: first);
        Assert.False(limiter.CheckAttempt(first, Source).IsAllowed);
        Assert.True(limiter.CheckAttempt(second, Source).IsAllowed);
    }

    [Fact(DisplayName = "A full tracking table evicts the least-recently-active unprotected key")]
    public void FullTable_EvictsLeastRecentlyActiveKey()
    {
        var (limiter, _) = Build(new NodeWebLoginLockoutOptions { MaxTrackedKeys = 2 });
        limiter.RecordFailure("a", Source);
        limiter.RecordFailure("b", Source);
        Assert.True(limiter.CheckAttempt("c", Source).IsAllowed);
    }

    [Fact(DisplayName = "A full tracking table refuses a new key when every entry is locked")]
    public void FullTable_RefusesNewKeys_WhenEveryEntryIsLocked()
    {
        var (limiter, _) = Build(new NodeWebLoginLockoutOptions { MaxTrackedKeys = 2 });
        Fail(limiter, 5, user: "a");
        Fail(limiter, 5, user: "b");

        Assert.False(limiter.CheckAttempt("c", Source).IsAllowed);
    }

    [Fact(DisplayName = "Stale entries are pruned so a full table recovers once windows age out")]
    public void FullTable_Recovers_AfterPrune()
    {
        var (limiter, clock) = Build(new NodeWebLoginLockoutOptions
        {
            MaxTrackedKeys = 2,
            MaxFailures = 1,
        });
        Fail(limiter, 1, user: "a");
        Fail(limiter, 1, user: "b");
        Assert.False(limiter.CheckAttempt("c", Source).IsAllowed);
        clock.Advance(TimeSpan.FromMinutes(16)); // both lockouts and windows have expired
        Assert.True(limiter.CheckAttempt("c", Source).IsAllowed);
        limiter.RecordFailure("c", Source);
        Assert.False(limiter.CheckAttempt("c", Source).IsAllowed);
    }

    [Fact(DisplayName = "Concurrent failures never under-count: parallel hammering engages the lockout")]
    public async Task Concurrency_EngagesLockout()
    {
        var (limiter, _) = Build();
        var admitted = 0;
        await Task.WhenAll(Enumerable.Range(0, 8).Select(_ => Task.Run(() =>
        {
            for (var i = 0; i < 25; i++)
            {
                if (limiter.CheckAttempt(User, Source).IsAllowed)
                {
                    Interlocked.Increment(ref admitted);
                    limiter.RecordFailure(User, Source);
                }
            }
        })));
        Assert.InRange(admitted, 1, 5);
        Assert.False(limiter.CheckAttempt(User, Source).IsAllowed);
    }

    [Fact(DisplayName = "Concurrent traffic across many keys stays internally consistent (no torn state)")]
    public async Task Concurrency_ManyKeys_NoTornState()
    {
        var (limiter, _) = Build();
        await Task.WhenAll(Enumerable.Range(0, 8).Select(worker => Task.Run(() =>
        {
            for (var i = 0; i < 50; i++)
            {
                var user = $"user-{worker % 4}";
                limiter.CheckAttempt(user, Source);
                limiter.RecordFailure(user, Source);
                if (i % 7 == 0)
                {
                    limiter.RecordSuccess(user, Source);
                }
            }
        })));
        // The property under test is that nothing threw and the limiter still answers coherently.
        Assert.True(limiter.CheckAttempt("fresh-user", Source).IsAllowed);
    }

    [Fact(DisplayName = "Nonsense configuration hardens rather than disables (threshold clamps to 1)")]
    public void NonsenseConfig_Hardens()
    {
        var (limiter, _) = Build(new NodeWebLoginLockoutOptions
        {
            MaxFailures = 0,
            Window = TimeSpan.Zero,
            BaseLockoutDuration = TimeSpan.Zero,
        });
        Assert.True(limiter.CheckAttempt(User, Source).IsAllowed);
        limiter.RecordFailure(User, Source);
        Assert.False(limiter.CheckAttempt(User, Source).IsAllowed);
    }

    [Fact(DisplayName = "Extreme duration configuration cannot overflow the limiter clock arithmetic")]
    public void ExtremeDurations_Harden()
    {
        var (limiter, _) = Build(new NodeWebLoginLockoutOptions
        {
            Window = TimeSpan.MaxValue,
            BaseLockoutDuration = TimeSpan.MaxValue,
            MaxLockoutDuration = TimeSpan.MaxValue,
        });

        Assert.True(limiter.CheckAttempt(User, Source).IsAllowed);
        limiter.RecordFailure(User, Source);
        Assert.True(limiter.CheckAttempt(User, Source).IsAllowed);
    }

    [Fact(DisplayName = "A limiter error poisons the gate so recovery cannot become fail-open")]
    public void LimiterError_PoisonsGate_FailClosed()
    {
        var (limiter, clock) = Build();
        clock.ThrowOnRead = true;

        Assert.False(limiter.CheckAttempt(User, Source).IsAllowed);

        // The dependency recovers, but the limiter does not silently reopen with unknown state.
        clock.ThrowOnRead = false;
        Assert.False(limiter.CheckAttempt(User, Source).IsAllowed);
    }

    [Fact(DisplayName = "A throwing logger cannot fault-close the limiter during audit emission")]
    public void LoggerFailure_DoesNotFaultClose()
    {
        var (limiter, clock) = Build(
            new NodeWebLoginLockoutOptions
            {
                MaxFailures = 1,
                BaseLockoutDuration = TimeSpan.FromMinutes(1),
                MaxLockoutDuration = TimeSpan.FromMinutes(1),
            },
            new ThrowingLogger());

        Fail(limiter, 1);
        Assert.False(limiter.CheckAttempt(User, Source).IsAllowed);

        clock.Advance(TimeSpan.FromMinutes(1) + TimeSpan.FromSeconds(1));
        // Both the engage and release audit calls throw; the state decision remains usable.
        Assert.True(limiter.CheckAttempt(User, Source).IsAllowed);
    }

    [Fact(DisplayName = "An abandoned reservation can be released without changing completed failures")]
    public void AbandonedReservation_Releases_OnlyPendingSlot()
    {
        var (limiter, _) = Build(new NodeWebLoginLockoutOptions { MaxFailures = 2 });

        Assert.True(limiter.CheckAttempt(User, Source).IsAllowed);
        limiter.RecordFailure(User, Source);

        // This reservation is abandoned and must not erase the completed failure above.
        Assert.True(limiter.CheckAttempt(User, Source).IsAllowed);
        limiter.ReleaseAttempt(User, Source);

        // The completed failure still occupies one of the two slots: this next failure crosses the
        // threshold, proving ReleaseAttempt removed only the pending reservation.
        Assert.True(limiter.CheckAttempt(User, Source).IsAllowed);
        limiter.RecordFailure(User, Source);
        Assert.False(limiter.CheckAttempt(User, Source).IsAllowed);
    }
}

