/// <summary>
/// The comms family is DESKTOP-PLANE ONLY (card earlier repository ticket #3383).
/// </summary>
/// <remarks>
/// <para>
/// <b>The deputy this closes.</b> <see cref="HostedCommsApiEndpoint"/> resolves the active member party ONCE
/// at startup and stamps it as the AUTHOR of every appended message. The per-route
/// <c>callerAuth.Validate</c> reads like the guard that would stop a web caller and is not one — it returns
/// <c>Allow</c> on the listener's gate-passed marker, which every selected-session request carries. So a
/// signed-in MEMBER's message was authored as the OPERATOR's roster party, signed with the node key, and
/// merged into a CRDT that peers accept.
/// </para>
/// <para>
/// The propagation is the harm, and it is why this is fenced rather than logged: a CRDT merge has no notion
/// of retracting a provenance claim, so the wrong author becomes a signed fact on every peer that syncs.
/// </para>
/// <para>
/// <b>These assert on the DURABLE RECORD, not the status code</b> (FLEET-0007). A refused POST that still
/// wrote a message would satisfy any status assertion; what has to be true is that nothing was signed and
/// nothing was merged. The log is read back through a desktop-plane GET, which reaches the EF read model
/// rather than the CRDT delta stream a peer actually syncs — a sound PROXY for "nothing was merged", not
/// the peer path itself: the append handler writes EF first and appends to the CRDT second, so an empty EF
/// log entails no local CRDT append.
/// </para>
/// <para>
/// This is the PLANE half. Card earlier repository ticket #3379 converts <c>CommsRoutes</c>'s fallback author to the acting
/// member — the ATTRIBUTION half, on a different file.
/// </para>
/// </remarks>
public sealed class CommsWebPlaneFenceTests : IAsyncLifetime
{
    private const string CallerToken = "comms-web-plane-fence-caller-token-0001";
    private const string MemberHandle = "handle-member-with-at-least-256-bits-of-comms-entropy-000000";
    private const string OperatorParty = "os:comms-fence-operator";
    private static readonly Guid Team = NodeTestActiveTeam.TestTeamId.Value;
    private static readonly IOperationVerifier Verifier = new Ed25519Verifier();

    private readonly List<string> _dirs = new();
    private readonly List<IAsyncDisposable> _async = new();
    private readonly List<ServiceProvider> _providers = new();
    private readonly List<SharedHostedWebApp> _apps = new();
    private readonly List<HttpClient> _clients = new();
    private readonly List<IDisposable> _disposables = new();

    public Task InitializeAsync() => Task.CompletedTask;

    public async Task DisposeAsync()
    {
        foreach (var c in _clients) c.Dispose();
        foreach (var a in _apps) { await a.StopAsync(CancellationToken.None); await a.DisposeAsync(); }
        foreach (var d in _async) await d.DisposeAsync();
        foreach (var p in _providers) await p.DisposeAsync();
        foreach (var d in _disposables) d.Dispose();
        foreach (var dir in _dirs)
            try { if (Directory.Exists(dir)) Directory.Delete(dir, recursive: true); } catch { /* best-effort */ }
    }

    [Fact]
    public async Task A_members_message_is_never_signed_or_merged()
    {
        var client = await StartAsync();

        var refused = await SendAsMemberAsync(client, NewPostRequest("a message the member should not be able to send"));

        Assert.Equal(HttpStatusCode.Forbidden, refused.StatusCode);
        using (var body = JsonDocument.Parse(await refused.Content.ReadAsStringAsync()))
        {
            Assert.Equal(
                WebPlaneUnavailableRouteFence.UnavailableCode,
                body.RootElement.GetProperty("code").GetString());
        }

        // THE assertion. Read the durable log back through the desktop plane. The append handler writes EF
        // before the CRDT, so an empty read model entails nothing was merged either. Before the fence this
        // held one message whose author was OperatorParty.
        var log = await ReadLogAsDesktopOperatorAsync(client);
        Assert.Empty(log);
    }

    [Fact]
    public async Task A_member_cannot_read_the_teams_log_either()
    {
        // The gated GET this consumer owes on its own account, rather than trusting another card's fence test
        // on a different route family. A GET here returns the whole team channel — a read scope the member
        // does not have under MTW-2.
        var client = await StartAsync();

        // Seed one real message from the desktop plane so an empty log cannot pass for a refusal.
        var seeded = await SendAsDesktopOperatorAsync(client, NewPostRequest("desktop message"));
        Assert.Equal(HttpStatusCode.Created, seeded.StatusCode);

        var refused = await SendAsMemberAsync(
            client, new HttpRequestMessage(HttpMethod.Get, CommsRoutes.RouteBase));

        Assert.Equal(HttpStatusCode.Forbidden, refused.StatusCode);
        using var body = JsonDocument.Parse(await refused.Content.ReadAsStringAsync());
        Assert.Equal(
            WebPlaneUnavailableRouteFence.UnavailableCode,
            body.RootElement.GetProperty("code").GetString());
    }

    [Fact]
    public async Task A_member_cannot_reach_the_dm_routes()
    {
        // The DM routes are mapped only when the DM feature flag is on, which is the PRODUCTION default —
        // the flag is a kill-switch (HARBORLINE_COMMS_DM_DISABLED), not an opt-in. A harness that disabled it
        // would leave the sealed-message half of the family driven by nothing, which is the same harm class
        // the card is about.
        var client = await StartAsync();

        var refused = await SendAsMemberAsync(
            client, new HttpRequestMessage(HttpMethod.Get, $"{CommsRoutes.RouteBase}/dm/roster"));

        Assert.Equal(HttpStatusCode.Forbidden, refused.StatusCode);
        using var body = JsonDocument.Parse(await refused.Content.ReadAsStringAsync());
        Assert.Equal(
            WebPlaneUnavailableRouteFence.UnavailableCode,
            body.RootElement.GetProperty("code").GetString());
    }

    [Fact]
    public async Task The_desktop_operator_still_sends_and_reads_as_the_roster_bound_member()
    {
        // THE control, and it is doing two jobs. A change that refused both planes would satisfy every
        // assertion above while making messaging impossible — so the desktop post must still land. And the
        // author it lands under must still be the roster-bound active member, or the fence would be masking
        // a regression in the very capture it exists to contain.
        var client = await StartAsync();

        var created = await SendAsDesktopOperatorAsync(client, NewPostRequest("hello from the desktop"));
        Assert.Equal(HttpStatusCode.Created, created.StatusCode);

        var log = await ReadLogAsDesktopOperatorAsync(client);
        var message = Assert.Single(log);
        Assert.Equal(OperatorParty, message.GetProperty("authorPartyId").GetString());
        Assert.Equal("hello from the desktop", message.GetProperty("body").GetString());
    }

    private static HttpRequestMessage NewPostRequest(string body) =>
        new(HttpMethod.Post, CommsRoutes.RouteBase) { Content = JsonContent.Create(new { body }) };

    /// <summary>Drives the request the way the Harborline App's web plane does — a selected-session cookie only.</summary>
    private static Task<HttpResponseMessage> SendAsMemberAsync(HttpClient client, HttpRequestMessage request)
    {
        request.Headers.Add("Cookie", $"{WebSessionCookieNames.Selected}={MemberHandle}");
        return client.SendAsync(request);
    }

    private static Task<HttpResponseMessage> SendAsDesktopOperatorAsync(HttpClient client, HttpRequestMessage request)
    {
        request.Headers.Add(NodeCallerSessionToken.HeaderName, "Bearer " + CallerToken);
        return client.SendAsync(request);
    }

    private static async Task<List<JsonElement>> ReadLogAsDesktopOperatorAsync(HttpClient client)
    {
        var response = await SendAsDesktopOperatorAsync(
            client, new HttpRequestMessage(HttpMethod.Get, CommsRoutes.RouteBase));
        Assert.Equal(HttpStatusCode.OK, response.StatusCode);

        using var doc = JsonDocument.Parse(await response.Content.ReadAsStringAsync());
        return doc.RootElement.GetProperty("messages").EnumerateArray().Select(e => e.Clone()).ToList();
    }

    /// <summary>
    /// A real listener serving the REAL <see cref="HostedCommsApiEndpoint"/>, driven through its own
    /// <c>StartAsync</c> so the startup capture and the fence installation are the production ones, over a
    /// REAL SQLite-backed <see cref="CommsConversationRegistry"/> so an appended message is genuinely durable.
    /// </summary>
    private async Task<HttpClient> StartAsync()
    {
        var signer = new NodePrincipalSigner(Seed(0x3b));
        _disposables.Add(signer);

        // The roster binds the operator party to THIS signer's key — the consistency the endpoint asserts
        // before mapping, and what makes the desktop control's author assertion meaningful.
        var roster = new NodeTeamRoster(MemberRoster.Genesis(
            Team, OperatorParty, signer.Signer, Verifier, DateTimeOffset.UtcNow, Guid.NewGuid()));

        var dir = Path.Combine(Path.GetTempPath(), $"harborline-comms-fence-{Guid.NewGuid():N}");
        Directory.CreateDirectory(dir);
        _dirs.Add(dir);

        var services = new ServiceCollection();
        services.AddTestKernelClock();
        services.AddLogging(b => b.ClearProviders());
        services.AddDbContextFactory<NodeLocalCommsDbContext>(opt =>
            opt.UseSqlite($"Data Source={Path.Combine(dir, "comms.db")};Pooling=False"));
        services.AddSingleton<ICrdtEngine, YDotNetCrdtEngine>();
        services.AddSingleton<IActiveTeamAccessor>(NodeTestActiveTeam.Accessor);
        services.AddSingleton(new NodeCallerSessionToken(CallerToken));
        services.AddSingleton<IWebSelectedSessionPrincipalAuthority>(new FixedSelectedSessionAuthority());
        services.AddHarborlineDeltaRouter();
        var sp = services.BuildServiceProvider();
        _providers.Add(sp);

        var factory = sp.GetRequiredService<IDbContextFactory<NodeLocalCommsDbContext>>();
        await using (var ctx = await factory.CreateDbContextAsync())
            await ctx.Database.EnsureCreatedAsync();

        var registry = new CommsConversationRegistry(
            sp.GetRequiredService<ICrdtEngine>(), factory, new Ed25519Verifier(),
            sp.GetRequiredService<IDeltaRouter>(), sp.GetRequiredService<ILoggerFactory>(),
            rosterBinding: roster.ForgeProofBinding);
        _async.Add(registry);

        var app = new SharedHostedWebApp(
            sp,
            Options.Create(new LocalNodeOptions { HealthPort = 0 }),
            new Harborline.Api.LocalNodeHost.Capabilities.LocalNodeExecutableEndpointRegistry(),
            sp.GetRequiredService<ILogger<SharedHostedWebApp>>(),
            sp.GetRequiredService<TimeProvider>());
        _apps.Add(app);

        // The REAL hosted endpoint. Its StartAsync performs the startup capture AND installs the fence in the
        // same call, so a change that separates them is visible here.
        var endpoint = new HostedCommsApiEndpoint(
            app, registry, signer, NodeTestActiveTeam.Accessor, sp.GetRequiredService<NodeCallerSessionToken>(),
            roster, new CommsDmFeatureFlag(), sp.GetRequiredService<TimeProvider>(),
            NullLogger<HostedCommsApiEndpoint>.Instance);
        await endpoint.StartAsync(CancellationToken.None);

        await app.StartAsync(CancellationToken.None);
        var client = new HttpClient { BaseAddress = new Uri(app.SelectedUrl!) };
        _clients.Add(client);
        return client;
    }

    private static byte[] Seed(byte fill)
    {
        var seed = new byte[32];
        Array.Fill(seed, fill);
        return seed;
    }

    /// <summary>
    /// Materializes ONE real <see cref="SelectedSessionRequestPrincipal"/> for the known handle — the only
    /// substituted seam, and it stands UPSTREAM of the route family under test. Its presence is what makes the
    /// listener open the attribution scope the fence reads, and what sets the gate-passed marker that
    /// <c>callerAuth.Validate</c> answers <c>Allow</c> to.
    /// </summary>
    private sealed class FixedSelectedSessionAuthority : IWebSelectedSessionPrincipalAuthority
    {
        public Task<SelectedSessionRequestPrincipal?> AuthenticateAsync(
            string? selectedHandle,
            CancellationToken cancellationToken = default) =>
            Task.FromResult(string.Equals(selectedHandle, MemberHandle, StringComparison.Ordinal)
                ? new SelectedSessionRequestPrincipal(
                    accountId: "account-comms-fence",
                    tenantId: new TenantId(Team.ToString("D")),
                    principalUserId: new PrincipalUserId("principal-comms-fence"),
                    canonicalParty: new CanonicalPartyReference("party-member-comms-fence"),
                    membershipId: "membership-comms-fence",
                    membershipOwnerVersion: 2,
                    pinnedGrantOwnerVersions: [new PinnedGrantOwnerVersion("grant-comms-fence", 3)],
                    authorizationEpoch: 5,
                    sessionCorrelationId: "session-comms-fence",
                    coordinationCorrelationId: "coordination-comms-fence")
                : null);
    }
}

using System;
using System.Net;
using System.Net.Http.Json;

using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Options;

using Harborline.Api.Foundation.Assets.Common;
using Harborline.Api.Foundation.Authorization;
using Harborline.Api.Foundation.Crypto;
using Harborline.Api.Foundation.IdentityAtlas;
using Harborline.Api.Foundation.IdentityAtlas.Enrollment;
using Harborline.Api.Kernel.Runtime.Teams;
using Harborline.Api.LocalNodeHost.Data.Identity;
using Harborline.Api.LocalNodeHost.Enrollment;
using Harborline.Api.LocalNodeHost.Health;
using Harborline.Api.LocalNodeHost.Health.WebSession;

using Xunit;

namespace Harborline.Api.LocalNodeHost.Tests.Identity;

/// <summary>
/// MTW-2 #3167 (adversarial verdict M1) — the connect-device mint route must NOT let an authenticated session mint
/// a years-long single-use bearer token. <see cref="ConnectDeviceRoutes.ClampMintTtl"/> bounds the caller-supplied
/// TTL to a short ceiling (absent / non-positive / non-finite → the short default; over-ceiling → the ceiling,
/// minted not refused), so <c>AdmissionToken.Mint</c> — which enforces only <c>&gt; 0</c> — can never receive an
/// attacker-chosen span. M2 additionally exercises the mapped endpoint over the real listener and proves a durable
/// binding fault collapses to the route's opaque refusal instead of escaping as a 500.
/// </summary>
public sealed class ConnectDeviceRoutesTests
{
    [Theory(DisplayName = "connect-device: caller TTL is clamped to [default, max] — no unbounded bearer lifetime (M1)")]
    [InlineData(null, 15.0)]      // absent → short default
    [InlineData(5.0, 5.0)]        // in-range → honored
    [InlineData(60.0, 60.0)]      // exactly the ceiling → honored
    [InlineData(600.0, 60.0)]     // over-ceiling (years) → CLAMPED to the ceiling (mints, does not refuse)
    [InlineData(0.0, 15.0)]       // non-positive → default
    [InlineData(-30.0, 15.0)]     // negative → default
    public void ClampMintTtl_Bounds_The_Caller_Supplied_Lifetime(double? requestedMinutes, double expectedMinutes)
    {
        Assert.Equal(TimeSpan.FromMinutes(expectedMinutes), ConnectDeviceRoutes.ClampMintTtl(requestedMinutes));
    }

    [Theory(DisplayName = "connect-device: a non-finite TTL (NaN / ±infinity) falls back to the default, never TimeSpan.FromMinutes(NaN)")]
    [InlineData(double.NaN)]
    [InlineData(double.PositiveInfinity)]
    [InlineData(double.NegativeInfinity)]
    public void ClampMintTtl_Rejects_NonFinite(double requestedMinutes)
    {
        Assert.Equal(
            TimeSpan.FromMinutes(ConnectDeviceRoutes.DefaultTtlMinutes),
            ConnectDeviceRoutes.ClampMintTtl(requestedMinutes));
    }

    [Fact(DisplayName = "connect-device: the real HTTP route mints a bounded token for an authenticated session")]
    public async Task Real_Http_Route_Mints_For_The_Authenticated_Principal()
    {
        await using var h = await RouteHarness.StartAsync(new InMemoryWebPairingInviteBindingStore());

        var response = await h.PostAsync(new { ttlMinutes = 600.0 });

        Assert.Equal(HttpStatusCode.OK, response.StatusCode);
        var body = await response.Content.ReadAsStringAsync();
        Assert.Contains("\"tokenId\":", body, StringComparison.Ordinal);
        Assert.Contains("\"joiningPartyId\":\"party-1\"", body, StringComparison.Ordinal);
        Assert.Contains("\"expiresAt\":", body, StringComparison.Ordinal);
        Assert.Equal("no-store", response.Headers.CacheControl?.ToString());
    }

    [Fact(DisplayName = "connect-device: a durable Bind fault through the real HTTP route is an opaque refusal, never 500 (M2)")]
    public async Task Real_Http_Route_Contains_Binding_Store_Fault()
    {
        await using var h = await RouteHarness.StartAsync(new ThrowingBindingStore());

        var response = await h.PostAsync(new { ttlMinutes = double.MaxValue });

        Assert.Equal(HttpStatusCode.Unauthorized, response.StatusCode);
        Assert.Equal(
            "{\"error\":\"connect_device_failed\",\"message\":\"Device pairing could not be started.\"}",
            await response.Content.ReadAsStringAsync());
        Assert.Equal("no-store", response.Headers.CacheControl?.ToString());

        // earlier repository ticket #3311 — this refusal spent the single-use token, so it must hand back a fresh one.
        // Nothing else in the pipeline stamps this header, so its presence here is the re-issue and
        // nothing else: deleting that one line turns this red.
        Assert.True(
            response.Headers.TryGetValues(WebAntiforgeryPolicy.HeaderName, out var replacement),
            "the refusal carried NO antiforgery header");
        Assert.Equal("replacement-token", replacement!.Single());
    }

    private sealed class ThrowingBindingStore : IWebPairingInviteBindingStore
    {
        public void Bind(WebPairingInviteBinding binding) =>
            throw new InvalidOperationException("induced pairing binding fault");

        public WebPairingInviteBinding? Lookup(string tokenId) => null;
    }

    private sealed class RouteHarness : IAsyncDisposable
    {
        private const string BootstrapToken = "connect-device-test-bootstrap-token";
        private const string SelectedHandle = "selected-route-test";

        private readonly ServiceProvider _outer;
        private readonly SharedHostedWebApp _app;
        private readonly HttpClient _client;

        private RouteHarness(ServiceProvider outer, SharedHostedWebApp app, HttpClient client)
        {
            _outer = outer;
            _app = app;
            _client = client;
        }

        internal static async Task<RouteHarness> StartAsync(IWebPairingInviteBindingStore bindings)
        {
            var key = KeyPair.Generate();
            var signer = new Ed25519Signer(key);
            var verifier = new Ed25519Verifier();
            var team = Guid.Parse("7e57aaaa-0000-0000-0000-00000000000c");
            var roster = new NodeTeamRoster(MemberRoster.Genesis(
                team, "founder", signer, verifier, DateTimeOffset.UtcNow, Guid.NewGuid()));
            var mint = new WebAdmittedMemberPairingTokenMint(
                new AdmissionCoordinator(verifier, new InMemoryAdmissionTokenStore(), clock: TimeProvider.System),
                bindings);

            var services = new ServiceCollection();
            services.AddLogging();
            services.AddTestKernelClock();
            services.AddSingleton<IActiveTeamAccessor>(new NoActiveTeamAccessor());
            services.AddSingleton(new NodeCallerSessionToken(BootstrapToken));
            var outer = services.BuildServiceProvider();
            var app = new SharedHostedWebApp(
                outer,
                Options.Create(new LocalNodeOptions { HealthPort = 0 }),
                new Harborline.Api.LocalNodeHost.Capabilities.LocalNodeExecutableEndpointRegistry(),
                outer.GetRequiredService<Microsoft.Extensions.Logging.ILogger<SharedHostedWebApp>>(),
                outer.GetRequiredService<TimeProvider>());
            app.MapApiRoutes(routes =>
            {
                routes.Use(async (context, next) =>
                {
                    context.Features.Set(Principal());
                    await next(context);
                });
                ConnectDeviceRoutes.Map(
                    routes.MapSelectedSessionProductGroup(),
                    mint,
                    roster,
                    new AcceptingAntiforgeryPolicy());
            });
            await app.StartAsync(CancellationToken.None);
            var client = new HttpClient
            {
                BaseAddress = new Uri(app.SelectedUrl!),
                Timeout = TimeSpan.FromSeconds(10),
            };
            return new RouteHarness(outer, app, client);
        }

        internal Task<HttpResponseMessage> PostAsync(object body)
        {
            var request = new HttpRequestMessage(HttpMethod.Post, ConnectDeviceRoutes.ConnectPath)
            {
                Content = JsonContent.Create(body),
            };
            request.Headers.Authorization =
                new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", BootstrapToken);
            request.Headers.Add("Cookie", $"__Host-hl-selected={SelectedHandle}");
            return _client.SendAsync(request);
        }

        public async ValueTask DisposeAsync()
        {
            _client.Dispose();
            await _app.StopAsync(CancellationToken.None);
            await _app.DisposeAsync();
            await _outer.DisposeAsync();
        }

        private static SelectedSessionRequestPrincipal Principal() =>
            new(
                "account-1",
                new TenantId("tenant-1"),
                new PrincipalUserId("principal-1"),
                new CanonicalPartyReference("party-1"),
                "membership-1",
                3,
                [new PinnedGrantOwnerVersion("grant-1", 4)],
                7,
                "session-1",
                "coordination-1");
    }

    private sealed class NoActiveTeamAccessor : IActiveTeamAccessor
    {
        public TeamContext? Active => null;
        public Task SetActiveAsync(TeamId teamId, CancellationToken ct) => Task.CompletedTask;
        public event EventHandler<ActiveTeamChangedEventArgs>? ActiveChanged { add { } remove { } }
    }

    private sealed class AcceptingAntiforgeryPolicy : IWebAntiforgeryPolicy
    {
        public Task<bool> IssueAnonymousAsync(HttpContext context) => Task.FromResult(true);
        public Task<bool> ConsumeAnonymousAsync(HttpContext context) => Task.FromResult(true);
        public Task<bool> ConsumeChallengeAsync(HttpContext context, string challengeHandle) => Task.FromResult(true);
        public Task<bool> ConsumeSelectedAsync(HttpContext context, string selectedHandle) => Task.FromResult(true);
        public Task<bool> ConsumeInstallationAsync(HttpContext context, string installationHandle) =>
            Task.FromResult(true);
        public Task<bool> RotateChallengeAsync(HttpContext context, string challengeHandle) => Task.FromResult(true);
        // Declared on IWebAntiforgeryPolicy before this branch's merge base, and already called by
        // ConnectDeviceRoutes. Omitting it was a CS0535 that failed the WHOLE test project, so none of
        // this branch's new tests had ever run.
        public Task<bool> RotateSelectedAsync(HttpContext context, string selectedHandle)
        {
            // The REAL policy emits the header from inside RotateAudienceAsync. A double that returns
            // true without emitting lets a test pass on a response the server never sends (ADR 0130
            // anti-pattern A1) — and the header is the point: it is what the browser sends next.
            EmitToken(context.Response, "replacement-token");
            return Task.FromResult(true);
        }
        public void EmitToken(HttpResponse response, string token) =>
            response.Headers[WebAntiforgeryPolicy.HeaderName] = token;
        public void ExpireAnonymousBinding(HttpResponse response) { }
    }
}

using Microsoft.EntityFrameworkCore;

using Harborline.Api.LocalNodeHost.Data.Identity;

namespace Harborline.Api.LocalNodeHost.Tests.Identity;

/// <summary>
/// Drives a REAL <see cref="InstallationIdentityCutoverOrchestrator"/> all the way to a committed v2
/// authority marker over a caller-supplied installation identity store.
/// </summary>
/// <remarks>
/// Shared so a production accept path can be proved against genuine post-cutover state rather than a
/// stubbed gate: the caller keeps its own real authority (challenge issuer, tenant selection, …)
/// bound to the same orchestrator, and every step below is asserted, so a proof that fails to reach
/// <c>V2Authoritative</c> says which stage refused instead of silently testing the pre-cutover state.
/// The store must already carry a bootstrapped founder — the marker CAS re-verifies the initial
/// installation-root designation and refuses with <c>identity_install_root_unresolved</c> without it.
/// </remarks>
internal static class CutoverAdvance
{
    private const string MigrationRunId = "mtw-3245-accept-path-run";
    private const string WatermarkDigest = "mtw-3245-watermark-digest";
    private const string VerificationDigest = "mtw-3245-verification-digest";

    /// <summary>Seeds the source watermark, then leases and advances through to the committed marker.</summary>
    internal static async Task CommitV2MarkerAsync(
        IDbContextFactory<NodeLocalInstallationIdentityDbContext> identityFactory,
        InstallationIdentityCutoverOrchestrator orchestrator,
        DateTimeOffset now)
    {
        ArgumentNullException.ThrowIfNull(identityFactory);
        ArgumentNullException.ThrowIfNull(orchestrator);

        await SeedSourceWatermarkAsync(identityFactory, now).ConfigureAwait(false);

        var acquired = await orchestrator
            .AcquireLeaseAsync("mtw-3245-coordinator", TimeSpan.FromHours(1))
            .ConfigureAwait(false);
        Require(
            acquired.Status == InstallationIdentityLeaseAcquireStatus.Acquired && acquired.Lease is not null,
            $"the migration lease could not be acquired ('{acquired.Status}').");
        var lease = acquired.Lease!;

        foreach (var stage in new[]
        {
            InstallationIdentityCutoverStage.WriteBarrierActive,
            InstallationIdentityCutoverStage.Copying,
            InstallationIdentityCutoverStage.Verified,
        })
        {
            var advanced = await orchestrator.AdvanceAsync(lease, stage, Evidence()).ConfigureAwait(false);
            Require(
                advanced.Status == InstallationIdentityCutoverAdvanceStatus.Advanced,
                $"the cutover could not advance to '{stage}' ('{advanced.RefusalCode}').");
        }

        var staged = await orchestrator
            .StageLegacyBearerRevocationsAsync(lease, Enum.GetValues<InstallationIdentityLegacyBearerAudience>())
            .ConfigureAwait(false);
        Require(
            staged.Status is InstallationIdentityLegacyBearerRevocationStatus.Staged
                or InstallationIdentityLegacyBearerRevocationStatus.AlreadyStaged,
            $"the legacy bearer revocation evidence was not staged ('{staged.Status}' / '{staged.RefusalCode}').");

        var committed = await orchestrator
            .AdvanceAsync(lease, InstallationIdentityCutoverStage.V2Authoritative, Evidence())
            .ConfigureAwait(false);
        Require(
            committed.Status == InstallationIdentityCutoverAdvanceStatus.Advanced,
            $"the v2 authority marker did not commit ('{committed.RefusalCode}').");

        var authority = await orchestrator.ResolveAuthorityAsync().ConfigureAwait(false);
        Require(
            authority.Stage == InstallationIdentityCutoverStage.V2Authoritative &&
                authority.Authority == InstallationIdentityAuthorityKind.Revision3V2,
            $"the store did not settle on the v2 authority ('{authority.Stage}' / '{authority.Authority}').");
    }

    private static async Task SeedSourceWatermarkAsync(
        IDbContextFactory<NodeLocalInstallationIdentityDbContext> identityFactory,
        DateTimeOffset now)
    {
        await using var context = await identityFactory.CreateDbContextAsync().ConfigureAwait(false);
        context.MigrationSourceWatermarks.Add(new InstallationIdentityMigrationSourceWatermarkRecord
        {
            SourceKind = "legacy-installation-account",
            SourcePartition = "singleton",
            MigrationRunId = MigrationRunId,
            SourceVersion = 7,
            HighWatermark = "7",
            SnapshotDigest = WatermarkDigest,
            OwnerVersion = 1,
            CapturedAtUtc = now,
        });
        await context.SaveChangesAsync().ConfigureAwait(false);
    }

    private static InstallationIdentityCutoverEvidence Evidence() =>
        new(MigrationRunId, WatermarkDigest, VerificationDigest);

    private static void Require(bool condition, string message)
    {
        if (!condition)
        {
            throw new InvalidOperationException(
                "CutoverAdvance could not reach a committed v2 marker: " + message);
        }
    }
}

