        var registry = new LocalNodeExecutableEndpointRegistry();

        Assert.Throws<RouteFenceViolationException>(() => registry.Seal(
            routes.DataSources,
            listenerCallerAuthEnforced: true,
            publicStaticFilesEnabled: false));
        Assert.False(registry.IsSealed);
    }

