/// <summary>
/// T-731 — DES-0052 layout-eng-31 (host half): at the host boundary, for an unauthorized caller, a missing
/// optional related target and a denied one are indistinguishable in shape, in fault classification and in
/// timing, on the ordinary path and on both outbox fault paths. Related traversals go through the REAL gate
/// over the seeded production definitions. In-process: T-735 wires the HTTP route.
/// </summary>
[Collection(LayoutTimingParityCollection.Name)]
public sealed class LayoutSurfaceHostParityTests(ITestOutputHelper output)
{
    private static readonly ActorId Stranger = new("stranger-731");
    private static readonly ActorId Member = new("member-731");

    public enum Fault { None, GateLogDown, OutboxDown }

    [Theory(DisplayName = "layout-eng-31: an unauthorized caller gets the same resolution for a missing and a denied target, with no fault, on every outbox path")]
    [InlineData(Fault.None)]
    [InlineData(Fault.GateLogDown)]
    [InlineData(Fault.OutboxDown)]
    public async Task MissingAndDeniedReturnTheSameResolution(Fault fault)
    {
        await using var h = await Harness.CreateAsync(fault);
        var host = h.Host(TimeSpan.Zero);

        var missing = await h.ResolveAsync(host, Stranger, ownerExists: false);
        await h.Pipeline.Appender.IdleAsync();
        Assert.Empty(await RowsAsync(h.Pipeline.Trail));
        var denied = await h.ResolveAsync(host, Stranger, ownerExists: true);
        await h.Pipeline.Appender.IdleAsync();

        Assert.Equal(Describe(missing), Describe(denied));
        Assert.Empty(denied.Refusals);
        h.Pipeline.Db.Fault = false;
        var logged = (await RowsAsync(h.Pipeline.Trail)).Count;
        var outboxed = (await h.Pipeline.Outbox.ListUnresolvedAsync()).Count;
        Assert.Equal(fault switch { Fault.None => (1, 0), Fault.GateLogDown => (0, 1), _ => (0, 0) }, (logged, outboxed));
        // The control: a caller allowed records:read sees the owner, so the equality above is not vacuous.
        var allowed = await h.ResolveAsync(host, Member, ownerExists: true);
        Assert.Contains(allowed.Blocks, block => block.BlockId == "owner-name");
    }

    [Fact(DisplayName = "layout-eng-31: the response floor is configuration, 250 ms by default (a placeholder), and a resolution that overruns it raises the health alert")]
    public async Task AnOverrunOfTheFloorRaisesTheHealthAlert()
    {
        Assert.Equal(TimeSpan.FromMilliseconds(250), new LayoutSurfaceOptions().ResponseFloor);
        await using var h = await Harness.CreateAsync(Fault.None);

        await h.ResolveAsync(h.Host(LayoutSurfaceOptions.DefaultResponseFloor), Stranger, ownerExists: true);
        await h.Pipeline.Appender.IdleAsync();
        Assert.Equal(HealthStatus.Healthy, (await h.Pipeline.HealthAsync()).Status);

        h.Pipeline.Db.Delay = TimeSpan.FromMilliseconds(40);
        await h.ResolveAsync(h.Host(TimeSpan.FromMilliseconds(5)), Stranger, ownerExists: true);
        await h.Pipeline.Appender.IdleAsync();

        var alert = await h.Pipeline.HealthAsync();
        Assert.Equal(HealthStatus.Degraded, alert.Status);
        Assert.Equal(1L, alert.Data["floorOverruns"]);
    }

    /// <summary>
    /// The timing-parity gate (<see cref="TimingParity"/>, owner rulings Q41 and Q41b): 60 counterbalanced
    /// pairs against a floor measured on the host, the median rule (17th and 44th paired differences
    /// inside ±0.1 ms) and the tail rule (p90 gap under 1 ms). It checks those bounds under these test
    /// conditions only; it does not certify indistinguishability to a remote attacker. Each local-store
    /// operation costs 5 ms of CPU, so without the floor the denied path is about 15 ms slower and the
    /// median rule fails.
    /// </summary>
    [Trait(LayoutTimingParityCollection.LaneTrait, LayoutTimingParityCollection.PerfLane)]
    [Theory(DisplayName = "layout-eng-31: under the test conditions, missing and denied timings meet the gate's bounds (paired median within ±0.1 ms at 99.96% coverage, p90 gap under 1 ms)")]
    [InlineData(Fault.None)]
    [InlineData(Fault.GateLogDown)]
    public async Task MissingAndDeniedTimingDistributionsAreTheSame(Fault fault)
    {
        await using var h = await Harness.CreateAsync(fault);
        h.Pipeline.Db.Delay = TimeSpan.FromMilliseconds(5);
        await TimingParity.AssertSameAsync(
            floor => ownerExists => h.ResolveAsync(h.Host(floor), Stranger, ownerExists),
            h.Pipeline.Appender.IdleAsync, fault.ToString(), output);
    }

    private static string Describe(LayoutBindingResolution resolution) => JsonSerializer.Serialize(new
    {
        blocks = resolution.Blocks.Select(block => new { block.BlockId, block.Kind, block.BindingKind, block.Name, Value = block.Value?.ToJsonString(), block.RowId }),
        resolution.Refusals,
        resolution.Hidden,
    });

    private sealed class Harness : IAsyncDisposable
    {
        private readonly ServiceProvider _provider;
        private readonly AuthorizationGate _gate;
        private int _request;

        private Harness(ServiceProvider provider, Fault fault)
        {
            _provider = provider;
            _gate = new AuthorizationGate(
                provider.GetRequiredService<IAuthorizationClosureSnapshotReader>(),
                provider.GetRequiredService<IRecordStandingResolver>(),
                provider.GetRequiredService<IAuthorizationDefinitionAtomReader>());
            Pipeline = new Pipeline(new SwitchableTrail { Down = fault == Fault.GateLogDown });
            Pipeline.Db.Fault = fault == Fault.OutboxDown;
        }

        public Pipeline Pipeline { get; }

        public static async Task<Harness> CreateAsync(Fault fault)
        {
            var services = new ServiceCollection();
            services.AddSingleton(TestAuthorization.AllowGate());
            services.AddAccessGrantModule();
            var provider = services.BuildServiceProvider();
            await provider.GetRequiredService<AccessGrantAuthorizationSeed>()
                .InstallAsync(Tenant, At, AuthorizationSeedProfile.Production, TestDesktopOperator.Actor);
            await provider.GetRequiredService<IGrantStore>().AppendAsync(Tenant, new AccessGrant(
                GrantId.New(), Tenant, Member, AccessGrantAuthorizationSeed.MemberRole, ScopeExpression.Parse("/"),
                GrantResidency.Cache, new GrantValidity(At.AddHours(-1)), GranterKind.Person, new ActorId("tenant-admin"),
                At.AddHours(-1), new GrantProvenance(GrantSourceKind.Manual, new GrantReason(GrantReasonCodes.Manual),
                    new ActorId("tenant-admin")), At.AddHours(-1)));
            return new Harness(provider, fault);
        }

        public LayoutSurfaceHost Host(TimeSpan floor) => new(_gate, Pipeline.Outbox, Pipeline.Appender, Pipeline.Alarms,
            new SystemTimeAt(), NullLogger.Instance, new LayoutSurfaceOptions { ResponseFloor = floor });

        public Task<LayoutBindingResolution> ResolveAsync(LayoutSurfaceHost host, ActorId caller, bool ownerExists)
        {
            var owner = new LayoutRelatedRecord(Owner, new LayoutBindingScope(null, null,
                new Dictionary<string, JsonNode?>(StringComparer.Ordinal) { ["name"] = JsonValue.Create("Contoso") }));
            return host.ResolveAsync(Surface(), new OutcomeSources(LayoutRelatedResult.Absent),
                new Dictionary<string, Func<LayoutBindingScope, LayoutRelatedRecord?>>(StringComparer.Ordinal)
                {
                    ["invoice.owner"] = _ => ownerExists ? owner : null,
                },
                LayoutBindingScope.Root(new Dictionary<string, JsonNode?>(StringComparer.Ordinal)),
                Tenant, caller, $"request-{Interlocked.Increment(ref _request)}");
        }

        public async ValueTask DisposeAsync()
        {
            await Pipeline.Appender.IdleAsync();
            await _provider.DisposeAsync();
            Pipeline.Dispose();
        }
    }

    /// <summary>Real elapsed time for the floor, with the seeded grants' instant as "now".</summary>
    private sealed class SystemTimeAt : TimeProvider
    {
        public override DateTimeOffset GetUtcNow() => At;
    }
}

namespace Harborline.Api.LocalNodeHost.Tests.Layout;

// Owner ruling Q36: the Layout timing-parity tests measure one host's response times, so they must not
// share the CPU with the rest of the suite. On macpro (run 36195754191) parallel load pushed most samples
// past the floor, and the paths' timings then reflected the load, not the host.
// The timing theories carry Lane=perf. The host lanes' exact-clone excludes that trait;
// verify-perf-hosted runs it on Linux, with verify-perf comparing results on mac16.
// The classes' other tests (shape parity, fault paths, alerts, probe logging) stay in the host lanes.
// T-680: those perf jobs set HARBORLINE_PERF_QUIET=1 and the gate applies its quiet bounds; anywhere else
// (an unfiltered local run beside other lanes) it applies TimingParity.Bounds.Busy instead of going red.
[CollectionDefinition(Name, DisableParallelization = true)]
public sealed class LayoutTimingParityCollection
{
    public const string Name = "LayoutTimingParity";

    /// <summary>The trait key the host lanes filter on.</summary>
    public const string LaneTrait = "Lane";

    /// <summary>The perf lane: excluded from exact-clone and run by the dedicated perf jobs.</summary>
    public const string PerfLane = "perf";
}

using System.Diagnostics;
using System.Globalization;
using System.Text;

using Xunit.Abstractions;

namespace Harborline.Api.LocalNodeHost.Tests.Layout;

/// <summary>
/// The T-731 timing-parity gate (owner rulings Q41 and Q41b; research R-0119, after SILENT, Dunsche et
/// al. 2025, arXiv 2504.19821, and tlsfuzzer's timing analysis). It checks specified timing bounds for a
/// missing and a denied related target under these test conditions: one host, one process, the floor
/// measured on the host. It does not establish indistinguishability against every remote attacker, and it
/// is not a LAN certification.
/// </summary>
/// <remarks>
/// <para>
/// The floor is derived the way owner ruling 1 derives the production one: the worst of 100 denied runs
/// with no floor, doubled, rounded up to the 15.6 ms tick, at least four ticks. Then 60 preplanned pairs
/// run, one missing and one denied resolution each, counterbalanced: even pairs run missing first, odd
/// pairs denied first.
/// </para>
/// <para>
/// Two rules decide, and both must hold:
/// </para>
/// <list type="bullet">
///   <item>The median rule. The 60 paired differences (denied minus missing), sorted, have their 17th
///     and 44th order statistics (1-based) strictly inside ±0.1 ms. For 60 independent pairs those two
///     order statistics bound the median of the difference with 99.961% coverage (binomial: 1 - 2 P(X ≤
///     16), X ~ Bin(60, 1/2)). The coverage holds only if the pairs are independent; the lag-1
///     autocorrelation is logged so that can be checked.</item>
///   <item>The tail rule. |p90(denied) - p90(missing)| &lt; 1 ms, each path's p90 taken over its own 60
///     timings, as a point estimate with the linear-interpolation quantile (Hyndman-Fan type 7). It is
///     the gap between the paths' p90s, not the p90 of the paired differences, so noise that moves
///     both paths alike cancels. It catches a leak that hits only a minority of denials, which the
///     median rule cannot see.</item>
/// </list>
/// <para>
/// The two-sample KS D, the median interval's endpoints, the p90 gap and the lag-1 autocorrelation of the
/// paired differences in run order are diagnostics only and never decide. All 60 raw pairs are written to
/// the test output.
/// </para>
/// <para>
/// Those bounds are the quiet bounds. On a box not marked quiet (<c>HARBORLINE_PERF_QUIET</c> unset) the
/// rules run at the looser <see cref="Bounds.Busy"/> bounds, scaled to the floor (T-680): the gate loses
/// its detection floor there, not its verdict. The perf lanes set the variable, so the detection floor
/// holds where the gate is required.
/// </para>
/// </remarks>
internal static class TimingParity
{
    private const int Pairs = 60;
    private const double Tick = 15.625;

    /// <summary>1-based order statistics bounding the median of 60 paired differences at 99.961% coverage.</summary>
    internal const int LowerRank = 17, UpperRank = 44;

    /// <summary>The two rules' bounds: the median rule's order statistics strictly inside ±MedianMs, the
    /// tail rule's p90 gap strictly under TailMs.</summary>
    internal sealed record Bounds(double MedianMs, double TailMs)
    {
        /// <summary>The gate's detection floor (owner rulings Q41 and Q41b): ±0.1 ms and 1 ms.</summary>
        public static readonly Bounds Quiet = new(0.1, 1.0);

        /// <summary>
        /// T-680, ticket 268's contract: a busy box costs the gate its detection floor rather than giving a
        /// false red. Measured on winbox over 80 gate phases with 43-82 dotnet/testhost processes running
        /// (the T-680 lane, 2026-09-28): the worst |d[17]| or |d[44]| was 24.5 ms at a 62.5 ms floor
        /// (0.39 of the floor) and the worst p90 gap 31.5 ms (0.50 of the floor). So the median rule allows
        /// half the floor: busy noise stays inside it, and a path that escapes the floor still fails,
        /// because the floor is twice the worst calibration run and so sits at least half a floor above
        /// any unpadded path. The tail rule allows one floor, since busy tails alone reached half of one.
        /// </summary>
        public static Bounds Busy(TimeSpan floor) => new(floor.TotalMilliseconds / 2, floor.TotalMilliseconds);

        /// <summary>
        /// The same signal the TypeScript perf rows read (<c>ceilingMs</c> in the platform's
        /// render-baseline.ts): the quiet bounds only when <c>HARBORLINE_PERF_QUIET=1</c>, which a perf lane
        /// that has the box to itself sets; anything else is a busy box.
        /// </summary>
        public static Bounds Current(TimeSpan floor)
            => LoadCeiling.IsQuiet ? Quiet : Busy(floor);
    }

    /// <summary>One preplanned pair, in run order.</summary>
    internal sealed record Pair(int Index, bool DeniedFirst, double MissingMs, double DeniedMs)
    {
        public double DifferenceMs => DeniedMs - MissingMs;
    }

    /// <summary>What the two rules decided, and the diagnostics beside them.</summary>
    internal sealed record Verdict(
        bool MedianRule, bool TailRule, double LowerMs, double UpperMs, double P90GapMs, double KsD, double Lag1, Bounds Bounds)
    {
        public bool Passed => MedianRule && TailRule;

        public override string ToString() => string.Create(CultureInfo.InvariantCulture,
            $"{(Passed ? "PASS" : "FAIL")}: median rule {(MedianRule ? "held" : "failed")} "
            + $"(d[{LowerRank}] {LowerMs:F3} ms, d[{UpperRank}] {UpperMs:F3} ms, bound ±{Bounds.MedianMs} ms); "
            + $"tail rule {(TailRule ? "held" : "failed")} (p90 gap {P90GapMs:F3} ms, bound {Bounds.TailMs} ms); "
            + $"diagnostics KS D {KsD:F3}, lag-1 autocorrelation {Lag1:F3}");
    }

    /// <summary>Applies the two rules to <paramref name="pairs"/> at <paramref name="bounds"/> (the quiet
    /// bounds by default). Pure, so synthetic samples can test it.</summary>
    internal static Verdict Evaluate(IReadOnlyList<Pair> pairs, Bounds? bounds = null)
    {
        ArgumentNullException.ThrowIfNull(pairs);
        bounds ??= Bounds.Quiet;
        var differences = pairs.Select(pair => pair.DifferenceMs).Order().ToArray();
        var lower = differences[LowerRank - 1];
        var upper = differences[UpperRank - 1];
        var medianRule = lower > -bounds.MedianMs && upper < bounds.MedianMs;

        var gap = QuantileType7(pairs.Select(pair => pair.DeniedMs), 0.9) - QuantileType7(pairs.Select(pair => pair.MissingMs), 0.9);
        var tailRule = Math.Abs(gap) < bounds.TailMs;

        return new Verdict(medianRule, tailRule, lower, upper, gap,
            KolmogorovSmirnov(pairs.Select(pair => pair.MissingMs), pairs.Select(pair => pair.DeniedMs)),
            Lag1(pairs.Select(pair => pair.DifferenceMs).ToArray()), bounds);
    }

    /// <param name="at">For a floor, a sampler that runs one missing (false) or denied (true) resolution.</param>
    /// <param name="settle">Waits for background work to finish between the calibration and the samples.</param>
    /// <param name="label">Names the row in the output and in a failure.</param>
    /// <param name="output">Receives the verdict and all 60 raw pairs, pass or fail.</param>
    public static async Task AssertSameAsync(
        Func<TimeSpan, Func<bool, Task>> at, Func<Task> settle, string label, ITestOutputHelper output)
    {
        var calibration = at(TimeSpan.Zero);
        for (var i = 0; i < 5; i++) await calibration(true); // JIT warm-up, discarded
        var worst = 0.0;
        for (var i = 0; i < 100; i++)
        {
            var clock = Stopwatch.StartNew();
            await calibration(true);
            worst = Math.Max(worst, clock.Elapsed.TotalMilliseconds);
        }
        await settle();
        var floor = TimeSpan.FromMilliseconds(Math.Max(4, Math.Ceiling(2 * worst / Tick)) * Tick);
        var sample = at(floor);

        var pairs = new List<Pair>(Pairs);
        for (var i = 0; i < Pairs; i++)
        {
            var deniedFirst = i % 2 == 1;
            double missing = 0, denied = 0;
            foreach (var ownerExists in deniedFirst ? new[] { true, false } : [false, true])
            {
                var clock = Stopwatch.StartNew();
                await sample(ownerExists);
                if (ownerExists) denied = clock.Elapsed.TotalMilliseconds;
                else missing = clock.Elapsed.TotalMilliseconds;
            }
            pairs.Add(new Pair(i, deniedFirst, missing, denied));
        }
        await settle();

        var verdict = Evaluate(pairs, Bounds.Current(floor));
        var report = new StringBuilder();
        report.AppendLine(CultureInfo.InvariantCulture, $"{label}: {verdict} at floor {floor.TotalMilliseconds} ms");
        report.AppendLine(CultureInfo.InvariantCulture, $"{label}: pairs (index, first, missing ms, denied ms, denied - missing ms)");
        foreach (var pair in pairs)
            report.AppendLine(CultureInfo.InvariantCulture,
                $"{label}: {pair.Index} {(pair.DeniedFirst ? "denied" : "missing")} {pair.MissingMs:F4} {pair.DeniedMs:F4} {pair.DifferenceMs:F4}");
        output.WriteLine(report.ToString());
        Assert.True(verdict.Passed, $"{label}: {verdict} at floor {floor.TotalMilliseconds} ms");
    }

    /// <summary>Hyndman-Fan type 7: linear interpolation between order statistics at (n - 1) p.</summary>
    internal static double QuantileType7(IEnumerable<double> values, double p)
    {
        var sorted = values.Order().ToArray();
        var h = (sorted.Length - 1) * p;
        var low = (int)Math.Floor(h);
        return low + 1 < sorted.Length ? sorted[low] + (h - low) * (sorted[low + 1] - sorted[low]) : sorted[low];
    }

    private static double KolmogorovSmirnov(IEnumerable<double> a, IEnumerable<double> b)
    {
        var x = a.Order().ToArray();
        var y = b.Order().ToArray();
        double d = 0;
        int i = 0, j = 0;
        while (i < x.Length && j < y.Length)
        {
            var t = Math.Min(x[i], y[j]);
            while (i < x.Length && x[i] <= t) i++;
            while (j < y.Length && y[j] <= t) j++;
            d = Math.Max(d, Math.Abs((double)i / x.Length - (double)j / y.Length));
        }
        return d;
    }

    private static double Lag1(double[] series)
    {
        var mean = series.Average();
        double numerator = 0, denominator = 0;
        for (var i = 0; i < series.Length; i++)
        {
            denominator += (series[i] - mean) * (series[i] - mean);
            if (i + 1 < series.Length) numerator += (series[i] - mean) * (series[i + 1] - mean);
        }
        return denominator == 0 ? 0 : numerator / denominator;
    }
}

namespace Harborline.Api.LocalNodeHost.Tests.Layout;

/// <summary>
/// T-731, owner rulings Q41 and Q41b: the timing-parity gate against seeded, synthetic samples, with no
/// real timing. The noise is 60 draws of 62.5 ms plus up to 0.04 ms. The denied path gets the same
/// draws in another order, plus any seeded leak, so each path's own distribution is exactly the noise
/// and the leak.
/// </summary>
public sealed class TimingParityGateTests
{
    public enum Leak { None, FiveMsOnEveryDenial, OneMsOnEveryDenial, FiveMsOnOneInFiveDenials }

    [Theory(DisplayName = "layout-eng-31: the timing-parity gate passes identical noise and fails a seeded leak (+5 ms or +1 ms on every denial, +5 ms on 20% of denials)")]
    [InlineData(Leak.None, true)]
    [InlineData(Leak.FiveMsOnEveryDenial, false)]
    [InlineData(Leak.OneMsOnEveryDenial, false)]
    [InlineData(Leak.FiveMsOnOneInFiveDenials, false)]
    public void TheGateCatchesASeededLeak(Leak leak, bool passes)
    {
        var verdict = TimingParity.Evaluate(Samples(leak));

        Assert.Equal(passes, verdict.Passed);
        // Which rule sees what: a leak on every denial moves the median and the tail; a leak on a
        // minority of denials leaves the median where it was, and only the tail rule sees it.
        var (median, tail) = leak switch
        {
            Leak.None => (true, true),
            Leak.FiveMsOnOneInFiveDenials => (true, false),
            _ => (false, false),
        };
        Assert.Equal((median, tail), (verdict.MedianRule, verdict.TailRule));
    }

    [Fact(DisplayName = "layout-eng-31: the timing-parity gate reads p90 by linear interpolation (Hyndman-Fan type 7)")]
    public void TheTailRuleUsesTypeSevenQuantiles()
    {
        // (n - 1) p = 9 * 0.9 = 8.1, so the p90 of 1..10 is 9 + 0.1 * (10 - 9).
        Assert.Equal(9.1, TimingParity.QuantileType7(Enumerable.Range(1, 10).Select(i => (double)i), 0.9), 10);
    }

    private static List<TimingParity.Pair> Samples(Leak leak)
    {
        var random = new Random(731);
        var noise = Enumerable.Range(0, 60).Select(_ => 62.5 + random.NextDouble() * 0.04).ToArray();
        var reordered = noise.OrderBy(_ => random.Next()).ToArray();
        return Enumerable.Range(0, 60).Select(i =>
        {
            var extra = leak switch
            {
                Leak.FiveMsOnEveryDenial => 5.0,
                Leak.OneMsOnEveryDenial => 1.0,
                Leak.FiveMsOnOneInFiveDenials when i % 5 == 0 => 5.0,
                _ => 0.0,
            };
            return new TimingParity.Pair(i, i % 2 == 1, noise[i], reordered[i] + extra);
        }).ToList();
    }
}

