    [Fact(DisplayName = "Node-local store: lease create → read round-trips (decimal + bool persist)")]
    public async Task Lease_Create_Read_RoundTrips()
    {
        using var host = await StartKeyedHostAsync(FreshRootSeed());
        var factory = host.Services.GetRequiredService<IDbContextFactory<NodeLocalLeaseDbContext>>();
        var now = DateTimeOffset.UtcNow;

        await using (var ctx = await factory.CreateDbContextAsync())
        {
            ctx.Leases.Add(new LeaseRecord
            {
                Name = "LEASE-0001",
                Tenant = "Jane Tenant",
                Property = "PROP-0001",
                Unit = "4B",
                StartDate = "2026-01-01",
                EndDate = "2026-12-31",
                MonthlyRent = 1850.50m,
                Status = "Active",
                TermCadence = "monthly",
                AutoRenew = true,
                CreatedAt = now,
                ModifiedAt = now,
            });
            await ctx.SaveChangesAsync();
        }

        await using (var ctx = await factory.CreateDbContextAsync())
        {
            var row = await ctx.Leases.AsNoTracking().SingleAsync(l => l.Name == "LEASE-0001");
            Assert.Equal("Jane Tenant", row.Tenant);
            Assert.Equal(1850.50m, row.MonthlyRent);
            Assert.True(row.AutoRenew);
            Assert.Equal("monthly", row.TermCadence);
        }

        await host.StopAsync();
    }

    [Fact(DisplayName = "Node-local store: property/lease rows are encrypted at rest (raw unkeyed open fails)")]
    public async Task NodeLocalRows_AreEncryptedAtRest()
    {
        using (var host = await StartKeyedHostAsync(FreshRootSeed()))
        {
            var now = DateTimeOffset.UtcNow;
            var propFactory = host.Services.GetRequiredService<IDbContextFactory<NodeLocalPropertyDbContext>>();
            await using (var ctx = await propFactory.CreateDbContextAsync())
            {
                ctx.Properties.Add(new PropertyRecord
                {
                    Name = "PROP-SECRET",
                    PropertyName = "Sensitive address",
                    CreatedAt = now,
                    ModifiedAt = now,
                });
                await ctx.SaveChangesAsync();
            }
            await host.StopAsync();
        }
        SqliteConnection.ClearAllPools();

        // (a) The file does not begin with the plaintext SQLite magic header.
        var bytes = await File.ReadAllBytesAsync(_dbPath);
        var magic = "SQLite format 3\0"u8.ToArray();
        var headerMatches = bytes.Length >= magic.Length
            && bytes.AsSpan(0, magic.Length).SequenceEqual(magic);
        Assert.False(headerMatches, "node-local store begins with plaintext SQLite header (SC-1 violation)");

        // (b) A raw UNKEYED open cannot read the node-local tables.
        using var raw = new SqliteConnection($"Data Source={_dbPath};");
        raw.Open();
        using var cmd = raw.CreateCommand();
        cmd.CommandText = "SELECT count(*) FROM properties;";
        Assert.Throws<SqliteException>(() => cmd.ExecuteScalar());
    }

    [Fact(DisplayName = "Node-local store: all catalog migrations are exact and restart-idempotent")]
    public async Task EveryCatalogContext_MigratesExactly_And_RestartIsIdempotent()
    {
        var seed = FreshRootSeed();
        using (var host = await StartKeyedHostAsync(seed))
        {
            await host.StopAsync();
        }
        SqliteConnection.ClearAllPools();

        // A fresh provider over the same encrypted file must replay as a no-op.
        using (var host = await StartKeyedHostAsync(seed))
        {
            await host.StopAsync();
        }
        SqliteConnection.ClearAllPools();

        var dek = new SqlCipherKeyDerivation().DeriveSqlCipherKey(
            seed, LocalNodeSqlCipherRegistration.RelationalStoreKeyId);
        AssertCatalogPhysicalEvidence(dek);
    }

    [Fact(DisplayName = "Node-local store: injected-DEK path applies the same exact catalog twice")]
    public async Task InjectedDek_EveryCatalogContext_MigratesExactly_And_RestartIsIdempotent()
    {
        var dek = new byte[32];
        RandomNumberGenerator.Fill(dek);
        using (var host = await StartKeyedHostWithStoreDekAsync(dek))
        {
            await host.StopAsync();
        }
        SqliteConnection.ClearAllPools();

        using (var host = await StartKeyedHostWithStoreDekAsync(dek))
        {
            await host.StopAsync();
        }
        SqliteConnection.ClearAllPools();

        AssertCatalogPhysicalEvidence(dek);
    }

    private void AssertCatalogPhysicalEvidence(byte[] dek)
    {
        using var conn = new SqliteConnection($"Data Source={_dbPath};");
        conn.Open();
        using (var keyCmd = conn.CreateCommand())
        {
            keyCmd.CommandText = $"PRAGMA key = \"x'{Convert.ToHexString(dek)}'\";";
            keyCmd.ExecuteNonQuery();
        }
        using var q = conn.CreateCommand();
        q.CommandText =
            "SELECT name FROM sqlite_schema WHERE type='table' AND name LIKE '%MigrationsHistory%';";
        var historyTables = new List<string>();
        using (var reader = q.ExecuteReader())
        {
            while (reader.Read())
            {
                historyTables.Add(reader.GetString(0));
            }
        }

        var expectedTables = LocalNodeExclusiveEfContextCatalog.All
            .Select(item => item.MigrationsHistoryTable)
            .Append("__EFMigrationsHistory")
            .Order(StringComparer.Ordinal)
            .ToArray();
        Assert.Equal(expectedTables, historyTables.Order(StringComparer.Ordinal));

        foreach (var descriptor in LocalNodeExclusiveEfContextCatalog.All)
        {
            using var history = conn.CreateCommand();
            history.CommandText =
                $"SELECT MigrationId FROM \"{descriptor.MigrationsHistoryTable}\" ORDER BY MigrationId;";
            var observedIds = new List<string>();
            using var reader = history.ExecuteReader();
            while (reader.Read())
            {
                observedIds.Add(reader.GetString(0));
            }

            Assert.Equal(
                descriptor.CompiledMigrations.Select(item => item.MigrationId),
                observedIds);
        }

        using var searchObjects = conn.CreateCommand();
        searchObjects.CommandText =
            "SELECT name FROM sqlite_schema " +
            "WHERE name IN ('search_fts', 'search_nodes_ai', 'search_nodes_ad', 'search_nodes_au') " +
            "ORDER BY name;";
        var observedSearchObjects = new List<string>();
        using (var reader = searchObjects.ExecuteReader())
        {
            while (reader.Read())
            {
                observedSearchObjects.Add(reader.GetString(0));
            }
        }

        Assert.Equal(
            new[] { "search_fts", "search_nodes_ad", "search_nodes_ai", "search_nodes_au" },
            observedSearchObjects);
    }

    public void Dispose()
    {
        try
        {
            SqliteConnection.ClearAllPools();
            if (Directory.Exists(_dir))
            {
                Directory.Delete(_dir, recursive: true);
            }
        }
        catch
        {
            // Best-effort temp cleanup.
        }
    }
}

using Harborline.Api.LocalNodeHost.Health;

namespace Harborline.Api.LocalNodeHost.Tests;

/// <summary>
/// Deep-review #1842 (major finding) — the FAIL-CLOSED coupling between the web-client profile and the
/// listener caller-auth gate. The listener middleware (<c>SharedHostedWebApp.UseListenerCallerAuth</c>)
/// FAST-PATHS — permits every route — when no bootstrap session token is configured
/// (<see cref="NodeCallerSessionToken.IsEnforced"/> == <c>false</c>). So a web node enabled WITHOUT
/// <c>LocalNode__SessionToken</c> set would leave every route open and make the browser login screen
/// decorative (server-side there is no gate). <see cref="NodeWebClientOptions.EnsureCallerAuthEnforcedIfEnabled"/>
/// is the startup guard Program.cs calls to refuse that exact misconfiguration; these facts pin it.
/// </summary>
/// <remarks>
/// The guard is driven through the SAME <see cref="NodeCallerSessionToken.IsEnforced"/> predicate the
/// composition root passes (a real token object built from the configured value), so the test exercises
/// the true enabled-web-client × unset-session-token config the reviewer named — not a synthetic bool.
/// </remarks>
public sealed class NodeWebClientOptionsTests
{
    // Mirrors Program.cs: the guard is fed `new NodeCallerSessionToken(sessionToken).IsEnforced`.
    private static bool CallerAuthEnforcedFor(string? sessionToken) =>
        new NodeCallerSessionToken(sessionToken).IsEnforced;

    [Theory(DisplayName = "web-client ENABLED without a session token ⇒ host refuses to start (fail-closed)")]
    [InlineData(null)]
    [InlineData("")]
    [InlineData("   ")]
    public void Enabled_Without_SessionToken_Throws(string? unsetSessionToken)
    {
        var options = new NodeWebClientOptions
        {
            Enabled = true,
            // A credential CAN be provisioned yet the node must STILL refuse — the decorative-login
            // risk is about the LISTENER gate being un-enforced, independent of the founder credential.
            FounderUsername = "founder",
            FounderPasswordHash = "$argon2id$v=19$m=19456,t=2,p=1$c2FsdHNhbHQ$aGFzaGhhc2g",
        };

        var ex = Assert.Throws<InvalidOperationException>(
            () => options.EnsureCallerAuthEnforcedIfEnabled(CallerAuthEnforcedFor(unsetSessionToken)));

        // The message must name the cause + the fix honestly (an opaque throw would be a worse gap).
        Assert.Contains("LocalNode__SessionToken", ex.Message, StringComparison.Ordinal);
        Assert.Contains("fail-closed", ex.Message, StringComparison.OrdinalIgnoreCase);
    }

    [Fact(DisplayName = "web-client ENABLED with a session token configured ⇒ starts (gate is enforced)")]
    public void Enabled_With_SessionToken_DoesNotThrow()
    {
        var options = new NodeWebClientOptions { Enabled = true };

        // A configured (non-blank) token ⇒ IsEnforced true ⇒ the listener gates every non-allowlisted
        // route ⇒ the browser login is a real server-side gate ⇒ no throw.
        options.EnsureCallerAuthEnforcedIfEnabled(
            CallerAuthEnforcedFor("carrier-per-boot-session-token-0123456789abcdef"));
    }

    [Fact(DisplayName = "web-client DISABLED ⇒ never throws, even with no session token (guard is a no-op)")]
    public void Disabled_NeverThrows()
    {
        var options = new NodeWebClientOptions { Enabled = false };

        // The default desktop/dev posture: the profile is off, so an un-enforced gate is fine (there is
        // no browser front door to make decorative). The guard must not gratuitously block that boot.
        options.EnsureCallerAuthEnforcedIfEnabled(CallerAuthEnforcedFor(null));
    }
}

