        Assert.True(r.HasOrgIdentity);
        Assert.Null(r.DisplayName);
        Assert.Equal(BrandingLogoSource.OrgLogo, r.LogoSource);
    }

    [Fact(DisplayName = "dark logo + accent surface through to the resolved view")]
