    [Fact(DisplayName = "declared reference into an installed app: composer emits it, install accepts, graph shows it")]
    public async Task Declared_reference_into_installed_app_flows_end_to_end()
    {
        // Base app FIRST (provides core-records.property), then the dependent app that DECLARES the dependency
        // and binds the type — the composer emits the signed content reference from the parsed content.
        await InstallAndActivateAsync(CoreRecordsBody());
        var install = await InstallAsync(FleetOpsBody(declareDependency: true));
        Assert.Equal(HttpStatusCode.OK, install.StatusCode); // reference resolves ⇒ install accepted
        await ActivateAsync("fleet-ops");

        using var doc = await GetJsonAsync(GraphRoute);
        var edge = Assert.Single(
            doc.RootElement.GetProperty("edges").EnumerateArray().ToList(),
            e => e.GetProperty("fromContentKey").GetString() == "fleet-ops.vehicle");
        Assert.Equal("CrossAppContentReference", edge.GetProperty("edgeClass").GetString());
        Assert.Equal("ParentOf", edge.GetProperty("relation").GetString());
        Assert.Equal("core-records", edge.GetProperty("toPackKey").GetString());
        Assert.Equal("core-records.property", edge.GetProperty("toContentKey").GetString());

        // The dependent app's "Depends on" line carries the cross-app content edge.
        using var slice = await GetJsonAsync($"{GraphRoute}?app=fleet-ops");
        Assert.Contains(slice.RootElement.GetProperty("dependsOn").EnumerateArray(),
            e => e.GetProperty("toPackKey").GetString() == "core-records"
                && e.GetProperty("edgeClass").GetString() == "CrossAppContentReference");
    }

    [Fact(DisplayName = "declared reference into a NOT-installed app: install refuses fail-closed, naming it")]
    public async Task Declared_reference_into_missing_app_refuses_fail_closed()
    {
        // Install the dependent app WITHOUT its dependency present — install must refuse, naming the missing app.
        var install = await InstallAsync(FleetOpsBody(declareDependency: true));
        Assert.Equal(HttpStatusCode.UnprocessableEntity, install.StatusCode);

        using var doc = JsonDocument.Parse(await install.Content.ReadAsStringAsync());
        Assert.Contains(doc.RootElement.GetProperty("refusalCodes").EnumerateArray(),
            c => c.GetString() == "pack.install.refused.unmet_content_reference");

        var unmet = Assert.Single(
            doc.RootElement.GetProperty("preview").GetProperty("unmetContentReferences").EnumerateArray().ToList());
        Assert.Equal("fleet-ops.vehicle", unmet.GetProperty("fromContentKey").GetString());
        Assert.Equal("core-records", unmet.GetProperty("toPackKey").GetString()); // the missing app is named
        Assert.Equal("core-records.property", unmet.GetProperty("toContentKey").GetString());
    }

    [Fact(DisplayName = "K9: export refuses a reference into a package the pack does not declare")]
    public async Task Export_refuses_a_reference_into_an_undeclared_package()
    {
        // ADR 0028: a cross-package reference requires a declared dependency. The deriver used to drop the
        // edge silently, so the pack exported with the reference and no edge.
        var export = await _client.PostAsJsonAsync(PackComposerRoutes.ExportRoute, FleetOpsBody(declareDependency: false));
        Assert.Equal(HttpStatusCode.UnprocessableEntity, export.StatusCode);

        using var doc = JsonDocument.Parse(await export.Content.ReadAsStringAsync());
        var code = Assert.Single(doc.RootElement.GetProperty("codes").EnumerateArray().ToList());
        Assert.Equal("pack.validation.reference.dependency_undeclared", code.GetProperty("code").GetString());
        Assert.Equal("fleet-ops.vehicle", code.GetProperty("target").GetString());
    }

    [Fact(DisplayName = "K9: install re-derives edges from content and refuses a reference into an undeclared package")]
    public async Task Install_rederives_edges_and_refuses_an_undeclared_reference()
    {
        await InstallAndActivateAsync(CoreRecordsBody());

        // A hand-signed manifest that drops both the dependency and the edge: install must not trust it.
        var honest = new PackFileCodec().TryDecode(await ExportAsync(FleetOpsBody(declareDependency: true)))!;
        var subject = honest.Envelope!.Payload;
        var forged = subject with
        {
            Manifest = subject.Manifest with { Dependencies = [], ContentReferences = null },
        };
        var envelope = await new Ed25519Signer(_key).SignAsync(forged, DateTimeOffset.UtcNow, Guid.NewGuid());
        var content = new ByteArrayContent(new PackFileCodec().Encode(honest with { Envelope = envelope }));
        content.Headers.ContentType = new MediaTypeHeaderValue("application/octet-stream");

        var forgedBytes = await content.ReadAsByteArrayAsync();
        var check = new ByteArrayContent(forgedBytes);
        check.Headers.ContentType = new MediaTypeHeaderValue("application/octet-stream");
        using (var checkDoc = JsonDocument.Parse(await (await _client.PostAsync(PackInstallRoutes.CheckRoute, check)).Content.ReadAsStringAsync()))
        {
            // CHECK collects the same refusal without installing.
            var collected = Assert.Single(checkDoc.RootElement.GetProperty("refusals").EnumerateArray().ToList());
            Assert.Equal("pack.install.refused.undeclared_reference", collected.GetProperty("code").GetString());
            Assert.Equal("/contents/0/contentBase64", collected.GetProperty("pointer").GetString());
        }

        var install = await _client.PostAsync(PackInstallRoutes.InstallRoute, content);
        Assert.Equal(HttpStatusCode.UnprocessableEntity, install.StatusCode);

        using var doc = JsonDocument.Parse(await install.Content.ReadAsStringAsync());
        Assert.Equal(
            "pack.install.refused.undeclared_reference",
            string.Join(",", doc.RootElement.GetProperty("refusalCodes").EnumerateArray().Select(c => c.GetString())));
        var refusal = Assert.Single(doc.RootElement.GetProperty("refusals").EnumerateArray().ToList());
        Assert.Equal("pack.install.refused.undeclared_reference", refusal.GetProperty("code").GetString());
        Assert.Equal("/contents/0/contentBase64", refusal.GetProperty("pointer").GetString());
    }

