    [Fact(DisplayName = "nothing installed exposes only install; first install restores the full pack surface")]
    public async Task Nothing_installed_exposes_only_install_then_restores_all_routes()
    {
        var absent = new[]
        {
            await _unattributedClient.PostAsync(PackInstallRoutes.PreviewRoute, new ByteArrayContent([1])),
            await _unattributedClient.PostAsJsonAsync(PackInstallRoutes.ActivateRoute, new { packKey = "acme.pack", version = "1.0.0" }),
            await _unattributedClient.PostAsJsonAsync(PackInstallRoutes.DeactivateRoute, new { packKey = "acme.pack", version = "1.0.0" }),
            await _unattributedClient.GetAsync(PackInstallRoutes.ListInstalledRoute),
        };

        foreach (var response in absent)
        {
            using (response)
            {
                using var unmapped = await _unattributedClient.SendAsync(new HttpRequestMessage(
                    response.RequestMessage!.Method, "/api/local-node/packs/not-a-route"));
                Assert.True(
                    response.StatusCode == unmapped.StatusCode,
                    $"Expected unavailable route '{response.RequestMessage.RequestUri}' to match an unmapped path; "
                    + $"expected {(int)unmapped.StatusCode}, actual {(int)response.StatusCode}.");
                Assert.Equal(HttpStatusCode.NotFound, response.StatusCode);
            }
        }

        var packBytes = await ExportAsync(FormPackBody());
        Assert.Equal(HttpStatusCode.OK, (await PostBytesAsync(PackInstallRoutes.InstallRoute, packBytes)).StatusCode);

        using var preview = await PostBytesAsync(PackInstallRoutes.PreviewRoute, packBytes);
        using var activate = await _client.PostAsJsonAsync(PackInstallRoutes.ActivateRoute,
            new { packKey = "acme.pack", version = "1.0.0" });
        using var deactivate = await _client.PostAsJsonAsync(PackInstallRoutes.DeactivateRoute,
            new { packKey = "acme.pack", version = "1.0.0" });
        using var installed = await _client.GetAsync(PackInstallRoutes.ListInstalledRoute);
        Assert.NotEqual(HttpStatusCode.NotFound, preview.StatusCode);
        Assert.NotEqual(HttpStatusCode.NotFound, activate.StatusCode);
        Assert.NotEqual(HttpStatusCode.NotFound, deactivate.StatusCode);
        Assert.Equal(HttpStatusCode.OK, installed.StatusCode);
    }

    // ══ The REAL 0143 validator refuses an inadmissible workflow pack at install (S-9 / A7) ══
    [Fact(DisplayName = "install refuses an inadmissible workflow via the real 0143 validator (422)")]
    public async Task Install_refuses_an_inadmissible_workflow()
    {
        // A real workflow whose initialState references a non-existent state ⇒ InitialStateMissing.
        var body = WorkflowPackBody(initialState: "ghost");
        var packBytes = await ExportAsync(body);

        var install = await PostBytesAsync(PackInstallRoutes.InstallRoute, packBytes);
        Assert.Equal(HttpStatusCode.UnprocessableEntity, install.StatusCode);
        var text = await install.Content.ReadAsStringAsync();
        Assert.Contains("pack.install.refused.admission", text);
        Assert.Contains("workflow.admission", text); // a real ADR 0143 violation code
        Assert.Empty(_store.ListInstalled(NodeTenantFor()));
    }

    [Fact(DisplayName = "an admissible workflow pack installs")]
    public async Task Admissible_workflow_pack_installs()
    {
        var packBytes = await ExportAsync(WorkflowPackBody(initialState: "start"));
        var install = await PostBytesAsync(PackInstallRoutes.InstallRoute, packBytes);
        Assert.Equal(HttpStatusCode.OK, install.StatusCode);
    }

    [Fact(DisplayName = "preview does not mutate + surfaces stale revocation")]
    public async Task Preview_does_not_mutate()
    {
        var installedBytes = await ExportAsync(FormPackBody());
        Assert.Equal(HttpStatusCode.OK, (await PostBytesAsync(PackInstallRoutes.InstallRoute, installedBytes)).StatusCode);
        var packBytes = await ExportAsync(FormPackBody("preview.acme.pack"));
        var preview = await PostBytesAsync(PackInstallRoutes.PreviewRoute, packBytes);
        Assert.Equal(HttpStatusCode.OK, preview.StatusCode);

        using var doc = JsonDocument.Parse(await preview.Content.ReadAsStringAsync());
        Assert.Equal("WouldInstall", doc.RootElement.GetProperty("verdict").GetString());
        Assert.True(doc.RootElement.GetProperty("revocationStale").GetBoolean()); // offline: no channel list
        Assert.Single(_store.ListInstalled(NodeTenantFor()));
    }

    [Fact(DisplayName = "check collects independent refusal codes and RFC 6901 pointers without a catalogue write")]
    public async Task Check_collects_independent_refusals_without_mutating()
    {
        var packBytes = await ExportAsync(UnsupportedKindsPackBody());
        var before = CatalogueHash();

        var check = await PostBytesAsync(PackInstallRoutes.CheckRoute, packBytes);

        Assert.Equal(HttpStatusCode.OK, check.StatusCode);
        using var document = JsonDocument.Parse(await check.Content.ReadAsStringAsync());
        var refusals = document.RootElement.GetProperty("refusals").EnumerateArray().ToList();
        Assert.Equal(4, refusals.Count);
        Assert.Equal(PackInstallCodes.RefusedUnsupportedStandardsCatalog, refusals[0].GetProperty("code").GetString());
        Assert.Equal("/contents/0/contentBase64", refusals[0].GetProperty("pointer").GetString());
        Assert.Equal(PackInstallCodes.RefusedUnsupportedCascadeDefaults, refusals[1].GetProperty("code").GetString());
        Assert.Equal("/contents/1/contentBase64", refusals[1].GetProperty("pointer").GetString());
        Assert.Equal(PackInstallCodes.RefusedAdmission, refusals[2].GetProperty("code").GetString());
        Assert.Equal("/contents/1/contentBase64", refusals[2].GetProperty("pointer").GetString());
        Assert.Equal(PackInstallCodes.RefusedAdmission, refusals[3].GetProperty("code").GetString());
        Assert.Equal("/contents/2/contentBase64", refusals[3].GetProperty("pointer").GetString());
        Assert.Equal(before, CatalogueHash());
        Assert.Empty(_store.ListInstalled(NodeTenantFor()));
    }

    [Fact(DisplayName = "check accepts a valid pack without installing or activating it")]
    public async Task Check_accepts_valid_pack_without_mutating()
    {
        var packBytes = await ExportAsync(FormPackBody());
        var before = CatalogueHash();

        var check = await PostBytesAsync(PackInstallRoutes.CheckRoute, packBytes);

        Assert.Equal(HttpStatusCode.OK, check.StatusCode);
        using var document = JsonDocument.Parse(await check.Content.ReadAsStringAsync());
        Assert.Equal("WouldInstall", document.RootElement.GetProperty("verdict").GetString());
        Assert.Empty(document.RootElement.GetProperty("refusals").EnumerateArray());
        Assert.Equal(before, CatalogueHash());
        Assert.Empty(_store.ListInstalled(NodeTenantFor()));
    }

    [Fact(DisplayName = "T-909 ck-1: preview, check and install refuse a record type that claims a compiled shape, committing nothing")]
    public async Task Pack_install_refuses_a_record_type_that_claims_a_compiled_shape()
    {
        // Preview and check are exposed once something is installed, so install an ordinary pack first.
        Assert.Equal(HttpStatusCode.OK, (await PostBytesAsync(PackInstallRoutes.InstallRoute, await ExportAsync(FormPackBody()))).StatusCode);
        var packBytes = await ExportAsync(CompiledShapeClaimPackBody());
        var before = CatalogueHash();

        foreach (var route in new[] { PackInstallRoutes.PreviewRoute, PackInstallRoutes.CheckRoute, PackInstallRoutes.InstallRoute })
        {
            using var response = await PostBytesAsync(route, packBytes);
            var body = await response.Content.ReadFromJsonAsync<JsonElement>();
            Assert.Equal(route == PackInstallRoutes.InstallRoute ? HttpStatusCode.UnprocessableEntity : HttpStatusCode.OK, response.StatusCode);
            var refusal = Assert.Single(body.GetProperty("refusals").EnumerateArray());
            Assert.Equal(Harborline.Kernel.Core.KernelBootstrapErrors.CompiledShapeReplacement, refusal.GetProperty("code").GetString());
            Assert.Equal("/contents/1/contentBase64", refusal.GetProperty("pointer").GetString());
        }

        Assert.Equal(before, CatalogueHash());
        Assert.DoesNotContain(_store.ListInstalled(NodeTenantFor()), pack => pack.PackKey == "acme.bootstrap");
    }

    [Fact(DisplayName = "T-980: activate refuses over an Active dependency below the pin, though a newer one is installed")]
    public async Task Activate_route_refuses_when_the_active_dependency_is_below_the_pin()
    {
        PlatformPackTestPreload.Activate(_store, NodeTenantFor());
        foreach (var version in new[] { "1.0.0", "2.0.0" })
        {
            using var dependency = await PostBytesAsync(PackInstallRoutes.InstallRoute,
                await ExportAsync(FormPackBody("acme.base", version)));
            Assert.Equal(HttpStatusCode.OK, dependency.StatusCode);
            if (version != "1.0.0") continue;
            using var active = await _client.PostAsJsonAsync(PackInstallRoutes.ActivateRoute, new { packKey = "acme.base", version });
            Assert.Equal(HttpStatusCode.OK, active.StatusCode);
        }
        // Install is satisfied by the latest installed 2.0.0; activation reads the Active 1.0.0.
        using var install = await PostBytesAsync(PackInstallRoutes.InstallRoute, await ExportAsync(
            FormPackBody("acme.pack", dependencies: [new { key = "acme.base", version = "2.0.0" }])));
        Assert.Equal(HttpStatusCode.OK, install.StatusCode);

        using var activate = await _client.PostAsJsonAsync(PackInstallRoutes.ActivateRoute,
            new { packKey = "acme.pack", version = "1.0.0" });

        Assert.Equal(HttpStatusCode.UnprocessableEntity, activate.StatusCode);
        var body = await activate.Content.ReadFromJsonAsync<JsonElement>();
        Assert.Equal(PackInstallCodes.ActivateDependencyBelowPin, body.GetProperty("error").GetString());
        Assert.Equal("closure path 'acme.pack > acme.base': active 1.0.0 is below the pin 2.0.0.",
            body.GetProperty("detail").GetString());
        Assert.Null(_store.GetActive(NodeTenantFor(), "acme.pack"));
    }

    [Fact(DisplayName = "T-980: deactivate refuses while an Active pack depends on the target and names it")]
    public async Task Deactivate_route_refuses_while_an_active_pack_depends_on_it()
    {
        PlatformPackTestPreload.Activate(_store, NodeTenantFor());
        foreach (var body in new[] { FormPackBody("acme.base"),
            FormPackBody("acme.pack", dependencies: [new { key = "acme.base", version = "1.0.0" }]) })
        {
            var bytes = await ExportAsync(body);
            using var install = await PostBytesAsync(PackInstallRoutes.InstallRoute, bytes);
            Assert.Equal(HttpStatusCode.OK, install.StatusCode);
        }
        foreach (var key in new[] { "acme.base", "acme.pack" })
        {
            using var active = await _client.PostAsJsonAsync(PackInstallRoutes.ActivateRoute, new { packKey = key, version = "1.0.0" });
            Assert.Equal(HttpStatusCode.OK, active.StatusCode);
        }

        using var deactivate = await _client.PostAsJsonAsync(PackInstallRoutes.DeactivateRoute,
            new { packKey = "acme.base", version = "1.0.0" });

        Assert.Equal(HttpStatusCode.UnprocessableEntity, deactivate.StatusCode);
        var refusal = await deactivate.Content.ReadFromJsonAsync<JsonElement>();
        Assert.Equal(PackInstallCodes.DeactivateDependentsActive, refusal.GetProperty("error").GetString());
        Assert.Equal(["acme.pack"], refusal.GetProperty("dependents").EnumerateArray().Select(item => item.GetString()));
        Assert.NotNull(_store.GetActive(NodeTenantFor(), "acme.base"));
    }


    [Fact(DisplayName = "T-909 ck-1: install names the compiled-shape refusal ahead of a standards-catalog refusal authored before it")]
    [Trait("Holds", "kernel-core-ck-1")]
    public async Task Install_names_the_compiled_shape_refusal_ahead_of_an_earlier_standards_catalog_refusal()
    {
        var packBytes = await ExportAsync(CompiledShapeClaimAfterStandardsPackBody());
        var before = CatalogueHash();

        using var response = await PostBytesAsync(PackInstallRoutes.InstallRoute, packBytes);

        Assert.Equal(HttpStatusCode.UnprocessableEntity, response.StatusCode);
        var body = await response.Content.ReadFromJsonAsync<JsonElement>();
        var refusal = Assert.Single(body.GetProperty("refusals").EnumerateArray());
        Assert.Equal(PackInstallCodes.RefusedCompiledShapeReplacement, refusal.GetProperty("code").GetString());
        Assert.Equal("/contents/1/contentBase64", refusal.GetProperty("pointer").GetString());
        Assert.Equal(before, CatalogueHash());
    }
    // ── helpers ─────────────────────────────────────────────────────────────────

    private async Task<byte[]> ExportAsync(object body)
    {
        var resp = await _client.PostAsJsonAsync(PackComposerRoutes.ExportRoute, body);
        Assert.Equal(HttpStatusCode.OK, resp.StatusCode);
        return await resp.Content.ReadAsByteArrayAsync();
    }

    private Task<HttpResponseMessage> PostBytesAsync(string route, byte[] bytes)
    {
        var content = new ByteArrayContent(bytes);
        content.Headers.ContentType = new MediaTypeHeaderValue("application/octet-stream");
        return _client.PostAsync(route, content);
    }

