                PackInstallRoutes.ActivateRoute,
                new { packKey = PackKey, version = "1.0.0" })).StatusCode);

        var seed = Assert.IsType<EntityTypeSeed>(_registry.GetSeed(assetTypeId));
        await _registry.OverrideSeedAsync(
            tenant,
