            scheduleKind: "harborline.scheduling-definition-draft/unknown");
        var store = new InMemoryPackInstallStore();
        using var keyPair = KeyPair.Generate();
        await InstallAndActivatePackAsync(
            store,
            tenant,
            definition.Key,
