    [Fact(DisplayName = "Cross-tenant isolation: a tenant-A WholeTenant grant cannot OPEN tenant-B's encrypted file")]
    public async Task CrossTenant_Isolation_Per_Encrypted_File()
    {
        // Two DISTINCT per-tenant encrypted files (different DEKs) — the cross-tenant boundary.
        await using var storeA = await SearchTestStore.CreateAsync(keySalt: 7);
        await using var storeB = await SearchTestStore.CreateAsync(keySalt: 99);
        await SeedNodeAsync(storeA, "inv-A", "tenant-A", "invoice", "alpha secret", "alpha");
        await SeedNodeAsync(storeB, "inv-B", "tenant-B", "invoice", "beta secret", "beta");

        // Alice has a WholeTenant grant in tenant-A. Reading tenant-A's store returns only tenant-A rows.
        var grants = TestInMemoryAuthorizationStores.GrantStore();
        await grants.SaveAsync(TenantA, ActiveGrant(TenantA, Alice, ScopeExpression.Parse("/")), 0);
        var svcA = new NodeSearchReadService(storeA.Factory, TestSearchAuthorization.Projection(grants));

        var hitsA = await svcA.SearchAsync(TenantA, Alice, "secret", Now);
        Assert.Equal(new[] { "inv-A" }, hitsA.Select(h => h.RecordId).ToArray());

        // tenant-B's data lives in a SEPARATE file keyed by a different DEK — storeA's service cannot reach
        // it at all (different physical file). Even the in-file tenant predicate would reject a tenant-B row.
        Assert.DoesNotContain("inv-B", hitsA.Select(h => h.RecordId));
    }

    [Fact(DisplayName = "Multilingual FTS5 trigram: CJK query has NON-ZERO recall (unicode61 would give 0)")]
    public async Task Multilingual_Trigram_Cjk_Recall()
    {
        await using var store = await SearchTestStore.CreateAsync();
        // Japanese: "請求書" (invoice), "月額家賃" (monthly rent). With the default unicode61 tokenizer a CJK
        // substring query recalls ZERO (no whitespace word boundaries); the trigram tokenizer indexes 3-char
        // sequences so a CJK substring of length >= 3 matches. (A query shorter than the trigram length
        // produces no trigram and so matches nothing — a CJK query must be >= 3 chars, which is the natural
        // term length for the doctype-name / field-name substrings users actually search.)
        await SeedNodeAsync(store, "inv-jp", "tenant-A", "invoice", "請求書 2026年6月", "家賃 ユニット4の月額家賃");

        var grants = TestInMemoryAuthorizationStores.GrantStore();
        await grants.SaveAsync(TenantA, ActiveGrant(TenantA, Alice, ScopeExpression.Parse("/")), 0);
        var svc = new NodeSearchReadService(store.Factory, TestSearchAuthorization.Projection(grants));

        var hits = await svc.SearchAsync(TenantA, Alice, "月額家賃", Now); // 4-char CJK substring of the body.
        Assert.Contains("inv-jp", hits.Select(h => h.RecordId)); // CJK recall > 0 (unicode61 would give 0).
    }

    [Fact(DisplayName = "Graph expansion: a 1-hop neighbourhood is CLIPPED — unauthorized neighbours are not traversed")]
    public async Task Graph_Expansion_Is_Clipped()
    {
        await using var store = await SearchTestStore.CreateAsync();
        // lease-1 → tenant party-1 (authorized) and → property prop-1 (NOT authorized).
        await SeedNodeAsync(store, "lease-1", "tenant-A", "lease", "Lease unit 4", "active lease");
        await SeedNodeAsync(store, "party-1", "tenant-A", "party", "Acme Tenant", "the renting party");
        await SeedNodeAsync(store, "prop-1", "tenant-A", "property", "Building A", "the property");

        var indexer = new NodeSearchIndexer(store.Factory);
        await indexer.IndexEdgesAsync("lease-1", new[]
        {
            new SearchEdgeRow { Id = Guid.NewGuid().ToString(), TenantId = "tenant-A", SourceRecordId = "lease-1", TargetRecordId = "party-1", EdgeType = "lease-tenant" },
            new SearchEdgeRow { Id = Guid.NewGuid().ToString(), TenantId = "tenant-A", SourceRecordId = "lease-1", TargetRecordId = "prop-1", EdgeType = "lease-property" },
        });

        // Alice may see lease-1 + party-1 but NOT prop-1.
        var grants = TestInMemoryAuthorizationStores.GrantStore();
        await AppendRecordGrantsAsync(grants, TenantA, Alice, ["lease-1", "party-1"]);

        var svc = new NodeSearchReadService(store.Factory, TestSearchAuthorization.Projection(grants));
        var neighbourhood = await svc.ExpandAsync(TenantA, Alice, "lease-1", Now, maxHops: 1);

        var ids = neighbourhood.Select(h => h.RecordId).OrderBy(x => x).ToArray();
        Assert.Contains("lease-1", ids);
        Assert.Contains("party-1", ids);
        Assert.DoesNotContain("prop-1", ids); // the clipped hop never crossed to the unauthorized neighbour.
    }

    [Fact(DisplayName = "Graph expansion: an unauthorized SEED returns nothing (fail-closed)")]
    public async Task Graph_Expansion_Unauthorized_Seed_Empty()
    {
        await using var store = await SearchTestStore.CreateAsync();
        await SeedNodeAsync(store, "lease-1", "tenant-A", "lease", "Lease unit 4", "active lease");

        var grants = TestInMemoryAuthorizationStores.GrantStore();
        await grants.SaveAsync(
            TenantA,
            ActiveGrant(TenantA, Alice, ScopeExpression.Parse("/records/some-other-record")),
            0);

        var svc = new NodeSearchReadService(store.Factory, TestSearchAuthorization.Projection(grants));
        var neighbourhood = await svc.ExpandAsync(TenantA, Alice, "lease-1", Now, maxHops: 2);

        Assert.Empty(neighbourhood);
    }

    [Fact(DisplayName = "Graph expansion (F1 per-hop clip): an authorized node reachable ONLY through a FORBIDDEN intermediary is NOT returned — the walk cannot tunnel through an unauthorized node")]
    public async Task Graph_Expansion_Does_Not_Tunnel_Through_Forbidden_Intermediary()
    {
        // F1 regression (security-engineering verdict earlier repository ticket #1370): the graph walk must be clipped at EVERY
        // HOP, not only at the output projection. Topology: seed(authorized) → X(FORBIDDEN) → Z(authorized).
        // Z is reachable from seed ONLY by traversing through the forbidden intermediary X. Under output-only
        // clipping the walk tunnels through X and surfaces Z — asserting a seed↔Z relationship that exists
        // solely via a record Alice may not see (a graph-STRUCTURE inference channel). With the clip pushed
        // into the recursive member, X is never admitted to the frontier, so Z is unreachable and not returned.
        await using var store = await SearchTestStore.CreateAsync();
        await SeedNodeAsync(store, "seed", "tenant-A", "lease", "Seed lease", "the seed");
        await SeedNodeAsync(store, "forbidden-x", "tenant-A", "party", "Hidden party", "must not be traversed");
        await SeedNodeAsync(store, "z", "tenant-A", "invoice", "Distal invoice", "reachable only via X");

        var indexer = new NodeSearchIndexer(store.Factory);
        await indexer.IndexEdgesAsync("seed", new[]
        {
            new SearchEdgeRow { Id = Guid.NewGuid().ToString(), TenantId = "tenant-A", SourceRecordId = "seed", TargetRecordId = "forbidden-x", EdgeType = "seed-x" },
        });
        await indexer.IndexEdgesAsync("forbidden-x", new[]
        {
            new SearchEdgeRow { Id = Guid.NewGuid().ToString(), TenantId = "tenant-A", SourceRecordId = "forbidden-x", TargetRecordId = "z", EdgeType = "x-z" },
        });

        // Alice is authorized for {seed, z} but NOT for the intermediary forbidden-x.
        var grants = TestInMemoryAuthorizationStores.GrantStore();
        await AppendRecordGrantsAsync(grants, TenantA, Alice, ["seed", "z"]);

        var svc = new NodeSearchReadService(store.Factory, TestSearchAuthorization.Projection(grants));
        var neighbourhood = await svc.ExpandAsync(TenantA, Alice, "seed", Now, maxHops: 2);

        var ids = neighbourhood.Select(h => h.RecordId).OrderBy(x => x, StringComparer.Ordinal).ToArray();
        Assert.Contains("seed", ids);
        Assert.DoesNotContain("forbidden-x", ids); // never emitted (output clip)…
        Assert.DoesNotContain("z", ids);           // …AND never reached, because the walk can't pass THROUGH X.
    }

    [Fact(DisplayName = "Graph expansion (F2 dedup): the seed appears EXACTLY ONCE — no duplicate CTE rows")]
    public async Task Graph_Expansion_Result_Rows_Are_Unique()
    {
        // F2 regression: the recursive CTE UNIONs on (record_id, depth), so a node reached at multiple depths
        // yielded duplicate result rows (the seed itself appeared twice). The projection must de-duplicate so
        // each authorized record appears exactly once regardless of how many paths reach it.
        await using var store = await SearchTestStore.CreateAsync();
        await SeedNodeAsync(store, "seed", "tenant-A", "lease", "Seed lease", "the seed");
        await SeedNodeAsync(store, "a", "tenant-A", "party", "Party A", "neighbour a");
        await SeedNodeAsync(store, "b", "tenant-A", "party", "Party B", "neighbour b");

        var indexer = new NodeSearchIndexer(store.Factory);
        // A diamond: seed↔a, seed↔b, a↔b. The seed is re-reachable at depth 2 (seed→a→… loops back), and
        // 'a'/'b' are each reachable by two paths — all of which previously produced duplicate rows.
        await indexer.IndexEdgesAsync("seed", new[]
        {
            new SearchEdgeRow { Id = Guid.NewGuid().ToString(), TenantId = "tenant-A", SourceRecordId = "seed", TargetRecordId = "a", EdgeType = "seed-a" },
            new SearchEdgeRow { Id = Guid.NewGuid().ToString(), TenantId = "tenant-A", SourceRecordId = "seed", TargetRecordId = "b", EdgeType = "seed-b" },
        });
        await indexer.IndexEdgesAsync("a", new[]
        {
            new SearchEdgeRow { Id = Guid.NewGuid().ToString(), TenantId = "tenant-A", SourceRecordId = "a", TargetRecordId = "b", EdgeType = "a-b" },
        });

        var grants = TestInMemoryAuthorizationStores.GrantStore();
        await AppendRecordGrantsAsync(grants, TenantA, Alice, ["seed", "a", "b"]);

        var svc = new NodeSearchReadService(store.Factory, TestSearchAuthorization.Projection(grants));
        var neighbourhood = await svc.ExpandAsync(TenantA, Alice, "seed", Now, maxHops: 2);

        var ids = neighbourhood.Select(h => h.RecordId).ToArray();
        Assert.Equal(new[] { "a", "b", "seed" }, ids.OrderBy(x => x, StringComparer.Ordinal).ToArray());
        // Cardinality: each authorized record appears EXACTLY ONCE (no duplicate-row defect).
        Assert.Equal(ids.Length, ids.Distinct(StringComparer.Ordinal).Count());
        Assert.Equal(3, ids.Length);
    }
}

using System;
using System.Linq;
using System.Threading.Tasks;

using Microsoft.EntityFrameworkCore;

using Harborline.Api.Blocks.AccessGrant;
using Harborline.Api.Foundation.Assets.Common;
using Harborline.Api.Foundation.IdentityAtlas;
using Harborline.Api.Foundation.IdentityAtlas.Permissions;
using Harborline.Api.LocalNodeHost.Data.Search;

using Xunit;

namespace Harborline.Api.LocalNodeHost.Tests.Search;

/// <summary>
/// G-2 (revoke-TOCTOU) + G-3 (OnlineOnly⇒never-index + delete-on-revoke) functional tests for KG-search
/// Slice 0 (ADR 0135 KG-search F3-lift amendment).
/// </summary>
public sealed class NodeSearchResidencyAndRevokeTests
{
    private static readonly DateTimeOffset Now = DateTimeOffset.UnixEpoch.AddYears(56);
    private static readonly TenantId TenantA = TenantId.FromString("tenant-A");
    private static readonly ActorId Alice = new("alice");

    private static AccessGrant ActiveGrant(ScopeExpression scope, GrantResidency residency = GrantResidency.Cache,
        DateTimeOffset? revokedAt = null) =>
        TestSearchAuthorization.Grant(TenantA, Alice, scope, Now, residency,
            revocation: revokedAt is null ? null : new GrantRevocation(
                new ActorId("owner"), revokedAt.Value,
                new GrantReason(GrantReasonCodes.RevocationOffboarding)));

    // ── G-3: OnlineOnly ⇒ never-index (the structural insert-time half) ──────────────────────────────────

    [Fact(DisplayName = "G-3 (structural): the indexer REFUSES to write an OnlineOnly node — it never enters the index")]
    public async Task G3_OnlineOnly_Node_Is_Never_Indexed()
    {
        await using var store = await SearchTestStore.CreateAsync();
        var indexer = new NodeSearchIndexer(store.Factory);

        var indexed = await indexer.IndexNodeAsync(new SearchNodeRow
        {
            RecordId = "inv-online",
            TenantId = "tenant-A",
            NodeType = "invoice",
            Title = "online-only secret",
            Body = "must never enter the local index",
            Residency = SearchResidency.OnlineOnly,
        });

        Assert.False(indexed); // refused.

        await using var ctx = store.CreateContext();
        Assert.Equal(0, await ctx.Nodes.CountAsync()); // no node row.
        // And no FTS5 row either (the trigger only fires on an inserted node).
        var ftsCount = await CountFtsAsync(store);
        Assert.Equal(0, ftsCount);
    }

    [Fact(DisplayName = "G-3 (transition): a node already indexed is DELETED when its residency flips to OnlineOnly")]
    public async Task G3_Revoke_To_OnlineOnly_Deletes_Indexed_Node()
    {
        await using var store = await SearchTestStore.CreateAsync();
        var indexer = new NodeSearchIndexer(store.Factory);

        // First indexed as Cache-resident — it IS in the index (+ FTS row).
        Assert.True(await indexer.IndexNodeAsync(new SearchNodeRow
        {
            RecordId = "inv-1", TenantId = "tenant-A", NodeType = "invoice",
            Title = "rent invoice", Body = "monthly rent", Residency = SearchResidency.Cache,
        }));
        Assert.Equal(1, await CountFtsAsync(store));

        // Residency flips to OnlineOnly → the indexed node + its FTS row are removed.
        await indexer.OnResidencyChangedAsync(
            "tenant-A",
            "inv-1",
            GrantResidency.OnlineOnly,
            TestAuthorization.AllowedDecision(new TenantId("tenant-A"), "inv-1"));

        await using var ctx = store.CreateContext();
        Assert.Equal(0, await ctx.Nodes.CountAsync());
        Assert.Equal(0, await CountFtsAsync(store));
    }

    [Fact(DisplayName = "G-3 (clip half): an OnlineOnly GRANT contributes NOTHING to the authorized scope")]
    public async Task G3_OnlineOnly_Grant_Authorizes_Nothing()
    {
        var grants = TestInMemoryAuthorizationStores.GrantStore();
        await grants.SaveAsync(
            TenantA,
            ActiveGrant(ScopeExpression.Parse("/records/inv-1"), GrantResidency.OnlineOnly),
            0);

        var clip = TestSearchAuthorization.Projection(grants);
        var scope = await clip.ResolveAsync(TenantA, Alice, Now);

        Assert.True(scope.IsEmpty); // an online-only grant authorizes nothing in the local index.
        Assert.False(scope.Authorizes("inv-1"));
    }

    // ── G-2: revoke-TOCTOU — the scope reflects the grant's active state at the resolve instant ──────────

    [Fact(DisplayName = "G-2: a revoked grant authorizes NOTHING — the scope is fail-closed Empty")]
    public async Task G2_Revoked_Grant_Authorizes_Nothing()
    {
        var grants = TestInMemoryAuthorizationStores.GrantStore();
        // A grant that was revoked BEFORE the resolve instant.
        await grants.SaveAsync(
            TenantA,
            ActiveGrant(ScopeExpression.Parse("/records/inv-1"), revokedAt: Now.AddMinutes(-5)),
            0);

        var clip = TestSearchAuthorization.Projection(grants);
        var scope = await clip.ResolveAsync(TenantA, Alice, Now);

        Assert.True(scope.IsEmpty); // a revoked grant Reaches nothing — fail-closed.
    }

    [Fact(DisplayName = "G-2: a revoke landing BEFORE resolution is SEEN — the read returns nothing afterward")]
    public async Task G2_Revoke_Before_Resolution_Is_Seen_By_Read()
    {
        await using var store = await SearchTestStore.CreateAsync();
        var indexer = new NodeSearchIndexer(store.Factory);
        await indexer.IndexNodeAsync(new SearchNodeRow
        {
            RecordId = "inv-1", TenantId = "tenant-A", NodeType = "invoice",
            Title = "rent invoice", Body = "monthly rent", Residency = SearchResidency.Cache,
        });

        var grants = TestInMemoryAuthorizationStores.GrantStore();
        var grant = ActiveGrant(ScopeExpression.Parse("/records/inv-1"));
        await grants.SaveAsync(TenantA, grant, 0);

        var svc = new NodeSearchReadService(store.Factory, TestSearchAuthorization.Projection(grants));

        // While active, the read returns inv-1.
        var before = await svc.SearchAsync(TenantA, Alice, "rent", Now);
        Assert.Equal(new[] { "inv-1" }, before.Select(h => h.RecordId).ToArray());

        // Revoke lands. The NEXT read resolves the scope in the same read transaction as the scan, sees the
        // revoke, and returns nothing — the clip cannot be widened by a stale allow-set.
        await grants.RevokeAsync(TenantA, grant.GrantId, 1, Now.AddMinutes(1));
        var after = await svc.SearchAsync(TenantA, Alice, "rent", Now.AddMinutes(2));
        Assert.Empty(after);
    }

    [Fact(DisplayName = "G-2: an EXPIRED grant (past its validity window) authorizes nothing at the read instant")]
    public async Task G2_Expired_Grant_Authorizes_Nothing()
    {
        var grants = TestInMemoryAuthorizationStores.GrantStore();
        var expiring = TestSearchAuthorization.Grant(TenantA, Alice,
            ScopeExpression.Parse("/records/inv-1"), Now, validTo: Now.AddDays(-1));
        await grants.SaveAsync(TenantA, expiring, 0);

        var clip = TestSearchAuthorization.Projection(grants);
        var scope = await clip.ResolveAsync(TenantA, Alice, Now);

        Assert.True(scope.IsEmpty);
    }

    private static async Task<int> CountFtsAsync(SearchTestStore store)
    {
        await using var ctx = store.CreateContext();
        var conn = (Microsoft.Data.Sqlite.SqliteConnection)ctx.Database.GetDbConnection();
        await conn.OpenAsync();
        await using var cmd = conn.CreateCommand();
        cmd.CommandText = "SELECT count(*) FROM search_fts;";
        return Convert.ToInt32(await cmd.ExecuteScalarAsync());
    }
}

using System;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Threading.Tasks;

using Microsoft.Extensions.DependencyInjection;

using Harborline.Api.Blocks.AccessGrant;
using Harborline.Api.Foundation.Assets.Common;
using Harborline.Api.Foundation.IdentityAtlas;
using Harborline.Api.Foundation.IdentityAtlas.Permissions;
using Harborline.Api.LocalNodeHost.Data.Search;
using Harborline.Api.LocalNodeHost.Data.Authorization;
using Harborline.Api.LocalNodeHost.Data.Search.Vector;

using Xunit;

namespace Harborline.Api.LocalNodeHost.Tests.Search;

/// <summary>
/// <b>SearchClipArchFence</b> — the G-1 fail-closed clip fence for KG-search Slice 0 (ADR 0135 KG-search
/// F3-lift amendment; the same no-mock-crypto / no-side-door pattern as
/// <c>DekPairingResolverArchFence</c>). It proves an UN-CLIPPED FTS5 / graph query is <b>structurally
/// impossible</b>, not merely discouraged:
/// <list type="number">
///   <item>the read service has NO constructor that omits the clip — the clip is a required dependency;</item>
///   <item>the SOLE producer of the query <c>WHERE</c> is <see cref="AuthorizedRecordScope"/>, and the SOLE
///     producer of THAT is <see cref="IAuthorizedRecordSetProjection"/> — the read service consumes only it;</item>
///   <item>the production assembly's ONLY <see cref="IAuthorizedRecordSetProjection"/> impl is the
///     grant-backed projection (no "no-clip" / "all-records" stand-in ships);</item>
///   <item>no production type OTHER than <see cref="NodeSearchReadService"/> references the FTS5
///     <c>search_fts</c> table / a raw <c>MATCH</c> — the raw query path is encapsulated;</item>
///   <item>no production type OTHER than the read service + the indexer reads the underlying
///     <c>search_nodes</c> CONTENT table (the same plaintext the FTS index mirrors) — closing the
///     clip-omitting side door the FTS-only fence (item 4) does not cover, and a non-vacuity check proving
///     the content-table fence actually fires on a planted un-clipped read; and</item>
///   <item>the leak test against the REAL grant-backed projection: a principal with no/wrong grant gets the
///     fail-closed Empty scope and the read returns NOTHING (a green leak test against a stand-in would be a
///     false positive — bug-1312 forward).</item>
/// </list>
/// </summary>
public sealed class SearchClipArchFence
{
    private static readonly DateTimeOffset Now = DateTimeOffset.UnixEpoch.AddYears(56);
    private static readonly TenantId TenantA = TenantId.FromString("tenant-A");
    private static readonly ActorId Alice = new("alice");

    private static readonly Assembly ProductionAssembly = typeof(NodeSearchReadService).Assembly;

    // ── FENCE 1 — the read service has NO clip-omitting constructor (the clip is required) ───────────────

    [Fact(DisplayName = "G-1 fence: NodeSearchReadService has NO constructor that omits the clip — it is a required dependency")]
    public void ReadService_Has_No_Constructor_Without_The_Clip()
    {
        var ctors = typeof(NodeSearchReadService)
            .GetConstructors(BindingFlags.Public | BindingFlags.Instance);

        Assert.NotEmpty(ctors);
        // EVERY public constructor must take the clip projection — there is no "no-clip" overload.
        Assert.All(ctors, c =>
            Assert.Contains(c.GetParameters(),
                p => typeof(IAuthorizedRecordSetProjection).IsAssignableFrom(p.ParameterType)));
    }

    // ── FENCE 2 — the production assembly's ONLY clip impl is the closure-backed projection ──────────────

    [Fact(DisplayName = "G-1 fence: the SHIPPED assembly's ONLY IAuthorizedRecordSetProjection impl is closure-backed (NO no-clip stand-in)")]
    public void ProductionAssembly_Clip_Is_ClosureBacked_Only()
    {
        Assert.Equal("Harborline.Api.LocalNodeHost", ProductionAssembly.GetName().Name);

        var clipImpls = ProductionAssembly.GetTypes()
            .Where(t => t is { IsClass: true, IsAbstract: false }
                        && typeof(IAuthorizedRecordSetProjection).IsAssignableFrom(t))
            .Select(t => t.Name)
            .OrderBy(n => n, StringComparer.Ordinal)
            .ToArray();

        // The ONLY shipped clip is the closure-backed projection. There is NO "all-records" / "no-clip"
        // alternative in production.
        Assert.Equal(new[] { nameof(ClosureAuthorizedRecordSetProjection) }, clipImpls);
    }

    // ── FENCE 3 — the DI wiring registers the closure-backed clip (the production override) ──────────────

    [Fact(DisplayName = "G-1 fence: AddNodeKnowledgeGraphSearch registers the closure-backed clip as the SOLE IAuthorizedRecordSetProjection")]
    public void Wiring_Registers_ClosureBacked_Clip()
    {
        var services = new ServiceCollection();
        services.AddSingleton<IGrantStore, InMemoryGrantStore>();
        services.AddSingleton<IAuthorizationClosureReader>(
            new Harborline.Api.LocalNodeHost.Tests.Identity.FixedAuthorizationClosure());
        services.AddNodeKnowledgeGraphSearch();

        using var sp = services.BuildServiceProvider();
        var clip = sp.GetRequiredService<IAuthorizedRecordSetProjection>();

        Assert.IsType<ClosureAuthorizedRecordSetProjection>(clip);
    }

    // ── FENCE 4 — the raw FTS5 MATCH path is encapsulated in the read service ONLY ───────────────────────

    [Fact(DisplayName = "G-1 fence: no production source file OTHER than NodeSearchReadService issues a raw FTS5 MATCH query")]
    public void Only_The_ReadService_Issues_A_Raw_Fts_Match()
    {
        // A raw FTS5 MATCH query against the index must live ONLY in a CLIPPED read service. Any OTHER
        // production source that issues `search_fts MATCH …` could be an un-clipped side door. Detect the
        // QUERY signature (`search_fts MATCH`) — NOT the bare table name (which appears legitimately in XML
        // doc-comments + in the migration's CREATE/trigger DDL). The migration dir is excluded outright
        // (it CREATEs the table; it does not read it). The graph-expansion CTE is also in the read service.
        // The allow-list has TWO clipped readers since Slice 1b: NodeSearchReadService (the Slice-0 FTS/graph
        // surface) AND NodeVecSearchReadService (the Slice-1b hybrid surface whose lexical leg is the SAME
        // clipped FTS read — it builds its WHERE via VecRecordClip from the fail-closed scope, so it is a
        // clip-bound reader, not a side door).
        var allowedFtsReaders = new[] { "NodeSearchReadService.cs", "NodeVecSearchReadService.cs" };
        var searchDir = LocateSearchSourceDir();
        var offenders = Directory
            .EnumerateFiles(searchDir, "*.cs", SearchOption.AllDirectories)
            .Where(f => !allowedFtsReaders.Contains(Path.GetFileName(f), StringComparer.Ordinal))
            .Where(f => !f.Contains($"{Path.DirectorySeparatorChar}Migrations{Path.DirectorySeparatorChar}",
                StringComparison.Ordinal)) // the migration legitimately CREATEs search_fts (DDL, not a read).
            .Where(f =>
            {
                var text = File.ReadAllText(f);
                // The actual FTS5 read signature: a MATCH against the search_fts table. Tolerant of
                // whitespace between the table name and the MATCH keyword.
                return System.Text.RegularExpressions.Regex.IsMatch(
                    text, @"search_fts\s+MATCH", System.Text.RegularExpressions.RegexOptions.IgnoreCase);
            })
            .Select(Path.GetFileName)
            .OrderBy(n => n, StringComparer.Ordinal)
            .ToArray();

        Assert.True(
            offenders.Length == 0,
            "Only NodeSearchReadService may issue a raw FTS5 MATCH against search_fts (the clipped path). " +
            "Un-clipped FTS5 readers found: " + string.Join(", ", offenders));
    }

    // ── FENCE 5 — the REAL leak test against the REAL closure-backed clip (NOT a stand-in) ───────────────

    [Fact(DisplayName = "G-1 leak test (REAL clip): a principal with NO grant gets the fail-closed Empty scope — the read returns NOTHING")]
    public async Task Leak_Test_No_Grant_Is_FailClosed_Against_Real_Clip()
    {
        // The no-leak guarantee runs through the real closure projection, not a construction stand-in
        // (a green leak test against a stand-in would be a false positive; bug-1312).
        await using var store = await SearchTestStore.CreateAsync();
        var indexer = new NodeSearchIndexer(store.Factory);
        await indexer.IndexNodeAsync(new SearchNodeRow
        {
            RecordId = "inv-1", TenantId = "tenant-A", NodeType = "invoice",
            Title = "confidential rent invoice", Body = "tenant-A only", Residency = SearchResidency.Cache,
        });

        await using (var db = store.CreateContext())
        {
            const string definitionId = "10000000-0000-0000-0000-000000000099";
            db.AuthorizationDefinitions.Add(new AuthorizationDefinitionRow
            {
                DefinitionId = definitionId, Revision = 1, PublisherPackageId = "test",
                Operation = "records:read", ScopeType = 0, ScopeValue = "/",
            });
            db.AuthorizationOfferedRoles.Add(new AuthorizationOfferedRoleRow
            {
                DefinitionId = definitionId, Revision = 1,
                Vocabulary = TestSearchAuthorization.RecordsReader.Vocabulary,
                RoleName = TestSearchAuthorization.RecordsReader.Name,
            });
            await db.SaveChangesAsync();
        }
        var grants = new NodeEfGrantStore(store.Factory); // Alice initially holds NO grant.
        var clip = new ClosureAuthorizedRecordSetProjection();

        // And the read service returns nothing for an unauthorized principal.
        var svc = new NodeSearchReadService(store.Factory, clip);
        Assert.Empty(await svc.SearchAsync(TenantA, Alice, "rent", Now));

        // Contrast: a principal WITH an active grant for inv-1 DOES retrieve it (the clip is the boundary —
        // grant, not identity-claim, gates the read).
        await grants.AppendAsync(TenantA, TestSearchAuthorization.Grant(
            TenantA, Alice, ScopeExpression.Parse("/records/inv-1"), Now));
        var authorized = await svc.SearchAsync(TenantA, Alice, "rent", Now);
        Assert.Equal(new[] { "inv-1" }, authorized.Select(h => h.RecordId).ToArray());
    }

    // ── FENCE 6 — the search_nodes CONTENT table is read ONLY through the read service / indexer ──────────

    [Fact(DisplayName = "G-1 fence: no production source OTHER than the read service + indexer reads the search_nodes content table (the clip-omitting side door the FTS-only fence missed)")]
    public void Only_The_ReadService_And_Indexer_Read_The_Content_Table()
    {
        // FENCE 4 above proves the FTS5 `search_fts MATCH` path is encapsulated — but the SAME plaintext
        // title/body lives in the underlying `search_nodes` content table, exposed as the `Nodes` DbSet. A
        // future un-clipped reader of search_nodes (a plain EF `ctx.Nodes` query, or a raw
        // `FROM/JOIN search_nodes` SQL) returns the same content and would NOT be caught by the FTS-only
        // fence — so "an un-clipped read is structurally impossible" only held for the FTS path, not the
        // content table. This fence closes that side door: only the clipped read service (which always
        // applies the scope WHERE) and the indexer (which writes / existence-checks, never projecting content
        // OUT) may touch search_nodes / Nodes. Any other production source is a clip-omitting read path.
        var searchDir = LocateSearchSourceDir();

        // (a) Raw-SQL content-table reads: a `FROM`/`JOIN search_nodes` against the content table. Only a
        //     CLIPPED read service issues these (always inside the clip's WHERE). The DbContext maps the table
        //     via `ToTable("search_nodes")` (a STRING literal, not FROM/JOIN) and the migration CREATEs it —
        //     both excluded by the SQL-keyword-adjacency pattern + the migration-dir filter. Since Slice 1b the
        //     allow-list has TWO clipped readers: NodeSearchReadService (Slice-0) AND NodeVecSearchReadService
        //     (the Slice-1b hybrid surface — its lexical leg JOINs search_nodes inside the SAME VecRecordClip
        //     WHERE, so it is clip-bound, not a side door).
        var allowedRawNodeReaders = new[] { "NodeSearchReadService.cs", "NodeVecSearchReadService.cs" };
        var rawSqlOffenders = Directory
            .EnumerateFiles(searchDir, "*.cs", SearchOption.AllDirectories)
            .Where(f => !allowedRawNodeReaders.Contains(Path.GetFileName(f), StringComparer.Ordinal))
            .Where(f => !f.Contains($"{Path.DirectorySeparatorChar}Migrations{Path.DirectorySeparatorChar}",
                StringComparison.Ordinal))
            .Where(f => System.Text.RegularExpressions.Regex.IsMatch(
                File.ReadAllText(f),
                @"\b(?:FROM|JOIN)\s+search_nodes\b",
                System.Text.RegularExpressions.RegexOptions.IgnoreCase))
            .Select(Path.GetFileName)
            .OrderBy(n => n, StringComparer.Ordinal)
            .ToArray();

        Assert.True(
            rawSqlOffenders.Length == 0,
            "Only a clipped read service may issue a raw FROM/JOIN against the search_nodes content table " +
            "(the clipped path). Un-clipped content-table SQL readers found: " + string.Join(", ", rawSqlOffenders));

        // (b) EF DbSet content reads: a `ctx.Nodes` / `.Nodes` access. Only the read service (none today)
        //     and the indexer (upsert existence-check + delete — never a content projection returned to a
        //     caller) may reference the Nodes DbSet. The DbContext DECLARES the DbSet (`Set<SearchNodeRow>()`
        //     / `public DbSet<SearchNodeRow> Nodes =>`) — that declaration is excluded; we forbid CONSUMING
        //     `.Nodes` from anywhere else.
        var allowedDbSetConsumers = new[]
        {
            "NodeSearchReadService.cs",
            "NodeSearchIndexer.cs",
            "NodeLocalSearchDbContext.cs", // declares the DbSet; does not consume it.
        };
        var dbSetOffenders = Directory
            .EnumerateFiles(searchDir, "*.cs", SearchOption.AllDirectories)
            .Where(f => !allowedDbSetConsumers.Contains(Path.GetFileName(f), StringComparer.Ordinal))
            .Where(f => !f.Contains($"{Path.DirectorySeparatorChar}Migrations{Path.DirectorySeparatorChar}",
                StringComparison.Ordinal))
            .Where(f => System.Text.RegularExpressions.Regex.IsMatch(
                File.ReadAllText(f),
                @"\.Nodes\b",
                System.Text.RegularExpressions.RegexOptions.None))
            .Select(Path.GetFileName)
            .OrderBy(n => n, StringComparer.Ordinal)
            .ToArray();

        Assert.True(
            dbSetOffenders.Length == 0,
            "Only the read service + indexer may reference the search_nodes `Nodes` DbSet. Other consumers " +
            "(potential clip-omitting content reads) found: " + string.Join(", ", dbSetOffenders));
    }

    // ── FENCE 7 — the content-table fence is NON-VACUOUS (it would FIRE on a planted side door) ───────────

    [Fact(DisplayName = "G-1 fence is non-vacuous: a planted un-clipped `FROM search_nodes` read IS detected by the content-table regex")]
    public void ContentTable_Fence_Is_NonVacuous()
    {
        // Guard against the fence silently passing because its pattern never matches anything (a vacuous
        // arch-test is worse than none — it asserts a guarantee it cannot actually check). Prove the regex
        // the fence uses DOES fire on a representative un-clipped content read, and does NOT fire on the
        // legitimate DbContext mapping (a string literal) — so a real side door would be caught.
        const string plantedSideDoor = "SELECT title, body FROM search_nodes WHERE tenant_id = $t;";
        const string legitimateMapping = "e.ToTable(\"search_nodes\");"; // the DbContext's table mapping.

        Assert.Matches(@"\b(?:FROM|JOIN)\s+search_nodes\b", plantedSideDoor);
        Assert.DoesNotMatch(@"\b(?:FROM|JOIN)\s+search_nodes\b", legitimateMapping);

        const string plantedDbSetRead = "var leak = await ctx.Nodes.ToListAsync();";
        Assert.Matches(@"\.Nodes\b", plantedDbSetRead);
    }

    [Fact(DisplayName = "ADR 0072 fence: no Data/Search production source orders by global bm25 corpus statistics")]
    public void Production_Search_Source_Has_No_Global_Bm25_Order()
    {
        var searchDir = LocateSearchSourceDir();
        var offenders = Directory
            .EnumerateFiles(searchDir, "*.cs", SearchOption.AllDirectories)
            .Where(f => ContainsGlobalBm25Order(File.ReadAllText(f)))
            .Select(Path.GetFileName)
            .OrderBy(n => n, StringComparer.Ordinal)
            .ToArray();

        Assert.True(
            offenders.Length == 0,
            "Data/Search production source must rank only within the authorized clip. Global bm25 ordering " +
            "found in: " + string.Join(", ", offenders));

        const string scratchSource = "SELECT record_id FROM search_fts ORDER BY bm25(search_fts);";
        Assert.True(ContainsGlobalBm25Order(scratchSource));
    }

    private static bool ContainsGlobalBm25Order(string source) =>
        source.Contains("ORDER BY bm25(", StringComparison.OrdinalIgnoreCase);

    private static string LocateSearchSourceDir()
    {
        // Walk up from the test assembly location to the repo, then into the host's Data/Search source dir.
        var dir = new DirectoryInfo(AppContext.BaseDirectory);
        while (dir is not null)
        {
            var candidate = Path.Combine(
                dir.FullName, "apps", "local-node-host", "Data", "Search");
            if (Directory.Exists(candidate))
            {
                return candidate;
            }

            dir = dir.Parent;
        }

        throw new DirectoryNotFoundException(
            "Could not locate apps/local-node-host/Data/Search from " + AppContext.BaseDirectory);
    }
}

using System;
using System.IO;
using System.Threading.Tasks;

using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Infrastructure;

using Harborline.Api.LocalNodeHost.Data.Search;
using Harborline.Api.LocalNodeHost.Data.Identity;

namespace Harborline.Api.LocalNodeHost.Tests.Search;

/// <summary>
/// Test harness that stands up a REAL SQLCipher-encrypted <see cref="NodeLocalSearchDbContext"/> with the
/// search migration applied (search_nodes / search_edges + the FTS5 trigram virtual table + sync triggers),
/// keyed under a per-tenant DEK. Mirrors the proven raw-key-hex <c>PRAGMA key</c> pattern the
/// <c>DekPairingResolverArchFence</c> uses — so the tests run against the encrypted store, not plaintext.
/// </summary>
/// <remarks>
/// A DISTINCT key per harness instance models the per-tenant encrypted FILE = the cross-tenant isolation
/// boundary: a context built under tenant-A's key cannot open tenant-B's file.
/// </remarks>
public sealed class SearchTestStore : IAsyncDisposable
{
    private static int s_cipherProviderBound;
    private readonly string _dir;
    private readonly byte[] _key;
    private readonly bool _ownsDirectory;

    private SearchTestStore(string dir, byte[] key, string dbPath, bool ownsDirectory = true)
    {
        _dir = dir;
        _key = key;
        DatabasePath = dbPath;
        _ownsDirectory = ownsDirectory;
    }

    /// <summary>Absolute path to this harness's encrypted SQLite file.</summary>
    public string DatabasePath { get; }

    /// <summary>
    /// Create a keyed encrypted store and apply the search migration to it. <paramref name="keySalt"/>
    /// distinguishes per-tenant files (different salt ⇒ different DEK ⇒ different, mutually-unopenable file).
    /// </summary>
    public static async Task<SearchTestStore> CreateAsync(byte keySalt = 7)
        => await CreateAtMigrationAsync(targetMigration: null, keySalt).ConfigureAwait(false);

    /// <summary>
    /// Create an empty keyed database and migrate it directly to <paramref name="targetMigration"/>.
    /// Passing null applies the latest schema. A historical target never executes a later migration's Down.
    /// </summary>
    public static async Task<SearchTestStore> CreateAtMigrationAsync(
        string? targetMigration,
        byte keySalt = 7)
    {
        EnsureCipherProvider();

        var dir = Path.Combine(Path.GetTempPath(), "harborline-kgsearch-" + Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(dir);
        var dbPath = Path.Combine(dir, "local-node.db");

        var key = new byte[32];
        for (var i = 0; i < key.Length; i++)
        {
            key[i] = (byte)(i + keySalt);
        }

        var store = new SearchTestStore(dir, key, dbPath);

        await using var ctx = store.CreateContext();
        await ctx.GetService<Microsoft.EntityFrameworkCore.Migrations.IMigrator>()
            .MigrateAsync(targetMigration);
        return store;
    }

    /// <summary>
    /// Reopen the SAME on-disk encrypted file under the SAME key as <paramref name="origin"/> WITHOUT
    /// re-migrating (the schema already exists) — models a process restart against durable state. The reopened
    /// handle does NOT own the temp directory, so disposing it leaves the file for <paramref name="origin"/>'s
    /// disposal (the test owns both lifetimes).
    /// </summary>
    public static SearchTestStore Reopen(SearchTestStore origin)
    {
        ArgumentNullException.ThrowIfNull(origin);
        EnsureCipherProvider();
        return new SearchTestStore(origin._dir, origin._key, origin.DatabasePath, ownsDirectory: false);
    }

    /// <summary>
    /// Build a fresh keyed <see cref="NodeLocalSearchDbContext"/> over this harness's encrypted file. A live
    /// <see cref="SqliteConnection"/> is opened and keyed via <c>PRAGMA key</c> BEFORE EF touches it (the
    /// most robust SQLCipher+EF pattern — no interceptor-timing ambiguity), then handed to EF as an already-
    /// open connection. The context owns + disposes the connection.
    /// </summary>
    public NodeLocalSearchDbContext CreateContext()
    {
        var connection = new SqliteConnection($"Data Source={DatabasePath};Pooling=False");
        connection.Open();
        using (var keyCmd = connection.CreateCommand())
        {
            keyCmd.CommandText = $"PRAGMA key = \"x'{Convert.ToHexString(_key)}'\";";
            keyCmd.ExecuteNonQuery();
        }

        var options = new DbContextOptionsBuilder<NodeLocalSearchDbContext>()
            .UseSqlite(
                connection,
                contextOwnsConnection: true,
                sqliteOptionsAction: sqlite => sqlite.MigrationsHistoryTable(
                    NodeLocalSearchDbContext.MigrationsHistoryTableName))
            .ConfigureWarnings(w =>
                w.Ignore(Microsoft.EntityFrameworkCore.Diagnostics.RelationalEventId.PendingModelChangesWarning))
            .Options;

        // contextOwnsConnection: true ⇒ disposing the context closes + disposes this keyed connection.
        return new NodeLocalSearchDbContext(options);
    }

    /// <summary>
    /// Build the installation-identity context over this same encrypted local-node database, matching the
    /// production composition where independently migrated contexts share one physical store.
    /// </summary>
    public NodeLocalInstallationIdentityDbContext CreateInstallationIdentityContext()
    {
        var connection = OpenKeyedConnection();
        var options = new DbContextOptionsBuilder<NodeLocalInstallationIdentityDbContext>()
            .UseSqlite(
                connection,
                contextOwnsConnection: true,
                sqliteOptionsAction: sqlite => sqlite.MigrationsHistoryTable(
                    NodeLocalInstallationIdentityDbContext.MigrationsHistoryTableName))
            .ConfigureWarnings(w =>
                w.Ignore(Microsoft.EntityFrameworkCore.Diagnostics.RelationalEventId.PendingModelChangesWarning))
            .Options;
        return new NodeLocalInstallationIdentityDbContext(options);
    }

    public Data.Roster.NodeLocalRosterDbContext CreateRosterContext() => new(
        new DbContextOptionsBuilder<Data.Roster.NodeLocalRosterDbContext>()
            .UseSqlite(OpenKeyedConnection(), contextOwnsConnection: true,
                sqliteOptionsAction: sqlite => sqlite.MigrationsHistoryTable(
                    Data.Roster.NodeLocalRosterDbContext.MigrationsHistoryTableName)).Options);

    public Data.Packs.NodeLocalPacksDbContext CreatePacksContext() => new(
        new DbContextOptionsBuilder<Data.Packs.NodeLocalPacksDbContext>()
            .UseSqlite(OpenKeyedConnection(), contextOwnsConnection: true,
                sqliteOptionsAction: sqlite => sqlite.MigrationsHistoryTable(
                    Data.Packs.NodeLocalPacksDbContext.MigrationsHistoryTableName)).Options);

    public IDbContextFactory<Data.Packs.NodeLocalPacksDbContext> PacksFactory => new PacksHarnessFactory(this);

    /// <summary>
    /// The main <see cref="Data.LocalNodeDbContext"/> over the same encrypted file, with the full Pattern-A catalog,
    /// as production composes it.
    /// </summary>
    public Data.LocalNodeDbContext CreateLocalNodeContext() => new(
        new DbContextOptionsBuilder<Data.LocalNodeDbContext>()
            .UseSqlite(OpenKeyedConnection(), contextOwnsConnection: true).Options,
        Data.LocalNodePatternAModuleCatalog.CreateModules());

    /// <summary>A main-context factory over the same encrypted file as <see cref="Factory"/>.</summary>
    public IDbContextFactory<Data.LocalNodeDbContext> LocalNodeFactory => new LocalNodeHarnessFactory(this);

    private sealed class LocalNodeHarnessFactory(SearchTestStore store) : IDbContextFactory<Data.LocalNodeDbContext>
    {
        public Data.LocalNodeDbContext CreateDbContext() => store.CreateLocalNodeContext();
    }

    /// <summary>A roster-context factory over the same encrypted file as <see cref="Factory"/>.</summary>
    public IDbContextFactory<Data.Roster.NodeLocalRosterDbContext> RosterFactory => new RosterHarnessFactory(this);

    private sealed class RosterHarnessFactory(SearchTestStore store) : IDbContextFactory<Data.Roster.NodeLocalRosterDbContext>
    {
        public Data.Roster.NodeLocalRosterDbContext CreateDbContext() => store.CreateRosterContext();
    }

    private sealed class PacksHarnessFactory(SearchTestStore store) : IDbContextFactory<Data.Packs.NodeLocalPacksDbContext>
    {
        public Data.Packs.NodeLocalPacksDbContext CreateDbContext() => store.CreatePacksContext();
    }

    /// <summary>An <see cref="IDbContextFactory{TContext}"/> over this harness for services that need one.</summary>
    public IDbContextFactory<NodeLocalSearchDbContext> Factory => new HarnessFactory(this);

    /// <summary>An installation-identity factory over the same encrypted file as <see cref="Factory"/>.</summary>
    public IDbContextFactory<NodeLocalInstallationIdentityDbContext> InstallationIdentityFactory =>
        new InstallationIdentityHarnessFactory(this);

    /// <inheritdoc />
    public ValueTask DisposeAsync()
    {
        if (_ownsDirectory)
        {
            try { Directory.Delete(_dir, recursive: true); } catch { /* best-effort */ }
        }
        return ValueTask.CompletedTask;
    }

    private static void EnsureCipherProvider()
    {
        // SC-1: pin the cipher provider explicitly, else a bare init can bind the non-cipher e_sqlite3 and
        // PRAGMA key becomes a silent no-op (plaintext). Same hygiene as DekPairingResolverArchFence.
        if (System.Threading.Interlocked.Exchange(ref s_cipherProviderBound, 1) == 0)
        {
            SQLitePCL.raw.SetProvider(new SQLitePCL.SQLite3Provider_e_sqlcipher());
        }
    }

    private SqliteConnection OpenKeyedConnection()
    {
        var connection = new SqliteConnection($"Data Source={DatabasePath};Pooling=False");
        connection.Open();
        using var keyCmd = connection.CreateCommand();
        keyCmd.CommandText = $"PRAGMA key = \"x'{Convert.ToHexString(_key)}'\";";
        keyCmd.ExecuteNonQuery();
        return connection;
    }

    private sealed class HarnessFactory : IDbContextFactory<NodeLocalSearchDbContext>
    {
        private readonly SearchTestStore _store;
        public HarnessFactory(SearchTestStore store) => _store = store;
        public NodeLocalSearchDbContext CreateDbContext() => _store.CreateContext();
    }

    private sealed class InstallationIdentityHarnessFactory(SearchTestStore store)
        : IDbContextFactory<NodeLocalInstallationIdentityDbContext>
    {
        public NodeLocalInstallationIdentityDbContext CreateDbContext() =>
            store.CreateInstallationIdentityContext();
    }
}

using Microsoft.EntityFrameworkCore;

namespace Harborline.Api.LocalNodeHost.Tests.Search;

public sealed class TenantScopedSearchProjectionMigrationTests
{
    private const string PreviousMigration = "20260902120000_AuthorizationClosureOwnerVersion";

    [Fact]
    public async Task Tenant_key_upgrade_preserves_rows_backfills_fts_and_keeps_triggers_in_sync()
    {
        await using var store = await SearchTestStore.CreateAtMigrationAsync(PreviousMigration);
        await using (var before = store.CreateContext())
        {
            await before.Database.ExecuteSqlRawAsync("""
                INSERT INTO search_nodes(record_id, tenant_id, node_type, title, body, residency)
                VALUES ('record-a', 'tenant-a', 'calendar', 'Alpha harbor', 'first migration token', 0),
                       ('record-b', 'tenant-b', 'calendar', 'Bravo harbor', 'second migration token', 1);
                INSERT INTO search_vec_rows
                    (record_id, tenant_id, subject_id, model, model_version, dimension,
                     encrypted_embedding, embedding_nonce, key_version, residency)
                VALUES ('vec-a', 'tenant-a', 'subject-a', 'model-a', 'v1', 1, X'01', X'02', 1, 0),
                       ('vec-b', 'tenant-b', 'subject-b', 'model-b', 'v1', 1, X'03', X'04', 1, 1);
                """);
        }

        await using var after = store.CreateContext();
        await after.Database.MigrateAsync();

        var nodes = await after.Nodes.AsNoTracking()
            .OrderBy(row => row.TenantId)
            .Select(row => new { row.TenantId, row.RecordId, row.Title })
            .ToArrayAsync();
        Assert.Equal(2, nodes.Length);
        Assert.Contains(nodes, row => row.TenantId == "tenant-a" && row.RecordId == "record-a");
        Assert.Contains(nodes, row => row.TenantId == "tenant-b" && row.RecordId == "record-b");

        var vectors = await after.VecRows.AsNoTracking()
            .OrderBy(row => row.TenantId)
            .Select(row => new { row.TenantId, row.RecordId, row.SubjectId })
            .ToArrayAsync();
        Assert.Equal(2, vectors.Length);
        Assert.Contains(vectors, row => row.TenantId == "tenant-a" && row.RecordId == "vec-a");
        Assert.Contains(vectors, row => row.TenantId == "tenant-b" && row.RecordId == "vec-b");

        Assert.Equal(1, await FtsCountAsync(after, "tenant-a", "alpha"));
        Assert.Equal(1, await FtsCountAsync(after, "tenant-b", "bravo"));
        Assert.Equal(0, await FtsCountAsync(after, "tenant-a", "bravo"));

        await after.Database.ExecuteSqlRawAsync("""
            UPDATE search_nodes SET title = 'Charlie harbor', body = 'updated trigger token'
            WHERE tenant_id = 'tenant-a' AND record_id = 'record-a';
            DELETE FROM search_nodes
            WHERE tenant_id = 'tenant-b' AND record_id = 'record-b';
            """);

        Assert.Equal(0, await FtsCountAsync(after, "tenant-a", "alpha"));
        Assert.Equal(1, await FtsCountAsync(after, "tenant-a", "charlie"));
        Assert.Equal(0, await FtsCountAsync(after, "tenant-b", "bravo"));
        Assert.Single(await after.Nodes.AsNoTracking().ToArrayAsync());
    }

    private static async Task<long> FtsCountAsync(
        Data.Search.NodeLocalSearchDbContext context,
        string tenant,
        string query)
    {
        var connection = context.Database.GetDbConnection();
        await using var command = connection.CreateCommand();
        command.CommandText =
            "SELECT COUNT(*) FROM search_fts WHERE tenant_id = $tenant AND search_fts MATCH $query;";
        var tenantParameter = command.CreateParameter();
        tenantParameter.ParameterName = "$tenant";
        tenantParameter.Value = tenant;
        command.Parameters.Add(tenantParameter);
        var queryParameter = command.CreateParameter();
        queryParameter.ParameterName = "$query";
        queryParameter.Value = query;
        command.Parameters.Add(queryParameter);
        return Convert.ToInt64(await command.ExecuteScalarAsync());
    }
}

using Harborline.Api.Blocks.AccessGrant;
