public sealed class GrantFreshnessMigrationTests : IAsyncLifetime
{
    private const string PreviousMigration = "20260624152259_DurableSubjectErasure";
    private const string FreshnessMigration = "20260714104253_GrantFreshnessRows";
    private const string PermissionMigration = "20260805090000_GrantPermissionSets";
    private string _directory = null!;

    public Task InitializeAsync()
    {
        _directory = Path.Combine(Path.GetTempPath(), $"harborline-adm01a-{Guid.NewGuid():N}");
        Directory.CreateDirectory(_directory);
        return Task.CompletedTask;
    }

    public Task DisposeAsync()
    {
        try { Directory.Delete(_directory, recursive: true); } catch { /* Best-effort test cleanup. */ }
        return Task.CompletedTask;
    }

    [Fact]
    [Trait("PlanCard", "ADM-01A")]
    public async Task Fresh_migration_creates_owner_version_and_empty_principal_epoch_authority()
    {
        var path = Path.Combine(_directory, "fresh.db");
        await using var context = CreateContext(path);

        await context.Database.MigrateAsync();

        Assert.Contains(FreshnessMigration, await context.Database.GetAppliedMigrationsAsync());
        Assert.Contains(PermissionMigration, await context.Database.GetAppliedMigrationsAsync());
        Assert.Empty(await context.Database.GetPendingMigrationsAsync());
        Assert.False(context.Database.HasPendingModelChanges());
        Assert.Equal("1", await ScalarAsync(path,
            "SELECT dflt_value FROM pragma_table_info('search_grants') WHERE name = 'owner_version';"));
        Assert.Equal("0", await ScalarAsync(path, "SELECT count(*) FROM search_grant_authorization_epochs;"));
    }

    [Fact]
    [Trait("PlanCard", "ADM-01A")]
    public async Task Authorization_clean_break_discards_existing_permission_grants()
    {
        var path = Path.Combine(_directory, "upgrade.db");
        await using var context = CreateContext(path);
        await context.Database.MigrateAsync(PreviousMigration);
        await context.Database.ExecuteSqlRawAsync("""
            INSERT INTO search_grants (
                grant_id, tenant_id, principal_id, roles_json, scope_json, residency,
                validity_from_unix_ms, validity_until_unix_ms, granted_by, granted_at_unix_ms,
                revoked_at_unix_ms, source_reference)
            VALUES ('11111111-1111-1111-1111-111111111111', 'tenant-a', 'principal-a', '[]',
                '{{"wholeTenant":true,"recordIds":[]}}', 0, 0, NULL, 'issuer-a', 0, NULL, NULL);
            """);

        await context.Database.MigrateAsync();

        Assert.Equal("0", await ScalarAsync(path, "SELECT count(*) FROM search_grants;"));
        // The clean break discards both the untruthful legacy grant and its now-orphaned freshness row.
        Assert.Equal("0", await ScalarAsync(path, "SELECT count(*) FROM search_grant_authorization_epochs;"));
        Assert.False(context.Database.HasPendingModelChanges());
    }

    [Fact]
    [Trait("PlanCard", "MTW-2-3666")]
    public async Task Authorization_clean_break_does_not_fabricate_a_role_for_legacy_ship_rows()
    {
        var path = Path.Combine(_directory, "legacy-permissions.db");
        await using var context = CreateContext(path);
        await context.Database.MigrateAsync(PreviousMigration);
        await context.Database.ExecuteSqlRawAsync("""
            INSERT INTO search_grants (
                grant_id, tenant_id, principal_id, roles_json, scope_json, residency,
                validity_from_unix_ms, validity_until_unix_ms, granted_by, granted_at_unix_ms,
                revoked_at_unix_ms, source_reference)
            VALUES ('eeeeeeee-0000-0000-0000-000000000001', 'tenant-a', 'principal-a', '["Scribe"]',
                '{{"wholeTenant":true,"recordIds":[]}}', 0, 0, NULL, 'issuer-a', 0, NULL, NULL);
            """);

        await context.Database.MigrateAsync();

        Assert.Empty(await context.Grants.AsNoTracking().ToArrayAsync());
    }

    /// <summary>The authorization clean break removes every epoch whose legacy grant is discarded.</summary>
    [Fact]
    [Trait("PlanCard", "ADM-01A")]
    public async Task Authorization_clean_break_removes_epochs_for_every_discarded_principal()
    {
        var path = Path.Combine(_directory, "epoch-backfill.db");
        await using var context = CreateContext(path);
        await context.Database.MigrateAsync(PreviousMigration);
        // principal-a holds two grants (one live, one revoked); principal-b holds one live grant;
        // principal-c holds ONLY a revoked grant (no live grant to fall back on); principal-d holds only a
        // not-yet-valid grant. The backfill is per-PRINCIPAL and does not evaluate liveness, so that is four
        // epoch rows. principal-c is the load-bearing fixture for "a revoked grant still earns one, because
        // revocation advances the epoch rather than removing it" — with principal-a alone (which also holds
        // a live grant) that claim is unfalsifiable, since principal-a earns its epoch via the live row
        // regardless of the revoked one. principal-d is the fixture for the migration's other documented
        // claim, that not-yet-valid grants are included on purpose.
        await context.Database.ExecuteSqlRawAsync(
            LegacyGrantInsert("aaaaaaaa-0000-0000-0000-000000000001", "principal-a", revokedAtUnixMs: null));
        await context.Database.ExecuteSqlRawAsync(
            LegacyGrantInsert("aaaaaaaa-0000-0000-0000-000000000002", "principal-a", revokedAtUnixMs: 5));
        await context.Database.ExecuteSqlRawAsync(
            LegacyGrantInsert("bbbbbbbb-0000-0000-0000-000000000001", "principal-b", revokedAtUnixMs: null));
        await context.Database.ExecuteSqlRawAsync(
            LegacyGrantInsert("cccccccc-0000-0000-0000-000000000001", "principal-c", revokedAtUnixMs: 5));
        await context.Database.ExecuteSqlRawAsync(
            LegacyGrantInsert("dddddddd-0000-0000-0000-000000000001", "principal-d", revokedAtUnixMs: null,
                validityFromUnixMs: 4102444800000));

        await context.Database.MigrateAsync();

        Assert.Equal("0", await ScalarAsync(path, "SELECT count(*) FROM search_grant_authorization_epochs;"));
        Assert.False(context.Database.HasPendingModelChanges());
    }

    /// <summary>
    /// The backfill must never disturb an epoch a real grant write already minted and advanced — it fills
    /// gaps only. It must also fill every gap independently: a second principal in the SAME tenant with no
    /// epoch row of its own must still get one. This is the load-bearing check that the <c>NOT EXISTS</c>
    /// guard correlates on principal_id as well as tenant_id — a tenant-only guard would see principal-a's
    /// pre-existing row, conclude the whole tenant is already backfilled, and permanently orphan principal-b
    /// (the failure is silent and unrecoverable, because EF marks the migration applied either way).
    /// </summary>
    [Fact]
    [Trait("PlanCard", "ADM-01A")]
    public async Task Authorization_clean_break_removes_preexisting_and_backfilled_epochs()
    {
        var path = Path.Combine(_directory, "epoch-preserve.db");
        await using var context = CreateContext(path);
        await context.Database.MigrateAsync(FreshnessMigration);
        await context.Database.ExecuteSqlRawAsync(
            LegacyGrantInsert("cccccccc-0000-0000-0000-000000000001", "principal-a", revokedAtUnixMs: null));
        await context.Database.ExecuteSqlRawAsync("""
            INSERT INTO search_grant_authorization_epochs (tenant_id, principal_id, authorization_epoch)
            VALUES ('tenant-a', 'principal-a', 9);
            """);
        await context.Database.ExecuteSqlRawAsync(
            LegacyGrantInsert("cccccccc-0000-0000-0000-000000000002", "principal-b", revokedAtUnixMs: null));

        await context.Database.MigrateAsync();

        Assert.Equal("0", await ScalarAsync(path, "SELECT count(*) FROM search_grant_authorization_epochs;"));
    }

    /// <summary>
    /// The grant scope envelope, with its braces DOUBLED — <c>ExecuteSqlRaw</c> runs the statement through
    /// <c>string.Format</c>, so a single brace is read as a format placeholder and throws.
    /// </summary>
    private const string ScopeJsonForExecuteSqlRaw = "{{\"wholeTenant\":true,\"recordIds\":[]}}";

    private static string LegacyGrantInsert(
        string grantId,
        string principalId,
        long? revokedAtUnixMs,
        long validityFromUnixMs = 0) =>
        $$"""
        INSERT INTO search_grants (
            grant_id, tenant_id, principal_id, roles_json, scope_json, residency,
            validity_from_unix_ms, validity_until_unix_ms, granted_by, granted_at_unix_ms,
            revoked_at_unix_ms, source_reference)
        VALUES ('{{grantId}}', 'tenant-a', '{{principalId}}', '[]',
            '{{ScopeJsonForExecuteSqlRaw}}', 0, {{validityFromUnixMs}}, NULL, 'issuer-a', 0,
            {{(revokedAtUnixMs?.ToString(System.Globalization.CultureInfo.InvariantCulture) ?? "NULL")}},
            NULL);
        """;

    [Fact]
    [Trait("PlanCard", "ADM-01A")]
    public async Task Freshness_rows_round_trip_after_context_restart()
    {
        var path = Path.Combine(_directory, "restart.db");
        await using (var first = CreateContext(path))
        {
            await first.Database.MigrateAsync();
            first.Grants.Add(NewGrantRow(ownerVersion: 7));
            first.GrantAuthorizationEpochs.Add(new GrantAuthorizationEpochRow
            {
                TenantId = "tenant-a",
                PrincipalId = "principal-a",
                AuthorizationEpoch = 11,
            });
            await first.SaveChangesAsync();
        }

        await using var restarted = CreateContext(path);
        var grant = await restarted.Grants.AsNoTracking().SingleAsync();
        var epoch = await restarted.GrantAuthorizationEpochs.AsNoTracking().SingleAsync();

        Assert.Equal(7, grant.OwnerVersion);
        Assert.Equal(11, epoch.AuthorizationEpoch);
        Assert.Equal(("tenant-a", "principal-a"), (epoch.TenantId, epoch.PrincipalId));
    }

    private static GrantRow NewGrantRow(long ownerVersion) => new()
    {
        GrantId = "22222222-2222-2222-2222-222222222222",
        TenantId = "tenant-a",
        SubjectId = "principal-a",
        RoleVocabulary = AccessGrantAuthorizationSeed.MemberRole.Vocabulary,
        RoleName = AccessGrantAuthorizationSeed.MemberRole.Name,
        ScopeValue = "/",
        Residency = 0,
        ValidityFromUnixMs = 0,
        GrantedBy = "issuer-a",
        GrantedAtUnixMs = 0,
        GranterKind = (int)GranterKind.Person,
        Source = (int)GrantSourceKind.Manual,
        Approver = "issuer-a",
        LastReviewedAtUnixMs = 0,
        OwnerVersion = ownerVersion,
    };

    private static NodeLocalSearchDbContext CreateContext(string path)
    {
        var options = new DbContextOptionsBuilder<NodeLocalSearchDbContext>()
            .UseSqlite(
                $"Data Source={path};Pooling=False",
                sqlite => sqlite.MigrationsHistoryTable(NodeLocalSearchDbContext.MigrationsHistoryTableName))
            .Options;
        return new NodeLocalSearchDbContext(options);
    }

    private static async Task<string> ScalarAsync(string path, string sql)
    {
        await using var connection = new SqliteConnection($"Data Source={path};Pooling=False");
        await connection.OpenAsync();
        await using var command = connection.CreateCommand();
        command.CommandText = sql;
        return Convert.ToString(await command.ExecuteScalarAsync(), System.Globalization.CultureInfo.InvariantCulture)!;
    }
}

using Harborline.Api.Blocks.AccessGrant;
using Harborline.Api.Foundation.Assets.Common;
using Harborline.Api.Foundation.IdentityAtlas.Permissions;
using Harborline.Api.LocalNodeHost.Data.Search.Vector;

namespace Harborline.Api.LocalNodeHost.Tests.Search.Vector;

public sealed class GrantWriterVersionFenceTests
{
    private static readonly TenantId Tenant = TenantId.FromString("tenant-a");
    private static readonly ActorId User = new("user-a");
    private static readonly ActorId Admin = new("admin-a");
    private static readonly DateTimeOffset Now = DateTimeOffset.Parse("2026-09-01T12:00:00Z");

    [Fact]
    public async Task GrantStore_AppendIsSourceReferenceIdempotentAndImmutable()
    {
        await using var h = await VecTestHarness.CreateAsync();
        var grant = Grant();
        var first = await h.GrantStore.AppendAsync(Tenant, grant, "source-a");
        var replay = await h.GrantStore.AppendAsync(Tenant, grant, "source-a");
        Assert.Equal(first, replay);
        await Assert.ThrowsAsync<InvalidOperationException>(() => h.GrantStore.AppendAsync(
            Tenant, grant, "source-b"));
        await Assert.ThrowsAsync<InvalidOperationException>(() => h.GrantStore.AppendAsync(
            Tenant, Grant() with { GrantId = grant.GrantId, Subject = new ActorId("other") }, "source-a"));
    }

    [Fact]
    public async Task GrantStore_ValidityChangeRetainsEvidenceAndAdvancesVersion()
    {
        await using var h = await VecTestHarness.CreateAsync();
        var grant = await h.GrantStore.AppendAsync(Tenant, Grant(), "source-a");
        var changed = await h.GrantStore.ChangeValidityAsync(Tenant, grant.GrantId,
            new GrantValidity(Now, Now.AddDays(2)), Admin, new GrantReason(GrantReasonCodes.Manual));
        Assert.Equal(grant.Role, changed!.Role);
        Assert.Equal(grant.Grant, changed.Grant);
        Assert.Equal(Now.AddDays(2), changed.Validity.ValidTo);
        Assert.Equal(Admin, changed.ValidityChange!.ChangedBy);
        Assert.Equal(GrantReasonCodes.Manual, changed.ValidityChange.Reason.Code);
        await using var db = h.Store.CreateContext();
        var row = db.Grants.Single();
        Assert.Equal(2, row.OwnerVersion);
        Assert.Equal(Admin.Value, row.ValidityChangedBy);
        Assert.Equal(GrantReasonCodes.Manual, row.ValidityChangeReasonCode);
    }

    [Fact]
    public async Task GrantStore_ReviewRetainsRowAndAdvancesReviewTimestamp()
    {
        await using var h = await VecTestHarness.CreateAsync();
        var grant = await h.GrantStore.AppendAsync(Tenant, Grant(), "source-a");
        var reviewed = await h.GrantStore.RecordReviewAsync(Tenant, grant.GrantId, Now.AddHours(1), Admin);
        Assert.Equal(Now.AddHours(1), reviewed!.LastReviewedAt);
        Assert.Equal(Admin, reviewed.LastReviewedBy);
        var roundTripped = await h.GrantStore.FindAsync(Tenant, grant.GrantId);
        Assert.Equal(Admin, roundTripped!.LastReviewedBy);
    }

    [Fact]
    public async Task GrantStore_RevocationRetainsRowRevokerAndReason()
    {
        await using var h = await VecTestHarness.CreateAsync();
        var grant = await h.GrantStore.AppendAsync(Tenant, Grant(), "source-a");
        var reason = new GrantReason(GrantReasonCodes.RevocationCompromise, "incident-7");
        var revoked = await h.GrantStore.RevokeAsync(Tenant, grant.GrantId,
            new GrantRevocation(Admin, Now, reason));
        Assert.Equal(GrantStatus.Revoked, revoked!.Status);
        Assert.Equal(reason, revoked.Revocation!.Reason);
        Assert.NotNull(await h.GrantStore.FindAsync(Tenant, grant.GrantId));
    }

    [Fact]
    public async Task GrantStore_RevokedGrantIsImmutableAndRevocationReplayRequiresIdenticalEvidence()
    {
        await using var h = await VecTestHarness.CreateAsync();
        var grant = await h.GrantStore.AppendAsync(Tenant, Grant(), "source-a");
        var revocation = new GrantRevocation(
            Admin, Now, new GrantReason(GrantReasonCodes.RevocationCompromise, "incident-7"));
        var revoked = await h.GrantStore.RevokeAsync(Tenant, grant.GrantId, revocation);

        var replay = await h.GrantStore.RevokeAsync(Tenant, grant.GrantId, revocation);
        Assert.Equal(revoked, replay);
        await using (var db = h.Store.CreateContext())
            Assert.Equal(2, db.Grants.Single().OwnerVersion);

        await Assert.ThrowsAsync<InvalidOperationException>(() => h.GrantStore.ChangeValidityAsync(
            Tenant, grant.GrantId, new GrantValidity(Now, Now.AddDays(1)), Admin,
            new GrantReason(GrantReasonCodes.Manual)));
        await Assert.ThrowsAsync<InvalidOperationException>(() => h.GrantStore.RecordReviewAsync(
            Tenant, grant.GrantId, Now.AddHours(1), Admin));
        await Assert.ThrowsAsync<InvalidOperationException>(() => h.GrantStore.RevokeAsync(
            Tenant, grant.GrantId, revocation with { RevokedBy = new ActorId("other-admin") }));
    }

    [Fact]
    public void GrantStore_HasNoDeleteOrRemoveOperation()
    {
        var names = typeof(IGrantStore).GetMethods().Select(method => method.Name).ToArray();
        Assert.DoesNotContain("DeleteAsync", names);
        Assert.DoesNotContain("RemoveAsync", names);
    }

    private static AccessGrant Grant() => TestSearchAuthorization.Grant(
        Tenant, User, ScopeExpression.Parse("/"), Now);
}

using Microsoft.EntityFrameworkCore;

using Harborline.Api.Foundation.Assets.Common;
using Harborline.Api.Foundation.Crypto;
using Harborline.Api.Foundation.Recovery;
using Harborline.Api.Foundation.Recovery.Erasure;
using Harborline.Api.Foundation.Recovery.TenantKey;
using Harborline.Api.Kernel.Audit;
using Harborline.Api.LocalNodeHost.Data.Search.Vector;
using Harborline.Api.LocalNodeHost.Tests.Search;

using Xunit;

namespace Harborline.Api.LocalNodeHost.Tests.Search.Vector;

/// <summary>
/// DES-0029 kernel-core-ck-6: a subject erasure interrupted after its registry commit is finished by the retry —
/// tombstone, cleartext purge and the SubjectErased audit — each exactly once, over the real durable stores.
/// Faults are injected at the real tombstone table (SQLite trigger), the trail and the propagator.
/// </summary>
public sealed class SubjectErasureCrashResumeTests : IAsyncLifetime
{
    private static readonly DateTimeOffset Now = DateTimeOffset.UnixEpoch.AddYears(56);
    private static readonly TenantId Tenant = TenantId.FromString("tenant-erasure-resume");
    private static readonly SubjectId Alice = new("subject-alice");

    private SearchTestStore _store = null!;
    private readonly FlakyTrail _trail = new();
    private readonly CountingPropagator _propagator = new();

    public async Task InitializeAsync() => _store = await SearchTestStore.CreateAsync();

    public async Task DisposeAsync() => await _store.DisposeAsync();

    [Fact(DisplayName = "ck-6 erasure: a crash after the registry commit is finished by the retry — tombstone, purge and one audit")]
    public async Task CrashAfterRegistryCommit_RetryFinishesTheErasure()
    {
        await ExecuteAsync("CREATE TRIGGER ck6_fault BEFORE INSERT ON search_subject_tombstones BEGIN SELECT RAISE(ABORT, 'ck6'); END;");
        await Assert.ThrowsAnyAsync<Exception>(() => Service().EraseAsync(Request()));
        await ExecuteAsync("DROP TRIGGER ck6_fault;");

        var retry = await Service().EraseAsync(Request());

        Assert.NotNull(retry.Tombstone);
        Assert.Equal(1, await TombstonesAsync());
        Assert.Equal(1, _propagator.Calls);
        Assert.Single(await ErasedAuditsAsync());
    }

    [Fact(DisplayName = "ck-6 erasure: a crash before the audit is finished by the retry with exactly one SubjectErased entry")]
    public async Task CrashBeforeAudit_RetryAuditsOnce()
    {
        _trail.FailNextAppend = true;
        await Assert.ThrowsAnyAsync<Exception>(() => Service().EraseAsync(Request()));

        await Service().EraseAsync(Request());

        Assert.Single(await ErasedAuditsAsync());
        Assert.Equal(1, await TombstonesAsync());
        Assert.True(_propagator.Calls >= 1);
    }

    [Fact(DisplayName = "ck-6 erasure: a crash in the cleartext purge is retried, and the audit records the completed erasure once")]
    public async Task CrashInPurge_RetryPurgesAndAuditsOnce()
    {
        _propagator.FailNext = true;
        await Assert.ThrowsAnyAsync<Exception>(() => Service().EraseAsync(Request()));

        await Service().EraseAsync(Request());

        Assert.Equal(1, _propagator.Calls);
        Assert.Single(await ErasedAuditsAsync());
    }

    [Fact(DisplayName = "ck-6 erasure: a retry of a completed erasure is a no-op — no second audit, no second purge")]
    public async Task CompletedErasure_RetryIsANoOp()
    {
        Assert.Equal(SubjectErasureOutcome.Erased, (await Service().EraseAsync(Request())).Outcome);

        var retry = await Service().EraseAsync(Request());

        Assert.Equal(SubjectErasureOutcome.AlreadyErased, retry.Outcome);
        Assert.Equal(1, _propagator.Calls);
        Assert.Single(await ErasedAuditsAsync());
    }

    // ── helpers ──────────────────────────────────────────────────────────────

    private SubjectErasureService Service() => new(
        new NodeEfSubjectErasureRegistry(_store.Factory, TimeProvider.System),
        new NodeEfSubjectTombstoneStore(_store.Factory),
        _trail,
        new Ed25519Signer(KeyPair.Generate()),
        new NoopTenantKeyDestroyer(),
        new FixedClock(),
        minimumWindow: TimeSpan.Zero,
        propagators: [_propagator]);

    private static SubjectErasureRequest Request() =>
        new(Tenant, Alice, Now, [new ActorId("captain"), new ActorId("officer")], "erasure-ticket");

    private async Task<int> TombstonesAsync()
    {
        await using var db = _store.CreateContext();
        return await db.SubjectTombstones.CountAsync();
    }

    private async Task<List<AuditRecord>> ErasedAuditsAsync()
    {
        var records = new List<AuditRecord>();
        await foreach (var record in _trail.QueryAsync(new AuditQuery(Tenant, AuditEventType.SubjectErased)))
            records.Add(record);
        return records;
    }

    private async Task ExecuteAsync(string sql)
    {
        await using var db = _store.CreateContext();
        await db.Database.ExecuteSqlRawAsync(sql);
    }

    private sealed class FixedClock : IRecoveryClock
    {
        public DateTimeOffset UtcNow() => Now;
    }

    private sealed class NoopTenantKeyDestroyer : ITenantKeyDestroyer
    {
        public Task DestroySubjectKeysAsync(TenantId tenant, SubjectId subject, CancellationToken ct) => Task.CompletedTask;

        public Task DestroyTenantKeysAsync(TenantId tenant, CancellationToken ct) => Task.CompletedTask;
    }

    private sealed class CountingPropagator : ISubjectErasurePropagator
    {
        public bool FailNext { get; set; }

        public int Calls { get; private set; }

        public Task PropagateErasureAsync(TenantId tenant, SubjectId subject, CancellationToken ct)
        {
            if (FailNext)
            {
                FailNext = false;
                throw new InvalidOperationException("ck-6 injected purge fault");
            }

            Calls++;
            return Task.CompletedTask;
        }
    }

    private sealed class FlakyTrail : IAuditTrail
    {
        private readonly InMemoryAuditTrail _inner = new();

        public bool FailNextAppend { get; set; }

        public ValueTask AppendAsync(AuditRecord record, CancellationToken ct = default)
        {
            if (FailNextAppend)
            {
                FailNextAppend = false;
                throw new InvalidOperationException("ck-6 injected trail fault");
            }

            return _inner.AppendAsync(record, ct);
        }

        public IAsyncEnumerable<AuditRecord> QueryAsync(AuditQuery query, CancellationToken ct = default) =>
            _inner.QueryAsync(query, ct);
    }
}

using Xunit;

namespace Harborline.Api.LocalNodeHost.Tests.Search.Vector;

internal static class Vec0NativeEnvironmentCollection
{
    internal const string Name = "vec0 native process environment";
}

/// <summary>
/// Serializes tests that mutate or assert the process-global vec0 opt-in variables. A build-staged native makes
/// the old timing accident observable: a parity test's temporary opt-in can otherwise leak into composition.
/// </summary>
[CollectionDefinition(Vec0NativeEnvironmentCollection.Name, DisableParallelization = true)]
public sealed class Vec0NativeEnvironmentCollectionDefinition;

using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;

using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;

using Harborline.Api.Foundation.Assets.Common;
using Harborline.Api.LocalNodeHost.Data.Search;
using Harborline.Api.LocalNodeHost.Data.Search.Vector;
using Harborline.Api.LocalNodeHost.Data.Search.Vector.Sqlite;

using Xunit;

namespace Harborline.Api.LocalNodeHost.Tests.Search.Vector;

/// <summary>
/// F2 (Slice-1d, HOST-GATED — the Slice-1b deep-review's F2 gate). The real <c>vec0</c> native path
/// (<see cref="Vec0KnnEngine"/>, <see cref="Vec0Native.TryLoad"/>'s load-extension-then-re-disable window,
/// <see cref="Vec0KnnEngine.EnsureTableAsync"/>) has ZERO runtime callers in Slice 1b — it is substrate. Before
/// the real native is trusted on any shipped host, it MUST pass a NATIVE-GATED parity probe that exercises the
/// vec0 engine through the SAME clip / no-neighbour-leak assertions the brute-force suite uses, AND asserts
/// <c>load_extension</c> is unreachable post-load (the spike-R-6 re-disable security property).
/// </summary>
/// <remarks>
/// <para>
/// <b>This test is NATIVE-GATED / skippable.</b> This Intel CI host has no bundled <c>vec0</c> native (per the
/// spike), so <see cref="Vec0Native.ResolveNativePath"/> returns null and the assertions that REQUIRE the
/// native return early as a documented skip — the test is GREEN-as-skip here. On a host WITH the native
/// (po-mac Mac native run + po-win Windows R-6 probe — the FLAGGED follow-on), it RUNS the real parity +
/// re-disable checks. The clip semantics are identical to the brute-force engine (both build their
/// <c>record_id</c> WHERE via <see cref="VecRecordClip"/>); this proves the NATIVE applies that constraint as a
/// true pre-filter, which the brute-force suite cannot.
/// </para>
/// <para>
/// <b>DO NOT enable <c>HARBORLINE_KG_VEC0_REAL</c> on any shipped host until this passes on that host's native.</b>
/// </para>
/// </remarks>
[Collection(Vec0NativeEnvironmentCollection.Name)]
public sealed class Vec0NativeParityF2Tests
{
    private const int Dim = 64;
    private static readonly TenantId TenantA = TenantId.FromString("tenant-A");

    /// <summary>
    /// True when the real vec0 native is available to load on this host — the precondition for the parity
    /// probe. False on a host without the bundled native (this Intel CI host) ⇒ the native-requiring tests
    /// return early as a documented skip.
    /// </summary>
    private static bool NativeAvailable()
    {
        // The native is only loadable when opted-in AND a path resolves. We DON'T require the opt-in env var to
        // be set for the test to RUN the probe (the test opts in itself below); we only need the native present.
        return Vec0Native.ResolveNativePath() is not null;
    }

    [Fact(DisplayName = "F2 (host-gated): the vec0 native, WHEN present, loads on a keyed SQLCipher connection and re-disables load_extension (spike R-6)")]
    public async Task Vec0_Native_Loads_And_ReDisables_Load_Extension()
    {
        if (!NativeAvailable())
        {
            // SKIP on a host without the native (this Intel CI host). The brute-force engine carries the
            // security semantics here; this probe is the po-mac/po-win follow-on. Documented green-as-skip.
            Assert.Null(Vec0Native.ResolveNativePath());
            return;
        }

        // Opt in for the duration of this probe (the test arms the native path it is validating).
        Environment.SetEnvironmentVariable(Vec0Native.RealVecEnvVar, "1");
        try
        {
            await using var h = await VecTestHarness.CreateAsync();
            await using var ctx = h.Store.CreateContext();
            var connection = (SqliteConnection)ctx.Database.GetDbConnection();
            await connection.OpenAsync();

            // The native loads on the OPEN, KEYED (PRAGMA key) connection — the spike-R-6 property.
            var loaded = Vec0Native.TryLoad(connection);
            Assert.True(loaded, "vec0 native is present but failed to load on the keyed connection");

            // SECURITY (spike R-6): after the trusted load, load_extension(...) must be UNREACHABLE from SQL.
            await using var cmd = connection.CreateCommand();
            cmd.CommandText = "SELECT load_extension('definitely-not-a-real-extension');";
            // The re-disable means this throws (load_extension is not callable), NOT that it silently loads
            // an arbitrary library. Any exception is the correct fail-closed outcome.
            await Assert.ThrowsAnyAsync<Exception>(() => cmd.ExecuteScalarAsync());
        }
        finally
        {
            Environment.SetEnvironmentVariable(Vec0Native.RealVecEnvVar, null);
        }
    }

    [Fact(DisplayName = "F2 (host-gated): vec0 applies tenant + record clip as TRUE pre-filters (no neighbour leak)")]
    public async Task Vec0_Native_Knn_Clip_Is_A_True_PreFilter()
    {
        if (!NativeAvailable())
        {
            // SKIP — the parity probe requires the native. Green-as-skip on this host (po-mac/po-win follow-on).
            Assert.Null(Vec0Native.ResolveNativePath());
            return;
        }

        Environment.SetEnvironmentVariable(Vec0Native.RealVecEnvVar, "1");
        try
        {
            await using var h = await VecTestHarness.CreateAsync();

            // Index two records with a real acceleration sink driving the vec0 table; one forbidden record
            // embeds the EXACT query text (globally nearest), one allowed record embeds far text.
            await using var ctx = h.Store.CreateContext();
            var connection = (SqliteConnection)ctx.Database.GetDbConnection();
            await connection.OpenAsync();
            Assert.True(Vec0Native.TryLoad(connection));

            var engine = new Vec0KnnEngine(Dim);
            await engine.EnsureTableAsync(connection, CancellationToken.None);

            // Seed the vec0 table directly (the acceleration sink's role) — forbidden row = exact query code.
            var stub = h.StubEmbedder(Dim);
            var qVec = (await stub.EmbedAsync("__q__", "tenant-A", null, "the exact query phrase here")).Vector;
            var allowedVec = (await stub.EmbedAsync("__a__", "tenant-A", null, "completely different text")).Vector;
            await InsertVec0Row(connection, "inv-allowed", "tenant-A", BinaryQuantization.Pack(allowedVec));
            await InsertVec0Row(connection, "inv-forbidden", "tenant-A", BinaryQuantization.Pack(qVec));
            await InsertVec0Row(connection, "inv-other-tenant", "tenant-B", BinaryQuantization.Pack(qVec));

            await using var tx = (SqliteTransaction)await connection.BeginTransactionAsync();

            // The record scope authorizes inv-allowed and a globally-nearest row from another tenant. Both the
            // tenant metadata constraint and record clip must be true prefilters: the only result is the farther
            // same-tenant row. The same-tenant inv-forbidden row proves the record clip independently.
            var scope = AuthorizedRecordScope.ForRecordIds(new[] { "inv-allowed", "inv-other-tenant" });
            var hits = await engine.KnnAsync(connection, tx, "tenant-A", scope, qVec, 5, CancellationToken.None);

            var ids = hits.Select(x => x.RecordId).ToArray();
            Assert.Equal(new[] { "inv-allowed" }, ids); // no neighbour leak — the spike R-1 property on the native.
        }
        finally
        {
            Environment.SetEnvironmentVariable(Vec0Native.RealVecEnvVar, null);
        }
    }

    private static async Task InsertVec0Row(
        SqliteConnection connection, string recordId, string tenantId, byte[] code)
    {
        await using var cmd = connection.CreateCommand();
        cmd.CommandText = Vec0AccelerationSink.UpsertCommandText;
        cmd.Parameters.AddWithValue("$r", recordId);
        cmd.Parameters.AddWithValue("$t", tenantId);
        cmd.Parameters.AddWithValue("$e", code);
        await cmd.ExecuteNonQueryAsync();
    }
}

