using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;

using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;

using Harborline.Api.Blocks.AccessGrant;
using Harborline.Api.Foundation.Assets.Common;
using Harborline.Api.Foundation.IdentityAtlas;
using Harborline.Api.Foundation.IdentityAtlas.Permissions;
using Harborline.Api.Foundation.Recovery.Erasure;
using Harborline.Api.LocalNodeHost.Data.Search;
using Harborline.Api.LocalNodeHost.Data.Search.Vector;

using Xunit;

namespace Harborline.Api.LocalNodeHost.Tests.Search.Vector;

/// <summary>
/// The security core of KG-search Slice 1b (ADR 0135 KG-search F3-lift amendment): the EXACT clip on the vec
/// path (no unclipped vec read; returns k from the allowed set even when the global-nearest are forbidden), the
/// G-2 same-transaction revoke-TOCTOU closure, and the G-6 erase-subject crypto-shred proof — all run against
/// the REAL encrypted per-subject-keyed index via the native-free brute-force KNN engine (which applies the same
/// exact clip + per-subject decrypt as the production vec0 path).
/// </summary>
public sealed class VecClipAndCryptoTests
{
    private const int Dim = 64;
    private static readonly DateTimeOffset Now = DateTimeOffset.UnixEpoch.AddYears(56);
    private static readonly TenantId TenantA = TenantId.FromString("tenant-A");
    private static readonly ActorId Alice = new("alice");

    private static AccessGrant ActiveGrant(
        ScopeExpression scope, GrantResidency residency = GrantResidency.Cache, DateTimeOffset? revokedAt = null) =>
        TestSearchAuthorization.Grant(TenantA, Alice, scope, Now, residency,
            revocation: revokedAt is null ? null : new GrantRevocation(
                new ActorId("owner"), revokedAt.Value,
                new GrantReason(GrantReasonCodes.RevocationOffboarding)));

    /// <summary>Resolve the scope + run a clipped KNN inside ONE read transaction (the G-2 path), returning ids nearest-first.</summary>
    private static async Task<IReadOnlyList<string>> ClippedKnnAsync(
        VecTestHarness h, string queryText, int k = 10)
    {
        var queryArtifact = await h.StubEmbedder(Dim).EmbedAsync("__q__", "tenant-A", null, queryText);
        var queryVec = queryArtifact.Vector;

        await using var ctx = h.Store.CreateContext();
        var connection = (SqliteConnection)ctx.Database.GetDbConnection();
        await connection.OpenAsync();
        await using var tx = (SqliteTransaction)await connection.BeginTransactionAsync();

        var scope = await h.ScopeResolver
            .ResolveAsync(connection, tx, TenantA, Alice, Now, default);
        if (scope.IsEmpty)
        {
            return Array.Empty<string>();
        }

        var hits = await h.KnnEngine.KnnAsync(connection, tx, "tenant-A", scope, queryVec, k, default);
        return hits.Select(x => x.RecordId).ToArray();
    }

    // ── G-1 — the EXACT clip on the vec path ──────────────────────────────────────────────────────────────

    [Fact(DisplayName = "G-1 vec clip: KNN returns ONLY records the principal's ForRecords grant authorizes")]
    public async Task Vec_Knn_Returns_Only_Authorized()
    {
        await using var h = await VecTestHarness.CreateAsync();
        var indexer = h.Indexer(allowStub: true, dimension: Dim);
        await indexer.IndexRecordAsync("inv-1", "tenant-A", "subj-1", "alpha rent invoice", SearchResidency.Cache);
        await indexer.IndexRecordAsync("inv-2", "tenant-A", "subj-2", "alpha rent invoice", SearchResidency.Cache);

        await h.GrantStore.SaveAsync(
            TenantA, ActiveGrant(ScopeExpression.Parse("/records/inv-1")), 0);

        var ids = await ClippedKnnAsync(h, "alpha rent invoice");
        Assert.Equal(new[] { "inv-1" }, ids);
    }

    [Fact(DisplayName = "G-1 vec clip is a TRUE PRE-FILTER: returns the authorized record even when the GLOBAL-NEAREST vectors are all FORBIDDEN (no neighbour leak)")]
    public async Task Vec_Knn_Returns_Authorized_When_Global_Nearest_Forbidden()
    {
        await using var h = await VecTestHarness.CreateAsync();
        var indexer = h.Indexer(allowStub: true, dimension: Dim);

        // inv-forbidden-* embed the EXACT query text (Hamming distance 0 — globally nearest). inv-allowed embeds
        // DIFFERENT text (farther). Alice may see ONLY inv-allowed. A post-filter would return the global top-k
        // (all forbidden) → 0 rows; a TRUE pre-filter returns inv-allowed (the spike R-1 proof).
        await indexer.IndexRecordAsync("inv-forbidden-1", "tenant-A", "s1", "the exact query phrase here", SearchResidency.Cache);
        await indexer.IndexRecordAsync("inv-forbidden-2", "tenant-A", "s2", "the exact query phrase here", SearchResidency.Cache);
        await indexer.IndexRecordAsync("inv-allowed", "tenant-A", "s3", "a totally different far away text", SearchResidency.Cache);

        await h.GrantStore.SaveAsync(
            TenantA, ActiveGrant(ScopeExpression.Parse("/records/inv-allowed")), 0);

        var ids = await ClippedKnnAsync(h, "the exact query phrase here", k: 5);
        Assert.Equal(new[] { "inv-allowed" }, ids);
        Assert.DoesNotContain("inv-forbidden-1", ids);
        Assert.DoesNotContain("inv-forbidden-2", ids);
    }

    [Fact(DisplayName = "G-1 vec clip: NO grant ⇒ NO vec rows (fail-closed, never a tenant-wide fall-through)")]
    public async Task Vec_No_Grant_Returns_Nothing()
    {
        await using var h = await VecTestHarness.CreateAsync();
        await h.Indexer(allowStub: true, dimension: Dim)
            .IndexRecordAsync("inv-1", "tenant-A", "subj-1", "alpha rent", SearchResidency.Cache);

        // Alice holds NO grant.
        var ids = await ClippedKnnAsync(h, "alpha rent");
        Assert.Empty(ids);
    }

    [Fact(DisplayName = "G-1 vec clip: read authority cannot be laundered through another grant's residency")]
    public async Task Vec_Read_Authority_Residency_And_Scope_Must_Come_From_One_Grant()
    {
        await using var h = await VecTestHarness.CreateAsync();
        await h.GrantStore.AppendAsync(
            TenantA, ActiveGrant(ScopeExpression.Parse("/"), GrantResidency.OnlineOnly), "online-reader");
        await h.GrantStore.AppendAsync(
            TenantA,
            TestSearchAuthorization.Grant(
                TenantA, Alice, ScopeExpression.Parse("/"), Now, GrantResidency.Cache, canRead: false),
            "cache-without-read");

        await using var ctx = h.Store.CreateContext();
        var connection = (SqliteConnection)ctx.Database.GetDbConnection();
        await connection.OpenAsync();
        await using var tx = (SqliteTransaction)await connection.BeginTransactionAsync();

        var scope = await h.ScopeResolver.ResolveAsync(
            connection, tx, TenantA, Alice, Now, default);

        Assert.True(scope.IsEmpty);
    }

    [Fact(DisplayName = "G-1 vec clip: a WholeTenant grant sees all tenant rows but NEVER cross-tenant")]
    public async Task Vec_WholeTenant_Stays_In_Tenant()
    {
        await using var h = await VecTestHarness.CreateAsync();
        var indexer = h.Indexer(allowStub: true, dimension: Dim);
        await indexer.IndexRecordAsync("a-1", "tenant-A", "subj-1", "shared text", SearchResidency.Cache);
        await indexer.IndexRecordAsync("a-2", "tenant-A", "subj-2", "shared text", SearchResidency.Cache);
        // A row in a DIFFERENT tenant (same file is per-tenant in prod; here we just plant a foreign tenant_id).
        await indexer.IndexRecordAsync("b-1", "tenant-B", "subj-3", "shared text", SearchResidency.Cache);

        await h.GrantStore.SaveAsync(TenantA, ActiveGrant(ScopeExpression.Parse("/")), 0);

        var ids = await ClippedKnnAsync(h, "shared text");
        Assert.Contains("a-1", ids);
        Assert.Contains("a-2", ids);
        Assert.DoesNotContain("b-1", ids); // tenant predicate keeps the WholeTenant scope in-tenant.
    }

    // ── G-2 — same-transaction revoke-TOCTOU closure ─────────────────────────────────────────────────────

    [Fact(DisplayName = "G-2: a revoke that has landed before the scan is SEEN — the revoked grant authorizes nothing (same-snapshot)")]
    public async Task G2_Landed_Revoke_Is_Seen()
    {
        await using var h = await VecTestHarness.CreateAsync();
        await h.Indexer(allowStub: true, dimension: Dim)
            .IndexRecordAsync("inv-1", "tenant-A", "subj-1", "alpha rent", SearchResidency.Cache);

        var grant = ActiveGrant(ScopeExpression.Parse("/records/inv-1"));
        await h.GrantStore.SaveAsync(TenantA, grant, 0);

        // Before: Alice sees inv-1.
        Assert.Equal(new[] { "inv-1" }, await ClippedKnnAsync(h, "alpha rent"));

        // Revoke lands. The next scan resolves grants in its OWN transaction and sees the revocation.
        await h.GrantStore.RevokeAsync(TenantA, grant.GrantId, 1, Now.AddSeconds(-1));

        Assert.Empty(await ClippedKnnAsync(h, "alpha rent"));
    }

    [Fact(DisplayName = "G-2: the grant read + the KNN scan run in ONE transaction over the SAME file (single snapshot — a mid-query revoke cannot widen the materialized allow-set)")]
    public async Task G2_Grant_Read_And_Scan_Share_One_Transaction()
    {
        await using var h = await VecTestHarness.CreateAsync();
        await h.Indexer(allowStub: true, dimension: Dim)
            .IndexRecordAsync("inv-1", "tenant-A", "subj-1", "alpha rent", SearchResidency.Cache);
        await h.GrantStore.SaveAsync(
            TenantA, ActiveGrant(ScopeExpression.Parse("/records/inv-1")), 0);

        await using var ctx = h.Store.CreateContext();
        var connection = (SqliteConnection)ctx.Database.GetDbConnection();
        await connection.OpenAsync();
        await using var tx = (SqliteTransaction)await connection.BeginTransactionAsync();

        // Grant read inside the transaction.
        var scope = await h.ScopeResolver.ResolveAsync(connection, tx, TenantA, Alice, Now, default);
        Assert.False(scope.IsEmpty);

        // The KNN scan inside the SAME transaction sees a consistent snapshot — the grant read it just did and
        // the scan are one snapshot, so no mid-query revoke (which would be a separate write) can widen this set.
        var queryArtifact = await h.StubEmbedder(Dim).EmbedAsync("__q__", "tenant-A", null, "alpha rent");
        var hits = await h.KnnEngine.KnnAsync(connection, tx, "tenant-A", scope, queryArtifact.Vector, 10, default);
        Assert.Equal(new[] { "inv-1" }, hits.Select(x => x.RecordId).ToArray());
    }

    // ── G-6 — erase-subject ⇒ vectors gone/unreadable (crypto-shred; the index is NOT a shred bypass) ──────

    [Fact(DisplayName = "G-6: crypto-shredding a subject makes their embeddings UNREADABLE — they vanish from KNN while other subjects remain")]
    public async Task G6_Erase_Subject_Makes_Embeddings_Unreadable()
    {
        await using var h = await VecTestHarness.CreateAsync();
        var indexer = h.Indexer(allowStub: true, dimension: Dim);
        await indexer.IndexRecordAsync("inv-alice", "tenant-A", "subject-alice", "alpha rent invoice", SearchResidency.Cache);
        await indexer.IndexRecordAsync("inv-bob", "tenant-A", "subject-bob", "alpha rent invoice", SearchResidency.Cache);

        await h.GrantStore.SaveAsync(TenantA, ActiveGrant(ScopeExpression.Parse("/")), 0);

        // Before erasure: both records are retrievable.
        var before = await ClippedKnnAsync(h, "alpha rent invoice");
        Assert.Contains("inv-alice", before);
        Assert.Contains("inv-bob", before);

        // Crypto-shred subject-alice (destroy their per-subject key via the erasure tombstone).
        await h.Erasure.MarkErasedAsync(TenantA, new SubjectId("subject-alice"));

        // After: subject-alice's embedding is undecryptable (the sub-key is gone) ⇒ it drops out; subject-bob's
        // is untouched. The index is NOT a shred bypass — even though the ciphertext row still physically exists,
        // it cannot be read.
        var after = await ClippedKnnAsync(h, "alpha rent invoice");
        Assert.DoesNotContain("inv-alice", after);
        Assert.Contains("inv-bob", after);
    }

    [Fact(DisplayName = "G-6: PurgeSubjectAsync physically removes a shredded subject's vec rows (durable purge of the partially-invertible blob)")]
    public async Task G6_Purge_Subject_Removes_Rows()
    {
        await using var h = await VecTestHarness.CreateAsync();
        var indexer = h.Indexer(allowStub: true, dimension: Dim);
        await indexer.IndexRecordAsync("inv-alice-1", "tenant-A", "subject-alice", "rent one", SearchResidency.Cache);
        await indexer.IndexRecordAsync("inv-alice-2", "tenant-A", "subject-alice", "rent two", SearchResidency.Cache);
        await indexer.IndexRecordAsync("inv-bob", "tenant-A", "subject-bob", "rent three", SearchResidency.Cache);

        var purged = await indexer.PurgeSubjectAsync("tenant-A", "subject-alice");
        Assert.Equal(2, purged);

        await using var ctx = h.Store.CreateContext();
        var remaining = await ctx.VecRows.Select(v => v.RecordId).ToListAsync();
        Assert.Equal(new[] { "inv-bob" }, remaining);
    }

    [Fact(DisplayName = "G-6: indexing a record for an ALREADY-erased subject fails closed — the embedding is never written")]
    public async Task G6_Index_For_Erased_Subject_Fails_Closed()
    {
        await using var h = await VecTestHarness.CreateAsync();
        await h.Erasure.MarkErasedAsync(TenantA, new SubjectId("subject-gone"));
        var indexer = h.Indexer(allowStub: true, dimension: Dim);

        await Assert.ThrowsAsync<FieldEncryptionDeniedAtIndexException>(() =>
            indexer.IndexRecordAsync("inv-gone", "tenant-A", "subject-gone", "rent", SearchResidency.Cache));

        await using var ctx = h.Store.CreateContext();
        Assert.Equal(0, await ctx.VecRows.CountAsync());
    }
}

using System;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Threading.Tasks;

using Harborline.Api.Foundation.Recovery.Erasure;
using Harborline.Api.LocalNodeHost.Data.Search;
using Harborline.Api.LocalNodeHost.Data.Search.Vector;
using Harborline.Api.LocalNodeHost.Data.Search.Vector.Sqlite;

using Xunit;

namespace Harborline.Api.LocalNodeHost.Tests.Search.Vector;

/// <summary>
/// <b>VecClipArchFence</b> — the G-1 fail-closed clip fence for the KG-search Slice 1b VECTOR path (ADR 0135
/// KG-search F3-lift amendment). The Slice-0 <c>SearchClipArchFence</c> proved an un-clipped FTS5 / graph read is
/// structurally impossible; this extends that to the new vec0 KNN + <c>search_vec_rows</c> surfaces, plus fences
/// the M1 no-fake-as-real gate and the G-6 per-subject-keyed index. It proves an un-clipped vector read — and an
/// unverified-model index write — is structurally impossible, not merely discouraged:
/// <list type="number">
///   <item>the SOLE producer of a vec query's <c>record_id</c> clip is <see cref="VecRecordClip"/>;</item>
///   <item>no production source OTHER than the vec0 engine issues a raw <c>vec0 MATCH</c> (the
///     <c>… embedding MATCH …</c> query signature);</item>
///   <item>no production source OTHER than the indexer / brute-force engine / acceleration sink reads
///     <c>search_vec_rows</c> (the per-subject-encrypted content table) — the same content-table side-door
///     closure as the Slice-0 fence, and a non-vacuity check;</item>
///   <item>the M1 gate (<see cref="KgModelFloorGate"/>) is the registered-floor allow-list, and the stub
///     sentinel is NOT a registered floor (a fake can't pin as real); and</item>
///   <item>the per-subject crypto is the load-bearing G-6 boundary: a row's embedding is sealed under the
///     record's subject sub-key.</item>
/// </list>
/// </summary>
public sealed class VecClipArchFence
{
    private static readonly Assembly ProductionAssembly = typeof(NodeVecIndexer).Assembly;

    // ── FENCE 1 — the read service has NO clip-omitting constructor (the G-2 resolver is required) ───────────

    [Fact(DisplayName = "vec G-1 fence: NodeVecSearchReadService REQUIRES the transactional scope resolver — no clip-omitting ctor")]
    public void VecReadService_Requires_The_Clip_Resolver()
    {
        var ctors = typeof(NodeVecSearchReadService)
            .GetConstructors(BindingFlags.Public | BindingFlags.Instance);
        Assert.NotEmpty(ctors);
        Assert.All(ctors, c =>
            Assert.Contains(c.GetParameters(),
                p => typeof(IAuthorizedRecordSetProjection).IsAssignableFrom(p.ParameterType)));
    }

    // ── FENCE 2 — no raw vec0 MATCH outside the vec0 engine ──────────────────────────────────────────────────

    [Fact(DisplayName = "vec G-1 fence: no production source OTHER than Vec0KnnEngine issues a raw `embedding MATCH` (vec0 KNN) query")]
    public void Only_Vec0Engine_Issues_A_Raw_Vec0_Match()
    {
        var dir = LocateVectorSourceDir();
        var offenders = Directory
            .EnumerateFiles(dir, "*.cs", SearchOption.AllDirectories)
            .Where(f => !Path.GetFileName(f).Equals("Vec0KnnEngine.cs", StringComparison.Ordinal))
            .Where(f => NonDocLines(f).Any(line => System.Text.RegularExpressions.Regex.IsMatch(
                line, @"embedding\s+MATCH", System.Text.RegularExpressions.RegexOptions.IgnoreCase)))
            .Select(Path.GetFileName)
            .OrderBy(n => n, StringComparer.Ordinal)
            .ToArray();

        Assert.True(
            offenders.Length == 0,
            "Only Vec0KnnEngine may issue a raw vec0 `embedding MATCH` KNN. Un-clipped vec0 readers: "
            + string.Join(", ", offenders));
    }

    // ── FENCE 3 — the vec query's record clip has ONE producer (VecRecordClip) ─────────────────────────────

    [Fact(DisplayName = "vec G-1 fence: the SOLE producer of a vec query's record_id IN(...) clip is VecRecordClip")]
    public void VecRecordClip_Is_The_Sole_Clip_Producer()
    {
        var dir = LocateVectorSourceDir();
        // A `record_id IN (` literal CONSTRUCTED in CODE anywhere OTHER than VecRecordClip would be a hand-rolled
        // clip that could omit the scope. Both engines + the read service build their clip via
        // VecRecordClip.Build(...). XML-doc-comment lines (`///`) legitimately DESCRIBE the clip — they are not
        // code, so they are excluded (a doc-comment that names the clip pattern is the intended documentation).
        var offenders = Directory
            .EnumerateFiles(dir, "*.cs", SearchOption.AllDirectories)
            .Where(f => !Path.GetFileName(f).Equals("VecRecordClip.cs", StringComparison.Ordinal))
            .Where(f => NonDocLines(f).Any(line => System.Text.RegularExpressions.Regex.IsMatch(
                line, @"record_id\s+IN\s*\(", System.Text.RegularExpressions.RegexOptions.IgnoreCase)))
            .Select(Path.GetFileName)
            .OrderBy(n => n, StringComparer.Ordinal)
            .ToArray();

        Assert.True(
            offenders.Length == 0,
            "Only VecRecordClip may produce a vec `record_id IN (...)` clip in CODE. Hand-rolled clip producers: "
            + string.Join(", ", offenders));
    }

    /// <summary>
    /// The file's lines with any COMMENT content removed (whole-line <c>///</c> / <c>//</c> lines dropped, and
    /// trailing <c>// …</c> comments stripped) — so a fence matches actual CODE, not the prose in a doc-comment
    /// or an inline comment that legitimately DESCRIBES the clip pattern.
    /// </summary>
    private static System.Collections.Generic.IEnumerable<string> NonDocLines(string path)
    {
        foreach (var raw in File.ReadLines(path))
        {
            var trimmed = raw.TrimStart();
            if (trimmed.StartsWith("//", StringComparison.Ordinal))
            {
                continue; // whole-line comment (covers both /// and //).
            }
            // Strip a trailing line-comment (// …). Not perfect for a // inside a string literal, but our SQL
            // never embeds the token "//", so this is safe for the clip-construction fences.
            var commentIdx = raw.IndexOf("//", StringComparison.Ordinal);
            yield return commentIdx >= 0 ? raw[..commentIdx] : raw;
        }
    }

    // ── FENCE 4 — the encrypted content table is read ONLY by the indexer / brute-force engine / sink ───────

    [Fact(DisplayName = "vec G-1 fence: no production source OTHER than the indexer + brute-force engine + acceleration sink reads search_vec_rows / the VecRows DbSet")]
    public void Only_Allowed_Consumers_Read_The_VecRows_Table()
    {
        var dir = LocateVectorSourceDir();

        // (a) raw SQL: a FROM/JOIN against search_vec_rows (in CODE, not a doc-comment description).
        var rawSqlOffenders = Directory
            .EnumerateFiles(dir, "*.cs", SearchOption.AllDirectories)
            .Where(f => !IsAllowedVecRowsConsumer(Path.GetFileName(f)))
            .Where(f => NonDocLines(f).Any(line => System.Text.RegularExpressions.Regex.IsMatch(
                line, @"\b(?:FROM|JOIN)\s+search_vec_rows\b",
                System.Text.RegularExpressions.RegexOptions.IgnoreCase)))
            .Select(Path.GetFileName)
            .OrderBy(n => n, StringComparer.Ordinal)
            .ToArray();
        Assert.True(
            rawSqlOffenders.Length == 0,
            "Only the indexer + brute-force engine may FROM/JOIN search_vec_rows. Offenders: "
            + string.Join(", ", rawSqlOffenders));

        // (b) the EF DbSet: a `.VecRows` access.
        var dbSetOffenders = Directory
            .EnumerateFiles(dir, "*.cs", SearchOption.AllDirectories)
            .Where(f => !IsAllowedVecRowsDbSetConsumer(Path.GetFileName(f)))
            .Where(f => System.Text.RegularExpressions.Regex.IsMatch(
                File.ReadAllText(f), @"\.VecRows\b"))
            .Select(Path.GetFileName)
            .OrderBy(n => n, StringComparer.Ordinal)
            .ToArray();
        Assert.True(
            dbSetOffenders.Length == 0,
            "Only the indexer may consume the VecRows DbSet. Offenders: " + string.Join(", ", dbSetOffenders));
    }

    [Fact(DisplayName = "vec G-1 fence is non-vacuous: the search_vec_rows / VecRows regexes DO fire on a planted un-clipped read")]
    public void VecRows_Fence_Is_NonVacuous()
    {
        const string plantedSql = "SELECT * FROM search_vec_rows WHERE tenant_id = $t;";
        Assert.Matches(@"\b(?:FROM|JOIN)\s+search_vec_rows\b", plantedSql);
        Assert.DoesNotMatch(@"\b(?:FROM|JOIN)\s+search_vec_rows\b", "e.ToTable(\"search_vec_rows\");");

        const string plantedDbSet = "var leak = await ctx.VecRows.ToListAsync();";
        Assert.Matches(@"\.VecRows\b", plantedDbSet);

        const string plantedMatch = "WHERE embedding MATCH $q AND k = $k";
        Assert.Matches(@"embedding\s+MATCH", plantedMatch);
    }

    // ── FENCE 5 — M1: the stub sentinel is NOT a registered floor (a fake can't pin as real) ────────────────

    [Fact(DisplayName = "M1 fence: the stub sentinel is NOT a registered floor; the only registered floor is bge-m3")]
    public void M1_Stub_Is_Not_A_Registered_Floor()
    {
        Assert.False(KgModelFloorGate.IsRegisteredFloor(KgModelFloorGate.StubModelSentinel));
        Assert.False(KgModelFloorGate.IsRegisteredFloor("unknown-model"));
        Assert.False(KgModelFloorGate.IsRegisteredFloor(null));
        Assert.True(KgModelFloorGate.IsRegisteredFloor(KgModelFloor.BgeM3.Id));
        Assert.Equal(new[] { "bge-m3" }, KgModelFloor.Registered.Select(f => f.Id).ToArray());
    }

    // ── FENCE 6 — G-6: the per-subject encryptor is a REQUIRED indexer dependency (no plaintext-embedding path) ──

    [Fact(DisplayName = "G-6 fence: NodeVecIndexer REQUIRES the per-subject field encryptor — no path writes a plaintext embedding")]
    public void Indexer_Requires_The_Subject_Encryptor()
    {
        var ctors = typeof(NodeVecIndexer).GetConstructors(BindingFlags.Public | BindingFlags.Instance);
        Assert.NotEmpty(ctors);
        Assert.All(ctors, c =>
            Assert.Contains(c.GetParameters(),
                p => p.ParameterType == typeof(Harborline.Api.Foundation.Recovery.Crypto.ISubjectFieldEncryptor)));
    }

    [Fact(DisplayName = "production assembly is Harborline.Api.LocalNodeHost (the fences scan the shipped host)")]
    public void Production_Assembly_Is_The_Host()
    {
        Assert.Equal("Harborline.Api.LocalNodeHost", ProductionAssembly.GetName().Name);
    }

    private static bool IsAllowedVecRowsConsumer(string fileName) =>
        fileName is "NodeVecIndexer.cs" or "BruteForceKnnEngine.cs" or "NodeLocalSearchDbContext.cs";

    private static bool IsAllowedVecRowsDbSetConsumer(string fileName) =>
        // The indexer writes/reads VecRows; the DbContext DECLARES the DbSet (excluded — it does not consume it).
        fileName is "NodeVecIndexer.cs" or "NodeLocalSearchDbContext.cs";

    private static string LocateVectorSourceDir()
    {
        var dir = new DirectoryInfo(AppContext.BaseDirectory);
        while (dir is not null)
        {
            var candidate = Path.Combine(dir.FullName, "apps", "local-node-host", "Data", "Search", "Vector");
            if (Directory.Exists(candidate))
            {
                return candidate;
            }
            dir = dir.Parent;
        }
        throw new DirectoryNotFoundException(
            "Could not locate apps/local-node-host/Data/Search/Vector from " + AppContext.BaseDirectory);
    }
}

using System;
using System.Threading.Tasks;

using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;

using Harborline.Api.Blocks.AccessGrant;
using Harborline.Api.Foundation.Recovery.Crypto;
using Harborline.Api.Foundation.Recovery;
using Harborline.Api.Foundation.Recovery.Erasure;
using Harborline.Api.Foundation.Recovery.TenantKey;
using Harborline.Api.LocalNodeHost.Data.Search;
using Harborline.Api.LocalNodeHost.Data.Search.Vector;
using Harborline.Api.LocalNodeHost.Data.Search.Vector.BruteForce;
using Harborline.Api.LocalNodeHost.Data.Search.Vector.Sqlite;
using Harborline.Api.LocalNodeHost.Tests.Identity;

using Xunit;

namespace Harborline.Api.LocalNodeHost.Tests.Search.Vector;

/// <summary>
/// Verifies the Slice 1b DI composition (<see cref="NodeVecSearchComposition.AddNodeKnowledgeGraphVectorSearch"/>)
/// wires the security-load-bearing pieces correctly: the durable EF grant store REPLACES the in-memory stopgap
/// (G-2), the native-free brute-force engine is selected without the explicit real-vec opt-in, and the M1
/// fail-closed posture holds when no real provider is registered.
/// </summary>
[Collection(Vec0NativeEnvironmentCollection.Name)]
public sealed class VecCompositionTests
{
    private static ServiceProvider BuildProvider(IKgEmbeddingProvider? provider, bool allowStub)
    {
        var services = new ServiceCollection();

        // A throwaway in-memory EF context factory just to satisfy the indexer/engine ctors (the composition
        // test does not run a real DB scan — it asserts the wiring).
        services.AddDbContextFactory<NodeLocalSearchDbContext>(opt =>
            opt.UseSqlite("Data Source=:memory:"));

        // The Slice-0 in-memory grant store is registered FIRST (the stopgap the composition must replace).
        services.AddSingleton<IGrantStore, InMemoryGrantStore>();
        services.AddSingleton<IAuthorizationClosureReader>(new FixedAuthorizationClosure());

        // The per-subject crypto substrate the indexer + engine depend on (real types, dev key provider).
        var tenantKeys = new InMemoryTenantKeyProvider();
        var erasure = new InMemorySubjectErasureRegistry();
        services.AddSingleton<ISubjectErasureRegistry>(erasure);
        services.AddSingleton<ISubjectFieldEncryptor>(new SubjectKeyFieldEncryptor(tenantKeys, erasure));
        services.AddSingleton<ISubjectFieldDecryptor>(new SubjectKeyFieldDecryptor(
            tenantKeys, erasure, new SystemRecoveryClock(TimeProvider.System)));

        services.AddNodeKnowledgeGraphVectorSearch(provider, allowStub);
        return services.BuildServiceProvider();
    }

    [Fact(DisplayName = "composition: AddNodeKnowledgeGraphVectorSearch REPLACES the in-memory grant store with the durable NodeEfGrantStore (G-2)")]
    public void Composition_Replaces_GrantStore_With_NodeEf()
    {
        using var sp = BuildProvider(new StubKgEmbeddingProvider(64), allowStub: true);
        var grantStore = sp.GetRequiredService<IGrantStore>();
        Assert.IsType<NodeEfGrantStore>(grantStore);
    }

    [Fact(DisplayName = "composition: the G-2 same-transaction scope resolver is registered")]
    public void Composition_Registers_The_Transactional_Projection()
    {
        using var sp = BuildProvider(new StubKgEmbeddingProvider(64), allowStub: true);
        Assert.IsType<ClosureAuthorizedRecordSetProjection>(
            sp.GetRequiredService<IAuthorizedRecordSetProjection>());
    }

    [Fact(DisplayName = "composition: a host without the real-vec opt-in selects the native-free brute-force KNN engine")]
    public void Composition_Selects_BruteForce_When_Native_Is_Not_Opted_In()
    {
        var previous = Environment.GetEnvironmentVariable(Vec0Native.RealVecEnvVar);
        Environment.SetEnvironmentVariable(Vec0Native.RealVecEnvVar, null);
        try
        {
            // The staged native remains inert until the explicit real-vec opt-in is present.
            using var sp = BuildProvider(new StubKgEmbeddingProvider(64), allowStub: true);
            Assert.IsType<BruteForceKnnEngine>(sp.GetRequiredService<IVecKnnEngine>());
        }
        finally
        {
            Environment.SetEnvironmentVariable(Vec0Native.RealVecEnvVar, previous);
        }
    }

    [Fact(DisplayName = "composition: with NO embedding provider, the indexer is still registered but its ingest fails closed (provider.kg_floor_unavailable)")]
    public async Task Composition_No_Provider_Indexer_Fails_Closed()
    {
        await using var h = await VecTestHarness.CreateAsync();
        // Build a real (file-backed) indexer with no provider via the harness to actually exercise the throw.
        var indexer = h.IndexerNoProvider();
        var ex = await Assert.ThrowsAsync<KgFloorUnavailableException>(() =>
            indexer.IndexRecordAsync("inv-1", "tenant-A", "subj-1", "rent", SearchResidency.Cache));
        Assert.Contains(KgFloorUnavailableException.ReasonCode, ex.Message);
    }

    // ── Slice 1d wire-live ──────────────────────────────────────────────────────────────────────────────────

    [Fact(DisplayName = "wire-live: the indexer + read service are registered + resolvable end-to-end when a provider is wired")]
    public void WireLive_Indexer_And_ReadService_Resolve()
    {
        using var sp = BuildProvider(new StubKgEmbeddingProvider(64), allowStub: true);
        // The indexer resolves (write side) and the read service resolves (read side) — the layer is reachable.
        Assert.NotNull(sp.GetRequiredService<NodeVecIndexer>());
        Assert.NotNull(sp.GetRequiredService<NodeVecSearchReadService>());
    }

    [Fact(DisplayName = "wire-live F1: the KgVecIndexSubjectErasurePropagator is registered into the erasure-flow propagator collection")]
    public void WireLive_F1_Propagator_Is_Registered()
    {
        using var sp = BuildProvider(new StubKgEmbeddingProvider(64), allowStub: true);
        // The erasure flow resolves IEnumerable<ISubjectErasurePropagator>; the KG propagator MUST be in it, or a
        // crypto-shred would leave the cleartext vec0 residue (the F1 gap). This is the composition-side proof
        // that the F1 wire is present (the functional purge proof is in VecErasureFlowF1Tests).
        var propagators = sp.GetServices<ISubjectErasurePropagator>();
        Assert.Contains(propagators, p => p is KgVecIndexSubjectErasurePropagator);
    }

    [Fact(DisplayName = "wire-live: with no provider, the read service is NOT registered (no real query surface), but the indexer + F1 propagator still are")]
    public void WireLive_No_Provider_Has_Indexer_And_Propagator_But_No_ReadService()
    {
        using var sp = BuildProvider(provider: null, allowStub: false);
        Assert.NotNull(sp.GetRequiredService<NodeVecIndexer>());
        Assert.Contains(sp.GetServices<ISubjectErasurePropagator>(), p => p is KgVecIndexSubjectErasurePropagator);
        // No provider ⇒ no query embedder ⇒ the read service is not registered (a query has nothing to embed with).
        Assert.Null(sp.GetService<NodeVecSearchReadService>());
    }

    [Fact(DisplayName = "legacy migration provider is install-secret and refuses application reads for an erased subject")]
    public async Task WireLive_RootSeedKeyProvider_Is_Install_Secret_And_Shred_Fails_Closed()
    {
        var tenant = Harborline.Foundation.Assets.Common.TenantId.FromString("tenant-A");
        var subject = new SubjectId("subject-1");

        var seedA = new byte[32];
        var seedB = new byte[32];
        for (var i = 0; i < 32; i++) { seedA[i] = (byte)i; seedB[i] = (byte)(255 - i); }

        var provA = new RootSeedTenantKeyProvider(seedA);
        var provB = new RootSeedTenantKeyProvider(seedB);
        var stub = new InMemoryTenantKeyProvider();

        var keyA = (await provA.DeriveKeyAsync(tenant, "encrypted-field-aes", default)).ToArray();
        var keyB = (await provB.DeriveKeyAsync(tenant, "encrypted-field-aes", default)).ToArray();
        var keyStub = (await stub.DeriveKeyAsync(tenant, "encrypted-field-aes", default)).ToArray();

        // Different root seeds ⇒ different DEKs (install-secret), and NEITHER equals the dev-stub's shared-salt key.
        Assert.False(keyA.AsSpan().SequenceEqual(keyB));
        Assert.False(keyA.AsSpan().SequenceEqual(keyStub));

        // Crypto-shred fail-closed is preserved: a shredded subject's sub-key is un-derivable.
        var erasure = new InMemorySubjectErasureRegistry();
        await erasure.MarkErasedAsync(tenant, subject, default);
        await Assert.ThrowsAsync<SubjectErasedException>(() =>
            provA.DeriveSubjectKeyAsync(tenant, subject, "encrypted-field-aes", erasure, default));
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;

using Microsoft.EntityFrameworkCore;

using Harborline.Api.Foundation.Assets.Common;
using Harborline.Api.Foundation.Crypto;
using Harborline.Api.Foundation.Recovery;
using Harborline.Api.Foundation.Recovery.Erasure;
using Harborline.Api.Foundation.Recovery.TenantKey;
using Harborline.Api.Kernel.Audit;
using Harborline.Api.LocalNodeHost.Data.Search;
using Harborline.Api.LocalNodeHost.Data.Search.Vector;

using Xunit;

namespace Harborline.Api.LocalNodeHost.Tests.Search.Vector;

/// <summary>
/// F1 (Slice-1d, BINDING — the Slice-1b deep-review's F1 gate). The subject-erasure FLOW
/// (<see cref="ISubjectErasureService.EraseAsync"/>) must drop the crypto-shredded subject's DERIVED CLEARTEXT
/// <c>vec0</c> residue, not just its durable encrypted rows. Slice 1b built
/// <see cref="NodeVecIndexer.PurgeSubjectAsync"/> (which deletes both the durable rows and the cleartext sink
/// rows) but left it with NO erasure-flow caller — so on a real-<c>vec0</c> host a shred would leave the
/// cleartext bit code resident. The <see cref="KgVecIndexSubjectErasurePropagator"/> closes that: registered
/// into the recovery erasure flow, a real <c>EraseAsync</c> now purges the vec0 sink.
/// </summary>
/// <remarks>
/// The real <c>vec0</c> native is host-gated (Intel CI has none), so the cleartext-cache contract is proven
/// here against a recording <see cref="IVecAccelerationSink"/> that stands in for the <c>search_vec0</c>
/// table. The wire under test — erasure flow ⇒ propagator ⇒ purge — is identical whether the sink is the
/// recording stand-in or the real native; only the sink impl differs (covered by the F2 host-gated native
/// parity probe).
/// </remarks>
public sealed class VecErasureFlowF1Tests
{
    private const int Dim = 64;
    private static readonly DateTimeOffset Now = DateTimeOffset.UnixEpoch.AddYears(56);
    private static readonly TenantId TenantA = TenantId.FromString("tenant-A");
    private static readonly SubjectId Alice = new("subject-alice");
    private static readonly SubjectId Bob = new("subject-bob");

    [Fact(DisplayName = "F1: a subject crypto-shred via the ERASURE FLOW drops the cleartext vec0 residue (durable rows AND cleartext sink) — bob survives")]
    public async Task EraseFlow_Purges_Cleartext_Vec0_Residue()
    {
        await using var h = await VecTestHarness.CreateAsync();
        var sink = new RecordingVec0Sink();
        var indexer = h.IndexerWithSink(sink, dimension: Dim);

        await indexer.IndexRecordAsync("inv-alice-1", "tenant-A", "subject-alice", "rent one", SearchResidency.Cache);
        await indexer.IndexRecordAsync("inv-alice-2", "tenant-A", "subject-alice", "rent two", SearchResidency.Cache);
        await indexer.IndexRecordAsync("inv-bob", "tenant-A", "subject-bob", "rent three", SearchResidency.Cache);

        // Pre-shred: the cleartext vec0 sink holds the partially-invertible bit code for BOTH subjects.
        Assert.Equal(new[] { "inv-alice-1", "inv-alice-2", "inv-bob" }, sink.RecordIdsSorted());

        // Build the REAL erasure flow with the KG-vec propagator wired in (the F1 wire), and run a valid shred.
        var erasureSvc = BuildErasureServiceWithPropagator(h.Erasure, indexer);
        var result = await erasureSvc.EraseAsync(ValidRequest(Alice), CancellationToken.None);
        Assert.Equal(SubjectErasureOutcome.Erased, result.Outcome);

        // F1 ASSERTION: the cleartext vec0 sink leaves ZERO residue of the shredded subject (the partially-
        // invertible bit code is gone), while bob's cleartext row survives.
        Assert.Equal(new[] { "inv-bob" }, sink.RecordIdsSorted());

        // And the durable per-subject-encrypted rows for the shredded subject are gone too; bob remains.
        await using var ctx = h.Store.CreateContext();
        var durable = await ctx.VecRows.Select(v => v.RecordId).ToListAsync();
        Assert.Equal(new[] { "inv-bob" }, durable);
    }

    [Fact(DisplayName = "F1 NON-VACUOUS: WITHOUT the propagator wired, an erasure-flow shred leaves the cleartext vec0 residue resident (the gap the wire closes)")]
    public async Task NonVacuous_WithoutPropagator_CleartextResidueRemains()
    {
        await using var h = await VecTestHarness.CreateAsync();
        var sink = new RecordingVec0Sink();
        var indexer = h.IndexerWithSink(sink, dimension: Dim);

        await indexer.IndexRecordAsync("inv-alice-1", "tenant-A", "subject-alice", "rent one", SearchResidency.Cache);
        await indexer.IndexRecordAsync("inv-bob", "tenant-A", "subject-bob", "rent three", SearchResidency.Cache);

        // The SAME erasure flow, but with NO propagator registered (the pre-F1 state).
        var erasureSvc = BuildErasureServiceWithoutPropagator(h.Erasure);
        var result = await erasureSvc.EraseAsync(ValidRequest(Alice), CancellationToken.None);
        Assert.Equal(SubjectErasureOutcome.Erased, result.Outcome);

        // The durable encrypted row is undecryptable (sub-key gone) — the shred boundary is closed regardless.
        // BUT the cleartext vec0 residue for the shredded subject SURVIVES: this is exactly the leak F1 closes,
        // so this test would PASS-as-leak only when the wire is absent — proving the wire's test is non-vacuous.
        Assert.Contains("inv-alice-1", sink.RecordIdsSorted());
    }

    private static SubjectErasureService BuildErasureServiceWithPropagator(
        InMemorySubjectErasureRegistry registry, NodeVecIndexer indexer) =>
        new(
            registry,
            new InMemorySubjectTombstoneStore(),
            new NoopAuditTrail(),
            new Ed25519Signer(KeyPair.Generate()),
            new NoopTenantKeyDestroyer(),
            new FixedClock(Now),
            TimeSpan.Zero,
            new ISubjectErasurePropagator[] { new KgVecIndexSubjectErasurePropagator(indexer) });

    private static SubjectErasureService BuildErasureServiceWithoutPropagator(
        InMemorySubjectErasureRegistry registry) =>
        new(
            registry,
            new InMemorySubjectTombstoneStore(),
            new NoopAuditTrail(),
            new Ed25519Signer(KeyPair.Generate()),
            new NoopTenantKeyDestroyer(),
            new FixedClock(Now),
            TimeSpan.Zero,
            propagators: null);

    private static SubjectErasureRequest ValidRequest(SubjectId subject) => new(
        TenantA, subject, Now,
        new[] { new ActorId("captain"), new ActorId("officer") }, "erasure-ticket");

    /// <summary>An in-memory stand-in for the derived cleartext <c>vec0</c> acceleration table.</summary>
    private sealed class RecordingVec0Sink : IVecAccelerationSink
    {
        private readonly Dictionary<string, byte[]> _rows = new(StringComparer.Ordinal);

        public Task UpsertAsync(string recordId, string tenantId, byte[] packedCode, CancellationToken ct)
        {
            _rows[recordId] = packedCode;
            return Task.CompletedTask;
        }

        public Task DeleteAsync(string recordId, CancellationToken ct)
        {
            _rows.Remove(recordId);
            return Task.CompletedTask;
        }

        public string[] RecordIdsSorted() => _rows.Keys.OrderBy(k => k, StringComparer.Ordinal).ToArray();
    }

    private sealed class FixedClock : IRecoveryClock
    {
        private readonly DateTimeOffset _instant;
        public FixedClock(DateTimeOffset instant) => _instant = instant;
        public DateTimeOffset UtcNow() => _instant;
    }

    private sealed class NoopAuditTrail : IAuditTrail
    {
        public ValueTask AppendAsync(AuditRecord record, CancellationToken ct = default) => ValueTask.CompletedTask;

        public async IAsyncEnumerable<AuditRecord> QueryAsync(
            AuditQuery query,
            [System.Runtime.CompilerServices.EnumeratorCancellation] CancellationToken ct = default)
        {
            await Task.CompletedTask;
            yield break;
        }
    }

    private sealed class NoopTenantKeyDestroyer : ITenantKeyDestroyer
    {
        public Task DestroySubjectKeysAsync(TenantId tenant, SubjectId subject, CancellationToken ct) =>
            Task.CompletedTask;

        public Task DestroyTenantKeysAsync(TenantId tenant, CancellationToken ct) => Task.CompletedTask;
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;

using Microsoft.EntityFrameworkCore;

using Harborline.Api.LocalNodeHost.Data.Search;
using Harborline.Api.LocalNodeHost.Data.Search.Vector;

using Xunit;

namespace Harborline.Api.LocalNodeHost.Tests.Search.Vector;

/// <summary>
/// The M1 (no-fake-as-real) + G-3 (OnlineOnly⇒never-index) + G-5 (versioned projection / dimension) gates of the
/// KG-search Slice 1b vector indexer (ADR 0135 KG-search F3-lift amendment).
/// </summary>
public sealed class VecIndexerGateTests
{
    private const int Dim = 64;

    private static KgEmbeddingArtifact Artifact(
        string recordId, string model, int? vectorWidth = null, int? declaredDim = null, string? subject = "subj-1") =>
        new(
            RecordId: recordId,
            TenantId: "tenant-A",
            SubjectId: subject,
            Vector: Enumerable.Range(0, vectorWidth ?? Dim).Select(i => (float)((i % 3) - 1)).ToArray(),
            Dimension: declaredDim ?? vectorWidth ?? Dim,
            Model: model,
            ModelVersion: "1.0");

    // ── M1 — a stub-model artifact is REJECTED by a production indexer ────────────────────────────────────

    [Fact(DisplayName = "M1: a STUB-model artifact is REFUSED by a production indexer (allowStubModel=false) — fake can't pin as real")]
    public async Task M1_Stub_Model_Refused_By_Production_Indexer()
    {
        await using var h = await VecTestHarness.CreateAsync();
        var prodIndexer = new NodeVecIndexer(
            h.Store.Factory, new StubKgEmbeddingProvider(Dim), h.SubjectEncryptor,
            accelerationSink: null, allowStubModel: false);

        var ex = await Assert.ThrowsAsync<KgFloorUnavailableException>(() =>
            prodIndexer.IndexRecordAsync("inv-1", "tenant-A", "subj-1", "rent invoice", SearchResidency.Cache));

        Assert.Equal(KgModelFloorGate.StubModelSentinel, ex.RefusedModel);

        // And nothing landed in the index.
        await using var ctx = h.Store.CreateContext();
        Assert.Equal(0, await ctx.VecRows.CountAsync());
    }

    [Fact(DisplayName = "M1: an artifact with a FABRICATED 'bge-m3' label but produced by the stub is admitted ONLY because it self-identifies — a forged unknown model is REFUSED")]
    public async Task M1_Unknown_Model_Refused()
    {
        await using var h = await VecTestHarness.CreateAsync();
        var indexer = h.Indexer(allowStub: true, dimension: Dim);

        // An artifact claiming a model that is NOT a registered floor and NOT the known stub sentinel.
        var forged = Artifact("inv-x", model: "totally-made-up-model");
        var ex = await Assert.ThrowsAsync<KgFloorUnavailableException>(() =>
            indexer.IndexArtifactAsync(forged, SearchResidency.Cache));
        Assert.Equal("totally-made-up-model", ex.RefusedModel);
    }

    [Fact(DisplayName = "M1: a non-opted-in host with NO provider fails closed (provider.kg_floor_unavailable) — never indexes an unverifiable artifact")]
    public async Task M1_No_Provider_Fails_Closed()
    {
        await using var h = await VecTestHarness.CreateAsync();
        var indexer = h.IndexerNoProvider();

        var ex = await Assert.ThrowsAsync<KgFloorUnavailableException>(() =>
            indexer.IndexRecordAsync("inv-1", "tenant-A", "subj-1", "rent invoice", SearchResidency.Cache));
        Assert.Contains(KgFloorUnavailableException.ReasonCode, ex.Message);
    }

    [Fact(DisplayName = "M1: a REGISTERED floor id (bge-m3) at the correct dimension IS admitted")]
    public async Task M1_Registered_Floor_Admitted()
    {
        await using var h = await VecTestHarness.CreateAsync();
        // allowStub is irrelevant — this is a REAL floor id. Use a 1024-dim artifact (the bge-m3 dimension).
        var indexer = new NodeVecIndexer(
            h.Store.Factory, embedder: null, h.SubjectEncryptor, accelerationSink: null, allowStubModel: false);

        var real = Artifact("inv-real", KgModelFloor.BgeM3.Id, vectorWidth: KgModelFloor.BgeM3.Dimension);
        await indexer.IndexArtifactAsync(real, SearchResidency.Cache);

        await using var ctx = h.Store.CreateContext();
        var row = await ctx.VecRows.SingleAsync();
        Assert.Equal("inv-real", row.RecordId);
        Assert.Equal(KgModelFloor.BgeM3.Id, row.Model);
    }

    // ── G-5 — model / dimension mismatch is a hard fault ──────────────────────────────────────────────────

    [Fact(DisplayName = "G-5: a bge-m3 artifact whose vector width != the floor dimension is REJECTED (dimension mismatch)")]
    public async Task G5_Dimension_Mismatch_Rejected()
    {
        await using var h = await VecTestHarness.CreateAsync();
        var indexer = new NodeVecIndexer(
            h.Store.Factory, embedder: null, h.SubjectEncryptor, accelerationSink: null, allowStubModel: false);

        // bge-m3 declares 1024 dims; hand it a 64-wide vector — a hard G-5 fault.
        var wrong = Artifact("inv-wrong", KgModelFloor.BgeM3.Id, vectorWidth: 64, declaredDim: 64);
        var ex = await Assert.ThrowsAsync<KgFloorUnavailableException>(() =>
            indexer.IndexArtifactAsync(wrong, SearchResidency.Cache));
        Assert.Contains("dimension", ex.Message, StringComparison.OrdinalIgnoreCase);
    }

    [Fact(DisplayName = "G-5: an artifact whose declared Dimension disagrees with its actual vector width is REJECTED")]
    public async Task G5_Declared_Vs_Actual_Width_Mismatch_Rejected()
    {
        await using var h = await VecTestHarness.CreateAsync();
        var indexer = h.Indexer(allowStub: true, dimension: Dim);

        // Stub model (admitted by allowStub) but declared dimension lies about the vector width.
        var lying = Artifact("inv-lie", KgModelFloorGate.StubModelSentinel, vectorWidth: Dim, declaredDim: Dim + 8);
        await Assert.ThrowsAsync<KgFloorUnavailableException>(() =>
            indexer.IndexArtifactAsync(lying, SearchResidency.Cache));
    }

    [Fact(DisplayName = "G-5: every indexed row carries model + modelVersion + dimension (versioned projection)")]
    public async Task G5_Row_Carries_Model_Version_Dimension()
    {
        await using var h = await VecTestHarness.CreateAsync();
        await h.Indexer(allowStub: true, dimension: Dim)
            .IndexRecordAsync("inv-1", "tenant-A", "subj-1", "rent invoice", SearchResidency.Cache);

        await using var ctx = h.Store.CreateContext();
        var row = await ctx.VecRows.SingleAsync();
        Assert.Equal(KgModelFloorGate.StubModelSentinel, row.Model);
        Assert.False(string.IsNullOrEmpty(row.ModelVersion));
        Assert.Equal(Dim, row.Dimension);
    }

    // ── G-3 — OnlineOnly ⇒ never-index (vec path) ─────────────────────────────────────────────────────────

    [Fact(DisplayName = "G-3: the vector indexer REFUSES an OnlineOnly record — no embedding enters the index")]
    public async Task G3_OnlineOnly_Never_Indexed()
    {
        await using var h = await VecTestHarness.CreateAsync();
        var indexer = h.Indexer(allowStub: true, dimension: Dim);

        var indexed = await indexer.IndexRecordAsync(
            "inv-online", "tenant-A", "subj-1", "online-only secret", SearchResidency.OnlineOnly);

        Assert.False(indexed); // refused.
        await using var ctx = h.Store.CreateContext();
        Assert.Equal(0, await ctx.VecRows.CountAsync());
    }

    [Fact(DisplayName = "G-3: a record flipping to OnlineOnly DELETES its pre-existing indexed embedding (delete-on-revoke)")]
    public async Task G3_Flip_To_OnlineOnly_Deletes_Existing()
    {
        await using var h = await VecTestHarness.CreateAsync();
        var indexer = h.Indexer(allowStub: true, dimension: Dim);

        await indexer.IndexRecordAsync("inv-1", "tenant-A", "subj-1", "cache rent", SearchResidency.Cache);
        await using (var ctx = h.Store.CreateContext())
        {
            Assert.Equal(1, await ctx.VecRows.CountAsync());
        }

        // The grant is revoked + re-issued online-only ⇒ residency flips ⇒ the embedding must be purged.
        var stillIndexed = await indexer.IndexRecordAsync(
            "inv-1", "tenant-A", "subj-1", "cache rent", SearchResidency.OnlineOnly);
        Assert.False(stillIndexed);

        await using (var ctx = h.Store.CreateContext())
        {
            Assert.Equal(0, await ctx.VecRows.CountAsync());
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;

using Microsoft.Data.Sqlite;

using Harborline.Api.Blocks.AccessGrant;
using Harborline.Api.Foundation.Assets.Common;
using Harborline.Api.Foundation.IdentityAtlas;
