namespace Harborline.Api.LocalNodeHost.Tests.Sync;

[Collection("Harborline process environment")]
public sealed class ComposedHostTransportTests
{
    // The root seed override keeps the composed boot off the platform keystore, which Linux and
    // macOS runners do not provide (PlatformNotSupportedException: libsecret is Wave 2).
    private const string RootSeedHex =
        "3463463463463463463463463463463463463463463463463463463463463463";

    [Fact]
    public async Task Known_network_with_mdns_enabled_composes_the_tier_one_mdns_transport()
    {
        var dataDirectory = CreateDataDirectory();
        var previousEnableMdns = Environment.GetEnvironmentVariable("LocalNode__Sync__EnableMdns");
        var previousNetworkTrust = Environment.GetEnvironmentVariable("LocalNode__Sync__NetworkTrust");
        var previousRootSeedHex = Environment.GetEnvironmentVariable("LocalNode__RootSeedHex");
        using var deadline = new CancellationTokenSource(TimeSpan.FromMinutes(3));

        try
        {
            Environment.SetEnvironmentVariable("LocalNode__Sync__EnableMdns", "true");
            Environment.SetEnvironmentVariable("LocalNode__Sync__NetworkTrust", "Known");
            Environment.SetEnvironmentVariable("LocalNode__RootSeedHex", RootSeedHex);

            await LocalNodeHostRuntime.StartAsync(
                "ticket-450-mdns-transport",
                dataDirectory,
                deadline.Token,
                finalServiceRegistration: services =>
                    services.AddSingleton<IPeerTransport, InertManagedRelayTransport>());

            var selector = Assert.IsType<DefaultTransportSelector>(
                LocalNodeHostRuntime.CurrentServices!.GetRequiredService<ITransportSelector>());

            Assert.IsType<MdnsPeerTransport>(selector.Tier1Transport);
        }
        finally
        {
            await LocalNodeHostRuntime.StopAsync(deadline.Token);
            Environment.SetEnvironmentVariable("LocalNode__Sync__EnableMdns", previousEnableMdns);
            Environment.SetEnvironmentVariable("LocalNode__Sync__NetworkTrust", previousNetworkTrust);
            Environment.SetEnvironmentVariable("LocalNode__RootSeedHex", previousRootSeedHex);
            DeleteDataDirectory(dataDirectory);
        }
    }

    [Fact]
    public async Task Default_composition_does_not_register_a_transport_selector()
    {
        var dataDirectory = CreateDataDirectory();
        var previousRootSeedHex = Environment.GetEnvironmentVariable("LocalNode__RootSeedHex");
        using var deadline = new CancellationTokenSource(TimeSpan.FromMinutes(3));

        try
        {
            Environment.SetEnvironmentVariable("LocalNode__RootSeedHex", RootSeedHex);
            await LocalNodeHostRuntime.StartAsync(
                "ticket-450-default-transport",
                dataDirectory,
                deadline.Token);

            Assert.Null(LocalNodeHostRuntime.CurrentServices!.GetService<ITransportSelector>());
        }
        finally
        {
            await LocalNodeHostRuntime.StopAsync(deadline.Token);
            Environment.SetEnvironmentVariable("LocalNode__RootSeedHex", previousRootSeedHex);
            DeleteDataDirectory(dataDirectory);
        }
    }

    private static string CreateDataDirectory()
    {
        var directory = Path.Combine(Path.GetTempPath(), $"ticket-450-{Guid.NewGuid():N}");
        Directory.CreateDirectory(directory);
        return directory;
    }

    private static void DeleteDataDirectory(string directory)
    {
        if (Directory.Exists(directory))
            Directory.Delete(directory, recursive: true);
    }

    private sealed class InertManagedRelayTransport : IPeerTransport
    {
        public TransportTier Tier => TransportTier.ManagedRelay;
        public bool IsAvailable => false;

        public Task<PeerEndpoint?> ResolvePeerAsync(PeerId peer, CancellationToken ct) =>
            Task.FromResult<PeerEndpoint?>(null);

        public Task<IDuplexStream> ConnectAsync(PeerId peer, CancellationToken ct) =>
            Task.FromException<IDuplexStream>(new InvalidOperationException("The inert test relay cannot connect."));
    }
}

using Harborline.Api.Kernel.Security.Crypto;
using Harborline.Api.Kernel.Sync.Handshake;
using Harborline.Api.Kernel.Sync.Protocol;

namespace Harborline.Api.LocalNodeHost.Tests.Sync;

public sealed class DeltaStateVectorProtocolTests
{
    [Fact]
    public void GossipPing_RoundTrips_PerDocumentStateVectors()
    {
        var expected = new Dictionary<string, byte[]>(StringComparer.Ordinal)
        {
            ["contacts"] = [0x01, 0xA4, 0x7F],
            ["comms"] = [0x02, 0x19],
        };
        var message = new GossipPingMessage(
            VectorClock: new Dictionary<string, ulong> { ["node-a"] = 7 },
            PeerMembershipDelta: new MembershipDelta(Array.Empty<byte[]>(), Array.Empty<byte[]>()),
            MonotonicNonce: 11,
            StateVectors: expected);

        var decoded = GossipPingMessage.FromCbor(message.ToCbor());

        Assert.Equal(expected.Keys.Order(), decoded.StateVectors.Keys.Order());
        Assert.Equal(expected["contacts"], decoded.StateVectors["contacts"]);
        Assert.Equal(expected["comms"], decoded.StateVectors["comms"]);
    }

    [Fact]
    public async Task Handshake_Negotiates_DeltaStateVectorCapability()
    {
        var endpoint = $"state-vector-handshake-{Guid.NewGuid():N}";
        await using var responderTransport = new InMemorySyncDaemonTransport(endpoint);
        await using var initiatorTransport = new InMemorySyncDaemonTransport();
        using var timeout = new CancellationTokenSource(TimeSpan.FromSeconds(5));
        var signer = new Ed25519Signer();
        var initiator = Identity(signer, "11111111111111111111111111111111");
        var responder = Identity(signer, "22222222222222222222222222222222");

        var responderTask = Task.Run(async () =>
        {
            await foreach (var connection in responderTransport.ListenAsync(timeout.Token))
            {
                await using (connection)
                {
                    return await HandshakeProtocol.RespondAsync(
                        connection,
                        responder,
                        proposal => new AckMessage(
                            proposal.ProposedStreams,
                            Array.Empty<Rejection>(),
                            GrantedCapabilities: proposal.Capabilities
                                .Where(capability => capability == SyncCapabilities.DeltaStateVector)
                                .ToArray()),
                        timeout.Token, timeProvider: TimeProvider.System);
                }
            }

            throw new InvalidOperationException("Responder did not accept the handshake connection.");
        }, timeout.Token);

        await using var initiatorConnection = await initiatorTransport.ConnectAsync(endpoint, timeout.Token);
        var initiatorResult = await HandshakeProtocol.InitiateAsync(
            initiatorConnection,
            initiator,
            timeout.Token, timeProvider: TimeProvider.System);
        var responderResult = await responderTask;

        Assert.Contains(SyncCapabilities.DeltaStateVector, initiatorResult.GrantedCapabilities);
        Assert.Contains(SyncCapabilities.DeltaStateVector, responderResult.GrantedCapabilities);
    }

    [Fact]
    public void DefaultSupportedVersions_RetainsCurrentAndPreviousVersion()
    {
        Assert.Equal(
            ["1.0.0", "0.9.0"],
            HandshakeProtocol.DefaultSupportedVersions);
    }

    private static LocalIdentity Identity(IEd25519Signer signer, string nodeId)
    {
        var (publicKey, privateKey) = signer.GenerateKeyPair();
        return new LocalIdentity(
            Convert.FromHexString(nodeId),
            publicKey,
            signer,
            privateKey,
            HandshakeProtocol.DefaultSchemaVersion,
            HandshakeProtocol.DefaultSupportedVersions,
            Capabilities: [SyncCapabilities.DeltaStateVector]);
    }
}

using Microsoft.Extensions.Options;

using Harborline.Api.Kernel.Security.Crypto;
using Harborline.Api.Kernel.Sync.Gossip;
using Harborline.Api.Kernel.Sync.Handshake;
using Harborline.Api.Kernel.Sync.Identity;
using Harborline.Api.Kernel.Sync.Protocol;

namespace Harborline.Api.LocalNodeHost.Tests.Sync;

public sealed class DeltaStreamDeadlineTests
{
    /// <summary>
    /// T-987: how long the test waits for the named deadline error, under the two-ceiling convention
    /// (<see cref="LoadCeiling"/>). The wait covers the handshake plus the 1 s deadline, which the
    /// daemon arms on the real clock (<c>CancelAfter</c>) once the handshake completes, so a fake clock
    /// cannot drive it. The quiet ceiling keeps the original 3 s. The busy ceiling is derived, not tuned:
    /// a working daemon emits the error no later than the 30 s connect timeout (which bounds connect and
    /// handshake) plus the 1 s deadline, so 45 s lies past every on-time arrival. With the thread pool
    /// starved, the base test timed out 5 of 5 runs; the error's continuation alone reached the test
    /// 20-25 s late; under that load the fixed test passed 20 of 20 in 24.7-28.6 s. The handler takes only <see cref="ErrorCode.DeltaStreamDeadlineExceeded"/>, so no
    /// other failure can satisfy the wait, and a daemon that never names the deadline still fails.
    /// </summary>
    private static readonly TimeSpan DeadlineErrorCeiling = LoadCeiling.Pick(
        quiet: TimeSpan.FromSeconds(3),
        busy: TimeSpan.FromSeconds(45));

    [Fact]
    public async Task StalledDeltaStream_EmitsNamedDeadlineError()
    {
        var endpoint = $"delta-deadline-{Guid.NewGuid():N}";
        await using var initiatorTransport = new InMemorySyncDaemonTransport($"{endpoint}-initiator");
        await using var responderTransport = new InMemorySyncDaemonTransport(endpoint);
        using var responderStop = new CancellationTokenSource();
        var signer = new Ed25519Signer();
        var initiatorIdentity = Identity(signer, '1');
        var responderIdentity = HandshakeIdentity(signer, '2');
        var responderTask = StallAfterHandshakeAsync(
            responderTransport,
            responderIdentity,
            responderStop.Token);

        await using var daemon = new GossipDaemon(
            initiatorTransport,
            new VectorClock(),
            Options.Create(new GossipDaemonOptions
            {
                PeerPickCount = 1,
                ConnectTimeoutSeconds = 30,
                DeltaStreamDeadlineSeconds = 1,
                DeadPeerBackoffSeconds = 1,
            }),
            new InMemoryNodeIdentityProvider(initiatorIdentity),
            signer, timeProvider: TimeProvider.System);
        daemon.AddPeer(endpoint, responderIdentity.PublicKey);
        var deadlineError = new TaskCompletionSource<GossipFrameEventArgs>(
            TaskCreationOptions.RunContinuationsAsynchronously);
        daemon.FrameReceived += (_, frame) =>
        {
            if (frame.ErrorCode == ErrorCode.DeltaStreamDeadlineExceeded)
            {
                deadlineError.TrySetResult(frame);
            }
        };

        var push = daemon.TriggerPushAsync(OutboundSyncLane.Background, CancellationToken.None);
        var observed = await deadlineError.Task.WaitAsync(DeadlineErrorCeiling);

        Assert.Equal(GossipFrameType.GossipError, observed.FrameType);
        Assert.Contains("delta stream deadline", observed.Summary, StringComparison.OrdinalIgnoreCase);
        await push;

        responderStop.Cancel();
        await responderTask;
    }

    private static async Task StallAfterHandshakeAsync(
        InMemorySyncDaemonTransport transport,
        LocalIdentity identity,
        CancellationToken ct)
    {
        try
        {
            await foreach (var connection in transport.ListenAsync(ct))
            {
                await using (connection)
                {
                    await HandshakeProtocol.RespondAsync(
                        connection,
                        identity,
                        proposal => new AckMessage(
                            proposal.ProposedStreams,
                            Array.Empty<Rejection>(),
                            proposal.Capabilities),
                        ct, timeProvider: TimeProvider.System);
                    await Task.Delay(Timeout.InfiniteTimeSpan, ct);
                }
            }
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
        }
    }

    private static NodeIdentity Identity(IEd25519Signer signer, char digit)
    {
        var (publicKey, privateKey) = signer.GenerateKeyPair();
        return new NodeIdentity(new string(digit, 32), publicKey, privateKey);
    }

    private static LocalIdentity HandshakeIdentity(IEd25519Signer signer, char digit)
    {
        var identity = Identity(signer, digit);
        return new LocalIdentity(
            identity.NodeIdBytes,
            identity.PublicKey,
            signer,
            identity.PrivateKey,
            HandshakeProtocol.DefaultSchemaVersion,
            HandshakeProtocol.DefaultSupportedVersions,
            Capabilities: [SyncCapabilities.DeltaStateVector]);
    }
}

