    private static TenantForkService CreateService(
        ICrdtEngine engine,
        INodeIdentityFactory identities,
        IAuditLog? audit = null,
        ITenantForkRosterStore? rosterStore = null,
        IOutboundSequenceAllocator? sequences = null,
        ITenantForkObligationAuthority? obligations = null,
        ITenantForkSnapshotTransfer? transfer = null,
        IAuthorizationClosureReader? authorization = null) =>
        new(
            engine,
            identities,
            obligations ?? new AllowingObligationAuthority(),
            audit ?? new InMemoryAuditLog(new InMemoryAssetStorage()),
            rosterStore ?? new InMemoryTenantForkRosterStore(),
            sequences ?? new RecordingSequenceAllocator(),
            transfer ?? InMemoryTenantForkSnapshotTransfer.Instance,
            TimeProvider.System,
            authorization ?? new Harborline.Api.LocalNodeHost.Tests.Identity.FixedAuthorizationClosure(
                PermissionAtomSet.Of(PermissionAtom.Parse("tenant-fork:create@/"))));

    private static AccessGrant WholeTenantGrant() => new(
        GrantId.New(),
        new TenantId("tenant-a"),
        new ActorId("operator-a"),
        AccessGrantAuthorizationSeed.MemberRole,
        ScopeExpression.Parse("/"), GrantResidency.Cache,
        new GrantValidity(DateTimeOffset.MinValue), GranterKind.Person,
        new ActorId("owner-a"), DateTimeOffset.UnixEpoch,
        new GrantProvenance(GrantSourceKind.Manual, new GrantReason(GrantReasonCodes.Manual),
            new ActorId("owner-a")), DateTimeOffset.UnixEpoch);

    private static HelloMessage HelloFor(NodeIdentity identity) => new(
        identity.NodeIdBytes,
        "1",
        ["1"],
        identity.PublicKey,
        0,
        []);

    private sealed class QueueIdentityFactory(params NodeIdentity[] identities) : INodeIdentityFactory
    {
        private readonly Queue<NodeIdentity> _identities = new(identities);

        public int CreatedCount { get; private set; }

        public NodeIdentity CreateFresh()
        {
            CreatedCount++;
            return _identities.Dequeue();
        }
    }

    private sealed class CorruptingSnapshotTransfer : ITenantForkSnapshotTransfer
    {
        public ReadOnlyMemory<byte> Transfer(ReadOnlyMemory<byte> snapshot)
        {
            var corrupted = snapshot.ToArray();
            corrupted[^1] ^= 0xff;
            return corrupted;
        }
    }

    private sealed class RecordingSequenceAllocator : IOutboundSequenceAllocator
    {
        public List<string> ReservedNodeIds { get; } = [];

        public ValueTask<ulong> ReserveNextAsync(string nodeId, CancellationToken ct = default)
        {
            ReservedNodeIds.Add(nodeId);
            return ValueTask.FromResult(1UL);
        }
    }

    private sealed class FixedRetentionResolver(DateTimeOffset minimumRetainUntil)
        : IRetentionPolicyResolver
    {
        public ValueTask<AuditRetentionPolicy> GetActiveAsync(
            TenantId tenant,
            CancellationToken cancellationToken = default) =>
            throw new NotSupportedException();

        public ValueTask<RetentionVerdict> ResolveAsync(
            TenantId tenant,
            AuditEventClass eventClass,
            DateTimeOffset recordCreatedAt,
            CancellationToken cancellationToken = default) =>
            ValueTask.FromResult(new RetentionVerdict(
                eventClass,
                minimumRetainUntil,
                minimumRetainUntil.AddDays(30),
                IsJurisdictionFloor: false));
    }

    private sealed class HeldRegistry : ILegalHoldRegistry
    {
        public List<string> Consulted { get; } = [];

        public ValueTask<bool> IsHeldAsync(
            TenantId tenant,
            HeldRef heldRef,
            CancellationToken ct = default)
        {
            Consulted.Add(heldRef.Canonical);
            return ValueTask.FromResult(true);
        }

        public ValueTask<bool> IsSubjectHeldAsync(
            TenantId tenant,
            SubjectId subject,
            CancellationToken ct = default) =>
            ValueTask.FromResult(true);
    }

    private sealed class AllowingObligationAuthority : ITenantForkObligationAuthority
    {
        public ValueTask<TenantForkObligation> ResolveAsync(
            TenantId tenant,
            IReadOnlyList<string> documentIds,
            DateTimeOffset capturedAt,
            CancellationToken ct = default) =>
            ValueTask.FromResult(new TenantForkObligation(
                RetentionClass: "configuration",
                MinimumRetainUntil: capturedAt.AddDays(30),
                IsUnderLegalHold: false));
    }
}

using System.Collections.Concurrent;
using System.Diagnostics;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.Logging;

namespace Harborline.Api.LocalNodeHost.Tests.TestDoubles;

// Store only structural metadata. Never invoke the log formatter or read exception messages,
// request/response bodies, headers, URLs, environment values, or principal/session identifiers.
internal sealed class FailureOnlyHttpDiagnostics : ILoggerProvider
{
    private const int Capacity = 64;
    private readonly ConcurrentQueue<string> _entries = new();
    private readonly long _started = Stopwatch.GetTimestamp();
    private int _sequence;

    public ILogger CreateLogger(string categoryName) => new StructuralLogger(this,
        categoryName.StartsWith("Microsoft.AspNetCore.Server.Kestrel", StringComparison.Ordinal));
    public void Dispose() { }

    public async Task ObserveAsync(HttpContext context, RequestDelegate next)
    {
        var sequence = Interlocked.Increment(ref _sequence);
        Add($"request {sequence} started");
        try
        {
            await next(context);
            Add($"request {sequence} completed status={context.Response.StatusCode}");
        }
        catch (Exception exception)
        {
            Add($"request {sequence} threw type={exception.GetType().FullName}");
            throw;
        }
    }

    public string Snapshot() => string.Join(Environment.NewLine, _entries.ToArray());

    public void WriteStatusFailure(int expected, int actual, Action<string> write)
    {
        if (expected == actual) return;
        write($"HTTP fixture failure: expected={expected}, actual={actual}");
        write(Snapshot());
    }

    private void Add(string entry)
    {
        _entries.Enqueue($"{Stopwatch.GetElapsedTime(_started).TotalMilliseconds:F0}ms {entry}");
        while (_entries.Count > Capacity) _entries.TryDequeue(out _);
    }

    private sealed class StructuralLogger(FailureOnlyHttpDiagnostics owner, bool kestrel) : ILogger
    {
        public IDisposable? BeginScope<TState>(TState state) where TState : notnull => null;
        public bool IsEnabled(LogLevel level) => kestrel && level >= LogLevel.Debug && level < LogLevel.None;
        public void Log<TState>(LogLevel level, EventId id, TState state, Exception? exception,
            Func<TState, Exception?, string> formatter)
        {
            if (IsEnabled(level)) owner.Add($"kestrel level={level} event={id.Id} exceptionType={exception?.GetType().FullName ?? "none"}");
        }
    }
}

using System.Security.Cryptography;
using System.Text;

using NSec.Cryptography;

using Harborline.Api.LocalNodeHost.Data.KeyDistribution;

namespace Harborline.Api.LocalNodeHost.Tests.TestDoubles;

/// <summary>
/// TEST-ONLY, INSECURE-BY-DESIGN <see cref="ITenantDekPairingResolver"/> — derives a recipient wrap key from the
/// PARTY ID alone (a compile-time-constant, party-id-keyed HKDF). It exists ONLY to make the MD-1 arch-fence's
/// false-positive scenario CONCRETE and to prove the <c>DekPairingResolverArchFence</c> structurally excludes it
/// from the shipped assembly. It lives in the TEST assembly and is NEVER registered in production.
/// </summary>
/// <remarks>
/// <para>
/// <b>WHY THIS MUST NEVER SHIP (the #1325 / bug-1312 lesson, applied to DEK pairing).</b> Because the recipient key
/// is a function of the PARTY ID (the root/node secret is deliberately not mixed in), anyone holding this assembly
/// could compute the wrap key for ANY party by claiming that party's id — and a non-participant who LIES about being
/// an admitted party would receive a DEK wrapped to a key it controls. The protection would be an identity self-check,
/// not crypto: the dev-gate, not the roster, would be load-bearing for confidentiality. A leak test GREEN against
/// THIS resolver is a FALSE POSITIVE — it proves a party-id-keyed construction round-trips, NOT that an unadmitted
/// party cannot obtain the DEK.
/// </para>
/// <para>
/// The REAL no-leak guarantee is delivered ONLY by <see cref="RosterBoundTenantDekPairingResolver"/> — the recipient
/// key comes from the SIGNED, genesis-rooted admission (<c>MemberRoster.DmPublicKeyOf</c>), so a forged id resolves a
/// DIFFERENT (or null) key. The MD-1 leak test runs against THAT resolver; this double exists only to be fenced out.
/// </para>
/// </remarks>
public sealed class IdentityDerivableTenantDekPairingResolver : ITenantDekPairingResolver
{
    private static readonly KeyAgreementAlgorithm Kem = KeyAgreementAlgorithm.X25519;

    // INSECURE-BY-DESIGN: the recipient key derives from the party id + a compile-time constant — NO node/root secret.
    // This is exactly the identity-derivable resolver the arch-fence forbids in the shipped assembly.
    private const string InfoPrefix = "sunfish-dek-pairing-testdouble:v1:";
    private static readonly byte[] TestDoubleIkm = "sunfish-dek-pairing-testdouble-ikm"u8.ToArray();

    /// <inheritdoc />
    /// <remarks>Returns a party-id-derivable public key for ANY non-empty party id (no roster check) — the insecure
    /// behaviour the fence exists to keep out of production.</remarks>
    public byte[]? ResolveRecipientWrapKey(string recipientPartyId)
    {
        if (string.IsNullOrWhiteSpace(recipientPartyId))
        {
            return null;
        }

        var priv = new byte[32];
        HKDF.DeriveKey(
            HashAlgorithmName.SHA256,
            ikm: TestDoubleIkm,
            output: priv,
            salt: ReadOnlySpan<byte>.Empty,
            info: Encoding.UTF8.GetBytes(InfoPrefix + recipientPartyId));
        try
        {
            using var key = Key.Import(Kem, priv, KeyBlobFormat.RawPrivateKey, new KeyCreationParameters
            {
                ExportPolicy = KeyExportPolicies.AllowPlaintextExport,
            });
            return key.PublicKey.Export(KeyBlobFormat.RawPublicKey);
        }
        finally
        {
            CryptographicOperations.ZeroMemory(priv);
        }
    }
}

using System.Security.Cryptography;
using System.Text;

using NSec.Cryptography;

namespace Harborline.Api.LocalNodeHost.Data.Comms;

/// <summary>
/// TEST-ONLY <see cref="IParticipantDmKeyResolver"/> — a deterministic, party-id-keyed X25519 keypair source used
/// ONLY to exercise the DM seal/unseal CONSTRUCTION (ECDH+HKDF, AAD, sign-then-encrypt, tamper fail-closed) in the
/// Tier-1 test harness. It lives in the TEST assembly and is NEVER registered in the production composition (the
/// arch-fence <c>ProductionComposition_RegistersFailClosed_NoDmKeyProvider</c> proves prod registers
/// <see cref="NoDmConversationKeyProvider"/> instead). It is NOT a confidentiality primitive.
/// </summary>
/// <remarks>
/// <para>
/// <b>WHY THIS IS NOT A CONFIDENTIALITY PRIMITIVE — and must never ship.</b> This resolver derives EVERY party's
/// DM keypair (private AND public) from a single compile-time-constant IKM keyed ONLY by the party id. The node
/// root seed is deliberately NOT mixed in (it cannot be — two test nodes must compute the SAME peer keypair from a
/// party id alone, with no wire distribution). The consequence, surfaced by the security-engineering deep-review of
/// PR #1325: <b>anyone holding this assembly can derive ANY party's DM PRIVATE key from a party id + the constant.</b>
/// A non-participant who simply <i>claims a participant's party id</i> derives the identical <c>K_dm</c> and
/// decrypts the body. The <c>DerivedDmConversationKeyProvider</c> "leak guard" (the <c>me ∈ {A,B}</c> self-check)
/// is an IDENTITY/routing check, not a cryptographic barrier — it is bypassed by lying about who you are.
/// </para>
/// <para>
/// So a leak test run against THIS resolver proves a property of the CONSTRUCTION (seal/unseal/AAD/tamper round-trip
/// correctly; a non-participant who honestly reports a non-participant id gets <c>null</c>), <b>NOT</b> a
/// confidentiality GUARANTEE (a non-participant CANNOT obtain the key even when lying about their id). That real
/// no-leak guarantee is delivered ONLY by the C5 roster-bound resolver — each node generates its DM private key
/// from its OWN root seed and never exposes a party-id-derivable private key — and the C5 leak test (a forged party
/// id yields a DIFFERENT, useless key) lands with that resolver.
/// </para>
/// <para>
/// <b>What carries forward to C5.</b> The KEY CONSTRUCTION (<see cref="DerivedDmConversationKeyProvider"/>) is
/// sound and unchanged across the swap: the X25519 ECDH + HKDF, the AAD context binding, the sign-then-encrypt
/// order, the contributory-check. Only the resolver — WHERE the peer public key comes from and how the private key
/// is bound — changes. This test double exists so that sound construction can be regression-tested now; it is
/// structurally isolated in the test assembly so it can never become the production provider.
/// </para>
/// </remarks>
public sealed class SeedDerivedParticipantDmKeyResolver : IParticipantDmKeyResolver
{
    private static readonly KeyAgreementAlgorithm Kem = KeyAgreementAlgorithm.X25519;

    // TEST-DOUBLE derivation (INSECURE BY DESIGN — must never ship; see the class remarks): BOTH the active
    // member's private key and ANY party's public key derive from the SAME compile-time-constant, party-id-keyed
    // HKDF. This is the self-consistency the harness needs (the public key node-B computes for party-A off A's
    // party id MUST match the private key node-A holds off the SAME party id, else the ECDH disagrees), and it is
    // EXACTLY why this is not a confidentiality primitive: the private key is recoverable by anyone with this
    // assembly + a party id (the root seed is deliberately NOT mixed in). The C5 ROSTER-BOUND resolver replaces
    // this: each node generates its OWN DM keypair from its OWN root seed + publishes the PUBLIC key on the
    // enrollment wire, so a private key is node-secret and a forged party id yields a useless key.
    // DerivedDmConversationKeyProvider's ECDH is unchanged across the swap.
    private const string PartyKeypairInfoPrefix = "sunfish-dm-subkey-testdouble:v1:";
    private static readonly byte[] TestDoubleIkm = "sunfish-dm-testdouble-ikm"u8.ToArray();

    private readonly byte[] _activeDmPrivateKey;

    /// <summary>The active (local) member's party id.</summary>
    public string ActiveMemberPartyId { get; }

    /// <inheritdoc />
    public ReadOnlySpan<byte> ActiveMemberDmPrivateKey => _activeDmPrivateKey;

    /// <summary>
    /// Construct the test-double resolver for the active member. (The active member's DM private key derives from the
    /// SAME party-id-keyed HKDF a peer uses to compute its public key — so the ECDH is self-consistent across test
    /// nodes without wire distribution. The <paramref name="rootSeed"/> is accepted for signature-compatibility with
    /// the C5 roster-bound resolver — where the private key folds in the root seed — but is NOT mixed in here,
    /// because mixing it would break the cross-node public/private agreement the harness needs. This is the exact
    /// reason this double is insecure and must never ship.)
    /// </summary>
    /// <param name="rootSeed">The node's 32-byte root seed (signature-compatible with C5; NOT used here — validated non-empty only).</param>
    /// <param name="activeMemberPartyId">The active member's party id.</param>
    public SeedDerivedParticipantDmKeyResolver(ReadOnlySpan<byte> rootSeed, string activeMemberPartyId)
    {
        if (rootSeed.Length == 0) throw new ArgumentException("Root seed must be non-empty.", nameof(rootSeed));
        ArgumentException.ThrowIfNullOrWhiteSpace(activeMemberPartyId);
        ActiveMemberPartyId = activeMemberPartyId;

        // The active member's DM private key — the SAME deterministic party-id-keyed derivation a peer uses to
        // compute this member's PUBLIC key (so ECDH(myPriv, peerPub) == ECDH(peerPriv, myPub) across nodes).
        _activeDmPrivateKey = DerivePartyPrivateKey(activeMemberPartyId);
    }

    /// <inheritdoc />
    /// <remarks>
    /// TEST DOUBLE: a party's DM public key derives deterministically from its party id (compile-time-constant HKDF),
    /// so every test node computes the SAME keypair for the same party with no wire distribution — letting the
    /// derived-ECDH construction round-trip now. C5 replaces this with the roster-bound public key each node
    /// published at enrollment. (Because the matching PRIVATE key is equally derivable from the party id, this is a
    /// construction harness, not a secrecy boundary.)
    /// </remarks>
    public byte[]? TryResolveDmPublicKey(string partyId)
    {
        if (string.IsNullOrWhiteSpace(partyId)) return null;
        var priv = DerivePartyPrivateKey(partyId);
        try
        {
            return PublicKeyFromPrivate(priv);
        }
        finally
        {
            CryptographicOperations.ZeroMemory(priv);
        }
    }

    /// <summary>The party-id-keyed deterministic X25519 private key (the test-double keypair source — insecure).</summary>
    private static byte[] DerivePartyPrivateKey(string partyId) =>
        DeriveX25519PrivateKey(TestDoubleIkm, PartyKeypairInfoPrefix + partyId);

    private static byte[] DeriveX25519PrivateKey(ReadOnlySpan<byte> ikm, string info)
    {
        var output = new byte[32];
        HKDF.DeriveKey(
            HashAlgorithmName.SHA256,
            ikm: ikm,
            output: output,
            salt: ReadOnlySpan<byte>.Empty,
            info: Encoding.UTF8.GetBytes(info));
        return output; // NSec applies RFC 7748 clamping on Import — do NOT pre-clamp.
    }

    private static byte[] PublicKeyFromPrivate(ReadOnlySpan<byte> privateKey)
    {
        using var key = Key.Import(Kem, privateKey, KeyBlobFormat.RawPrivateKey, new KeyCreationParameters
        {
            ExportPolicy = KeyExportPolicies.AllowPlaintextExport,
        });
        return key.PublicKey.Export(KeyBlobFormat.RawPublicKey);
    }
}

